def _cadence_domain_owner(domain):
    """The agent slug owning `domain`'s crew lane, or None. See the note above
    _CADENCE_DOMAINS_WITH_OWNER."""
    if domain in _CADENCE_DOMAINS_WITH_OWNER:
        return _health_agent()
    return None


