def _health_agent_crew(conn=None):
    """The crew-level health-domain OVERRIDE from the shared DB's config table,
    or None. Never raises and never exits: a missing DB, a missing table or a
    malformed value all mean "not set" so the caller falls through. Uses `conn`
    when given (same transaction, no second lock)."""
    own = None
    try:
        if conn is None:
            if not os.path.isfile(DB_PATH):
                return None
            own = sqlite3.connect(DB_PATH, timeout=5)
            conn = own
        row = conn.execute("SELECT value FROM config WHERE key=? LIMIT 1;",
                           (HEALTH_DOMAIN_AGENT_KEY,)).fetchone()
    except sqlite3.Error:
        return None
    finally:
        if own is not None:
            own.close()
    val = (row[0] if row else None) or ""
    val = str(val).strip()
    return val if _AGENT_SLUG_RE.match(val) else None


def _instance_conf_read(root):
    """KEY -> VALUE from <root>/.instance.conf. First line per key wins (the
    framework's _conf_get convention); comments and blank lines skipped. {} on
    any read error -- never raises."""
    out = {}
    try:
        with open(os.path.join(root, ".instance.conf"), encoding="utf-8",
                  errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = k.strip()
                if k and k not in out:
                    out[k] = v.strip().strip('"').strip("'")
    except (OSError, ValueError):
        return {}
    return out


def _health_pack_installed():
    """True when a member of this kit's crew (solo: this instance) lists
    pack_health in DOGANY_PACKS -- the same read _health_agent_derive does."""
    _reg, roots = _health_crew_members()
    for root in roots:
        packs = _instance_conf_read(root).get("DOGANY_PACKS", "")
        if any(p.strip().split("@", 1)[0] == HEALTH_DOMAIN_PACK
               for p in packs.split(",") if p.strip()):
            return True
    return False


def _health_crew_members():
    """(registry, [instance roots]). The kit already knows its crew through its
    DB: a crew member's database/kit_life.db links to
    <crews>/<kit>/kit_life.db and crew.conf sits beside it, one member=<root>
    line per member. A DB that is not in a crew dir is a solo instance whose
    only member is this instance (the parent of the database dir, the same root
    routine_roller reads .instance.conf from). Never raises."""
    try:
        conf = os.path.join(os.path.dirname(os.path.realpath(DB_PATH)),
                            "crew.conf")
        if os.path.isfile(conf):
            roots = []
            with open(conf, encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if line.startswith("member="):
                        r = line[len("member="):].strip()
                        if r and r not in roots:
                            roots.append(r)
            return conf, roots
    except (OSError, ValueError):
        return "unreadable", []
    root = _kit_root()
    return "solo:" + root, [root]


def _health_agent_derive(roots):
    """(slug, fact) or (None, why-not). Pure over the members' .instance.conf.
    Rule (owner ruling 2026-09-24): exactly one member carries a pack_health@
    entry in DOGANY_PACKS -> that member; else exactly one member is
    DOGANY_AGENT_CLASS=main (missing class = main, the framework convention:
    mint writes 'domain' only for domain agents) -> that member; else none."""
    health, main = [], []
    for root in roots:
        conf = _instance_conf_read(root)
        name = conf.get("DOGANY_AGENT_NAME", "").strip().lower()
        if not _AGENT_SLUG_RE.match(name):
            continue
        packs = [p.strip() for p in conf.get("DOGANY_PACKS", "").split(",")]
        if any(p.split("@", 1)[0] == HEALTH_DOMAIN_PACK for p in packs if p):
            if name not in health:
                health.append(name)
        klass = (conf.get("DOGANY_AGENT_CLASS", "") or "main").strip().lower()
        if klass == "main" and name not in main:
            main.append(name)
    notes = []
    if len(health) == 1:
        return health[0], "%s member %s" % (HEALTH_DOMAIN_PACK, health[0])
    if health:
        notes.append("%s ambiguous (%s)" % (HEALTH_DOMAIN_PACK,
                                             ",".join(health)))
    else:
        notes.append("no %s member" % HEALTH_DOMAIN_PACK)
    if len(main) == 1:
        notes.append("sole main member %s" % main[0])
        return main[0], "; ".join(notes)
    notes.append("main ambiguous (%s)" % ",".join(main) if main
                 else "no main member")
    return None, "; ".join(notes)


def _health_agent_derived():
    """(slug, fact) or (None, why-not) from machine facts; read-only, cheap,
    never raises. Cached per process per registry (a process never outlives a
    mint, and a stale answer here only delays a handover to the next write)."""
    try:
        registry, roots = _health_crew_members()
        hit = _HEALTH_DERIVED_CACHE.get(registry)
        if hit is None:
            hit = _health_agent_derive(roots)
            _HEALTH_DERIVED_CACHE[registry] = hit
        return hit
    except Exception as exc:   # a fact we cannot read decides nothing
        return None, "derive failed (%s)" % type(exc).__name__


def _health_agent_resolve_full(conn=None):
    """(slug, source, fact). source = 'env' | 'crew' | 'derived' | 'default';
    fact = the machine fact that won (derived) or why derivation fell through
    (default), '' otherwise."""
    env = os.environ.get(HEALTH_DOMAIN_AGENT_ENV)
    if env and env.strip():
        return env.strip(), "env", ""
    crew = _health_agent_crew(conn)
    if crew:
        return crew, "crew", ""
    slug, fact = _health_agent_derived()
    if slug:
        return slug, "derived", fact
    return _HEALTH_DOMAIN_AGENT_DEFAULT, "default", fact


def _health_agent_resolve(conn=None):
    """(slug, source) where source is 'env' | 'crew' | 'derived' | 'default'."""
    return _health_agent_resolve_full(conn)[:2]


def _health_agent(conn=None):
    """The slug a HEALTH-DOMAIN row carries (meal / workout / metric / health
    routine_def), for READ paths. Write paths use _health_agent_write. See
    HEALTH_DOMAIN_AGENT_ENV above."""
    return _health_agent_resolve(conn)[0]


def _health_owner_recorded(conn):
    """The last crew-wide owner a health write recorded, '' when never recorded,
    or None when the config table cannot be read (no handover then)."""
    try:
        row = conn.execute("SELECT value FROM config WHERE key=? LIMIT 1;",
                           (HEALTH_DOMAIN_OWNER_RECORD_KEY,)).fetchone()
    except sqlite3.Error:
        return None
    return str((row[0] if row else "") or "").strip()


def _health_domain_handover(conn, new):
    """Move the health domain to `new` on `conn`, INSIDE the caller's
    transaction (the caller commits; a crash before that commit leaves the old
    state whole). No-op when `new` is already the recorded owner. On the FIRST
    record (nothing recorded yet) the rows moved belong to the retired health agent.
    Returns {label: rows relabeled} or None for a no-op."""
    old = _health_owner_recorded(conn)
    if old is None or old == new:
        return None
    old = old or _HEALTH_DOMAIN_AGENT_RETIRED
    moved = {}
    if old != new:
        for label, table, sql in _HEALTH_DOMAIN_RELABEL:
            if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' "
                            "AND name=?;", (table,)).fetchone():
                moved[label] = conn.execute(sql, (new, old)).rowcount
    conn.execute(
        "INSERT INTO config (key, value) VALUES (?, ?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value, "
        "updated_at=datetime('now','localtime');",
        (HEALTH_DOMAIN_OWNER_RECORD_KEY, new))
    return moved


def _health_agent_write(conn):
    """The owner to stamp on a health-domain row about to be written on `conn`,
    with the handover folded into the SAME transaction: call it before the
    write's commit, never after. Only crew-wide sources (crew override,
    derived) move history -- an env override is one process's business and
    the default means "no fact decides"; neither may relabel the crew's rows."""
    slug, source, _fact = _health_agent_resolve_full(conn)
    if source in ("crew", "derived"):
        _health_domain_handover(conn, slug)
    return slug


# InBody segmental keys (health-log vocabulary): lean mass per segment
# and the sheet's own "% of standard" for that segment. Declared here so the
# write echoes what the sheet printed (88.5, not 89); body-segment reads the
# _pct key back as standard_pct.
_SEGMENT_KEYS = ("arm_l", "arm_r", "trunk", "leg_l", "leg_r")
# The raw panel (health-log vocabulary) on the sheet's printed grid too: an
# integer echo of bmi 23.7 / whr 0.84 read as a lost decimal and drew a
# "checking the stored decimals" progress message on capture turns.
_METRIC_ECHO_DECIMALS = dict(
    [("lean_%s_kg" % sg, 1) for sg in _SEGMENT_KEYS]
    + [("lean_%s_pct" % sg, 1) for sg in _SEGMENT_KEYS]
    + [("fat_%s_kg" % sg, 1) for sg in _SEGMENT_KEYS]
    + [("lean_mass_kg", 1), ("slm_kg", 1), ("protein_kg", 1),
       ("mineral_kg", 1), ("tbw_l", 1), ("bmi", 1), ("smi", 1),
       ("whr", 2)])


def _metric_echo(metric, value):
    """log-metric's echo of the value it just STORED.  A guided metric
    declares its display resolution in _CADENCE_GUIDED (a few InBody keys in
    _METRIC_ECHO_DECIMALS); render the stored value on that grid
    (half-away-from-zero, the _f0 idiom).  The grid is a floor: a value
    stored with finer digits (a 4.12 kg mineral on a 0.1 grid) echoes them,
    never rounded away.  A metric with no declared
    resolution keeps the legacy %.0f echo byte-identical -- fail-closed to
    the old contract, never an invented precision."""
    guided = _CADENCE_GUIDED.get(metric)
    if guided is None and metric in _METRIC_ECHO_DECIMALS:
        guided = (None, None, None, None, _METRIC_ECHO_DECIMALS[metric])
    if guided is None:
        return _f0(_num(value))
    dec = max(guided[4],
              -Decimal(str(_num(value))).normalize().as_tuple().exponent)
    q = Decimal(str(_num(value))).quantize(
        Decimal(1).scaleb(-dec), rounding=ROUND_HALF_UP)
    return f"{q}"


def _cadence_declare_fixed(conn, metrics):
    """Module-declared FIXED cadence, written at the module's own touchpoint.

    INSERT OR IGNORE is the whole discipline: an existing row -- above all a
    row the USER declared -- is never trampled.  FK note: OR IGNORE does not
    swallow a foreign-key violation, so tokens are filtered to ones
    metric_def actually holds (the diet cargo is seeded in schema.sql, but a
    stray token must fail closed here, not crash the meal write)."""
    for tok in metrics:
        if tok not in _CADENCE_FIXED:
            continue
        if conn.execute("SELECT 1 FROM metric_def WHERE token=?",
                        (tok,)).fetchone() is None:
            continue
        conn.execute(
            "INSERT OR IGNORE INTO metric_freshness"
            "(metric, stale_after_hours, declared_by, note) VALUES (?,?,?,?)",
            (tok, _CADENCE_FIXED_HOURS, 'module',
             'structurally daily: the recording act itself is daily (diet)'))


def _meal_kcal(vals):
    """구 meals.kcal 의 GENERATED 정의를 그대로 계산한다 -- 순탄수 + 알코올.
    이 식은 schema.sql 의 생성 컬럼과 ** 반드시 같아야 한다 ** ."""
    g = lambda k: float(vals.get(k) or 0)
    return round(g('protein') * 4 + g('fat') * 9
                 + (g('carb') - g('fiber')) * 4 + g('alcohol') * 7, 2)


def _meal_is_real(slot, kcal):
    """Only energy-bearing food is an eating occasion; supplements are separate."""
    return (float(kcal or 0) > 0 and
            str(slot or '').strip().lower() not in
            ('보충제', 'supplement', 'supplements'))


def _meal_log_slot(slot, name, kcal):
    if _meal_is_real(slot, kcal):
        return meal_slots.label(slot)
    supplement = (str(slot or '').strip().lower() in
                  ('보충제', 'supplement', 'supplements') or
                  any(word in str(name or '').lower()
                      for word in ('크레아틴', 'creatine')))
    return (_i18n('meal.card.supplement', 'Supplement') if supplement else
            _i18n('meal.card.nonmeal', 'Record'))


def _meal_observed_instant(date):
    """measure.observed_at for a meal row: the meal day's LOCAL midnight as a
    canonical UTC-Z instant, resolved through the instance's DECLARED offset
    (AGENT_TZ_OFFSET_HOURS in config/agent.conf, read via agent_conf -- the
    same reader every other kit knob uses, env override included).  The
    judgment layer (037/038) reads observed_at as an INSTANT; writing the
    bare local day made the read side floor it to a UTC day start, which
    between 00:00 and 09:00 local on a UTC+9 estate is a FUTURE instant --
    the 9h/day fail-open 038 closes.  Resolving the offset at WRITE time
    removes the ambiguity for every new row (2026-09-08 06:48 owner rule:
    resolve from the configured value; no fourth clock, no hardcoded +9).
    Fail-CLOSED when the offset is UNDECLARED, absurd (outside -12..+14, a
    typo'd knob) or the date is not a bare YYYY-MM-DD: return the date-only
    grade byte-identical to pre-2.1.2 (agent_conf's zero-delta contract).
    NEVER silently assume 0 -- a 0-offset instant fabricated for a KST day
    is the exact fail-open being closed; the 038 read side treats the honest
    date-only grade's ambiguity as stale, never fresh."""
    off = agent_conf.conf_int("AGENT_TZ_OFFSET_HOURS", None)
    if off is None or not -12 <= off <= 14:
        return date
    try:
        day = datetime.datetime.strptime(str(date), "%Y-%m-%d")
    except (TypeError, ValueError):
        return date
    return (day - datetime.timedelta(hours=off)).strftime(
        "%Y-%m-%dT%H:%M:%SZ")


def _meal_write_v32(conn, date, meal, name, vals, owning_agent=None,
                    notion_id=None, block_id=None, experience_id=None):
    """meals 한 건을 v3.2 축에 쓴다. block_id 가 주어지면 그 블록을 갱신한다.
    반환: block.id"""
    # An unrelated correction may preserve an unknown historical slot, but
    # no write path may introduce a new untyped value.
    prior = (conn.execute("SELECT value FROM block_attr WHERE block_id=? AND attr_token='meal_slot'",
                          (block_id,)).fetchone() if block_id is not None else None)
    unchanged = block_id is not None and meal_slots.stored(meal or '') == meal_slots.stored(prior[0] if prior else '')
    meal = meal_slots.stored(meal) if unchanged else meal_slots.canonical(meal)
    now = now_utc()
    if block_id is None:
        cur = conn.execute(
            "INSERT INTO block(ulid, source_module, title, date, kind_token, "
            "settled_at, settled_outcome, settled_by, settled_verdict, created_at) "
            "VALUES (?,?,?,?,?,?,?,?,?,?)",
            (new_ulid(), 'diet', name, date, 'record',
             now, 'done', 'meal-record', 'machine', now))
        block_id = cur.lastrowid
    else:
        conn.execute("UPDATE block SET title=?, date=? WHERE id=?",
                     (name, date, block_id))
        # cut 3: a pointing record's ts is a cached copy of this block's
        # event time -- refresh it in the SAME tx so a date fix (meal-upd)
        # never leaves a drifted pointer.
        conn.execute(
            "UPDATE record SET ts=? WHERE source_table='block' AND source_id=?;",
            (date, block_id))
        conn.execute("DELETE FROM measure WHERE block_id=?", (block_id,))
        conn.execute("DELETE FROM block_delta WHERE block_id=?", (block_id,))
    for tok, unit in (('meal_slot', meal), ('notion_id', notion_id),
                      ('owning_agent', owning_agent)):
        if unit is not None and unit != '':
            conn.execute(
                "INSERT OR REPLACE INTO block_attr(block_id, attr_token, value, source) "
                "VALUES (?,?,?,'user')", (block_id, tok, str(unit)))
    # 038: the judgment layer reads observed_at as an INSTANT -- resolve the
    # owner's local day through the declared offset (fail-closed to the
    # date-only grade when undeclared; see _meal_observed_instant).
    observed = _meal_observed_instant(date)
    if vals.get('caffeine') is not None and vals.get('caffeine_origin') == 'estimated':
        # Reference provenance is module vocabulary, registered when first used.
        # Older DBs carry only measured/declared/computed/default/unknown.
        conn.execute("INSERT OR IGNORE INTO provenance(token,is_estimate,recomputable,writable,origin) "
                     "VALUES('estimated',1,0,1,'module')")
    for m, u in _MEAL_MEASURES:
        v = vals.get(m)
        if v is None:
            continue
        conn.execute(
            "INSERT INTO measure(metric, value, unit, block_id, observed_at, "
            "source, value_origin) VALUES (?,?,?,?,?,?,?)",
            (m, float(v), u, block_id, observed,
             (vals.get('caffeine_source') or 'module:diet') if m == 'caffeine' else 'module:diet',
             ('estimated' if vals.get('caffeine_origin') == 'estimated' else 'measured')
             if m == 'caffeine' else 'measured'))
    # kcal 0.0 은 ** 측정된 0 ** 이다(사이리움/크레아틴/제로콜라). 없음이 아니다 --
    # truthiness 로 거르면 측정된 0 이 부재로 바뀐다(이관기 주석과 같은 판정).
    kcal = _meal_kcal(vals)
    if kcal is not None:
        conn.execute(
            "INSERT INTO block_delta(block_id, resource, amount, unit, component, "
            "value_origin) VALUES (?,?,?,?,?,?)",
            (block_id, 'nutrition', kcal, 'kcal', 'intake', 'measured'))
        # 2.15.0 -- the SAME value, also in measure, for the same reason
        # 2.13.0 gave the workouts lane: measure is the home the JUDGEMENT
        # layer reads (037 S1), and block_delta is the resource-flow axis
        # (039).  Without this row the diet domain could never be judged --
        # v_criterion_verdict saw no kcal at all, which is why the calorie
        # criterion had nothing to be judged against even once its period
        # was corrected.  block_delta stays the flow store of record and
        # every existing reader keeps reading it; this is a SHADOW written
        # in the SAME tx, and the UPDATE path above already deleted the
        # block's measure rows, so an edit refreshes it with no drift.
        # value_origin 'computed', not 'measured': kcal is DERIVED from the
        # macro rows by _meal_kcal (provenance.recomputable=1 says exactly
        # that), while the macros themselves are what was measured.
        # NO metric_freshness row is declared for kcal_intake (unlike the
        # macros below): since 045 the accrued PERIOD arm does not read
        # cadence at all, so a row here would govern nothing -- the dead-knob
        # shape 044 refused for week_start.  A future POINT criterion on
        # kcal_intake would stay silent until a cadence is declared, which
        # is the fail-CLOSED answer, not a defect.
        _criterion_metric_ensure(conn, 'kcal_intake')
        conn.execute(
            "INSERT INTO measure(metric, value, unit, basis, block_id, "
            "observed_at, source, value_origin) "
            "VALUES ('kcal_intake', ?, 'kcal', 'actual', ?, ?, "
            "'module:diet', 'computed')",
            (float(kcal), block_id, observed))
    # Fixed-class cadence: diet is structurally daily, so the module declares
    # the interval HERE, at its own write, silently -- never asked, never
    # seeded by a migration (cut-1 freshness hooks; see _CADENCE_FIXED).
    _cadence_declare_fixed(conn, [m for m, _u in _MEAL_MEASURES
                                  if vals.get(m) is not None])
    if not name.endswith(PLANNED_SUFFIX):
        if experience_id is None:
            try:
                candidates = _meal_containment_events(conn, block_id, date, meal)
                candidates = {eid: value for eid, value in candidates.items()
                              if _record_exclusion_for_block(conn, eid, block_id) is None}
            except Exception:
                # Containment is optional; its existing post-commit safe path
                # reports failures. The meal and its own capture still land.
                candidates = {}
            if len(candidates) == 1:
                experience_id = next(iter(candidates))
        clock_row = conn.execute("SELECT value FROM block_attr WHERE block_id=? "
                                 "AND attr_token='meal_occurred_at'", (block_id,)).fetchone()
        clock = None
        if clock_row:
            import meal_time
            local = _satiety_instant(clock_row[0]).astimezone(meal_time.zone(sys.modules[__name__]))
            local = datetime.datetime.combine(datetime.date.fromisoformat(date), local.timetz())
            clock = local.isoformat()
            stamp = meal_time.iso(local)
            conn.execute("UPDATE block_attr SET value=? WHERE block_id=? AND attr_token='meal_occurred_at'", (stamp, block_id))
            conn.execute('UPDATE measure SET observed_at=? WHERE block_id=?', (stamp, block_id))
        experience_ensure(conn, name, occurred_on=date, occurred_at=clock,
                          block_id=block_id, event_id=experience_id)
    return block_id


PORTION_BASES = ('exact', 'package', 'count', 'part', 'volume', 'standard', 'estimate')
PORTION_WEIGHTS = dict(exact=1.0, package=1.0, part=0.8, count=0.65,
                       volume=0.65, standard=0.2, estimate=0.0)


def _portion_basis_check(basis, evidence, source, grams, count, fraction, volume_ml):
    """Validate the typed amount basis the AGENT chose from the owner's words.

    Code never reads the owner's words: it only checks that the declared basis
    carries the numbers that basis needs, and keeps the legacy
    meal_portion_source in step (exact->stated, package->package,
    estimate->estimate) so older readers keep working.
    """
    if basis is None:
        if any(v is not None for v in (evidence, count, fraction, volume_ml)):
            raise ValueError('portion evidence/count/fraction/volume need --portion-basis')
        return None, source, None, None, None
    if basis not in PORTION_BASES:
        raise ValueError('portion basis must be one of ' + '|'.join(PORTION_BASES))
    legacy = {'exact': 'stated', 'package': 'package'}.get(basis, 'estimate')
    if source is not None and source != legacy:
        raise ValueError('portion source %s conflicts with portion basis %s' % (source, basis))
    ev = (evidence or '').strip()
    if basis not in ('estimate', 'standard') and not ev:
        raise ValueError('portion basis %s needs --portion-evidence (the owner words verbatim)' % basis)
    import math
    def pos(value, what):
        number = _opt_num(value)
        if number is None or not math.isfinite(number) or number <= 0:
            raise ValueError(what + ' must be positive')
        return number
    if basis in ('exact', 'package'):
        pos(grams, 'portion grams')
    if basis == 'count':
        count = pos(count, 'count')
    elif count is not None:
        raise ValueError('--count only goes with --portion-basis count')
    if basis == 'part':
        fraction = pos(fraction, 'fraction')
        if fraction > 1:
            raise ValueError('fraction must be in (0,1]')
    elif fraction is not None:
        raise ValueError('--fraction only goes with --portion-basis part')
    if basis == 'volume':
        volume_ml = pos(volume_ml, 'volume ml')
    elif volume_ml is not None:
        raise ValueError('--volume-ml only goes with --portion-basis volume')
    return basis, source or legacy, count, fraction, volume_ml


def _portion_options(argv):
    options = {}
    for flag, field in (('basis', 'basis'), ('evidence', 'evidence'),
                        ('count', 'count'), ('fraction', 'fraction'),
                        ('volume-ml', 'volume_ml'), ('source', 'source')):
        option = '--portion-' + flag if flag in ('basis', 'evidence', 'source') else '--' + flag
        argv, options['portion_' + field] = _pop_opt(argv, option)
    return argv, options


def _portion_save(conn, bid, basis, evidence, source, count, fraction, volume_ml):
    # A correction replaces the entire declaration, including obsolete numbers.
    tokens = ('basis', 'evidence', 'source', 'count', 'fraction', 'volume_ml', 'weight')
    conn.executemany('DELETE FROM block_attr WHERE block_id=? AND attr_token=?',
                     [(bid, 'meal_portion_' + token) for token in tokens])
    values = (basis, evidence, source, count, fraction, volume_ml, PORTION_WEIGHTS.get(basis))
    conn.executemany("INSERT INTO block_attr VALUES(?,?,?,'module:diet')",
                     [(bid, 'meal_portion_' + token, str(value))
                      for token, value in zip(tokens, values) if value is not None])


def meal_add(date, meal, name, carb=0, protein=0, fat=0,
             fiber=0, sugar=0, alt_sugar=0, grams=None, alcohol=0, conn=None,
             allow_unlooked=False, allow_unsated=False, experience_id=None,
             shake=False, mix_water_ml=None, mix_liquid=None, mix_reference=None,
             mix_water_default_ml=None, mix_water_source=None,
             _confirmation_key=None, planned_at=None, portion_source=None,
             portion_basis=None, portion_evidence=None, portion_count=None,
             portion_fraction=None, portion_volume_ml=None):
    """식단 한 건 기록(area=식습관 자동). kcal은 DB generated. 새 행 id 반환.

    alcohol=순수 알코올 그램(선택, 7kcal/g). 술류는 volume_ml×ABV×0.789로 구해 넘긴다.
    미지정이면 0. 탄수는 실제 탄수 그램 그대로(알코올을 탄수에 접지 말 것).

    043 (DGN-928): `name` 에 대해 조회 단계가 실제로 돈 영수증
    (meal_lookup_receipt) 이 없으면 아무것도 쓰지 않고 LookupSkippedError 를
    올린다 -- 순서를 산문이 아니라 실행 지점에 건다. allow_unlooked=True 는
    그 전제를 명시적으로 면제하고(호출부 무변경 보장), 영수증 레인 자체가
    고장 나면(표 없음/DB 오류) 판정을 못 하므로 fail-OPEN 으로 그대로 기록한다
    -- the owner must never be left unable to log a meal.

    Estimated meals record immediately. Their eating occasion stays pending
    calibration until the owner answers the post-card satiety question.
    allow_unsated is retained for SDK compatibility; it cannot block a write.
    portion_source grades the consumed mass independently of the nutrients:
    stated/package are fixed; estimate is a photo or vague-amount guess.
    """
    meal = meal_slots.canonical(meal)
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if portion_source not in (None, 'stated', 'package', 'estimate'):
            raise ValueError('portion source must be stated, package or estimate')
        portion_basis, portion_source, portion_count, portion_fraction, portion_volume_ml = \
            _portion_basis_check(portion_basis, portion_evidence, portion_source, grams,
                                 portion_count, portion_fraction, portion_volume_ml)
        if portion_source is not None and (_opt_num(grams) is None or _opt_num(grams) <= 0):
            raise ValueError('portion source requires positive grams')
        if planned_at is not None:
            if not name.endswith(PLANNED_SUFFIX):
                raise ValueError('planned_at requires a planned meal')
            planned_at = _planned_meal_clock(planned_at)
        if not allow_unlooked and lookup_receipt_check(conn, name) is False:
            # BEFORE the write: nothing partial survives a refusal.
            raise LookupSkippedError(name)
        # Serialize the shared answer check, pending request and food write.
        if not conn.in_transaction:
            conn.execute('BEGIN IMMEDIATE')
        import meal_mixture
        mixture = meal_mixture.prepare(
            sys.modules[__name__], conn, name, _opt_num(grams), shake,
            mix_water_ml, mix_liquid, mix_reference, mix_water_default_ml, mix_water_source)
        # v3.2: meals 표가 아니라 block+measure+delta 로 나간다. area_id 는
        # v3.2 에 자리가 없다(UNMAPPED O-7) -- 도메인 귀속은 block_domain 이 맡는다.
        vals = {'carb': _num(carb), 'protein': _num(protein), 'fat': _num(fat),
                'fiber': _num(fiber), 'sugar': _num(sugar),
                'alt_sugar': _num(alt_sugar), 'alcohol': _num(alcohol),
                'portion_grams': _opt_num(grams)}
        vals.update(_caffeine_for_meal(sys.modules[__name__], conn, name, grams))
        # meal = health domain. The owner is the DOMAIN's owner, always --
        # each agent is just a capture surface, and the capturer is provenance,
        # not owner (owner directive 2026-08-20). See _health_agent().
        bid = _meal_write_v32(conn, date, _txt(meal), name, vals,
                              owning_agent=_health_agent_write(conn),
                              experience_id=experience_id)
        if planned_at is not None:
            conn.execute("INSERT INTO block_attr VALUES(?,'meal_planned_at',?,'user')",
                         (bid, planned_at))
        meal_mixture.save(conn, bid, mixture)
        _portion_save(conn, bid, portion_basis, portion_evidence, portion_source,
                      portion_count, portion_fraction, portion_volume_ml)
        if (not name.endswith(PLANNED_SUFFIX) and
                _meal_is_real(meal, _meal_kcal(vals)) and
                lookup_receipt_grade(conn, name) == 'estimate'):
            data = _satiety_state_load(conn=conn)
            key, ids = _satiety_context(conn, data, date, _txt(meal))
            entry = data.setdefault('meal_times', {}).setdefault(key, {})
            entry['occasion_ids'] = ids
            if entry.get('fullness') not in SATIETY_LEVELS:
                entry['calib'] = {'status': 'pending'}
            _satiety_state_save(data, conn=conn, commit=False)
        if _confirmation_key is not None:
            pending = json.loads(_config_stored(conn, _confirmation_key))
            pending.update(state='confirmed', meal_id=bid)
            conn.execute('UPDATE config SET value=? WHERE key=?',
                         (json.dumps(pending, ensure_ascii=False), _confirmation_key))
        conn.commit()
        # cut 3 lock 3: capture is COMMITTED above -- containment runs after,
        # additive and non-blocking (a raise in there never breaks the write).
        _meal_autolink_safe(conn, bid)
        return bid
    except Exception:
        conn.rollback()
        raise
    finally:
        if own:
            conn.close()


def meal_get(conn, mid):
    return conn.execute("SELECT * FROM " + MEALS_V32 + " WHERE id=?;", (mid,)).fetchone()


def meal_find(date, conn=None):
    """그날 식단 목록 (id, name, meal, kcal) 튜플 리스트."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return conn.execute(
            "SELECT id, name, COALESCE(meal,''), kcal "
            "FROM " + MEALS_V32 + " WHERE date=? ORDER BY id;", (date,)).fetchall()
    finally:
        if own:
            conn.close()


def meal_day(date, conn=None):
    """그날 식단 (사람용 라인 리스트)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, meal, name, kcal, protein, carb, fat "
            "FROM " + MEALS_V32 + " WHERE date=? ORDER BY id;", (date,)).fetchall()
        out = []
        for mid, meal, name, kcal, protein, carb, fat in rows:
            out.append(
                f"[{mid}] {meal_slots.label(meal)}/{name}"
                f"  ({_f0(kcal)}kcal 단{_f0(protein)}g 탄{_f0(carb)}g 지{_f0(fat)}g)")
        return out
    finally:
        if own:
            conn.close()


def _block_record_del(conn, block_id):
    """026 polymorphic-integrity guard #1 for the 'block' source token: when a
    block row dies, its pointing record row dies in the SAME tx -- no FK backs
    the polymorphic pointer, so a survivor would dangle and a later rowid
    reuse would silently re-bind evidence. record_event links cascade off the
    record row (junction-only, foreign_keys=ON)."""
    conn.execute(
        "DELETE FROM record WHERE source_table='block' AND source_id=?;",
        (int(block_id),))


def meal_del(mid, conn=None):
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if not conn.in_transaction:
            conn.execute('BEGIN IMMEDIATE')
        # v3.2: block 하나를 지우면 measure/block_delta/block_attr 이
        # ON DELETE CASCADE 로 따라간다 -- 조각을 손으로 지우지 않는다.
        cur = conn.execute(
            "DELETE FROM block WHERE id=? AND settled_by='meal-record';",
            (int(mid),))
        if cur.rowcount:
            _block_record_del(conn, mid)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        if own:
            conn.close()


# 부분 업데이트 허용 컬럼 → 값 변환기. kcal은 generated라 제외.
_MEAL_UPD_COLS = {
    'date': _txt, 'meal': _txt, 'name': _txt,
    'carb': _num, 'protein': _num, 'fat': _num, 'fiber': _num,
    'sugar': _num, 'alt_sugar': _num, 'alcohol': _num,
    'grams': _opt_num, 'mix_water_ml': _opt_num,
}


def meal_upd(mid, fields, conn=None, commit=True, portion_basis=None,
             portion_evidence=None, portion_count=None, portion_fraction=None,
             portion_volume_ml=None, portion_source=None, _satiety_scale=False):
    """식단 한 건의 지정 필드만 갱신(부분 업데이트). fields=={컬럼:원본값}.
    kcal은 파생이라 갱신 대상에서 제외(자동 재계산). 갱신 후 행 반환(없으면 None).

    v3.2 (036): meals 표는 없다 -- 현재값을 MEALS_V32 표면에서 읽어 병합한 뒤
    _meal_write_v32 로 그 블록을 통째로 다시 쓴다 (측정 행 전체 교체; 부분
    UPDATE 를 measure 조각마다 흉내내면 갱신 경로가 둘이 된다)."""
    fields = dict(fields)
    if 'meal' in fields:
        fields['meal'] = meal_slots.canonical(fields['meal'])
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if not conn.in_transaction:
            conn.execute('BEGIN IMMEDIATE')
        has_dishes = conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='made_dish_meal'").fetchone()
        linked = (conn.execute('SELECT dish_id,fraction FROM made_dish_meal WHERE block_id=?', (int(mid),)).fetchone()
                  if has_dishes else None)
        # Satiety may adjust inferred mass, never the declared stock share.
        # Owner corrections still use delete/re-log to restore that share.
        if linked and set(fields) - {'date', 'meal'} and not _satiety_scale:
            raise ValueError('made-dish meal: delete and log the corrected portion to restore stock')
        merged = {}
        for col, raw in fields.items():
            if col not in _MEAL_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            merged[col] = _MEAL_UPD_COLS[col](raw)
        declaration = any(v is not None for v in (portion_basis, portion_evidence,
                          portion_count, portion_fraction, portion_volume_ml, portion_source))
        if not merged and not declaration:
            raise ValueError("갱신할 필드가 없음")
        row = conn.execute(
            "SELECT id, date, meal, name, notion_id, owning_agent "
            "FROM " + MEALS_V32 + " WHERE id=?;", (int(mid),)).fetchone()
        if row is None:
            return None
        bid, date, meal, name, notion_id, owning_agent = row
        meas = dict(conn.execute(
            "SELECT metric, value FROM measure WHERE block_id=?;", (bid,)))
        cur = {'date': date, 'meal': meal, 'name': name,
               'carb': meas.get('carb'), 'protein': meas.get('protein'),
               'fat': meas.get('fat'), 'fiber': meas.get('fiber'),
               'sugar': meas.get('sugar'), 'alt_sugar': meas.get('alt_sugar'),
               'alcohol': meas.get('alcohol'),
               'grams': meas.get('portion_grams')}
        caf = conn.execute("SELECT value,source,value_origin FROM measure "
                           "WHERE block_id=? AND metric='caffeine'", (bid,)).fetchone()
        if 'mix_water_ml' in merged:
            import meal_mixture
            amount = merged.pop('mix_water_ml')
            if amount is None:
                raise ValueError('mix_water_ml requires a volume')
            meal_mixture.save(conn, bid, dict(ml=meal_mixture.volume(amount),
                              origin='stated', source='owner corrected mix water'))
        cur.update(merged)
        if declaration:
            if portion_source not in (None, 'stated', 'package', 'estimate'):
                raise ValueError('portion source must be stated, package or estimate')
            portion_basis, portion_source, portion_count, portion_fraction, portion_volume_ml = _portion_basis_check(
                portion_basis, portion_evidence, portion_source, cur['grams'],
                portion_count, portion_fraction, portion_volume_ml)
            if portion_source is not None and (_opt_num(cur['grams']) is None or _opt_num(cur['grams']) <= 0):
                raise ValueError('portion source requires positive grams')
            _portion_save(conn, bid, portion_basis, portion_evidence, portion_source,
                          portion_count, portion_fraction, portion_volume_ml)
        if not fields:
            if commit:
                conn.commit()
            return conn.execute('SELECT id,name,kcal FROM ' + MEALS_V32 + ' WHERE id=?', (bid,)).fetchone()
        vals = {'carb': _num(cur['carb'] or 0), 'protein': _num(cur['protein'] or 0),
                'fat': _num(cur['fat'] or 0), 'fiber': _num(cur['fiber'] or 0),
                'sugar': _num(cur['sugar'] or 0),
                'alt_sugar': _num(cur['alt_sugar'] or 0),
                'alcohol': _num(cur['alcohol'] or 0),
                'portion_grams': _opt_num(cur['grams'])}
        if caf:
            estimated = conn.execute('SELECT is_estimate FROM provenance WHERE token=?', (caf[2],)).fetchone()
            vals.update(caffeine=caf[0], caffeine_source=caf[1],
                        caffeine_origin='estimated' if estimated and estimated[0] else caf[2])
        if 'name' in merged or 'grams' in merged:
            vals.update(_caffeine_for_meal(sys.modules[__name__], conn, cur['name'], cur['grams']))
        _meal_write_v32(conn, cur['date'], _txt(cur['meal']), cur['name'], vals,
                        owning_agent=owning_agent or _health_agent_write(conn),
                        notion_id=notion_id, block_id=bid)
        if linked:
            import made_dish
            dish = next(d for d in made_dish.dishes(sys.modules[__name__], conn, str(linked[0])) if d['id'] == linked[0])
            recipe_grams = sum(i['nutrition']['grams'] for i in dish['ingredients']) * linked[1]
            factor = float(cur['grams']) / recipe_grams if recipe_grams else 1.0
            made_dish.apply_nutrition(conn, bid, dish, linked[1] * factor)
        if commit:
            conn.commit()
        # cut 3 lock 3: a date/slot FIX can move the meal into a declared
        # event's span -- same additive post-commit containment as meal_add.
        # (Removal stays the owner's act: a move OUT never auto-detaches.)
        if commit:
            _meal_autolink_safe(conn, bid)
        return conn.execute("SELECT id, name, kcal FROM " + MEALS_V32 + " WHERE id=?;",
                            (int(mid),)).fetchone()
    except Exception:
        conn.rollback()
        raise
    finally:
        if own:
            conn.close()


# ── 예정(planned) 식단 마커 ────────────────────────────────
# meals 에는 planned/status 컬럼이 없다. 소유자 결정(2026-08-25): 스키마를 건드리는
# 대신 "예정 항목도 실제 행으로 넣어두고, 저녁 회고에서 실제로 먹었는지 확인한다".
# 그 확정 전 상태를 나타내는 마커가 name 의 이 '끝자리' 접미사다.
#
# 부분일치(LIKE '%예정%') 금지 -- 이름 안에 우연히 그 단어가 들어간 음식
# (예: "예정식당 도시락")까지 쓸어담는다. 반드시 끝자리 고정 비교로만 본다.
# 이건 다리(bridge)지 최종형이 아니다. 정식 컬럼은 별도 lockstep 사안.
PLANNED_SUFFIX = ' (예정)'


def meal_planned_list(date, conn=None):
    """그날의 '아직 확인 안 된 예정' 식단 행 목록.

    반환: (id, meal, display_name, kcal, protein) 리스트. display_name 은 마커
    접미사를 뗀 이름(사람에게 보여줄 이름). 매칭은 substr(name, -len(suffix)) 로
    끝자리만 본다 -- LIKE 와이드카드 부분일치가 아니다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        suf = PLANNED_SUFFIX
        return conn.execute(
            "SELECT id, COALESCE(meal,''), "
            "       substr(name, 1, length(name)-length(?)), kcal, protein "
            "FROM " + MEALS_V32 + " "
            "WHERE date=? "
            "  AND length(name) > length(?) "
            "  AND substr(name, -length(?)) = ? "
            "ORDER BY id;",
            (suf, date, suf, suf, suf)).fetchall()
    finally:
        if own:
            conn.close()


def _meal_planned_food_names(name):
    # Exact food names with/without a trailing portion, for comparing a planned
    # row against a replacement. No substring/fuzzy match (ISO100 stays part of
    # the name).
    food = name[:-len(PLANNED_SUFFIX)] if name.endswith(PLANNED_SUFFIX) else name
    names = {food}
    portion = r'\s+(?:\(\d+(?:\.\d+)?\s*(?:g|ml|스쿱|개|잔|인분|scoops?)\)|\d+(?:\.\d+)?\s*(?:g|ml|스쿱|개|잔|인분|scoops?))$'
    while True:
        shorter = re.sub(portion, '', food, flags=re.I)
        if shorter == food or not shorter:
            return names
        names.add(shorter)
        food = shorter


# The planned meal row IS the open state (owner 2026-10-22): no owner task is
# opened for it any more. Markers an older diet-plan opened are settled by
# migration 097 and, for any that still appear, by meal-planned-marker-retire.
_PLANNED_MARKER_SQL = (
    "SELECT t.id, t.version FROM timeblock t WHERE t.kind='task' "
    "AND t.settled_at IS NULL AND (EXISTS (SELECT 1 FROM block_attr a "
    "WHERE a.block_id=t.id AND a.attr_token='planned_meal_ulid') "
    "OR (t.title LIKE '회고: %' AND t.title LIKE '% 예정대로 드셨는지 확인') "
    "OR (t.title LIKE 'Review: %' AND t.title LIKE '% — did you eat it as planned?')) "
    "ORDER BY t.id")


def _meal_planned_close_tasks(conn, tasks, outcome):
    """Transaction-local settle of legacy review markers (bookkeeping, not
    activity evidence: unrelated completion gates must not block it)."""
    now = now_utc()
    for tid, version in tasks:
        n = _tb_update(conn, tid, {'settled_at': now, 'settled_outcome': outcome,
                       'settled_by': 'meal-planned', 'updated_at': now},
                       where_extra=' AND settled_at IS NULL',
                       bump_version=True, cas_version=version)
        if n != 1:
            raise ValueError('planned review changed during retirement')
        _recompute_and_store(conn, tid, now=now)
    return len(tasks)


def _meal_planned_enqueue(conn, tasks):
    # Queue the mirror push for settled markers (post-commit contract).
    for tid, _ in tasks:
        row = conn.execute('SELECT ulid FROM block WHERE id=?', (tid,)).fetchone()
        if row:
            _outbox_enqueue_best_effort(row[0])


def _meal_swap_slot(slot):
    # Retain numbered historical snacks when matching old planned meals.
    slot = (meal_slots.stored(slot) or '').strip().casefold()
    return 'snack' if re.match(r'^(?:간식|snack)(?:$|[\s_#(\d-])', slot) else slot


def meal_planned_swap_candidates(conn, eaten_id):
    row = _meal_row_full(conn, eaten_id)
    if not row or row[3].endswith(PLANNED_SUFFIX):
        return []
    return [r for r in meal_planned_list(row[1], conn=conn)
            if _meal_swap_slot(r[1]) == _meal_swap_slot(row[2])]


def _emit_planned_swap(conn, eaten_id):
    candidates = meal_planned_swap_candidates(conn, eaten_id)
    for mid, slot, name, *_ in candidates:
        print('PLANNED_SWAP_ASK\t' + json.dumps(dict(
            planned_id=mid, eaten_id=eaten_id, name=name,
            question=_i18n('meal.planned.swap_question',
                           'Did you eat this instead of the {name} you planned earlier?').format(name=name)),
            ensure_ascii=False))
        print(_ask_choices().options_line('PLANNED_SWAP_ASK', '%s:%s' % (mid,eaten_id), [('yes',_i18n('ask.yes','Yes')),('no',_i18n('ask.no','No'))]))
    if candidates:
        print('PLANNED_SWAP_RELAY Ask ONLY the question in PLANNED_SWAP_ASK, one row at a time. '
              'No target/satiety question or intake verdict until answered. '
              'Yes -> meal-planned-swap <planned_id> --eaten <eaten_id>; '
              'no -> meal-planned-swap <planned_id> --keep. '
              'Never show machine tags or IDs to the owner. The eaten meal is already saved.')
    return bool(candidates)


def cli_meal_planned_add(argv):
    # Same lookup/nutrition/duplicate contract as meal-add; task is atomic.
    if len(argv) < 3:
        _err('usage: meal-planned-add DATE SLOT NAME [macros] [--at HH:MM] [--new]')
    argv = list(argv)
    if not argv[2].endswith(PLANNED_SUFFIX):
        argv[2] += PLANNED_SUFFIX
    cli_meal_add(argv)


PLANNED_MEAL_CHOICES = (('ate', 'meal.planned.ask.ate', 'I ate it'),
                        ('skip', 'meal.planned.ask.skip', 'I did not eat it'),
                        ('other', 'meal.planned.ask.other', 'I ate something else'))


def _planned_meal_choices():
    return [(k, _i18n(key, dflt)) for k, key, dflt in PLANNED_MEAL_CHOICES]


def _planned_meal_clock(value):
    """An explicitly planned local clock, independent of eating occurrence time.

    block_attr already stores optional per-meal facts; no schema migration or
    backfill is needed. Unknown time remains absent.
    """
    value = str(value).strip()
    if not re.fullmatch(r'(?:[01]\d|2[0-3]):[0-5]\d', value):
        raise ValueError('planned meal time must be HH:MM (00:00..23:59)')
    return value


def _planned_meal_when(value):
    if value is None:
        return ''
    h, m = map(int, _planned_meal_clock(value).split(':'))
    hour = h % 12 or 12
    period = (_i18n('meal.planned.time.am', 'am ') if h < 7 else
              _i18n('meal.planned.time.pm', 'pm ') if h >= 19 else '')
    key = 'half' if m == 30 else 'minute' if m else 'hour'
    fallback = {'half': '{period}{hour}:30 or so ',
                'minute': '{period}{hour}:{minute:02d} or so ',
                'hour': '{period}{hour} or so '}[key]
    return _i18n('meal.planned.time.' + key, fallback).format(
        period=period, hour=hour, minute=m, clock=value)


def meal_planned_asks(date, conn=None):
    """One ask per still-unconfirmed planned row of `date` -- the planned meal
    row is the open state, nothing else is. [(id, question, token line,
    ASK_OPTIONS line)]."""
    out = []
    choices = _planned_meal_choices()
    own = conn is None
    conn = conn or get_conn()
    try:
        rows = meal_planned_list(date, conn=conn)
        clocks = dict(conn.execute(
            "SELECT a.block_id, a.value FROM block_attr a JOIN " + MEALS_V32 +
            " m ON m.id=a.block_id WHERE m.date=? AND a.attr_token='meal_planned_at' "
            "AND a.source='user'", (date,)))
    finally:
        if own:
            conn.close()
    for mid, slot, name, _kcal, _protein in rows:
        when = _planned_meal_when(clocks.get(mid))
        q = _i18n('meal.planned.ask_question',
                  'You planned {name} for {slot} {when}-- did you eat it?').format(
                      name=name, slot=meal_slots.label(slot), when=when)
        out.append((mid, q,
                    'PLANNED_MEAL_ASK\t%s\t%s\t%s' % (
                        mid, q, _ask_choices().choices_field(choices)),
                    _ask_choices().options_line('PLANNED_MEAL_ASK', mid, choices)))
    return out


def cli_meal_planned_ask(argv):
    # meal-planned-ask DATE [--wrap | --walk]
    # default: PLANNED_MEAL_ASK + ASK_OPTIONS lines (agent relay).
    # --wrap: the evening wrap's own rendering: `ask<TAB>question` lines and one
    #   `buttons<TAB>json` line (opt: callbacks carry the button label).
    argv, wrap = _pop_flag(list(argv), '--wrap')
    argv, walk = _pop_flag(argv, '--walk')
    if len(argv) != 1 or not _DATE_RE.match(argv[0]) or (wrap and walk):
        _err('usage: meal-planned-ask DATE [--wrap | --walk]')
    asks = meal_planned_asks(argv[0])
    if not asks:
        return
    if walk:
        # The retro walk's rendering: one `ask<TAB>json` row per planned row
        # (the retro-sections ask contract), each asked as its own message
        # after the card. "I ate something else" still needs the owner to say
        # what, so that choice is a `talk`; the other two settle the row.
        for mid, q, _tok, _opt in asks:
            print('ask\t' + json.dumps(dict(id='planned:%s' % mid, text=q, choices=[
                dict(label=l, cmd='kit:meal-planned-answer %s %s' % (mid, k),
                     **({'then': 'talk'} if k == 'other' else {}))
                for k, l in _planned_meal_choices()]), ensure_ascii=False))
        return
    if wrap:
        # One question per card: the buttons answer exactly one row. The next
        # still-planned row is asked after this answer (agent relay below).
        print('ask\t' + asks[0][1])
        print('buttons\t' + json.dumps([[
            {'text': l, 'callback_data': 'opt:' + l}
            for _k, l in _planned_meal_choices()]], ensure_ascii=False))
        return
    for _mid, _q, tok, opt in asks:
        print(tok)
        print(opt)
    print('PLANNED_MEAL_RELAY Ask ONLY the question of a PLANNED_MEAL_ASK, one row at a time, '
          'with its buttons. The answer command is the answer= field of its ASK_OPTIONS line. '
          'ate -> the row counts as eaten; skip -> the row leaves the day; other -> ask what was '
          'eaten instead and log it through the ordinary meal log (its planned-swap question '
          'settles the planned row). Never show machine tags or IDs to the owner.')


def cli_meal_planned_answer(argv):
    # meal-planned-answer ID ate|skip|other -- the answer settles the row itself.
    if len(argv) != 2 or not argv[0].isdigit() or argv[1] not in ('ate', 'skip', 'other'):
        _err('usage: meal-planned-answer ID ate|skip|other')
    mid, value = int(argv[0]), argv[1]
    conn = get_conn()
    try:
        row = _meal_row_full(conn, mid)
    finally:
        conn.close()
    if row is None or not row[3].endswith(PLANNED_SUFFIX):
        print(_i18n('meal.planned.not_pending', 'This food is already confirmed or was never planned.'))
        return
    if value == 'ate':
        return cli_meal_planned_confirm([str(mid)])
    if value == 'skip':
        # The owner's "did not eat it" IS the confirmation the drop census asks for.
        return cli_meal_planned_drop([str(mid), '--confirm-kcal', _f0(row[4])])
    print('PLANNED_MEAL_OTHER\t%d\t%s' % (mid, row[3][:-len(PLANNED_SUFFIX)]))
    print('PLANNED_MEAL_OTHER_RELAY Ask what was eaten instead, log it with the ordinary meal log '
          '(meal-add, same date and slot); its PLANNED_SWAP_ASK settles this planned row. Nothing '
          'is changed yet. Never print this line.')


def cli_meal_planned_swap(argv):
    argv, eaten = _pop_opt(argv, '--eaten')
    argv, keep = _pop_flag(argv, '--keep')
    if len(argv) != 1 or not argv[0].isdigit() or keep == (eaten is not None) or (eaten is not None and not eaten.isdigit()):
        _err('usage: meal-planned-swap ID --eaten ID | --keep')
    conn = get_conn()
    try:
        conn.execute('BEGIN IMMEDIATE')
        row = _meal_row_full(conn, int(argv[0]))
        if not row or not row[3].endswith(PLANNED_SUFFIX):
            _err(_i18n('meal.planned.closed', 'That planned food has already been resolved.'))
        if keep:
            conn.rollback()
            print(_i18n('meal.planned.kept', 'Kept both foods.'))
            return
        if int(argv[0]) not in [r[0] for r in meal_planned_swap_candidates(conn, int(eaten))]:
            _err(_i18n('meal.planned.wrong_replacement', 'Choose the food eaten on the same day and at the same meal.'))
        if row[6]:
            _err(_i18n('meal.planned.mirrored', 'This planned food also has an external record; reconcile that record first.'))
        meal_del(int(argv[0]), conn=conn)
        print(_i18n('meal.planned.swapped', 'Removed the planned food; only the food you ate counts.'))
    finally:
        conn.close()


def meal_planned_marker_retire(conn=None):
    """Settle every still-open legacy review marker as abandoned; the planned
    meal rows are untouched. Returns the number settled. Mirror enqueue covers
    these rows and, once, the ones migration 097 settled in SQL."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        conn.execute('BEGIN IMMEDIATE')
        tasks = conn.execute(_PLANNED_MARKER_SQL).fetchall()
        count = _meal_planned_close_tasks(conn, tasks, 'abandoned')
        done = conn.execute("SELECT 1 FROM config WHERE key='meal_marker_retire_enqueued'").fetchone()
        sql_settled = [] if done else [(r[0], 0) for r in conn.execute(
            "SELECT id FROM block WHERE kind_token='task' AND settled_by='meal-planned' "
            "AND settled_outcome='abandoned'")]
        if not done:
            conn.execute("INSERT OR REPLACE INTO config(key, value) VALUES('meal_marker_retire_enqueued','1')")
        conn.commit()
        _meal_planned_enqueue(conn, tasks + [t for t in sql_settled if t[0] not in {x[0] for x in tasks}])
        return count
    except Exception:
        conn.rollback()
        raise
    finally:
        if own:
            conn.close()


def cli_meal_planned_marker_retire(argv):
    if argv:
        _err('usage: meal-planned-marker-retire')
    print('PLANNED_MARKERS_RETIRED\t%d' % meal_planned_marker_retire())



# ── v3.2 축: meals 읽기 표면 (2026-09-05) ──────────────────────────────────
# 구 스키마의 meals 한 행이 v3.2 에서 넷으로 흩어진다:
#   block 1행 (source_module='diet', settled_by='meal-record')
#   measure 11행 (carb / protein / fat / fiber / sugar / sodium / caffeine ...)
#   block_delta 1행 (nutrition) + block_attr 3행 (meal_slot / notion_id / owning_agent)
#
# ** 이 상수가 그 역조립의 유일한 사본이다. ** 읽기 함수 13개가 각자 피벗 SQL 을
# 들면 같은 공식이 13벌 생긴다 -- B2 에서 EFF_END 를 v_block_span 하나로 모은 것과
# 같은 이유로 여기서도 하나만 둔다.
#
# 뷰가 아니라 코드 상수인 이유: 스키마가 'carb'/'protein' 같은 도메인 어휘를 들면
# 규칙 B 위반이다(기계는 어휘를 모르고 플래그만 읽는다). 그리고 kit_life.py 밖에서
# 이 표를 SQL 로 직접 읽는 소비자는 실측 0건이라, 코드에 두는 비용이 없다.
#
# kcal 공식은 ** 지어내지 않고 원천 정의를 그대로 옮긴다. ** 구 meals.kcal 은
# GENERATED ALWAYS AS (protein*4 + fat*9 + (carb-fiber)*4 + alcohol*7) 이다 --
# 총탄수가 아니라 ** 순탄수(carb-fiber) ** 이고 알코올 7kcal 이 들어간다.
# 내가 처음에 carb*4+protein*4+fat*9 로 짰다가 545행 중 298행이 어긋났다.
# transform-v3.2.py:1004 가 같은 실수를 이미 기록해 두었다("the stored generated
# value IS the fact -- do not re-derive a fact that the source already computes").
_MEAL_KCAL = ("ROUND(COALESCE({protein},0)*4 + COALESCE({fat},0)*9 "
              "+ (COALESCE({carb},0) - COALESCE({fiber},0))*4 "
              "+ COALESCE({alcohol},0)*7, 2)")
_MEAL_M = ("(SELECT m.value FROM measure m WHERE m.block_id = b.id "
           "AND m.metric = '%s' LIMIT 1)")
_MEAL_A = ("(SELECT a.value FROM block_attr a WHERE a.block_id = b.id "
           "AND a.attr_token = '%s' LIMIT 1)")

MEALS_V32 = """(
  SELECT b.id                            AS id,
         b.date                          AS date,
         COALESCE({slot}, '')            AS meal,
         b.title                         AS name,
         {carb}                          AS carb,
         {protein}                       AS protein,
         {fat}                           AS fat,
         {sugar}                         AS sugar,
         {kcal}                          AS kcal,
         {notion}                        AS notion_id,
         {owner}                         AS owning_agent,
         b.created_at                    AS created_at,
         {fiber}                         AS fiber,
         {alcohol}                       AS alcohol,
         {grams}                         AS grams
  FROM block b
  WHERE b.settled_by = 'meal-record'
)""".format(slot=meal_slots.stored_sql(_MEAL_A % 'meal_slot'), notion=_MEAL_A % 'notion_id',
            owner=_MEAL_A % 'owning_agent',
            carb=_MEAL_M % 'carb', protein=_MEAL_M % 'protein',
            fat=_MEAL_M % 'fat', sugar=_MEAL_M % 'sugar',
            fiber=_MEAL_M % 'fiber', alcohol=_MEAL_M % 'alcohol',
            grams=_MEAL_M % 'portion_grams',
            kcal=("COALESCE((SELECT value FROM measure WHERE block_id=b.id "
                  "AND metric='kcal_intake' AND source='module:made-dish' LIMIT 1), "
                  + _MEAL_KCAL.format(protein=_MEAL_M % 'protein',
                                   fat=_MEAL_M % 'fat',
                                   carb=_MEAL_M % 'carb',
                                   fiber=_MEAL_M % 'fiber',
                                   alcohol=_MEAL_M % 'alcohol') + ')'))


def _meal_row_full(conn, mid):
    """(id, date, meal, name, kcal, protein, notion_id) 또는 None."""
    return conn.execute(
        "SELECT id, date, COALESCE(meal,''), name, kcal, protein, notion_id "
        "FROM " + MEALS_V32 + " WHERE id=?;", (int(mid),)).fetchone()


def _meal_day_census(conn, date):
    """(행 수, kcal 합) -- 삭제 전/후 대조용."""
    row = conn.execute(
        "SELECT COUNT(*), COALESCE(SUM(kcal),0) FROM " + MEALS_V32 + " WHERE date=?;",
        (date,)).fetchone()
    return int(row[0]), float(row[1])


