def _day_pin_inbound_token(message_id=None):
    # opt: delivers the button LABEL; the stable token is in tap metadata.
    path = os.path.join(_instance_root(), ".telegram_bot", "inbound-context.json")
    try:
        with open(path, encoding="utf-8") as fh:
            ctx = json.load(fh)
        if ctx.get("source") != "callback":
            return None
        if message_id is not None and str(ctx.get("message_id")) != str(message_id):
            return None
        data = ctx.get("callback_data") or ""
        return data[4:] if data.startswith("opt:pin:") else None
    except (OSError, ValueError, TypeError, AttributeError):
        return None


def cli_start_tap(argv):
    # start-tap "<tapped text>" [--message-id N]
    #   A tap on a start card (start_card.py). The card is the tapped bubble:
    #   --message-id, else the bridge's inbound-context (source callback).
    #   -> JSON {status, id, title, action, next, ...}
    argv, mid = _pop_opt(argv, '--message-id')
    argv, at = _pop_opt(argv, '--at')
    if len(argv) != 1 or not argv[0].strip():
        _err('usage: kit_life.sh start-tap "<tapped text>" [--message-id N]')
    try:
        with open(os.path.join(_instance_root(), '.telegram_bot', 'inbound-context.json')) as fh:
            ctx = json.load(fh)
    except (OSError, ValueError):
        ctx = {}
    data = ctx.get('callback_data', '') if ctx.get('source') == 'callback' else ''
    activity_token = argv[0].strip() if argv[0].strip().startswith('activity:') else (
        data[4:] if isinstance(data, str) and data.startswith('opt:activity:') else None)
    if activity_token:
        import cooking_session
        conn = event_conn()
        try:
            out = cooking_session.apply(sys.modules[__name__], conn, activity_token,
                                         message_id=mid or ctx.get('message_id'))
        finally:
            conn.close()
        print(json.dumps(out, ensure_ascii=False))
        return
    sc = _start_card_mod()
    token = (argv[0].strip() if argv[0].strip().startswith("pin:")
             else _day_pin_inbound_token(mid))
    if token:
        conn = event_conn()
        try:
            out = day_pin_tap(conn, token)
            card = _done_card(conn, 'start-tap', out['id']) if out.get('status') == 'DONE' else ''
        finally:
            conn.close()
        if card:
            out['next'] = _timeblock_card_mod().NEXT
        print(json.dumps(out, ensure_ascii=False))
        _timeblock_card_mod().emit(sys.modules[__name__], card)
        return
    if mid is None:
        mid = sc.inbound_message_id(sys.modules[__name__])
    conn = event_conn()
    try:
        out = sc.tap(sys.modules[__name__], conn, argv[0], message_id=mid,
                     now=canonical(now_utc()), at=at)
        state = {'DONE': 'done', 'DONE_TIME': 'done', 'CANCELLED': 'cancelled',
                 'SNOOZED': 'postponed'}.get(out.get('status'))
        card = _mutation_card(conn, 'start-tap', out['id'], state) if state else ''
    finally:
        conn.close()
    if card:
        out["next"] = _timeblock_card_mod().NEXT
    print(json.dumps(out, ensure_ascii=False))
    _timeblock_card_mod().emit(sys.modules[__name__], card)


def _pin_agent():
    # A read scope may contain several agents. A session runner is ONE agent.
    agent = scope_self().get("agent")
    return agent if agent and _AGENT_SLUG_RE.match(agent) else _facade_agent()


def session_start_entry(conn, block_id):
    """Structured handoff shared by pin and timed start-card buttons."""
    row = conn.execute(
        "SELECT e.ulid,e.title,e.owning_agent,e.settled_at,"
        "COALESCE(a.value,'check'),d.purpose,e.rec_date,e.start_at,e.display_tz FROM timeblock e "
        "LEFT JOIN block_attr a ON a.block_id=e.id AND a.attr_token='action_kind' "
        "LEFT JOIN routine_def d ON d.recurrence_id=e.recurrence_id "
        "WHERE e.id=? AND e.kind='task' AND e.block_class IS NULL;",
        (block_id,)).fetchone()
    if not row or row[3] is not None or row[2] != _pin_agent() or row[4] == "check":
        return {"status": "SPENT", "next": "NO_PUSH"}
    ulid, title, owner, _, kind, purpose, rec_date, start_at, display_tz = row
    if _config_stored(conn, 'cooking.plan.' + str(block_id)):
        import cooking_session
        return cooking_session.start_task(sys.modules[__name__], conn, block_id)
    active = _activity_session_state(conn)
    if active and active['phase'] not in ('closed', 'cancelled'):
        return dict(status='SESSION_OPEN', next='Continue cooking with cooking input; keep this task open.')
    lane = "weekly" if purpose == "retro:weekly" else "daily"
    if kind == "retro":
        if lane == "weekly":
            rec = conn.execute("SELECT rec_date FROM timeblock WHERE id=?", (block_id,)).fetchone()
            if rec and rec[0]:
                weekly_retro_record(conn, weekly_retro_week_end(rec[0]), "started")
                conn.commit()
        entry = "brief-session"
        nxt = ("Open brief-session in the %s lane for this existing task; "
               "read its lane reference and begin the retro now. Exclude this task from "
               "leftover task questions; complete it when the retro closes. "
               "Do not create another task." % lane)
        if lane == "daily":
            # The occurrence, not the time of the tap, owns the retro day.
            import retro_session
            if not rec_date and not start_at:
                return dict(status="ASK_DATE", id=block_id, entry=entry, lane=lane,
                            next="Ask which daily retro date to open; this task has no date.")
            date = rec_date or str(_local_date_of(start_at, display_tz or "Asia/Seoul"))
            daily = retro_session.resolve("retro:daily:" + date)
            nxt += " " + daily["next"]
    elif kind == "workout":
        entry = "workout-session"
        nxt = ("Open workout-session for this existing task. Read reference/session-start.md; "
               "run service/health/rx-calc first, then service/health/session-open. "
               "Keep the existing task id/ulid; never mark it done on start.")
    else:
        entry = "session-start"
        nxt = ("Run this owning agent's session start entry for the existing task; "
               "use its id and ulid, never mark it done on start.")
    related = _related_shopping(conn, title, block_id)
    return dict(status="SESSION_START", id=block_id, ulid=ulid, title=title,
                kind=kind, owning_agent=owner, entry=entry,
                lane=lane if kind == "retro" else None,
                prepare=("routines/bundle/weekly-review.sh --marker-only"
                         if kind == "retro" and lane == "weekly" else None), next=nxt,
                **({"retro_date": daily["retro_date"], "tomorrow": daily["tomorrow"]}
                   if kind == "retro" and lane == "daily" else {}),
                **({"related_shopping": related} if related else {}))


def day_pin_tap(conn, token, now=None):
    """Claim only a token from this instance's latest rendered keyboard.

    Bare chat containing '#123' must never settle a task. Nonces retire all
    old buttons on re-render; ulid + version fence deletes, edits and moves.
    """
    now = now or now_utc()
    key = "day_pin_actions." + _pin_agent()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        actions = json.loads(_config_stored(conn, key) or "{}")
        hit = actions.get(token)
        if not hit:
            conn.rollback()
            return {"status": "SPENT", "next": "NO_PUSH"}
        if hit["kind"] == "routine_retire":
            defn = routine_def_get(conn, hit["ulid"])
            ask_key = "routine_retire_ask." + (defn["recurrence_id"] if defn else "")
            if (not defn or defn["status"] != "active"
                    or defn["version"] != hit["version"]
                    or _config_stored(conn, ask_key) != "pending"):
                conn.rollback()
                return {"status": "SPENT", "next": "NO_PUSH"}
            actions.pop(token)
            _config_put(conn, key, json.dumps(actions))
            if hit["choice"] == "keep":
                _config_put(conn, ask_key, "asked")
            conn.commit()
            if hit["choice"] == "retire":
                result = routine_retire(conn, defn["ulid"], now=now)
                if result["result"] != "applied":
                    # Re-arm the spent token so the same button works again.
                    fresh = json.loads(_config_stored(conn, key) or "{}")
                    fresh[token] = hit
                    _config_put(conn, key, json.dumps(fresh))
                    conn.commit()
                    return {"status": "RETRY", "next": "Tap the button again."}
                _config_put(conn, ask_key, "asked")
                conn.commit()
            return {"status": "ROUTINE_RETIRED" if hit["choice"] == "retire"
                    else "ROUTINE_KEPT", "ulid": defn["ulid"], "next": "NO_PUSH"}
        row = conn.execute(
            "SELECT id,ulid,version,settled_at FROM timeblock "
            "WHERE ulid=? AND kind='task' AND block_class IS NULL;",
            (hit["ulid"],)).fetchone()
        if not row or row[2] != hit["version"] or row[3] is not None:
            conn.rollback()
            return {"status": "SPENT", "next": "NO_PUSH"}
        if hit["kind"] == "check" and _workout_history.task_sessions(
                sys.modules[__name__], conn, row[0]):
            conn.rollback()
            return dict(status="SESSION_OPEN", id=row[0], next=_workout_history.SESSION_NEXT)
        # Save the claim before the mutation (force_settle owns its txn).
        actions.pop(token)
        _config_put(conn, key, json.dumps(actions))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    if hit["kind"] != "check":
        return session_start_entry(conn, row[0])
    res = force_settle(conn, row[0], row[2], "owner-chat", settled_at_ts=now,
                       move_late=True)
    if res == MutationResult.SESSION_OPEN:
        return dict(status="SESSION_OPEN", id=row[0], next=_workout_history.SESSION_NEXT)
    if res != MutationResult.APPLIED:
        return {"status": "RETRY", "id": row[0], "next": "Refresh the pin and tap again."}
    _photo_gate_release(conn, now, row[0])
    _outbox_enqueue_best_effort(row[1])
    return {"status": "DONE", "id": row[0], "title": hit["title"], "next": "NO_PUSH"}


