def routine_today(tz_name="Asia/Seoul"):
    """Local calendar date (ISO string) in the routine display tz."""
    return datetime.datetime.now(ZoneInfo(tz_name)).strftime("%Y-%m-%d")


def routine_def_get(conn, token):
    """routine_def row (sqlite3.Row-like dict) by def ulid, recurrence_id or
    integer id. None if absent."""
    old_factory = conn.row_factory
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT * FROM routine_def WHERE ulid=? OR recurrence_id=?;",
            (token, token)).fetchone()
        if row is None and str(token).isdigit():
            row = conn.execute(
                "SELECT * FROM routine_def WHERE id=?;", (int(token),)).fetchone()
        return routine_placement_load(conn, dict(row)) if row is not None else None
    finally:
        conn.row_factory = old_factory


def routine_placement_load(conn, defn):
    """Attach the validated 092 aggregate; pre-092 stores stay readable."""
    if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='routine_placement'").fetchone():
        row = conn.execute("SELECT spec FROM routine_placement WHERE routine_id=?",
                           (defn['id'],)).fetchone()
        if row:
            import placement_alternatives as pa
            duration = (_projection_mod().DEFAULT_DURATION_MIN if defn['duration_min'] is None
                        else defn['duration_min'])
            defn['placement_alternatives'] = pa.validate(row[0], duration)
    return defn


def _alternatives_validate(spec, duration_min, kind, place_id, placement,
                           fallback_at, ride_not_before, ride_prefer):
    if spec is None:
        return None
    import placement_alternatives as pa
    if (kind != 'task' or place_id is not None or placement is not None
            or fallback_at is not None or ride_not_before is not None
            or ride_prefer is not None):
        raise ValueError(_i18n('routine.placement.shape',
            'Use alternatives for an anywhere task; clear place and legacy ride fields.'))
    try:
        duration = (_projection_mod().DEFAULT_DURATION_MIN if duration_min is None else duration_min)
        return pa.validate(spec, duration)
    except ValueError as exc:
        reason = getattr(exc, 'reason', 'conditions')
        raise ValueError(_i18n('routine.placement.invalid_' + reason,
            _i18n('routine.placement.invalid',
                  'Cannot execute that interval or condition. Check the times, duration and supported fields.'))) from exc


def _alternatives_tod(spec):
    """Display hint only. Every execution must use the candidate selector."""
    return next((a['start_not_before'] for a in spec['alternatives']
                 if a['type'] == 'window'), spec.get('fallback_at', '00:00'))


def routine_retro_skip_set(conn, token, skip):
    """052: set per-routine retro-question exclusion state.

    This changes only retro questioning. It does not pause the routine, hide
    its events, or remove it from schedule displays -- routine_def.status is
    a different axis and this verb never touches it.
    Returns (id, ulid, retro_skip), or None when the definition is absent.
    """
    defn = routine_def_get(conn, token)
    if defn is None:
        return None

    value = 1 if skip else 0
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE routine_def "
            "SET retro_skip=?, version=version+1, updated_at=? "
            "WHERE id=?;",
            (value, now_utc(), defn["id"]))
        if cur.rowcount != 1:
            conn.rollback()
            return None
        conn.commit()
        return defn["id"], defn["ulid"], value
    except Exception:
        conn.rollback()
        raise


def routine_def_for_event(conn, token):
    """052: resolve the routine_def that generated an event.

    Returns the same dict shape as routine_def_get, or None when the event
    does not exist, is not a routine occurrence, or references no current
    definition."""
    if str(token).isdigit():
        row = conn.execute(
            "SELECT recurrence_id FROM timeblock WHERE id=?;",
            (int(token),)).fetchone()
    else:
        row = conn.execute(
            "SELECT recurrence_id FROM timeblock WHERE ulid=?;",
            (str(token),)).fetchone()

    if row is None or not row[0]:
        return None
    return routine_def_get(conn, row[0])


# ── 053: carry_item (자원축) -- possession / containment / routine defaults /
# per-event prep, reusing sub_event(kind='prep_item', ref=carry_item.ulid).
_CARRY_COLS = ("id", "ulid", "name", "item_kind", "parent_id", "possession",
              "acquired_on", "released_on", "possession_as_of", "source",
              "owning_agent", "status", "created_at", "updated_at")


def _carry_item_row_dict(row):
    return dict(zip(_CARRY_COLS, row))


def carry_item_get(conn, token):
    """carry_item row (dict) by integer id or ulid. None if absent."""
    cols = ", ".join(_CARRY_COLS)
    if str(token).isdigit():
        row = conn.execute(
            "SELECT %s FROM carry_item WHERE id=?;" % cols,
            (int(token),)).fetchone()
    else:
        row = conn.execute(
            "SELECT %s FROM carry_item WHERE ulid=?;" % cols,
            (str(token),)).fetchone()
    return _carry_item_row_dict(row) if row is not None else None


def carry_item_add(conn, name, item_kind="item", possession="unknown",
                   source="user", owning_agent=None):
    """053: register one portable possession. Returns the new row (dict).

    No duplicate-name gate (DGN-231's EXISTS pattern is for calendar-facing
    add verbs; an owner naming two things "여분 충전기" is not a mistake to
    catch here) -- carry-list is how a duplicate would be noticed."""
    name = str(name).strip()
    if not name:
        raise ValueError("carry_item_add: name required")
    if item_kind not in ("item", "container"):
        raise ValueError("carry_item_add: item_kind must be item|container, "
                         "got %r" % item_kind)
    if possession not in ("has", "has_not", "unknown"):
        raise ValueError("carry_item_add: possession must be "
                         "has|has_not|unknown, got %r" % possession)
    owning_agent = owning_agent or _facade_agent()
    ulid = new_ulid()
    now = now_utc()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT INTO carry_item (ulid, name, item_kind, possession, "
            "source, owning_agent, status, created_at, updated_at) "
            "VALUES (?,?,?,?,?,?, 'active', ?,?);",
            (ulid, name, item_kind, possession, source, owning_agent,
             now, now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return carry_item_get(conn, ulid)


def carry_item_list(conn, possession=None, include_retired=False):
    """053: carry_item rows, id-ordered. status='active' only unless
    include_retired (CLI --all)."""
    cols = ", ".join(_CARRY_COLS)
    sql = "SELECT %s FROM carry_item" % cols
    where, params = [], []
    if not include_retired:
        where.append(LIVE_CARRY_SQL)
    if possession is not None:
        where.append("possession=?")
        params.append(possession)
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY id;"
    return [_carry_item_row_dict(r) for r in conn.execute(sql, params).fetchall()]


_CARRY_UPD_COLS = ("name", "item_kind", "possession", "acquired_on",
                   "released_on", "possession_as_of", "status")


def carry_item_update(conn, token, fields):
    """053: raw field setter (carry-upd). `parent_id` is NOT settable here --
    that is carry_item_pack's job alone, because it is the one write that
    needs the cycle guard.

    Losing possession (has -> has_not|unknown) auto-clears parent_id in the
    SAME update: the schema CHECK (parent_id IS NULL OR possession='has')
    would otherwise turn "오너가 잃어버렸다고 말했다" into a raw
    IntegrityError instead of the natural reading (a thing you no longer
    have cannot still be "packed" anywhere).
    Returns the updated row (dict), or None when the item does not exist."""
    item = carry_item_get(conn, token)
    if item is None:
        return None
    bad = [k for k in fields if k not in _CARRY_UPD_COLS]
    if bad:
        raise ValueError("carry_item_update: column(s) not updatable: %s "
                         "(allowed: %s)" % (bad, list(_CARRY_UPD_COLS)))
    if not fields:
        raise ValueError("carry_item_update: no fields given")
    cols = sorted(fields.keys())
    sets = ["%s=?" % c for c in cols]
    params = [fields[c] for c in cols]
    if "possession" in fields and fields["possession"] != "has" \
            and item["parent_id"] is not None:
        sets.append("parent_id=NULL")
    sets.append("updated_at=?")
    params.append(now_utc())
    params.append(item["id"])
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "UPDATE carry_item SET %s WHERE id=?;" % ", ".join(sets), params)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return carry_item_get(conn, item["id"])


def _carry_chain_has_cycle(conn, start_id, item_id):
    """True if walking parent_id upward from `start_id` reaches `item_id` --
    i.e. setting item_id.parent_id = start_id would close a cycle. Same
    shape as _parent_chain_has_cycle (ledger_goal); a CHECK cannot see the
    chain above the row being written, so this is the tool layer's guard
    (040's own division: event.parent_id's depth/cycle guard is code, not
    schema)."""
    seen = set()
    cid = start_id
    while cid is not None:
        if cid == item_id:
            return True
        if cid in seen:
            return False
        seen.add(cid)
        row = conn.execute(
            "SELECT parent_id FROM carry_item WHERE id=?;", (cid,)).fetchone()
        cid = row[0] if row else None
    return False


def carry_item_pack(conn, item_token, container_token):
    """053: carry-pack -- set (or clear) an item's container.

    container_token == 'none' (case-insensitive) clears parent_id. Rejects
    self-parenting and any container already below the item (cycle guard).
    Requires possession='has' on the item when packing into a real
    container -- schema CHECK (parent_id IS NULL OR possession='has')
    enforces this at the DB layer too; the check here exists to give a
    named error instead of a raw IntegrityError.
    Returns the updated item row (dict). Raises ValueError on item/container
    not found or an invalid link; never returns None silently."""
    item = carry_item_get(conn, item_token)
    if item is None:
        raise ValueError("carry-pack: item not found: %s" % item_token)
    if item["status"] != "active":
        raise ValueError("carry-pack: item is retired: %s" % item_token)

    if str(container_token).strip().lower() == "none":
        conn.execute("BEGIN IMMEDIATE;")
        try:
            conn.execute(
                "UPDATE carry_item SET parent_id=NULL, updated_at=? "
                "WHERE id=?;", (now_utc(), item["id"]))
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        return carry_item_get(conn, item["id"])

    container = carry_item_get(conn, container_token)
    if container is None:
        raise ValueError("carry-pack: container not found: %s"
                         % container_token)
    if container["status"] != "active":
        raise ValueError("carry-pack: container is retired: %s"
                         % container_token)
    if container["id"] == item["id"]:
        raise ValueError("carry-pack: 자기 자신을 담을 수 없어요")
    if _carry_chain_has_cycle(conn, container["id"], item["id"]):
        raise ValueError("carry-pack: 이미 그 아래 있는 컨테이너예요 "
                         "(순환)")
    if item["possession"] != "has":
        raise ValueError("carry-pack: 갖고 있지 않은 물건은 담을 수 없어요 "
                         "(possession=%s)" % item["possession"])

    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "UPDATE carry_item SET parent_id=?, updated_at=? WHERE id=?;",
            (container["id"], now_utc(), item["id"]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return carry_item_get(conn, item["id"])


# ── routine defaults: routine_prep_item junction (routine_def <-> carry_item)
def routine_prep_add(conn, routine_token, item_token, source="user"):
    """053: add one carry_item to a routine's default packing list.
    Idempotent (PK is the pair). Returns (routine_ulid, item_ulid, item_name),
    or None when the routine or the item does not exist."""
    defn = routine_def_get(conn, routine_token)
    if defn is None:
        return None
    item = carry_item_get(conn, item_token)
    if item is None:
        return None
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT OR IGNORE INTO routine_prep_item "
            "(routine_def_id, carry_item_id, source, created_at) "
            "VALUES (?,?,?,?);",
            (defn["id"], item["id"], source, now_utc()))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return defn["ulid"], item["ulid"], item["name"]


def routine_prep_rm(conn, routine_token, item_token):
    """053: remove one carry_item from a routine's default packing list.
    Returns (routine_ulid, item_ulid, item_name), or None when the routine,
    the item, or the link itself does not exist."""
    defn = routine_def_get(conn, routine_token)
    if defn is None:
        return None
    item = carry_item_get(conn, item_token)
    if item is None:
        return None
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "DELETE FROM routine_prep_item "
            "WHERE routine_def_id=? AND carry_item_id=?;",
            (defn["id"], item["id"]))
        if cur.rowcount != 1:
            conn.rollback()
            return None
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return defn["ulid"], item["ulid"], item["name"]


def routine_prep_list(conn, routine_token):
    """053: a routine's default packing list, item-id ordered.
    Returns [(item_ulid, item_name)], or None when the routine does not
    exist."""
    defn = routine_def_get(conn, routine_token)
    if defn is None:
        return None
    rows = conn.execute(
        "SELECT ci.ulid, ci.name FROM routine_prep_item rpi "
        "JOIN carry_item ci ON ci.id = rpi.carry_item_id "
        "WHERE rpi.routine_def_id=? ORDER BY ci.id;",
        (defn["id"],)).fetchall()
    return [(r[0], r[1]) for r in rows]


def routine_prep_materialize(conn, def_id, eid, owning_agent, now=None):
    """053: copy a routine_def's default packing list onto one freshly
    materialized instance, as live sub_event(kind='prep_item') rows.

    Called by routine_roller.materialize_def right after the instance id is
    known. INSERT OR IGNORE + the partial unique index
    (ux_sub_event_live_prep_item) supply retry idempotence on a re-run of
    the same (event_id, ref) -- deterministic dedup, not a fresh-ulid
    collision concern (the ulid column is never the conflict target)."""
    now = now or now_utc()
    items = conn.execute(
        "SELECT ci.ulid FROM routine_prep_item rpi "
        "JOIN carry_item ci ON ci.id = rpi.carry_item_id "
        "WHERE rpi.routine_def_id=? AND ci.status='active';",
        (def_id,)).fetchall()
    for (item_ulid,) in items:
        conn.execute(
            "INSERT OR IGNORE INTO sub_event "
            "(ulid, event_id, owning_agent, kind, ref, done, tombstone, "
            "created_at) VALUES (?,?,?,'prep_item',?,0,0,?);",
            (new_ulid(), eid, owning_agent, item_ulid, now))


# ── per-event prep: sub_event(kind='prep_item') directly -- NOT sub_add/
# sub_done. Those bubble a CAS version bump + derive_status recompute into
# the parent block, which is the wrong coupling for "packed for this event"
# (see _live_subs's 053 note); a prep-item write only ever touches sub_event.
def _carry_event_resolve(conn, token):
    """(id, ulid) for a block by integer id or ulid. None if absent."""
    if str(token).isdigit():
        return conn.execute(
            "SELECT id, ulid FROM timeblock WHERE id=?;",
            (int(token),)).fetchone()
    return conn.execute(
        "SELECT id, ulid FROM timeblock WHERE ulid=?;",
        (str(token),)).fetchone()


def prep_add(conn, event_token, item_token):
    """053: attach one carry_item as a required prep item on one event.
    Returns (sub_event_id, sub_event_ulid, block_ulid, item_ulid, done), or
    None when the event or the item does not exist. Idempotent: re-attaching
    an already-live (event, item) pair returns the existing row untouched
    (the partial unique index is the source of truth, not a pre-check
    race)."""
    ev = _carry_event_resolve(conn, event_token)
    if ev is None:
        return None
    eid, block_ulid = ev
    item = carry_item_get(conn, item_token)
    if item is None:
        return None
    owning_agent = item["owning_agent"]
    now = now_utc()
    ulid = new_ulid()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT OR IGNORE INTO sub_event "
            "(ulid, event_id, owning_agent, kind, ref, done, tombstone, "
            "created_at) VALUES (?,?,?,'prep_item',?,0,0,?);",
            (ulid, eid, owning_agent, item["ulid"], now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    row = conn.execute(
        "SELECT id, ulid, done FROM sub_event WHERE event_id=? AND ref=? "
        "AND kind='prep_item' AND tombstone=0;",
        (eid, item["ulid"])).fetchone()
    return row[0], row[1], block_ulid, item["ulid"], row[2]


def prep_rm(conn, event_token, item_token):
    """053: tombstone the live prep-item row for (event, item). done!= its
    pre-tombstone value (delete != complete, same 5534 convention).
    Returns (sub_event_id, sub_event_ulid, block_ulid, item_ulid, done), or
    None when the event, the item, or the live link does not exist."""
    ev = _carry_event_resolve(conn, event_token)
    if ev is None:
        return None
    eid, block_ulid = ev
    item = carry_item_get(conn, item_token)
    if item is None:
        return None
    row = conn.execute(
        "SELECT id, ulid, done FROM sub_event WHERE event_id=? AND ref=? "
        "AND kind='prep_item' AND tombstone=0;",
        (eid, item["ulid"])).fetchone()
    if row is None:
        return None
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE sub_event SET tombstone=1, settled_at=? WHERE id=?;",
            (now_utc(), row[0]))
        if cur.rowcount != 1:
            conn.rollback()
            return None
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return row[0], row[1], block_ulid, item["ulid"], row[2]


# The shallowest-satisfying-unit read (design report §6, checked against
# this table shape): a required leaf bubbles up through possessed,
# active-status containers to the highest ancestor still positively
# possessed ('has') -- that ancestor is what displays. Pulling an item out
# (parent_id=NULL) ends its chain at itself, so it reappears on its own.
_PREP_DISPLAY_SQL = """
WITH RECURSIVE
required AS (
  SELECT se.id AS prep_id, se.done AS done, ci.id AS item_id
  FROM sub_event AS se
  JOIN carry_item AS ci ON ci.ulid = se.ref
  WHERE se.event_id = ? AND se.kind = 'prep_item' AND se.tombstone = 0
    AND ci.status = 'active'
),
chain(prep_id, done, item_id, candidate_id, depth, path) AS (
  SELECT prep_id, done, item_id, item_id, 0, printf('/%d/', item_id)
  FROM required
  UNION ALL
  SELECT c.prep_id, c.done, c.item_id, parent.id, c.depth + 1,
         c.path || parent.id || '/'
  FROM chain AS c
  JOIN carry_item AS current ON current.id = c.candidate_id
  JOIN carry_item AS parent ON parent.id = current.parent_id
  WHERE parent.status = 'active' AND parent.possession = 'has'
    AND instr(c.path, printf('/%d/', parent.id)) = 0
),
chosen AS (
  SELECT chain.*,
         row_number() OVER (PARTITION BY prep_id ORDER BY depth DESC)
           AS rank_in_chain
  FROM chain
)
SELECT shown.id, shown.ulid, shown.name,
       MIN(chosen.done) AS done,
       COUNT(*) AS required_count,
       GROUP_CONCAT(chosen.prep_id) AS prep_ids
FROM chosen
JOIN carry_item AS shown ON shown.id = chosen.candidate_id
WHERE chosen.rank_in_chain = 1
GROUP BY shown.id, shown.ulid, shown.name
ORDER BY MIN(chosen.prep_id);
"""


def _prep_display_rows(conn, eid):
    """053: one row per shallowest-satisfying display unit for event `eid`.
    Returns [{'id', 'ulid', 'name', 'done', 'required_count', 'prep_ids'}],
    prep_ids = the underlying live sub_event.id list that display unit
    stands in for (a container row stands in for every leaf packed inside
    it)."""
    out = []
    for (cid, ulid, name, done, required_count, prep_ids) in conn.execute(
            _PREP_DISPLAY_SQL, (eid,)).fetchall():
        out.append({
            "id": cid, "ulid": ulid, "name": name, "done": done,
            "required_count": required_count,
            "prep_ids": [int(p) for p in str(prep_ids).split(",")],
        })
    return out


def prep_list(conn, event_token):
    """053: shallowest-satisfying-unit prep listing for one event.
    Returns [(display_item_ulid, display_name, done, required_count)], or
    None when the event does not exist."""
    ev = _carry_event_resolve(conn, event_token)
    if ev is None:
        return None
    eid, _block_ulid = ev
    return [(r["ulid"], r["name"], r["done"], r["required_count"])
            for r in _prep_display_rows(conn, eid)]


def prep_set(conn, event_token, display_token, value):
    """053: check/uncheck a DISPLAYED prep row. When the display row is a
    container standing in for several packed leaves, every one of those
    leaves' sub_event.done is set together -- one visible checkbox, the
    per-required-item state stays in sub_event (design report §4).
    Returns (display_item_ulid, display_name, done, required_count), or None
    when the event does not exist or `display_token` is not a currently
    displayed prep row for it."""
    value = 1 if value else 0
    ev = _carry_event_resolve(conn, event_token)
    if ev is None:
        return None
    eid, _block_ulid = ev
    display = carry_item_get(conn, display_token)
    if display is None:
        return None
    rows = _prep_display_rows(conn, eid)
    hit = next((r for r in rows if r["id"] == display["id"]), None)
    if hit is None:
        return None
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.executemany(
            "UPDATE sub_event SET done=? WHERE id=?;",
            [(value, pid) for pid in hit["prep_ids"]])
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return hit["ulid"], hit["name"], value, hit["required_count"]


def _routine_validate(cadence, schedule_kind, time_of_day, kind, place_id=None):
    """Shared registration/update validation (spec 1.3/1.4/1.6)."""
    if kind not in ("task", "presence"):
        # v1 scope: appointment routines (hard-blocker materialization) are a
        # follow-up ticket (OQ-12). Schema keeps the column; the verb gates.
        # DGN-842: presence recurring routines are supported (roller already
        # materializes kind='presence'); only appointment stays gated.
        raise ValueError("routine_add: kind=%r is not supported in v1 "
                         "(OQ-12); only kind='task'|'presence'" % kind)
    if kind == "presence" and place_id is None:
        # schema CHECK (routine_def / event): presence rows require a place.
        raise ValueError("routine_add: kind='presence' requires place_id")
    _projection_mod().parse_cadence(cadence)     # closed-grammar validation
    if schedule_kind not in ("timed", "all_day"):
        raise ValueError("routine schedule_kind must be timed|all_day, got %r"
                         % schedule_kind)
    if schedule_kind == "timed" and (
            time_of_day is None or not _TOD_RE.match(time_of_day)):
        raise ValueError("timed routine requires time_of_day HH:MM, got %r"
                         % time_of_day)


RIDE_COLS = ("placement", "fallback_at", "ride_not_before", "ride_prefer")


def _ride_validate(placement, fallback_at, ride_not_before, ride_prefer,
                   kind, place_id, cadence):
    """070: a ride_travel def is a task with no place, a fallback that
    covers every day its cadence fires, and optional not-before / prefer.
    The ride knobs mean nothing without the placement. Returns the
    time_of_day the def stores (the fallback default) or None."""
    rp = _projection_mod()
    if placement is None:
        if fallback_at or ride_not_before or ride_prefer:
            raise ValueError("fallback / not_before / prefer go with "
                             "ride=travel only")
        return None
    if placement != rp.RIDE_TRAVEL:
        raise ValueError("placement must be %r, got %r"
                         % (rp.RIDE_TRAVEL, placement))
    if kind != "task":
        raise ValueError("ride=travel is for a thing to do (kind=task); "
                         "a stay has its own place")
    if place_id is not None:
        raise ValueError("ride=travel routine has no place (it is done "
                         "anywhere -- on the way)")
    rp.parse_fallback(fallback_at)
    missing = rp.fallback_covers(fallback_at, cadence)
    if missing:
        raise ValueError("fallback has no time for %s (add a default "
                         "HH:MM or name those days)" % ",".join(missing))
    if ride_not_before is not None and not _TOD_RE.match(ride_not_before):
        raise ValueError("not_before must be HH:MM, got %r"
                         % ride_not_before)
    if ride_prefer is not None and ride_prefer not in rp.RIDE_PREFER:
        raise ValueError("prefer must be morning|evening, got %r"
                         % ride_prefer)
    return rp.fallback_default(fallback_at)


def _valid_until_for(end_date, today):
    """Spec 1.3 initialization: autonomous -> today+56d; end_date defs carry
    valid_until=end_date for shape consistency (it never binds upper())."""
    if end_date is not None:
        return end_date
    d = datetime.date.fromisoformat(today) + timedelta(days=ROUTINE_VALID_DAYS)
    return d.isoformat()


def routine_add(conn, title, cadence, schedule_kind, time_of_day=None,
                duration_min=None, area_id=None, project_id=None,
                purpose=None, start_date=None, end_date=None, kind="task",
                display_tz="Asia/Seoul", created_by=None, today=None,
                materialize=True, state_conn=None, now=None,
                notify_policy=None, notify_lead_min=None, place_id=None,
                placement=None, fallback_at=None, ride_not_before=None,
                ride_prefer=None, action_kind="check", owning_agent=None,
                until_event=None, until_mode=None, placement_alternatives=None, admit_cmd=None):
    """Register a routine_def + inline first materialization (spec 8.2).
    until_event (+until_mode eve|day): link the end to that event block.
    Returns dict(def_id, ulid, recurrence_id, materialized_dates).
    DGN-273: notify_policy/notify_lead_min live on the def and are stamped
    onto every materialized instance (NULL = 'default' = legacy alerts).
    070: placement='ride_travel' + fallback_at (+ ride_not_before /
    ride_prefer) = the routine rides the day's travel; time_of_day is then
    the fallback default and the day's instant comes from the roller."""
    if action_kind not in ("check", "workout", "retro", "session", "other"):
        raise ValueError("routine action must be check|workout|retro|session|other")
    if admit_cmd is not None:
        import routine_admission
        routine_admission.command(admit_cmd)
    alternatives = _alternatives_validate(
        placement_alternatives, duration_min, kind, place_id, placement,
        fallback_at, ride_not_before, ride_prefer)
    if alternatives is not None:
        schedule_kind, time_of_day = 'timed', _alternatives_tod(alternatives)
    ride_tod = _ride_validate(placement, fallback_at, ride_not_before,
                              ride_prefer, kind, place_id, cadence)
    if ride_tod is not None:
        schedule_kind, time_of_day = "timed", ride_tod
    _routine_validate(cadence, schedule_kind, time_of_day, kind, place_id)
    notify_policy, notify_lead_min = validate_notify_policy(
        notify_policy, notify_lead_min)
    if not title or not str(title).strip():
        raise ValueError("routine_add: title required")
    if created_by is None:
        created_by = _facade_agent()
    today = today or routine_today(display_tz)
    start_date = start_date or today
    valid_until = _valid_until_for(end_date, today)
    ulid = new_ulid()
    rid = "rd:%s" % ulid
    ts = now_utc()
    # v19 one-writer (datamodel #2): routine_def owner is per-row by created_by --
    # 'ag' for ag/notion-import rows (budget/retro/company), the health-domain
    # owner otherwise (_health_agent_write, inside the BEGIN IMMEDIATE below so
    # a handover it performs commits or rolls back with this row). NO default
    # fallback (mis-tag risk).
    conn.execute("BEGIN IMMEDIATE;")
    try:
        if owning_agent is None:
            if action_kind == "workout":
                owning_agent = _health_agent_write(conn)
            elif action_kind != "check":
                owning_agent = _pin_agent()
            else:
                owning_agent = ('ag' if created_by in _ROUTINE_AG_CREATORS
                                else _health_agent_write(conn))
        conn.execute(
            "INSERT INTO routine_def (ulid, recurrence_id, title, kind, "
            "cadence, schedule_kind, time_of_day, duration_min, display_tz, "
            "area_id, project_id, purpose, status, start_date, end_date, "
            "valid_until, rule_effective_from, notify_policy, "
            "notify_lead_min, created_by, created_at, updated_at, place_id, "
            "owning_agent) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'active',?,?,?,?,?,?,?,?,?,?,?);",
            (ulid, rid, title, kind, cadence, schedule_kind, time_of_day,
             duration_min, display_tz, area_id, project_id, purpose,
             start_date, end_date, valid_until, today, notify_policy,
             notify_lead_min, created_by, ts, ts, place_id, owning_agent))
        if alternatives is not None:
            conn.execute("INSERT INTO routine_placement(routine_id,spec) "
                         "SELECT id,? FROM routine_def WHERE ulid=?",
                         (json.dumps(alternatives, sort_keys=True), ulid))
        if admit_cmd is not None:
            conn.execute("UPDATE routine_def SET admit_cmd=? WHERE ulid=?;", (admit_cmd, ulid))
        if action_kind != "check":
            # 088's default is check. Only non-default actions need the new
            # column, so ordinary adds retain pre-088 SDK compatibility.
            conn.execute("UPDATE routine_def SET action_kind=? WHERE ulid=?;",
                         (action_kind, ulid))
        if placement is not None:
            # 070 columns written only for a ride def, so a plain add keeps
            # working on a pre-070 store.
            conn.execute(
                "UPDATE routine_def SET placement=?, fallback_at=?, "
                "ride_not_before=?, ride_prefer=? WHERE ulid=?;",
                (placement, fallback_at, ride_not_before, ride_prefer, ulid))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    if until_event:
        routine_until_set(conn, rid, until_event, until_mode)
    dates = []
    if materialize:
        rr = _roller_mod()
        defn = routine_def_get(conn, ulid)
        dates = rr.materialize_def(conn, state_conn, defn,
                                   today=today, now=now)
    # DGN-623 presence lane: a place-bearing presence def IS a travel anchor.
    # Auto-attach AFTER materialization (the probe needs a live instance),
    # mirroring the appointment lane's auto-attach on appt-add. Silent and
    # best-effort -- _travel_autoattach_def never raises, and place == base
    # (재택) deliberately mints nothing.
    # gym-place-wire (2026-10-09): a place-bound timed TASK (a workout at
    # the gym) is out of the house the same way; _travel_autoattach_def decides.
    travel_attach = None
    if place_id is not None and materialize:
        travel_attach = _travel_autoattach_def(conn, ulid,
                                               state_conn=state_conn)
    result = {"def_id": routine_def_get(conn, ulid)["id"], "ulid": ulid,
              "recurrence_id": rid, "materialized_dates": dates,
              "travel_attach": travel_attach}
    if alternatives is not None:
        result['placement_notes'] = routine_placement_notes(conn, rid)
    return result


# -- deadline-bound routines (owner 2026-10-19) --
# A routine whose purpose is an event ("before the gig") ends at that event.
# The link lives in config routine_until.<rid> = {"event": ulid, "mode":
# "eve"|"day"}; the roller re-derives end_date from the live event, so
# moving the event moves the end. Interactive adds opt in with ask=1;
# programmatic adds retain the open-ended default.
END_ASK_CODE = 4
END_ASK_RELAY = (
    "END_ASK_RELAY Nothing was registered. Say ONLY the question sentence "
    "of the END_ASK line, verbatim, and put the [[OPTIONS: ...]] marker of "
    "its ASK_OPTIONS line on its own line, last. On the tap: until -> re-run "
    "the same routine add with until=<the 4th END_ASK field>; open (keep "
    "going) -> re-run it with open=1; pick (a date) -> ask the date, then "
    "re-run with end=YYYY-MM-DD. If the user's own words already give an "
    "end (before the gig, until year end, just a month) skip this and pass "
    "until=<event words | YYYY-MM-DD | +Nd|+Nw|+Nm> on the first call.")
ROUTINE_CLASH_RELAY = (
    "ROUTINE_CLASH_RELAY Say each ROUTINE_CLASH line once, as written. "
    "The appointment never moves; only the practice did.")
_UNTIL_STOP = set(["routine", "daily", "every", "morning", "evening",
                   "night", "before", "until", "the", "and", "for"])
_ROUTINE_ASK_WORDS_RE = re.compile(r"[0-9A-Za-z\uac00-\ud7a3]{2,}")


def routine_until_set(conn, rid, event_ulid, mode):
    if event_ulid:
        conn.execute(
            "INSERT OR REPLACE INTO config(key, value) VALUES(?, ?);",
            ("routine_until." + rid,
             json.dumps({"event": event_ulid, "mode": mode or "eve"})))
    else:
        conn.execute("DELETE FROM config WHERE key=?;",
                     ("routine_until." + rid,))
    conn.commit()


def _routine_words(*texts):
    out = []
    for t in texts:
        for w in _ROUTINE_ASK_WORDS_RE.findall(t or ""):
            w = w.lower()
            if w not in _UNTIL_STOP and w not in out:
                out.append(w)
    return out


def routine_upcoming_events(conn, today, tz_name="Asia/Seoul"):
    """Live upcoming appointments: [(ulid, title, local date)]."""
    lo = datetime.datetime.strptime(today, "%Y-%m-%d")
    rows = conn.execute(
        "SELECT ulid, title, start_at FROM timeblock WHERE kind='appointment' "
        "AND settled_at IS NULL AND start_at IS NOT NULL "
        "AND block_class IS NULL ORDER BY start_at;").fetchall()
    out = []
    tz = ZoneInfo(tz_name)
    for ulid, title, st in rows:
        d = datetime.datetime.strptime(st, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc).astimezone(tz).date()
        if d >= lo.date():
            out.append((ulid, title, d.isoformat()))
    return out


def routine_event_by_ref(conn, ref, today, tz_name="Asia/Seoul"):
    """ulid, or title words, -> (ulid, title, local date) of the nearest
    upcoming appointment that matches; None if nothing matches."""
    ref = (ref or "").strip()
    evs = routine_upcoming_events(conn, today, tz_name)
    for ev in evs:
        if ev[0] == ref:
            return ev
    words = _routine_words(ref)
    for ev in evs:
        if words and all(w in ev[1].lower() for w in words):
            return ev
    return None


def routine_end_candidate(conn, title, purpose, today, tz_name="Asia/Seoul"):
    """The upcoming appointment this routine relates to by title/purpose
    words (nearest first), else None."""
    words = _routine_words(title, purpose)
    for ev in routine_upcoming_events(conn, today, tz_name):
        ev_words = _routine_words(ev[1])
        if any(w in ev[1].lower() or any(e in w for e in ev_words)
               for w in words):
            return ev
    return None


def _add_months(d, n):
    m = d.month - 1 + n
    y, m = d.year + m // 12, m % 12 + 1
    import calendar
    return datetime.date(y, m, min(d.day, calendar.monthrange(y, m)[1]))


def routine_parse_until(conn, spec, today, tz_name="Asia/Seoul"):
    """until= value -> dict(end_date, event, mode); end_date None = open.
    open|none | YYYY-MM-DD | +Nd|+Nw|+Nm | [day:]<event ref>."""
    spec = (spec or "").strip()
    if spec.lower() in ("open", "none"):
        return {"end_date": None, "event": None, "mode": None}
    if re.match(r"^\d{4}-\d{2}-\d{2}$", spec):
        datetime.date.fromisoformat(spec)
        return {"end_date": spec, "event": None, "mode": None}
    m = re.match(r"^\+(\d+)([dwm])$", spec.lower())
    if m:
        n, u = int(m.group(1)), m.group(2)
        t = datetime.date.fromisoformat(today)
        e = (t + timedelta(days=n) if u == "d" else
             t + timedelta(weeks=n) if u == "w" else _add_months(t, n))
        return {"end_date": e.isoformat(), "event": None, "mode": None}
    mode = "eve"
    if spec.lower().startswith("day:"):
        mode, spec = "day", spec[4:]
    ev = routine_event_by_ref(conn, spec, today, tz_name)
    if ev is None:
        raise ValueError("until: no upcoming appointment matches %r" % spec)
    end = (ev[2] if mode == "day" else
           (datetime.date.fromisoformat(ev[2]) - timedelta(days=1)).isoformat())
    return {"end_date": end, "event": ev[0], "mode": mode}


def routine_end_ask(conn, title, purpose, today, tz_name="Asia/Seoul"):
    """The one-line end question for a routine add that gave no end.
    Returns the END_ASK TSV: END_ASK, kind(event|none), event ulid,
    until value to re-add with, line, buttons."""
    ev = routine_end_candidate(conn, title, purpose, today, tz_name)
    keep = _i18n("routine.end_ask.keep", "Keep going")
    if ev is not None:
        eve = datetime.date.fromisoformat(ev[2]) - timedelta(days=1)
        line = (_i18n("routine.end_ask.event", "{md} {title} until {eve}?")
                .replace("{md}", _rt_md(ev[2])).replace("{title}", ev[1])
                .replace("{eve}", _rt_md(eve.isoformat())))
        choices = [("until", _i18n("routine.end_ask.until", "Until {eve}")
                    .replace("{eve}", _rt_md(eve.isoformat()))),
                   ("open", keep)]
        head = "END_ASK\tevent\t%s\t%s" % (ev[0], ev[0])
    else:
        line = _i18n("routine.end_ask.none", "Does it end?")
        choices = [("open", keep),
                   ("pick", _i18n("routine.end_ask.pick", "Pick a date"))]
        head = "END_ASK\tnone\t\topen"
    ac = _ask_choices()
    return ["%s\t%s\t%s" % (head, line, ac.choices_field(choices)),
            ac.options_line("END_ASK", ev[0] if ev else "none", choices)]


def _rt_md(iso):
    return slash_md(int(iso[5:7]), int(iso[8:10]))


def routine_placement_rule(defn):
    """Plain owner-language echo; the sentence lives in one i18n key."""
    rp = _projection_mod()
    spec = defn['placement_alternatives']
    rules = []
    for alt in spec['alternatives']:
        if alt['type'] == 'window':
            key = ('routine.placement.window_end' if 'end_not_after' in alt
                   else 'routine.placement.window')
            rule = _i18n(key).format(start=alt['start_not_before'], end=alt.get('end_not_after'))
        else:
            rule = _i18n('routine.placement.travel').format(minutes=alt['min_container_minutes'])
        if 'weekdays' in alt:
            days = ', '.join(_i18n('routine.cadence.dow.%d' % rp.DAY_NAMES.index(d))
                             for d in alt['weekdays'])
            rule = _i18n('routine.placement.scope').format(rule=rule, days=days)
        rules.append(rule)
    if 'priority' in spec:
        placements = _i18n('routine.placement.priority').format(
            rules=' -> '.join(rules[i] for i in spec['priority']))
    else:
        placements = _i18n('routine.placement.or').join(rules)
    if 'fallback_at' in spec:
        placements = _i18n('routine.placement.fallback').format(
            rule=placements, time=spec['fallback_at'])
    rule = _i18n('routine.placement.rule').format(
        cadence=rp.describe_cadence(defn['cadence'], _i18n),
        duration=defn['duration_min'] or rp.DEFAULT_DURATION_MIN, placements=placements)
    return _i18n('routine.placement.echo').format(
        rule=rule, title=defn['title'], date=max(defn['start_date'], defn['rule_effective_from']))


def routine_placement_notes(conn, rid=None, date=None, card=False, consume=False):
    """Latest placement result per date, with actionable localized reasons."""
    if not conn.execute("SELECT 1 FROM sqlite_master WHERE name='routine_placement'").fetchone():
        return []
    latest = {}
    for rec, detail, title, tz_name in conn.execute(
            "SELECT l.recurrence_id,l.detail,r.title,r.display_tz FROM roller_log l "
            "JOIN routine_def r ON r.recurrence_id=l.recurrence_id "
            "JOIN routine_placement p ON p.routine_id=r.id "
            "WHERE l.category='placement' AND r.status='active' ORDER BY l.id"):
        kv = dict(t.split('=', 1) for t in detail.split() if '=' in t)
        if rid and rec != rid:
            continue
        if date and (kv['d'] != date if card else kv['d'] < date):
            continue
        if not date and kv['d'] < routine_today(tz_name):
            continue
        latest[(rec, kv['d'])] = (kv, title)
    out = []
    for (rec, d), (kv, title) in sorted(latest.items()):
        reasons = kv.get('reasons', '')
        if not reasons:
            continue
        defn = routine_def_get(conn, rec)
        told = 'routine_placement_told.%s.%s.%s' % (rec, defn['version'], d)
        if consume and not card and _config_stored(conn, told) is not None:
            continue
        # Give one physical reason and one concrete nearby alternative.
        order = ('overlap_fixed', 'insufficient_remaining', 'container_too_short',
                 'container_unavailable', 'interval_elapsed', 'scope_unavailable')
        primary = next((r for r in order if r in reasons.split(',')), reasons.split(',')[0])
        reason = _i18n('routine.placement.' + primary)
        key = ('routine.placement.unavailable' if kv['kind'] == 'unavailable'
               else 'routine.placement.adjusted')
        line = _i18n(key).format(date=d, title=title, reason=reason)
        if kv['kind'] == 'unavailable':
            suggestion = routine_placement_suggestion(conn, defn, d)
            if suggestion:
                line += ' ' + suggestion
        out.append(line)
        if consume and not card:
            _config_put(conn, told, '1')
    if consume and not card:
        conn.commit()
    return out


def routine_placement_suggestion(conn, defn, date):
    """Offer the closest later free full-length slot outside a failed rule."""
    import placement_alternatives as pa
    rr = _roller_mod()
    duration = defn['duration_min'] or _projection_mod().DEFAULT_DURATION_MIN
    tz = ZoneInfo(defn['display_tz'] or 'Asia/Seoul')
    starts = [a['start_not_before'] for a in defn['placement_alternatives']['alternatives']
              if a['type'] == 'window']
    starts += [_day_hm(leg[0], tz) for leg in rr.day_ride_legs(
        conn, date, defn['display_tz'], overlapping=True)]
    if not starts:
        starts = ['00:00']
    spec = {'alternatives': [{'type': 'window', 'start_not_before': min(starts)}]}
    busy = rr._blockers(conn, date, defn['display_tz'], defn['recurrence_id'],
                        with_ids=True, extend_minutes=duration)
    try:
        choice = pa.select(spec, date, duration, defn['display_tz'], busy=busy, now=now_utc())
    except pa.PlacementUnavailable:
        return _i18n('routine.placement.offer_time')
    return _i18n('routine.placement.offer').format(
        date=date, time=_day_hm(choice['start_at'], tz), duration=duration)


def routine_insist(conn, token, date, time, state_conn=None):
    """Honor an explicit owner override for one occurrence, keeping its duration.

    The exception marker is atomic with creation. Normal rule materialization
    and collision handling preserve the owner's chosen seat on later passes.
    """
    defn = routine_def_get(conn, token)
    rp = _projection_mod()
    if (defn is None or defn['status'] != 'active' or defn['kind'] != 'task'
            or not rp.is_alternatives(defn)):
        raise ValueError(_i18n('routine.placement.insist_target'))
    import placement_alternatives as pa
    try:
        pa._time(time)
        day = datetime.date.fromisoformat(date)
    except (ValueError, TypeError):
        raise ValueError(_i18n('routine.placement.invalid_time')) from None
    if not list(rp.occurrence_dates(defn, date, date)):
        raise ValueError(_i18n('routine.placement.insist_date'))
    rr = _roller_mod()
    duration = defn['duration_min'] or rp.DEFAULT_DURATION_MIN
    tz = ZoneInfo(defn['display_tz'] or 'Asia/Seoul')
    start = datetime.datetime.combine(day, datetime.time.fromisoformat(time), tz)
    sa = start.astimezone(timezone.utc).strftime(pa.FMT)
    ea = (start + timedelta(minutes=duration)).astimezone(timezone.utc).strftime(pa.FMT)
    row = _travel_row(conn, 'SELECT * FROM timeblock WHERE recurrence_id=? '
                      'AND rec_date=? AND settled_at IS NULL', (defn['recurrence_id'], date))
    if row:
        result = routine_exception(conn, row['ulid'], schedule=('timed', sa, ea),
                                   state_conn=state_conn)
        if result != 'applied':
            raise ValueError(_i18n('routine.placement.insist_target'))
        ulid = row['ulid']
    else:
        if rr.occupied(conn, defn['recurrence_id'], date):
            raise ValueError(_i18n('routine.placement.insist_settled'))
        def stamp(db, eid):
            db.executemany('INSERT OR REPLACE INTO block_attr '
                           '(block_id,attr_token,value,source) VALUES(?,?,?,?)',
                           [(eid, 'rec_exception', '1', 'routine'),
                            (eid, 'action_kind', defn.get('action_kind') or 'check', 'routine')])
        eid = timeblock_add(conn, 'task', defn['title'], 'timed', sa, ea,
            created_by=_facade_agent(), owning_agent=defn['owning_agent'],
            completion_rule='manual', area_id=defn['area_id'],
            project_id=defn['project_id'], display_tz=defn['display_tz'],
            recurrence_id=defn['recurrence_id'], rec_date=date, is_routine=1,
            notify_policy=defn.get('notify_policy'), notify_lead_min=defn.get('notify_lead_min'),
            post_insert=stamp)
        ulid = conn.execute('SELECT ulid FROM timeblock WHERE id=?', (eid,)).fetchone()[0]
        routine_prep_materialize(conn, defn['id'], eid, defn['owning_agent'])
    own_state = state_conn is None
    if own_state:
        state_conn = rr.open_state_db()
    try:
        rr.outbox_enqueue(state_conn, ulid)
    finally:
        if own_state and state_conn is not None:
            state_conn.close()
    rr.placement_note(conn, defn, date, 'owner', [])
    return {'ulid': ulid, 'reply': _i18n('routine.placement.insisted').format(
        date=date, time=time, duration=duration, title=defn['title'])}


def _print_placement(conn, token):
    defn = routine_def_get(conn, token)
    if defn is None or not _projection_mod().is_alternatives(defn):
        return
    print('PLACEMENT_RULE\t' + routine_placement_rule(defn))
    _print_ride_days(conn, defn['ulid'])
    for line in routine_placement_notes(conn, defn['recurrence_id'], consume=True):
        print('PLACEMENT_NOTE\t' + line)


def routine_clash_notes(conn, date=None, card=False):
    """One line per not-yet-told clash move/skip (all dates >= date when
    given), then marked told. card=True is a read-only, exact-day view,
    independent of whether an add reply already told the owner."""
    rows = conn.execute(
        "SELECT l.id, l.category, l.recurrence_id, l.detail, r.title "
        "FROM roller_log l JOIN routine_def r ON r.recurrence_id=l.recurrence_id "
        "WHERE l.category IN ('clash_moved','clash_skip') ORDER BY l.id;"
    ).fetchall()
    out = []
    if card:
        # A day may first move and later be skipped: show its latest outcome.
        latest = {}
        for row in rows:
            kv = dict(t.split("=", 1) for t in row[3].split() if "=" in t)
            latest[(row[2], kv.get("d"))] = row
        rows = list(latest.values())
    for lid, cat, rid, detail, title in rows:
        key = "routine_clash_told.%d" % lid
        if not card and _config_stored(conn, key) is not None:
            continue
        kv = dict(t.split("=", 1) for t in detail.split() if "=" in t)
        d = kv.get("d", "")
        if date and (d != date if card else d < date):
            continue
        if card:
            live = conn.execute(
                "SELECT start_at, display_tz FROM timeblock WHERE recurrence_id=? "
                "AND rec_date=? AND settled_at IS NULL;", (rid, d)).fetchone()
            if cat == "clash_skip" and live:
                continue          # the appointment went away; the day returned
            if cat == "clash_moved" and (not live or _day_hm(
                    live[0], _day_tz(live[1], None)) != kv.get("to")):
                continue          # a later owner edit superseded the move
        tpl = (_i18n("routine.clash.moved",
                     "{md} {title}: moved {from} -> {to} (appointment)")
               if cat == "clash_moved" else
               _i18n("routine.clash.skip",
                     "{md} {title}: skipped that day (appointment)"))
        out.append(tpl.replace("{md}", _rt_md(d)).replace("{title}", title)
                   .replace("{from}", kv.get("from", ""))
                   .replace("{to}", kv.get("to", "")))
        if not card:
            conn.execute("INSERT OR REPLACE INTO config(key, value) VALUES(?, '1');",
                         (key,))
    if not card:
        conn.commit()
    return out + routine_placement_notes(conn, date=date, card=card, consume=True)


def routine_retire_check(conn, rid, today):
    """After an owner calendar delete: if the routine has no live future
    occurrence left, mark ONE retire question pending (asked once)."""
    d = conn.execute("SELECT ulid, title, status FROM routine_def "
                     "WHERE recurrence_id=?;", (rid,)).fetchone()
    if d is None or d[2] != "active":
        return None
    n = conn.execute(
        "SELECT COUNT(*) FROM timeblock WHERE recurrence_id=? AND rec_date>=? "
        "AND settled_at IS NULL;", (rid, today)).fetchone()[0]
    key = "routine_retire_ask." + rid
    if n or _config_stored(conn, key) is not None:
        return None
    conn.execute("INSERT OR REPLACE INTO config(key, value) VALUES(?, "
                 "'pending');", (key,))
    conn.commit()
    return d[0]


def routine_retire_asks(conn, consume=True):
    """Pending retire questions -> lines, then marked asked."""
    out = []
    for key, in conn.execute("SELECT key FROM config WHERE key LIKE "
                             "'routine_retire_ask.%' AND value='pending';"
                             ).fetchall():
        rid = key.split(".", 1)[1]
        d = conn.execute("SELECT ulid, title FROM routine_def WHERE "
                         "recurrence_id=? AND status='active';", (rid,)).fetchone()
        if d:
            choices = [("retire", _i18n("routine.retire_ask.retire", "Retire")),
                       ("keep", _i18n("routine.retire_ask.keep", "Keep"))]
            ac = _ask_choices()
            out.append("RETIRE_ASK\t%s\t%s\t%s" % (d[0], _i18n(
                "routine.retire_ask", "Retire {title}?").replace(
                    "{title}", d[1]), ac.choices_field(choices)))
            out.append(ac.options_line("RETIRE_ASK", d[0], choices))
        if consume:
            conn.execute("UPDATE config SET value='asked' WHERE key=?;", (key,))
    if consume:
        conn.commit()
    return out


def _emit_clash_asks(conn, date=None, anchor_id=None):
    import owner_clash
    proposals = owner_clash.pending(sys.modules[__name__], conn, date=date, anchor_id=anchor_id)
    for proposal in proposals:
        print("\n".join(owner_clash.lines(sys.modules[__name__], conn, proposal)))
    if proposals:
        print(_ask_choices().RELAY)


def routine_day_notes(conn, date, now=None):
    """Card annotations plus pending questions from retire-asks.
    Expire elapsed clash questions without acknowledging an owner choice.
    """
    try:
        lines = routine_clash_notes(conn, date, card=True)
        import owner_clash
        for proposal in owner_clash.pending(sys.modules[__name__], conn, date=date, now=now):
            ask = owner_clash.lines(sys.modules[__name__], conn, proposal)
            lines += [ask[0].split("\t")[2], ask[1].split("\t")[3]]
        for line in routine_retire_asks(conn, consume=False):
            fields = line.split("\t")
            if fields[0] in ("RETIRE_ASK", "ASK_OPTIONS"):
                lines.append(fields[2] if fields[0] == "RETIRE_ASK" else fields[3])
        return lines
    except sqlite3.OperationalError:
        return []                 # pre-routine stores keep their day surface



_ROUTINE_UPD_COLS = ("title", "cadence", "schedule_kind", "time_of_day",
                     "duration_min", "area_id", "project_id", "purpose",
                     "end_date", "notify_policy", "notify_lead_min",
                     "place_id", "action_kind", "placement_alternatives", "admit_cmd") + RIDE_COLS


def _routine_place_arg(conn, value):
    """place=<name|id> for routine add / update -> place_id (None = empty).
    A bare number is an id and must name a live place (it never mints a
    place called "4"); anything else goes through place_upsert -- the same
    resolver routine add always used, so ABSENT mints and a near match
    raises NearMatchError for the caller's NEAR_MATCH block."""
    v = str(value or "").strip()
    if not v:
        return None
    if v.isdigit():
        p = travel_place_get(conn, int(v))
        if p is None or p.get("status", "active") != "active":
            raise ValueError("place id %s not found" % v)
        return p["id"]
    pid, _ = place_upsert(conn, v)
    return pid


def _routine_live_future_rows(conn, defn, floor, now):
    """Unsettled instances of the def that have not started yet, from floor
    on -- owner-edited days (rec_exception / version>0) included."""
    old = conn.row_factory
    conn.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in conn.execute(
            "SELECT id, ulid, place_id FROM timeblock WHERE recurrence_id=? "
            "AND settled_at IS NULL AND block_class IS NULL "
            "AND rec_date >= ? AND (start_at IS NULL OR start_at > ?);",
            (defn["recurrence_id"], floor, now))]
    finally:
        conn.row_factory = old


def _routine_place_stamp(conn, state_conn, defn, floor, now):
    """Put the def's place on every live future instance (gym-place-wire
    2026-10-09). In place, no version bump: where the owner is is not a
    time edit, so a day the owner moved keeps its time AND gets the place,
    and the roller still owns the rows it made. Past rows are lifelog."""
    pid = defn.get("place_id")
    n = 0
    for row in _routine_live_future_rows(conn, defn, floor, now):
        if row["place_id"] == pid:
            continue
        conn.execute("BEGIN IMMEDIATE;")
        try:
            k = _tb_update(conn, row["id"], {"place_id": pid},
                           where_extra=" AND settled_at IS NULL")
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        if k == 1:
            _roller_mod().outbox_enqueue(state_conn, row["ulid"])
            n += 1
    return n


def _routine_place_travel_sync(conn, state_conn, defn, now=None):
    """After a def's place changed: its travel rule follows. No place / home
    -> the rule (if any) retires (at home: no move, no prep). A rule already
    there moves to the new place and re-derives; none -> auto-attach, forced,
    because setting a place IS the owner asking for the travel. Returns the
    TRAVEL_ATTACH_* tuple (status, origin, dest)."""
    existing = _travel_row(
        conn, "SELECT * FROM travel_rule WHERE anchor_type='def' "
        "AND anchor_ulid=? AND status != 'retired';", (defn["ulid"],))
    pid = defn.get("place_id")
    if pid is None or pid == _travel_base_place_id(conn):
        if existing is not None:
            travel_rule_retire(conn, existing["id"], state_conn=state_conn,
                               now=now)
        return TRAVEL_ATTACH_NONE, "", (_place_name(conn, pid)
                                        if pid is not None else "")
    if existing is not None:
        if existing["place_id"] != pid:
            travel_rule_upd(conn, existing["id"], {"place_id": pid},
                            state_conn=state_conn, now=now)
        else:
            travel_refresh_rule(conn, state_conn,
                                travel_rule_get(conn, existing["id"]),
                                now=now)
    return _travel_autoattach_def(conn, defn["ulid"], state_conn=state_conn,
                                  force=existing is None)


def routine_update(conn, def_token, changes, effective_from=None,
                   today=None, state_conn=None, now=None):
    """Mode B rule change (spec 4.2) -- convergent, not atomic:
      1. single txn: CAS bump def (version, updated_at) + apply changes +
         persist rule_effective_from (F-A).
      2. cancel-set regen (row-per-txn, roller regen path).
      3. materialize per new rule over [max(today, effective_from), upper].
    Returns dict(result, cancelled, deleted, materialized_dates)."""
    defn = routine_def_get(conn, def_token)
    if defn is None:
        return {"result": "not_found"}
    notify_only = bool(changes) and set(changes) <= {"notify_policy", "notify_lead_min"}
    today = today or routine_today(defn["display_tz"])
    notify_floor = max(today, effective_from or today)
    effective_from = (defn["rule_effective_from"] if notify_only
                      else effective_from or today)
    merged = dict(defn)
    for col in changes:
        if col not in _ROUTINE_UPD_COLS:
            raise ValueError("routine_update: column %r not updatable "
                             "(allowed: %s)" % (col, list(_ROUTINE_UPD_COLS)))
        merged[col] = changes[col]
    if 'admit_cmd' in changes:
        import routine_admission
        routine_admission.command(changes['admit_cmd'])
    if changes.get("place_id") is not None:
        _p = travel_place_get(conn, int(changes["place_id"]))
        if _p is None or _p.get("status", "active") != "active":
            raise ValueError("routine_update: place %r not found"
                             % changes["place_id"])
    place_changed = ("place_id" in changes
                     and changes["place_id"] != defn.get("place_id"))
    if (not notify_only and changes.get('placement_alternatives') is None
            and (any(c in changes for c in RIDE_COLS)
                 or merged.get("placement") is not None)):
        # 070: ride=off clears the knobs with it; a ride def's time_of_day
        # follows its fallback (the roller places the day, not this).
        if merged.get("placement") is None:
            for c in RIDE_COLS:
                if merged.get(c) is not None:
                    changes = dict(changes, **{c: None})
                    merged[c] = None
        ride_tod = _ride_validate(
            merged.get("placement"), merged.get("fallback_at"),
            merged.get("ride_not_before"), merged.get("ride_prefer"),
            merged["kind"], merged.get("place_id"), merged["cadence"])
        if ride_tod is not None:
            changes = dict(changes, schedule_kind="timed",
                           time_of_day=ride_tod)
            merged.update(schedule_kind="timed", time_of_day=ride_tod)
    if merged.get('placement_alternatives') is not None and any(
            k in changes for k in ('time_of_day', 'schedule_kind')):
        raise ValueError(_i18n('routine.placement.invalid'))
    # The new aggregate replaces legacy fields only on explicit opt-in.
    if changes.get('placement_alternatives') is not None:
        for c in RIDE_COLS:
            if c not in changes:
                changes = dict(changes, **{c: None})
                merged[c] = None
    alternatives = _alternatives_validate(
        merged.get('placement_alternatives'), merged['duration_min'],
        merged['kind'], merged.get('place_id'), merged.get('placement'),
        merged.get('fallback_at'), merged.get('ride_not_before'), merged.get('ride_prefer'))
    if alternatives is not None and not notify_only:
        changes = dict(changes, schedule_kind='timed', time_of_day=_alternatives_tod(alternatives))
        merged.update(schedule_kind='timed', time_of_day=_alternatives_tod(alternatives))
    changes = dict(changes)
    alternatives_changed = 'placement_alternatives' in changes
    changes.pop('placement_alternatives', None)
    _routine_validate(merged["cadence"], merged["schedule_kind"],
                      merged["time_of_day"], merged["kind"],
                      merged.get("place_id"))
    # DGN-273: notify pair must stay coherent after the merge (CLI always
    # writes the pair together; API callers get the same guarantee here).
    validate_notify_policy(merged.get("notify_policy"),
                           merged.get("notify_lead_min"))
    if merged.get("action_kind", "check") not in ("check", "workout", "retro", "session", "other"):
        raise ValueError("invalid routine action_kind")
    # end_date change re-derives valid_until per the 1.3 initialization rule.
    new_valid_until = (_valid_until_for(merged["end_date"], today)
                       if "end_date" in changes else defn["valid_until"])
    ts = now_utc()
    sets = ", ".join("%s=?" % c for c in sorted(changes.keys()))
    params = [changes[c] for c in sorted(changes.keys())]
    conn.execute("BEGIN IMMEDIATE;")
    try:
        if alternatives_changed:
            conn.execute("DELETE FROM routine_placement WHERE routine_id=?", (defn['id'],))
        cur = conn.execute(
            "UPDATE routine_def SET " + (sets + ", " if sets else "") +
            "valid_until=?, rule_effective_from=?, version=version+1, "
            "updated_at=? WHERE id=? AND version=?;",
            params + [new_valid_until, effective_from, ts,
                      defn["id"], defn["version"]])
        if cur.rowcount != 1:
            conn.rollback()
            return {"result": "cas_fail"}
        if alternatives_changed and alternatives is not None:
            conn.execute("INSERT INTO routine_placement(routine_id,spec) VALUES(?,?)",
                         (defn['id'], json.dumps(alternatives, sort_keys=True)))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    if notify_only:
        # Notification metadata is not a new recurrence rule. Keep today's
        # elapsed occurrences and any missing seats intact; update only live
        # future rows in place, as place-only stamping does (no time edit).
        rr = _roller_mod()
        if state_conn is None:
            state_conn = rr.open_state_db()
        stamp_now = now or now_utc()
        policy = {k: merged.get(k) for k in ("notify_policy", "notify_lead_min")}
        for row in _routine_live_future_rows(conn, defn, notify_floor, stamp_now):
            conn.execute("BEGIN IMMEDIATE;")
            try:
                n = _tb_update(conn, row["id"], policy,
                               where_extra=" AND settled_at IS NULL AND "
                                           "(start_at IS NULL OR start_at > ?)",
                               params_extra=(stamp_now,))
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            if n:
                rr.outbox_enqueue(state_conn, row["ulid"])
        return {"result": "applied", "cancelled": 0, "deleted": 0,
                "materialized_dates": [], "stale_exception_dates": [],
                "travel_attach": None}
    # steps 2+3: best-effort catch-up; nightly conformance converges (2.4).
    rr = _roller_mod()
    fresh = routine_def_get(conn, def_token)
    if not alternatives_changed and set(changes) <= {"place_id"}:
        # a place-only change is not a rule change: the rows keep their
        # ulid / time (no GCal tombstone + re-create churn) and take the
        # place in place below.
        cancelled = deleted = 0
    else:
        cancelled, deleted = rr.cancel_set_regen(conn, state_conn, fresh,
                                                 effective_from, now=now)
    dates = rr.materialize_def(conn, state_conn, fresh, today=today, now=now,
                               floor_date=max(today, effective_from))
    travel_attach = None
    if place_changed:
        if state_conn is None:
            state_conn = rr.open_state_db()
        _routine_place_stamp(conn, state_conn, fresh,
                             max(today, effective_from), now or now_utc())
        travel_attach = _routine_place_travel_sync(conn, state_conn, fresh,
                                                   now=now)
    # 2026-08-24 edit-preservation: the days the owner had hand-set are NOT
    # rewritten by this rule change (rec_exception=1 is out of every regen
    # predicate) -- but the caller must be able to SAY so, otherwise the new
    # rule looks like it silently failed on those days. Report, do not act.
    stale = rr.stale_exceptions(conn, fresh, max(today, effective_from),
                                rr.upper(fresh, today))
    result = {"result": "applied", "cancelled": cancelled, "deleted": deleted,
              "materialized_dates": dates, "stale_exception_dates": stale,
              "travel_attach": travel_attach}
    if alternatives is not None:
        result['placement_notes'] = routine_placement_notes(conn, fresh['recurrence_id'])
    return result


def routine_pause(conn, def_token, today=None, state_conn=None, now=None):
    """pause = cancel-set treatment + status='paused' (spec 4.2)."""
    defn = routine_def_get(conn, def_token)
    if defn is None:
        return {"result": "not_found"}
    today = today or routine_today(defn["display_tz"])
    ts = now_utc()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE routine_def SET status='paused', version=version+1, "
            "updated_at=? WHERE id=? AND version=? AND status='active';",
            (ts, defn["id"], defn["version"]))
        if cur.rowcount != 1:
            conn.rollback()
            return {"result": "cas_fail"}
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    rr = _roller_mod()
    cancelled, deleted = rr.cancel_set_regen(conn, state_conn, defn,
                                             today, now=now)
    return {"result": "applied", "cancelled": cancelled, "deleted": deleted}


def routine_resume(conn, def_token, today=None, state_conn=None, now=None):
    """resume: status='active' (+ autonomous valid_until reset, M7) + inline
    materialize. end_date defs skip the valid_until reset (unused, 2.2).
    pause/resume never touch rule_effective_from (spec 4.2)."""
    defn = routine_def_get(conn, def_token)
    if defn is None:
        return {"result": "not_found"}
    today = today or routine_today(defn["display_tz"])
    ts = now_utc()
    new_valid = (_valid_until_for(None, today)
                 if defn["end_date"] is None else defn["valid_until"])
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE routine_def SET status='active', valid_until=?, "
            "version=version+1, updated_at=? "
            "WHERE id=? AND version=? AND status='paused';",
            (new_valid, ts, defn["id"], defn["version"]))
        if cur.rowcount != 1:
            conn.rollback()
            return {"result": "cas_fail"}
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    rr = _roller_mod()
    fresh = routine_def_get(conn, def_token)
    dates = rr.materialize_def(conn, state_conn, fresh, today=today, now=now)
    return {"result": "applied", "materialized_dates": dates}


def routine_retire(conn, def_token, today=None, state_conn=None, now=None,
                   by="routine-retire"):
    """Group cleanup (spec 5.4): cancel ALL future unsettled instances
    (exceptions INCLUDED -- retire means stop) + def.status='retired'
    (row preserved). Past/settled rows = lifelog, untouchable."""
    defn = routine_def_get(conn, def_token)
    if defn is None:
        return {"result": "not_found"}
    today = today or routine_today(defn["display_tz"])
    ts = now_utc()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE routine_def SET status='retired', version=version+1, "
            "updated_at=? WHERE id=? AND version=? AND status != 'retired';",
            (ts, defn["id"], defn["version"]))
        if cur.rowcount != 1:
            conn.rollback()
            return {"result": "cas_fail"}
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    rr = _roller_mod()
    n = rr.retire_group_cancel(conn, state_conn, defn, today, now=now, by=by)
    return {"result": "applied", "cancelled": n}


def _is_presence_row(conn, event_ulid):
    row = conn.execute("SELECT kind FROM timeblock WHERE ulid=?;",
                       (event_ulid,)).fetchone()
    return row is not None and row[0] == "presence"


def _presence_exception_apply(conn, event_ulid, new_schedule_kind,
                              new_start, new_end):
    """Owner's this-day-only edit on a PRESENCE recurrence instance
    (2026-08-24 edit-preservation fix). Delegates to presence_move so the
    one-presence-at-a-time guard still holds, and stamps rec_exception=1 in
    the same CAS txn when the row belongs to a recurrence.

    Returns a bypass_schedule_apply-compatible result string so
    routine_exception's caller contract is unchanged:
    'applied' | 'not_found' | 'cas_fail' | 'overlap_reject'
    | 'rejected_untimed'.

    M-C parity: a recurrence instance may never become untimed (identity /
    lapse would break) -- and a presence row cannot be untimed at all
    (schema CHECK), so untimed is terminal-rejected here too."""
    if new_schedule_kind == "untimed":
        return "rejected_untimed"
    # local retry budget: _UPD_RETRY_MAX lives in the CLI section further
    # down, so it is not referenced here (SDK section must not depend on
    # CLI-section ordering).
    for _attempt in range(3):
        row = conn.execute(
            "SELECT id, version, recurrence_id FROM timeblock WHERE ulid=?;",
            (event_ulid,)).fetchone()
        if row is None:
            return "not_found"
        eid, version, rid = row
        res = presence_move(conn, eid, version, new_start, new_end,
                            stamp_exception=rid is not None)
        if res == MutationResult.APPLIED:
            return "applied"
        if res == MutationResult.NOT_FOUND:
            return "not_found"
        if res == MutationResult.OVERLAP_REJECT:
            return "overlap_reject"
        # CAS_FAIL -> re-read the version and retry.
    return "cas_fail"


# Terminal (non-retryable) classifications of an inbound presence edit. The
# mirror maps these to "refuse + restore the calendar + TELL the owner";
# anything else (cas_fail / not_found) is a plain retryable failure.
PRESENCE_INBOUND_TERMINAL = (
    "overlap_reject", "rejected_untimed", "rejected_kind_change",
    "rejected_unbounded", "rejected_not_presence", "rejected_settled",
)


def presence_inbound_apply(conn, ulid, new_schedule_kind, new_start, new_end):
    """INBOUND (Google Calendar) schedule edit on a PRESENCE row
    (2026-08-25 inbound edit-preservation fix).

    Why this exists. bypass_schedule_apply is the inbound lane and refuses
    presence on purpose (`rejected_presence`): it skips the FG-1 overlap
    predicate, and presence carries a one-presence-at-a-time invariant that a
    blind calendar drag must not be allowed to break. The 2026-08-24 fix gave
    the CHAT lane a safe path (routine_exception -> _presence_exception_apply
    -> presence_move). The owner does not use the chat lane -- he drags the
    block in Google Calendar -- so the inbound lane needs the SAME treatment,
    not a weaker one.

    So: no bypass. The edit goes through presence_move, the presence-SCOPED
    CAS verb, which keeps the invariant (its NOT-EXISTS probe is restricted to
    kind='presence' rows, so a task/appointment sharing the wall clock can
    never refuse it) and stamps rec_exception=1 in the same txn when the row
    belongs to a recurrence -- the owner's drag on his work block means "just
    change today", exactly as the chat lane's `routine exception` does, and
    that bit is what makes it survive the nightly roller.

    Shape guards, all terminal (row unchanged, caller notifies):
      - unbounded instants: presence spans are CHECK-pinned bounded.
      - untimed: M-C parity (a recurrence instance may never go untimed) and
        presence cannot be untimed at all.
      - schedule_kind change (timed <-> all_day): presence_move moves
        instants only; a shape transition is not expressible here.
      - SETTLED row: the inbound lane matches on ulid ALONE (no
        settled_at filter), so a Google item can resolve to a cancelled /
        abandoned row -- e.g. a regeneration tombstone whose surface object
        still exists. presence_move has no settled guard of its own, so
        without this check an inbound edit would rewrite a dead row's
        instants and stamp rec_exception=1 on it. Refuse; the canonical
        re-push is what reconciles the stale surface object.

    Returns (result, overlap_warning) -- the SAME tuple contract as
    bypass_schedule_apply so the mirror's _run_verb_tuple / VERB_OK
    classification is unchanged. The warning is always None on purpose: the
    generic _mirror_overlap_post_check probes the FG-1 slot predicate, under
    which a presence block legitimately co-exists with tasks/appointments --
    running it here would fire a false overlap notice on every accepted drag.
    presence_move's own predicate already guarantees the only overlap that
    matters (presence vs presence) cannot survive an APPLIED result."""
    if new_start is None or new_end is None:
        return "rejected_unbounded", None
    canonical(new_start)
    canonical(new_end)
    validate_interval(new_start, new_end)
    row = conn.execute(
        "SELECT kind, schedule_kind, start_at, end_at, settled_at "
        "FROM timeblock WHERE ulid=?;", (ulid,)).fetchone()
    if row is None:
        return "not_found", None
    cur_kind, cur_sk, cur_start, cur_end = row[0], row[1], row[2], row[3]
    if cur_kind != "presence":
        return "rejected_not_presence", None
    if row[4] is not None:
        return "rejected_settled", None          # never write a dead row
    if new_schedule_kind == "untimed":
        return "rejected_untimed", None
    if new_schedule_kind != cur_sk:
        return "rejected_kind_change", None
    if (cur_start, cur_end) == (new_start, new_end):
        return "noop", None                      # nothing to move, no stamp
    res = _presence_exception_apply(conn, ulid, new_schedule_kind,
                                    new_start, new_end)
    # dec-021 (OQ-8) parity with bypass_schedule_apply: an APPLIED schedule
    # change on an anchor supersedes that occurrence's travel skips.
    if res == "applied" and _travel_schema_ready(conn):
        _travel_clear_skips(conn, ulid)
        _travel_clear_pins(conn, ulid)              # D3-1: same supersession
    return res, None


def routine_exception(conn, event_ulid, schedule=None, content=None,
                      state_conn=None):
    """Mode A this-instance-only edit (spec 4.1) -- thin wrapper.
    schedule = (new_schedule_kind, new_start, new_end) -> delegates to
    bypass_schedule_apply (which owns the rec_exception stamp, M-B).
    content = {title/note} -> timeblock_set_meta path (NO stamp; version bump
    already makes the row regen-untouchable). Returns result string.

    DGN-274 (V8):
      - travel-block gate (4.4, F-B second-write-path seal): blocks carry
        recurrence_id NULL so they are never a normal target, but a direct
        ulid hit is possible -- explicit loud gate; time adjustment goes
        through travel-move.
      - inline follow (3.2, F-B): routine_exception passes through bypass
        (no slot predicate -> no self-deadlock -> no pre-clean needed);
        instead, a successful schedule commit runs travel_refresh(instance)
        in the SAME process (occurrence time-move is the primary use case;
        the block must not sit at the old position until nightly)."""
    if schedule is None and not content:
        raise ValueError("routine_exception: nothing to change")
    travel_ready = _travel_schema_ready(conn)   # M2: v7 clean degrade
    if travel_ready:
        brow = conn.execute(
            "SELECT block_class FROM timeblock WHERE ulid=?;",
            (event_ulid,)).fetchone()
        if brow is not None and brow[0] == "travel":
            return "rejected_travel_block"    # loud gate; use travel-move
    res = "noop"
    schedule_applied = False
    if schedule is not None:
        sk, ns, ne = schedule
        if _is_presence_row(conn, event_ulid):
            # 2026-08-24 edit-preservation fix. bypass_schedule_apply is the
            # INBOUND mirror lane and refuses presence on purpose: it skips
            # the overlap predicate, and presence carries a one-at-a-time
            # invariant that a blind GCal drag must not be able to break.
            # But the owner's deliberate "just move today's block" is a
            # different lane, and it had NO working verb at all -- the
            # documented `routine exception` returned 'rejected_presence'
            # and changed nothing, which is why an edited work day appeared
            # to snap back to the template. Route it through the
            # presence-scoped CAS verb instead, which keeps the invariant
            # AND stamps rec_exception=1 in the same txn.
            res = _presence_exception_apply(conn, event_ulid, sk, ns, ne)
        else:
            res, _warn = bypass_schedule_apply(conn, event_ulid, sk, ns, ne)
        if res != "applied":
            return res
        schedule_applied = True
    if content:
        found = _ulid_lookup(conn, event_ulid)
        if found is None:
            return "not_found"
        eid, version = found
        mres = timeblock_set_meta(conn, eid, version, dict(content))
        res = mres if isinstance(mres, str) else "applied"
    if schedule_applied and travel_ready:
        travel_refresh(conn, state_conn, event_ulid)   # F-B inline follow
    return res


# ── health aggregation (spec 6.1 -- structural tombstones in NO bucket) ────
ANOMALY_RATE_MIN_ELAPSED = 4     # last-14d elapsed occurrences (OQ-1)
ANOMALY_RATE_THRESHOLD = 0.30
ANOMALY_STREAK_D = 5
ANOMALY_STREAK_WI = 3

STRUCTURAL_SETTLERS = ("rule-regen", "routine-retire")


def _def_streak_threshold(cadence):
    return ANOMALY_STREAK_D if cadence == "D" else ANOMALY_STREAK_WI


def routine_health(conn, window=28, as_of=None, include_retired=False,
                   owning_agent=None):
    """Per-def health JSON rows (spec 6.1). Pure read.
    scheduled = COUNT(DISTINCT rec_date) of elapsed instances in the window,
    structural tombstones (settled_by rule-regen/routine-retire) excluded
    from EVERY bucket (M-E). rate = done/scheduled.

    owning_agent: restrict the def population to that owner. Instances can
    share ONE routine_def table, so an unscoped read lets either instance
    judge -- and push on -- the other instance's routines (measured live: a
    health-domain instance pushed an anomaly about the life instance's
    presence routine). Judgment is per-owner; MATERIALIZATION deliberately
    is not (P1-A: shared routines are born from one table on purpose, so
    either roller keeps the other's calendar filled).

    None = every owner. That is the historical behaviour and stays the
    default so no existing caller changes meaning -- the CLI `health`
    verb is an operator debug surface and keeps the whole-table view."""
    as_of = as_of or routine_today()
    lo = (datetime.date.fromisoformat(as_of)
          - timedelta(days=int(window))).isoformat()
    old_factory = conn.row_factory
    conn.row_factory = sqlite3.Row
    try:
        q = "SELECT * FROM routine_def"
        where, params = [], []
        if not include_retired:
            where.append(LIVE_ROUTINE_DEF_SQL)
        if owning_agent is not None:
            # bound parameter, not interpolation: the owner token reaches
            # here from instance config, which is not this module's to trust.
            where.append("owning_agent = ?")
            params.append(owning_agent)
        if where:
            q += " WHERE " + " AND ".join(where)
        defs = [dict(r) for r in conn.execute(q + " ORDER BY id;", params)]
        out = []
        for defn in defs:
            rid = defn["recurrence_id"]
            rows = [dict(r) for r in conn.execute(
                "SELECT rec_date, status, settled_at, settled_by, "
                "rec_exception, settled_outcome FROM timeblock "
                "WHERE recurrence_id=? "
                "AND rec_date IS NOT NULL AND rec_date <= ? "
                "AND NOT (settled_outcome IS 'abandoned' AND settled_by IN "
                "('rule-regen','routine-retire')) ORDER BY rec_date;",
                (rid, as_of))]
            # settle-first: "missed" now means a CONFIRMED lapse -- the
            # roller looked at a due instance and settled it abandoned.
            # An instance that was simply never resolved is a different
            # epistemic state ("no stamp", not "did not do it") and gets
            # its own bucket. Collapsing the two is what pushed a false
            # "missed N times running" at the user while the domain record
            # held evidence for every one of those days (see
            # routine_evidence docstring).
            def _bucket(r):
                if r["settled_outcome"] == "done":
                    return "done"
                if (r["settled_outcome"] == "abandoned"
                        and r["settled_by"] in ("roller-lapse", "roller-expired")):
                    return "missed"
                if r["settled_outcome"] == "abandoned":
                    return "skipped"
                if r["settled_at"] is None and (
                        r["status"] == "expired" or r["rec_date"] < as_of):
                    # An owner-edited occurrence with no positive domain
                    # record cannot be judged from absence. Unverifiable
                    # -> never judged, whatever the routine.
                    if r["rec_exception"]:
                        return "untouchable"
                    return "unresolved"
                return "open"

            per_date = {}
            for r in rows:
                # one bucket per (rid, rec_date): done wins over miss/skip
                b = _bucket(r)
                cur = per_date.get(r["rec_date"])
                order = {"done": 5, "skipped": 4, "missed": 3,
                         "unresolved": 2, "untouchable": 1, "open": 0}
                if cur is None or order[b] > order[cur]:
                    per_date[r["rec_date"]] = b

            # m-3 (grill-final): an as_of-day occurrence counts as elapsed
            # only once resolved -- a still-open same-day row would
            # transiently understate the morning rate via the denominator.
            def _elapsed(d):
                return d < as_of or per_date.get(d, "open") != "open"

            in_win = [r for r in rows if r["rec_date"] > lo]
            sched_dates = sorted(
                d for d in {r["rec_date"] for r in in_win} if _elapsed(d))
            done = sum(1 for d in sched_dates if per_date.get(d) == "done")
            missed = sum(1 for d in sched_dates if per_date.get(d) == "missed")
            skipped = sum(1 for d in sched_dates if per_date.get(d) == "skipped")
            unresolved = sum(1 for d in sched_dates
                             if per_date.get(d) == "unresolved")
            untouchable = sum(1 for d in sched_dates
                              if per_date.get(d) == "untouchable")
            # rules 1-3: an unresolved instance counts against the user
            # ONLY where the kit actually observes the resource -- there
            # the settle pass has already run, so "still unresolved"
            # means we looked for evidence and found none. Where the kit
            # does not observe it, "unknown" must not be folded into the
            # denominator as if it were a failure. Untouchable rows are
            # unverifiable by construction and never enter it.
            judge = _routine_evidence.judgeable(rid)
            scheduled = done + missed + skipped + (
                unresolved if judge else 0)
            displaced = conn.execute(
                "SELECT COUNT(DISTINCT detail) FROM roller_log "
                "WHERE category='displaced' AND recurrence_id=? "
                "AND detail > ? AND detail <= ?;", (rid, lo, as_of)).fetchone()[0]
            rate = round(done / scheduled, 2) if scheduled else None
            # consec_miss over the most recent elapsed occurrences (all time)
            consec = 0
            for d in sorted(per_date.keys(), reverse=True):
                b = per_date[d]
                if b == "missed" or (b == "unresolved" and judge):
                    consec += 1
                elif b in ("open", "unresolved", "untouchable"):
                    continue                     # not yet resolved: neutral
                else:
                    break                        # done/skipped breaks streak
            # anomaly (2.5 constants; conformance_frozen from roller_log)
            frozen = conn.execute(
                "SELECT 1 FROM roller_log WHERE category='conformance_frozen' "
                "AND recurrence_id=? AND ts > ? LIMIT 1;",
                (rid, defn["updated_at"])).fetchone() is not None
            lo14 = (datetime.date.fromisoformat(as_of)
                    - timedelta(days=14)).isoformat()
            d14 = sorted(d for d in {r["rec_date"] for r in rows
                                     if r["rec_date"] > lo14} if _elapsed(d))
            d14 = [d for d in d14
                   if per_date.get(d) != "untouchable"
                   and (judge or per_date.get(d) != "unresolved")]
            done14 = sum(1 for d in d14 if per_date.get(d) == "done")
            anomaly = None
            if frozen:
                anomaly = "conformance_frozen"
            elif not judge:
                # rule 3 -- silence. The kit holds no evidence for this
                # resource, so it has no standing to call the user's
                # behaviour bad. Counts stay visible for diagnostics;
                # only the JUDGMENT is withheld.
                anomaly = None
            elif (len(d14) >= ANOMALY_RATE_MIN_ELAPSED
                    and (done14 / len(d14)) < ANOMALY_RATE_THRESHOLD):
                anomaly = "rate"
            elif (defn["cadence"] is not None
                    and consec >= _def_streak_threshold(defn["cadence"])):
                anomaly = "streak"
            area = conn.execute("SELECT name FROM areas WHERE id=?;",
                                (defn["area_id"],)).fetchone() \
                if defn["area_id"] else None
            project = None
            if defn["project_id"]:
                pr = conn.execute("SELECT title FROM projects WHERE id=?;",
                                  (defn["project_id"],)).fetchone()
                project = pr[0] if pr else None
            out.append({
                "rid": rid, "title": defn["title"],
                "purpose": defn["purpose"],
                "area": area[0] if area else None, "project": project,
                "cadence": defn["cadence"], "status": defn["status"],
                "scheduled": scheduled, "done": done, "missed": missed,
                "skipped": skipped, "unresolved": unresolved,
                "untouchable": untouchable, "judgeable": judge,
                "displaced": displaced,
                "rate": rate, "consec_miss": consec, "anomaly": anomaly,
                "valid_until": defn["valid_until"],
            })
        return out
    finally:
        conn.row_factory = old_factory


def routine_ack_anomaly(conn, def_token, snapshot):
    """Retro choice 4 (spec 6.3): record anomaly_ack snapshot JSON
    ({type, rate, streak, ts}) under CAS."""
    defn = routine_def_get(conn, def_token)
    if defn is None:
        return "not_found"
    ts = now_utc()
    payload = dict(snapshot)
    payload.setdefault("ts", ts)
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE routine_def SET anomaly_ack=?, version=version+1, "
            "updated_at=? WHERE id=? AND version=?;",
            (json.dumps(payload), ts, defn["id"], defn["version"]))
        if cur.rowcount != 1:
            conn.rollback()
            return "cas_fail"
        conn.commit()
        return "applied"
    except Exception:
        conn.rollback()
        raise


# ── mirror outbox enqueue hook (DGN-258) ─────────────────────────────────────
# Self-locating path: SCRIPT_DIR = database/ -> ../mirror/mirror_state.db.
# Idempotent insert: unique-pending index (idx_outbox_ulid_pending) on
# (event_ulid) WHERE status IN ('queued','claimed') collapses duplicates.
# Pattern is byte-identical to routine_roller.outbox_enqueue (single home kept
# there; this copy avoids importing routine_roller into the interactive path
# which would create a circular import: routine_roller -> kit_life -> .).
#
# Flag gate (DGN-259): when the mirror module is disabled (MIRROR_MODULE=off
# in config/kit_life.conf, or the module directory is absent), this hook is a
# SILENT no-op. A warning is emitted to stderr only if the module is enabled
# but the state DB is unreachable (broken module, not disabled module).
# The gate is cheap: one stat check per process start, cached in _MIRROR_ENABLED.

# SECOND HOME for this path (mirror/adapter.py:STATE_DB_PATH is the first) --
# kept deliberately to avoid the circular import noted above, so BOTH must
# honour the same override or the escape hatch leaks.  Measured 2026-09-09:
# patching only adapter.py left the pollution in place because THIS copy is
# what the test suite actually reaches.
def _mirror_state_default(script_dir):
    """Resolve the mirror state db path, refusing to mint one inside a PACK SOURCE.

    The state file is self-locating (module home -> ../mirror/mirror_state.db).
    In a live instance that is the instance directory and correct.  In the pack
    SOURCE tree the same rule writes a real-data sqlite INTO the product
    payload, which compat-lint C5 refuses -- and the path is .gitignore'd, so
    `git status` reports the tree clean while the installer refuses it.
    Measured 2026-09-09: this blocked an install three separate times, and
    opening an env override (MIRROR_STATE_DB) did not fix it because the CALLERS
    have to set it; six test entry points still did not.

    So the DEFAULT is made safe instead of asking every caller to remember.
    Discriminator, measured not guessed: a pack source carries pack-manifest.json
    beside payload/; a live instance does not (verified on live instances).
    Inside a pack source we fall back to a temp path -- the process still works,
    it just stops writing into the product.
    """
    explicit = os.environ.get("MIRROR_STATE_DB")
    if explicit:
        return explicit
    home = os.path.normpath(os.path.join(script_dir, "..", "mirror"))
    payload_parent = os.path.normpath(os.path.join(script_dir, "..", ".."))
    if os.path.isfile(os.path.join(payload_parent, "pack-manifest.json")):
        import tempfile
        d = os.path.join(tempfile.gettempdir(), "dogany-packsrc-mirror-state")
        try:
            os.makedirs(d, exist_ok=True)
        except OSError:
            return os.path.join(home, "mirror_state.db")
        return os.path.join(d, "mirror_state.db")
    return os.path.join(home, "mirror_state.db")

_STATE_DB_PATH = _mirror_state_default(SCRIPT_DIR)

# Module-presence sentinel: ../mirror/ directory (adjacent to database/).
_MIRROR_DIR = os.path.normpath(os.path.join(SCRIPT_DIR, "..", "mirror"))

# Config file: ../config/kit_life.conf (standard agent config location).
_LIFEKIT_CONF_PATH = os.path.normpath(
    os.path.join(SCRIPT_DIR, "..", "config", "kit_life.conf"))

_MIRROR_ENABLED = None          # None = not yet resolved; True/False = cached


def _mirror_module_enabled():
    """Return True iff the mirror module is present AND not explicitly disabled.
    Result is cached per process (one stat + one file read, then pinned).
    Disabled = MIRROR_MODULE=off in kit_life.conf OR mirror/ dir absent."""
    global _MIRROR_ENABLED
    if _MIRROR_ENABLED is not None:
        return _MIRROR_ENABLED
    # Module presence check (fast path: no dir = definitely disabled).
    if not os.path.isdir(_MIRROR_DIR):
        _MIRROR_ENABLED = False
        return False
    # Config flag check: read MIRROR_MODULE line from kit_life.conf if present.
    try:
        with open(_LIFEKIT_CONF_PATH, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line.startswith("MIRROR_MODULE="):
                    val = line.split("=", 1)[1].strip().lower()
                    if val == "off":
                        _MIRROR_ENABLED = False
                        return False
    except OSError:
        pass  # conf absent or unreadable: fall through (module dir present = enabled)
    _MIRROR_ENABLED = True
    return True


# Minimal DDL subset -- only used when the state db does not exist yet
# (e.g. a fresh test sandbox). Byte-identical schema subset to routine_roller.
_STATE_MIN_DDL = """
CREATE TABLE IF NOT EXISTS mirror_state (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mirror_outbox (
    id           INTEGER PRIMARY KEY,
    event_ulid   TEXT NOT NULL,
    op           TEXT NOT NULL DEFAULT 'sync',
    status       TEXT NOT NULL DEFAULT 'queued',
    lease_at     TEXT,
    attempts     INTEGER NOT NULL DEFAULT 0,
    requeues     INTEGER NOT NULL DEFAULT 0,
    dead         INTEGER NOT NULL DEFAULT 0,
    last_error   TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    CHECK (status IN ('queued','claimed','pushed','failed'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_outbox_ulid_pending
    ON mirror_outbox(event_ulid) WHERE status IN ('queued','claimed');
CREATE TABLE IF NOT EXISTS push_snapshot (
    event_ulid   TEXT PRIMARY KEY,
    surface      TEXT NOT NULL,
    field_hash   TEXT NOT NULL,
    field_json   TEXT NOT NULL DEFAULT '{}',
    pushed_at    TEXT NOT NULL
);
"""


_ENQUEUE_TO = None


def _mirror_enqueue_to():
    """Path of the mirror outbox this instance ENQUEUES into, or None.

    WHY THIS IS NOT `_mirror_module_enabled()` (measured 2026-09-11):
    that flag answers "does THIS instance run a mirror" -- poll, reconcile,
    own a calendar. Enqueueing is a different question: "is there a mirror
    that should carry my writes". On a shared kit those answers differ. The health agent
    has MIRROR_MODULE=off (DGN-839, 2026-08-12: it must not double-register
    against the calendar the life agent owns) and the enqueue rode the same flag, so
    every health-agent write -- including a settled workout -- was dropped on the
    floor. Measured consequence: the owner's finished workouts stopped
    reaching his calendar entirely; the last delivery was 2026-09-09T13:42
    via an unrelated bulk push, and he noticed as "그젠가부터".

    Turning MIRROR_MODULE back on is NOT the fix -- that reintroduces the
    double registration DGN-839 closed. The two jobs get split instead:
    the flag keeps governing ownership, and this key names the outbox.

    Cached per process, same as the flag it sits beside."""
    global _ENQUEUE_TO
    if _ENQUEUE_TO is not None:
        return _ENQUEUE_TO or None
    target = ""
    try:
        with open(_LIFEKIT_CONF_PATH, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line.startswith("MIRROR_ENQUEUE_TO="):
                    target = os.path.expanduser(
                        line.split("=", 1)[1].strip().strip('"').strip("'"))
                    break
    except Exception:
        target = ""
    _ENQUEUE_TO = target
    return target or None


def _outbox_enqueue_best_effort(event_ulid, state_db_path=None):
    """Best-effort enqueue of event_ulid into mirror_outbox.
    Called after every interactive kit_life write that touches the event table.
    NEVER raises: on any failure, prints a one-line warning to stderr and
    returns False. The kit_life write is already committed at this point.
    Silent no-op when there is no outbox to write to."""
    override = _mirror_enqueue_to()
    if not override and not _mirror_module_enabled():
        return False   # silent: no mirror owns this instance's writes
    path = state_db_path or override or _STATE_DB_PATH
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        sc = sqlite3.connect(path)
        sc.execute("PRAGMA journal_mode=WAL")
        sc.execute("PRAGMA busy_timeout=5000")
        sc.executescript(_STATE_MIN_DDL)
        sc.commit()
        now = now_utc()
        try:
            sc.execute(
                "INSERT INTO mirror_outbox(event_ulid, op, status, "
                "created_at, updated_at) VALUES(?, 'sync', 'queued', ?, ?)",
                (event_ulid, now, now))
            sc.commit()
        except sqlite3.IntegrityError:
            sc.rollback()   # already queued/claimed -- idempotent, not an error
        sc.close()
        return True
    except Exception as exc:
        print("mirror outbox enqueue warning: %s (ulid=%s)" % (exc, event_ulid),
              file=sys.stderr)
        return False


def _mirror_state_path():
    """The state db this instance's outbox writes AND never-mirrored reads
    resolve to: MIRROR_ENQUEUE_TO when set (the shared-kit seam above),
    else the self-located default. Same precedence as
    _outbox_enqueue_best_effort, so the roller/travel handles and the
    interactive enqueue can never disagree about which outbox is 'ours'."""
    return _mirror_enqueue_to() or _STATE_DB_PATH


# The five keys adapter.get_mirror_targets decides configured-ness on
# (DGN-364 2.1). Duplicated, not imported: kit_life cannot import the
# adapter (circular import, see _STATE_DB_PATH). test_travel_tombstone_proof
# pins this predicate to adapter.get_mirror_targets over every shape.
_MIRROR_V15_CAL_KEYS = ("cal_id_appt", "cal_id_task", "cal_id_travel")
_MIRROR_CHECKLIST_KEYS = ("gtasks_checklist_id", "agent_tasklist_id")
_MIRROR_LEGACY_KEYS = ("agent_calendar_id", "agent_tasklist_id")


def _state_db_proves_reach(state_conn):
    """True only when state_conn is the bookkeeping of a CONFIGURED mirror
    (adapter.get_mirror_targets would resolve without raising) -- the only
    state db whose silence (no snapshot, no pending outbox) PROVES a row
    was never mirrored.

    Measured 2026-09-27 (travel ghost incident): the crew DB is shared but
    every instance has its own mirror/mirror_state.db. A rule-regen run from
    the health instance opened a freshly minted, EMPTY state db, read 'no
    snapshot' as 'never mirrored', and hard-DELETED 34 travel legs the life agent had
    pushed -- they stayed confirmed on the owner's calendar with no source
    row. An empty, unconfigured or foreign state db is not proof; the row is
    treated as possibly mirrored (soft tombstone), and the life agent's poll sweep
    (adapter.sweep_step, DGN-302 abandoned scan) delivers the cancel."""
    if state_conn is None:
        return False

    def _engraved(key):
        try:
            r = state_conn.execute(
                "SELECT value FROM mirror_state WHERE key=?;",
                (key,)).fetchone()
        except sqlite3.Error:
            return False
        return r is not None and r[0] is not None and str(r[0]).strip() != ""

    v15 = [_engraved(k) for k in _MIRROR_V15_CAL_KEYS]
    if any(v15):
        return all(v15) and any(_engraved(k) for k in _MIRROR_CHECKLIST_KEYS)
    return all(_engraved(k) for k in _MIRROR_LEGACY_KEYS)


def _ulid_for_event_id(conn, eid):
    """Return the ulid for an event integer id, or None."""
    row = conn.execute("SELECT ulid FROM timeblock WHERE id=?;", (eid,)).fetchone()
    return row[0] if row else None


# ══════════════════════════════════════════════════════════════════════════
# DGN-274 travel blocks (build spec v4) -- deriver + verb family (V2..V9).
# Protection / refusal / pre-clean / pin / demotion / chain logic ALL lives
# here in the verb layer (deterministic code, zero model discretion).
# English/ASCII only.
# ══════════════════════════════════════════════════════════════════════════

# Per-instance tunable (config/agent.conf; blank/absent -> old defaults 60/15,
# zero-delta). Still a single per-instance definition -- NOT a per-rule value.
TRAVEL_CHAIN_WINDOW_MIN = agent_conf.conf_int("LIFEKIT_TRAVEL_WINDOW_MIN", 60)
TRAVEL_GRID_MIN = agent_conf.conf_int("LIFEKIT_TRAVEL_GRID_MIN", 15)  # rounding grid (ceil)
# G0a: auto travel-time SOURCE selector (adapter dispatch). Which source fills a
# missing (origin -> dest) edge duration when auto-attach hits edge_missing:
#   agent    -> KEYLESS DEFAULT: during a conversational turn the LLM reads the
#               driving minutes off a Korean map (Kakao 길찾기) via agent-browser
#               (goal-oriented procedure, authored in the schedule-log skill),
#               then registers the edge (travel-edge-add) and re-attaches. No key.
#   kakao-api-> UPGRADE slot (next version): deterministic Kakao Mobility
#               Directions API + owner free key. Interface stubbed; not wired yet.
#   manual   -> the existing one-turn elicitation (ask the user for the minutes). The
#               fail-open safety net; also the source used for background/cron
#               edge-needs where no LLM turn is present.
# Owner directive 2026-08-20: keyless `agent` is the DEFAULT-ON default so a
# key-less user gets auto travel-time out of the box. Fail-open chain is always
# agent -> manual (and kakao-api -> manual until built); a source failure NEVER
# breaks the appt attach.
TRAVEL_SOURCE_AGENT = "agent"
TRAVEL_SOURCE_KAKAO_API = "kakao-api"
TRAVEL_SOURCE_MANUAL = "manual"
TRAVEL_SOURCE_ALLOWED = {TRAVEL_SOURCE_AGENT, TRAVEL_SOURCE_KAKAO_API,
                         TRAVEL_SOURCE_MANUAL}
TRAVEL_SOURCE = agent_conf.conf_str("LIFEKIT_TRAVEL_SOURCE",
                                    TRAVEL_SOURCE_AGENT,
                                    allowed=TRAVEL_SOURCE_ALLOWED)
# G1: default span (minutes) for a one-off TIMED task created via task-add --at
# with no explicit --dur/--end. Per-instance tunable; blank/absent -> 60.
DEFAULT_DURATION_MIN = agent_conf.conf_int("LIFEKIT_DEFAULT_DURATION_MIN", 60)
# D2 (owner ruling 2026-08-25): APPOINTMENT ARRIVAL BUFFER, in minutes. The
# movement leg is derived BACKWARDS from the destination and lands so the user
# ARRIVES this many minutes before the appointment starts; the margin is then
# materialized as its OWN NAMED block, never as empty space
# ("그것도 명시적으로 약속 버퍼 이런걸로 이름 넣어주라").
# FRONT ONLY -- a trailing buffer was rejected outright ("마무리여유는 뭐냐
# 언제마무리될지도모르는데"): an end time nobody can predict cannot be buffered.
# Per-instance tunable, same shape/family as the knobs above; <=0 disables and
# is byte-identical to pre-D2 derivation.
TRAVEL_APPT_BUFFER_MIN = agent_conf.conf_int("LIFEKIT_APPT_BUFFER_MIN", 0)
TRAVEL_BLOCK_CLASS = travel_core.TRAVEL_BLOCK_CLASS
# Derived roles the reconciler iterates, in wall-clock order. 'buffer' (D2) is
# the named arrival margin between the move leg and the anchor.
TRAVEL_ROLE_BUFFER = travel_core.TRAVEL_ROLE_BUFFER
TRAVEL_ROLES = travel_core.TRAVEL_ROLES
# D3-3: PIN PROVENANCE. derived_pinned alone cannot tell an explicit owner
# travel-move apart from a system-minted pin, so the provenance rides inside
# the derived_delta JSON under key "by" (no schema migration needed:
# derived_delta is already a free-form JSON column). Only an owner pin is
# carried forward across a pre-clean; an unattributed/legacy pin is dropped
# and the block regenerates at the derived position.
TRAVEL_PIN_BY_OWNER = travel_core.TRAVEL_PIN_BY_OWNER
TRAVEL_DERIVER_BY = travel_core.TRAVEL_DERIVER_BY
TRAVEL_REGEN_BY = travel_core.TRAVEL_REGEN_BY
TRAVEL_SKIP_BY = travel_core.TRAVEL_SKIP_BY
TRAVEL_EXPIRE_BY = travel_core.TRAVEL_EXPIRE_BY
TRAVEL_SKIP_CLEARED_BY = travel_core.TRAVEL_SKIP_CLEARED_BY
# G3: a started-but-cancelled derived block settled OFF-surface because its
# ANCHOR was cancelled/abandoned (distinct from a normal past block, which is
# lifelog and assumes the anchor happened).
TRAVEL_ANCHOR_CANCELLED_BY = travel_core.TRAVEL_ANCHOR_CANCELLED_BY
TRAVEL_OWNING_AGENT = "ag"
TRAVEL_DISPLAY_TZ = "Asia/Seoul"          # A2: KST single-tz scope

# user-facing strings live as i18n values (DGN-210); source stays ASCII
# (ko values unicode-escaped; the ko title shape is pinned by spec 5.1:
# "<travel>: <anchor title>").
TRAVEL_TITLE_I18N = {
    "ko": u"\uc774\ub3d9: %s",
    "en": u"Travel: %s",
}
# DGN-305: prep block title ("\uc900\ube44: <anchor title>").
TRAVEL_PREP_TITLE_I18N = {
    "ko": u"\uc900\ube44: %s",
    "en": u"Prep: %s",
}
# DGN-314: after-leg title -- fixed home destination, not the anchor title
# (ko: "\uc774\ub3d9: \uc9d1" = "\uc774\ub3d9: \uc9d1"; en: "Travel: home").
TRAVEL_HOME_TITLE_I18N = {
    "ko": u"\uc774\ub3d9: \uc9d1",
    "en": u"Travel: home",
}
# D2: the arrival-buffer block title. The owner must be able to READ the block
# and know what it is -- an unexplained 15-minute hole makes him wonder what
# it is; a labelled block explains itself. ko: "약속 버퍼: <anchor title>".
TRAVEL_BUFFER_TITLE_I18N = {
    "ko": u"\uc57d\uc18d \ubc84\ud37c: %s",
    "en": u"Appointment buffer: %s",
}
TRAVEL_REMIND_I18N = {
    # 4.3/V13: prep_eff>0 -> "prep start -- HH:MM departure" (departure time
    # carried inside the single start_only alert); prep_eff=0 -> departure.
    # DGN-305: alert now anchors on 'before_prep' block start_at (= prep_start).
    "prep": {"ko": u"\uc900\ube44 \uc2dc\uc791 -- {hhmm} \ucd9c\ubc1c",
             "en": u"prep start -- {hhmm} departure"},
    "depart": {"ko": u"\ucd9c\ubc1c", "en": u"departure"},
}


def _travel_schema_ready(conn):
    """M2 (grill fix): v8 code must degrade CLEANLY on a v7 DB inside the
    (7,8) rollout window -- the sdk_bridge/mirror lanes open without the
    version assert, so every travel touchpoint reachable from those lanes
    checks column presence first (PRAGMA is an in-memory schema lookup;
    uncached per the bk_get precedent -- id-keyed caches risk GC reuse).
    False -> all travel behavior is a no-op (pre-008 semantics)."""
    try:
        cols = {r[1] for r in conn.execute("PRAGMA table_info(timeblock);")}
    except sqlite3.Error:
        return False
    return "block_class" in cols


def _travel_title(anchor_title, lang="ko"):
    return TRAVEL_TITLE_I18N.get(lang, TRAVEL_TITLE_I18N["ko"]) % anchor_title


def _travel_prep_title(anchor_title, lang="ko"):
    # DGN-305: title for the prep block derived from the anchor.
    return TRAVEL_PREP_TITLE_I18N.get(lang, TRAVEL_PREP_TITLE_I18N["ko"]) % anchor_title


def _travel_home_title(lang="ko"):
    # DGN-314: after-leg always uses a fixed home title (not the anchor title).
    return TRAVEL_HOME_TITLE_I18N.get(lang, TRAVEL_HOME_TITLE_I18N["ko"])


def _travel_buffer_title(anchor_title, lang="ko"):
    # D2: named arrival-margin block ("약속 버퍼: <anchor title>").
    return (TRAVEL_BUFFER_TITLE_I18N.get(lang, TRAVEL_BUFFER_TITLE_I18N["ko"])
            % anchor_title)


def _travel_role_title(anchor, role):
    """SINGLE locus for the derived-block title per role. Both the mint
    (_travel_create_block) and the conformance comparison (travel_refresh)
    read it here, so a role can never be minted with one title and then judged
    against another (the DGN-314 after-title bug shape)."""
    if role == "before_prep":
        return _travel_prep_title(anchor["title"])
    if role == "after":
        return _travel_home_title()
    if role == TRAVEL_ROLE_BUFFER:
        return _travel_buffer_title(anchor["title"])
    return _travel_title(anchor["title"])


# A derived block is kind='task' (the kind model stays intact), but its alert
# is not a task starting: owner 2026-09-28, 15549 치과 검진 -- the move leg
# "이동: 치과 검진" fired "🚨 태스크 시작". Per role: the reminder header stem
# (remind.sh reads remind.<stem>_<alert>; keys ship in config/i18n/*.bundle
# .json), whether the body names the ANCHOR (title, time, place) instead of
# the helper's own label, and whether it carries the travel minutes.
TRAVEL_ROLE_REMIND = {
    "before_prep": ("prep", True, False),
    "before": ("travel", True, True),
    TRAVEL_ROLE_BUFFER: ("prep", True, False),
    # the return leg's anchor has already happened; its own label says where
    "after": ("travel", False, True),
}


def travel_remind_view(conn, row):
    """Compatibility entry point; lifecycle policy lives in travel_core."""
    return travel_core.travel_remind_view(sys.modules[__name__], conn, row)


def _md_link(text, url):
    """A Markdown link the push sanitizer turns into <a href> (Telegram
    HTML). The label loses [ ] (they would end it early); the url is kept
    ASCII and free of ( ) and whitespace (they would end the target)."""
    label = re.sub(r"[\[\]]+", " ", text or "").strip() or "-"
    return "[%s](%s)" % (label, _url_safe(url))


def _url_safe(url):
    from urllib.parse import quote
    return quote(url or "", safe="/:?&=,.;%+-_~#@!$*'")


def _travel_route_links(conn, origin_id, dest_id, buttons, prep=False):
    """The in-text half of a move alert (owner 2026-10-07 17:35-17:40):
      route_md   "origin -> [dest](place url)" -- both ends by
                 the place's own NAME (address only for a place with no
                 name). The destination is the first link, so a transport's
                 first-link preview opens the arrival place, not the origin;
      directions {"text", "url"} of the leg's directions, only when both
                 ends have coordinates (travel_directions_link) -- never a
                 route the map would have to guess, else None;
      buttons    the map buttons left after the in-text links: a button
                 that opens the same route as the directions line, or a
                 place search the in-text place link already opens, is
                 dropped (the text keeps it); a different provider's route
                 stays a button.
    Prep cards link both place names and keep route URLs as inline buttons
    (owner 2026-10-21), with the requested local Naver/Kakao pair when located.
    An end the map could not locate (2026-10-15): the directions line names
    it and opens the map search instead (_travel_directions_fallback); a
    location not stored YET keeps the 17:40 shape (no line)."""
    region = travel_leg_region(conn, origin_id, dest_id)
    provider = map_providers_for_leg(conn, region)[0]
    ends = []
    for pid in (origin_id, dest_id):
        if pid is None:
            continue
        name = _travel_place_name_text(conn, pid)
        ends.append(_md_link(name, travel_place_link(conn, pid, provider))
                    if prep or pid == dest_id else name)
    route_md = _i18n("remind.prep_route" if prep else "remind.route",
                     fallback=u"{origin} \u2192 {dest}"
                     ).format(origin=ends[0], dest=ends[1]) \
        if len(ends) == 2 else (ends[0] if ends else "")
    directions = travel_directions_link(conn, origin_id, dest_id, region)
    if directions is None and dest_id is not None:
        directions = _travel_directions_fallback(conn, origin_id, dest_id,
                                                 region)
    shown = {directions["url"]} if directions else set()
    left = [b for b in buttons or ()
            if b.get("kind") != "search" and b["url"] not in shown]
    if prep:
        # The prep card offers directions buttons for the user's map pick
        # (owner 2026-11-03 07:27 supersedes 2026-10-21 "both": follow the
        # setting like every other card); no pick -> both local providers.
        # Reuse the existing builders, coordinates and modes; a search
        # fallback must never be labelled as directions.
        routes = [b for b in buttons or () if b.get("kind") != "search"]
        local = map_region_local(conn, region)
        pick = map_provider_pick(conn, region)
        o_c = place_coord_get(conn, origin_id)
        d_c = place_coord_get(conn, dest_id)
        if o_c is not None and d_c is not None:
            requested = ([p for p in pick if p in local] if pick else
                         [p for p in ("naver", "kakao") if p in local])
            if requested:
                routes = []
                for p in requested:
                    for b in _MAP_LINK_BUILDERS[p](
                            conn, origin_id, dest_id, o_c, d_c,
                            _travel_map_mode(conn), _travel_base_place_id(conn)):
                        if b.get("kind") == "route":
                            routes.append(dict(b, text=_i18n(
                                "remind.prep_directions_" + p,
                                fallback="{map} directions").format(map=b["text"])))
        left = routes
        # A known-unlocated place keeps its existing explicit search notice.
        if directions and directions.get("kind") != "search":
            directions = None
    return {"route_md": route_md, "directions": directions,
            "buttons": left}


def _travel_directions_fallback(conn, origin_id, dest_id, region):
    """The directions line of a move whose ends are not both located, or
    None. Owner 2026-10-07 17:40: no coordinates -> NO directions line
    (never a fake route); the destination's place link in the route line
    is the tappable way to the map. That stays the shape while a location
    is merely not stored yet (the daily coordinate pass fills it). Only an
    end the map could NOT find (marked by place-coord-set --missing) gets a
    line, and the line says so instead of posing as a route: "<place> not
    located: map search", opening the leg's map (never Google for a picked
    map, owner 2026-10-08) on the destination. Never raises."""
    try:
        lost = [pid for pid in (origin_id, dest_id)
                if pid is not None and place_coord_get(conn, pid) is None
                and _config_stored(conn, _PLACE_COORD_MISSING_KEY % pid)]
        if not lost:
            return None
        provider = map_providers_for_leg(conn, region)[0]
        text = ", ".join(
            _i18n("remind.directions_unlocated",
                  fallback="{place} not located: map search").format(
                      place=_travel_place_name_text(conn, pid))
            for pid in lost)
        return {"text": text,
                "url": travel_place_link(conn, dest_id, provider),
                "provider": provider, "kind": "search"}
    except Exception:  # noqa: BLE001 -- a reminder never dies on a route
        return None


def _travel_place_name_text(conn, place_id):
    """How the alert's route line names one end: the place's own name as
    the owner knows it (the office by its name, not its street address);
    the address only for a place with no name."""
    place = travel_place_get(conn, place_id) or {}
    return (place.get("name") or _travel_place_map_string(conn, place_id)
            or "")


def _travel_leg_places(conn, role, anchor):
    """(origin_id, dest_id) of the move a derived role belongs to, by the
    kit's existing origin rule: the outbound legs (prep, move, buffer) go
    from _travel_origin_place_id (stated origin > chain neighbour > presence
    > home) to the rule's place; a provisional rule defers to the anchor's
    resolved place. The return leg goes from that place to home.
    Either id may be None (unknown -> no route, never guessed)."""
    if anchor is None:
        return None, None
    rule = _travel_rule_for_anchor_row(conn, anchor)
    dest_id = rule.get("place_id") if rule is not None else None
    # A stopgap estimates time, not venue identity. Already-stored stale
    # stopgaps must display the corrected appointment even before re-attach.
    if (rule is not None and rule.get("before_src") == TRAVEL_SRC_PROVISIONAL
            and anchor.get("place_id") is not None):
        dest_id = anchor["place_id"]
    if dest_id is None:
        dest_id = anchor.get("place_id")
    if role == "after":
        return dest_id, _travel_base_place_id(conn)
    origin_id = _travel_origin_place_id(conn, anchor)
    if origin_id is None:
        origin_id = _travel_base_place_id(conn)
    return origin_id, dest_id


def _travel_place_map_string(conn, place_id):
    """The place's typeable address (same order travel-resolve.sh drives
    into the map: the primary unless it is a map_url, then a road address,
    then any other typeable kind), or None."""
    try:
        row = conn.execute(
            "SELECT value FROM place_address WHERE place_id=? "
            "AND kind <> 'map_url' AND TRIM(value) <> '' "
            "ORDER BY is_primary DESC, (kind = 'road') DESC, id LIMIT 1;",
            (place_id,)).fetchone()
        if row is not None:
            return row[0]
    except sqlite3.Error:
        pass
    try:                                  # pre-050: the single column
        row = conn.execute(
            "SELECT address FROM place WHERE id=? AND address IS NOT NULL "
            "AND TRIM(address) <> '' AND address NOT LIKE 'http%';",
            (place_id,)).fetchone()
    except sqlite3.Error:
        return None
    return row[0] if row is not None else None


def _travel_place_alert_text(conn, place_id, base_id=None):
    """How an alert names one end of a move: home by its name (everyone
    knows where home is: the confirmed sample names home, not its address), every
    other place by its address, falling back to the name."""
    place = travel_place_get(conn, place_id)
    name = place["name"] if place is not None else ""
    if place_id == base_id and name:
        return name
    return _travel_place_map_string(conn, place_id) or name


# -- map buttons (066 place_coord) ------------------------------------------
# Verified 2026-10-06 against the live map apps, not folklore:
#   * Kakao's web route app (kakaomap_pc_route, 2026-10-01 build) reads only
#     rt=<x,y,...> + rt1/rt2 names from the URL; the old sName/eName text
#     form is not read any more (the page opens with empty ends). Its URL
#     guide's directions form is /link/by/<car|traffic|walk|bicycle>/
#     name,lat,lng/name,lat,lng -- WGS84, both ends filled.
#   * Naver's directions page addresses each end as "x,y,name,id,type"
#     (/p/directions/<origin>/<dest>/-/<mode>); route.sh lands on exactly
#     that URL, so the resolve stores each end's segment as Naver wrote it.
#   * Google's documented Maps URL (/maps/dir/?api=1&origin=&destination=
#     &travelmode=) opens directions from text or "lat,lng" anywhere; no
#     origin = the user's current location. (kit 2.42.0, 069)
# A button that cannot fill both ends is never emitted. With no coordinates
# for an end: Kakao and Naver fall back to a search for the destination
# (opens, shows the place, one tap to directions) -- never to Google while
# the owner's pick can open anything (owner 2026-10-08). WHICH providers a leg
# gets is per leg by region (069, travel_map_links): Google unless the
# owner picked the leg's region's local maps.
TRAVEL_MAP_MODES = {   # travel_mode -> (kakao /link/by, naver path, google)
    "transit": ("traffic", "transit", "transit"),
    "walk": ("walk", "walk", "walking"),
    "car": ("car", "car", "driving"),
    "bike": ("bicycle", "bicycle", "bicycling"),
}
TRAVEL_MODE_CARD_TEXT = {
    "transit": u"대중교통", "walk": u"도보", "car": u"승용차",
    "bike": u"자전거",
}
_MERCATOR_R = 6378137.0


def _naver_b62_deg(tok):
    """Degrees from one encoded Naver coordinate (0-9a-zA-Z), or None."""
    digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if not tok or not tok.isascii() or any(c not in digits for c in tok):
        return None
    n = 0
    for c in tok:
        n = n * 62 + digits.index(c)
    return (n - 2000000000) / 1e7


def _naver_ref_coord(ref):
    """(lat, lng) WGS84 of one Naver directions end "x,y,name,id,type", or
    None. x,y are lng,lat degrees or Web Mercator metres (EPSG:3857, what
    the current page writes) -- told apart by range, converted exactly."""
    import math
    parts = (ref or "").split(",")
    if len(parts) < 2:
        return None
    try:
        x, y = float(parts[0]), float(parts[1])
    except ValueError:
        # the page now writes each end as base62 text ("3zjD4Y,2AJrSI"):
        # (value - 2e9) / 1e7 = degrees, lng first
        x, y = _naver_b62_deg(parts[0]), _naver_b62_deg(parts[1])
        if x is None or y is None or not (
                124 <= x <= 132 and 33 <= y <= 39):   # Korea, with margin
            return None
        return round(y, 7), round(x, 7)
    if abs(x) <= 180 and abs(y) <= 90:
        lng, lat = x, y
    else:
        lng = math.degrees(x / _MERCATOR_R)
        lat = math.degrees(2 * math.atan(math.exp(y / _MERCATOR_R))
                           - math.pi / 2)
    if not (-90 <= lat <= 90 and -180 <= lng <= 180):
        return None
    return round(lat, 7), round(lng, 7)


def _place_coord_ready(conn):
    try:
        return conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='place_coord';").fetchone() is not None
    except sqlite3.Error:
        return False


def place_coord_get(conn, place_id):
    """{lat, lng, naver_ref, source, updated_at} of a place, or None (no
    row, or a pre-066 store)."""
    if place_id is None or not _place_coord_ready(conn):
        return None
    row = conn.execute(
        "SELECT lat, lng, naver_ref, source, updated_at FROM place_coord "
        "WHERE place_id=?;", (place_id,)).fetchone()
    if row is None:
        return None
    return {"lat": row[0], "lng": row[1], "naver_ref": row[2],
            "source": row[3], "updated_at": row[4]}


def place_coord_set(conn, place_token, naver_ref, source="naver_route",
                    now=None):
    """Store where a place is, from one Naver directions end segment
    ("x,y,name,id,type", URL-decoded). Upsert, one row per place. Returns
    {"result": applied|not_found|bad_ref|schema_not_ready, ...}."""
    if not _place_coord_ready(conn):
        return {"result": "schema_not_ready"}
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    ref = (naver_ref or "").strip()
    coord = _naver_ref_coord(ref)
    if coord is None:
        return {"result": "bad_ref"}
    now = now or now_utc()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT INTO place_coord(place_id, lat, lng, naver_ref, source, "
            "updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(place_id) DO UPDATE "
            "SET lat=excluded.lat, lng=excluded.lng, "
            "naver_ref=excluded.naver_ref, source=excluded.source, "
            "updated_at=excluded.updated_at;",
            (place["id"], coord[0], coord[1], ref, source, now))
        _place_coord_clear_missing(conn, place["id"])
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied", "place_id": place["id"],
            "lat": coord[0], "lng": coord[1]}


def _place_coord_clear_missing(conn, place_id):
    """A stored location ends the 'not located' mark (inside the caller's
    transaction)."""
    conn.execute("DELETE FROM config WHERE key=?;",
                 (_PLACE_COORD_MISSING_KEY % place_id,))


def _travel_map_mode(conn):
    try:
        row = conn.execute("SELECT TRIM(value) FROM config WHERE "
                           "key='travel_mode';").fetchone()
    except sqlite3.Error:
        row = None
    mode = (row[0] or "").lower() if row is not None else ""
    return TRAVEL_MAP_MODES.get(mode, TRAVEL_MAP_MODES["transit"])


def _kakao_label(text):
    # a /link/by end is "name,lat,lng" between slashes: neither may appear
    # inside the name
    return re.sub(r"[,/]+", " ", text or "").strip() or "-"


def _map_link_kakao(conn, origin_id, dest_id, o_c, d_c, modes, base_id):
    """Kakao: directions with both ends' coordinates; else a search for the
    destination (opens, shows the place, one tap to directions)."""
    from urllib.parse import quote
    text = _i18n("remind.map_kakao", fallback="Kakao Map")
    if o_c is not None and d_c is not None and origin_id != dest_id:
        # the ends are routed by coordinates; the labels are what the map
        # shows, so they are the places' own names (owner 2026-10-07 17:35)
        o_name = _kakao_label(_travel_place_name_text(conn, origin_id))
        d_name = _kakao_label(_travel_place_name_text(conn, dest_id))
        return [{"text": text, "kind": "route", "url": (
            "https://map.kakao.com/link/by/%s/%s,%.7f,%.7f/%s,%.7f,%.7f" % (
                modes[0], quote(o_name, safe=""), o_c["lat"], o_c["lng"],
                quote(d_name, safe=""), d_c["lat"], d_c["lng"]))}]
    query = _map_search_query(conn, dest_id)
    if not query:
        return []
    return [{"text": text, "kind": "search",
             "url": "https://map.kakao.com/link/search/"
             + quote(query, safe="")}]


def _map_search_query(conn, dest_id):
    """What a provider's search opens on when it cannot route: the
    destination's typeable address, else its name ('' for neither)."""
    from place_location import split_location
    name = _travel_place_name_text(conn, dest_id) if dest_id is not None else ""
    label, _room, _embedded = split_location(name)
    return _travel_place_map_string(conn, dest_id) or label


def _naver_end(conn, place_id, coord):
    """One Naver directions end: the segment the resolve stored, else
    "lng,lat,name,," from the coordinates (the documented https form,
    owner 2026-10-07 17:37); URL-encoded, commas kept as separators."""
    from urllib.parse import quote
    if coord.get("naver_ref"):
        return quote(coord["naver_ref"], safe=",")
    name = re.sub(r"[,/]+", " ",
                  _travel_place_name_text(conn, place_id)).strip()
    return "%.7f,%.7f,%s,," % (coord["lng"], coord["lat"],
                               quote(name, safe=""))


def _map_link_naver(conn, origin_id, dest_id, o_c, d_c, modes, base_id):
    """Naver: directions with both ends located (stored segment or
    coordinates); else a search for the destination -- Naver cannot fill a
    directions end from text, but the owner picked Naver, so the button
    opens Naver on the place (owner 2026-10-08: a picked provider never
    silently becomes Google)."""
    from urllib.parse import quote
    text = _i18n("remind.map_naver", fallback="Naver Map")
    if o_c is not None and d_c is not None and origin_id != dest_id:
        return [{"text": text, "kind": "route",
                 "url": "https://map.naver.com/p/directions/%s/%s/-/%s" % (
                     _naver_end(conn, origin_id, o_c),
                     _naver_end(conn, dest_id, d_c), modes[1])}]
    query = _map_search_query(conn, dest_id)
    if not query:
        return []
    return [{"text": text, "kind": "search",
             "url": MAP_PLACE_LINKS["naver"][1].format(
                 q=quote(query, safe=""))}]


def _map_google_end(conn, place_id, coord):
    """One end for Google: coordinates when stored, else the typeable
    address, else the name (Google geocodes text; home is never sent by
    its nickname)."""
    if coord is not None:
        return "%.7f,%.7f" % (coord["lat"], coord["lng"])
    addr = _travel_place_map_string(conn, place_id)
    if addr:
        return addr
    if place_id == _travel_base_place_id(conn):
        return None
    return (travel_place_get(conn, place_id) or {}).get("name") or None


def _map_link_google(conn, origin_id, dest_id, o_c, d_c, modes, base_id):
    """Google: the documented Maps URL (api=1) -- opens directions from text
    or coordinates, anywhere; no origin -> the user's current location."""
    from urllib.parse import urlencode
    dest = _map_google_end(conn, dest_id, d_c)
    if not dest:
        return []
    q = [("api", "1")]
    origin = (_map_google_end(conn, origin_id, o_c)
              if origin_id is not None and origin_id != dest_id else None)
    if origin:
        q.append(("origin", origin))
    q += [("destination", dest), ("travelmode", modes[2])]
    return [{"text": _i18n("remind.map_google", fallback="Google Maps"),
             "kind": "route",
             "url": "https://www.google.com/maps/dir/?" + urlencode(q)}]


# Place links per provider (owner 2026-10-07 17:38: each place name in a move
# alert opens that place). One row per provider, tried in order: a stored
# map/place URL always wins (place_address kind map_url, e.g. the Naver place
# link saved at registration); then the provider's own place page when the
# stored coordinates name one; else search for address or the clean label.
#   naver   entry/place/<id> needs the place id in the stored directions
#           segment ("x,y,name,id,type"); search /p/search/<q>
#   kakao   /link/map/<name>,<lat>,<lng> needs coordinates; /link/search/<q>
#   google  documented search URL (api=1) -- coordinates or text
MAP_PLACE_LINKS = {
    "naver": ("https://map.naver.com/p/entry/place/{naver_id}",
              "https://map.naver.com/p/search/{q}"),
    "kakao": ("https://map.kakao.com/link/map/{name},{lat},{lng}",
              "https://map.kakao.com/link/search/{q}"),
    "google": ("https://www.google.com/maps/search/?api=1&query={lat},{lng}",
               "https://www.google.com/maps/search/?api=1&query={q}"),
}


def _place_map_url(conn, place_id):
    """A stored http(s) map/place URL of the place, or None."""
    try:
        row = conn.execute(
            "SELECT value FROM place_address WHERE place_id=? "
            "AND kind='map_url' AND value LIKE 'http%' "
            "ORDER BY is_primary DESC, id LIMIT 1;", (place_id,)).fetchone()
    except sqlite3.Error:
        return None
    return row[0].strip() if row else None


def travel_place_link(conn, place_id, provider):
    """The URL a place name in a move alert opens on `provider`
    (MAP_PLACE_LINKS). Never empty for a place on file: the search form
    needs only the name."""
    from urllib.parse import quote
    stored = _place_map_url(conn, place_id)
    if stored:
        return stored
    by_place, search = MAP_PLACE_LINKS.get(provider,
                                           MAP_PLACE_LINKS["google"])
    name = _travel_place_name_text(conn, place_id)
    c = place_coord_get(conn, place_id)
    if c is not None:
        parts = (c.get("naver_ref") or "").split(",")
        nid = parts[3].strip() if len(parts) > 3 else ""
        if "{naver_id}" not in by_place or nid.isdigit():
            return by_place.format(
                naver_id=nid, lat="%.7f" % c["lat"], lng="%.7f" % c["lng"],
                name=quote(re.sub(r"[,/]+", " ", name).strip(), safe=""))
    return search.format(q=quote(_map_search_query(conn, place_id), safe=""))


def travel_directions_link(conn, origin_id, dest_id, region=None):
    """{"text", "url"} of the in-text directions line for one move: the
    first provider of the leg's pick that opens a route with BOTH ends at
    stored coordinates; None when an end has none (owner 2026-10-07 17:40:
    never a fake route) -- the place links still open each end."""
    if origin_id is None or dest_id is None or origin_id == dest_id:
        return None
    o_c, d_c = place_coord_get(conn, origin_id), place_coord_get(conn, dest_id)
    if o_c is None or d_c is None:
        return None
    if region is None:
        region = travel_leg_region(conn, origin_id, dest_id)
    modes = _travel_map_mode(conn)
    base_id = _travel_base_place_id(conn)
    for p in map_providers_for_leg(conn, region):
        for link in _MAP_LINK_BUILDERS[p](conn, origin_id, dest_id, o_c, d_c,
                                          modes, base_id):
            if link.get("kind") == "route":
                return {"text": _i18n("remind.directions",
                                      fallback="Directions"),
                        "url": link["url"], "provider": p}
    return None


# The link builders: a provider the kit can offer is one it can build a link
# for. Which providers a REGION uses is data (map_region, 069); nothing below
# branches on a country.
MAP_PROVIDER_DEFAULT = "google"
_MAP_LINK_BUILDERS = {
    "google": _map_link_google,
    "kakao": _map_link_kakao,
    "naver": _map_link_naver,
}
_MAP_PROVIDER_KEY = "map_provider_%s"          # config: the user's pick, csv
_MAP_PROVIDER_ASKED_KEY = "map_provider_asked_%s"


def _map_region_ready(conn):
    try:
        return conn.execute(
            "SELECT COUNT(*) FROM sqlite_master WHERE type='table' "
            "AND name IN ('map_region', 'place_region');").fetchone()[0] == 2
    except sqlite3.Error:
        return False


def _region_code(raw):
    r = str(raw or "").strip().upper()
    return r if re.match(r"^[A-Z]{2}$", r) else None


def map_region_get(conn, region):
    """{region, label, providers, box, source} of one region row, or None."""
    if region is None or not _map_region_ready(conn):
        return None
    row = conn.execute(
        "SELECT region, label, providers, lat_min, lat_max, lng_min, "
        "lng_max, source, updated_at FROM map_region WHERE region=?;",
        (region,)).fetchone()
    if row is None:
        return None
    try:
        prov = [str(p) for p in json.loads(row[2] or "[]")]
    except ValueError:
        prov = []
    return {"region": row[0], "label": row[1], "providers": prov,
            "box": list(row[3:7]) if row[3] is not None else None,
            "source": row[7], "updated_at": row[8]}


def map_region_label(conn, region):
    """How the user's language names a region: the bundle, then the stored
    label, then the code."""
    m = map_region_get(conn, region) or {}
    return _i18n("map.region." + str(region), fallback=(
        m.get("label") or str(region)))


def place_region_of(conn, place_id):
    """(region, source) of a place: its place_region row, else the region
    whose coordinate box holds its 066 coordinates (the smallest box when
    several do), else (None, None). Never guessed from a name."""
    if place_id is None or not _map_region_ready(conn):
        return None, None
    row = conn.execute("SELECT region, source FROM place_region "
                       "WHERE place_id=?;", (place_id,)).fetchone()
    if row is not None:
        return row[0], row[1]
    c = place_coord_get(conn, place_id)
    if c is None:
        return None, None
    row = conn.execute(
        "SELECT region FROM map_region WHERE lat_min IS NOT NULL "
        "AND ? BETWEEN lat_min AND lat_max AND ? BETWEEN lng_min AND lng_max "
        "ORDER BY (lat_max - lat_min) * (lng_max - lng_min), region LIMIT 1;",
        (c["lat"], c["lng"])).fetchone()
    return (row[0], "coord") if row is not None else (None, None)


def travel_leg_region(conn, origin_id, dest_id):
    """Resolve a move's region without overriding an owner's map choice.

    A known end supplies the region for an unknown end.  When every end is
    unknown (one or two ends), one (and only one) configured regional
    provider supplies the region.  Two different known regions remain ambiguous and use Google.
    """
    ends = [p for p in (origin_id, dest_id) if p is not None]
    if not ends:
        return None
    regs = {place_region_of(conn, p)[0] for p in ends}
    known = regs - {None}
    if len(known) > 1:
        return None
    if known:
        return known.pop()
    rows = conn.execute(
        "SELECT key FROM config WHERE key GLOB 'map_provider_[A-Z][A-Z]' "
        "ORDER BY key;").fetchall()
    configured = [row[0][-2:] for row in rows
                  if map_provider_pick(conn, row[0][-2:])]
    return configured[0] if len(configured) == 1 else None


def map_region_local(conn, region):
    """The region's local providers the kit can build a link for (Google is
    the default, never 'local')."""
    m = map_region_get(conn, region)
    if m is None:
        return []
    return [p for p in m["providers"]
            if p in _MAP_LINK_BUILDERS and p != MAP_PROVIDER_DEFAULT]


def map_provider_pick(conn, region):
    """The user's stored pick for a region (list), or None (never asked or
    not answered)."""
    if region is None:
        return None
    raw = _config_stored(conn, _MAP_PROVIDER_KEY % region)
    if not raw:
        return None
    pick = [p.strip() for p in str(raw).split(",")
            if p.strip() in _MAP_LINK_BUILDERS]
    return pick or None


def map_providers_for_leg(conn, region):
    """Providers for one move: the user's pick for the leg's region, else
    Google. A leg with no single region is Google."""
    return map_provider_pick(conn, region) or [MAP_PROVIDER_DEFAULT]


def travel_map_links(conn, origin_id, dest_id):
    """Map buttons for one move: [{"text", "url"}], in the provider order of
    the leg's pick (map_providers_for_leg). Only links that open: a picked
    provider that cannot route this leg (no stored ends) gives its SEARCH on
    the destination instead (Kakao /link/search, Naver /p/search); Google
    stands in only when none of the picked can build any link -- it opens
    from text. No destination at all -> []."""
    if dest_id is None:
        return []
    modes = _travel_map_mode(conn)
    base_id = _travel_base_place_id(conn)
    o_c = place_coord_get(conn, origin_id) if origin_id is not None else None
    d_c = place_coord_get(conn, dest_id)
    region = travel_leg_region(conn, origin_id, dest_id)
    links = []
    for p in map_providers_for_leg(conn, region):
        links += _MAP_LINK_BUILDERS[p](conn, origin_id, dest_id, o_c, d_c,
                                       modes, base_id)
    if not links:
        links = _map_link_google(conn, origin_id, dest_id, o_c, d_c, modes,
                                 base_id)
    return links


def _card_map_button(conn, origin_id, dest_id, search_only=False, location=None):
    """The one owner-selected map action carried beside an appointment card."""
    links = travel_map_links(conn, origin_id, dest_id)
    if not links and location:
        from place_location import split_location
        from urllib.parse import quote
        label, _room, address = split_location(location)
        if not label or _location_link_kind(label):
            return None
        return {"text": re.sub(r"\s+", "", _i18n("remind.map_google", fallback="Google Maps")) + u" 길찾기",
                "url": MAP_PLACE_LINKS["google"][1].format(q=quote(address or label, safe=""))}
    if not links:
        return None
    link = links[0]
    url = link["url"]
    if search_only:
        from urllib.parse import quote
        provider = map_providers_for_leg(conn, travel_leg_region(conn, origin_id, dest_id))[0]
        url = MAP_PLACE_LINKS[provider][1].format(q=quote(_map_search_query(conn, dest_id), safe=""))
    return {"text": re.sub(r"\s+", "", link["text"]) + u" 길찾기",
            "url": url}


# -- map provider: region lookup + the one-time choice (069) ------------------
# Printed with the card (next to PLACE_HOURS_NEEDED), for the AGENT:
#   PLACE_REGION_NEEDED<TAB><place_id><TAB><name><TAB><address>
#       an end of an upcoming move whose region is not on file and not
#       readable from coordinates: look the country up silently, store it.
#   MAP_REGION_NEEDED<TAB><CC>
#       a region with no map_region row: look up its local map apps, store
#       the ones the kit can link (or none).
#   MAP_PROVIDER_ASK<TAB><CC><TAB><text> + MAP_PROVIDER_CHOICE<TAB><p><TAB>
#   <label> per choice: the first move in a region that has local providers,
#       while the user has no pick for it -- asked ONCE per region.
PLACE_REGION_NEEDED = "PLACE_REGION_NEEDED"
MAP_REGION_NEEDED = "MAP_REGION_NEEDED"
MAP_PROVIDER_ASK = "MAP_PROVIDER_ASK"
MAP_PROVIDER_CHOICE = "MAP_PROVIDER_CHOICE"
MAP_REGION_RELAY = (
    "MAP_REGION_RELAY PLACE_REGION_NEEDED names a place on an upcoming move "
    "whose country is not on file. Look it up yourself, silently, from its "
    "address / name and store it: kit_life.sh place-region-set <place_id> "
    "<ISO 3166-1 alpha-2, e.g. KR> --source <url|address>. MAP_REGION_NEEDED "
    "names a country whose local map apps are not on file: look up which map "
    "apps people there use for directions and store the ones the kit can "
    "link: kit_life.sh map-region-set <CC> <provider[,provider]|none> "
    "--label '<the country in the user's language>' --source <url> "
    "(linkable: " + ", ".join(sorted(_MAP_LINK_BUILDERS)) + "; google is the "
    "default everywhere, list only local ones). Never ask the owner; never "
    "print these lines.")
MAP_PROVIDER_RELAY = (
    "MAP_PROVIDER_RELAY After the card, end your reply with the "
    "MAP_PROVIDER_ASK text verbatim, once, with the MAP_PROVIDER_CHOICE "
    "labels as buttons (or listed) -- an optional answer, never asked again "
    "for this region. Owner picks -> kit_life.sh map-provider-set <CC> "
    "<provider> (both local maps -> two providers comma-joined, e.g. "
    "kakao,naver). No answer -> Google stays. Never print these lines. A "
    "literal \\n in the text is a line break.")


def _map_touched_legs(conn, ids, removed_ids=(), now=None):
    """[(role, anchor)] of the upcoming live move legs of the touched
    blocks (a touched leg names its anchor)."""
    removed = set(int(i) for i in (removed_ids or ()) if str(i).isdigit())
    now = now or now_utc()
    seen, out = set(), []
    for raw in ids or ():
        try:
            eid = int(raw)
        except (TypeError, ValueError):
            continue
        if eid in removed:
            continue
        row = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;", (eid,))
        if row is None:
            continue
        if row.get("block_class") == TRAVEL_BLOCK_CLASS:
            if not row.get("derived_from"):
                continue
            row = _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=?;",
                              (row["derived_from"],))
            if row is None:
                continue
        if not row.get("ulid") or row["ulid"] in seen:
            continue
        seen.add(row["ulid"])
        for (role,) in conn.execute(
                "SELECT DISTINCT derived_role FROM timeblock WHERE "
                "block_class=? AND derived_from=? AND derived_role IN "
                "('before', 'after') AND settled_at IS NULL AND start_at > ? "
                "ORDER BY derived_role DESC;",
                (TRAVEL_BLOCK_CLASS, row["ulid"], now)).fetchall():
            out.append((role, row))
    return out


def _map_provider_ask_lines(conn, region):
    local = map_region_local(conn, region)
    names = [_i18n("remind.map_" + p, fallback=p) for p in local]
    label = map_region_label(conn, region)
    ira = "\uc774\ub77c" if _hangul_final(label) else "\ub77c"
    text = _i18n("map.provider.ask",
                 "Map buttons open Google Maps by default. This place is in "
                 "{region}, so {providers} work too. Which map should they "
                 "open?").format(region=label, ira=ira,
                                 providers="/".join(names))
    choices = [(p, _i18n("remind.map_" + p, fallback=p))
               for p in [MAP_PROVIDER_DEFAULT] + local]
    ac = _ask_choices()
    out = ["%s\t%s\t%s\t%s" % (MAP_PROVIDER_ASK, region,
                               text.replace("\n", "\\n"),
                               ac.choices_field(choices))]
    for p, label in choices:
        out.append("%s\t%s\t%s" % (MAP_PROVIDER_CHOICE, p, label))
    out.append(ac.options_line(MAP_PROVIDER_ASK, region, choices))
    return out


def _emit_map_region(conn, ids, removed_ids=(), now=None):
    """Region lookups and the one-time provider choice for the touched
    blocks' upcoming moves (block comment above). Prints nothing when every
    end is placed and every region's choice is made or not needed.
    Best-effort: never raises."""
    if not _map_region_ready(conn):
        return
    try:
        legs = _map_touched_legs(conn, ids, removed_ids, now=now)
        need, regions, asks, asked = [], [], [], set()
        placed = set()
        for role, anchor in legs:
            try:
                o, d = _travel_leg_places(conn, role, anchor)
            except Exception:
                continue
            for pid in (o, d):
                if pid is None or pid in placed:
                    continue
                placed.add(pid)
                reg = place_region_of(conn, pid)[0]
                if reg is None:
                    place = travel_place_get(conn, pid) or {}
                    addr = (_travel_place_map_string(conn, pid)
                            or place.get("address") or "")
                    need.append("%s\t%s\t%s\t%s" % (
                        PLACE_REGION_NEEDED, pid,
                        _travel_signal_field(place.get("name") or ""),
                        _travel_signal_field(addr)))
                elif map_region_get(conn, reg) is None and \
                        reg not in regions:
                    regions.append(reg)
            reg = travel_leg_region(conn, o, d)
            if (reg is None or reg in asked or not map_region_local(conn, reg)
                    or map_provider_pick(conn, reg) is not None
                    or _config_stored(conn, _MAP_PROVIDER_ASKED_KEY % reg)
                    is not None):
                continue
            asked.add(reg)
            asks.append(reg)
    except (sqlite3.Error, TypeError, ValueError):
        return
    for line in need:
        print(line)
    for reg in regions:
        print("%s\t%s" % (MAP_REGION_NEEDED, reg))
    if need or regions:
        print(MAP_REGION_RELAY)
    for reg in asks:
        for line in _map_provider_ask_lines(conn, reg):
            print(line)
        try:
            _config_put(conn, _MAP_PROVIDER_ASKED_KEY % reg, now_utc())
            conn.commit()
        except sqlite3.Error:
            pass
    if asks:
        print(MAP_PROVIDER_RELAY)
        print(_ask_choices().RELAY)


# -- coordinates at registration (owner 2026-10-07 17:40) ---------------------
# Every path that saves a place (place-manage / travel-place-add, an
# appointment's venue, a map link resolved to a venue, the ORIGIN_ASK answer)
# mints it through travel_place_add, which notes the new id here. The verb's
# output then carries, for the AGENT:
#   PLACE_COORD_NEEDED<TAB><place_id><TAB><name><TAB><address><TAB>register
#       look the place up (keyless map lookup) and put what the map found in
#       the SAME owner-confirm message that confirms the place name; confirmed
#       -> place-coord-set; not found -> place-coord-set <id> --missing. The
#       place is already saved: registration never waits on this.
#   PLACE_COORD_NEEDED<TAB>...<TAB>later
#       a place on an upcoming move still has no coordinates (marked missing
#       at registration, or saved before this rule): asked ONCE, with the
#       card; place_coord_asked_<id> records that it was.
PLACE_COORD_NEEDED = "PLACE_COORD_NEEDED"
_PLACE_COORD_ASKED_KEY = "place_coord_asked_%s"
_PLACE_COORD_MISSING_KEY = "place_coord_missing_%s"
_PLACE_COORD_NEW = []          # ids minted by this process, not yet signalled
PLACE_COORD_RELAY = (
    "PLACE_COORD_RELAY PLACE_COORD_NEEDED names a saved place with no map "
    "coordinates. Resolve it yourself: map_search.py '<venue>', then bash "
    "routines/bundle/travel-resolve.sh --coords-lookup <place_id> --hint "
    "'<area/address>' (parse the hint from the supplied location too). "
    "COORD_FOUND carries the map end; COORD_CANDIDATES / COORD_CANDIDATE "
    "carry names and addresses, never silently pick the first branch. "
    "Use WebSearch for '<venue> <area>' to verify unresolved/ambiguous "
    "identity. Save a uniquely verified match with place-coord-set "
    "<place_id> '<naver end>' --source naver_lookup; resolve travel and "
    "appt-travel-attach. A successful verified lookup needs no owner "
    "address or confirmation question. If every means fails, ask ONE "
    "specific NEW identifying detail or candidate pick, subject to the UI "
    "copy gate. Never repeat a supplied name, address, link or area. "
    "No candidates after all lookups -> place-coord-set <place_id> --missing; "
    "track the one question already asked. Dependency failure stays agent "
    "work, never an owner address request. Never print these instructions.")


def _conn_db_file(conn):
    try:
        row = conn.execute("PRAGMA database_list;").fetchone()
        return os.path.realpath(row[2]) if row and row[2] else ""
    except (sqlite3.Error, TypeError, ValueError):
        return ""


def _place_coord_note_new(conn, place):
    """Note a place this process just saved (per database file, so a
    process that touches several stores never signals one store's id
    against another)."""
    try:
        key = (_conn_db_file(conn), int((place or {}).get("id")))
    except (TypeError, ValueError):
        return
    if key not in _PLACE_COORD_NEW:
        _PLACE_COORD_NEW.append(key)


def _place_coord_line(conn, pid, phase):
    place = travel_place_get(conn, pid) or {}
    addr = (_travel_place_map_string(conn, pid) or place.get("address")
            or "")
    return "%s\t%s\t%s\t%s\t%s" % (
        PLACE_COORD_NEEDED, pid,
        _travel_signal_field(place.get("name") or ""),
        _travel_signal_field(addr), phase)


def _place_coord_wanted(conn, pid):
    """True for a live place with no stored coordinates."""
    if pid is None or not _place_coord_ready(conn):
        return False
    place = travel_place_get(conn, pid)
    if place is None or place.get("status") == "gone":
        return False
    return place_coord_get(conn, pid) is None


def _place_coord_register_lines(conn):
    """PLACE_COORD_NEEDED ... register for the places this process minted
    (each once). Clears the note."""
    out = []
    here = _conn_db_file(conn)
    mine = [k for k in _PLACE_COORD_NEW if k[0] == here]
    for k in mine:
        _PLACE_COORD_NEW.remove(k)
    for _db, pid in mine:
        try:
            if _place_coord_wanted(conn, pid):
                # find it in this same call; only a place the map could not
                # place falls through to the agent's confirm step
                if place_coord_autolookup(conn, pid)["result"] == "applied":
                    continue
                out.append(_place_coord_line(conn, pid, "register"))
        except sqlite3.Error:
            continue
    return out


def _emit_place_coord(conn, ids, removed_ids=(), now=None):
    """The coordinate signals of one write: 'register' for places this verb
    saved, 'later' (once per place) for an upcoming move's end that still
    has none. Best-effort: never raises."""
    try:
        lines = _place_coord_register_lines(conn)
        seen = {int(ln.split("\t")[1]) for ln in lines}
        for role, anchor in _map_touched_legs(conn, ids, removed_ids,
                                              now=now):
            try:
                ends = _travel_leg_places(conn, role, anchor)
            except Exception:
                continue
            for pid in ends:
                if (pid is None or pid in seen
                        or not _place_coord_wanted(conn, pid)
                        or _config_stored(conn, _PLACE_COORD_ASKED_KEY % pid)
                        is not None):
                    continue
                seen.add(pid)
                lines.append(_place_coord_line(conn, pid, "later"))
                _config_put(conn, _PLACE_COORD_ASKED_KEY % pid, now_utc())
                conn.commit()
    except (sqlite3.Error, TypeError, ValueError):
        return
    for line in lines:
        print(line)
    if lines:
        print(PLACE_COORD_RELAY)


def _emit_place_coord_pending():
    """main(): the 'register' lines of a verb that saved a place and printed
    no card (travel-place-add, appt-origin, ...). Best-effort."""
    if not _PLACE_COORD_NEW:
        return
    try:
        conn = event_conn()
    except Exception:                                       # noqa: BLE001
        del _PLACE_COORD_NEW[:]
        return
    try:
        lines = _place_coord_register_lines(conn)
    except Exception:                                       # noqa: BLE001
        lines = []
    finally:
        conn.close()
    for line in lines:
        print(line)
    if lines:
        print(PLACE_COORD_RELAY)


def place_coord_store(conn, place_token, lat, lng, naver_ref=None,
                      source="lookup", now=None):
    """Store a place's coordinates as degrees (a lookup that is not a Naver
    directions end). Returns {"result": applied|not_found|bad_coord|
    schema_not_ready, ...}."""
    if not _place_coord_ready(conn):
        return {"result": "schema_not_ready"}
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    try:
        lat, lng = float(lat), float(lng)
    except (TypeError, ValueError):
        return {"result": "bad_coord"}
    if not (-90 <= lat <= 90 and -180 <= lng <= 180):
        return {"result": "bad_coord"}
    now = now or now_utc()
    ref = (naver_ref or "").strip() or None
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT INTO place_coord(place_id, lat, lng, naver_ref, source, "
            "updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(place_id) DO UPDATE "
            "SET lat=excluded.lat, lng=excluded.lng, "
            "naver_ref=excluded.naver_ref, source=excluded.source, "
            "updated_at=excluded.updated_at;",
            (place["id"], round(lat, 7), round(lng, 7), ref,
             (source or "lookup").strip() or "lookup", now))
        _place_coord_clear_missing(conn, place["id"])
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied", "place_id": place["id"],
            "lat": round(lat, 7), "lng": round(lng, 7)}


def place_coord_mark_missing(conn, place_token, now=None):
    """The lookup found nothing (or the owner said no): the place stays
    saved with no coordinates and is asked once later (_emit_place_coord).
    Returns {"result": applied|not_found}."""
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    _config_put(conn, _PLACE_COORD_MISSING_KEY % place["id"],
                now or now_utc())
    conn.commit()
    return {"result": "applied", "place_id": place["id"]}


def _map_search_script():
    """map_search.py (place-manage's keyless-by-name lookup), or None.
    LIFEKIT_MAP_SEARCH overrides ('off' disables the in-verb lookup)."""
    env = os.environ.get("LIFEKIT_MAP_SEARCH", "").strip()
    if env:
        return env if env != "off" and os.path.isfile(env) else None
    here = os.path.dirname(os.path.abspath(__file__))
    for rel in ("../skills-bundle/place-manage/map_search.py",
                "../.claude/skills/place-manage/map_search.py",
                "../skills/place-manage/map_search.py"):
        cand = os.path.normpath(os.path.join(here, rel))
        if os.path.isfile(cand):
            return cand
    return None


def _compact_name(text):
    return re.sub(r"[\s\-_.,()\u00b7]+", "", (text or "")).lower()


def place_coord_autolookup(conn, place_token, now=None):
    """Find an unlocated place on the map by its name (or address) and store
    address + coordinates + naver ref in this call (owner rule 2026-10-08:
    every registration path stores coordinates; a failure never blocks).
    Only a result whose name equals the place's name is taken -- another
    place's position is worse than none. Not found -> the place is marked
    'not located'. {"result": applied|not_found|unavailable|has_coord,
    "place_id"}; never raises on a lookup fault."""
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    pid = place["id"]
    if not _place_coord_ready(conn):
        return {"result": "unavailable", "place_id": pid}
    if place_coord_get(conn, pid) is not None:
        return {"result": "has_coord", "place_id": pid}
    import subprocess
    script = _map_search_script()
    if script is None:
        return {"result": "unavailable", "place_id": pid}
    query = place.get("name") or ""
    try:
        r = subprocess.run([sys.executable, "-I", script, query],
                           capture_output=True, text=True, timeout=25)
        hits = json.loads(r.stdout) if r.returncode == 0 else None
    except (OSError, subprocess.SubprocessError, ValueError):
        hits = None
    if hits is None:
        return {"result": "unavailable", "place_id": pid}
    want = _compact_name(query)
    pick = next((h for h in hits if isinstance(h, dict)
                 and _compact_name(h.get("name")) == want
                 and h.get("lat") is not None and h.get("lng") is not None),
                None)
    if pick is None:
        place_coord_mark_missing(conn, pid, now=now)
        return {"result": "not_found", "place_id": pid}
    res = place_coord_store(conn, pid, pick["lat"], pick["lng"],
                            naver_ref=pick.get("naver_ref"),
                            source="naver_search", now=now)
    if res.get("result") != "applied":
        place_coord_mark_missing(conn, pid, now=now)
        return {"result": "not_found", "place_id": pid}
    if pick.get("address") and not _travel_place_map_string(conn, pid):
        try:
            travel_place_upd(conn, pid, {"address": pick["address"]}, now=now)
        except Exception:                                   # noqa: BLE001
            pass
    return {"result": "applied", "place_id": pid, "lat": res["lat"],
            "lng": res["lng"]}


def place_coord_upcoming(conn, days=14, now=None):
    """Live places with no coordinates that an appointment in the next `days`
    days (or one still running) is held at -- the daily pass's first list,
    whether or not the place has a travel edge. [(place_id, name, start_at,
    appt_ids, has_edge)], soonest first; has_edge = a measured base <-> place
    duration exists (those pairs are driven by place-coord-missing)."""
    if not _place_coord_ready(conn):
        return []
    now = now or now_utc()
    base = _travel_base_place_id(conn)
    try:
        rows = conn.execute(
            "SELECT id, ulid, place_id, start_at FROM timeblock WHERE "
            "kind='appointment' AND COALESCE(block_class,'')<>? AND settled_at IS NULL "
            "AND start_at < ? AND COALESCE(end_at, start_at) >= ? "
            "ORDER BY start_at, id;",
            (TRAVEL_BLOCK_CLASS, _iso_shift_min(now, days * 1440),
             now)).fetchall()
    except sqlite3.Error:
        return []
    found = {}
    for bid, ulid, pid, start in rows:
        ends = [pid]
        try:
            anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE "
                                 "ulid=?;", (ulid,))
            ends.append(_travel_leg_places(conn, "before", anchor)[1])
        except Exception:                                   # noqa: BLE001
            pass
        for e in ends:
            if e is None or e == base:
                continue
            ent = found.setdefault(e, [start, []])
            if bid not in ent[1]:
                ent[1].append(bid)
    out = []
    for pid, (start, bids) in found.items():
        if not _place_coord_wanted(conn, pid):
            continue
        place = travel_place_get(conn, pid) or {}
        try:
            edge = conn.execute(
                "SELECT 1 FROM travel_edge WHERE minutes IS NOT NULL AND "
                "((from_place_id=? AND to_place_id=?) OR (from_place_id=? "
                "AND to_place_id=?)) LIMIT 1;",
                (base, pid, pid, base)).fetchone() is not None
        except sqlite3.Error:
            edge = False
        out.append((pid, place.get("name") or "", start, bids, edge))
    out.sort(key=lambda r: (r[2], r[0]))
    return out


def place_coord_pending(conn):
    """Every live place with no coordinates -- the backfill list for the
    registration rule (one lookup + owner confirm per place). [(id, name,
    address, state)], state 'missing' (lookup failed), 'asked' (asked once
    later) or 'none'."""
    if not _place_coord_ready(conn):
        return []
    out = []
    for (pid,) in conn.execute(
            "SELECT p.id FROM place p WHERE NOT EXISTS (SELECT 1 FROM "
            "place_coord c WHERE c.place_id = p.id) ORDER BY p.id;").fetchall():
        if not _place_coord_wanted(conn, pid):
            continue
        place = travel_place_get(conn, pid) or {}
        state = ("asked" if _config_stored(conn, _PLACE_COORD_ASKED_KEY % pid)
                 else "missing" if _config_stored(
                     conn, _PLACE_COORD_MISSING_KEY % pid) else "none")
        out.append((pid, place.get("name") or "",
                    _travel_place_map_string(conn, pid) or "", state))
    return out


# -- one end of a coordinate backfill drive (owner 2026-10-08) ---------------
# Live run 2026-10-08: place-coord-backfill.sh failed all 21 pairs. The two
# ends were never resolved by the kit before the map was driven:
# travel-resolve.sh --coords-only probed them with raw sqlite3 against a DB
# path it GUESSED (beside $LIFEKIT_SH), typed each end's NAME into the map
# when that probe found no address -- so the base place went in as the bare
# word for home (and the parents' home, a restaurant chain's name) --
# and reported ANY place-coord-set refusal as "neither place is on file".
# place-route-end is the kit's own answer for one end, by the same lookup
# place-coord-set uses: what to drive into the map, or that it cannot be.
#   role  base  the base place (home): routed by its address, else the
#               instance's ROUTE_HOME_ADDR, else NEEDS_ADDRESS
#         stay  a place the owner stays at (a presence block names it, e.g.
#               the parents' home): routed by its address only -- its name
#               is a nickname no map knows -> NEEDS_ADDRESS
#         place anything else: address, else its name (a venue / station
#               name is what the map searches for)
_PLACE_ADDRESS_ASKED_KEY = "place_address_asked_%s"


def place_route_end(conn, place_token):
    """{id, ulid, name, role, address, coord, asked} for one end, or None."""
    place = travel_place_get(conn, place_token)
    if place is None:
        return None
    pid = place["id"]
    if pid == _travel_base_place_id(conn):
        role = "base"
    else:
        try:
            stay = conn.execute(
                "SELECT 1 FROM block WHERE kind_token='presence' AND "
                "place_id=? AND (settled_outcome IS NULL OR "
                "settled_outcome <> 'abandoned') LIMIT 1;",
                (pid,)).fetchone() is not None
        except sqlite3.Error:
            stay = False
        role = "stay" if stay else "place"
    return {"id": pid, "ulid": place.get("ulid") or "",
            "name": place.get("name") or "", "role": role,
            "address": _travel_place_map_string(conn, pid) or "",
            "coord": place_coord_get(conn, pid) is not None,
            "asked": bool(_config_stored(
                conn, _PLACE_ADDRESS_ASKED_KEY % pid))}


def place_address_ask_mark(conn, place_token, now=None):
    """Record that the owner was asked for this place's address (once).
    {"result": applied|already|not_found, "place_id"}."""
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    key = _PLACE_ADDRESS_ASKED_KEY % place["id"]
    if _config_stored(conn, key):
        return {"result": "already", "place_id": place["id"]}
    _config_put(conn, key, now or now_utc())
    conn.commit()
    return {"result": "applied", "place_id": place["id"]}


def map_provider_set(conn, region, providers):
    """The user's pick for a region. providers: list or csv of tokens the
    kit can link. Returns {"result": applied|bad_region|bad_provider, ...}."""
    reg = _region_code(region)
    if reg is None:
        return {"result": "bad_region"}
    if isinstance(providers, str):
        providers = providers.split(",")
    pick = []
    for p in providers:
        p = str(p).strip().lower()
        if not p:
            continue
        if p not in _MAP_LINK_BUILDERS:
            return {"result": "bad_provider", "provider": p}
        if p not in pick:
            pick.append(p)
    if not pick:
        return {"result": "bad_provider", "provider": ""}
    _config_put(conn, _MAP_PROVIDER_KEY % reg, ",".join(pick))
    _config_put(conn, _MAP_PROVIDER_ASKED_KEY % reg, now_utc())
    conn.commit()
    return {"result": "applied", "region": reg, "providers": pick}


def place_region_set(conn, place_token, region, source="agent_lookup",
                     now=None):
    """Store the region a place is in. Upsert, one row per place."""
    if not _map_region_ready(conn):
        return {"result": "schema_not_ready"}
    reg = _region_code(region)
    if reg is None:
        return {"result": "bad_region"}
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    conn.execute(
        "INSERT INTO place_region(place_id, region, source, updated_at) "
        "VALUES(?,?,?,?) ON CONFLICT(place_id) DO UPDATE SET "
        "region=excluded.region, source=excluded.source, "
        "updated_at=excluded.updated_at;",
        (place["id"], reg, (source or "agent_lookup").strip()
         or "agent_lookup", now or now_utc()))
    conn.commit()
    return {"result": "applied", "place_id": place["id"], "region": reg}


def map_region_set(conn, region, providers, label=None, source="agent_lookup",
                   box=None, now=None):
    """Store a region's local map providers (looked up). providers: list /
    csv of linkable tokens, or 'none'. A provider the kit cannot link is
    kept out (reported), never stored. box: (lat_min, lat_max, lng_min,
    lng_max) or None (an existing box is kept)."""
    if not _map_region_ready(conn):
        return {"result": "schema_not_ready"}
    reg = _region_code(region)
    if reg is None:
        return {"result": "bad_region"}
    if isinstance(providers, str):
        providers = [] if providers.strip().lower() == "none" \
            else providers.split(",")
    keep, dropped = [], []
    for p in providers:
        p = str(p).strip().lower()
        if not p or p == MAP_PROVIDER_DEFAULT or p in keep:
            continue
        (keep if p in _MAP_LINK_BUILDERS else dropped).append(p)
    cur = map_region_get(conn, reg)
    if box is None and cur is not None and cur["box"]:
        box = cur["box"]
    b = list(box) if box else [None] * 4
    if label is None and cur is not None:
        label = cur["label"]
    try:
        conn.execute(
            "INSERT INTO map_region(region, label, providers, lat_min, "
            "lat_max, lng_min, lng_max, source, updated_at) "
            "VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(region) DO UPDATE SET "
            "label=excluded.label, providers=excluded.providers, "
            "lat_min=excluded.lat_min, lat_max=excluded.lat_max, "
            "lng_min=excluded.lng_min, lng_max=excluded.lng_max, "
            "source=excluded.source, updated_at=excluded.updated_at;",
            (reg, (label or "").strip() or None, json.dumps(keep), b[0], b[1],
             b[2], b[3], (source or "agent_lookup").strip() or "agent_lookup",
             now or now_utc()))
    except sqlite3.IntegrityError:
        conn.rollback()
        return {"result": "bad_box"}
    conn.commit()
    return {"result": "applied", "region": reg, "providers": keep,
            "not_linkable": dropped}


def place_coord_missing(conn):
    """Known place pairs (a stored travel duration either way) with an end
    that has no 066 coordinates and a region whose local providers need them
    (or no region yet) -- the coordinate backfill list. [(origin_id,
    origin_name, dest_id, dest_name)], one per unordered pair, base first.
    Order (2026-10-15, the daily pass drives a bounded number): pairs on an
    upcoming move leg first, soonest leg first; then the rest by id."""
    try:
        pairs = conn.execute(
            "SELECT DISTINCT from_place_id, to_place_id FROM travel_edge "
            "WHERE minutes IS NOT NULL;").fetchall()
    except sqlite3.Error:
        return []
    base_id = _travel_base_place_id(conn)
    seen, out = set(), []

    def wants(pid):
        reg = place_region_of(conn, pid)[0]
        return reg is None or bool(map_region_local(conn, reg))

    for a, b in pairs:
        if a is None or b is None or a == b:
            continue
        key = (min(a, b), max(a, b))
        if key in seen:
            continue
        seen.add(key)
        if b == base_id:
            a, b = b, a
        if (place_coord_get(conn, a) is not None
                and place_coord_get(conn, b) is not None):
            continue
        if not (wants(a) and wants(b)):
            continue
        pa, pb = travel_place_get(conn, a), travel_place_get(conn, b)
        if not pa or not pb or "gone" in (pa.get("status"), pb.get("status")):
            continue
        out.append((a, pa["name"], b, pb["name"]))
    soon = _travel_upcoming_pair_starts(conn)
    out.sort(key=lambda r: (soon.get((min(r[0], r[2]), max(r[0], r[2])))
                            or "~"))
    return out


def _travel_upcoming_pair_starts(conn, days=14, now=None):
    """{(lo_id, hi_id): earliest start_at} of the live move legs in the next
    `days` days, by the ends an alert would show (_travel_leg_places).
    Best-effort: {} on any fault."""
    out = {}
    now = now or now_utc()
    try:
        rows = conn.execute(
            "SELECT derived_role, derived_from, MIN(start_at) FROM timeblock "
            "WHERE block_class=? AND derived_role IN ('before', 'after') "
            "AND settled_at IS NULL AND start_at > ? AND start_at < ? "
            "GROUP BY derived_role, derived_from;",
            (TRAVEL_BLOCK_CLASS, now, _iso_shift_min(now, days * 1440))
        ).fetchall()
    except sqlite3.Error:
        return out
    for role, ulid, start in rows:
        try:
            anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE "
                                 "ulid=?;", (ulid,))
            o, d = _travel_leg_places(conn, role, anchor)
        except Exception:  # noqa: BLE001 -- ordering only
            continue
        if o is None or d is None or o == d:
            continue
        k = (min(o, d), max(o, d))
        if k not in out or start < out[k]:
            out[k] = start
    return out


# -- place opening hours (067) -------------------------------------------------
# Owner 2026-10-06 14:24: the life agent filed a dentist visit with no time, then told the
# owner to check the clinic's hours / call ahead; the hours were one web
# search away. The kit now keeps hours per place (place_hours) and, when a
# card or a visit needs them and none are on file (or they are stale), prints
#   PLACE_HOURS_NEEDED<TAB><place_id><TAB><name><TAB><address>
# for the AGENT: it looks the hours up silently, stores them with
# place-hours-set, and only then answers. Never a question to the owner.
PLACE_HOURS_NEEDED = "PLACE_HOURS_NEEDED"
PLACE_HOURS_LINE = "PLACE_HOURS"
PLACE_HOURS_DEFAULT = "PLACE_HOURS_DEFAULT"
PLACE_HOURS_STALE_DAYS = 90             # config place_hours_stale_days wins
PLACE_HOURS_STALE_KEY = "place_hours_stale_days"
PLACE_HOURS_VISIT_MIN = 30              # the default slot a no-time visit takes
PLACE_HOURS_RELAY = (
    "PLACE_HOURS_NEEDED names a place whose opening hours are not on file "
    "(or are older than the stale window). Before replying, look them up "
    "yourself, silently (web search / fetch the place's listing by its name "
    "and address), store them with: kit_life.sh place-hours-set <place_id> "
    "'<hours>' --source <url>, then re-run event-card for the touched ids. "
    "A place that keeps no opening hours (a home, a park, an office) or "
    "whose hours the lookup cannot find: place-hours-set <place_id> none "
    "(not looked up again inside the stale window). PLACE_HOURS gives the hours on the item's date: state "
    "the closing time in the reply; a visit with no time takes "
    "PLACE_HOURS_DEFAULT. A card row flagged outside the hours: say so and "
    "offer the nearest time inside them. Never tell the owner to check the "
    "hours or to call the place, and never ask the owner for them; if the "
    "lookup finds nothing, say nothing about hours. Never print these lines or this one.")
_HOURS_DAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
# Korean day words, \u-escaped (code stays ASCII): mon..sun single syllables,
# then weekdays / weekend / every day / public holiday / holiday.
_HOURS_KO_DAY = {u"\uc6d4": "mon", u"\ud654": "tue", u"\uc218": "wed",
                 u"\ubaa9": "thu", u"\uae08": "fri", u"\ud1a0": "sat",
                 u"\uc77c": "sun"}
_HOURS_GROUPS = (
    (u"\uacf5\ud734\uc77c", ("holiday",)),            # public holiday
    (u"\ubc95\uc815\ud734\uc77c", ("holiday",)),      # statutory holiday
    (u"\ud734\uc77c", ("holiday",)),                  # holiday
    (u"\ud3c9\uc77c", _HOURS_DAYS[:5]),               # weekdays
    (u"\uc8fc\ub9d0", _HOURS_DAYS[5:]),               # weekend
    (u"\ub9e4\uc77c", _HOURS_DAYS),                   # every day
    ("holidays", ("holiday",)), ("holiday", ("holiday",)),
    ("weekdays", _HOURS_DAYS[:5]), ("weekday", _HOURS_DAYS[:5]),
    ("weekends", _HOURS_DAYS[5:]), ("weekend", _HOURS_DAYS[5:]),
    ("everyday", _HOURS_DAYS), ("daily", _HOURS_DAYS),
)
_HOURS_CLOSED_WORDS = (u"\ud734\ubb34", u"\ud734\uc9c4", u"\ud734\uc5c5",
                       u"\ud734\uad00", "closed", "off")   # closed / no clinic
_HOURS_BREAK_WORDS = (u"\uc810\uc2ec", u"\ud734\uac8c",
                      u"\ube0c\ub808\uc774\ud06c", "lunch", "break")
_HOURS_NONE_WORDS = ("none", "n/a", "na")
_HOURS_RANGE_RE = re.compile(
    r"(\d{1,2}):(\d{2})\s*[-~\u2013\u2014\u301c\uff5e]\s*(\d{1,2}):(\d{2})")
_HOURS_EN_DAY_RE = re.compile(
    r"\b(mon|tue|wed|thu|fri|sat|sun)[a-z]*\b(?:\s*[-~]\s*"
    r"\b(mon|tue|wed|thu|fri|sat|sun)[a-z]*\b)?")


def _hours_hm(h, m):
    h, m = int(h), int(m)
    if not (0 <= h <= 24 and 0 <= m < 60) or (h == 24 and m):
        raise ValueError("bad time %02d:%02d" % (h, m))
    return "%02d:%02d" % (h, m)


def _hours_range(text):
    """'09:30-18:30' / ['09:30','18:30'] -> ('09:30','18:30'), open < close."""
    if isinstance(text, (list, tuple)) and len(text) == 2:
        text = "%s-%s" % tuple(text)
    m = _HOURS_RANGE_RE.fullmatch(str(text or "").strip())
    if not m:
        raise ValueError("not a HH:MM-HH:MM range: %r" % (text,))
    a, b = _hours_hm(m.group(1), m.group(2)), _hours_hm(m.group(3), m.group(4))
    if not a < b:
        raise ValueError("range must open before it closes: %s-%s" % (a, b))
    return a, b


def _hours_span(i, j):
    """Day keys from index i to j inclusive, wrapping past Sunday."""
    out = []
    while True:
        out.append(_HOURS_DAYS[i])
        if i == j:
            return out
        i = (i + 1) % 7


def _hours_days_in(text):
    """Day keys named in one text part (+ 'holiday'), in week order."""
    found = set()
    t = text.lower()
    for word, keys in _HOURS_GROUPS:
        if word in t:
            found.update(keys)
            t = t.replace(word, " ")
    t = t.replace(u"\uc694\uc77c", "")        # '...yoil' suffix
    ko = "".join(_HOURS_KO_DAY)
    for m in re.finditer(u"([%s])\\s*[-~]\\s*([%s])" % (ko, ko), t):
        found.update(_hours_span(
            _HOURS_DAYS.index(_HOURS_KO_DAY[m.group(1)]),
            _HOURS_DAYS.index(_HOURS_KO_DAY[m.group(2)])))
    t = re.sub(u"([%s])\\s*[-~]\\s*([%s])" % (ko, ko), " ", t)
    for m in _HOURS_EN_DAY_RE.finditer(t):
        i = _HOURS_DAYS.index(m.group(1))
        j = _HOURS_DAYS.index(m.group(2)) if m.group(2) else i
        found.update(_hours_span(i, j))
    t = _HOURS_EN_DAY_RE.sub(" ", t)
    for ch in t:
        if ch in _HOURS_KO_DAY:
            found.add(_HOURS_KO_DAY[ch])
    return [d for d in _HOURS_DAYS + ("holiday",) if d in found]


def _hours_day_value(v):
    """One day's value -> 'closed' | 'open' (holiday only) | {open, close,
    breaks}."""
    if isinstance(v, str) and v.strip().lower() in ("closed", "open"):
        return v.strip().lower()
    if isinstance(v, dict):
        a, b = _hours_range([v.get("open"), v.get("close")])
        brs = [list(_hours_range(x)) for x in (v.get("breaks") or [])]
        return {"open": a, "close": b, "breaks": brs}
    a, b = _hours_range(v)
    return {"open": a, "close": b, "breaks": []}


def _hours_finish(days, holiday, breaks_all):
    """Apply day-less breaks to every open day whose hours hold them, then
    validate and sort. Returns the normalized document."""
    placed = set()
    for d, v in list(days.items()):
        if not isinstance(v, dict):
            continue
        brs = [tuple(b) for b in v["breaks"]]
        for b in breaks_all:
            if v["open"] <= b[0] and b[1] <= v["close"]:
                placed.add(tuple(b))
                if tuple(b) not in brs:
                    brs.append(tuple(b))
        for b in brs:
            if not (v["open"] <= b[0] and b[1] <= v["close"]):
                raise ValueError("break %s-%s is outside %s %s-%s"
                                 % (b[0], b[1], d, v["open"], v["close"]))
        v["breaks"] = [list(b) for b in sorted(set(brs))]
    lost = [b for b in breaks_all if tuple(b) not in placed]
    if lost:
        raise ValueError("break %s-%s fits no day's hours" % tuple(lost[0]))
    if not days and holiday is None:
        raise ValueError("no day carries hours")
    doc = {"days": {d: days[d] for d in _HOURS_DAYS if d in days}}
    if holiday is not None:
        doc["holiday"] = holiday
    return doc


def _hours_parse_json(obj):
    if not isinstance(obj, dict):
        raise ValueError("hours JSON must be an object")
    if obj.get("none") is True:
        return {"none": True}
    src = obj.get("days") if isinstance(obj.get("days"), dict) else obj
    days, holiday, breaks_all = {}, None, []
    for raw in (obj.get("breaks"), obj.get("break")):
        if not raw:
            continue
        # one range ("13:00-14:00" or ["13:00","14:00"]) or a list of them
        one = isinstance(raw, str) or (
            isinstance(raw, list) and len(raw) == 2
            and all(isinstance(x, str) and _HOURS_RANGE_RE.search(x) is None
                    for x in raw))
        breaks_all.extend(_hours_range(x) for x in ([raw] if one else raw))
    for key, v in src.items():
        k = str(key).strip().lower()
        if k in ("days", "break", "breaks", "none", "source", "source_url"):
            continue
        keys = _hours_days_in(k)
        if not keys:
            raise ValueError("unknown day key: %r" % (key,))
        val = _hours_day_value(v)
        for d in keys:
            if d == "holiday":
                holiday = val
            elif val == "open":
                raise ValueError("'open' is a holiday value only")
            else:
                days[d] = val
    if "holiday" in obj and "days" in obj:
        holiday = _hours_day_value(obj["holiday"])
    return _hours_finish(days, holiday, breaks_all)


def _hours_parse_text(text):
    days, holiday, breaks_all = {}, None, []
    segs = [s.strip() for s in re.split(r"[,;\n|]+", text) if s.strip()]
    for n, seg in enumerate(segs):
        low = seg.lower()
        pos = min([low.find(w) for w in _HOURS_BREAK_WORDS if w in low]
                  or [len(low)])
        head, tail = low[:pos], low[pos:]
        h_ranges = [_hours_range(m.group(0))
                    for m in _HOURS_RANGE_RE.finditer(head)]
        b_ranges = [_hours_range(m.group(0))
                    for m in _HOURS_RANGE_RE.finditer(tail)]
        keys = _hours_days_in(_HOURS_RANGE_RE.sub(" ", head))
        words = re.findall(r"[a-z]+", head)
        closed = any((w in words) if w.isascii() else (w in head)
                     for w in _HOURS_CLOSED_WORDS)
        if not keys and not h_ranges and not closed:
            if not b_ranges:
                raise ValueError("cannot read: %r" % seg)
            breaks_all.extend(b_ranges)          # a day-less break
            continue
        if not keys:
            if n > 0 or closed:
                raise ValueError("no day named in: %r" % seg)
            keys = list(_HOURS_DAYS)             # '09:00-18:00' alone
        if closed:
            val = "closed"
        elif len(h_ranges) == 1:
            val = {"open": h_ranges[0][0], "close": h_ranges[0][1],
                   "breaks": [list(b) for b in b_ranges]}
        elif not h_ranges and b_ranges:
            for d in keys:                       # 'weekdays lunch 13-14'
                if isinstance(days.get(d), dict):
                    days[d]["breaks"].extend(list(b) for b in b_ranges)
                else:
                    raise ValueError("break before hours for %s" % d)
            continue
        else:
            raise ValueError("one range per part, got %d: %r"
                             % (len(h_ranges), seg))
        for d in keys:
            if d == "holiday":
                holiday = val
            else:
                days[d] = (dict(val, breaks=list(val["breaks"]))
                           if isinstance(val, dict) else val)
    return _hours_finish(days, holiday, breaks_all)


def place_hours_parse(raw):
    """Opening hours in JSON or in words -> the normalized document stored in
    place_hours.hours (see migrations/067). Raises ValueError, loud: a wrong
    week is worse than none.

    JSON: {"days": {...}, "holiday": ...} (the stored shape), or flat day
    keys ("mon".."sun", "weekdays", "weekend", "daily", "holiday", Korean day
    words) to "HH:MM-HH:MM" | [open, close] | {open, close, breaks} |
    "closed"; "break(s)": ranges applied to every open day that holds them;
    {"none": true} = the place keeps no opening hours.
    Text: parts split on , ; | or newline, each '<days> HH:MM-HH:MM [lunch
    HH:MM-HH:MM]' or '<days> closed', e.g. the Korean listing form
    'weekdays 09:30-18:30 (lunch 13:00-14:00), sat 09:30-14:30, sun/holiday
    closed'. A part with no day applies to every day only when it is first."""
    if isinstance(raw, dict):
        return _hours_parse_json(raw)
    text = str(raw or "").strip()
    if not text:
        raise ValueError("empty hours")
    if text.lower() in _HOURS_NONE_WORDS:
        return {"none": True}
    if text.startswith("{"):
        try:
            obj = json.loads(text)
        except ValueError as e:
            raise ValueError("bad JSON: %s" % e)
        return _hours_parse_json(obj)
    return _hours_parse_text(text)


def _place_hours_ready(conn):
    try:
        return conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='place_hours';").fetchone() is not None
    except sqlite3.Error:
        return False


def _place_hours_today(now=None):
    inst = now or now_utc()
    return _local_date_of(canonical(inst), TRAVEL_DISPLAY_TZ)


def _place_hours_stale_days(conn):
    try:
        row = conn.execute("SELECT TRIM(value) FROM config WHERE key=?;",
                           (PLACE_HOURS_STALE_KEY,)).fetchone()
        if row is not None and str(row[0]).isdigit() and int(row[0]) > 0:
            return int(row[0])
    except sqlite3.Error:
        pass
    return PLACE_HOURS_STALE_DAYS


def place_hours_get(conn, place_id, now=None):
    """{hours, source_url, fetched_on, stale} of a place, or None (no row, or
    a pre-067 store)."""
    if place_id is None or not _place_hours_ready(conn):
        return None
    row = conn.execute(
        "SELECT hours, source_url, fetched_on FROM place_hours "
        "WHERE place_id=?;", (place_id,)).fetchone()
    if row is None:
        return None
    try:
        hours = json.loads(row[0])
    except ValueError:
        return None
    try:
        age = (_place_hours_today(now)
               - datetime.date.fromisoformat(row[2])).days
    except ValueError:
        age = None
    return {"hours": hours, "source_url": row[1], "fetched_on": row[2],
            "stale": age is None or age > _place_hours_stale_days(conn)}


def place_hours_set(conn, place_token, raw, source_url=None, fetched_on=None,
                    now=None):
    """Store a place's opening hours (upsert, one row per place). Returns
    {"result": applied|not_found|bad_hours|schema_not_ready, ...}."""
    if not _place_hours_ready(conn):
        return {"result": "schema_not_ready"}
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    try:
        doc = place_hours_parse(raw)
    except ValueError as e:
        return {"result": "bad_hours", "error": str(e)}
    if fetched_on is None:
        fetched_on = _place_hours_today(now).isoformat()
    else:
        try:
            fetched_on = datetime.date.fromisoformat(fetched_on).isoformat()
        except ValueError:
            return {"result": "bad_hours",
                    "error": "fetched date must be YYYY-MM-DD"}
    src = (source_url or "").strip() or None
    text = json.dumps(doc, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"))
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT INTO place_hours(place_id, hours, source_url, fetched_on, "
            "updated_at) VALUES(?,?,?,?,?) ON CONFLICT(place_id) DO UPDATE "
            "SET hours=excluded.hours, source_url=excluded.source_url, "
            "fetched_on=excluded.fetched_on, updated_at=excluded.updated_at;",
            (place["id"], text, src, fetched_on, now or now_utc()))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied", "place_id": place["id"],
            "name": place.get("name"), "hours": doc, "fetched_on": fetched_on}


def _hours_is_holiday(date):
    try:
        import holiday_source
        return bool(holiday_source.is_holiday(date))
    except Exception:
        return False


def place_hours_on(conn, place_id, date, now=None):
    """The hours of one place on one local date:
      {"state": "open", "open", "close", "breaks", "why": weekday|holiday}
      {"state": "closed", "why": weekday|holiday}
      {"state": "unknown", "why": no_row|no_day|holiday}
      {"state": "none"}   the place keeps no opening hours
    plus "stale" / "source_url" / "fetched_on" when a row exists."""
    if isinstance(date, str):
        date = datetime.date.fromisoformat(date)
    rec = place_hours_get(conn, place_id, now=now)
    if rec is None:
        return {"state": "unknown", "why": "no_row", "stale": True}
    meta = {"stale": rec["stale"], "source_url": rec["source_url"],
            "fetched_on": rec["fetched_on"]}
    hours = rec["hours"]
    if hours.get("none"):
        return dict(meta, state="none")
    val, why = None, "weekday"
    if _hours_is_holiday(date):
        why = "holiday"
        val = hours.get("holiday")
        if val is None:
            return dict(meta, state="unknown", why="holiday")
    if val is None or val == "open":
        val = (hours.get("days") or {}).get(_HOURS_DAYS[date.weekday()])
    if val is None:
        return dict(meta, state="unknown", why="no_day")
    if val == "closed":
        return dict(meta, state="closed", why=why)
    return dict(meta, state="open", why=why, open=val["open"],
                close=val["close"], breaks=[tuple(b) for b in val["breaks"]])


def _hours_min(hm):
    return int(hm[:2]) * 60 + int(hm[3:])


def place_hours_default_start(day, date, now=None,
                              visit_min=PLACE_HOURS_VISIT_MIN):
    """First start on the 30-minute grid inside the hours of `day` (a
    place_hours_on 'open' result) where a visit of visit_min fits before the
    close and clear of every break; on today, not before now. 'HH:MM' or
    None (nothing fits)."""
    if day.get("state") != "open":
        return None
    lo, hi = _hours_min(day["open"]), _hours_min(day["close"])
    if isinstance(date, str):
        date = datetime.date.fromisoformat(date)
    inst = canonical(now or now_utc())
    local = (datetime.datetime.strptime(inst, "%Y-%m-%dT%H:%M:%SZ")
             .replace(tzinfo=timezone.utc)
             .astimezone(ZoneInfo(TRAVEL_DISPLAY_TZ)))
    if local.date() == date:
        lo = max(lo, local.hour * 60 + local.minute)
    elif local.date() > date:
        return None
    t = -(-lo // 30) * 30
    brs = [(_hours_min(a), _hours_min(b)) for a, b in day.get("breaks") or ()]
    while t + visit_min <= hi:
        clash = [b for b in brs if t < b[1] and b[0] < t + visit_min]
        if not clash:
            return "%02d:%02d" % (t // 60, t % 60)
        t = -(-max(b[1] for b in clash) // 30) * 30
    return None


def place_hours_flag(day, start_hm):
    """Why a visit starting at start_hm does not fit `day`: 'closed' |
    'outside' | 'break' | None (fits, or the hours are not known)."""
    if day.get("state") == "closed":
        return "closed"
    if day.get("state") != "open" or not start_hm:
        return None
    if not (day["open"] <= start_hm < day["close"]):
        return "outside"
    for a, b in day.get("breaks") or ():
        if a <= start_hm < b:
            return "break"
    return None


def _hours_breaks_text(day):
    return ",".join("%s-%s" % tuple(b) for b in day.get("breaks") or ()) or "-"


def _place_hours_block(conn, eid, now=None):
    """The hours view of one block: None when hours do not apply (not a live
    appointment / task, no place, home, a derived leg, a past day); else
    {"eid", "place", "date", "day", "start_hm", "all_day", "flag",
    "needed"}. READ ONLY; never raises."""
    try:
        row = conn.execute(
            "SELECT kind, place_id, start_at, schedule_kind, settled_at, "
            "block_class FROM timeblock WHERE id=?;", (int(eid),)).fetchone()
    except (sqlite3.Error, TypeError, ValueError):
        return None
    if row is None or row[0] not in ("appointment", "task") or row[1] is None:
        return None
    if row[4] is not None or row[5] is not None:
        return None
    try:
        place = travel_place_get(conn, int(row[1]))
    except Exception:
        place = None
    if not place or place.get("is_base") or place.get("status") == "gone":
        return None
    today = _place_hours_today(now)
    start_hm, all_day = None, True
    if row[2]:
        try:
            local = (datetime.datetime.strptime(row[2], "%Y-%m-%dT%H:%M:%SZ")
                     .replace(tzinfo=timezone.utc)
                     .astimezone(ZoneInfo(TRAVEL_DISPLAY_TZ)))
        except ValueError:
            return None
        date = local.date()
        if row[3] != "all_day":
            start_hm, all_day = local.strftime("%H:%M"), False
    else:
        date = today
    if date < today:
        return None
    try:
        day = place_hours_on(conn, place["id"], date, now=now)
    except Exception:
        return None
    return {"eid": int(eid), "place": place, "date": date, "day": day,
            "start_hm": start_hm, "all_day": all_day,
            # an errand takes no visit time (errand.py): no default start
            "errand": all_day and row[0] == "task",
            "flag": place_hours_flag(day, start_hm),
            "needed": bool(day.get("stale"))}


def _place_hours_needed_line(conn, place):
    addr = (_travel_place_map_string(conn, place["id"])
            or place.get("address") or "")
    return "%s\t%s\t%s\t%s" % (PLACE_HOURS_NEEDED, place["id"],
                               _travel_signal_field(place.get("name") or ""),
                               _travel_signal_field(addr))


def _place_hours_open_line(prefix, key, place, date, day):
    st = day.get("state", "unknown").upper()
    if st == "OPEN":
        tail = "%s\t%s\t%s" % (day["open"], day["close"],
                               _hours_breaks_text(day))
    else:
        tail = "-\t-\t%s" % (day.get("why") or "-")
    return "%s\t%s\t%s\t%s\t%s\t%s\t%s" % (
        prefix, key, place["id"], _travel_signal_field(place.get("name") or ""),
        date.isoformat(), st, tail)


def _emit_place_hours(conn, ids, removed_ids=(), now=None):
    """For the touched blocks at a place: PLACE_HOURS_NEEDED once per place
    with no (or stale) hours, PLACE_HOURS<TAB><id><TAB><place_id><TAB><name>
    <TAB><date><TAB>OPEN|CLOSED|UNKNOWN<TAB><open|-><TAB><close|-><TAB>
    <breaks|why> per block whose hours are known, PLACE_HOURS_DEFAULT<TAB>
    <id><TAB><HH:MM> for a no-time visit, then the relay. Prints nothing
    when no touched block is at a place that keeps hours."""
    removed = set(int(i) for i in (removed_ids or ()) if str(i).isdigit())
    out, asked = [], set()
    for raw in ids or ():
        try:
            if int(raw) in removed:
                continue
        except (TypeError, ValueError):
            continue
        v = _place_hours_block(conn, raw, now=now)
        if v is None:
            continue
        pid = v["place"]["id"]
        if v["needed"] and pid not in asked:
            asked.add(pid)
            out.append(_place_hours_needed_line(conn, v["place"]))
        if v["day"].get("why") == "no_row" or v["day"]["state"] == "none":
            continue
        out.append(_place_hours_open_line(PLACE_HOURS_LINE, v["eid"],
                                          v["place"], v["date"], v["day"]))
        if v["all_day"] and not v.get("errand"):
            d = place_hours_default_start(v["day"], v["date"], now=now)
            if d:
                out.append("%s\t%s\t%s" % (PLACE_HOURS_DEFAULT, v["eid"], d))
    if not out:
        return
    for line in out:
        print(line)
    print("PLACE_HOURS_RELAY " + PLACE_HOURS_RELAY)


def _place_hours_card_flag(conn, eid, now=None):
    """The card suffix of a row whose start falls outside its place's known
    hours ('' when it fits or nothing is known)."""
    v = _place_hours_block(conn, eid, now=now)
    if v is None or not v["flag"]:
        return ""
    day = v["day"]
    try:
        if v["flag"] == "closed":
            return _day_i18n("day.card.hours_closed")
        if v["flag"] == "break":
            b = [x for x in day["breaks"] if x[0] <= v["start_hm"] < x[1]][0]
            return _day_i18n("day.card.hours_break").format(
                start=b[0], end=b[1])
        return _day_i18n("day.card.hours_outside").format(
            open=day["open"], close=day["close"])
    except (KeyError, IndexError, ValueError):
        return ""

def _ceil_grid(minutes):
    """15-min grid ceil (2.4): travel under-allocation is the failure mode
    (late), over-allocation is slack -- ceil is the safe side."""
    m = int(minutes)
    if m < 0:
        raise ValueError("negative minutes refused: %r" % minutes)
    g = TRAVEL_GRID_MIN
    return ((m + g - 1) // g) * g


def _iso_shift_min(ts, minutes):
    """Canonical UTC instant shifted by minutes (+/-)."""
    dt = datetime.datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")
    return (dt + timedelta(minutes=int(minutes))).strftime("%Y-%m-%dT%H:%M:%SZ")


def _iso_diff_min(a, b):
    """Whole minutes of (a - b) for canonical instants."""
    da = datetime.datetime.strptime(a, "%Y-%m-%dT%H:%M:%SZ")
    db = datetime.datetime.strptime(b, "%Y-%m-%dT%H:%M:%SZ")
    return int((da - db).total_seconds() // 60)


def _iso_dt(ts):
    """Canonical UTC instant -> naive datetime (UTC wall clock)."""
    return datetime.datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")


def _iso_fmt(dt):
    """Naive UTC datetime -> canonical UTC instant. Inverse of _iso_dt.
    Second-exact: durations are preserved as an absolute delta, not rounded
    to whole minutes the way _iso_shift_min/_iso_diff_min do."""
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _travel_state_conn(state_conn=None):
    """Best-effort mirror state db handle (outbox + never-mirrored reads).
    None on failure -- callers treat that as 'tombstone path, never DELETE'
    (0.1 pin, safe side)."""
    if state_conn is not None:
        return state_conn
    try:
        path = _mirror_state_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        sc = sqlite3.connect(path)
        sc.execute("PRAGMA journal_mode=WAL")
        sc.execute("PRAGMA busy_timeout=5000")
        sc.executescript(_STATE_MIN_DDL)
        sc.commit()
        return sc
    except Exception:
        return None


def _travel_outbox(state_conn, ulid):
    """Idempotent outbox enqueue on a state handle (adapter semantics)."""
    if state_conn is None:
        return False
    now = now_utc()
    try:
        state_conn.execute(
            "INSERT INTO mirror_outbox(event_ulid, op, status, created_at, "
            "updated_at) VALUES(?, 'sync', 'queued', ?, ?)", (ulid, now, now))
        state_conn.commit()
        return True
    except sqlite3.IntegrityError:
        state_conn.rollback()
        return False


def _travel_log(conn, category, rule_ulid=None, detail=None, now=None):
    """Audit line in roller_log (shared table; travel categories are
    namespaced 'travel_*' and keyed by travel_rule.ulid in the
    recurrence_id column -- the roller's recurrence_id key is NOT reused,
    blocks carry recurrence_id NULL (3.1 churn key pin))."""
    conn.execute(
        "INSERT INTO roller_log(ts, recurrence_id, category, detail) "
        "VALUES(?,?,?,?);", (now or now_utc(), rule_ulid, category, detail))
    conn.commit()


def _travel_row(conn, sql, params):
    old = conn.row_factory
    conn.row_factory = sqlite3.Row
    try:
        r = conn.execute(sql, params).fetchone()
        return dict(r) if r is not None else None
    finally:
        conn.row_factory = old


def _travel_rows(conn, sql, params):
    old = conn.row_factory
    conn.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in conn.execute(sql, params).fetchall()]
    finally:
        conn.row_factory = old


# ── v3.2 travel store (place_link + measure) ──────────────────────────────
# v3.2 has no travel_edge TABLE and no to_min/from_min/prep_min node columns.
# The pair's identity is a place_link row; the number is a measure row
# (metric 'travel_min' / 'travel_prep_min', unit 'min') carrying provenance
# and valid_until -- a duration is a dated, sourced, expirable answer, not a
# fixed property of the pair.  READS keep working through the old names: the
# compat layer ships a read-only travel_edge VIEW (no INSTEAD OF, by design),
# so every SELECT in this file is covered.  WRITES cannot go through the view
# and must not try -- the _travel_v32_* helpers below are the only write door.

TRAVEL_METRIC_MIN = "travel_min"        # one-way movement duration (min)
TRAVEL_METRIC_PREP = "travel_prep_min"  # prep before departing on this leg


def _travel_v32_ensure_metrics(conn):
    """The travel lane carries its own metric rows (design B-3: the kit seeds
    no metrics -- the module that writes a metric registers it). Idempotent."""
    for tok in (TRAVEL_METRIC_MIN, TRAVEL_METRIC_PREP):
        conn.execute(
            "INSERT OR IGNORE INTO metric_def"
            "(token, scope_kind, accrual, unit_token, owner_module, origin) "
            "VALUES(?, 'place_link', 'observed', 'min', 'life', 'module');",
            (tok,))


def _travel_v32_link_id(conn, from_id, to_id, create=False):
    """place_link id for the ORDERED pair; optionally mint it."""
    row = conn.execute(
        "SELECT id FROM place_link WHERE from_place_id=? AND to_place_id=?;",
        (int(from_id), int(to_id))).fetchone()
    if row is not None:
        return row[0]
    if not create:
        return None
    if int(from_id) == int(to_id):
        raise ValueError("place_link: from and to must differ")
    cur = conn.execute(
        "INSERT INTO place_link(from_place_id, to_place_id, created_at) "
        "VALUES(?,?,?);", (int(from_id), int(to_id), now_utc()))
    return cur.lastrowid


def _travel_v32_set(conn, link_id, metric, minutes, value_origin="declared",
                    source="user", now=None):
    """Supersede-and-insert (the goal_target discipline: a value in force is
    never edited -- the old row gets valid_until stamped, the new row is the
    answer from now on). minutes=None RETRACTS: the in-force row expires and
    nothing replaces it -- "no row" is how v3.2 says unknown.
    Same-second re-declare is treated as a correction of the same declaration
    (ux_measure_row would otherwise reject the second insert). That holds
    whether or not a retract happened in between (2026-09-05 review F4:
    declare -> retract -> declare in one second must land the last value):
    the same-second row is REUSED -- value corrected, valid_until cleared --
    rather than observed_at advanced, because observed_at is when the owner
    actually declared; minting a fabricated future second would outrun every
    `ORDER BY observed_at` read and put a lie in the history. ux_measure_row
    stays untouched -- one row per (link, metric, basis, second) is exactly
    what makes "reuse" well-defined."""
    now = now or now_utc()
    _travel_v32_ensure_metrics(conn)
    if minutes is not None:
        cur = conn.execute(
            "SELECT id FROM measure WHERE place_link_id=? AND metric=? "
            "AND basis='actual' AND observed_at=?;",
            (link_id, metric, now)).fetchone()
        if cur is not None:
            # defensive: expire any OTHER in-force row first, so the revive
            # below can never seat two answers at once.
            conn.execute(
                "UPDATE measure SET valid_until=? WHERE place_link_id=? "
                "AND metric=? AND basis='actual' AND id != ? "
                "AND (valid_until IS NULL OR valid_until > ?);",
                (now, link_id, metric, cur[0], now))
            conn.execute(
                "UPDATE measure SET value=?, value_origin=?, source=?, "
                "valid_until=NULL WHERE id=?;",
                (float(minutes), value_origin, source, cur[0]))
            return
    conn.execute(
        "UPDATE measure SET valid_until=? WHERE place_link_id=? AND metric=? "
        "AND basis='actual' AND (valid_until IS NULL OR valid_until > ?);",
        (now, link_id, metric, now))
    if minutes is None:
        return
    conn.execute(
        "INSERT INTO measure(metric, value, unit, basis, place_link_id, "
        "observed_at, source, value_origin) "
        "VALUES(?,?, 'min', 'actual', ?, ?, ?, ?);",
        (metric, float(minutes), link_id, now, source, value_origin))


def _travel_place_row_v32(conn, where_sql, params):
    """A place row shaped like the OLD one: `name` is reconstructed from the
    label layer (v3.2 stores an ASCII token; the human string lives in label).
    aliases/note are served from the place row itself -- 036 rebuilds place
    KEEPING both columns (X-5 closed), so hardcoding them to NULL here made
    real alias data invisible (2026-09-05 review F1)."""
    return _travel_row(
        conn,
        "SELECT p.id, p.ulid, p.token, p.address, p.is_base, p.status, "
        "COALESCE(l.display, p.token) AS name, p.aliases, p.note "
        "FROM place p LEFT JOIN label l ON l.namespace='place' "
        "AND l.token=p.token AND l.lang='ko' " + where_sql, params)


def _travel_place_decorate_v32(conn, row):
    """Old readers expect base-origin to_min/from_min/prep_min keys on a place
    dict. Under v3.2 those are READ-SURFACE derivations from the base pair's
    current measures -- stored nowhere on the place (single home: measure)."""
    if row is None:
        return None
    to_min = from_min = prep_min = None
    base = _travel_base_place_id(conn)
    if base is not None and base != row["id"]:
        e = _travel_edge_get(conn, base, row["id"])
        if e is not None:
            to_min, prep_min = e["minutes"], e["prep_min"]
        e = _travel_edge_get(conn, row["id"], base)
        if e is not None:
            from_min = e["minutes"]
    row["to_min"], row["from_min"], row["prep_min"] = to_min, from_min, prep_min
    return row


def _place_slug(name):
    """ASCII stable key, matching the migration's rule: Korean degrades to ''
    and the caller falls back to a deterministic id-based token."""
    import unicodedata
    out = ''.join(c if c.isascii() and (c.isalnum() or c in '_-') else '_'
                  for c in unicodedata.normalize('NFKD', name or ''))
    return '_'.join(filter(None, out.lower().split('_')))


# ── 050: address layer + sub-place layer ──────────────────────────────────
# The three layers the owner decided on 2026-09-12 (migrations/050):
#   place         the terminus of a trip.  place_link/measure attach HERE.
#   place_address the strings a MAP resolves.  Many per place, one primary.
#   sub_place     room / floor / suite / hall.  NOT a terminus, structurally.
#
# `place.address` still exists and every pre-050 reader still reads it --
# routines/bundle/travel-resolve.sh does so in raw SQL -- but since 050 it is a
# DERIVED MIRROR of the primary address row, maintained by trigger and refused
# to any direct writer.  So every function below writes place_address and lets
# the mirror follow; nothing here ever issues `UPDATE place SET address=`.

PLACE_ADDRESS_KINDS = ("road", "lot", "building", "map_url", "legacy")


def _place_split_ready(conn):
    """True iff the 050 tables exist.  Pre-050 databases degrade to the single
    `place.address` column exactly as they did at 049 -- the same fail-open
    shape _travel_edge_schema_ready uses, so a mid-rollout DB never hard-fails."""
    try:
        return conn.execute(
            "SELECT COUNT(*) FROM sqlite_master WHERE type='table' "
            "AND name IN ('place_address','sub_place');").fetchone()[0] == 2
    except sqlite3.Error:
        return False


def place_address_classify(value):
    """kind for an address string, or None for a blank.

    THE SAME RULE migration 050 backfilled with, restated here because this is
    the write path the rule has to hold on tomorrow's strings too -- and a
    second, looser classifier would reintroduce exactly the guessing 050
    refuses.  Only two shapes are settled by the string's own structure:

      map_url  starts http:// or https://.  A URL is not a street.
      road     a road-name token immediately followed by a building number
               (도로명 + 건물번호) -- the defining shape of a Korean road-name
               address, and no other address shape produces it.
      legacy   EVERYTHING ELSE -- an honest "not classified", to be re-tagged
               by the next map resolution.

    `lot` and `building` are assigned by nothing automatic, on purpose: the
    obvious lot rule ("<x>동 <number>") also matches an apartment block
    ("…아파트 112동 903호"), which makes it a coin flip, not a classification
    (038: never invent a value to fill a column).  The caller may always state
    the kind explicitly -- that is a person answering, not the machine guessing.
    """
    v = str(value or "").strip()
    if not v:
        return None
    if v.startswith("http://") or v.startswith("https://"):
        return "map_url"
    if re.search(r"[로길] [0-9]", v):
        return "road"
    return "legacy"


def place_address_list(conn, place_id):
    """Every address string on file for a place, primary first."""
    if not _place_split_ready(conn):
        return []
    return _travel_rows(
        conn, "SELECT * FROM place_address WHERE place_id=? "
        "ORDER BY is_primary DESC, id;", (place_id,))


def place_address_primary(conn, place_id):
    """The one string handed to the map, or None."""
    if not _place_split_ready(conn):
        row = conn.execute("SELECT address FROM place WHERE id=?;",
                           (place_id,)).fetchone()
        return (row[0] if row else None) or None
    row = conn.execute(
        "SELECT value FROM place_address WHERE place_id=? AND is_primary=1;",
        (place_id,)).fetchone()
    return row[0] if row else None


def place_address_add(conn, place_id, value, kind=None, primary=None,
                      now=None):
    """Teach a place one more string that points at it.

    kind=None classifies by structure (place_address_classify); an explicit
    kind is stored as given -- the caller is a person answering a question, and
    'lot'/'building' can only ever arrive that way.

    primary: None means "primary iff this place has none yet" -- the first
    address a place learns is the one the map gets, and a later one does not
    silently steal the wheel.  True promotes it (demoting whatever held it),
    False never promotes.  Re-teaching a string already on file UPDATES its
    kind instead of duplicating the row (the value is the row identity).

    Returns the place_address row dict.  The `place.address` mirror follows by
    trigger, in the same transaction."""
    v = str(value or "").strip()
    if not v:
        raise ValueError("place_address_add: value required")
    if not _place_split_ready(conn):
        raise ValueError(
            "place_address_add: this database predates migration 050 -- the "
            "address layer does not exist yet")
    k = kind or place_address_classify(v)
    if k not in PLACE_ADDRESS_KINDS:
        raise ValueError("place_address_add: kind must be one of %s"
                         % (PLACE_ADDRESS_KINDS,))
    now = now or now_utc()
    have = conn.execute(
        "SELECT COUNT(*) FROM place_address WHERE place_id=?;",
        (place_id,)).fetchone()[0]
    make_primary = (have == 0) if primary is None else bool(primary)
    conn.execute("BEGIN IMMEDIATE;")
    try:
        row = conn.execute(
            "SELECT id, is_primary FROM place_address WHERE place_id=? "
            "AND value=?;", (place_id, v)).fetchone()
        if row is None:
            if make_primary:
                conn.execute("UPDATE place_address SET is_primary=0, "
                             "updated_at=? WHERE place_id=? AND is_primary=1;",
                             (now, place_id))
            conn.execute(
                "INSERT INTO place_address(place_id, kind, value, is_primary, "
                "created_at, updated_at) VALUES(?,?,?,?,?,?);",
                (place_id, k, v, 1 if make_primary else 0, now, now))
        else:
            if make_primary and not row[1]:
                conn.execute("UPDATE place_address SET is_primary=0, "
                             "updated_at=? WHERE place_id=? AND is_primary=1;",
                             (now, place_id))
            conn.execute(
                "UPDATE place_address SET kind=?, is_primary=?, updated_at=? "
                "WHERE id=?;",
                (k, 1 if (make_primary or row[1]) else 0, now, row[0]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return _travel_row(conn, "SELECT * FROM place_address WHERE place_id=? "
                             "AND value=?;", (place_id, v))


def place_address_set_primary(conn, place_id, value, now=None):
    """Promote an address already on file to the one the map gets."""
    v = str(value or "").strip()
    row = conn.execute(
        "SELECT id FROM place_address WHERE place_id=? AND value=?;",
        (place_id, v)).fetchone() if _place_split_ready(conn) else None
    if row is None:
        return {"result": "not_found"}
    now = now or now_utc()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute("UPDATE place_address SET is_primary=0, updated_at=? "
                     "WHERE place_id=? AND is_primary=1;", (now, place_id))
        conn.execute("UPDATE place_address SET is_primary=1, updated_at=? "
                     "WHERE id=?;", (now, row[0]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied",
            "address": _travel_row(conn, "SELECT * FROM place_address "
                                         "WHERE id=?;", (row[0],))}


def place_address_remove(conn, place_id, value=None, now=None):
    """Forget one address string, or (value=None) the PRIMARY one.

    Removing the primary does NOT auto-promote a survivor.  Which of the
    remaining strings the map should get is a question only the owner can
    answer, and promoting the next row by id is that answer invented
    (place-address-primary is the verb that answers it)."""
    if not _place_split_ready(conn):
        return {"result": "not_found"}
    if value is None:
        row = conn.execute("SELECT id FROM place_address WHERE place_id=? "
                           "AND is_primary=1;", (place_id,)).fetchone()
    else:
        row = conn.execute("SELECT id FROM place_address WHERE place_id=? "
                           "AND value=?;",
                           (place_id, str(value).strip())).fetchone()
    if row is None:
        return {"result": "not_found"}
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute("DELETE FROM place_address WHERE id=?;", (row[0],))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied"}


def _place_address_write(conn, place_id, value, now=None):
    """The one seam the LEGACY `address=` verb lands on.

    `travel-place-add ... address=X` / `travel-place-upd <p> address=X` predate
    the address layer and stay the ask-once path the skills already drive, so
    they keep meaning "THE map string for this place": a value promotes to
    primary, a blank clears the primary row (and only that one -- a taught map
    link is not collateral of clearing a street address)."""
    v = None if value is None else (str(value).strip() or None)
    if v is None:
        return place_address_remove(conn, place_id, None, now=now)
    return place_address_add(conn, place_id, v, primary=True, now=now)


# ── sub-place: the room, which is not a place ─────────────────────────────

def sub_place_add(conn, place_id, name, token=None, note=None, now=None):
    """Declare a room / floor / hall OF a place.

    This is the verb that makes the 050 refusal trigger bite: the moment a room
    is declared, minting a `place` out of that same string -- bare ("D룸") or
    composed ("<parent> D룸", which is what a calendar entry carries) -- aborts.
    So declaring the room is not bookkeeping; it is what closes the hole the
    room fell through.

    Returns the sub_place row dict.  Idempotent on (place_id, name)."""
    nm = _place_norm_name(name)
    if not nm:
        raise ValueError("sub_place_add: name required")
    if not _place_split_ready(conn):
        raise ValueError(
            "sub_place_add: this database predates migration 050 -- the "
            "sub-place layer does not exist yet")
    if travel_place_get(conn, place_id) is None:
        raise ValueError("sub_place_add: place %r not found" % (place_id,))
    pid = travel_place_get(conn, place_id)["id"]
    now = now or now_utc()
    tok = _place_slug(token or nm)
    conn.execute("BEGIN IMMEDIATE;")
    try:
        row = conn.execute("SELECT id FROM sub_place WHERE place_id=? "
                           "AND name=?;", (pid, nm)).fetchone()
        if row is None:
            if not tok or conn.execute(
                    "SELECT 1 FROM sub_place WHERE place_id=? AND token=? "
                    "LIMIT 1;", (pid, tok)).fetchone() is not None:
                tok = "sub_%d_%d" % (pid, conn.execute(
                    "SELECT COUNT(*) FROM sub_place WHERE place_id=?;",
                    (pid,)).fetchone()[0] + 1)
            conn.execute(
                "INSERT INTO sub_place(place_id, name, token, note, "
                "created_at, updated_at) VALUES(?,?,?,?,?,?);",
                (pid, nm, tok, note, now, now))
        elif note is not None:
            conn.execute("UPDATE sub_place SET note=?, updated_at=? "
                         "WHERE id=?;", (note, now, row[0]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return _travel_row(conn, "SELECT * FROM sub_place WHERE place_id=? "
                             "AND name=?;", (pid, nm))


def sub_place_list(conn, place_id=None):
    """Declared rooms, for one place or for all of them."""
    if not _place_split_ready(conn):
        return []
    if place_id is None:
        return _travel_rows(conn, "SELECT * FROM sub_place ORDER BY "
                                  "place_id, id;", ())
    return _travel_rows(conn, "SELECT * FROM sub_place WHERE place_id=? "
                              "ORDER BY id;", (place_id,))


def _sub_place_resolve(conn, text):
    """Location text -> (parent place id, sub_place row), or (None, None).

    THE terminus lift: a trip that names a ROOM ends at the room's PLACE.  Three
    accepted spellings, all EQUALITY on the canonical whitespace form (never a
    prefix test, never fuzzy -- 6):
        the room name           "D룸"
        the room token          "d"
        parent name + room name "<parent> D룸"   <- what a calendar entry gives
    Lowest sub_place id wins on a tie, the same precedence rule
    _place_by_alias uses, so resolution is deterministic.  A room of a 'gone'
    place does not resolve, for the same reason a gone place does not."""
    key = _place_norm_name(text)
    if not key or not _place_split_ready(conn):
        return None, None
    try:
        rows = conn.execute(
            "SELECT sp.id, sp.place_id, sp.name, sp.token, p.name "
            "FROM sub_place sp JOIN place p ON p.id = sp.place_id "
            "WHERE p.status='active' ORDER BY sp.id;").fetchall()
    except sqlite3.Error:
        return None, None
    for sid, pid, nm, tok, pname in rows:
        if (key == _place_norm_name(nm) or key == _place_norm_name(tok)
                or key == _place_norm_name("%s %s" % (pname or "", nm))):
            return pid, _travel_row(
                conn, "SELECT * FROM sub_place WHERE id=?;", (sid,))
    return None, None


# ── the duplicate DETECTOR: it OFFERS, it never merges ────────────────────
#
# 050 split the model so that a room can no longer BECOME a place.  It did
# nothing about the duplicates already on file, and nothing about the other
# doors the world keeps producing them through: a booking that names a
# building, a map link that arrives where a name belongs, an address typed as
# a place name.  Measured on the live registry 2026-09-12 -- 5 of 20 rows were
# duplicates of 3 physical places, one 45-minute leg had been registered
# twice, and the owner only found out because a developer read the table.
#
# LANE (D10).  Finding CANDIDATES is a rule: every signal below is a string or
# graph comparison, same input -> same output, no judgement in it.  Deciding
# that two rows are ONE PLACE is not -- `양화로 147 == 그라운드 본점` was true
# only because the owner said so.  So this function's output type is `verify`,
# never `value`: a PAIR plus the reason it was noticed.  It carries no
# survivor, no direction and no recommendation, because the survivor is the
# part only the owner knows (D1) and a field for it here is exactly where the
# guess would leak in.  `pair` is ordered by row id and that order means
# NOTHING.
#
# Nothing here writes.  An offer the owner ignores must cost him nothing.

DUPE_SIGNALS = ("name_contains", "shared_address", "name_is_address",
                "twin_edges")
# The three STRUCTURAL signals: each is a statement about the rows themselves
# (one name inside another, one string on two places, a name that is an
# address).  `twin_edges` is not -- two genuinely different venues can both be
# 45 minutes from home -- so it corroborates and never leads.  That is the
# whole difference between the pull surface (shows everything) and the
# registration nudge (structural only, because the owner did not ask).
DUPE_STRUCTURAL = ("name_contains", "shared_address", "name_is_address")


def _dupe_key(text):
    """Comparison form: the canonical whitespace of _place_norm_name, casefolded.

    Casefold is for the ASCII half (`Ground` vs `ground`); Korean is unchanged
    by it.  This is still EQUALITY, not fuzzy matching -- the place lane
    forbids that, and a detector that guessed would be making the owner's
    decision with extra steps."""
    return _place_norm_name(text).casefold()


def _dupe_places(conn):
    """Live places, id-ordered: [{'id', 'name'}].  `gone` rows are already
    somebody's answered question and are never candidates again."""
    where = "WHERE status='active'" if _is_v32(conn) else ""
    return [{"id": r[0], "name": _place_norm_name(r[1])}
            for r in conn.execute(
                "SELECT id, name FROM place " + where + " ORDER BY id;"
            ).fetchall()]


def _dupe_addresses(conn, ids):
    """{place_id: {comparison_key: the string as stored}}.

    Every string on file that points at a place -- NOT just the primary.  A
    duplicate is often the row that holds the 지번 while its twin holds the
    도로명, and reading only the primary would miss exactly that pair.  Before
    050 the address layer is one column, and that column is the same string
    (post-050 it is the mirror of the primary row), so the shape degrades
    instead of failing."""
    out = {}
    if _place_split_ready(conn):
        rows = conn.execute("SELECT place_id, value FROM place_address;")
    else:
        rows = conn.execute(
            "SELECT id, address FROM place "
            "WHERE address IS NOT NULL AND TRIM(address) <> '';")
    for pid, value in rows.fetchall():
        if pid not in ids:
            continue
        k = _dupe_key(value)
        if k:
            out.setdefault(pid, {})[k] = _place_norm_name(value)
    return out


def _dupe_name_contains(a, b):
    """One name contains the other ON A TOKEN BOUNDARY.

    Equality is deliberately NOT a signal: `travel-place-add`'s dedup gate
    already refuses that exact case at write time (2.20.0), so a pair of
    identically-named live rows cannot reach here anyway.  What this catches is
    the shape the gate cannot see -- `<studio> D룸` sitting beside `<studio>`.

    The boundary is a SPACE, never a bare substring: `한빛로` inside
    `한빛로데오거리` is two different streets, and a prefix rule would flag
    every venue that merely starts with a known building's name.  Same reason
    050's trigger matches on equality rather than LIKE."""
    if not a or not b or a == b:
        return False
    short, long = (a, b) if len(a) <= len(b) else (b, a)
    if len(short) < 2:
        return False
    return (long.startswith(short + " ") or long.endswith(" " + short)
            or (" " + short + " ") in long)


def place_dupe_candidates(conn, strong_only=False, place=None,
                          tolerance_min=0):
    """Pairs of live places that MIGHT be one place, with the reason each was
    noticed.  Pure read.  Never decides, never writes.

    strong_only  drop any pair whose only signal is `twin_edges`.
    place        only pairs involving this place (id / name / alias / ulid).
    tolerance_min  how close two edges must be to count as twins.  0 (exact)
                 by default: travel minutes are ceil'd to a 15-minute grid, so
                 equality is the natural comparison and a window would only
                 widen the noise.

    Returns [{'pair': [lo_id, hi_id], 'names': [...], 'signals': [...],
              'evidence': {signal: [...]}}] sorted by pair.  There is no
    'keep', no 'into' and no 'survivor' key, and that absence is the design
    (D1): the direction of a merge is the owner's answer, and this function
    never talks to him."""
    places = _dupe_places(conn)
    byid = {p["id"]: p["name"] for p in places}
    only = None
    if place is not None:
        row = travel_place_get(conn, place)
        if row is None:
            raise ValueError("place_dupe_candidates: place %r not found"
                             % (place,))
        only = row["id"]
    addrs = _dupe_addresses(conn, byid)
    found = {}

    def note(x, y, signal, evidence):
        if x == y or x not in byid or y not in byid:
            return
        if only is not None and only not in (x, y):
            return
        lo, hi = (x, y) if x < y else (y, x)
        found.setdefault((lo, hi), {}).setdefault(signal, []).append(evidence)

    ids = sorted(byid)
    # 1. name-contains  -- "<studio>" and "<studio> D룸"
    for i, a in enumerate(ids):
        ka = _dupe_key(byid[a])
        for b in ids[i + 1:]:
            kb = _dupe_key(byid[b])
            if _dupe_name_contains(ka, kb):
                note(a, b, "name_contains", byid[a] if len(ka) <= len(kb)
                     else byid[b])
    # 2. shared-address -- two rows holding the same string
    for i, a in enumerate(ids):
        for b in ids[i + 1:]:
            for k in sorted(set(addrs.get(a, {})) & set(addrs.get(b, {}))):
                note(a, b, "shared_address", addrs[a][k])
    # 3. name-is-address -- one row's NAME is another row's address string
    for a in ids:
        ka = _dupe_key(byid[a])
        if not ka:
            continue
        for b, have in addrs.items():
            if b != a and ka in have:
                note(a, b, "name_is_address", have[ka])
    # 4. twin-edges -- the same origin reaches both in the same minutes.  This
    #    is the signal that would have caught the 45-minute leg being paid for
    #    twice, and it is the one that needs the owner most: two gyms really
    #    can both be 25 minutes away.
    by_origin = {}
    try:
        edges = conn.execute(
            "SELECT from_place_id, to_place_id, minutes FROM travel_edge "
            "WHERE minutes IS NOT NULL;").fetchall()
    except sqlite3.Error:
        edges = []
    for o, d, m in edges:
        if o in byid and d in byid:
            by_origin.setdefault(o, []).append((d, m))
    for o, dests in by_origin.items():
        dests.sort()
        for i, (da, ma) in enumerate(dests):
            for db, mb in dests[i + 1:]:
                if da != db and abs(ma - mb) <= tolerance_min:
                    note(da, db, "twin_edges",
                         "%s %s=%s" % (byid[o], ma, mb))

    out = []
    for (a, b), sig in sorted(found.items()):
        signals = [s for s in DUPE_SIGNALS if s in sig]
        if strong_only and not any(s in DUPE_STRUCTURAL for s in signals):
            continue
        out.append({"pair": [a, b], "names": [byid[a], byid[b]],
                    "signals": signals,
                    "evidence": {s: sig[s] for s in signals}})
    return out


def dupe_candidate_line(c):
    """One TSV line per candidate.  Column 3/5 are the two ids IN ROW ORDER --
    which is not a ranking, a direction, or a recommendation."""
    why = []
    for s in c["signals"]:
        ev = c["evidence"][s]
        why.append("%s=%s" % (s.replace("_", "-"),
                              "|".join(str(e) for e in ev[:3])))
    return "place-dupe\t%s\t%s\t%s\t%s\t%s\t%s" % (
        ",".join(c["signals"]), c["pair"][0],
        _travel_signal_field(c["names"][0]), c["pair"][1],
        _travel_signal_field(c["names"][1]), "; ".join(why))


def _dupe_nudge(conn, place_id):
    """The OFFER, at the one moment it costs the owner nothing (D6): the turn
    that just registered or renamed this place.

    STRUCTURAL signals only.  He did not ask for this list, so a pair held up
    by `twin_edges` alone -- two venues that happen to be the same number of
    minutes from home -- is not worth a question here; it is worth one when he
    goes looking, which is what `place-dupes` is for.

    Never blocks, never changes the exit code, and prints AFTER the row the
    verb already printed, so every existing caller reads the same first line it
    always did.  A nudge that could fail a write would be a merge with extra
    steps."""
    try:
        cands = place_dupe_candidates(conn, strong_only=True, place=place_id)
    except (sqlite3.Error, ValueError):
        return
    if not cands:
        return
    print("DUPE-CANDIDATE %d" % len(cands))
    for c in cands:
        print(dupe_candidate_line(c))


# ── place (6: the home of place knowledge) ────────────────────────────────

def _place_norm_name(text):
    """THE canonical whitespace form of a venue / location string.

    One function, used by BOTH halves of the place lane: what gets STORED as
    a place name, and what any lookup key is reduced to before it is matched.
    That is the whole point -- they used to disagree. Locations are free text
    the owner (or Google Calendar) typed, and measured 2026-09-11 the live
    rows carry internal newlines (block 924
    '경기 가온시 한빛구 한빛로 319\n한빛마을 아파트 112동 903호', block 1025
    '식사: \n공연: 가온 라이브홀') as well as trailing ones (blocks 704/706).
    The mint stored the raw string, the TSV signal printed a collapsed one --
    so the text the owner was SHOWN could never resolve to the row the sweep
    had just made, and the documented recovery minted a second place.

    Whitespace is never part of a venue name, so collapse it rather than
    escape it: the signal field is copied straight into the next verb
    argument (travel-place-add / travel-edge-add) and read out loud in a
    Korean question, and a `\n` escape would have to be undone by every
    consumer and would still leave two spellings of one venue. Collapsing
    gives one spelling, which is what "the signal text IS the lookup key"
    requires."""
    return " ".join(str(text or "").split())


def _place_by_norm_name(conn, text):
    """Place id whose STORED name matches `text` modulo whitespace.

    The fallback arm for rows written before _place_norm_name existed (a
    name persisted with an embedded newline can never be typed back). Runs
    only after every exact match has missed, scans in id order so the
    earliest row wins like _place_by_alias, and is NOT fuzzy matching (6):
    the comparison is still equality, on the canonical whitespace form.
    Returns place id or None."""
    key = _place_norm_name(text)
    if not key:
        return None
    where = "WHERE status='active'" if _is_v32(conn) else ""
    for pid, name in conn.execute(
            "SELECT id, name FROM place " + where + " ORDER BY id;").fetchall():
        if name is not None and _place_norm_name(name) == key:
            return pid
    return None


def _place_by_alias(conn, name):
    """THE alias-resolution rule for places -- the single home; every alias
    lookup routes here (place_upsert, _resolve_location_place,
    travel_place_get). Semantics, both axes: exact JSON-array element
    membership on place.aliases; malformed/non-JSON blobs (legacy
    pipe-joined text) are skipped, never fatal; on the v3.2 axis a 'gone'
    place does not resolve (a removed place must stop deriving).

    AMBIGUITY precedence: when two places carry the same alias, the LOWEST
    place id wins -- the place that learned the alias earliest keeps it.
    Deterministic on both axes (036 preserves place ids) and identical to
    the de-facto rowid scan order of the four loops this helper replaced,
    so unification flipped no existing resolution. Callers order this arm
    AFTER every exact identifier (ulid, token, name, integer id), so an
    alias can never shadow a canonical identifier.

    Both sides are reduced by _place_norm_name first: an alias taught from a
    Google Calendar location string carries that string's internal newlines,
    and the key handed back by the TRAVEL_PLACE_NEEDED signal is the
    collapsed form of the same text. Matching the raw spellings made the two
    miss each other. Still equality, not fuzzy matching (6). Returns place id
    or None."""
    if not name:
        return None
    key = _place_norm_name(name)
    where = ("WHERE " + LIVE_PLACE_SQL + " AND aliases IS NOT NULL"
             if _is_v32(conn) else "WHERE aliases IS NOT NULL")
    for pid, blob in conn.execute(
            "SELECT id, aliases FROM place " + where +
            " ORDER BY id;").fetchall():
        try:
            arr = json.loads(blob)
        except (TypeError, ValueError):
            continue
        if isinstance(arr, list) and any(
                _place_norm_name(a) == key for a in arr
                if isinstance(a, str)):
            return pid
    return None


def travel_place_get(conn, token):
    """place row by ulid, integer id, exact name -- or, LAST, a taught
    alias (_place_by_alias; exact identifiers are never shadowed by an
    alias), then the whitespace-canonical name (_place_by_norm_name, for
    rows stored before names were normalized). This is the lookup
    `travel-edge-add <from> <to> <min>` uses, so it has to accept the same
    string TRAVEL_PLACE_NEEDED printed.

    An `int` argument is an ID and is resolved as one FIRST (2.20.0). It used
    to be str()-ed and thrown into the same token match as user text, and on
    live data that silently returned the WRONG ROW. The v3.2 tokenizer keeps
    the ASCII part of a name, so a place named for a street address whose only
    ASCII is a trailing number carries that BARE NUMBER as its token -- and
    `travel_place_get(conn, N)` then matched p.token=N before it ever reached
    p.id=N, and answered with a different place entirely. Measured 2026-09-12
    on the live DB: exactly one such collision, and it is load-bearing --
    travel rule 14's destination is the shadowed id.

    Five internal callers pass an integer id. Two are the deriver reading its
    own destination (_travel_resolve_before_leg / _travel_resolve_return_leg,
    `dest = travel_place_get(conn, rule['place_id'])`), so that rule was
    reading a DIFFERENT place's durations on every sweep with nothing printed.
    travel_rule_add is worse: it writes back `place_id = place["id"]`, i.e. it
    would have STORED the shadowing row's id for a caller that named the
    shadowed one.

    An int cannot be a ulid, a token, or a display name -- those are all TEXT
    columns -- so preferring the id for an int narrows nothing. A numeric
    STRING (what the CLI hands over: `travel-place-upd 9 ...`) keeps the old
    order exactly, because from the CLI '9' really might be a name."""
    if _is_v32(conn):
        if isinstance(token, int) and not isinstance(token, bool):
            return _travel_place_decorate_v32(
                conn, _travel_place_row_v32(conn, "WHERE p.id=?", (token,)))
        t = str(token)
        row = _travel_place_row_v32(
            conn, "WHERE p.ulid=? OR p.token=? OR COALESCE(l.display,p.token)=?",
            (t, t, t))
        if row is None and t.isdigit():
            row = _travel_place_row_v32(conn, "WHERE p.id=?", (int(t),))
        if row is None:
            pid = _place_by_alias(conn, t)
            if pid is None:
                pid = _place_by_norm_name(conn, t)
            if pid is not None:
                row = _travel_place_row_v32(conn, "WHERE p.id=?", (pid,))
        return _travel_place_decorate_v32(conn, row)
    if isinstance(token, int) and not isinstance(token, bool):
        # Same int-is-an-id rule on the legacy axis (see docstring). The v35
        # collision needs a place literally NAMED "9" rather than a token, so
        # it is rarer here -- but "rarer" is not a contract.
        return _travel_row(conn, "SELECT * FROM place WHERE id=?;", (token,))
    row = _travel_row(conn, "SELECT * FROM place WHERE ulid=? OR name=?;",
                      (str(token), str(token)))
    if row is None and str(token).isdigit():
        row = _travel_row(conn, "SELECT * FROM place WHERE id=?;",
                          (int(token),))
    if row is None:
        pid = _place_by_alias(conn, str(token))
        if pid is None:
            pid = _place_by_norm_name(conn, token)
        if pid is not None:
            row = _travel_row(conn, "SELECT * FROM place WHERE id=?;",
                              (pid,))
    return row


def _place_by_display_name(conn, name):
    """073: the live place whose display_name equals `name` (canonical
    whitespace form, lowest id on a tie), or None."""
    key = _place_norm_name(name)
    if not key:
        return None
    try:
        where = ("WHERE " + LIVE_PLACE_SQL + " AND display_name IS NOT NULL"
                 if _is_v32(conn) else "WHERE display_name IS NOT NULL")
        for pid, disp in conn.execute(
                "SELECT id, display_name FROM place " + where +
                " ORDER BY id;").fetchall():
            if _place_norm_name(disp) == key:
                return pid
    except sqlite3.Error:
        return None
    return None


def _place_at_address(conn, address):
    """A unique live registry destination with this exact address; no guessing."""
    from place_location import address_key
    key = address_key(address)
    if not key:
        return None
    matches = set()
    live = " WHERE status='active'" if _is_v32(conn) else ""
    for pid, stored in conn.execute("SELECT id,address FROM place" + live):
        if address_key(stored) == key:
            matches.add(pid)
    if _place_split_ready(conn):
        for pid, stored in conn.execute(
                "SELECT pa.place_id,pa.value FROM place_address pa JOIN place p ON p.id=pa.place_id "
                "WHERE p.status='active' AND pa.kind!='map_url'"):
            if address_key(stored) == key:
                matches.add(pid)
    return travel_place_get(conn, matches.pop()) if len(matches) == 1 else None


def _resolve_location_place(conn, location):
    """Deterministic location-text -> place resolution: exact canonical name
    or alias match. Runtime fuzzy matching is forbidden (6); this is the
    lookup the chain predicate (2.6 external()) uses. Returns place dict or
    None (= unknown = judgment-impossible = prep included, safe side).

    The key is reduced by _place_norm_name, the SAME reduction travel_place_add
    applies to the stored name, so the venue text and the canonical name are
    one string. Stripping alone was not enough: a location with an INTERNAL
    newline stored one spelling and the signal printed another, and the
    round trip missed."""
    if not location:
        return None
    from place_location import split_location
    loc, _room, address = split_location(location)
    if not loc:
        return None
    by_address = _place_at_address(conn, address)
    if by_address is not None:
        return by_address
    if _is_v32(conn):
        # gone places do not resolve: a removed place must stop deriving.
        row = _travel_place_row_v32(
            conn, "WHERE p.status='active' "
            "AND (COALESCE(l.display,p.token)=? OR p.token=?)", (loc, loc))
        # 073 -- display_name is what the owner calls a place (place 1, the
        # office, carries display_name "the office room" in the owner's words;
        # "straight from the office" minted place 29 because no arm read it). After the exact name/token, before the
        # room lift and the aliases -- the registry's precedence.
        if row is None:
            pid = _place_by_display_name(conn, loc)
            if pid is not None:
                row = _travel_place_row_v32(conn, "WHERE p.id=?", (pid,))
        # 050 -- THE TERMINUS LIFT. A trip that names a ROOM ends at the
        # room's PLACE, so "<studio> D룸" resolves to the studio and the third
        # studio row that this exact string minted on 2026-09-12 can never be
        # minted again. Ordered AFTER the exact name/token match (an exact
        # identifier is never shadowed -- the same precedence _place_by_alias
        # documents) and BEFORE the alias/whitespace fallbacks and the mint.
        if row is None:
            pid, sub = _sub_place_resolve(conn, loc)
            if pid is not None:
                row = _travel_place_row_v32(conn, "WHERE p.id=?", (pid,))
                if row is not None:
                    row["sub_place"] = sub
        # alias fallback: THE rule (_place_by_alias -- 'gone' stays excluded
        # there). Ordered after the exact name/token match; the whitespace
        # fallback is last (legacy rows stored with embedded newlines).
        if row is None:
            pid = _place_by_alias(conn, loc) or _place_by_norm_name(conn, loc)
            if pid is not None:
                row = _travel_place_row_v32(conn, "WHERE p.id=?", (pid,))
        return _travel_place_decorate_v32(conn, row)
    row = _travel_row(conn, "SELECT * FROM place WHERE name=?;", (loc,))
    if row is not None:
        return row
    pid = _place_by_display_name(conn, loc)       # 073 display_name arm
    if pid is not None:
        return _travel_row(conn, "SELECT * FROM place WHERE id=?;", (pid,))
    pid, sub = _sub_place_resolve(conn, loc)      # 050 terminus lift
    if pid is not None:
        row = _travel_row(conn, "SELECT * FROM place WHERE id=?;", (pid,))
        if row is not None:
            row["sub_place"] = sub
            return row
    pid = _place_by_alias(conn, loc) or _place_by_norm_name(conn, loc)
    if pid is not None:
        return _travel_row(conn, "SELECT * FROM place WHERE id=?;", (pid,))
    return None


def travel_place_add(conn, name, aliases=None, to_min=None, from_min=None,
                     prep_min=None, note=None, address=None, now=None):
    """Register a place (ask-once landing spot). Minute values are grid-
    ceiled (2.4). `address` (035) is the ONE map-routable string for this
    place; NULL means the route puller falls back to routing the NAME, which
    is exactly pre-035 behaviour. Returns the place dict.

    The name is STORED in _place_norm_name form -- the same reduction every
    lookup key gets. This is the storage half of "the signal text is the
    lookup key": a venue whose raw text carries a newline lands as one line,
    so the string TRAVEL_PLACE_NEEDED prints resolves back to THIS row
    instead of minting a second one."""
    if not name or not _place_norm_name(name):
        raise ValueError("travel_place_add: name required")
    from place_location import split_location
    name, _room, embedded = split_location(name)
    address = address or embedded or None
    existing = _place_at_address(conn, address) or _resolve_location_place(conn, name)
    if existing is not None:
        return existing
    now = now or now_utc()
    ulid = new_ulid()
    vals = {
        "to_min": _ceil_grid(to_min) if to_min is not None else None,
        "from_min": _ceil_grid(from_min) if from_min is not None else None,
        "prep_min": _ceil_grid(prep_min) if prep_min is not None else None,
    }
    if _is_v32(conn):
        place = _travel_place_add_v32(conn, name, aliases, vals,
                                      note, address, ulid, now)
        _place_coord_note_new(conn, place)
        return place
    conn.execute("BEGIN IMMEDIATE;")
    try:
        # 050: `address` is NOT written here. It is a derived mirror of
        # place_address(is_primary=1) and the schema REFUSES a direct write; the
        # address lands right after, through _place_address_write, and the
        # mirror follows by trigger.
        conn.execute(
            "INSERT INTO place(ulid, name, aliases, to_min, from_min, "
            "prep_min, note, address, created_at, updated_at) "
            "VALUES(?,?,?,?,?,?,?,NULL,?,?);",
            (ulid, name,
             json.dumps(aliases) if aliases else None,
             vals["to_min"], vals["from_min"], vals["prep_min"],
             note, now, now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    place = travel_place_get(conn, ulid)
    if address and _place_split_ready(conn):
        _place_address_write(conn, place["id"], address, now=now)
        place = travel_place_get(conn, ulid)
    # DGN-623: a to_min/from_min given at registration IS the base(집)-origin
    # edge -- mirror it into travel_edge so the presence-aware deriver finds it
    # for the common 집-departure case (node column kept for back-compat).
    _travel_place_mirror_edges(conn, place, now=now)
    _place_coord_note_new(conn, place)
    return place


def _travel_place_add_v32(conn, name, aliases, vals, note, address, ulid, now):
    """v3.2 place registration. The human name goes to the label layer; the
    durations go where v3.2 keeps every travel number: measures on EXPLICIT
    ordered pairs (base <-> place). Nothing base-relative is stored, so a later
    base change cannot silently rot these values. aliases/note persist on the
    place row exactly as at v35 -- 036 keeps both columns (X-5 closed;
    2026-09-05 review F1 hit the refusal that used to sit here)."""
    base = _travel_base_place_id(conn)
    if base is None and any(v is not None for v in vals.values()):
        raise ValueError(
            "travel_place_add: no base place registered -- v3.2 stores travel "
            "durations on explicit place pairs. Register the base first, or "
            "add the place without minutes and use travel-edge-add")
    conn.execute("BEGIN IMMEDIATE;")
    try:
        # name 도 함께 쓴다 (036): place.name 은 v36 에도 남는 미러 읽기
        # 컬럼이다 (sdk_bridge REQUIRED_CAPABILITIES place.name). 렌더 정본은
        # 여전히 label -- name 은 그 사본이고, 쓰는 자리는 이 두 곳뿐이다.
        # 050: address NULL at INSERT -- it is a derived mirror the schema
        # refuses to let any writer set directly. The real address row is
        # written below, after the place has an id.
        cur = conn.execute(
            "INSERT INTO place(ulid, name, aliases, note, token, address, "
            "is_base) VALUES(?, ?, ?, ?, '', NULL, 0);",
            (ulid, name,
             json.dumps(aliases) if aliases else None, note or None))
        pid = cur.lastrowid
        tok = _place_slug(name) or ("place_%d" % pid)
        if conn.execute("SELECT 1 FROM place WHERE token=? AND id!=? LIMIT 1;",
                        (tok, pid)).fetchone() is not None:
            tok = "%s_%d" % (tok, pid)
        conn.execute("UPDATE place SET token=? WHERE id=?;", (tok, pid))
        conn.execute(
            "INSERT OR REPLACE INTO label(namespace, token, lang, display) "
            "VALUES('place', ?, 'ko', ?);", (tok, name))
        if vals["to_min"] is not None or vals["prep_min"] is not None:
            lid = _travel_v32_link_id(conn, base, pid, create=True)
            if vals["to_min"] is not None:
                _travel_v32_set(conn, lid, TRAVEL_METRIC_MIN, vals["to_min"],
                                now=now)
            if vals["prep_min"] is not None:
                _travel_v32_set(conn, lid, TRAVEL_METRIC_PREP,
                                vals["prep_min"], now=now)
        if vals["from_min"] is not None:
            lid = _travel_v32_link_id(conn, pid, base, create=True)
            _travel_v32_set(conn, lid, TRAVEL_METRIC_MIN, vals["from_min"],
                            now=now)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    if address:
        _place_address_write(conn, pid, address, now=now)
    return travel_place_get(conn, ulid)


def _travel_place_mirror_edges(conn, place, now=None):
    """Keep travel_edge consistent with a place's base-origin node columns:
      to_min   -> edge(base -> place)   (outbound, carries place.prep_min)
      from_min -> edge(place -> base)   (homeward)
    Best-effort: no travel_edge table (pre-v21) or no base seeded -> no-op."""
    if place is None or not _travel_edge_schema_ready(conn):
        return
    base = conn.execute("SELECT id FROM place WHERE is_base=1;").fetchone()
    if base is None or base[0] == place["id"]:
        return
    now = now or now_utc()
    if place.get("to_min") is not None:
        travel_edge_add(conn, base[0], place["id"], place["to_min"],
                        prep_min=place.get("prep_min"), now=now)
    if place.get("from_min") is not None:
        travel_edge_add(conn, place["id"], base[0], place["from_min"], now=now)


_PLACE_LEG_TO_RULE = {          # 2.3 propagation map: place col -> rule leg
    "to_min": ("before_min", "before_src"),
    "from_min": ("after_min", "after_src"),
    "prep_min": ("prep_min", "prep_src"),
}


def travel_place_upd(conn, place_token, changes, state_conn=None, now=None):
    """Update a place. src='place' dependent rule legs are updated in the
    SAME txn (2.3: propagation is verb-layer code, no model discretion);
    src='explicit' legs are untouched -- the user's explicit declaration
    wins. Affected active rules are refreshed inline afterwards."""
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    now = now or now_utc()
    if changes.get("name"):
        # Renaming is the other author of the canonical name -- normalize
        # here, once, so both axes below inherit it (see travel_place_add).
        changes = dict(changes)
        from place_location import split_location
        changes["name"], _room, embedded = split_location(changes["name"])
        if embedded and "address" not in changes:
            changes["address"] = embedded
    if _is_v32(conn):
        return _travel_place_upd_v32(conn, place, changes, state_conn, now)
    # 035: `address` joins the settable set -- this is the line that makes
    # `travel-place-upd <place> address=...` work, since cli_travel_place_upd
    # forwards the raw kv dict. Deliberately NOT added to _PLACE_LEG_TO_RULE:
    # an address propagates to no rule leg, so the same-txn propagation block
    # below skips it untouched and no travel_rule version is bumped by it.
    allowed = ("name", "aliases", "to_min", "from_min", "prep_min", "note",
               "address")
    sets, params = [], []
    for k, v in changes.items():
        if k not in allowed:
            raise ValueError("travel_place_upd: column %r not allowed" % k)
        if k in ("to_min", "from_min", "prep_min") and v is not None:
            v = _ceil_grid(v)
        if k == "aliases" and v is not None and not isinstance(v, str):
            v = json.dumps(v)
        # 050: `address` no longer rides the place UPDATE -- place.address is
        # a derived mirror and the schema refuses a direct write. It lands via
        # _place_address_write below (a blank still means UNKNOWN, i.e. clear
        # the primary row; an empty string was never a storable address).
        if k == "address":
            continue
        sets.append("%s=?" % k)
        params.append(v)
    if "address" in changes and _place_split_ready(conn):
        _place_address_write(conn, place["id"], changes["address"], now=now)
    if not sets:
        if "address" in changes:
            return {"result": "applied",
                    "place": travel_place_get(conn, place["id"])}
        raise ValueError("travel_place_upd: nothing to change")
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "UPDATE place SET " + ", ".join(sets) + ", updated_at=? "
            "WHERE id=?;", params + [now, place["id"]])
        # same-txn propagation to src='place' rule legs (all three legs).
        for pcol, (rcol, scol) in _PLACE_LEG_TO_RULE.items():
            if pcol not in changes:
                continue
            newv = changes[pcol]
            newv = _ceil_grid(newv) if newv is not None else 0
            conn.execute(
                ("UPDATE travel_rule SET %s=?" +
                 ("" if rcol == "prep_min" else _TRAVEL_PREP_RELABEL_SQL) +
                 ", version=version+1, updated_at=? "
                 "WHERE place_id=? AND %s='place' AND " + LIVE_TRAVEL_RULE_SQL
                 + ";") % (rcol, scol), (newv, now, place["id"]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    # inline refresh of affected active rules (3.1(i)).
    for rule in _travel_rows(
            conn, "SELECT * FROM travel_rule WHERE place_id=? "
            "AND status='active';", (place["id"],)):
        travel_refresh_rule(conn, state_conn, rule, now=now)
    return {"result": "applied", "place": travel_place_get(conn, place["id"])}


def _travel_place_upd_v32(conn, place, changes, state_conn, now):
    """v3.2 update path. name -> label layer; address -> place; minute keys ->
    supersede-and-insert on the base pair's measures (the old in-force row is
    expired, never edited). The travel_rule propagation (src='place' legs move
    with the place, src='explicit' legs never do) is kept verbatim --
    travel_rule is a module-side table on both schemas."""
    # aliases/note joined back (X-5 closed; 2026-09-05 review F1): 036 keeps
    # both columns on place, so they update in place exactly as at v35.
    allowed = ("name", "aliases", "to_min", "from_min", "prep_min", "note",
               "address")
    for k in changes:
        if k not in allowed:
            raise ValueError("travel_place_upd: column %r not allowed" % k)
    if not changes:
        raise ValueError("travel_place_upd: nothing to change")
    minute_keys = [k for k in ("to_min", "from_min", "prep_min")
                   if k in changes]
    base = _travel_base_place_id(conn)
    if minute_keys and (base is None or base == place["id"]):
        raise ValueError(
            "travel_place_upd: base-origin minutes need a distinct base place "
            "-- v3.2 stores durations on explicit pairs (travel-edge-add)")
    conn.execute("BEGIN IMMEDIATE;")
    try:
        if "name" in changes and changes["name"]:
            conn.execute(
                "INSERT OR REPLACE INTO label(namespace, token, lang, display) "
                "VALUES('place', ?, 'ko', ?);",
                (place["token"], str(changes["name"]).strip()))
            # 미러 읽기 컬럼 동기화 (036) -- travel_place_add_v32 의 주석 참조.
            conn.execute("UPDATE place SET name=? WHERE id=?;",
                         (str(changes["name"]).strip(), place["id"]))
        # 050: address is NOT set here. place.address is a derived mirror and
        # the schema refuses this UPDATE outright; the write goes to the
        # address layer after this transaction commits (place_address_* opens
        # its own BEGIN IMMEDIATE, so it cannot nest inside this one).
        if "aliases" in changes:
            v = changes["aliases"]
            if v is not None and not isinstance(v, str):
                v = json.dumps(v)
            conn.execute("UPDATE place SET aliases=? WHERE id=?;",
                         (v, place["id"]))
        if "note" in changes:
            conn.execute("UPDATE place SET note=? WHERE id=?;",
                         (changes["note"], place["id"]))
        for k in minute_keys:
            v = changes[k]
            v = _ceil_grid(v) if v is not None else None
            if k == "from_min":
                lid = _travel_v32_link_id(conn, place["id"], base, create=True)
                _travel_v32_set(conn, lid, TRAVEL_METRIC_MIN, v, now=now)
            else:
                lid = _travel_v32_link_id(conn, base, place["id"], create=True)
                metric = (TRAVEL_METRIC_MIN if k == "to_min"
                          else TRAVEL_METRIC_PREP)
                _travel_v32_set(conn, lid, metric, v, now=now)
        # same-txn propagation to src='place' rule legs (all three legs).
        for pcol, (rcol, scol) in _PLACE_LEG_TO_RULE.items():
            if pcol not in changes:
                continue
            newv = changes[pcol]
            newv = _ceil_grid(newv) if newv is not None else 0
            conn.execute(
                ("UPDATE travel_rule SET %s=?" +
                 ("" if rcol == "prep_min" else _TRAVEL_PREP_RELABEL_SQL) +
                 ", version=version+1, updated_at=? "
                 "WHERE place_id=? AND %s='place' AND " + LIVE_TRAVEL_RULE_SQL
                 + ";") % (rcol, scol), (newv, now, place["id"]))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    if "address" in changes:
        _place_address_write(conn, place["id"], changes["address"], now=now)
    for rule in _travel_rows(
            conn, "SELECT * FROM travel_rule WHERE place_id=? "
            "AND status='active';", (place["id"],)):
        travel_refresh_rule(conn, state_conn, rule, now=now)
    return {"result": "applied", "place": travel_place_get(conn, place["id"])}


def travel_place_remove(conn, place_token, state_conn=None, now=None):
    """Remove a place, in the form v3.2 gives disappearance: STATUS, not
    DELETE (the dividing axis has 소멸, never 완료 -- and past blocks /
    ax_machine.gym_id must keep resolving). What "no orphaned travel data"
    means here, concretely:
      - place.status='gone'  -> the read surfaces (v_place_link_measure, the
        compat travel_edge view, _resolve_location_place) stop serving every
        pair touching it, in both directions;
      - every IN-FORCE travel measure on those pairs gets valid_until stamped
        -- the answer is expired on the record, not just hidden;
      - travel rules pinned to the place are retired through
        travel_rule_retire, which also cleans their derived, un-settled
        travel/prep blocks.
    History (expired measures, past blocks at the place) stays -- v3.2 does
    not rewrite the past. Base removal is refused: relocate the base first."""
    if not _is_v32(conn):
        raise ValueError(
            "travel_place_remove: requires the v3.2 store (the legacy schema "
            "has no removal path -- it was never built there)")
    place = travel_place_get(conn, place_token)
    if place is None:
        return {"result": "not_found"}
    if place.get("is_base"):
        raise ValueError(
            "travel_place_remove: refusing to remove the base place; "
            "set another base first (place_set_base)")
    if place.get("status") == "gone":
        return {"result": "already_gone", "place_id": place["id"]}
    now = now or now_utc()
    # 순서가 계약이다 (2026-09-05 리뷰 F2): 규칙 은퇴 + 파생 블록 정리가 먼저,
    # 장소 소멸 + 측정 만료(단일 트랜잭션)가 마지막. 은퇴/정리는 규칙마다
    # 트랜잭션이 갈리고 미러 I/O 도 껴서 중간에 죽을 수 있는 쪽인데, 그 시점엔
    # 장소가 아직 온전하므로 재실행이 수렴한다. 반대 순서(예전 코드)는 정리가
    # 죽는 순간 "장소는 gone, 규칙은 은퇴, 파생 블록 2개는 라이브 고아" 라는
    # 반쪽 상태를 커밋해 놓고 나갔다.
    retired = 0
    for rule in _travel_rows(
            conn, "SELECT * FROM travel_rule WHERE place_id=? "
            "AND " + LIVE_TRAVEL_RULE_SQL + ";", (place["id"],)):
        travel_rule_retire(conn, rule["ulid"], state_conn=state_conn, now=now)
        retired += 1
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute("UPDATE place SET status='gone' WHERE id=?;",
                     (place["id"],))
        conn.execute(
            "UPDATE measure SET valid_until=? WHERE place_link_id IN "
            "(SELECT id FROM place_link WHERE from_place_id=? OR to_place_id=?)"
            " AND (valid_until IS NULL OR valid_until > ?);",
            (now, place["id"], place["id"], now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"result": "applied", "place_id": place["id"],
            "rules_retired": retired}


# ── travel_rule (5.1/5.2) ─────────────────────────────────────────────────

def travel_rule_get(conn, token):
    row = _travel_row(conn, "SELECT * FROM travel_rule WHERE ulid=?;",
                      (str(token),))
    if row is None and str(token).isdigit():
        row = _travel_row(conn, "SELECT * FROM travel_rule WHERE id=?;",
                          (int(token),))
    return row


def _travel_rule_for_anchor_txn(conn, event_ulid, recurrence_id):
    """ACTIVE rule governing an anchor INSTANCE, txn-safe (pure SELECT).
    Resolution (5.1 join-key pin): event-direct rule first; else the def
    rule via event.recurrence_id = routine_def.recurrence_id ONLY (title /
    def-id joins forbidden). Returns rule dict or None."""
    rule = _travel_row(
        conn, "SELECT * FROM travel_rule WHERE anchor_type='event' "
        "AND anchor_ulid=? AND status='active';", (event_ulid,))
    if rule is not None:
        return rule
    if recurrence_id:
        d = conn.execute(
            "SELECT ulid FROM routine_def WHERE recurrence_id=?;",
            (recurrence_id,)).fetchone()
        if d is not None:
            return _travel_row(
                conn, "SELECT * FROM travel_rule WHERE anchor_type='def' "
                "AND anchor_ulid=? AND status='active';", (d[0],))
    return None


def _travel_rule_for_anchor_row(conn, anchor_row):
    return _travel_rule_for_anchor_txn(
        conn, anchor_row["ulid"], anchor_row.get("recurrence_id"))


def travel_rule_add(conn, anchor_type, anchor_ulid, place_id=None,
                    before_min=None, after_min=None, prep_min=None,
                    before_src=None, after_src=None, prep_src=None,
                    status="active", created_by=None, state_conn=None,
                    now=None):
    """Create a travel rule (2.1: derivation is ALWAYS grounded in an
    explicit rule row; no silent auto-attach). Minute values grid-ceil.
    place_id + a None leg value = pre-fill from the place (src='place');
    an explicit value = src='explicit' (2.3/2.5). status='proposed' is the
    deferred-offer carrier (derives nothing). Active rules derive inline."""
    if anchor_type not in ("def", "event"):
        raise ValueError("travel_rule_add: anchor_type must be def|event")
    if anchor_type == "event":
        arow = _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=?;",
                           (anchor_ulid,))
        if arow is None:
            raise ValueError("travel_rule_add: anchor event %r not found"
                             % anchor_ulid)
        if arow.get("block_class") is not None:
            raise ValueError(
                "travel_rule_add: a derived block cannot be an anchor "
                "(no derivation of derivations, spec 1)")
    else:
        d = conn.execute("SELECT 1 FROM routine_def WHERE ulid=?;",
                         (anchor_ulid,)).fetchone()
        if d is None:
            raise ValueError("travel_rule_add: routine_def %r not found"
                             % anchor_ulid)
    place = None
    if place_id is not None:
        place = travel_place_get(conn, place_id)
        if place is None:
            raise ValueError("travel_rule_add: place %r not found" % place_id)
        place_id = place["id"]

    def leg(value, src, place_col):
        if value is not None:
            return _ceil_grid(value), (src or "explicit")
        if place is not None and place.get(place_col) is not None:
            return place[place_col], (src or "place")
        return 0, (src or "explicit")

    b_min, b_src = leg(before_min, before_src, "to_min")
    if (after_min is None and place is not None
            and after_src in (None, "place") and _is_v32(conn)):
        # v3.2: place.from_min is not a stored node column any more -- the
        # decorated value IS the pair's current measure. Baking it into the
        # rule would put the same number in two homes again (the drift the
        # axis change removed) and a baked after_min defeats the P2 chain
        # resolution (interior events would return home mid-chain). Bake 0
        # with src='place': the deriver resolves the return leg from the
        # current edge at derive time.
        a_min, a_src = 0, "place"
    else:
        a_min, a_src = leg(after_min, after_src, "from_min")
    p_min, p_src = leg(prep_min, prep_src, "prep_min")
    if prep_min is None and prep_src is None and p_src == "explicit":
        # nobody gave a prep and the place has none: the user default applies
        # (_travel_rule_prep), never a silent 0 that reads like a choice.
        p_src = TRAVEL_SRC_PROVISIONAL
    now = now or now_utc()
    ulid = new_ulid()
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT INTO travel_rule(ulid, anchor_type, anchor_ulid, "
            "place_id, before_min, after_min, prep_min, before_src, "
            "after_src, prep_src, status, created_by, created_at, "
            "updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?);",
            (ulid, anchor_type, anchor_ulid, place_id, b_min, a_min, p_min,
             b_src, a_src, p_src, status,
             created_by or _facade_agent(), now, now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    rule = travel_rule_get(conn, ulid)
    if rule["status"] == "active":
        travel_refresh_rule(conn, state_conn, rule, now=now)   # 3.1(i) inline
    return rule


_TRAVEL_RULE_UPD_COLS = ("before_min", "after_min", "prep_min",
                         "before_src", "after_src", "prep_src",
                         "status", "place_id")


def travel_rule_upd(conn, rule_token, changes, state_conn=None, now=None, owner_edit=True):
    """Update a rule (proposed->active transition + churn-freeze release +
    prep handling, 2.5/2.6/3.1). CAS version bump; updated_at refresh is the
    ONLY freeze release path. retire -> group cleanup rides along."""
    rule = travel_rule_get(conn, rule_token)
    if rule is None:
        return {"result": "not_found"}
    now = now or now_utc()
    sets, params = [], []
    for k, v in changes.items():
        if k not in _TRAVEL_RULE_UPD_COLS:
            raise ValueError("travel_rule_upd: column %r not allowed" % k)
        if k in ("before_min", "after_min", "prep_min") and v is not None:
            v = _ceil_grid(v)
        sets.append("%s=?" % k)
        params.append(v)
    if not sets:
        raise ValueError("travel_rule_upd: nothing to change")
    relabel = ""
    if "prep_min" in changes and "prep_src" not in changes:
        # a stated prep (0 included) is the user's choice for this event
        sets.append("prep_src=?")
        params.append("explicit")
    elif "prep_min" not in changes and "prep_src" not in changes:
        relabel = _TRAVEL_PREP_RELABEL_SQL
    conn.execute("BEGIN IMMEDIATE;")
    try:
        cur = conn.execute(
            "UPDATE travel_rule SET " + ", ".join(sets) + relabel +
            ", version=version+1, updated_at=? WHERE id=? AND version=?;",
            params + [now, rule["id"], rule["version"]])
        if cur.rowcount != 1:
            conn.rollback()
            return {"result": "cas_fail"}
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    rule = travel_rule_get(conn, rule["id"])
    if rule["status"] == "retired":
        n = _travel_rule_group_cleanup(conn, state_conn, rule, now=now)
        return {"result": "applied", "rule": rule, "cleaned": n}
    if rule["status"] == "active":
        # D3-1: a pin is superseded by an edit to the rule that governs it.
        # Clear BEFORE refreshing, or travel_refresh takes its pinned branch
        # and the owner's rule change lands as regen=0 created=0 -- exactly
        # what was measured on the 60 -> 30 change.
        if owner_edit:
            _travel_clear_pins_rule(conn, rule, now=now)
        travel_refresh_rule(conn, state_conn, rule, now=now)
    return {"result": "applied", "rule": rule}


def travel_rule_retire(conn, rule_token, state_conn=None, now=None):
    """Retire a rule (derivation stops) + group cleanup of live future
    blocks (3.2 / 5.3 rollback step 1-2 shape)."""
    return travel_rule_upd(conn, rule_token, {"status": "retired"},
                           state_conn=state_conn, now=now)


def _travel_rule_group_cleanup(conn, state_conn, rule, now=None):
    """Tombstone all live FUTURE blocks of a rule (started/past = lifelog,
    untouched)."""
    now = now or now_utc()
    state_conn = _travel_state_conn(state_conn)
    n = 0
    for row in _travel_iter_rule_blocks(conn, rule):
        if row["start_at"] is not None and row["start_at"] > now:
            if _travel_tombstone_block(conn, state_conn, row) != "skipped":
                n += 1
    return n


def _travel_iter_rule_blocks(conn, rule):
    """Live blocks belonging to a rule (via anchor resolution)."""
    if rule["anchor_type"] == "event":
        return _travel_rows(
            conn, "SELECT * FROM timeblock WHERE block_class='travel' "
            "AND derived_from=? AND settled_at IS NULL;",
            (rule["anchor_ulid"],))
    d = conn.execute("SELECT recurrence_id FROM routine_def WHERE ulid=?;",
                     (rule["anchor_ulid"],)).fetchone()
    if d is None:
        return []
    return _travel_rows(
        conn, "SELECT b.* FROM timeblock b JOIN timeblock a ON a.ulid=b.derived_from "
        "WHERE b.block_class='travel' AND b.settled_at IS NULL "
        "AND a.recurrence_id=?;", (d[0],))


def _travel_rule_anchor_instances(conn, rule):
    """Anchor instance ulids a rule governs right now: live instances plus
    any instance that still has live blocks (so tombstones converge)."""
    if rule["anchor_type"] == "event":
        return [rule["anchor_ulid"]]
    d = conn.execute("SELECT recurrence_id FROM routine_def WHERE ulid=?;",
                     (rule["anchor_ulid"],)).fetchone()
    if d is None:
        return []
    rows = conn.execute(
        "SELECT ulid FROM timeblock WHERE recurrence_id=? AND settled_at IS NULL "
        "UNION "
        "SELECT a.ulid FROM timeblock b JOIN timeblock a ON a.ulid=b.derived_from "
        "WHERE b.block_class='travel' AND b.settled_at IS NULL "
        "AND a.recurrence_id=?;", (d[0], d[0])).fetchall()
    return [r[0] for r in rows]


# ── derive(): the pure expected-blocks function (1/2.6/3.6) ───────────────

def _travel_anchor_eligible(anchor):
    """Anchor eligibility predicate (spec 1, deterministic): timed, has a
    start, unsettled, and not itself a block (no derivation of
    derivations). all_day/untimed anchors are structurally out (OQA-13)."""
    return (anchor.get("schedule_kind") == "timed"
            and anchor.get("start_at") is not None
            and anchor.get("settled_at") is None
            and anchor.get("block_class") is None)


def _travel_stop_place_id(conn, ev):
    """Rule 2 of the outing model (2026-09-30, "as a layer of events"): the place a
    live block puts the owner at, for ANY kind -- the block's own place_id
    first, else its place text resolved the deterministic way. None = the
    block is not at a known place (a call, a no-venue task)."""
    if travel_core.attendance_online(sys.modules[__name__], conn, ev):
        return None
    pid = ev.get("place_id")
    if pid is not None:
        return pid if travel_core.attendance_physical_place(sys.modules[__name__], conn, travel_place_get(conn, pid)) else None
    if ev.get("location"):
        place = _resolve_location_place(conn, ev["location"])
        return place["id"] if place is not None else None
    return None


def _travel_external(conn, ev):
    """external(E) of the chain predicate (2.6): E is an instance of an
    anchor holding an ACTIVE travel_rule (user is out at E's place), OR an
    appointment whose location resolves to a known place, OR (Rule 2,
    2026-09-30) any other TIMED live block whose place resolves to a place
    that is not home -- a stay (presence), a place-bound todo. Kind does not
    decide whether the body is somewhere; the place does. Home is not an
    out-of-home stop: treating a block at home as "already out" would drop
    the home-prep of the next outing and the return leg of the previous one.
    Judgment-impossible = NOT external = prep included (upward safe side)."""
    if travel_core.attendance_online(sys.modules[__name__], conn, ev):
        return False
    if ev.get("block_class") is not None:
        return False          # a derived block is never an out-at-place stay
    if _travel_rule_for_anchor_txn(
            conn, ev["ulid"], ev.get("recurrence_id")) is not None:
        return True
    if ev.get("kind") == "appointment":
        if ev.get("location"):
            return travel_core.attendance_physical_place(
                sys.modules[__name__], conn, _resolve_location_place(conn, ev["location"]))
        return False
    if ev.get("schedule_kind", "timed") != "timed":
        return False
    pid = _travel_stop_place_id(conn, ev)
    return pid is not None and pid != _travel_base_place_id(conn)


# -- the outing as a layer of events (owner 2026-09-30) ----------------------
# Every bundle -- an outing, a trip, a stay, a workday -- is an `event` in the
# existing two-layer parent/child hierarchy; its legs are the timed blocks
# linked to it through event_timeblock. Time lives only on the blocks (the
# span is derived, _event_span). One concept, two rules:
#   Rule 1 (move together): two CONSECUTIVE legs under the same root event
#     travel together -- no travel leg, no prep, no arrival buffer and no
#     home-return between them. The day card says day.gap.together once.
#   Rule 2 (chain stop): any live timed block whose place resolves is a stop
#     on the travel chain, whatever its kind (_travel_external).
# No new table or column: the bundle IS the event row, the leg IS the block.

def _bundle_event_ids(conn, event_id):
    """The root of event_id plus every child of that root (two layers)."""
    row = conn.execute("SELECT COALESCE(parent_id, id) FROM event "
                       "WHERE id=?;", (int(event_id),)).fetchone()
    if row is None:
        return []
    root = row[0]
    return [root] + [r[0] for r in conn.execute(
        "SELECT id FROM event WHERE parent_id=? ORDER BY id;", (root,))]


def _block_bundle_roots(conn, block_id):
    """Root event ids (COALESCE(parent_id, id)) of every event a block is
    linked to. Empty for a block in no bundle -- which is every block on a
    day nobody grouped, so every Rule 1 probe is a no-op there."""
    if block_id is None:
        return set()
    try:
        return {r[0] for r in conn.execute(
            "SELECT DISTINCT COALESCE(e.parent_id, e.id) "
            "FROM event_timeblock et JOIN event e ON e.id = et.event_id "
            "WHERE et.timeblock_id=?;", (int(block_id),))}
    except sqlite3.Error:
        return set()


def _same_bundle(conn, a, b):
    """True when blocks a and b (ids) sit under the same root event."""
    ra = _block_bundle_roots(conn, a)
    return bool(ra) and bool(ra & _block_bundle_roots(conn, b))


def _travel_bundle_neighbour(conn, anchor, direction):
    """Rule 1: the leg of the anchor's bundle IMMEDIATELY before
    (direction='prev') or after ('next') it, or None.

    Immediately = the nearest live timed leg of the same root event that
    ends at/before the anchor starts (prev) or starts at/after it ends
    (next), with no OTHER chain stop starting in between. A stop between
    them means the owner went somewhere else in the middle, so the two legs
    are no longer consecutive and ordinary travel applies. A row with no
    place (a call, a note) does not break the pair; a stay that began
    before the gap and still covers it does not either (it is not between).
    """
    if anchor.get("id") is None:
        return None
    roots = _block_bundle_roots(conn, anchor["id"])
    if not roots:
        return None
    ids = set()
    for root in roots:
        ids.update(_bundle_event_ids(conn, root))
    marks = ",".join("?" * len(ids))
    base_sql = (
        "SELECT t.* FROM event_timeblock et "
        "JOIN timeblock t ON t.id = et.timeblock_id "
        "WHERE et.event_id IN (%s) AND t.settled_at IS NULL "
        "AND t.block_class IS NULL AND t.schedule_kind='timed' "
        "AND t.start_at IS NOT NULL AND t.end_at IS NOT NULL "
        "AND t.id != ? " % marks)
    if direction == "prev":
        if anchor.get("start_at") is None:
            return None
        leg = _travel_row(
            conn, base_sql + "AND t.end_at <= ? "
            "ORDER BY t.end_at DESC, t.id DESC LIMIT 1;",
            list(ids) + [anchor["id"], anchor["start_at"]])
        lo = leg["end_at"] if leg else None
        hi = anchor["start_at"]
    else:
        if anchor.get("end_at") is None:
            return None
        leg = _travel_row(
            conn, base_sql + "AND t.start_at >= ? "
            "ORDER BY t.start_at, t.id LIMIT 1;",
            list(ids) + [anchor["id"], anchor["end_at"]])
        lo = anchor["end_at"]
        hi = leg["start_at"] if leg else None
    if leg is None:
        return None
    for ev in _travel_rows(
            conn,
            "SELECT id, ulid, kind, location, recurrence_id, block_class, "
            "derived_from, place_id, schedule_kind FROM timeblock "
            "WHERE settled_at IS NULL AND block_class IS NULL "
            "AND start_at IS NOT NULL AND start_at >= ? AND start_at < ? "
            "AND id NOT IN (?, ?);", (lo, hi, anchor["id"], leg["id"])):
        if (_travel_external(conn, ev)
                and not _same_bundle(conn, ev["id"], anchor["id"])):
            return None
    return leg


def _travel_chain(conn, rule, anchor, departure, home_departure=None):
    """chain(anchor) (2.6, deterministic): True -> prep_eff = 0 (the owner is
    positively known to be out and continuing). Siblings of this rule are
    excluded.

    Owner 2026-10-15 13:11 ("isn't the constraint too strict") + the
    2026-09-20 rule (a missed prep alert is worse than an extra one): a stop
    ending inside [departure - N, departure] is NOT enough on its own. The
    leg loses its prep only when such a stop is at a known non-home place
    AND the trip home provably does not fit before the departure
    (_travel_home_return_verdict is False). Home return fits (True) or the
    system cannot tell (None: no return leg, no rule, unknown durations) ->
    prep stays. Measured miss this replaces: the gym (05:00-07:00, place
    stamped 10-11, no travel rule since the 09-28 reset) read as "just in"
    for the 07:45 office departure and dropped the 07:15 prep every gym day.

    home_departure: when the leg leaves from a non-home origin (a hop), the
    instant the owner would have to leave HOME to make the same arrival; the
    return verdict is judged against it. None = `departure` (home origin)."""
    lo = _iso_shift_min(departure, -TRAVEL_CHAIN_WINDOW_MIN)
    cands = _travel_rows(
        conn,
        "SELECT id, ulid, kind, location, recurrence_id, block_class, "
        "derived_from, place_id, schedule_kind, end_at FROM timeblock "
        "WHERE settled_at IS NULL "
        "AND end_at IS NOT NULL AND end_at >= ? AND end_at <= ? "
        "AND id != ? "
        "AND NOT (block_class IS 'travel' AND derived_from IS ?);",
        (lo, departure, anchor["id"], anchor["ulid"]))
    for ev in cands:
        if not _travel_external(conn, ev):
            continue
        # 2026-08-23: "already out" holds only if the user never got HOME
        # (gym 05:00-07:00, home 07:15, office departure 07:45).
        if _travel_home_return_verdict(
                conn, ev, home_departure or departure) is False:
            return True
    return False


def _travel_returns_home_before(conn, ev, departure):
    """True when `ev` provably returns the user to base at or before
    `departure` (the True branch of _travel_home_return_verdict)."""
    return _travel_home_return_verdict(conn, ev, departure) is True


def _travel_home_return_verdict(conn, ev, departure):
    """Compatibility entry point; lifecycle policy lives in travel_core."""
    return travel_core._travel_home_return_verdict(sys.modules[__name__], conn, ev, departure)


def _travel_external_place_id(conn, ev):
    """DGN-841: RESOLVED place id of an external event `ev`. Symmetric to the
    _travel_external branches: a rule-holding anchor resolves to that active
    rule's place_id; an appointment resolves via its location text; any
    other stop (Rule 2) via _travel_stop_place_id. Returns a place id or None
    (None = not resolvable -> treat as non-chain, safe side, never guess)."""
    if travel_core.attendance_online(sys.modules[__name__], conn, ev):
        return None
    if ev.get("block_class") is not None:
        return None
    rule = _travel_rule_for_anchor_txn(
        conn, ev["ulid"], ev.get("recurrence_id"))
    if rule is not None:
        return rule.get("place_id")
    if ev.get("kind") == "appointment":
        if ev.get("location"):
            place = _resolve_location_place(conn, ev["location"])
            return place["id"] if travel_core.attendance_physical_place(sys.modules[__name__], conn, place) else None
        return None
    if not _travel_external(conn, ev):
        return None
    return _travel_stop_place_id(conn, ev)


def _travel_chain_origin_place_id(conn, anchor):
    """DGN-841 P1: chain-aware ORIGIN. If a live EXTERNAL event ends inside
    [anchor.start - N, anchor.start], the user is coming FROM that event's
    resolved place, so the origin is that place (NOT presence/base). Most-
    recent-ending neighbor wins (closest preceding stay). Excludes derived
    travel/prep blocks and this anchor's own siblings, exactly like
    _travel_chain. Returns a place id, or None when no such neighbor resolves
    (caller then falls through to the presence/base path, unchanged)."""
    at = anchor.get("start_at")
    if at is None:
        return None
    lo = _iso_shift_min(at, -TRAVEL_CHAIN_WINDOW_MIN)
    cands = _travel_rows(
        conn,
        "SELECT id, ulid, kind, location, recurrence_id, block_class, "
        "derived_from, end_at, place_id, schedule_kind FROM timeblock "
        "WHERE settled_at IS NULL "
        "AND end_at IS NOT NULL AND end_at >= ? AND end_at <= ? "
        "AND id != ? "
        "AND NOT (block_class IS 'travel' AND derived_from IS ?) "
        "ORDER BY end_at DESC;",
        (lo, at, anchor["id"], anchor["ulid"]))
    home = None
    for ev in cands:
        if _travel_external(conn, ev):
            pid = _travel_external_place_id(conn, ev)
            if pid is not None:
                # 2026-10-15: the stop is not the origin -- the leg leaves
                # from home -- when the trip home provably lands before the
                # owner would leave home for this anchor (gym 06:30-07:30,
                # home 07:45, office departure 07:45), or when that cannot be
                # told AND only the home leg has a duration: a hop with no
                # stop->dest duration derives no leg at all, and the 10-13
                # office day lost its leave-now alert that way. Provably not
                # home (False) stays the chain origin.
                if home is None:
                    home = _travel_home_departure(conn, anchor) or ("", None)
                home_dep, dest_id = home
                if home_dep:
                    v = _travel_home_return_verdict(conn, ev, home_dep)
                    if v is True:
                        continue
                    if (v is None and dest_id is not None
                            and _travel_edge_get(conn, pid, dest_id) is None):
                        continue
                return pid       # most-recent-ending external neighbor wins
    far = _travel_far_chain_neighbour(conn, anchor, "prev")
    if far is not None:
        return far["_place_id"]
    return None


def _travel_home_departure(conn, anchor):
    """(instant, dest_id): when the owner would leave HOME to reach `anchor`
    on time -- arrival (start - appointment buffer) minus the home->dest
    duration (a stored edge, either direction of the pair; dest = the
    anchor's rule place, else its own place). None when either end or the
    duration is unknown. Read only; never raises."""
    try:
        if anchor.get("start_at") is None:
            return None
        base_id = _travel_base_place_id(conn)
        rule = (_travel_rule_for_anchor_txn(
            conn, anchor["ulid"], anchor.get("recurrence_id"))
            if anchor.get("ulid") else None)
        dest_id = ((rule or {}).get("place_id") or anchor.get("place_id"))
        if (base_id is None or dest_id is None or dest_id == base_id
                or not _travel_edge_schema_ready(conn)):
            return None
        e = (_travel_edge_get(conn, base_id, dest_id)
             or _travel_edge_get(conn, dest_id, base_id))
        if e is not None:
            out = int(e["minutes"])
        else:
            # the same base-origin fallbacks _travel_resolve_before_leg
            # derives from: the place's to_min, else the rule's own declared
            # before_min (the 036 edge hole, 2026-09-17)
            dest = travel_place_get(conn, dest_id) or {}
            out = dest.get("to_min")
            if out is None and rule is not None:
                out = rule.get("before_min")
            out = int(out or 0)
        if out <= 0:
            return None
        buffer_eff = _travel_appt_buffer_min(anchor, conn)
        arrival = (_iso_shift_min(anchor["start_at"], -buffer_eff)
                   if buffer_eff > 0 else anchor["start_at"])
        return _iso_shift_min(arrival, -out), dest_id
    except Exception:  # noqa: BLE001 -- a probe never breaks derivation
        return None


# -- the chain beyond the window: does a trip home fit in the gap? ----------
# (owner 2026-10-05 21:16) a rehearsal ended 15:00, a brewery visit started
# 16:30. The 60-minute chain window called that "not chained", so the deriver sent the
# owner home at 15:00 and out again from home -- a round trip that cannot
# fit: 45 min back, a move out and the 15-min arrival buffer do not fit in
# 90 minutes. Past the window the chain is judged from the geometry instead:
# two consecutive stops of one local day are chained when the trip home
# between them provably does not fit. The window rule is untouched (inside
# it the stops are always chained); this only adds the case past it.

def _travel_home_fits_between(conn, from_pid, to_pid, gap_min, buffer_min):
    """Does a stop at home fit between leaving `from_pid` and arriving at
    `to_pid` `gap_min` minutes later (buffer_min = the arrival margin)?

    True / False, or None when it cannot be judged. Minutes come from stored
    edges only: from->home and home->to (else to->home, the same pair
    measured the other way). An unknown leg borrows the direct from->to
    hop -- the only measured scale of this trip -- for this yes/no judgment
    only; no block ever carries borrowed minutes. Nothing known -> None."""
    base_id = _travel_base_place_id(conn)
    if base_id is None or from_pid is None or to_pid is None:
        return None
    if base_id in (from_pid, to_pid):
        return True               # one end IS home: nothing to chain past it
    if not _travel_edge_schema_ready(conn):
        return None

    def _mins(a, b):
        e = _travel_edge_get(conn, a, b)
        return int(e["minutes"]) if e is not None else None

    direct = _mins(from_pid, to_pid)
    ret = _mins(from_pid, base_id)
    out = _mins(base_id, to_pid)
    if out is None:
        out = _mins(to_pid, base_id)
    ret = ret if ret is not None else direct
    out = out if out is not None else direct
    if ret is None or out is None:
        return None
    return ret + out + int(buffer_min or 0) <= int(gap_min)


def _travel_far_chain_neighbour(conn, anchor, direction):
    """The stop chained to `anchor` from PAST the chain window, or None.

    direction='prev': the latest live external stop of the same local day
    ending more than TRAVEL_CHAIN_WINDOW_MIN before the anchor starts;
    'next': the earliest one starting more than that after it ends. Either
    must be the IMMEDIATE neighbour (no other external stop starts between
    them), both places must resolve, the earlier stop must carry no pinned
    return leg (the owner placed that trip home), and the trip home between
    them must provably not fit (_travel_home_fits_between False). The
    returned row carries its place id under '_place_id'.

    v3.2 only (the legacy axis keeps its window rule byte for byte, the same
    gate _travel_has_following_external applies). Never raises."""
    try:
        if not _is_v32(conn) or anchor.get("block_class") is not None:
            return None
        if anchor.get("start_at") is None or anchor.get("end_at") is None:
            return None
        my_pid = _travel_external_place_id(conn, anchor)
        if my_pid is None:
            my_pid = _travel_stop_place_id(conn, anchor)
        if my_pid is None:
            return None
        lo, hi = _travel_local_day_window(anchor["start_at"])
        cols = ("SELECT id, ulid, kind, location, recurrence_id, block_class, "
                "derived_from, start_at, end_at, place_id, schedule_kind "
                "FROM timeblock WHERE settled_at IS NULL "
                "AND block_class IS NULL AND schedule_kind='timed' "
                "AND start_at IS NOT NULL AND end_at IS NOT NULL "
                "AND id != ? ")
        if direction == "prev":
            edge_at = _iso_shift_min(anchor["start_at"],
                                     -TRAVEL_CHAIN_WINDOW_MIN)
            cands = _travel_rows(
                conn, cols + "AND end_at >= ? AND end_at < ? "
                "ORDER BY end_at DESC, id DESC;",
                (anchor["id"], lo, edge_at))
        else:
            edge_at = _iso_shift_min(anchor["end_at"],
                                     TRAVEL_CHAIN_WINDOW_MIN)
            cands = _travel_rows(
                conn, cols + "AND start_at > ? AND start_at < ? "
                "ORDER BY start_at, id;", (anchor["id"], edge_at, hi))
        ev = next((c for c in cands if _travel_external(conn, c)), None)
        if ev is None:
            return None
        ev_pid = _travel_external_place_id(conn, ev)
        if ev_pid is None:
            return None
        first, second = (ev, anchor) if direction == "prev" else (anchor, ev)
        # immediate: no other external stop starts between the two
        for mid in _travel_rows(
                conn, cols + "AND id != ? AND start_at >= ? AND start_at < ?;",
                (first["id"], second["id"], first["end_at"],
                 second["start_at"])):
            if _travel_external(conn, mid):
                return None
        if conn.execute(
                "SELECT 1 FROM timeblock WHERE block_class='travel' "
                "AND derived_from=? AND derived_role='after' "
                "AND settled_at IS NULL AND derived_pinned=1 LIMIT 1;",
                (first["ulid"],)).fetchone() is not None:
            return None
        gap = _iso_diff_min(second["start_at"], first["end_at"])
        fits = _travel_home_fits_between(
            conn, ev_pid if direction == "prev" else my_pid,
            my_pid if direction == "prev" else ev_pid,
            gap, _travel_appt_buffer_min(second, conn))
        if fits is not False:
            return None
        ev = dict(ev)
        ev["_place_id"] = ev_pid
        return ev
    except Exception:  # noqa: BLE001 -- a probe never breaks derivation
        return None


def _travel_expected_exclusive(conn, rule, anchor, bs, be):
    """DGN-579 D-C1 (owner-locked): movement blocks are ALWAYS soft
    (slot_exclusive = 0). The DGN-274 3.6 demotion predicate (exclusive
    unless an external live exclusive blocker overlaps, with the seniority
    tie-break) is retired: movement is derived background context and never
    occupies the slot. Overlap visibility moved to the MOVEMENT_OVERLAP
    response contract (B2b). Signature kept so derive() call sites and the
    reconcile expected-value shape stay unchanged."""
    return 0


def _travel_after_suppressed(conn, anchor, as_, ae):
    """DGN-314: after-leg suppression predicate -- deterministic, read-only.
    Returns True if a live external travel block with derived_role='before'
    overlaps the ideal after interval [as_, ae) half-open.

    Conditions (all must hold for a suppressing row):
      block_class = 'travel'
      settled_at IS NULL
      derived_from != anchor.ulid   (not a sibling of this anchor)
      derived_role = 'before'       (next anchor's outbound leg)
      interval overlap [as_, ae) half-open: start_at < ae AND end_at > as_

    before_prep overlaps do NOT suppress (spec DGN-314 delta item 2)."""
    rows = _travel_rows(
        conn,
        "SELECT 1 FROM timeblock WHERE block_class='travel' "
        "AND settled_at IS NULL "
        "AND derived_from IS NOT ? "
        "AND derived_role='before' "
        "AND start_at < ? AND end_at > ?;",
        (anchor["ulid"], ae, as_))
    return len(rows) > 0


# ── DGN-623: movement spatial awareness (presence-origin + travel_edge) ────

# Edge-resolution status codes surfaced to the deriver / reconciler. On a
# 'missing' the before leg cannot be derived deterministically and the attach
# layer emits an elicitation signal naming BOTH origin and dest.
TRAVEL_EDGE_OK = "ok"                # a stored edge (origin -> dest) was found
TRAVEL_EDGE_MISSING = "missing"     # origin != dest but no edge is registered
TRAVEL_EDGE_SAME = "same"           # origin == dest (already there; no move)
TRAVEL_EDGE_SIBLING = "sibling"     # Rule 1: previous leg of the same bundle
                                    # (the owner moves WITH the outing; no leg)


def _travel_edge_schema_ready(conn):
    """True iff the travel_edge table exists (v21+). Older DBs degrade to the
    node-column (base-origin) path so the deriver never hard-fails mid-rollout."""
    try:
        # v3.2: travel_edge is a compat VIEW over place_link + measure -- the
        # read surface is the same, so a view counts as ready.
        return conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type IN ('table','view') "
            "AND name='travel_edge' LIMIT 1;").fetchone() is not None
    except sqlite3.Error:
        return False


def _travel_edge_get(conn, from_place_id, to_place_id):
    """The stored one-way edge row (from -> to), or None. Ordered pair."""
    if from_place_id is None or to_place_id is None:
        return None
    return _travel_row(
        conn, "SELECT * FROM travel_edge WHERE from_place_id=? "
        "AND to_place_id=?;", (from_place_id, to_place_id))


def _travel_edge_retracted(conn, from_id, to_id):
    if not _is_v32(conn):
        return False
    return conn.execute(
        "SELECT 1 FROM measure m JOIN place_link p ON p.id=m.place_link_id "
        "WHERE p.from_place_id=? AND p.to_place_id=? AND m.metric=? "
        "AND m.basis='actual' AND m.valid_until IS NOT NULL LIMIT 1",
        (from_id, to_id, TRAVEL_METRIC_MIN)).fetchone() is not None


# Sentinel default for travel_edge_add's prep_min: "the caller said NOTHING
# about prep". prep_min=None used to mean two different things -- not supplied
# AND clear it -- and the collision was live: travel-resolve.sh registers a
# resolved duration with minutes only, and that omission destroyed the pair's
# declared prep (2026-09-05: the owner's 집->회사 prep 30 wiped by an automatic
# route resolution). Omitted now PRESERVES; None stays the EXPLICIT clear.
TRAVEL_PREP_KEEP = object()


def travel_edge_add(conn, from_place_id, to_place_id, minutes,
                    prep_min=TRAVEL_PREP_KEEP, now=None):
    """Register / update a one-way edge (from -> to). Grid-ceils minutes.
    Upsert on the ordered pair. Returns the edge row. src='place' before-legs
    of active rules that would now resolve to this edge are refreshed by the
    caller (verb layer), matching the node-column propagation contract (2.3).

    prep_min: omitted -> the stored prep is left alone (a duration update is
    not a statement about prep); an int -> set; None -> EXPLICIT clear (legacy
    NULL / v3.2 retract). Same semantics on both axes, storage differs."""
    if from_place_id == to_place_id:
        raise ValueError("travel_edge_add: from and to must differ")
    now = now or now_utc()
    m = _ceil_grid(minutes)
    keep_prep = prep_min is TRAVEL_PREP_KEEP
    p = _ceil_grid(prep_min) if not keep_prep and prep_min is not None else None
    if _is_v32(conn):
        # v3.2: the pair gets an identity (place_link) and the numbers get
        # measure rows. An omitted prep writes NOTHING to the prep metric --
        # the in-force declaration stands. An explicit clear is a retract
        # (in-force row expires, no replacement).
        conn.execute("BEGIN IMMEDIATE;")
        try:
            lid = _travel_v32_link_id(conn, from_place_id, to_place_id,
                                      create=True)
            _travel_v32_set(conn, lid, TRAVEL_METRIC_MIN, m, now=now)
            if not keep_prep:
                _travel_v32_set(conn, lid, TRAVEL_METRIC_PREP, p, now=now)
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        return _travel_edge_get(conn, from_place_id, to_place_id)
    conn.execute("BEGIN IMMEDIATE;")
    try:
        if keep_prep:
            # prep_min stays OUT of the conflict SET: an existing value
            # survives; a fresh pair starts with no prep declared.
            conn.execute(
                "INSERT INTO travel_edge(from_place_id, to_place_id, "
                "minutes, prep_min, created_at, updated_at) "
                "VALUES(?,?,?,NULL,?,?) "
                "ON CONFLICT(from_place_id, to_place_id) DO UPDATE SET "
                "minutes=excluded.minutes, updated_at=excluded.updated_at;",
                (from_place_id, to_place_id, m, now, now))
        else:
            conn.execute(
                "INSERT INTO travel_edge(from_place_id, to_place_id, "
                "minutes, prep_min, created_at, updated_at) "
                "VALUES(?,?,?,?,?,?) "
                "ON CONFLICT(from_place_id, to_place_id) DO UPDATE SET "
                "minutes=excluded.minutes, prep_min=excluded.prep_min, "
                "updated_at=excluded.updated_at;",
                (from_place_id, to_place_id, m, p, now, now))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return _travel_edge_get(conn, from_place_id, to_place_id)


# ── G0a: auto travel-time SOURCE adapter dispatch ─────────────────────────
# The engine owns only the DETERMINISTIC seam: which source is active, and the
# fail-open resolution order. The `agent` source itself is an LLM-driven
# browser procedure that lives in the schedule-log skill (no unit-testable
# code here -- the browser run is runtime-LLM). `kakao-api` is a stubbed slot.
# Everything below is pure dispatch + a documented stub, so it IS testable.

# Resolution order when the selected source cannot serve an edge_missing NOW.
# `agent` needs a live conversational turn; in a background/cron context (no LLM
# turn) it must DEFER to manual so nothing blocks. Callers pass conversational=
# to say whether an LLM turn is present.
def travel_source_select(conversational=True, source=None):
    """Return the source that should try to fill a missing edge duration, given
    the configured LIFEKIT_TRAVEL_SOURCE and whether an LLM turn is present.

    Deterministic dispatch (never raises):
      - configured 'agent':
          conversational turn  -> 'agent'  (LLM reads the map via agent-browser)
          background/cron       -> 'manual' (defer; never block a headless run)
      - configured 'kakao-api': -> 'kakao-api' (deterministic; turn-agnostic).
          NOTE: the kakao-api adapter is a STUB (see travel_source_kakao_api);
          it fail-opens to manual at call time until the API is built.
      - configured 'manual' (or any unknown, via conf_str fail-open) -> 'manual'.

    `source` overrides the configured value (for tests / explicit callers).
    Returns one of TRAVEL_SOURCE_AGENT / TRAVEL_SOURCE_KAKAO_API /
    TRAVEL_SOURCE_MANUAL."""
    src = source if source is not None else TRAVEL_SOURCE
    if src not in TRAVEL_SOURCE_ALLOWED:
        src = TRAVEL_SOURCE_MANUAL          # defensive fail-open
    if src == TRAVEL_SOURCE_AGENT:
        return TRAVEL_SOURCE_AGENT if conversational else TRAVEL_SOURCE_MANUAL
    return src


def travel_source_kakao_api(origin_name, dest_name):
    """STUB -- kakao-api adapter slot (next-version promotion; DO NOT ship as
    live). Owner directive 2026-08-20: keyless `agent` ships now; `kakao-api`
    is the documented UPGRADE path (faster, headless, no browser).

    TODO(next version): implement the Kakao Mobility Directions API call.
      - endpoint: https://apis-navi.kakaomobility.com/v1/directions
      - auth: Authorization: KakaoAK <REST API key>  (owner free-quota key,
        provisioned + read from a secret knob, NOT hardcoded).
      - inputs: origin/dest coords (geocode place addresses first, e.g. via the
        Kakao Local geocode API) -> request driving route.
      - output: parse routes[0].summary.duration (seconds) -> ceil to minutes.
      - D7: discloses origin/dest + key identity to Kakao; record the 3-axis
        review when built (see the G0a D7 record).
    Until built, this returns None so the dispatch fail-opens to manual. The
    interface (origin_name, dest_name) -> int minutes | None is the contract a
    real adapter must satisfy."""
    return None       # not implemented; caller falls open to manual


def _travel_origin_place_id(conn, anchor):
    """Presence-aware ORIGIN place for an anchor: where the user IS at the
    anchor's start. Resolution order:
      0. 2.37.0: the appointment's owner-stated origin (block_attr
         origin_place_id, written by appt-origin).
      1. DGN-841 P1 chain origin: a live external event ending in
         [start - N, start] -> origin = that neighbor's resolved place (the
         user is coming straight from it; no home round-trip in between).
      2. presence layer (presence row covering start), else base (집).
    Returns a place id or None (no presence/base seeded)."""
    at = anchor.get("start_at")
    if at is None:
        return None
    # 2.37.0: the owner said where they leave from for THIS appointment
    # (appt-origin, the ORIGIN_ASK answer) -- that outranks every inference.
    stated = _appt_origin_override(conn, anchor.get("id"))
    if stated is not None:
        return stated
    chain_origin = _travel_chain_origin_place_id(conn, anchor)
    if chain_origin is not None:
        return chain_origin
    try:
        # Exclude the anchor itself: when the anchor IS the presence row (a
        # kind=presence routine instance), an unexcluded lookup self-matches
        # and reports the destination as the origin (see presence_at).
        _kind, place_id, _rid = presence_at(
            conn, at, exclude_event_id=anchor.get("id"))
    except Exception:
        return None
    return place_id


# Prep default (owner 2026-10-06 07:28: prep time takes a default, and every
# event can still carry its own). ONE user-level default (config key travel_prep_min, asked
# once -- prep-default-ask) applies to every rule leg whose prep nobody chose;
# a per-event value (travel-rule-upd prep_min=N, 0 included) always wins, and
# so does a place's own travel_prep_min measure (edge prep, unchanged).
# The default is only the DECLARED prep: _travel_prep_gate still zeroes it
# for a chain outing / a hop from a non-base place, and the day scope keeps
# one prep per day -- a chain outing stays prep 0.
#
# "Nobody chose" is prep_src='provisional' from now on (travel_rule_add
# stamps it when no prep was given and the place has none). Rules written
# before that carry prep_src='explicit' + prep_min 0 for the same case: every
# auto-attach path (appt / def / provisional stopgap) wrote that pair without
# ever asking about prep, and those rules have before_src 'place' or
# 'provisional' -- a hand-declared leg has before_src 'explicit'. So a legacy
# row is unset when it is explicit-0 on an auto-attached leg AND was last
# written before TRAVEL_PREP_LEGACY_BEFORE. Nothing is mass-rewritten: a writer
# that touches such a row for another reason relabels it 'provisional' in the
# same UPDATE (_TRAVEL_PREP_RELABEL_SQL), so the read keeps its meaning, and
# an explicit 0 written after the cutover is the user's "no prep".
TRAVEL_PREP_DEFAULT_KEY = "travel_prep_min"
TRAVEL_PREP_ENABLED_KEY = "travel_prep_enabled"


def _travel_prep_enabled(conn):
    """Prep derivation is opt-in; stored minutes alone never enable it.

    Step 1 of the 2026-10-20 prep removal keeps the schema, minute sources
    and existing blocks intact. config-set travel_prep_enabled=1 restores
    the previous derivation and onboarding behavior.
    """
    return _config_stored(conn, TRAVEL_PREP_ENABLED_KEY) == "1"


TRAVEL_PREP_LEGACY_BEFORE = "2026-10-06T00:00:00Z"
_TRAVEL_PREP_LEGACY_UNSET_SQL = (
    "(prep_src='explicit' AND prep_min=0 "
    "AND before_src IN ('place','provisional') AND updated_at < '%s')"
    % TRAVEL_PREP_LEGACY_BEFORE)
_TRAVEL_PREP_RELABEL_SQL = (
    ", prep_src=CASE WHEN " + _TRAVEL_PREP_LEGACY_UNSET_SQL +
    " THEN 'provisional' ELSE prep_src END")


def _travel_prep_default(conn):
    """The user's default prep minutes (config travel_prep_min, grid-ceiled),
    or None when never answered -- None changes nothing (prep stays the
    rule's own value, i.e. 0 for an unset leg)."""
    try:
        row = conn.execute("SELECT value FROM config WHERE key=?;",
                           (TRAVEL_PREP_DEFAULT_KEY,)).fetchone()
    except sqlite3.Error:
        return None
    if row is None or row[0] is None:
        return None
    try:
        return _ceil_grid(int(str(row[0]).strip()))
    except (TypeError, ValueError):
        return None


def _travel_rule_prep_unset(rule):
    """True when nobody chose this rule's prep (see the block above)."""
    src = rule.get("prep_src")
    if src == "provisional":
        return True
    return (src == "explicit" and int(rule.get("prep_min") or 0) == 0
            and rule.get("before_src") in ("place", "provisional")
            and (rule.get("updated_at") or "") < TRAVEL_PREP_LEGACY_BEFORE)


def _travel_rule_prep(conn, rule):
    """Declared prep minutes of one rule: its own value, or the user default
    when the rule's prep is unset and a default was answered."""
    if _travel_rule_prep_unset(rule):
        default = _travel_prep_default(conn)
        if default is not None:
            return default
    return int(rule.get("prep_min") or 0)


def _travel_resolve_before_leg(conn, rule, anchor):
    """DGN-623 core: resolve the OUTBOUND (origin -> dest) leg for one anchor
    instance, presence-aware. Returns (minutes, prep_min, status, origin_id):

      - explicit before leg (before_src != 'place'): the user's declared value
        wins, unchanged -- return (rule.before_min, rule.prep_min, OK, None).
      - place-sourced leg on a pre-v21 DB / rule without place_id: fall back to
        the node-column value already baked in the rule (base-origin legacy).
      - place-sourced with an edge store: origin = presence place at event time;
        dest = rule.place_id.
          origin == dest -> SAME (already there; before leg collapses to 0).
          edge(origin,dest) present -> OK with the edge minutes (+ edge prep if
            set, else the rule's prep default).
          edge missing -> MISSING (deriver omits the before leg; the attach
            layer elicits origin->dest). Never guess a duration.
    prep rides the outbound leg only.

    Rule 1 (2026-09-30) is decided FIRST: when the previous leg of the
    anchor's own bundle is its immediate predecessor, the owner moves with
    the outing -- (0, 0, SIBLING, that leg's place). No before leg, no prep,
    and (before_eff 0) no arrival buffer; nothing to elicit either."""
    sib = _travel_bundle_neighbour(conn, anchor, "prev")
    if sib is not None:
        return 0, 0, TRAVEL_EDGE_SIBLING, _travel_stop_place_id(conn, sib)
    before_min = int(rule["before_min"])
    prep_min = _travel_rule_prep(conn, rule)
    if rule.get("before_src") != "place" or rule.get("place_id") is None:
        # explicit declaration or rule-less place -> keep the baked value.
        return before_min, prep_min, TRAVEL_EDGE_OK, None
    if not _travel_edge_schema_ready(conn):
        # pre-v21: node-column base-origin behavior preserved verbatim.
        return before_min, prep_min, TRAVEL_EDGE_OK, None
    dest_id = rule["place_id"]
    origin_id = _travel_origin_place_id(conn, anchor)
    if origin_id is None:
        # presence layer gave nothing (no base seeded): keep baked value.
        return before_min, prep_min, TRAVEL_EDGE_OK, None
    if origin_id == dest_id:
        return 0, 0, TRAVEL_EDGE_SAME, origin_id
    edge = _travel_edge_get(conn, origin_id, dest_id)
    if edge is not None:
        # G0b: a minutes==0 edge is an explicit owner declaration that the
        # dest is negligibly near the origin (집->gym 5-min walk). Treat it as
        # SAME/already-there: NO before leg AND NO prep (prep forced 0). The
        # edge CHECK (minutes>=0 AND minutes%15==0) makes 0 storable, so this
        # is a first-class "near" outcome, not a missing edge. Real edges (>0)
        # keep deriving exactly as before.
        if int(edge["minutes"]) == 0:
            return 0, 0, TRAVEL_EDGE_SAME, origin_id
        e_prep = edge["prep_min"] if edge["prep_min"] is not None else prep_min
        return int(edge["minutes"]), int(e_prep), TRAVEL_EDGE_OK, origin_id
    if _travel_edge_retracted(conn, origin_id, dest_id):
        return 0, 0, TRAVEL_EDGE_MISSING, origin_id
    # No materialized edge. If the origin IS the base (집) and the dest place
    # carries a to_min node column, that column IS the implicit base->place edge
    # (back-compat: pre-edge places and directly-seeded to_min still derive).
    base = conn.execute("SELECT id FROM place WHERE is_base=1;").fetchone()
    if base is not None and origin_id == base[0]:
        dest = travel_place_get(conn, dest_id)
        if dest is not None and dest.get("to_min") is not None:
            dp = dest.get("prep_min")
            return (int(dest["to_min"]),
                    int(dp) if dp is not None else prep_min,
                    TRAVEL_EDGE_OK, origin_id)
        # LAST base-origin fallback: the rule's OWN baked before_min.
        #
        # Measured 2026-09-17 (owner's live instance): 036 moved edge minutes
        # into measure rows and carried the place_link rows WITHOUT them --
        # 29 links, 10 with a travel_min measure, and every pre-036 pair
        # (집->회사 among them) lost its duration. place.to_min was emptied by
        # the same restructure, so the back-compat branch directly above --
        # which exists for exactly this rescue -- fell into the same hole.
        # Result: every before_src='place' rule silently stopped deriving its
        # outbound leg, and the owner's commute prep+travel vanished from the
        # calendar for 26 days while `before_min=45 prep_min=30` sat unread in
        # the rule row the whole time.
        #
        # This is NOT a guess: for a base-origin leg the rule's baked column
        # IS the declared base->dest duration (this function's own docstring
        # calls it "base-origin legacy"), so reading it back is restoring the
        # owner's declaration, not inventing one. Scope is deliberately narrow
        # -- origin == base ONLY. A hop from a NON-base origin still returns
        # MISSING and elicits, because the flat column says nothing about
        # that pair and guessing there would be the invention this lane
        # refuses to make.
        if before_min > 0:
            return before_min, prep_min, TRAVEL_EDGE_OK, origin_id
    # Origin is a non-base place (or base with no usable declaration) and no
    # edge exists -> the deriver cannot know the duration. Signal elicitation.
    return 0, 0, TRAVEL_EDGE_MISSING, origin_id


def _travel_base_place_id(conn):
    """The base (집) place id, or None when no base is seeded."""
    row = conn.execute("SELECT id FROM place WHERE is_base=1;").fetchone()
    return row[0] if row is not None else None


def _travel_has_following_external(conn, anchor):
    """DGN-841 P2: True iff a live EXTERNAL event STARTS inside
    (anchor.end, anchor.end + N] -- i.e. the chain continues after this
    anchor, so this anchor is NOT the tail and must not emit a return leg
    (the next event's before leg / its own tail return owns the homeward
    trip). Symmetric to _travel_chain (same window N, same exclusions:
    derived travel/prep blocks and this anchor's own siblings)."""
    end = anchor.get("end_at")
    if end is None:
        return False
    hi = _iso_shift_min(end, TRAVEL_CHAIN_WINDOW_MIN)
    # v3.2: start_at >= end (not >) -- a back-to-back event starting EXACTLY
    # when this one ends is the chain continuing, so this anchor is interior
    # and must not emit a return. GATED (2026-09-05 review F3): this change
    # set replaces storage; the legacy axis keeps its old strict `>`
    # byte-for-byte. If `>=` is right there too, that is a separate,
    # separately-tested change.
    op = ">=" if _is_v32(conn) else ">"
    cands = _travel_rows(
        conn,
        "SELECT id, ulid, kind, location, recurrence_id, block_class, "
        "derived_from, start_at, place_id, schedule_kind FROM timeblock "
        "WHERE settled_at IS NULL "
        "AND start_at IS NOT NULL AND start_at " + op + " ? AND start_at <= ? "
        "AND id != ? "
        "AND NOT (block_class IS 'travel' AND derived_from IS ?);",
        (end, hi, anchor["id"], anchor["ulid"]))
    my_pid = None
    for ev in cands:
        if _travel_external(conn, ev):
            # 2026-10-15 (gym 06:30-07:30, office 08:30): inside the window a
            # trip home that provably fits (_travel_home_fits_between True)
            # means the owner goes home first -- this anchor keeps its return
            # leg, and the next stop leaves from home. Unknown stays chained.
            if _is_v32(conn) and ev.get("start_at"):
                if my_pid is None:
                    my_pid = (_travel_external_place_id(conn, anchor)
                              or _travel_stop_place_id(conn, anchor) or -1)
                ev_pid = _travel_external_place_id(conn, ev)
                if my_pid != -1 and ev_pid is not None and \
                        _travel_home_fits_between(
                            conn, my_pid, ev_pid,
                            _iso_diff_min(ev["start_at"], end),
                            _travel_appt_buffer_min(ev, conn)) is True:
                    continue
            return True
    # The owner said the next stop departs from HERE (appt-origin, or
    # presence-add --then): the trip leaves from this place, not from home,
    # so there is no return leg to emit (owner 2026-10-07, the stay that goes
    # straight to Friday lunch).
    if _travel_next_departs_from(conn, anchor):
        return True
    # past the window: still interior when the trip home cannot fit before
    # the next stop (_travel_far_chain_neighbour).
    return _travel_far_chain_neighbour(conn, anchor, "next") is not None


def _travel_next_departs_from(conn, anchor):
    """True when the first live stop starting after the anchor ends, within
    TRAVEL_ORIGIN_ASK_HORIZON_MIN, carries an owner-stated origin equal to
    the anchor's own place. v3.2 only (the attr lives there). Never raises."""
    try:
        end = anchor.get("end_at")
        if end is None or not _is_v32(conn):
            return False
        my_pid = _travel_stop_place_id(conn, anchor)
        if my_pid is None:
            return False
        hi = _iso_shift_min(end, TRAVEL_ORIGIN_ASK_HORIZON_MIN)
        for ev in _travel_rows(
                conn,
                "SELECT id, ulid, kind, location, recurrence_id, block_class, "
                "derived_from, start_at, place_id, schedule_kind "
                "FROM timeblock WHERE settled_at IS NULL "
                "AND block_class IS NULL AND start_at IS NOT NULL "
                "AND start_at >= ? AND start_at <= ? AND id != ? "
                "ORDER BY start_at, id;", (end, hi, anchor["id"])):
            stated = _appt_origin_override(conn, ev["id"])
            if stated is not None:
                return stated == my_pid
            if _travel_external(conn, ev):
                return False
        return False
    except Exception:  # noqa: BLE001 -- a probe never breaks derivation
        return False


def _travel_resolve_return_leg(conn, rule, anchor):
    """DGN-841 P2: DERIVED return-to-base leg for a chain TAIL. The after-leg
    is re-resolved from chain position at derive time (not a stored after_min
    knob), so it stays correct across drags/moves. Returns return minutes, or
    None when no return leg should be emitted.

    Emit a return (dest -> base) leg iff ALL hold:
      - the anchor's resolved origin (P1 chain / presence) is NON-base
        (the user is genuinely out of home for this event), AND
      - there is NO following external event within N after the anchor's end
        (this anchor is the chain tail; interior events emit no return), AND
      - the anchor's dest (rule.place_id) is known and differs from base.
    Duration source (symmetric to the before leg): edge(dest, base), else the
    dest place's from_min node column (base-origin back-compat). Missing both
    -> return None (omit the return leg silently, never fabricate).

    050 stopgap exception (owner 2026-10-09, "where is the trip home?"): a
    PROVISIONAL rule already guessed the outbound 60, so a missing duration
    is not a reason to drop the trip home -- the return mirrors the stopgap
    (_travel_provisional_return_min) until the dest->base edge is measured.
    The tail check and the dest==base check still apply."""
    mirror = _travel_provisional_return_min(rule)
    # A stopgap estimates time, not venue identity: the corrected appointment
    # place outranks a stale rule place (same rule as _travel_leg_places).
    dest_id = rule.get("place_id")
    if mirror is not None and anchor.get("place_id") is not None:
        dest_id = anchor["place_id"]
    if dest_id is None:
        if mirror is None or _travel_has_following_external(conn, anchor):
            return None
        return mirror             # venue unknown: the stopgap is all we have
    if not _travel_edge_schema_ready(conn):
        return mirror
    base_id = _travel_base_place_id(conn)
    if base_id is None:
        return mirror
    if dest_id == base_id:
        return None               # dest already home: no return
    origin_id = _travel_origin_place_id(conn, anchor)
    if origin_id is None:
        return mirror
    if origin_id == base_id and not _is_v32(conn):
        # legacy axis: the home-origin return is owned by the baked after_min
        # knob (place.from_min node column). v3.2 has no baked copy -- the
        # return is derive-time for EVERY origin, so home-origin falls through
        # to the same tail check + edge lookup as the chain case.
        return mirror
    if _travel_has_following_external(conn, anchor):
        return None               # interior event: the chain continues
    edge = _travel_edge_get(conn, dest_id, base_id)
    if edge is not None:
        # G0b: a 0 return edge = negligibly near base -> no return block
        # (symmetric with the SAME/0 outbound outcome). Emit nothing.
        if int(edge["minutes"]) == 0:
            return None
        return int(edge["minutes"])
    if _travel_edge_retracted(conn, dest_id, base_id):
        return None
    dest = travel_place_get(conn, dest_id)
    if dest is not None and dest.get("from_min") is not None:
        return int(dest["from_min"])
    return mirror                 # no duration known -> stopgap, else omit


def _travel_provisional_return_min(rule):
    """Return-leg minutes a 050 stopgap rule mirrors when the dest->base
    duration is unknown, or None. Only a rule whose OUTBOUND is the stamped
    guess (before_src='provisional') and whose return nobody declared
    (after_src 'place'/'provisional', after_min 0) mirrors; an explicit
    after leg -- 0 included -- is the owner's word and stays as declared."""
    if (rule.get("before_src") != TRAVEL_SRC_PROVISIONAL
            and rule.get("after_src") != TRAVEL_SRC_PROVISIONAL):
        return None
    if rule.get("after_src") not in ("place", TRAVEL_SRC_PROVISIONAL):
        return None
    if int(rule.get("after_min") or 0) > 0:
        return None
    before = (int(rule.get("before_min") or 0)
              if rule.get("before_src") == TRAVEL_SRC_PROVISIONAL
              else TRAVEL_PROVISIONAL_MIN)
    return before if before > 0 else None


def _travel_appt_buffer_min(anchor, conn=None):
    """D2: arrival-buffer minutes for ONE anchor instance.

    Scoped to APPOINTMENTS. The owner asked for a "약속 버퍼" -- an appointment
    buffer -- and a routine/presence anchor already owns a readiness margin in
    the home-prep block (DGN-305), so widening this to every anchor would
    double-count it and stamp an "약속 버퍼" label in front of 회사. Knob
    LIFEKIT_APPT_BUFFER_MIN (default 0); <=0 disables.

    NOT grid-ceil'd on purpose. _ceil_grid exists because an UNDER-allocated
    travel duration makes the owner late (ceil is the safe side). A buffer is
    an explicit owner quantity: silently rounding a declared 10 up to 15 would
    override the override, which is the opposite of "user-overridable"."""
    if anchor.get("kind") != "appointment":
        return 0
    if conn is not None:
        import appointment_buffer
        return appointment_buffer.resolve(sys.modules[__name__], conn, anchor)['minutes']
    return TRAVEL_APPT_BUFFER_MIN if TRAVEL_APPT_BUFFER_MIN > 0 else 0


def _travel_prep_gate(conn, rule, anchor, departure, origin_id, prep_declared):
    """Per-anchor home-prep minutes (no day scope): 0 when disabled or the owner is
    positively known to be out and continuing (_travel_chain); else the
    declared prep (owner 2026-10-15: unknown => prep ON).

    A hop (DGN-841 P1: the resolved origin is a non-base place) is judged by
    the same test, against the instant the owner would have to leave HOME
    for the same arrival (_travel_home_departure). Without that duration
    the hop departure itself is the bound."""
    if not _travel_prep_enabled(conn) or prep_declared <= 0:
        return 0
    base_id = _travel_base_place_id(conn)
    hop_from_place = (origin_id is not None and base_id is not None
                      and origin_id != base_id)
    home_departure = None
    if hop_from_place:
        home = _travel_home_departure(conn, anchor)
        if home is not None:
            home_departure = min(departure, home[0])
    if _travel_chain(conn, rule, anchor, departure,
                     home_departure=home_departure):
        return 0
    return prep_declared


def _travel_anchor_home_prep(conn, rule, anchor):
    """Home-prep minutes `anchor` would carry on its own, judged exactly the
    way travel_derive judges it before the day scope is applied."""
    before_eff, prep_declared, _st, origin_id = \
        _travel_resolve_before_leg(conn, rule, anchor)
    if before_eff <= 0 or prep_declared <= 0:
        return 0
    departure, _arr, _buf, away = _travel_before_geometry(
        conn, rule, anchor, before_eff)
    if away:
        return 0
    return _travel_prep_gate(conn, rule, anchor, departure, origin_id,
                             prep_declared)


def _travel_local_day_window(instant):
    """[00:00, next 00:00) of the owner-local day holding `instant`, as
    canonical UTC instants (A2: single display tz)."""
    day = _local_date_of(instant, TRAVEL_DISPLAY_TZ).strftime("%Y-%m-%d")
    return all_day_instants(day, tz_name=TRAVEL_DISPLAY_TZ)


def _travel_day_prep_held(conn, anchor, now):
    """DGN-623 slice3: True when ANOTHER anchor of the same local day already
    holds that day's single home-prep block, so `anchor` gets none.

    The holder is, in order:
      1. a prep block of another same-day anchor that the owner pinned, or
         that has already started (lifelog -- the owner got ready already).
         Pins are never relocated, so a pinned prep keeps the day's slot
         even when an earlier appointment appears.
      2. otherwise the earliest same-day anchor (start, then id) whose own
         derivation carries prep (_travel_anchor_home_prep). An earlier
         appointment therefore takes the prep over from a later one, and a
         cancelled or moved-away one hands it back on the next refresh.
    Deterministic and read-only: the answer depends on rows and rules, not
    on which anchor happened to be refreshed first."""
    start = anchor.get("start_at")
    if start is None:
        return False
    lo, hi = _travel_local_day_window(start)
    held = conn.execute(
        "SELECT 1 FROM timeblock b JOIN timeblock a ON a.ulid = b.derived_from "
        "WHERE b.block_class='travel' AND b.derived_role='before_prep' "
        "AND b.settled_at IS NULL AND b.derived_from != ? "
        "AND (b.derived_pinned = 1 OR b.start_at <= ?) "
        "AND a.start_at >= ? AND a.start_at < ? LIMIT 1;",
        (anchor["ulid"], now, lo, hi)).fetchone()
    if held is not None:
        return True
    for peer in _travel_rows(
            conn,
            "SELECT * FROM timeblock WHERE settled_at IS NULL "
            "AND block_class IS NULL AND schedule_kind='timed' "
            "AND start_at >= ? AND start_at < ? AND id != ? "
            "AND (start_at < ? OR (start_at = ? AND id < ?)) "
            "ORDER BY start_at, id;",
            (lo, hi, anchor["id"], start, start, anchor["id"])):
        rule = _travel_rule_for_anchor_row(conn, peer)
        if rule is None or not _travel_anchor_eligible(peer):
            continue
        if _travel_anchor_home_prep(conn, rule, peer) > 0:
            return True
    return False


def _travel_peer_prep_state(conn, anchor_ulid):
    """(has_unpinned, has_pinned) live before_prep blocks of one anchor."""
    rows = conn.execute(
        "SELECT derived_pinned FROM timeblock WHERE block_class='travel' "
        "AND derived_role='before_prep' AND settled_at IS NULL "
        "AND derived_from=?;", (anchor_ulid,)).fetchall()
    return (any(not r[0] for r in rows), any(r[0] for r in rows))


def _travel_refresh_day_peers(conn, state_conn, instant, exclude_id,
                              now=None, agg=None):
    """Re-derive the anchors of the local day holding `instant` (except
    exclude_id) whose prep block is out of step with the day scope, one
    level only, so the day's single prep block follows the earliest anchor
    (slice3). Returns the number refreshed.

    Only a peer whose live unpinned prep disagrees with what travel_derive
    now expects is refreshed: a blanket re-derive would also re-judge roles
    this rule does not own (e.g. DGN-314 after-leg suppression), changing
    days that carry no prep at all. While prep is enabled, a peer with a
    pinned prep is left alone (pins are never relocated). With prep off,
    only its move/buffer geometry participates; the prep row is preserved."""
    if instant is None:
        return 0
    prep_enabled = _travel_prep_enabled(conn)
    now = now or now_utc()
    lo, hi = _travel_local_day_window(instant)
    n = 0
    for peer in _travel_rows(
            conn,
            "SELECT * FROM timeblock WHERE settled_at IS NULL "
            "AND block_class IS NULL AND start_at >= ? AND start_at < ? "
            "AND id != ? ORDER BY start_at, id;",
            (lo, hi, exclude_id if exclude_id is not None else -1)):
        rule = _travel_rule_for_anchor_row(conn, peer)
        if rule is None or not _travel_anchor_eligible(peer):
            continue
        has, pinned = _travel_peer_prep_state(conn, peer["ulid"])
        if pinned and prep_enabled:
            continue
        exp = travel_derive(conn, rule, peer, now=now)
        want = "before_prep" in exp
        if ((prep_enabled and has != want)
                or _travel_before_out_of_step(conn, peer, exp, now)):
            s_ = travel_refresh(conn, state_conn, peer["ulid"], now=now,
                                _chain=False)
            _travel_summary_add(agg, s_)
            n += 1
    return n


_TRAVEL_SUMMARY_COUNTS = ("regen", "created", "tombstoned", "moved")


def _travel_summary_add(summary, s_):
    """Fold a chained travel_refresh's counters into the caller's
    summary["chain"] (2.46.0-dev.2: a refresh reported only its own
    anchor's rows, so a move whose regen landed on a neighbour or a day
    peer read regen=0). Kept apart from the anchor's own counters on
    purpose: travel_refresh_rule sums those per rule for the nightly churn
    breaker, and a neighbour's regen must not freeze this rule."""
    if summary is None or not s_:
        return
    chain = summary.setdefault("chain", dict.fromkeys(
        _TRAVEL_SUMMARY_COUNTS, 0))
    for k in _TRAVEL_SUMMARY_COUNTS:
        chain[k] += (s_.get(k) or 0)


def travel_summary_total(s_, key):
    """The anchor's own counter plus its chained refreshes' (the number a
    verb reports to the owner's audit line)."""
    return ((s_.get(key) or 0)
            + ((s_.get("chain") or {}).get(key) or 0))


_TRAVEL_BEFORE_SIDE_ROLES = ("before_prep", "before", TRAVEL_ROLE_BUFFER)


def _travel_before_out_of_step(conn, anchor, exp, now):
    """True when a FUTURE unpinned before-side row (prep / move / buffer) of
    `anchor` sits elsewhere than `exp` wants it, or one `exp` wants in the
    future is missing.

    The before leg reads the stay in front of it (_travel_away_end), so a
    stay that moves re-shapes a same-day appointment's leg. Live 2026-10-07:
    the mirror refreshed the moved appointment while the office stay still
    held its old end, then refreshed the stay -- and this peer pass looked
    only at prep, so the leg built off the stale end (08:30-09:15 before a
    09:00 start) stayed. Pinned and started rows are not judged here."""
    live = {}
    for r in _travel_rows(
            conn,
            "SELECT derived_role, start_at, end_at, derived_pinned "
            "FROM timeblock WHERE block_class='travel' AND derived_from=? "
            "AND settled_at IS NULL;", (anchor["ulid"],)):
        live[r["derived_role"]] = r
    for role in _TRAVEL_BEFORE_SIDE_ROLES:
        if role == "before_prep" and not _travel_prep_enabled(conn):
            continue
        row, want = live.get(role), exp.get(role)
        if row is not None and (row["derived_pinned"]
                                or (row["start_at"] or "") <= now):
            continue
        if want is not None and want["start_at"] <= now:
            want = None
        if row is None and want is None:
            continue
        if row is None or want is None:
            return True
        if (row["start_at"], row["end_at"]) != (want["start_at"],
                                                want["end_at"]):
            return True
    return False


def _travel_away_end(conn, rule, anchor, departure):
    """End of the latest live same-day block at ANOTHER place that is still
    running at `departure` and ends before the anchor starts, or None.

    the life agent 2026-10-06 13:05: the office stay moved to end 17:00, a clinic visit at 18:00
    with an unknown duration armed the 60-minute stopgap, and the leg was
    hung backwards off the anchor -- 16:45-17:45, starting 15 minutes inside
    the office stay. Nobody leaves a place before the stay there ends, so a
    move leg never starts before that end. READ ONLY; never raises."""
    if not anchor.get("start_at"):
        return None
    # An anchor with no place row (an unregistered venue: the stopgap's
    # usual case) is somewhere else than every place on file.
    dest_id = anchor.get("place_id") or rule.get("place_id") or -1
    try:
        since, until = _travel_local_day_window(anchor["start_at"])
        row = conn.execute(
            "SELECT MAX(end_at) FROM timeblock "
            "WHERE settled_at IS NULL AND id != ? "
            "AND (block_class IS NULL OR block_class != ?) "
            "AND schedule_kind = 'timed' AND place_id IS NOT NULL "
            "AND place_id != ? AND start_at >= ? AND start_at < ? "
            "AND end_at > ? AND end_at < ?;",
            (anchor.get("id") or -1, TRAVEL_BLOCK_CLASS, dest_id, since,
             anchor["start_at"], departure, anchor["start_at"])).fetchone()
    except Exception:
        return None
    return row[0] if row and row[0] else None


def _travel_before_geometry(conn, rule, anchor, before_eff):
    """(departure, arrival, buffer_eff, away) of a before leg of `before_eff`
    minutes. D1/D2: hung backwards off arrival = anchor start - buffer. When
    that departure falls inside a preceding stay at another place
    (_travel_away_end), the leg starts at that stay's end instead and keeps
    its length; arrival moves with it and the buffer shrinks (to nothing
    once arrival reaches the anchor). away = True then: the owner leaves
    from that place (no home prep) and the anchor is tight (day card).

    The arrival never passes the anchor start (live 2026-10-07: a stay end
    read before its own move landed pushed a 45-minute leg to 08:30-09:15
    in front of a 09:00 appointment). A stay ending too late for the whole
    leg leaves a shorter leg from the stay end to the start -- the day card
    still says tight -- never a leg that overlaps the appointment."""
    buffer_eff = _travel_appt_buffer_min(anchor, conn) if before_eff > 0 else 0
    arrival = (_iso_shift_min(anchor["start_at"], -buffer_eff)
               if buffer_eff > 0 else anchor["start_at"])
    departure = _iso_shift_min(arrival, -before_eff)
    if anchor.get("kind") == "appointment" and buffer_eff:
        import appointment_buffer
        prev = appointment_buffer.previous(sys.modules[__name__], conn, anchor)
        dest = anchor.get("place_id") or rule.get("place_id")
        if (prev and departure < prev["end_at"] <= anchor["start_at"]
                and (not prev.get("place_id") or prev["place_id"] != dest)):
            # Only the margin is disposable; never shorten the real journey.
            shrink = min(buffer_eff, -_iso_diff_min(departure, prev['end_at']))
            departure = _iso_shift_min(departure, shrink)
            arrival = _iso_shift_min(arrival, shrink)
            buffer_eff -= shrink
    away = _travel_away_end(conn, rule, anchor, departure)
    if away is None:
        return departure, arrival, buffer_eff, False
    departure = away
    arrival = min(_iso_shift_min(departure, before_eff), anchor["start_at"])
    buffer_eff = max(0, _iso_diff_min(anchor["start_at"], arrival))
    return departure, arrival, buffer_eff, True


def travel_derive(conn, rule, anchor, now=None):
    """Pure derive(): expected UNPINNED blocks for one anchor instance.
    {role: {start_at, end_at, exclusive, prep_eff}}. Pin-delta expectation
    is the reconciler's branch (3.3). Rounding lives at rule/place WRITE
    time (values are already on the grid).

    DGN-305 split: when prep_eff > 0, two 'before' roles are emitted:
      'before_prep' : prep_start  -> departure  (notify_policy 'start_only')
      'before'      : departure   -> anchor.start (notify_policy 'start_only')
    When prep_eff = 0 (chain outing): single 'before' role, unchanged.
    The move leg after a prep block used to be 'silent' (the prep alert
    carried the departure); owner 2026-10-06 07:21 "why drop the outbound
    travel alert" -- each step alerts at its own moment: prep at prep start,
    the move at departure. The two instants are prep_eff (>= one grid unit)
    apart, so they never land on the same poll. Untouched legacy silent
    pairs also converge before the nightly geometry freeze gate; edited or
    ambiguous outbound silence is preserved by refresh.

    DGN-314: after-leg title is fixed "home" title (not anchor title).
    after-leg suppression: if a live external 'before' travel block overlaps
    the ideal after interval [anchor.end, anchor.end + after_min), omit 'after'
    from the expected dict (the next anchor's before leg covers this move;
    its own after leg will cover the eventual homeward trip). before_prep
    overlaps do NOT suppress. Reconcile convergence restores 'after' when the
    next anchor is removed."""
    if travel_core.attendance_online(sys.modules[__name__], conn, anchor):
        return {}
    exp = {}
    now = now or now_utc()
    # DGN-623: presence-aware outbound leg. before_eff / prep_declared come from
    # the resolved (origin -> dest) edge, not the flat base-origin rule column.
    # status MISSING (no edge for the resolved origin) or SAME (origin == dest)
    # yields before_eff = 0, so the before leg is omitted; MISSING additionally
    # signals elicitation via _travel_derive_edge_status() at the attach layer.
    before_eff, prep_declared, _edge_status, _origin_id = \
        _travel_resolve_before_leg(conn, rule, anchor)
    # D1/D2 (product rule 2026-08-25: travel attaches before the appointment --
    # in front of the next block, not after the previous one): the whole before-leg geometry hangs
    # off the DESTINATION, never off whatever happens to precede it. ARRIVAL is
    # the anchor-side end of the chain and sits `buffer_eff` minutes before the
    # anchor starts; the move leg is then derived BACKWARDS from arrival.
    # Measured defect this replaces: 회사 ended 17:30, 이동 ran 17:30-18:30,
    # then a 30-minute void, then the 19:00 appointment -- he arrived an hour
    # early and waited.
    buffer_eff = 0
    if before_eff > 0:
        departure, arrival, buffer_eff, away = _travel_before_geometry(
            conn, rule, anchor, before_eff)
        # DGN-841 P1: prep (home preparation) only applies when departing from
        # BASE. A chained hop whose resolved origin is a NON-base place carries
        # no home-prep (the user is already out). This complements the existing
        # _travel_chain window suppression, which keys off `departure`: a short
        # hop can leave the preceding stay's end outside that window even though
        # the origin is plainly a place, not home.
        prep_eff = 0 if away else _travel_prep_gate(
            conn, rule, anchor, departure, _origin_id, prep_declared)
        # DGN-623 slice3: one home-prep per local day. The earliest anchor of
        # the day that would carry prep keeps it; every later one departs
        # with a plain move leg (its alert moves onto that leg, see below).
        if prep_eff > 0 and _travel_day_prep_held(conn, anchor, now):
            prep_eff = 0
        if prep_eff > 0:
            # DGN-305: split into prep block + travel block.
            prep_start = _iso_shift_min(departure, -prep_eff)
            exp["before_prep"] = {
                "start_at": prep_start, "end_at": departure,
                "prep_eff": prep_eff,
                "notify_policy": "start_only",
                "exclusive": _travel_expected_exclusive(
                    conn, rule, anchor, prep_start, departure),
            }
            exp["before"] = {
                "start_at": departure, "end_at": arrival,
                "prep_eff": 0,
                "notify_policy": "start_only",
                "exclusive": _travel_expected_exclusive(
                    conn, rule, anchor, departure, arrival),
            }
        else:
            # Chain case: single travel block, prep_eff=0, unchanged.
            bs = departure
            be = arrival
            exp["before"] = {
                "start_at": bs, "end_at": be, "prep_eff": 0,
                "notify_policy": "start_only",
                "exclusive": _travel_expected_exclusive(
                    conn, rule, anchor, bs, be),
            }
        if buffer_eff > 0:
            # D2: materialize the margin as a NAMED block. Silent -- the move
            # (or prep) leg already carries this outing's single alert; a
            # second ping 15 minutes later is noise, and this block exists to
            # be READ on the calendar, not to fire.
            exp[TRAVEL_ROLE_BUFFER] = {
                "start_at": arrival, "end_at": anchor["start_at"],
                "prep_eff": 0,
                "notify_policy": "silent",
                "exclusive": _travel_expected_exclusive(
                    conn, rule, anchor, arrival, anchor["start_at"]),
            }
    after = _travel_expected_after(conn, rule, anchor)
    if after is not None:
        as_, ae = after
        exp["after"] = {
            "start_at": as_, "end_at": ae, "prep_eff": 0,
            "notify_policy": "start_only",
            "exclusive": _travel_expected_exclusive(
                conn, rule, anchor, as_, ae),
        }
    return exp


def _travel_expected_after(conn, rule, anchor):
    """(start_at, end_at) of the return leg travel_derive expects for
    `anchor`, or None. Read-only; never consults this anchor's own blocks or
    its chain predecessors, so _travel_returns_home_before can ask it about a
    neighbour without recursing.

    The effective after-minutes is DERIVED from chain position at derive time
    (DGN-841 P2), not a stored knob: an explicit rule.after_min still wins
    (declared value, unchanged), else the chain tail auto-derives the
    dest->base return via edge(dest, base). Interior chain events and
    home-origin events derive no return (None)."""
    after_eff = int(rule["after_min"])
    if _travel_bundle_neighbour(conn, anchor, "next") is not None:
        # Rule 1: the next leg of this bundle follows -- the owner does not
        # go home in between, whatever the rule declares.
        after_eff = 0
    elif after_eff <= 0:
        chain_ret = _travel_resolve_return_leg(conn, rule, anchor)
        if chain_ret is not None:
            after_eff = chain_ret
    if after_eff <= 0 or anchor.get("end_at") is None:
        return None
    as_ = anchor["end_at"]
    ae = _iso_shift_min(as_, after_eff)
    # DGN-314: omit 'after' when a chained-appointment 'before' block
    # already covers this departure window (reconcile restores on cancel).
    if _travel_after_suppressed(conn, anchor, as_, ae):
        return None
    return as_, ae


# ── block row lifecycle primitives (single writer = deriver) ──────────────

def _travel_never_mirrored(conn, state_conn, row):
    """Compatibility entry point; lifecycle policy lives in travel_core."""
    return travel_core._travel_never_mirrored(sys.modules[__name__], conn, state_conn, row)


def _travel_tombstone_block(conn, state_conn, row, by=TRAVEL_REGEN_BY):
    """Compatibility entry point; lifecycle policy lives in travel_core."""
    return travel_core._travel_tombstone_block(sys.modules[__name__], conn, state_conn, row, by)


def _travel_create_block(conn, state_conn, anchor, role, start_at, end_at,
                         exclusive, pinned=0, delta_json=None, now=None,
                         notify_policy="start_only", notify_policy_preserved=False):
    """Single-writer block insert (bypass semantics: the demotion predicate
    already decided exclusivity deterministically; the deriver never asks
    the slot predicate about its own block). idx_timeblock_travel_live guards
    duplicate live rows (race -> skip). Returns event id or None.

    notify_policy also allows silent buffers and declared retro legs.
    Both prep and future outbound move legs now use start_only.
    A preserved edited policy starts at version 1: stamp that provenance in
    the insert transaction, so a crash cannot leave an edited silent policy
    looking like an untouched version-zero legacy row."""
    now = now or now_utc()
    ulid = new_ulid()
    # DGN-305 prep title / DGN-314 fixed home title / D2 buffer title all
    # resolve through the SINGLE role->title locus.
    title = _travel_role_title(anchor, role)
    conn.execute("BEGIN IMMEDIATE;")
    try:
        # DGN-579: movement rows are kind='task', time_mode='anchored'
        # (spec A4) and slot-soft (D-C1). The exclusive param is IGNORED
        # here (kept for call-site/carry shape stability): forcing 0 at
        # this SOLE mint locus makes an exclusive travel row structurally
        # impossible (pinned-carry lanes could still relay a pre-flip 1).
        exclusive = 0
        cols = ("ulid, kind, title, schedule_kind, start_at, "
                "end_at, display_tz, open_ended, slot_exclusive, "
                "completion_rule, status, owning_agent, created_by, "
                "notify_policy, block_class, derived_from, derived_role, "
                "derived_pinned, derived_delta, time_mode, version, "
                "created_at, updated_at")
        vals = [ulid, "task", title, "timed", start_at, end_at,
                anchor.get("display_tz") or TRAVEL_DISPLAY_TZ,
                0, 1 if exclusive else 0, "manual", "open",
                TRAVEL_OWNING_AGENT, TRAVEL_DERIVER_BY, notify_policy,
                TRAVEL_BLOCK_CLASS, anchor["ulid"], role,
                1 if pinned else 0, delta_json, "anchored",
                1 if notify_policy_preserved else 0, now, now]
        # v3.2 에는 idx_timeblock_travel_live(부분 유니크)가 없다 -- 같은 라이브
        # 중복 가드를 라우터의 INSERT..SELECT..WHERE NOT EXISTS 로 원자적으로 세운다.
        # 구 축은 인덱스가 지키므로 가드 없이 원래 문장 그대로 돈다.
        if _is_v32(conn):
            eid = _tb_insert(
                conn, cols, vals,
                guard_sql=("NOT EXISTS (SELECT 1 FROM timeblock g WHERE "
                           "g.block_class='travel' AND g.derived_from=? "
                           "AND g.derived_role=? AND g.settled_at IS NULL)"),
                guard_params=(anchor["ulid"], role))
            if eid is None:
                conn.rollback()
                return None   # live dup guard: another writer won -- converge
        else:
            eid = _tb_insert(conn, cols, vals)
        _recompute_and_store(conn, eid, now=now)
        conn.commit()
    except sqlite3.IntegrityError as e:
        conn.rollback()
        # The guard is idx_timeblock_travel_live (the old idx_event_travel_live
        # name predates the 023 event->timeblock rename and could never match).
        # SQLite reports a partial-unique-index violation by COLUMN LIST, never
        # by index name -- verified: "UNIQUE constraint failed:
        # timeblock.derived_from, timeblock.derived_role". So the column
        # signature is the load-bearing test; the name is documentation.
        if ("timeblock.derived_from" in str(e)
                or "idx_timeblock_travel_live" in str(e)
                or "UNIQUE" in str(e)):
            return None       # live dup guard: another writer won -- converge
        raise
    except Exception:
        conn.rollback()
        raise
    _travel_outbox(state_conn, ulid)
    return eid


# ── travel_refresh: the convergence entrypoint (3.1) ──────────────────────

def travel_refresh(conn, state_conn, anchor_ulid, carry=None, now=None, _chain=True, declared=False):
    """Compatibility entry point; lifecycle policy lives in travel_core."""
    return travel_core.react(sys.modules[__name__], conn, 'leg_regen',
                             state_conn=state_conn, anchor_ulid=anchor_ulid,
                             carry=carry, now=now, _chain=_chain, declared=declared)


def _travel_local_date(instant, tz_name=None):
    return (datetime.datetime.strptime(instant, "%Y-%m-%dT%H:%M:%SZ")
            .replace(tzinfo=timezone.utc)
            .astimezone(ZoneInfo(tz_name or TRAVEL_DISPLAY_TZ))
            .strftime("%Y-%m-%d"))


def _ride_resolve_best_effort(conn, state_conn, now=None, dates=None):
    """070: re-seat ride routines after travel changed (routine_roller.
    ride_resolve_pass). Best-effort like every travel-lane follower: a
    fault is logged and never undoes the travel write that triggered it.
    Returns the moved list ([] on fault). A caller still inside its own
    transaction is left alone (the pass commits per row); the next sweep
    re-seats that day."""
    if conn.in_transaction:
        return []
    try:
        return _roller_mod().ride_resolve_pass(conn, state_conn, now=now,
                                               dates=dates)
    except Exception as e:                                  # noqa: BLE001
        try:
            _travel_log(conn, "travel_ride_resolve_error", None,
                        "%s: %s" % (type(e).__name__, e), now=now)
        except Exception:                                   # noqa: BLE001
            pass
        return []


# Statuses derive_status / v_block_state produce on an UNSETTLED row from the
# clock alone. They are not a record of anything the owner did.
_TRAVEL_CLOCK_STATUSES = travel_core._TRAVEL_CLOCK_STATUSES


