def _ride_cli_fields(fields):
    """070: CLI ride fields -> routine_add / routine_update columns.
    ride=travel|off, fallback=, not_before=, prefer= (empty = unset)."""
    if fields.get('alternatives'):
        if any(fields.get(k) for k in ('ride', 'fallback', 'not_before', 'prefer', 'time')):
            raise ValueError(_i18n('routine.placement.shape'))
        return dict(placement=None, fallback_at=None, ride_not_before=None,
                    ride_prefer=None, placement_alternatives=fields['alternatives'])
    ride = (fields.get("ride") or "").strip().lower()
    if ride not in ("", "travel", "off"):
        raise ValueError("ride must be travel|off, got %r" % fields["ride"])
    return {"placement": (_projection_mod().RIDE_TRAVEL if ride == "travel"
                          else None),
            "fallback_at": (fields.get("fallback") or "").strip() or None,
            "ride_not_before": (fields.get("not_before") or "").strip()
            or None,
            "ride_prefer": (fields.get("prefer") or "").strip().lower()
            or None}


def _print_ride_days(conn, def_ulid, days=7):
    """070: where the ride routine sits on its next `days` instances --
    RIDE<TAB>date<TAB>HH:MM<TAB>travel|fallback<TAB>leg title -- so the
    confirm/echo can say "출근길 07:45" or "21:00" without guessing."""
    for d, hhmm, how, leg in _roller_mod().ride_view(conn, def_ulid,
                                                     days=days):
        print("RIDE\t%s\t%s\t%s\t%s" % (d, hhmm, how, leg or ""))


def _routine_mutation_cards(conn, token, state, removing=None):
    defn = routine_def_get(conn, token)
    if not defn:
        return []
    predicate = '' if removing == 'retire' else ' AND rec_date>=?'
    params = [defn['recurrence_id']]
    if removing != 'retire':
        params.append(routine_today(defn['display_tz']))
    if removing == 'pause':
        # Pausing preserves owner-edited exceptions; only the roller's
        # untouched occurrences are actually removed by cancel_set_regen.
        predicate += " AND rec_exception=0 AND created_by='roller' AND version=0"
    ids = [r[0] for r in conn.execute(
        'SELECT id FROM timeblock WHERE recurrence_id=? AND settled_at IS NULL' +
        predicate + ' ORDER BY start_at,id', params)]
    return [card for bid in ids
            if (card := _mutation_card(conn, 'routine', bid, state))]


def cli_routine(argv):
    _u = ("사용법: kit_life.sh routine "
          "add|list|show|update|pause|resume|retire|exception|insist|health|"
          "materialize ...\n"
          "  add <title> <cadence> [field=value ...] [--new]\n"
          "      cadence: D | W:MON,WED,FRI | I:2@YYYY-MM-DD\n"
          "               | M:12 (monthly; M:1,15 / M:L last day)\n"
          "               | MW:2:MON (Nth weekday of the month, N=1..4|L)\n"
          "               | Y:03-05 (yearly, solar) | YL:08-15 (yearly, lunar)\n"
          "               | IM:3@YYYY-MM-DD (every N months)\n"
          "      cadence-label <cadence>  -> the owner-facing label\n"
          "      field: time(HH:MM) duration area project purpose start end\n"
          "             until(event|date|+Nd|+Nw|+Nm|open) open(1) ask(1)\n"
          "             (project accepts id OR title, same resolve as\n"
          "             task-add/appt-add --project -- _resolve_project_id)\n"
          "             notify(default|silent|start_only|<lead-min>)\n"
          "             kind(task|presence) action(check|workout|retro|session|other)\n"
          "             place(<name>, presence requires it)\n"
          "             ride(travel|off) fallback(HH:MM | MON,FRI=HH:MM;HH:MM)\n"
          "             not_before(HH:MM) prefer(morning|evening)\n"
          "             alternatives(JSON: alternatives, optional priority/fallback_at)\n"
          "             -- ride=travel: rides the day's first move leg that\n"
          "             fits duration, else sits at fallback (070)\n"
          "  update <def_ulid> [effective_from=YYYY-MM-DD] field=value ...\n"
          "      field: also place(<name|id>, empty clears) -- future rows\n"
          "             take the place, travel/prep follow (past untouched)\n"
          "  insist <def_ulid> date=YYYY-MM-DD time=HH:MM (owner override)\n"
          "  exception <event_ulid> field=value ... "
          "(field: start_at end_at date title note)\n"
          "  health [window=N] [as_of=YYYY-MM-DD]")
    if not argv:
        _err(_u)
    verb, rest = argv[0], argv[1:]
    if verb in ('unretire', 'unretire-undo'):
        conn = event_conn()
        try:
            _schedule_correction.routine(sys.modules[__name__], conn, verb, rest)
        except (ValueError, sqlite3.IntegrityError) as exc:
            _err(str(exc))
        finally:
            conn.close()
        return
    if verb == "cadence-label":              # pure: no DB
        if len(rest) != 1:
            _err(_u)
        try:
            print(_projection_mod().describe_cadence(
                rest[0], lambda key: _i18n(key, key)))
        except ValueError as e:
            _err(str(e))
        return
    conn = event_conn()
    try:
        if verb == "add":
            rest, force_new = _pop_flag(rest, "--new")   # DGN-231 pattern
            if len(rest) < 2 or not rest[0] or not rest[1]:
                _err(_u)
            title, cadence = rest[0], rest[1]
            fields = {}
            for tok in rest[2:]:
                if "=" not in tok:
                    _err("field=value 형식이 아님: %s\n%s" % (tok, _u))
                k, v = tok.split("=", 1)
                fields[k.strip()] = v
            if fields.get('alternatives'):
                allowed = {'time', 'duration', 'area', 'project', 'purpose', 'start',
                           'end', 'until', 'open', 'ask', 'notify', 'kind', 'place',
                           'action', 'ride', 'fallback', 'not_before', 'prefer', 'tz', 'alternatives', 'admit_cmd'}
                if set(fields) - allowed:
                    _err(_i18n('routine.placement.invalid'))
            if not force_new:
                # duplicate gate: same-title active def (spec 8.3 / DGN-231)
                dups = conn.execute(
                    "SELECT id, ulid, title, cadence, schedule_kind, "
                    "time_of_day, status, retro_skip FROM routine_def "
                    "WHERE title=? AND status='active';", (title,)).fetchall()
                if dups:
                    print("EXISTS %d" % len(dups))
                    for d in dups:
                        print(_routine_line({
                            "id": d[0], "ulid": d[1], "title": d[2],
                            "cadence": d[3], "schedule_kind": d[4],
                            "time_of_day": d[5], "status": d[6],
                            "retro_skip": d[7]}))
                    sys.exit(EXISTS_CODE)
            # The agent's interactive path opts in; packs keep the open default.
            _today_ = routine_today(fields.get("tz") or "Asia/Seoul")
            until = {"end_date": fields.get("end") or None, "event": None,
                     "mode": None}
            if fields.get("until"):
                try:
                    until = routine_parse_until(conn, fields["until"],
                                                _today_)
                except ValueError as e:
                    _err(str(e))
            elif (fields.get("ask") in ("1", "true", "yes")
                  and not fields.get("end") and fields.get("open") not in (
                      "1", "true", "yes")):
                for _ln in routine_end_ask(conn, title, fields.get("purpose"),
                                           _today_):
                    print(_ln)
                print(END_ASK_RELAY)
                sys.exit(END_ASK_CODE)
            aid = None
            if fields.get("area"):
                aid = area_id(conn, fields["area"])
                if aid is None:
                    _err("영역 없음: %s" % fields["area"])
            # project axis: id-or-title, shared resolver (_resolve_project_id)
            # with task-add/appt-add/project-link -- was title-only inline
            # lookup before the project axis wiring landed.
            pid = _resolve_project_id(conn, fields.get("project"))
            tod = fields.get("time")
            sk = "timed" if tod else "all_day"
            # 070: ride=travel -- the day's travel, else the fallback time
            # (time= is not asked: fallback= is the clock time it has).
            try:
                ride = _ride_cli_fields(fields)
            except ValueError as e:
                _err(str(e))
            if ride["placement"] is not None or ride.get('placement_alternatives'):
                sk = "timed"
                if not fields.get("notify"):
                    # no-travel day: its own alert at the fallback, once
                    fields["notify"] = "start_only"
            # DGN-842: kind=presence support. Default 'task'; validation gates
            # presence-without-place and any other kind (appointment, OQ-12).
            rkind = fields.get("kind", "task")
            # DGN-579/place: place-bound routine -- resolve a place name to
            # place_id (place_upsert is the sole insert path). Absent -> None.
            _rt_place_id = None
            if fields.get("place") and str(fields["place"]).strip():
                try:
                    _rt_place_id = _routine_place_arg(conn, fields["place"])
                except NearMatchError as e:
                    _near_exit(e.domain, e.query, e.cands)
                except ValueError as e:
                    _err(str(e))
            try:
                np, nl = parse_notify_arg(fields.get("notify"))
                res = routine_add(
                    conn, title, cadence, sk, time_of_day=tod,
                    duration_min=(int(fields["duration"])
                                  if fields.get("duration") else None),
                    area_id=aid, project_id=pid, kind=rkind,
                    purpose=fields.get("purpose"),
                    start_date=fields.get("start"),
                    end_date=until["end_date"],
                    until_event=until["event"], until_mode=until["mode"],
                    notify_policy=np, notify_lead_min=nl,
                    place_id=_rt_place_id,
                    display_tz=fields.get("tz") or "Asia/Seoul",
                    action_kind=fields.get("action", "check"),
                    admit_cmd=fields.get("admit_cmd"), **ride)
            except ValueError as e:
                _err(str(e))
            print("%s\t%s\t%s" % (res["def_id"], res["ulid"],
                                  ",".join(res["materialized_dates"])))
            _clash = routine_clash_notes(conn)
            for _ln in _clash:
                print("ROUTINE_CLASH\t" + _ln)
            if _clash:
                print(ROUTINE_CLASH_RELAY)
            if ride["placement"] is not None:
                _print_ride_days(conn, res["ulid"])
            _print_placement(conn, res['ulid'])
            _emit_clash_asks(conn)
            _emit_card_block(_routine_mutation_cards(conn, res['ulid'], 'created'),
                             relay=_timeblock_card_mod().RELAY)
        elif verb == "list":
            status = rest[0] if rest else None
            q = ("SELECT id, ulid, title, cadence, schedule_kind, "
                 "time_of_day, status, retro_skip FROM routine_def ")
            if status:
                rows = conn.execute(q + "WHERE status=? ORDER BY id;",
                                    (status,)).fetchall()
            else:
                rows = conn.execute(q + "ORDER BY id;").fetchall()
            for d in rows:
                print(_routine_line({
                    "id": d[0], "ulid": d[1], "title": d[2], "cadence": d[3],
                    "schedule_kind": d[4], "time_of_day": d[5],
                    "status": d[6], "retro_skip": d[7]}))
        elif verb == "show":
            if not rest:
                _err(_u)
            defn = routine_def_get(conn, rest[0])
            if defn is None:
                _err("routine 없음: %s" % rest[0])
            # retro-read-paths: retro_skip appended trailing (KEY=VALUE lines
            # are read by key, not position, so this is a pure addition).
            for k in ("id", "ulid", "recurrence_id", "title", "kind", "action_kind",
                      "cadence", "schedule_kind", "time_of_day",
                      "duration_min", "area_id", "project_id", "purpose",
                      "status", "start_date", "end_date", "valid_until",
                      "rule_effective_from", "notify_policy",
                      "notify_lead_min", "version", "retro_skip"):
                print("%s=%s" % (k, "" if defn[k] is None else defn[k]))
            # 070 (appended; absent on a pre-070 store)
            for k in RIDE_COLS:
                if k in defn:
                    print("%s=%s" % (k, "" if defn[k] is None else defn[k]))
            if defn.get("placement") is not None:
                _print_ride_days(conn, defn["ulid"])
            if defn.get('placement_alternatives'):
                print('placement_alternatives=' + json.dumps(defn['placement_alternatives'], sort_keys=True))
                _print_placement(conn, defn['ulid'])
        elif verb == "clash-notes":
            for ln in routine_clash_notes(conn, rest[0] if rest else None):
                print("ROUTINE_CLASH\t" + ln)
            _emit_clash_asks(conn, rest[0] if rest else None)
        elif verb == "retire-asks":
            for ln in routine_retire_asks(conn):
                print(ln)
        elif verb == "clash-sweep":
            rr = _roller_mod()
            rr.clash_sweep(conn, rr.open_state_db())
            for ln in routine_clash_notes(conn):
                print("ROUTINE_CLASH\t" + ln)
            _emit_clash_asks(conn)
        elif verb in ("update", "pause", "resume", "retire"):
            if not rest:
                _err(_u)
            token = rest[0]
            before_cards = (_routine_mutation_cards(conn, token, 'cancelled', removing=verb)
                            if verb in ('pause', 'retire') else [])
            if verb == "update":
                fields = {}
                eff = None
                until_link = None
                for tok in rest[1:]:
                    if "=" not in tok:
                        _err("field=value 형식이 아님: %s\n%s" % (tok, _u))
                    k, v = tok.split("=", 1)
                    k = k.strip()
                    if k == "effective_from":
                        eff = v
                    elif k == "time":
                        fields["time_of_day"] = v or None
                        fields.setdefault("schedule_kind",
                                          "timed" if v else "all_day")
                    elif k == "action":
                        fields["action_kind"] = v
                    elif k == "duration":
                        fields["duration_min"] = int(v)
                    elif k == "end":
                        fields["end_date"] = v or None
                        until_link = (None, None)     # explicit date: unlink
                    elif k == "until":
                        try:
                            _u2 = routine_parse_until(
                                conn, v, routine_today("Asia/Seoul"))
                        except ValueError as e:
                            _err(str(e))
                        fields["end_date"] = _u2["end_date"]
                        until_link = (_u2["event"], _u2["mode"])
                    elif k == "notify":
                        # DGN-273: the pair is always written together
                        # (notify= empty resets both to NULL = default).
                        try:
                            np, nl = parse_notify_arg(v)
                        except ValueError as e:
                            _err(str(e))
                        fields["notify_policy"] = np
                        fields["notify_lead_min"] = nl
                    elif k == 'alternatives':
                        fields['placement_alternatives'] = v or None
                    elif k in ("ride", "fallback", "not_before", "prefer"):
                        try:
                            ride = _ride_cli_fields({k: v})
                        except ValueError as e:
                            _err(str(e))
                        col = {"ride": "placement", "fallback": "fallback_at",
                               "not_before": "ride_not_before",
                               "prefer": "ride_prefer"}[k]
                        fields[col] = ride[col]
                    elif k in ("place", "place_id"):
                        # gym-place-wire: same resolver as routine add
                        # (NEAR_MATCH exits 5, ABSENT mints); empty clears.
                        try:
                            fields["place_id"] = _routine_place_arg(conn, v)
                        except NearMatchError as e:
                            _near_exit(e.domain, e.query, e.cands)
                        except ValueError as e:
                            _err(str(e))
                    elif k in _ROUTINE_UPD_COLS:
                        fields[k] = v or None
                    else:
                        _err("수정 불가 컬럼: %s\n%s" % (k, _u))
                if not fields:
                    _err(_u)
                try:
                    if until_link is not None:
                        _d0 = routine_def_get(conn, token)
                        if _d0 is not None:
                            routine_until_set(conn, _d0["recurrence_id"],
                                              until_link[0], until_link[1])
                    res = routine_update(conn, token, fields,
                                         effective_from=eff)
                except ValueError as e:
                    _err(str(e))
            elif verb == "pause":
                res = routine_pause(conn, token)
            elif verb == "resume":
                res = routine_resume(conn, token)
            else:
                res = routine_retire(conn, token)
            if res["result"] != "applied":
                _err("routine %s 실패 (%s)" % (verb, res["result"]))
            extra = ""
            if "materialized_dates" in res:
                extra = "\t" + ",".join(res["materialized_dates"])
            if "cancelled" in res:
                extra += "\tcancelled=%s" % res["cancelled"]
            # 2026-08-24 edit-preservation: days the owner had hand-set keep
            # THEIR time, not the new rule's. Surfaced so the caller can ask
            # the owner instead of leaving a silent divergence.
            if res.get("stale_exception_dates"):
                extra += "\tkept_owner_edit=%s" % ",".join(
                    res["stale_exception_dates"])
            print("%s\t%s%s" % (token, res["result"], extra))
            cards = before_cards if verb in ('pause', 'retire') else _routine_mutation_cards(
                conn, token, 'changed' if verb == 'update' else 'open')
            _emit_card_block(cards, relay=_timeblock_card_mod().RELAY)
            if verb == 'update':
                _print_placement(conn, token)
            if res.get("travel_attach") is not None:
                # same line shape as routine-travel-attach, so the caller
                # reads EDGE_MISSING / NO_DURATION and elicits the minutes.
                _d = routine_def_get(conn, token)
                print("routine-travel-attach\t%s\t%s\t%s\t%s\t%s" % (
                    (_d["id"], _d["ulid"]) + tuple(res["travel_attach"])))
        elif verb == 'insist':
            if len(rest) != 3 or any('=' not in t for t in rest[1:]):
                _err(_u)
            fields = dict(t.split('=', 1) for t in rest[1:])
            if set(fields) != {'date', 'time'}:
                _err(_u)
            try:
                result = routine_insist(conn, rest[0], fields['date'], fields['time'])
            except ValueError as exc:
                _err(str(exc))
            print('PLACEMENT_OWNER\t' + result['reply'])
            bid = conn.execute('SELECT id FROM block WHERE ulid=?', (result['ulid'],)).fetchone()[0]
            _timeblock_card_mod().emit(sys.modules[__name__],
                                      _mutation_card(conn, 'routine-insist', bid, 'changed'))
        elif verb == "exception":
            if len(rest) < 2:
                _err(_u)
            ulid_t = rest[0]
            fields = {}
            for tok in rest[1:]:
                if "=" not in tok:
                    _err("field=value 형식이 아님: %s\n%s" % (tok, _u))
                k, v = tok.split("=", 1)
                fields[k.strip()] = v
            schedule = None
            if "date" in fields:                       # DATE-only move
                # Defer-preserves-time fix (2026-08-25), sibling of
                # task-reschedule: this branch used to hardcode 'all_day', so
                # moving a TIMED routine instance to another day silently
                # dropped its clock time and flipped the row onto the tasks
                # surface. A date move now changes the DATE only; the shape
                # comes from the row itself (start_at=/end_at= is still the
                # way to change the time deliberately).
                _ex = conn.execute(
                    "SELECT schedule_kind, start_at, end_at, display_tz "
                    "FROM timeblock WHERE ulid=?;", (ulid_t,)).fetchone()
                try:
                    if _ex is None:
                        sa, ea = all_day_instants(fields["date"])
                        schedule = ("all_day", sa, ea)
                    else:
                        schedule = _defer_shape(_ex[0], _ex[1], _ex[2], _ex[3],
                                                fields["date"])
                except ValueError as e:
                    _err(str(e))
            elif "start_at" in fields or "end_at" in fields:
                try:
                    ns = (_to_canonical_utc(fields["start_at"])
                          if fields.get("start_at") else None)
                    ne = (_to_canonical_utc(fields["end_at"])
                          if fields.get("end_at") else None)
                except ValueError as e:
                    _err(str(e))
                if ns and not ne:
                    # m-2 (grill-final): start-only move preserves the
                    # row's current duration instead of collapsing to a
                    # zero-length instance (end_at=start_at).
                    _row = conn.execute(
                        "SELECT start_at, end_at FROM timeblock WHERE ulid=?;",
                        (ulid_t,)).fetchone()
                    if _row and _row[0] and _row[1]:
                        _fmt = "%Y-%m-%dT%H:%M:%SZ"
                        _dur = (datetime.datetime.strptime(_row[1], _fmt)
                                - datetime.datetime.strptime(_row[0], _fmt))
                        ne = (datetime.datetime.strptime(ns, _fmt)
                              + _dur).strftime(_fmt)
                    else:
                        ne = ns
                schedule = ("timed", ns, ne)
            content = {k: v for k, v in fields.items()
                       if k in ("title", "note")}
            try:
                res = routine_exception(conn, ulid_t, schedule=schedule,
                                        content=content or None)
            except ValueError as e:
                _err(str(e))
            if res not in ("applied", "noop"):
                _err("routine exception 실패 (%s)" % res)
            print("%s\t%s" % (ulid_t, res))
            if res == 'applied':
                bid = conn.execute('SELECT id FROM block WHERE ulid=?', (ulid_t,)).fetchone()[0]
                _timeblock_card_mod().emit(sys.modules[__name__],
                                          _mutation_card(conn, 'routine-exception', bid, 'changed'))
        elif verb == "health":
            window, as_of = 28, None
            i = 0
            while i < len(rest):
                tok = rest[i]
                if tok.startswith("window="):
                    window = int(tok.split("=", 1)[1])
                elif tok.startswith("as_of="):
                    as_of = tok.split("=", 1)[1]
                elif tok == "--window" and i + 1 < len(rest):
                    i += 1
                    window = int(rest[i])
                elif tok == "--as-of" and i + 1 < len(rest):
                    i += 1
                    as_of = rest[i]
                i += 1
            for row in routine_health(conn, window=window, as_of=as_of):
                print(json.dumps(row, ensure_ascii=False))
        elif verb == "materialize":
            rr = _roller_mod()
            defs = ([routine_def_get(conn, rest[0])] if rest
                    else rr.active_defs(conn))
            total = []
            for defn in defs:
                if defn is None:
                    _err("routine 없음: %s" % rest[0])
                if defn["status"] == "active" and defn["cadence"]:
                    total += rr.materialize_def(conn, None, defn)
            print("materialized\t%d" % len(total))
        else:
            _err(_u)
    finally:
        conn.close()


