def _err(msg, code=1):
    print(msg, file=sys.stderr)
    sys.exit(code)


# DGN-231: reconcile-before-write (doctrine D3). add verbs self-check for an
# existing match before insert; on match they print "EXISTS n" + the matching
# rows (reusing the verb's find/list format) and exit 3, registering nothing.
# The --new flag forces the insert past a match. A --new-less 0-match call keeps
# the pre-DGN-231 behavior byte-for-byte (existing callers unchanged).
EXISTS_CODE = 3

# DGN-579 B2/A3: structured conflict listing exit code (analog of the
# EXISTS contract): the write did NOT land; the blocker rows were printed.
CONFLICT_CODE = 4

# ══════════════════════════════════════════════════════════════════════════
# NEAR-MATCH gate (owner 2026-09-28 12:26). Every create path that matches by
# name/alias runs near_match.py before it writes a NEW row. A near candidate
# does not create and does not resolve: the verb prints a NEAR_MATCH block
# and exits NEAR_MATCH_CODE, and the agent asks the owner ONE question (copy
# table: near_match.ask.<place|person|thing>[.multi]).
#   Yes -> near-match-accept <domain> <ref> <text>: <text> becomes an alias of
#          <ref> (exact matching finds it from then on).
#   No  -> near-match-refuse <domain> <ref> <text> (remember only), or the
#          create verb's --new-confirmed (remember every current candidate,
#          then create). The pair is never asked again (060).
# Output (TSV, machine-first, stdout):
#   NEAR_MATCH<TAB>n<TAB>domain<TAB>query
#   <ref><TAB><name><TAB><signal><TAB><matched string>      (n lines, best first)
#   ASK<TAB><the one question>
# Rule 6 (no runtime fuzzy RESOLUTION) is untouched: nothing here ever answers
# "this is that row" -- it only turns a silent create into a question.
# ══════════════════════════════════════════════════════════════════════════
NEAR_MATCH_CODE = 5
NEAR_DOMAINS = ("place", "person", "method", "food", "exercise", "item",
                "category",    # item / category: 071 module_shopping (shop.py)
                "group", "sub_place")   # 073 proper-noun registry


def _near_mod():
    """The sibling near_match.py, imported on first use (the muscle_fatigue
    convention): a copy of kit_life.py that carries only its older siblings
    -- the test harnesses copy exactly agent_conf + routine_evidence -- keeps
    working. Without the sibling the gate is OFF (None), which is precisely
    the pre-2026-09-28 behaviour; an installed kit always ships it."""
    try:
        import near_match
    except ImportError:
        return None
    return near_match


class NearMatchError(ValueError):
    """A create was refused because the name looks like an existing row.
    ValueError subclass so a caller that does not know about it still fails
    LOUD (its existing `except ValueError: _err(...)`), never silently."""

    def __init__(self, domain, query, cands):
        self.domain, self.query, self.cands = domain, query, cands
        ValueError.__init__(self, "%s\n%s" % (
            near_match_lines(domain, query, cands)[0],
            near_question(domain, cands)))


def _near_json_list(blob):
    try:
        arr = json.loads(blob) if blob else []
    except (TypeError, ValueError):
        return []
    return [a for a in arr if isinstance(a, str)] if isinstance(arr, list) \
        else []


def _near_rows_place(conn):
    where = "WHERE " + LIVE_PLACE_SQL if _is_v32(conn) else ""
    return [(pid, _place_norm_name(name), _near_json_list(aliases))
            for pid, name, aliases in conn.execute(
                "SELECT id, name, aliases FROM place " + where +
                " ORDER BY id;").fetchall() if name]


def _near_rows_person(conn):
    return [(pid, name, [a.strip() for a in (aliases or '').split(',')
                         if a.strip()])
            for pid, name, aliases in conn.execute(
                "SELECT id, name, aliases FROM persons ORDER BY id;"
            ).fetchall() if name]


def _near_rows_method(conn):
    return [(mid, name, _method_aliases(aliases))
            for mid, name, aliases in conn.execute(
                "SELECT id, name, aliases FROM pay_method ORDER BY id;"
            ).fetchall() if name]


def _near_rows_food(conn):
    """meal_food rows keyed by `key`; a meal_alias whose canonical normalizes
    to a row's key rides as that row's alias."""
    rows = conn.execute("SELECT key, name FROM meal_food ORDER BY key;"
                        ).fetchall()
    al = {}
    try:
        for alias, canonical in conn.execute(
                "SELECT alias, canonical FROM meal_alias;").fetchall():
            al.setdefault(normalize_food_key(canonical or ''), []).append(alias)
    except sqlite3.Error:
        pass
    return [(k, n or k, [k] + al.get(k, [])) for k, n in rows if k]


def _near_rows_exercise(conn):
    try:
        return [(n, n, []) for (n,) in conn.execute(
            "SELECT DISTINCT exercise_name FROM ax_exercise "
            "WHERE status='active' ORDER BY exercise_name;").fetchall()]
    except sqlite3.Error:
        return []


def _near_rows_noun(domain):
    """073 group / sub_place rows (noun_registry.near_rows)."""
    def rows(conn):
        return _noun_mod().near_rows(conn, domain)
    return rows


def _noun_mod():
    """noun_registry.py (073), imported on first use (errand.py convention)."""
    if SCRIPT_DIR not in sys.path:
        sys.path.insert(0, SCRIPT_DIR)
    import noun_registry
    return noun_registry


def _near_rows_shop(kind):
    """071 module_shopping rows (shop.near_rows), imported on first use."""
    def rows(conn):
        import shop
        return shop.near_rows(sys.modules[__name__], conn, kind)
    return rows


_NEAR_ROWS = {"place": _near_rows_place, "person": _near_rows_person,
              "method": _near_rows_method, "food": _near_rows_food,
              "exercise": _near_rows_exercise,
              "item": _near_rows_shop("item"),
              "category": _near_rows_shop("category"),
              "group": _near_rows_noun("group"),
              "sub_place": _near_rows_noun("sub_place")}


def near_candidates(conn, domain, query):
    """Ranked near candidates for `query` in `domain`, refusals removed.
    [] when the query matches a row EXACTLY (the exact resolver's case) or
    nothing is near. Never raises on a missing table: a domain whose table is
    absent has no rows to be near."""
    nm = _near_mod()
    if nm is None:
        return []
    if domain == "place":
        query = _place_norm_name(query)
    try:
        rows = _NEAR_ROWS[domain](conn)
    except sqlite3.Error:
        return []
    return nm.candidates(query, rows, domain,
                         nm.refused_refs(conn, domain, query))


def near_question(domain, cands):
    """The ONE question, from the kit copy table."""
    names = [c["name"] for c in cands]
    key = _near_mod().question_key(domain, len(names))
    if len(names) == 1:
        fb = {"near_match.ask.place": "혹시 {name}{rang} 같은 곳인가요?",
              "near_match.ask.person": "혹시 {name}{rang} 같은 분인가요?",
              "near_match.ask.thing": "혹시 {name}{rang} 같은 건가요?"}
        return _i18n(key, fb.get(key, "")).format(
            name=names[0], rang=_josa(names[0], "irang"))
    fb = {"near_match.ask.place.multi": "혹시 {names} 중에 같은 곳이 있나요?",
          "near_match.ask.person.multi": "혹시 {names} 중에 같은 분이 있나요?",
          "near_match.ask.thing.multi": "혹시 {names} 중에 같은 게 있나요?"}
    return _i18n(key, fb.get(key, "")).format(names=", ".join(names))


def near_match_lines(domain, query, cands):
    q = " ".join(str(query).split())
    out = ["NEAR_MATCH\t%d\t%s\t%s" % (len(cands), domain, q)]
    for c in cands:
        out.append("%s\t%s\t%s\t%s" % (c["ref"], c["name"], c["signal"],
                                       c["matched"]))
    out.append("ASK\t%s" % near_question(domain, cands))
    return out


def _near_exit(domain, query, cands):
    """Print the NEAR_MATCH block and exit NEAR_MATCH_CODE. Nothing written."""
    for line in near_match_lines(domain, query, cands):
        print(line)
    sys.exit(NEAR_MATCH_CODE)


def near_refuse(conn, domain, query, refs, said=None):
    """Remember 'query is not ref' (commit). Returns the count stored, or None
    on a pre-060 database (nothing remembered; a stderr note says so)."""
    if domain not in NEAR_DOMAINS:
        raise ValueError("near-match: unknown domain %r (%s)"
                         % (domain, "|".join(NEAR_DOMAINS)))
    nm = _near_mod()
    n = None if nm is None else nm.record_refusal(conn, domain, query, refs,
                                                  said=said)
    if n is None:
        print("주의: 이 답을 기억하지 못했습니다(near_match_refusal 표 없음. "
              "060 이전 DB, 또는 near_match.py 없음). 같은 질문이 다시 나올 수 "
              "있습니다.", file=sys.stderr)
        return None
    conn.commit()
    return n


def _near_gate_new_confirmed(conn, domain, query, force):
    """The create verbs' common gate. force (--new-confirmed) = the owner said
    'different': remember every current candidate, then let the create run.
    Otherwise a candidate stops the verb (NEAR_MATCH block, exit 5)."""
    cands = near_candidates(conn, domain, query)
    if not cands:
        return
    if force:
        near_refuse(conn, domain, query, [c["ref"] for c in cands],
                    said="--new-confirmed")
        return
    _near_exit(domain, query, cands)


def near_accept(conn, domain, ref, query):
    """'Yes, the same': teach `query` as an alias of `ref`. Returns
    (ref, canonical name, taught_bool). Refuses (ValueError) when `query`
    already names a DIFFERENT row exactly -- teaching it would make the
    exact resolver ambiguous."""
    q = " ".join(str(query or "").split())
    if not q:
        raise ValueError("near-match-accept: text required")
    if domain == "place":
        row = travel_place_get(conn, ref)
        if row is None:
            raise ValueError("place %r not found" % (ref,))
        q = _place_norm_name(q)
        other = _resolve_location_place(conn, q)
        if other is not None and other["id"] != row["id"]:
            raise ValueError("'%s' 는 이미 다른 장소(%s. %s)의 이름/별칭입니다"
                             % (q, other["id"], other["name"]))
        already = other is not None
        import place_identity
        if place_identity.ready(conn):
            try:
                conn.execute("BEGIN IMMEDIATE")
                place_identity.teach(sys.modules[__name__], conn, row, q)
                conn.execute("UPDATE place_identity_ask SET state='yes' WHERE query=? AND place_id=?", (q,row['id']))
                conn.commit()
            except Exception:
                conn.rollback()
                raise
        else:
            if already:
                return row["id"], row["name"], False
            have = _near_json_list(conn.execute(
                "SELECT aliases FROM place WHERE id=?;", (row["id"],)).fetchone()[0])
            have.append(q)
            conn.execute("UPDATE place SET aliases=? WHERE id=?;", (json.dumps(have),row['id']))
            conn.commit()
        return row["id"], row["name"], not already
    if domain == "person":
        if not str(ref).isdigit():
            raise ValueError("person ref must be an id")
        prow = conn.execute("SELECT id, name, aliases FROM persons WHERE id=?;",
                            (int(ref),)).fetchone()
        if prow is None:
            raise ValueError("person %s not found" % ref)
        others = [r for r in _person_exact_matches(conn, q) if r[0] != prow[0]]
        if others:
            raise ValueError("'%s' 는 이미 다른 사람(%s. %s)의 이름/별칭입니다"
                             % (q, others[0][0], others[0][1]))
        if q == prow[1] or q in [a.strip() for a in (prow[2] or '').split(',')]:
            return prow[0], prow[1], False
        person_alias_add(prow[0], q, conn=conn)
        return prow[0], prow[1], True
    if domain == "method":
        res = method_alias_add(ref, [q], conn)
        if res is None:
            raise ValueError("method %r not found" % (ref,))
        return res[0], res[1], bool(res[3])
    if domain == "food":
        frow = _food_row(conn, str(ref))
        if frow is None:
            raise ValueError("food %r not found" % (ref,))
        if normalize_food_key(q) == frow[0]:
            return frow[0], frow[1], False
        # canonical = the KEY, not the display name: foodcache_lookup
        # normalizes the canonical and looks it up as a key, and half the
        # live display names do not normalize back to their key (043 note).
        alias_upsert(q, frow[0], conn=conn)
        return frow[0], frow[1], True
    if domain == "exercise":
        # Exercise names are the agent's snake_case, not the owner's words:
        # there is no alias store. Yes = use the existing name; nothing to
        # write.
        hit = conn.execute("SELECT exercise_name FROM ax_exercise WHERE "
                           "exercise_name=? LIMIT 1;", (str(ref),)).fetchone()
        if hit is None:
            raise ValueError("exercise %r not found" % (ref,))
        return hit[0], hit[0], False
    if domain in ("item", "category"):
        # 071 module_shopping: an item learns the words as an alias; a
        # category token is the agent's (yes = use it, nothing taught).
        import shop
        return shop.near_accept(sys.modules[__name__], conn, domain, ref, q)
    if domain in ("group", "sub_place"):
        # 073: a group learns the words as an alias; a room is used by its
        # own name (yes = use it; a room has no alias store, its token and
        # the room-noun-dropped core already match).
        nr = _noun_mod()
        if not str(ref).isdigit():
            raise ValueError("%s ref must be an id" % domain)
        name = nr.display(conn, domain, int(ref))
        if not name:
            raise ValueError("%s %s not found" % (domain, ref))
        if domain == "sub_place":
            return int(ref), name, False
        others = [h for h in nr.resolve(conn, q)
                  if not (h["kind"] == "group" and h["ref"] == int(ref))]
        if others:
            raise ValueError("'%s' already names %s:%d (%s)" % (
                q, others[0]["kind"], others[0]["ref"], others[0]["display"]))
        if nr.resolve(conn, q, kinds=("group",)):
            return int(ref), name, False
        nr.add_alias(sys.modules[__name__], conn, "group", int(ref), q)
        conn.commit()
        return int(ref), name, True
    raise ValueError("near-match: unknown domain %r (%s)"
                     % (domain, "|".join(NEAR_DOMAINS)))


def _near_ref_for_refuse(conn, domain, ref):
    """A refusal is stored under the same ref the candidate list prints.
    Places accept id / ulid / exact name on the CLI (the TRAVEL_PLACE_NEEDED
    near_place signal hands over the NAME), so resolve those to the id."""
    if domain == "place":
        row = travel_place_get(conn, ref)
        if row is None:
            raise ValueError("place %r not found" % (ref,))
        return row["id"]
    return ref


def cli_near_match_check(argv):
    """near-match-check <domain> <text>   READ ONLY.
    Prints the NEAR_MATCH block (exit 0) or NONE<TAB>domain<TAB>text."""
    if len(argv) < 2 or argv[0] not in NEAR_DOMAINS:
        _err("usage: kit_life.sh near-match-check <%s> <text>"
             % "|".join(NEAR_DOMAINS))
    conn = get_conn()
    try:
        cands = near_candidates(conn, argv[0], argv[1])
    finally:
        conn.close()
    if not cands:
        print("NONE\t%s\t%s" % (argv[0], " ".join(argv[1].split())))
        return
    for line in near_match_lines(argv[0], argv[1], cands):
        print(line)


def cli_near_match_accept(argv):
    """near-match-accept <domain> <ref> <text>   owner said YES.
    Output: ACCEPTED<TAB>domain<TAB>ref<TAB>canonical<TAB>taught(0|1)"""
    if len(argv) < 3 or argv[0] not in NEAR_DOMAINS:
        _err("usage: kit_life.sh near-match-accept <%s> <ref> <text>"
             % "|".join(NEAR_DOMAINS))
    conn = get_conn()
    try:
        try:
            ref, name, taught = near_accept(conn, argv[0], argv[1], argv[2])
        except ValueError as e:
            _err(str(e))
    finally:
        conn.close()
    print("ACCEPTED\t%s\t%s\t%s\t%d" % (argv[0], ref, name, 1 if taught else 0))


def cli_near_match_undo(argv):
    """Undo a person near-match acceptance through the alias inverse."""
    if len(argv) < 3 or argv[0] != "person" or not str(argv[1]).isdigit():
        _err("usage: kit_life.sh near-match-undo <person> <id> <alias>")
    row = person_alias_rm(argv[1], argv[2])
    if row is None:
        _err("해당 id 사람 없음: %s" % argv[1])
    print("UNDONE\tperson\t%s\t%s\t%s" % (
        row[0], row[1], _noun_mod().ws(argv[2])))


def cli_near_match_refuse(argv):
    """near-match-refuse <domain> <ref> <text> [said]   owner said NO.
    Remembers the pair; creates nothing (re-run the create verb, or the
    appt-travel-attach that raised near_place, and it goes through).
    Output: REFUSED<TAB>domain<TAB>ref<TAB>text"""
    if len(argv) < 3 or argv[0] not in NEAR_DOMAINS:
        _err("usage: kit_life.sh near-match-refuse <%s> <ref> <text> [said]"
             % "|".join(NEAR_DOMAINS))
    conn = get_conn()
    try:
        try:
            ref = _near_ref_for_refuse(conn, argv[0], argv[1])
            n = near_refuse(conn, argv[0], argv[2], [ref],
                            said=argv[3] if len(argv) > 3 else None)
        except ValueError as e:
            _err(str(e))
    finally:
        conn.close()
    if n is None:
        sys.exit(1)
    print("REFUSED\t%s\t%s\t%s" % (argv[0], ref, " ".join(argv[2].split())))



def _ff_task_line(row):
    """Render an event_find_first row in the task-CLI line format."""
    (eid, _u, _k, title, sa, _ea, _sk, tz, outcome, _sat, _v, _loc) = row
    due = str(_local_date_of(sa, tz or "Asia/Seoul")) if sa else ""
    state = "done" if outcome == "done" else "todo"
    return f"{eid}\t{title}\t{due}\t{state}"


def _ff_appt_line(row):
    """Render an event_find_first row in the appt-CLI line format."""
    (eid, _u, _k, title, sa, _ea, sk, tz, _o, _sat, _v, loc) = row
    col2 = _render_local_col(sa, sk, tz or "Asia/Seoul") if sa else ""
    return f"{eid}\t{col2}\t{title}\t{loc or ''}"


def _exists_gate(conn, title, date, line_fn):
    """DGN-579 B4 shared add-verb gate: run the unified probe; on a hit,
    print the EXISTS listing (contract preserved verbatim: 'EXISTS n' +
    rows) and exit EXISTS_CODE without writing. Caller handles --new."""
    _tier, rows = event_find_first(conn, title, date=date)
    if rows:
        print(f"EXISTS {len(rows)}")
        for row in rows:
            print(line_fn(row))
        conn.close()
        sys.exit(EXISTS_CODE)


def exclusive_blockers(conn, cand_start, cand_eff_end, exclude_id=None):
    """DGN-579 B2 (locked decision 1): live exclusive actionable rows whose
    [start, eff_end) intersects the candidate span -- the rows the write lost
    the slot to. Companion listing of the _overlap_not_exists guard (same
    LIVE_FILTER + half-open math). Returns
    [(id, ulid, title, start_local, end_local, kind)] start-ordered."""
    sql = ("SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, "
           "e.schedule_kind, e.display_tz, e.kind FROM timeblock e WHERE " +
           LIVE_FILTER + " AND ? < " + EFF_END_SQL + " AND e.start_at < ?")
    params = [cand_start, cand_eff_end]
    if exclude_id is not None:
        sql += " AND e.id != ?"
        params.append(exclude_id)
    rows = conn.execute(sql + " ORDER BY e.start_at;", params).fetchall()
    out = []
    for (eid, ulid, title, sa, ea, sk, tz, kind) in rows:
        out.append((eid, ulid, title,
                    _render_local_col(sa, sk, tz or "Asia/Seoul"),
                    _render_local_col(ea, sk, tz or "Asia/Seoul"), kind))
    return out


def _print_conflict_and_exit(conn, cand_start, cand_eff_end, exclude_id=None):
    """DGN-579 B2: print the structured CONFLICT listing (the blocker rows
    the agent needs to PROMPT the user) and exit CONFLICT_CODE. Nothing was
    written -- distinct from EXISTS (pre-write dup) and from a bare error."""
    blockers = exclusive_blockers(conn, cand_start, cand_eff_end,
                                  exclude_id=exclude_id)
    print(f"CONFLICT {len(blockers)}")
    for (bid, bulid, btitle, bsl, bel, bkind) in blockers:
        print(f"{bid}\t{btitle}\t{bsl}\t{bel}\t{bkind}")
    conn.close()
    sys.exit(CONFLICT_CODE)


def _pop_flag(argv, flag):
    """Return (argv_without_flag, present_bool), removing every occurrence of
    flag. These CLIs are positional, so the flag may sit anywhere; stripping it
    leaves the remaining positional args index-identical to the legacy call."""
    if flag in argv:
        return [a for a in argv if a != flag], True
    return list(argv), False


def _pop_opt(argv, flag):
    """DGN-273: return (argv_without_pair, value_or_None), removing the first
    '<flag> <value>' pair. Same positional-preserving contract as _pop_flag.
    A trailing flag with no value is a loud usage error."""
    argv = list(argv)
    if flag not in argv:
        return argv, None
    i = argv.index(flag)
    if i + 1 >= len(argv):
        _err("%s requires a value" % flag)
    val = argv[i + 1]
    del argv[i:i + 2]
    return argv, val


def _meal_history_ask(conn, argv, name, grams):
    """Persist only the proposed action; no meal, alias or satiety writes."""
    conn.execute('BEGIN IMMEDIATE')
    prefix = 'meal_history_confirm.'
    token = None
    for key, raw in conn.execute('SELECT key,value FROM config WHERE key LIKE ?',
                                 (prefix + '%',)):
        pending = json.loads(raw)
        if pending['state'] == 'pending' and pending['argv'] == argv:
            token = key[len(prefix):]
            break
    if token is None:
        token = secrets.token_hex(12)
        conn.execute('INSERT INTO config(key,value) VALUES(?,?)',
                     (prefix + token, json.dumps(dict(state='pending', argv=argv),
                                                 ensure_ascii=False)))
    conn.commit()
    amount = _opt_num(grams)
    food = _meal_receipt_base(name) if amount is not None else name
    amount_text = '(%sg)' % _f0(amount) if amount is not None else ''
    question = _i18n('meal.resolved.history', 'Your usual {food}{amount}, right?')
    question = question.replace('{food}', food).replace('{amount}', amount_text)
    choices = [('yes', _i18n('meal.resolved.yes', 'Yes')),
               ('other', _i18n('meal.resolved.other', 'Something else'))]
    ac = _ask_choices()
    print('MEAL_CONFIRM_ASK\t%s\t%s\t%s' % (token, question, ac.choices_field(choices)))
    print(ac.options_line('MEAL_CONFIRM_ASK', token, choices))
    print('MEAL_CONFIRM_RELAY For a history match, send ONLY the question verbatim '
          'and its [[OPTIONS]] marker on its own line. Nothing is recorded yet. '
          'Never write before 맞아요 / Yes. Run the ASK_OPTIONS answer command '
          'with yes for 맞아요 / Yes, other for 다른 거예요 / Something else. '
          'After yes, relay ONE reply: RESOLVED -> MEAL_CARD -> SATIETY_ASK '
          '(when printed), with its buttons last. Never print protocol tags or this line.')


def cli_meal_confirm(argv):
    if len(argv) != 2 or argv[1] not in ('yes', 'other'):
        _err('usage: kit_life.sh meal-confirm <request> yes|other')
    key = 'meal_history_confirm.' + argv[0]
    conn = get_conn()
    try:
        conn.execute('BEGIN IMMEDIATE')
        raw = _config_stored(conn, key)
        if raw is None:
            _err('unknown meal confirmation; ask again through meal-add')
        pending = json.loads(raw)
        if pending['state'] == 'confirmed':
            print(_i18n('meal.resolved.already', 'This meal is already logged.'))
            return 'meal-no-write'
        if argv[1] == 'other' or pending['state'] == 'rejected':
            pending['state'] = 'rejected'
            conn.execute('UPDATE config SET value=? WHERE key=?',
                         (json.dumps(pending, ensure_ascii=False), key))
            conn.commit()
            print(_i18n('meal.resolved.what', 'What did you eat?'))
            return 'meal-no-write'
        # Keep the writer lock through the meal and confirmation commit. A
        # repeated tap cannot append another row, including with --new.
        cli_meal_add(pending['argv'], _confirmation=(conn, key))
    finally:
        conn.close()


def cli_meal_add(argv, _confirmation=None):
    argv = list(argv)
    if len(argv) >= 2:
        try:
            argv[1] = meal_slots.canonical(argv[1])
        except ValueError as e:
            _err(str(e))
    original_argv = list(argv)
    if any(flag in argv for flag in ('--dish', '--portion', '--cooked')):
        import made_dish
        if made_dish.cli_meal(sys.modules[__name__], argv):
            return
    # meal-add <date> <meal> <name> [carb protein fat fiber sugar alt_sugar grams alcohol] [--new] [--no-lookup]
    argv, experience_id = _pop_opt(argv, '--experience')
    argv, planned_at = _pop_opt(argv, '--at')
    argv, portion_options = _portion_options(argv)
    argv, force_new = _pop_flag(argv, '--new')      # DGN-231
    # 043: the documented escape from the lookup precondition. It ALWAYS works
    # -- the owner must never be unable to log a meal (DGN-928).
    argv, no_lookup = _pop_flag(argv, '--no-lookup')
    argv, from_stock = _pop_opt(argv, '--from-stock')
    argv, stock_quantity = _pop_opt(argv, '--stock-quantity')
    argv, stock_unit = _pop_opt(argv, '--stock-unit')
    if from_stock is not None:
        import pantry_stock
        if stock_quantity is not None:
            pantry_stock.number(stock_quantity)
    # Retained compatibility flag; satiety no longer blocks recording.
    argv, no_satiety = _pop_flag(argv, '--no-satiety')
    argv, from_history = _pop_flag(argv, '--from-history')
    argv, shake = _pop_flag(argv, '--shake')
    argv, mix_water_ml = _pop_opt(argv, '--mix-water-ml')
    argv, mix_liquid = _pop_opt(argv, '--mix-liquid')
    argv, mix_water_default_ml = _pop_opt(argv, '--mix-water-default-ml')
    argv, mix_water_source = _pop_opt(argv, '--mix-water-source')
    # --ref "<owner phrase>": the free-text reference the item was resolved
    # from; stored as a meal_alias of that item when the item already exists.
    ref = None
    if '--ref' in argv:
        i = argv.index('--ref')
        ref = argv[i + 1] if i + 1 < len(argv) else ''
        argv = argv[:i] + argv[i + 2:]
    if len(argv) < 3 or not argv[0] or not argv[2]:
        _err("사용법: kit_life.sh meal-add <date> <meal> <name> "
             "[carb protein fat fiber sugar alt_sugar grams alcohol] "
             "[--new] [--no-lookup] [--no-satiety] [--ref <phrase>] "
             "[--portion-source stated|package|estimate] "
             "[--portion-basis exact|package|count|part|volume|standard|estimate "
             "--portion-evidence <owner words> [--count N|--fraction F|--volume-ml N]] "
             "[--from-history] [--shake] [--mix-water-ml <ml>] [--mix-liquid water|milk|none] "
             "[--at HH:MM (planned meals only)]")
    date, meal, name = argv[0], argv[1], argv[2]
    g = lambda i: argv[i] if i < len(argv) else None
    conn = _confirmation[0] if _confirmation else get_conn()
    try:
        if experience_id is not None:
            event = experience_resolve(conn, experience_id)
            if event is None:
                _err('meal experience not found')
            experience_id = event[0]
        # A cooking session owns its meal nutrition. A --new --no-lookup
        # estimate must never bypass the made-dish close/share path.
        import activity_session as _cooking_frame
        _cooking_state = _cooking_frame.load(sys.modules[__name__], conn)
        if _cooking_state and _cooking_state.get('kind') == 'cooking':
            import cooking_owner as _cooking_owner
            _said = _cooking_owner.latest(sys.modules[__name__])
            _active = _cooking_state.get('phase') in ('ready', 'active')
            _unlogged = not conn.execute('SELECT 1 FROM made_dish d JOIN made_dish_meal m ON m.dish_id=d.id WHERE d.session_id=? LIMIT 1', (_cooking_state['id'],)).fetchone()
            _same_day = any(str(h.get('completed_at', '')) and datetime.datetime.fromtimestamp(h['completed_at'], ZoneInfo(agent_conf.conf_str('AGENT_TIMEZONE', 'Asia/Seoul'))).date().isoformat() == date for h in _cooking_state.get('history', []))
            if _active:
                print(json.dumps(dict(status='COOKED_REQUIRED', next='Run meal-add DATE SLOT --cooked with the exact owner words. Close the session and resolve its share; never hand-type macros.'), ensure_ascii=False))
                return 'meal-no-write'
        alias_new = None
        if ref:
            from meal_search import alias_candidate, meal_search
            alias_new = alias_candidate(sys.modules[__name__], conn, ref, name)
            identity = _meal_capture_identity(conn, name)
            from_history = from_history or any(
                row['source'] == 'history' and not row['planned'] and
                row['key'] == identity for row in meal_search(
                    sys.modules[__name__], conn, _meal_receipt_base(name)))
        if from_history and _confirmation is None:
            _meal_history_ask(conn, original_argv, name, g(9))
            return 'meal-no-write'
        if from_stock is not None:
            import shop
            stock_item = shop._item_must(conn, from_stock)
            if not pantry_stock.ready(conn):
                _err('meal stock use requires migration 090')
        # record-always-on: satiety calibration and the target offer are the
        # meal module's management lens. Not eligible -> the meal records now
        # (no satiety precondition, no ask, no offer); the card still shows.
        manage = _manage_on(conn, 'module_meal')
        real_meal = _meal_is_real(meal, _meal_kcal({
            'carb': _num(g(3)), 'protein': _num(g(4)), 'fat': _num(g(5)),
            'fiber': _num(g(6)), 'alcohol': _num(g(10))}))
        if not real_meal:
            no_satiety = True
        # Every estimate records before asking; never manufacture an answer.
        captured_meal = experience_id is not None and not name.endswith(PLANNED_SUFFIX)
        pending_satiety = (real_meal and manage
                           and lookup_receipt_grade(conn, name) == 'estimate'
                           and satiety_read(date, _txt(meal), conn=conn, incoming=True) is None)
        if pending_satiety:
            no_satiety = True
        if not manage or (not name.endswith(PLANNED_SUFFIX) and any(
                _meal_swap_slot(r[1]) == _meal_swap_slot(meal)
                for r in meal_planned_list(date, conn=conn))):
            no_satiety = True
        if not force_new:
            # DGN-231 match key = (date, meal slot). meal_find -> (id, name,
            # meal, kcal); its meal col is COALESCE(meal,'') so '' <-> _txt None.
            slot = _txt(meal)
            matches = [r for r in meal_find(date, conn=conn)
                       if (r[2] or None) == slot and
                       (name.endswith(PLANNED_SUFFIX) or not r[1].endswith(PLANNED_SUFFIX))]
            if matches and lookup_receipt_check(conn, name) is True:
                # A completed lookup identifies the incoming food. Other
                # foods in this slot are not duplicates (dinner may contain
                # both pork and pasta); resolve the old --new retry here.
                # No receipt/infra fault keeps the conservative slot guard.
                food = _meal_capture_identity(conn, name)
                matches = [r for r in matches
                           if _meal_capture_identity(conn, r[1]) == food]
                if real_meal and not name.endswith(PLANNED_SUFFIX):
                    _key, occasion_ids = _satiety_context(
                        conn, _satiety_state_load(conn=conn), date, slot, incoming=True)
                    matches = [r for r in matches if r[0] in occasion_ids]
                elif not name.endswith(PLANNED_SUFFIX):
                    # Non-meals have no occasion ids. Still guard immediate
                    # retries, while allowing another supplement later.
                    now = _satiety_instant(now_utc())
                    recent = set()
                    for mid, ts in conn.execute('SELECT id, created_at FROM ' +
                                               MEALS_V32 + ' WHERE date=?', (date,)):
                        at = _satiety_instant(ts)
                        if (now and at and 0 <= (now - at).total_seconds() <
                                SATIETY_OCCASION_GAP_MINUTES * 60):
                            recent.add(mid)
                    matches = [r for r in matches if r[0] in recent]
            if matches:
                print(f"EXISTS {len(matches)}")
                for mid, nm, ml, kcal in matches:
                    print(f"{mid}\t{nm}\t{ml}\t{_f0(kcal)}")
                sys.exit(EXISTS_CODE)
        # the record line is stdout line 1; AUTO-LINKED follows it
        notices = _autolink_defer()
        try:
            try:
                nid = meal_add(date, meal, name,
                               carb=g(3), protein=g(4), fat=g(5), fiber=g(6),
                               sugar=g(7), alt_sugar=g(8), grams=g(9),
                               alcohol=g(10), conn=conn,
                               allow_unlooked=no_lookup,
                               allow_unsated=no_satiety, experience_id=experience_id,
                               shake=shake, mix_water_ml=mix_water_ml, mix_liquid=mix_liquid,
                               mix_reference=ref, mix_water_default_ml=mix_water_default_ml,
                               mix_water_source=mix_water_source,
                               _confirmation_key=_confirmation[1] if _confirmation else None,
                               planned_at=planned_at, **portion_options)
            except (LookupSkippedError, ValueError) as e:
                _err(str(e))
            row = conn.execute("SELECT id, name, kcal FROM " + MEALS_V32 +
                               " WHERE id=?;", (nid,)).fetchone()
            # A plain food write also creates a meal experience. Continue on
            # its durable primary link so all foods share the clock lane.
            meal_event = conn.execute(
                "SELECT re.event_id FROM record r "
                "JOIN record_event re ON re.record_id=r.id "
                "WHERE r.source_table='block' AND r.source_id=? "
                "AND re.role='primary' ORDER BY re.event_id DESC LIMIT 1", (nid,)).fetchone()
            meal_event_id = (int(experience_id) if experience_id is not None
                             else meal_event[0] if meal_event else None)
            swap_pending = bool(meal_planned_swap_candidates(conn, nid))
            time_flow = (meal_event_id is not None and real_meal and not swap_pending
                         and not name.endswith(PLANNED_SUFFIX))
            print(f"{row[0]}\t{row[1]}\t{_f0(row[2])}")
            if time_flow and captured_meal:
                import meal_time
                resolved = meal_time.resolved(sys.modules[__name__], conn, int(experience_id))
            else:
                resolved = meal_resolved_text(conn, row[1], g(9), from_history, mid=nid)
            print("RESOLVED\t" + resolved)
            if from_stock is not None:
                usage_key = 'meal:%s' % nid
                if stock_quantity is None:
                    # Unknown amount is durable, and asks once; never assume a pack.
                    conn.execute("INSERT INTO stock_use(usage_key,item_id,quantity,unit,state,detail) "
                                 "VALUES(?,?,NULL,?,'unknown','meal amount unknown')",
                                 (usage_key, stock_item['id'], pantry_stock.norm_unit(stock_unit)))
                else:
                    pantry_stock.consume(conn, stock_item['id'], stock_quantity,
                                         stock_unit or 'pack', usage_key)
                for line in pantry_stock.ask_once(sys.modules[__name__], conn, usage_key):
                    print(line)
                conn.commit()
            if alias_new:
                alias_upsert(alias_new[0], alias_new[1], conn=conn)
                print(f"ALIAS_SAVED\t{alias_new[0]}\t{alias_new[1]}")
        finally:
            _autolink_flush(notices)
        # fb-1787479201-4: the estimate and its reason, at the write.
        est = meal_estimate_reason(conn, name)
        if est:
            print(f"ESTIMATE\t{est[0]}\t{est[1]}")
        # Shared kit text card, then the existing target/satiety protocol.
        if time_flow:
            import meal_time
            for line in meal_time.begin(sys.modules[__name__], conn, meal_event_id,
                                        once=not captured_meal):
                print(line)
            _capture_open_today(conn, 'meal-add', nid, date, MEALS_V32)
            return
        offered = _emit_meal_card(conn, date, offer=manage and not swap_pending and not captured_meal and not pending_satiety) == 'offer'
        # Satiety follows the recorded card: required for a pending estimate,
        # optional for an exact meal. An existing answer closes the occasion.
        # The once-only target offer owns the buttons of its turn: no ask then.
        slot = _txt(meal)
        if real_meal and slot and satiety_read(date, slot, conn=conn) is None:
            lines = ([] if offered or not manage or swap_pending
                     else _meal_satiety_ask_once(conn, date, slot, pending_satiety))
        elif real_meal and slot and manage and not swap_pending:
            lines = ["SATIETY_CLOSE\tmeal-satiety %s %s" % (date, slot)]
        else:
            lines = []
        if lines:
            for ln in lines:
                print(ln)
            print(SATIETY_RELAY)
        _capture_open_today(conn, "meal-add", nid,
                            conn.execute("SELECT date FROM " + MEALS_V32 +
                                         " WHERE id=?", (nid,)).fetchone()[0], MEALS_V32)
        if swap_pending:
            _emit_planned_swap(conn, nid)
    finally:
        if _confirmation is None:
            conn.close()


# -- shared kit text diet card + simple daily target -----------------------
# Owner layout 1, 2026-10-18 20:29; burn policy clarified 2026-10-19.
# Both agents use this renderer. Pack image/routing adapter proposal lives in
# docs/proposals/diet-text-card-pack.md; no planning skills move in this change.
# The daily target is the stored base + meal_workouts' calibrated allowance.
# Satiety buttons remain after MEAL_CARD_END through the existing meal CLI.
MEAL_CARD_BEGIN = "MEAL_CARD_BEGIN"
MEAL_CARD_END = "MEAL_CARD_END"
MEAL_CARD_RELAY = (
    "MEAL_CARD_RELAY Finish remaining tool work silently, then send ONE reply. "
    "If this food belongs to an experience, attach its block id first. "
    "For meal-add, start with its RESOLVED sentence verbatim, naming the food "
    "and grams with the supplied estimate wording. History matches first get "
    "MEAL_CONFIRM_ASK alone with its buttons; never write before 맞아요 / Yes. Then put the lines "
    "between MEAL_CARD_BEGIN and MEAL_CARD_END VERBATIM inside ONE code block "
    "(```), keeping every space and line. Any printed fullness question follows the card with "
    "its buttons last; never relay a bare fullness question. If identity is "
    "ambiguous, confirm the candidate before recording, then follow this same "
    "name -> card -> fullness order. For a card-only refresh, use its rendered "
    "card without inventing a RESOLVED line. When TARGET_OFFER is present, end "
    "with its text and two TARGET_BUTTON labels in order. Never print "
    "RESOLVED, MEAL_CARD_*, TARGET_* tags or this relay instruction.")

DIET_STATUS_CARD_PATHS = (
    os.path.join(".claude", "skills", "diet-status", "card.py"),
    os.path.join(".claude", "skills-bundle", "diet-status", "card.py"),
)
KIT_AGENT_ROOT_ENV = "KIT_LIFE_AGENT_ROOT"      # test seam: the agent root
MEAL_CARD_WIDTH = 36
MEAL_BAR_CELLS = 10
_MEAL_TARGET_OFFERED_KEY = "meal_target_offered"
_MEAL_TARGET_KEYS = ("diet_bmr_method", "deficit_kcal", "protein_g")
# slot order of the [log] rows: breakfast, lunch, dinner, snack, workout
_MEAL_SLOT_RANK = meal_slots.RANK
# The LOCAL time-of-day window each meal slot stands for, [start, end) as
# minutes after local midnight. Read by event containment (_meal_slot_in_span:
# auto-link + experience-sweep) so a date-only meal joins only an event whose
# span overlaps the slot's part of the day -- 2026-10-08: a lunch was linked
# to an evening housewarming because the span rule judged whole days. A
# slot absent here (snack, workout, free text) has no time of day: span
# containment says nothing about it (038 doctrine: silence over a guess).
_MEAL_SLOT_WINDOWS = {u"\uc544\uce68": (5 * 60, 11 * 60),    # breakfast
                      u"\uc810\uc2ec": (11 * 60, 15 * 60),   # lunch
                      u"\uc800\ub141": (17 * 60, 22 * 60)}   # dinner
_TARGET_DIRECTIONS = {
    "lose": "cut", u"빼기": "cut",
    "keep": "recomp", u"유지": "recomp",
    "gain": "lean_bulk", u"늘리기": "lean_bulk",
}
_TARGET_SEX = {"male": "male", "m": "male", u"남": "male",
               u"남자": "male", "female": "female", "f": "female",
               u"여": "female", u"여자": "female"}


def _agent_root():
    return os.environ.get(KIT_AGENT_ROOT_ENV) or _kit_root()


def diet_status_card_present(root=None):
    """Compatibility detector for consumers; never suppresses the kit card."""
    root = root or _agent_root()
    return any(os.path.isfile(os.path.join(root, p))
               for p in DIET_STATUS_CARD_PATHS)


def _cell_width(ch):
    import unicodedata
    if unicodedata.combining(ch) or ch in "‍️":
        return 0
    if ord(ch) >= 0x1F000:
        return 2                         # emoji
    return 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1


def _card_dwidth(s):
    return sum(_cell_width(c) for c in str(s))


def _card_pad(s, width, align="l"):
    s = str(s)
    gap = width - _card_dwidth(s)
    if gap <= 0:
        return s
    return (" " * gap + s) if align == "r" else (s + " " * gap)


def _n(x):
    """Whole number with thousands separators ('1,240')."""
    try:
        return "{:,}".format(int(round(float(x or 0))))
    except (TypeError, ValueError):
        return "0"


def meal_targets_set(conn):
    """True when a daily intake target is on file (the goal interview's or
    the kit's simple target): stored energy intent, plus a stored protein
    goal or measured/stored body weight for the protein band."""
    protein_basis = (_config_stored(conn, 'protein_g') is not None
                     or _body_weight_now(conn) is not None)
    return protein_basis and (
        _settled_diet_base(conn) is not None or
        all(_config_stored(conn, k) is not None for k in _MEAL_TARGET_KEYS[:2]))


def meal_targets(conn, date):
    """{kcal, carb, protein, fat} daily targets, or None when none is set."""
    if not meal_targets_set(conn):
        return None
    try:
        stats = _meal_body_stats(conn)
        t = targets_for_date(date, stats=stats, conn=conn)
        kcal = t["eff_goal"]
        mg = resolve_macro_goals(kcal, stats, _macro_day_type(conn, date))
    except Exception:            # noqa: BLE001 -- a card never fails a write
        return None
    if not kcal or kcal <= 0:
        return None
    settled = _settled_diet_base(conn) is not None
    return {"kcal": kcal, "carb": mg["carb"], "protein": mg["protein"],
            "fat": mg["fat"], "base_kcal": t["base_goal"],
            "macro_bands": _meal_macro_bands(conn, kcal, date=date),
            "workout_kcal": t["burn_kcal"],
            # Compatibility point target; the card uses macro_bands when
            # body weight is known. Formula terms stay below the kcal row.
            "protein_goal": (mg["protein"]
                             if mg["protein_source"] not in ("default", None)
                             else None),
            # additive, NOT rendered by any card (UI-GATE): provenance and
            # status for JSON/CLI consumers
            "protein_source": mg["protein_source"],
            "macro_status": mg["status"], "diet_style": mg["style"],
            "bmr": t["bmr"], "neat": t["neat"], "balance": t["deficit"],
            "carry": 0, "notices": [],
            "adjustment": (t["base_goal"] - (t["bmr"] + t["neat"] - t["deficit"])
                           if settled else 0)}


def _meal_body_stats(conn):
    """Use the latest body records on each read, with stored config fallback."""
    stats = _merge_body_stats(SqliteConfigStore()._read_rows(conn))
    observed = {}
    weight = _body_weight_now(conn)
    if weight is not None:
        stats['weight_kg'] = weight
    # Across FFM aliases, the newest reading wins. A same-day weight and
    # fat reading also supplies FFM, without averaging old compositions.
    lean = _brief_measure_row(conn, _FFM_KEYS)
    candidates = [(lean['as_of'], lean['value'])] if lean else []
    measured_weight = _brief_measure_row(conn, ('body_weight', 'weight_kg'))
    if measured_weight and measured_weight['value'] == weight:
        observed['weight_kg'] = measured_weight['as_of']
    if measured_weight:
        for keys, is_pct in [(('fat_mass_kg',), False), (('body_fat_pct',), True)]:
            fat = _brief_measure_row(conn, keys)
            if fat and fat['as_of'] == measured_weight['as_of']:
                value = (measured_weight['value'] * (1 - fat['value'] / 100)
                         if is_pct else measured_weight['value'] - fat['value'])
                candidates.append((fat['as_of'], value))
    if candidates:
        _day, value = max(candidates, key=lambda r: r[0])
        if value > 0:
            stats['lean_mass_kg'] = value
            observed['lean_mass_kg'] = _day
    pct = None
    fat = _brief_measure_row(conn, ('fat_mass_kg',))
    if fat:
        stats['fat_mass_kg'] = fat['value']
        observed['fat_mass_kg'] = fat['as_of']
    elif measured_weight:
        pct = _brief_measure_row(conn, ('body_fat_pct',))
        if pct and pct['as_of'] == measured_weight['as_of']:
            stats['fat_mass_kg'] = weight * pct['value'] / 100
            observed['fat_mass_kg'] = pct['as_of']
    # Measured aliases are stored facts too; a config-only fallback marker
    # would otherwise make the kernel reject a real body snapshot.
    measured = set(observed)
    stats[BODY_STATS_FALLBACK_KEY] = tuple(
        k for k in stats[BODY_STATS_FALLBACK_KEY] if k not in measured)
    stats['_body_measurements'] = observed
    return stats


def _meal_macro_bands(conn, kcal, eaten=None, date=None):
    """Additive band contract; legacy/minimal readers need no body tables."""
    try:
        stats = body_stats_for_conn(conn)
        if date is not None and eaten is None:
            rows = conn.execute('SELECT name,kcal,protein,carb,fat FROM ' +
                                MEALS_V32 + ' WHERE date=?', (date,)).fetchall()
            rows = [r for r in rows if not (len(str(r[0] or '')) > len(PLANNED_SUFFIX)
                                            and str(r[0]).endswith(PLANNED_SUFFIX))]
            eaten = {k: sum(float(r[i] or 0) for r in rows)
                     for i, k in enumerate(('kcal', 'protein', 'carb', 'fat'), 1)}
        return resolve_macro_goals(kcal, stats, eaten=eaten)['macro_bands']
    except (sqlite3.OperationalError, ValueError, TypeError):
        return None


def _meal_card_title(date, today):
    try:
        d = datetime.date.fromisoformat(str(date)[:10])
    except ValueError:
        return _i18n("meal.card.title", "Meals · {date}").format(date=date)
    days = [w.strip() for w in _i18n("day.card.weekdays",
                                     "Mon,Tue,Wed,Thu,Fri,Sat,Sun").split(",")]
    label = "%d/%d(%s)" % (d.month, d.day,
                           days[d.weekday()] if len(days) == 7 else "")
    key = "meal.card.title_today" if str(date)[:10] == today else "meal.card.title"
    return _i18n(key, "Meals · {date}").format(date=label)


DIET_TARGET_ROWS = "diet-providers.tsv"      # service/<ns>/: <module>\t<command>
DIET_TARGET_TIMEOUT_SEC = 8


def _provider_num(v):
    """float or None; a card number is finite and not a bool."""
    import math
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return None
    return float(v) if math.isfinite(v) else None


def _diet_target_from_provider(date):
    """The card target a pack declares (`module_health<TAB>diet-target` in
    service/<ns>/diet-providers.tsv; `diet-target --date D --json`), shaped like
    meal_targets(); None with no provider, a timeout, a failure or JSON that
    carries no usable eff_goal -- the caller then uses the kit's own target."""
    try:
        import retro_sections
        import subprocess
        root = retro_sections.service_dir(SCRIPT_DIR)
        found = retro_sections.rows(root, DIET_TARGET_ROWS)
        if not found:
            return None
        _key, argv, base, _lanes = found[0]
        p = subprocess.run(argv + ["--date", str(date), "--json"], cwd=base,
                           stdin=subprocess.DEVNULL, capture_output=True,
                           timeout=DIET_TARGET_TIMEOUT_SEC)
        if p.returncode != 0:
            return None
        d = json.loads(p.stdout.decode("utf-8", "replace"))
    except Exception:            # noqa: BLE001 -- a card never fails a write
        return None
    return nutrition_target(d)


def nutrition_target(d):
    """Normalize a provider's structured target, without reading or rendering."""
    if not isinstance(d, dict):
        return None
    eff = _provider_num(d.get("eff_goal"))
    if not eff or eff <= 0:
        return None
    base_goal = _provider_num(d.get("base_goal"))
    macros = d.get("macros") if isinstance(d.get("macros"), dict) else {}
    burn = _provider_num(d.get("burn_kcal"))
    if burn is None:
        burn = eff - base_goal if base_goal is not None else 0.0
    notices = ([str(x) for x in d["notices"] if str(x).strip()]
               if isinstance(d.get("notices"), list) else [])
    lines = ([str(x) for x in d["formula_lines"]]
             if isinstance(d.get("formula_lines"), list) else [])
    balance = _provider_num(d.get("balance"))
    if balance is None:
        balance = _provider_num(d.get("deficit"))
    return {"kcal": eff, "carb": _provider_num(macros.get("carb")),
            "protein": _provider_num(d.get("protein_goal")),
            "protein_goal": _provider_num(d.get("protein_goal")),
            "fat": _provider_num(macros.get("fat")),
            "base_kcal": base_goal if base_goal is not None else eff - burn,
            "workout_kcal": burn,
            "bmr": _provider_num(d.get("bmr")),
            "neat": _provider_num(d.get("neat")),
            "balance": balance,
            "carry": _provider_num(d.get("carry_kcal")) or 0,
            "adjustment": _provider_num(d.get("adjustment")) or 0,
            "notices": notices, "formula_lines": lines}


def _meal_card_sub_line(value):
    """Keep meal breakdowns under the bulleted macro label."""
    return " " + sub_line(value)


def _meal_card_formula(tgt):
    """The two formula lines under the calorie row. The first term follows
    the goal direction (cut -> reduction, gain -> increase, maintain ->
    omitted); exercise only above zero; carry and adjustment ride on line 2.
    A provider that sends no bmr/neat gets its own formula_lines verbatim."""
    if tgt.get("bmr") is None or tgt.get("neat") is None:
        return [_meal_card_sub_line(line) for line in tgt.get("formula_lines") or []]
    def k(key, fallback, **kw):
        return _i18n("meal.card." + key, fallback).format(**kw)
    bal = int(round(tgt.get("balance") or 0))
    bmr = int(round(tgt["bmr"]))
    first = k("formula_base", "Base {n}", n=_n(bmr))
    if bal > 0:
        first += k("formula_cut", " - Deficit {n}", n=_n(bal))
    elif bal < 0:
        first += k("formula_gain", " + Surplus {n}", n=_n(-bal))
    second = k("formula_neat", "NEAT {n}", n=_n(tgt["neat"]))
    if round(float(tgt.get("workout_kcal") or 0)) > 0:
        second += k("formula_exercise", " + Exercise {n}",
                    n=_n(tgt["workout_kcal"]))
    if tgt.get("carry"):
        second += k("formula_carry", " - Carry {n}", n=_n(tgt["carry"]))
    adj = int(round(tgt.get("adjustment") or 0))
    if adj:
        second += k("formula_adjust_up" if adj > 0 else "formula_adjust_down",
                    " + Adjustment {n}" if adj > 0 else " - Adjustment {n}",
                    n=_n(abs(adj)))
    return [_meal_card_sub_line(first), _meal_card_sub_line(second)]


def nutrition_snapshot(conn, date, *, target_override=None):
    """Read today's nutrition facts once; every surface renders this snapshot."""
    from nutrition_snapshot import NutritionSnapshot, display_bands
    rows = conn.execute(
        "SELECT id, meal, name, kcal, carb, protein, fat, sugar FROM " + MEALS_V32 +
        " WHERE date=?;", (date,)).fetchall()
    rows.sort(key=lambda r: (_MEAL_SLOT_RANK.get(r[1] or "", 9), r[0]))
    def _is_planned(r):
        nm = str(r[2] or "")
        return len(nm) > len(PLANNED_SUFFIX) and nm.endswith(PLANNED_SUFFIX)
    eaten_rows = [r for r in rows if not _is_planned(r)]
    plan_rows = [r for r in rows if _is_planned(r)]
    def _sum(rs):
        return {"kcal": sum(float(r[3] or 0) for r in rs),
                "carb": sum(float(r[4] or 0) for r in rs),
                "protein": sum(float(r[5] or 0) for r in rs),
                "fat": sum(float(r[6] or 0) for r in rs),
                "sugar": sum(float(r[7] or 0) for r in rs)}
    tot, plan = _sum(eaten_rows), _sum(plan_rows)
    plan["caffeine"] = 0  # planned caffeine is never an intake or an allowance
    ids = [r[0] for r in eaten_rows]
    caffeine_estimated = False
    try:
        tot["caffeine"] = float(conn.execute(
            "SELECT COALESCE(SUM(value),0) FROM measure WHERE metric='caffeine' "
            "AND block_id IN (%s)" % ",".join("?" * len(ids)), ids).fetchone()[0]
            or 0) if ids else 0.0

        caffeine_estimated = bool(ids and conn.execute(
            "SELECT 1 FROM measure m JOIN provenance p ON p.token=m.value_origin "
            "WHERE m.metric='caffeine' AND m.value>0 AND p.is_estimate=1 "
            "AND m.block_id IN (%s) LIMIT 1" %
            ",".join("?" * len(ids)), ids).fetchone())
    except sqlite3.Error:
        tot["caffeine"] = 0.0
    provider_tgt = target_override or _diet_target_from_provider(date)
    tgt = provider_tgt or meal_targets(conn, date)
    band_result = _meal_macro_bands(conn, tgt['kcal'], tot) if tgt else None
    normal_result = None
    if band_result and band_result['remaining_kcal'] <= 0:
        # Rebuild the last normal-day target from recorded intake, before the
        # meal that exhausted the budget. Log order is independent of the
        # presentation's slot order; planned rows never change this target.
        prefix = sorted(eaten_rows, key=lambda r: r[0])
        while prefix:
            prefix.pop()
            candidate = _meal_macro_bands(conn, tgt['kcal'], _sum(prefix))
            if (candidate and candidate['remaining_kcal'] > 0
                    and candidate['status'] != 'infeasible'):
                normal_result = candidate
                break
    bands = display_bands(band_result, tot, normal_result=normal_result)
    if provider_tgt and provider_tgt.get('protein_goal') is None:
        # An explicit provider withdrawal still suppresses the protein bar.
        bands.pop('protein', None)
    if tgt and tgt.get('protein_source') == 'withdrawn':
        bands.pop('protein', None)
    extra_rows = []
    try:
        tracked_metrics = _config_stored(conn, 'meal_tracked_metrics')
    except sqlite3.OperationalError:
        # Minimal/legacy card readers need no config table for the default.
        tracked_metrics = None
    if tracked_metrics:
        import meal_tracking
        extra_rows = meal_tracking.amount_rows(
            sys.modules[__name__], conn, ids, [r[0] for r in plan_rows])
    import health_regimen
    import meal_tracking
    try:
        flags = meal_tracking.regimen_flags(sys.modules[__name__], conn, date)
    except sqlite3.OperationalError:
        flags = []
    caffeine_sensitive = tot['caffeine'] > 0 and _caffeine_sensitive(conn)
    advice = tuple(_caffeine_advice_keys(conn, tot['caffeine'], caffeine_sensitive)) if tot['caffeine'] > 0 else ()
    try:
        declared_protein = _provider_num(float(_config_stored(conn, 'protein_g')))
    except (TypeError, ValueError, sqlite3.OperationalError):
        declared_protein = None
    return NutritionSnapshot(
        date=str(date), rows=tuple(rows), eaten_rows=tuple(eaten_rows),
        planned_rows=tuple(plan_rows), eaten=tot, planned=plan, target=tgt,
        target_source="provider" if provider_tgt else "kit",
        declared_protein=declared_protein,
        band_result=band_result, bands=bands, tracked_rows=tuple(extra_rows),
        supplement_flags=tuple(flags), workouts=tuple(meal_workouts(conn, date)),
        caffeine_estimated=caffeine_estimated,
        caffeine_sensitive=caffeine_sensitive, caffeine_advice=advice,
        regimen_count=health_regimen.taken_count(conn, date) if not flags else 0)


def _meal_card_parts(conn, date, today=None, snapshot=None, sections=None):
    """(card lines, body start, body end): the body is the block between the
    first blank line and the blank line before the log section.

    Shared diet-status text, including zero meals before the first log.
    Owner layout: kcal with remaining, target and activity sub-lines, then
    protein, carb (sugar sub-line), fat, caffeine and optional tracked rows
    and supplement names. The energy target is the pack's diet-target
    provider when one is declared, else the kit's own."""
    snapshot = snapshot or nutrition_snapshot(conn, date)
    rows, eaten_rows, plan_rows = snapshot.rows, snapshot.eaten_rows, snapshot.planned_rows
    # Rendering must not mutate the facts shared with other surfaces.
    tot, plan = dict(snapshot.eaten), dict(snapshot.planned)
    tgt, bands = snapshot.target, snapshot.bands
    today = today or datetime.date.today().isoformat()
    slots = {r[1] or "" for r in rows if _meal_is_real(r[1], r[3])}
    title = _meal_card_title(date, today)
    count = _i18n("meal.card.count", "{n} meals").format(n=len(slots))
    lines = [title + " " * max(2, MEAL_CARD_WIDTH - _card_dwidth(title)
                               - _card_dwidth(count)) + count, ""]
    for workout in snapshot.workouts:
        lines.insert(len(lines) - 1, _i18n(
            'meal.card.workout', '{label} {minutes}min - {kcal}kcal{estimated}').format(
                label=workout['label'] or _i18n('meal.card.workout_unnamed', 'Workout'),
                minutes=_n(workout['minutes']),
                kcal=(_n(workout['kcal']) if workout['kcal'] is not None else '?'),
                estimated=(_i18n('meal.card.estimated', ' [estimated]')
                           if workout['estimated'] else '')))
    body_start = len(lines)
    cols = int(_i18n("meal.card.label_cols", "8") or 8)
    def _label_text(key):
        return _i18n("meal.card." + key, key)
    def _label(key):
        # Hangul occupies two cells; use ordinary monospace spaces for the
        # remainder rather than a fullwidth space with client font fallback.
        return _card_pad(_label_text(key), cols)
    goals = {"kcal": tgt and tgt["kcal"],
             "protein": tgt and tgt.get("protein_goal"),
             "carb": tgt and tgt.get("carb"), "fat": tgt and tgt.get("fat")}
    caffeine_sensitive = snapshot.caffeine_sensitive
    if tot["caffeine"] > 0 and not caffeine_sensitive:
        goals['caffeine'] = 400
    nutrients = [("kcal", "kcal"), ("protein", "g"), ("carb", "g"), ("fat", "g")]
    if 'caffeine' in goals:
        nutrients.append(('caffeine', 'mg'))
    extra_rows = snapshot.tracked_rows
    for row in extra_rows:
        key = row['metric']
        nutrients.append((key, row['unit']))
        tot[key], plan[key], goals[key] = row['eaten'], row['planned'], row['goal']
    cols = max([cols] + [_card_dwidth(_label_text(k)) for k, _u in nutrients])
    exhausted = snapshot.remaining_kcal is not None and snapshot.remaining_kcal <= 0
    for key, band in bands.items():
        goals[key] = band['min' if key == 'protein' and not exhausted else 'max']

    def _remaining_line():
        def signed(v, key_left, key_over, fb_left, fb_over):
            return (_i18n(key_left, fb_left) if v >= 0
                    else _i18n(key_over, fb_over)).format(kcal=_n(abs(v)))
        left = float(tgt['kcal']) - tot['kcal']
        value = (_n(left) + 'kcal' if left >= 0 else
                 _i18n('meal.card.over', '{kcal}kcal over').format(kcal=_n(-left)))
        tail = _i18n('meal.card.remaining', 'Remaining calories: {kcal}').format(kcal=value)
        if plan_rows:
            tail += ' \u00b7 ' + signed(
                left - plan['kcal'], 'meal.card.after_left',
                'meal.card.after_over', '{kcal}kcal left if you eat the planned',
                '{kcal}kcal over if you eat the planned')
        return _meal_card_sub_line(tail)

    nutrient_lines = {}
    for key, unit in nutrients:
        label = "• " + _label(key) + " "
        cur = tot[key]
        goal = float(goals[key] or 0)
        if goal > 0 or key in bands:
            def _cells(v):
                if goal <= 0:
                    return MEAL_BAR_CELLS if v > 0 else 0
                return max(0, min(MEAL_BAR_CELLS,
                                  int(MEAL_BAR_CELLS * v / goal + 0.5)))
            filled = _cells(cur)
            both = max(filled, _cells(cur + plan[key]))
            bar = ("\u2588" * filled + "\u2592" * (both - filled)
                   + "\u2591" * (MEAL_BAR_CELLS - both))
            # Exhausting kcal does not mean every nutrient exceeded its band.
            amount = cur if key in bands and exhausted else cur + plan[key]
            upper = bands[key]["max"] if key in bands else goal
            if amount > upper:    # "+" takes the separator's place
                head = "%s%s+ %s" % (label, bar, _card_pad(_n(cur), 4, "r"))
            else:
                head = "%s%s %s" % (label, bar, _card_pad(_n(cur), 5, "r"))
            line = "%s / %s%s" % (head, _n(goal), unit)
            if key in bands:
                line = "%s / %s-%sg" % (head, _n(bands[key]['min']),
                                         _n(bands[key]['max']))
            if key == 'caffeine' and snapshot.caffeine_estimated:
                line += _i18n('meal.card.estimated', ' [estimated]')
            lines.append(line)
        else:
            lines.append("%s%s%s" % (label, _n(cur), unit))
        nutrient_lines[key] = (lines[-1],)
        if key == "kcal" and goal > 0:
            lines.append(_remaining_line())
            lines += _meal_card_formula(tgt)
        if key == "carb" and tot["sugar"] > 0:
            lines.append(_meal_card_sub_line(_i18n("meal.card.sugar", "Sugar") + " " + _i18n(
                "meal.card.sugar_value", "{n}g").format(n=_n(tot["sugar"]))))
    if tot["caffeine"] > 0:
        for key in snapshot.caffeine_advice:
            lines.append(_i18n(key, _caffeine_COPY_EN[key]))
    if tgt:
        lines += list(tgt.get("notices") or [])
    flags = snapshot.supplement_flags
    if flags:
        lines.append(_i18n('meal.card.supplements', '💊 Supplements {taken}/{total}').format(
                     taken=sum(r['taken'] for r in flags), total=len(flags)))
        lines += [sub_line(r['name'] + (' \u2713' if r['taken'] else ' \u2610'))
                  for r in flags]
    else:
        if snapshot.regimen_count:
            lines.append(_i18n('regimen.card', 'card').format(n=snapshot.regimen_count))
    body_end = len(lines)
    lines += ["", _i18n("meal.card.log", "[Log]")]
    macro = _i18n("meal.card.row_macros",
                  "{kcal}kcal C{carb}g P{protein}g F{fat}g")
    for _id, slot, name, kcal, carb, protein, fat, _sugar in rows:
        lines.append(" %s: %s" % (_meal_log_slot(slot, name, kcal), name))
        lines.append("  └ " + macro.format(kcal=_n(kcal), carb=_n(carb),
                                          protein=_n(protein), fat=_n(fat)))
    if sections is not None:
        sections.update(nutrient_lines)
    return lines, body_start, body_end


def nutrition_block(conn, date, *, variant, lang=None, today=None, snapshot=None):
    """Structured, localized sections and text from one typed snapshot.

    full/body retain the approved card layout. target/summary are review-only
    candidates until their wording is selected; production adapters retain
    existing copy while consuming snapshot facts.
    """
    from nutrition_snapshot import NutritionBlock
    if variant not in ('full', 'body', 'retro', 'summary', 'target'):
        raise ValueError('unknown nutrition variant: ' + str(variant))
    global _i18n
    saved = _i18n
    if lang:
        _i18n = lambda key, fallback="": _i18n_lang(key, lang, fallback)
    try:
        snapshot = snapshot or nutrition_snapshot(conn, date)
        if snapshot.date != str(date):
            raise ValueError('nutrition snapshot date does not match requested date')
        sections = {}
        lines, a, b = _meal_card_parts(conn, date, today, snapshot=snapshot, sections=sections)
        sections.update({'header': tuple(lines[:a-1]), 'body': tuple(lines[a:b]),
                    'log': tuple(lines[b+1:]),
                    'formula': tuple(_meal_card_formula(snapshot.target))
                               if snapshot.target else ()})
        if variant == 'full':
            text = "\n".join(lines)
        elif variant == 'retro':
            # Approved evening card: dated meal header and all nutrition rows,
            # without the separate food log. Consumers add one code fence.
            text = "\n".join(sections['header'] + ('',) + sections['body'])
        elif variant == 'body':
            text = "\n".join(sections['body'])
        else:
            # A concise review rendering reuses the identical target and bands.
            keys = ('kcal', 'protein', 'carb', 'fat') if variant == 'target' else ('kcal',)
            text = "\n".join(ln for key in keys for ln in sections[key])
        return NutritionBlock(snapshot, sections, text)
    finally:
        _i18n = saved


def meal_card_render(conn, date, today=None):
    return nutrition_block(conn, date, variant='full', today=today).text


def meal_card_body(conn, day, lang=None, today=None):
    return nutrition_block(conn, day, variant='body', lang=lang, today=today).text


def _emit_meal_card(conn, date, offer=False, *, snapshot=None, today=None):
    """The kit card after a meal write (and, once, the simple-target offer).
    Both agents use this renderer, including health-pack installations."""
    card = (nutrition_block(conn, date, variant='full', snapshot=snapshot, today=today).text
            if snapshot is not None else meal_card_render(conn, date, today)
            if today is not None else meal_card_render(conn, date))
    if card is None:
        return False
    if (offer and not meal_targets_set(conn)
            and _config_stored(conn, _MEAL_TARGET_OFFERED_KEY) is None):
        print("TARGET_OFFER\t%s" % _i18n(
            "meal.target.offer", "With a daily target set, I'll show how "
            "much you have left."))
        print("TARGET_BUTTON\t%s" % _i18n("meal.target.offer.set",
                                          "Set a target"))
        print("TARGET_BUTTON\t%s" % _i18n("meal.target.offer.skip",
                                          "Just log"))
        try:
            _config_put(conn, _MEAL_TARGET_OFFERED_KEY, now_utc())
            conn.commit()
        except sqlite3.Error:
            pass
        offered = True
    else:
        offered = False
    print(MEAL_CARD_BEGIN)
    print(card)
    print(MEAL_CARD_END)
    print(MEAL_CARD_RELAY)
    return 'offer' if offered else True


def cli_meal_satiety(argv):
    argv, occasion = _pop_opt(argv, '--occasion')
    # meal-satiety <date> <slot> [<token>|skip]
    # Once per eating occasion after its last item. With a token:
    # store the answer after the recorded meal card. The
    # close records an exact slot as a calibration sample and rescales an
    # estimated slot through the calibration when its cell is ready.
    if len(argv) < 2:
        _err("usage: kit_life.sh meal-satiety <YYYY-MM-DD> <slot> [%s|skip]"
             % "|".join(SATIETY_LEVELS))
    try:
        argv = list(argv)
        argv[1] = meal_slots.canonical(argv[1])
        import made_dish
        conn = get_conn()
        try:
            deferred = made_dish.defer_satiety(sys.modules[__name__], conn, argv[0], argv[1], argv[2] if len(argv) > 2 else None)
        finally:
            conn.close()
        if deferred:
            print(json.dumps(dict(status='PENDING_PORTION', next='Fullness retained. Keep the existing share question pending; after meal-add logs that share, its reply acknowledges fullness once. Do not ask again or send a separate acknowledgement.'), ensure_ascii=False))
            return
        res = meal_satiety(argv[0], argv[1], argv[2] if len(argv) > 2 else None, occasion=occasion)
    except ValueError as e:
        _err(str(e))
    st = res['status']
    print("SATIETY\t%s\t%s\t%s\t%s\t%s\t%s\t%s" % (
        res['date'], res['slot'], st, res.get('level') or '',
        res.get('resolved') or '',
        '' if res.get('grams') is None else _f0(res['grams']),
        '' if res.get('kcal') is None else _f0(res['kcal'])))
    if st in ('calibrated', 'not_ready'):
        cell = res['scope'] + ('(%s)' % res['band'] if res['scope'] == 'band'
                               else '')
        if st == 'calibrated':
            print("CALIBRATED\tfactor=%s\tgrams=%s->%s\tref=%s\tscope=%s"
                  "\tn=%d%s" % (res['factor'], _f0(res['est_grams']),
                                 _f0(res['grams']), _f0(res['ref_grams']),
                                 cell, res['n'],
                                 "\tclamped" if res.get('clamped') else ""))
        else:
            print("CALIB_NOT_READY\teffective_n=%.3f\tneed=%d\tscope=%s\tband=%s"
                  "\tanchor_weight=%.3f\tn=%d\tanchor_n=%d" % (
                res['effective_n'], res['need'], cell, res.get('band') or '',
                res['anchor_weight'], res['n'], res['anchor_n']))
            # Owner 2026-10-27: calibration progress is never shown in the
            # satiety reply (no readiness sentence, no weight fraction).
    if st == 'stored':
        print("SATIETY_CLOSE\tmeal-satiety %s %s" % (res['date'], res['slot']))
    if st == 'ask_portion':
        print('SATIETY_PORTION_ASK\t' + json.dumps(res['proposed'], ensure_ascii=False))
        print('SATIETY_PORTION_RELAY Ask the owner to confirm the estimated food portion '
              'before any correction. The fullness answer is stored; no food was changed. '
              'Use existing portion question copy; never relay machine tags or claim a correction.')
    if res.get('changed') or (res.get('answer_changed') and res.get('grams') is not None):
        conn = get_conn()
        try:
            _emit_meal_card(conn, res['date'])
        finally:
            conn.close()
    if res.get('reply'):
        print("SATIETY_REPLY\t%s" % res['reply'])
        print("SATIETY_REPLY_RELAY Relay the entire multiline SATIETY_REPLY once, "
              "verbatim, preserving one quote block per changed food (bold name, then a gram line and a kcal line). "
              "Never print SATIETY_* tags. "
              "Never invent portion or food-count advice from this feeling.")


def satiety_readiness_text(cell):
    return _i18n(
        'meal.satiety.readiness',
        "Calibration evidence {effective_n}/{need} (recent 'just right' answers count more)."
    ).replace('{effective_n}', '%.1f' % cell['effective_n']).replace(
        '{need}', str(cell['need']))


def cli_satiety_calib(argv):
    # satiety-calib [<as_of YYYY-MM-DD>]   READ ONLY: the calibration
    # reference per level (and per level x density band) with sample count
    # and newest/oldest sample date, so a drift is visible.
    as_of = datetime.date.today()
    if argv:
        as_of = _satiety_date(argv[0])
        if as_of is None:
            _err("usage: kit_life.sh satiety-calib [YYYY-MM-DD]")
    print("SATIETY_CALIB\tas_of=%s\twindow=%dd\thalf_life=%dd\tneed=%d" % (
        as_of.isoformat(), SATIETY_CALIB_WINDOW_DAYS,
        SATIETY_CALIB_HALF_LIFE_DAYS, SATIETY_CALIB_MIN_SAMPLES))
    for r in satiety_calibration_table(as_of):
        print("%s\t%s\tn=%d\tready=%d\tref_g=%s\tnewest=%s\toldest=%s"
              "\teffective_n=%.3f\tanchor_weight=%.3f\tanchor_n=%d" % (
            r['level'], r['band'] or 'all', r['n'], 1 if r['ready'] else 0,
            '' if r['ref_grams'] is None else _f0(r['ref_grams']),
            r['newest'] or '', r['oldest'] or '', r['effective_n'], r['anchor_weight'],
            r['anchor_n']))


def cli_meal_card(argv):
    # meal-card [--body] [<date>] -- shared read-only text card for every kit
    # agent; --body (any position) prints only the card body, no markers/log.
    body = "--body" in argv
    argv = [a for a in argv if a != "--body"]
    date = argv[0] if argv else datetime.date.today().isoformat()
    if len(argv) > 1 or not _DATE_RE.match(date):
        _err("usage: kit_life.sh meal-card [--body] [YYYY-MM-DD]")
    conn = get_conn()
    try:
        if body:
            print(meal_card_body(conn, date))
        else:
            _emit_meal_card(conn, date)
    finally:
        conn.close()


_TARGET_ASK_FIELDS = (("height_cm", "height", "cm"), ("weight_kg", "weight", "kg"),
                      ("age", "age", ""), ("sex", "sex", ""))


def _meal_target_known(conn):
    """[(field, label, shown value)] the kit already holds for the simple
    target (record-always-on readback: recorded facts are never re-asked)."""
    out = []
    for key, field, unit in _TARGET_ASK_FIELDS:
        v = _config_stored(conn, key)
        if v in (None, ""):
            continue
        shown = (_fmeas(_num(v, None)) + unit) if unit else (
            _i18n("meal.target.sex." + str(v), str(v)) if key == "sex"
            else str(v))
        out.append((field, _i18n("meal.target.field." + field, field), shown))
    return out


def cli_meal_target_ask(argv):
    # meal-target-ask   the one question the simple target needs (C3); the
    # values already recorded are read back (TARGET_KNOWN) and not asked again
    conn = get_conn()
    try:
        known = _meal_target_known(conn)
    finally:
        conn.close()
    if known:
        have = {f for f, _l, _v in known}
        missing = [_i18n("meal.target.field." + f, f) for _k, f, _u in
                   _TARGET_ASK_FIELDS if f not in have]
        missing.append(_i18n("meal.target.field.direction", "direction"))
        for field, label, shown in known:
            print("TARGET_KNOWN\t%s\t%s" % (field, shown))
        ask = _i18n("meal.target.ask_missing",
                    "I'll work out your daily target. Already recorded: "
                    "{known}.\n\nJust tell me: {missing}.").format(
            known=", ".join("%s %s" % (l, v) for _f, l, v in known),
            # ko topic particle after the last known value; empty elsewhere
            eun=(_josa(known[-1][2], "eun")
                 if agent_conf.conf_str('AGENT_LANG', 'en') == 'ko' else ""),
            missing=", ".join(missing))
        print("TARGET_ASK\t%s" % ask.replace("\n", "\\n"))
    else:
        print("TARGET_ASK\t%s" % _i18n(
            "meal.target.ask", "Tell me height, weight, age, sex and direction "
            "(lose / keep / gain).").replace("\n", "\\n"))
    print(_ask_choices().options_line("TARGET_ASK", "target", []))
    print("TARGET_RELAY Ask the TARGET_ASK text verbatim (a literal \\n is a "
          "line break). Answer -> meal-target-set height=<cm> weight=<kg> "
          "age=<years> sex=male|female direction=lose|keep|gain, a "
          "TARGET_KNOWN value passed as recorded (never asked). An InBody "
          "photo instead -> health-log first, then meal-target-set with "
          "what is still missing. Never print TARGET_* tags or this line.")


def meal_target_set(conn, height, weight, age, sex, direction):
    """Store the owner's numbers and derive the simple daily target through
    the kit's own model (_diet_target -> _persist_diet_target). Returns the
    card targets {kcal, carb, protein, fat}. Raises ValueError on bad input."""
    mode = _TARGET_DIRECTIONS.get(str(direction).strip().lower())
    sx = _TARGET_SEX.get(str(sex).strip().lower())
    if mode is None:
        raise ValueError("direction must be lose|keep|gain")
    if sx is None:
        raise ValueError("sex must be male|female")
    h, w, a = _num(height, None), _num(weight, None), _num(age, None)
    if not (h and 100 <= h <= 250):
        raise ValueError("height must be cm (100-250)")
    if not (w and 25 <= w <= 300):
        raise ValueError("weight must be kg (25-300)")
    if not (a and 10 <= a <= 110):
        raise ValueError("age must be years (10-110)")
    for k, v in (("height_cm", h), ("weight_kg", w), ("age", int(a)),
                 ("sex", sx)):
        _config_put(conn, k, v)
    result = _diet_target(conn, None, {"goal_mode": mode}, {})
    if not result or result.get("pending"):
        conn.rollback()
        raise ValueError("target could not be derived from the numbers given")
    _persist_diet_target(conn, result)
    # A new explicit simple-target choice supersedes an older pack consult.
    if _settled_diet_base(conn) is not None:
        _config_put(conn, 'calorie_target_kcal', result['kcal'])
        _config_put(conn, 'maintenance_mid', result['kcal'] - result['change'])
    _config_put(conn, "diet_target_source", "kit_simple")
    conn.commit()
    return meal_targets(conn, datetime.date.today().isoformat())


def cli_meal_target_set(argv):
    # meal-target-set height=<cm> weight=<kg> age=<y> sex=male|female
    #                 direction=lose|keep|gain
    usage = ("usage: kit_life.sh meal-target-set height=<cm> weight=<kg> "
             "age=<years> sex=male|female direction=lose|keep|gain")
    kv = {}
    for tok in argv:
        if "=" not in tok:
            _err(usage)
        k, v = tok.split("=", 1)
        kv[k.strip()] = v.strip()
    need = ("height", "weight", "age", "sex", "direction")
    if any(k not in kv for k in need):
        _err(usage)
    conn = get_conn()
    try:
        try:
            t = meal_target_set(conn, kv["height"], kv["weight"], kv["age"],
                                kv["sex"], kv["direction"])
        except ValueError as e:
            _err("meal-target-set: %s" % e)
        if t is None:
            _err("meal-target-set: target could not be read back")
        print("TARGET\t%s\t%s\t%s\t%s" % (int(round(t["kcal"])),
                                          int(t["carb"]), int(t["protein"]),
                                          int(t["fat"])))
        if not _emit_diet_consultation(conn, t["kcal"]):
            print("TARGET_LINE\t%s" % _i18n(
                "meal.target.done", "Your daily target is {kcal}kcal with "
                "{protein}g of protein.").format(kcal=_n(t["kcal"]),
                                                 protein=_n(t["protein"])))
            print("TARGET_RELAY Lead your reply with the TARGET_LINE text "
                  "verbatim, then the meal card (if any) as its relay says.")
        _emit_meal_card(conn, datetime.date.today().isoformat())
    finally:
        conn.close()


