def cli_meal_upd(argv):
    # meal-upd <id> field=value [field=value ...]
    # field: date meal name carb protein fat fiber sugar alt_sugar grams alcohol
    _u = ("사용법: kit_life.sh meal-upd <id> field=value [field=value ...]\n"
          "  field: date meal name carb protein fat fiber sugar alt_sugar grams alcohol\n"
          "  지정한 필드만 바뀐다(부분 수정). kcal은 자동 재계산.")
    argv, portion_options = _portion_options(argv)
    if not argv or not str(argv[0]).isdigit():
        _err(_u)
    fields = {}
    for tok in argv[1:]:
        if '=' not in tok:
            _err(f"field=value 형식이 아님: {tok}\n{_u}")
        col, val = tok.split('=', 1)
        col = col.strip()
        if col not in _MEAL_UPD_COLS:
            _err(f"수정 불가 컬럼: {col}\n{_u}")
        fields[col] = val
    if not fields and not any(v is not None for v in portion_options.values()):
        _err(_u)
    notices = _autolink_defer()      # record line first, AUTO-LINKED after
    try:
        row = meal_upd(argv[0], fields, **portion_options)
        if row is None:
            _err(f"해당 id 식단 없음: {argv[0]}")
        print(f"{row[0]}\t{row[1]}\t{_f0(row[2])}")
    finally:
        _autolink_flush(notices)
    _capture_candidates()  # correction: no fresh activity receipt


