def cli_foodcache_lookup(argv):
    # foodcache-lookup <name> [grams]
    # alias-resolve -> meal_food fetch -> scale to grams. TSV out; miss -> "NOTFOUND".
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh foodcache-lookup <name> [grams]")
    name = argv[0]
    grams = argv[1] if len(argv) > 1 and str(argv[1]).strip() != '' else None
    res = foodcache_lookup(name, grams=grams)
    if not res.get("found"):
        print(f"NOTFOUND\t{res.get('key','')}")
        sys.exit(EXISTS_CODE)
    # TSV: name grams kcal carb protein fat fiber sugar sodium_mg estimated source
    def _n(v):
        return '' if v is None else _f0(v) if float(v) == int(v) else f"{v}"
    print("\t".join([
        res["name"], _n(res.get("grams")), _n(res.get("kcal")),
        _n(res.get("carb")), _n(res.get("protein")), _n(res.get("fat")),
        _n(res.get("fiber")), _n(res.get("sugar")), _n(res.get("sodium_mg")),
        str(res.get("estimated", 0)), res.get("source") or ""]))


