def food_merge(loser, winner, conn=None):
    """Fold one meal_food row into another (owner-confirmed duplicate).

    One transaction: every alias pointing at the loser (by key or display name)
    is repointed to the winner; the loser's key and display name become aliases
    of the winner; the loser's default portion moves over when the winner has
    none (else it is dropped); the loser row is deleted.  Past meal records are
    untouched (they carry their own numbers, not a food key).
    Returns (loser_key, winner_key, aliases_written)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        lk, wk = normalize_food_key(loser), normalize_food_key(winner)
        lrow, wrow = _food_row(conn, lk), _food_row(conn, wk)
        if lrow is None:
            raise ValueError(f"no food row with key '{lk}'")
        if wrow is None:
            raise ValueError(f"no food row with key '{wk}'")
        if lk == wk:
            raise ValueError("loser and winner are the same row")
        lname = lrow[1] or lk
        by = _facade_agent()
        conn.execute(
            "UPDATE meal_alias SET canonical=?, updated_by=?, "
            "updated_at=datetime('now','localtime') "
            "WHERE canonical IN (?, ?);", (wk, by, lk, lname))
        written = 0
        for a in dict.fromkeys((lk, lname)):
            if a == wk:
                continue
            conn.execute(
                "INSERT INTO meal_alias (alias, canonical, updated_by, updated_at) "
                "VALUES (?,?,?, datetime('now','localtime')) "
                "ON CONFLICT(alias) DO UPDATE SET canonical=excluded.canonical, "
                "updated_by=excluded.updated_by, "
                "updated_at=datetime('now','localtime');", (a, wk, by))
            written += 1
        # An alias equal to the winner's own key is a self-loop (lookup finds
        # the key first anyway). The winner's display name is NOT one: lookup
        # is by key, so "<display name>" still needs its alias to resolve.
        conn.execute("DELETE FROM meal_alias WHERE alias=? AND canonical=?;",
                     (wk, wk))
        has_w = conn.execute("SELECT 1 FROM meal_portion WHERE key=?;",
                             (wk,)).fetchone()
        if has_w:
            conn.execute("DELETE FROM meal_portion WHERE key=?;", (lk,))
        else:
            conn.execute("UPDATE meal_portion SET key=? WHERE key=?;", (wk, lk))
        conn.execute("DELETE FROM meal_food WHERE key=?;", (lk,))
        conn.commit()
        return lk, wk, written
    except Exception:
        conn.rollback()
        raise
    finally:
        if own:
            conn.close()


