def cli_targets(argv):
    """targets --burn N → eff_goal bmr neat deficit protein_goal (공백구분 한 줄).

    2.20.0: when any of those numbers came from DEFAULT_STATS instead of the
    owner's stored measurements, a SECOND line follows saying so. The first
    line is untouched -- daily-retro.sh reads it with `read -r ... <<<`, which
    consumes only the first line of the here-string, so every existing caller
    parses exactly what it parsed before and a human running the verb by hand
    now sees whose body the numbers describe."""
    p = argparse.ArgumentParser(prog='kit_life.sh targets', add_help=False)
    # 064 / ticket 2026-09-02 D3: --burn omitted no longer means 0 (a rest
    # day); it means "read that day's burn" (--date, default today).  A caller
    # that wants the burn-free baseline passes --burn 0.
    # Owner 2026-10-18/19: calibrated exercise increases the daily target.
    p.add_argument('--burn', type=float, default=None)
    p.add_argument('--date', default=None)
    p.add_argument('--json', action='store_true')
    ns, _ = p.parse_known_args(argv)
    day = ns.date or datetime.date.today().isoformat()
    conn = get_conn()
    try:
        stats = body_stats_for_conn(conn)
        t = targets_for_date(day, stats=stats, conn=conn, burn_override=ns.burn)
        m = resolve_macro_goals(t['eff_goal'], stats, _macro_day_type(conn, day))
        m['macro_bands'] = _meal_macro_bands(conn, t['eff_goal'], date=day)
    finally:
        conn.close()
    if ns.json:
        print(json.dumps({'date': day, 'targets': t, 'macros': m},
                         ensure_ascii=False, default=str))
        return
    print(f"{t['eff_goal']} {t['bmr']} {t['neat']} {t['deficit']} "
          f"{m['protein'] if m['protein'] is not None else ''}")
    warn = body_stats_fallback_line(stats, macros=m)
    if warn:
        print(warn)


def diet_consultation_text(conn, kcal):
    """First target explanation, using the card's base bands (before intake).

    Returns Telegram HTML, already escaped once. Callers relay it verbatim;
    this text is never appended to a meal card.
    """
    from html import escape
    stats = body_stats_for_conn(conn)
    result = resolve_macro_goals(kcal, stats)
    bands = result.get('macro_bands')
    if not bands:
        return ''
    base = bands['base_bands']
    profile = _macro_profile(kcal, stats)
    manual = (profile['protein_mode'] in ('manual', 'stored_legacy')
              and 'manual_protein_outside_band' not in bands['issues'])
    values = dict(weight=_fmeas(stats['weight_kg']), kcal=_n(kcal),
                  protein=_fmeas(profile['explicit_protein_g']))
    for macro, band in base.items():
        values[macro + '_min'] = _fmeas(band['min'])
        values[macro + '_max'] = _fmeas(band['max'])
    address = os.environ.get('AGENT_ADDRESS')
    if address is None:
        address = agent_conf._raw('AGENT_ADDRESS') or ''
    values['address'] = escape(address.strip())
    values['i'] = _josa(address.strip(), 'i') if address.strip() else ''
    basis = 'manual' if manual else 'auto'
    values['protein_basis'] = _i18n('meal.consult.protein_' + basis).format(**values)
    body_basis = basis if address.strip() else 'auto'
    values['body'] = _i18n('meal.consult.body_' + body_basis).format(**values)
    return _i18n('meal.consult.explanation').format(**values)


def _emit_diet_consultation(conn, kcal):
    text = diet_consultation_text(conn, kcal)
    if text:
        print("TARGET_LINE\t%s" % text.replace("\n", "\\n"))
        print("TARGET_RELAY Relay TARGET_LINE verbatim as Telegram HTML; "
              "a literal \\n is a line break. Do not escape it again or "
              "put sources on the meal card. Never print TARGET_* tags.")
    return bool(text)


