def cli_appt_find(argv):
    # appt-find <date_from> [date_to] [--retro] [--weekly]
    argv, weekly = _pop_flag(argv, '--weekly')
    argv, retro = _pop_flag(argv, '--retro')
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh appt-find <date_from> [date_to]")
    g = lambda i: argv[i] if i < len(argv) else None
    # grill-final M-4: a malformed date (e.g. '2026-7-8') must be a loud
    # one-liner, not a strptime traceback. Regex-first, same as appt-add.
    for d in (argv[0], g(1)):
        if d is not None and not _DATE_RE.match(d):
            _err(f"bad date format (want YYYY-MM-DD): {d}")   # E-find-badfmt
    # 052: end and people appended as cols 5-6 (existing consumers reading
    # cols 1-4 by position are unaffected).
    # retro-read-paths: retro_line appended as col 7 (existing consumers
    # reading cols 1-6 by position are unaffected).
    conn = event_conn()
    try:
        found = False
        for aid, col2, title, location, end, people, retro_line in appt_find(
                argv[0], g(1), conn=conn, retro=retro, weekly=weekly):
            found = True
            related = _related_shopping(conn, title, aid)
            extra = "\t" + " | ".join(related) if related else ""
            print(f"{aid}\t{col2 or ''}\t{title}\t{location or ''}"
                  f"\t{end or ''}\t{people}\t{retro_line}" + extra)
        if found:
            # Keep TSV stdout stable for scripts; tool users also see stderr.
            print(APPT_CONTEXT_RELAY, file=sys.stderr)
    finally:
        conn.close()


# -- appointment place: unset vs undecided (2026-09-30) ----------------------
# The agent should ask for the place when booking; if it is undecided the
# user says so. Two different facts used to share one empty column:
#   location NULL/''     -> UNSET: nobody asked yet. Every write card of the
#                           appointment says 장소 미입력 and the verb prints
#                           PLACE_UNSET + PLACE_ASK, so the question is owed
#                           by the mechanism, not by skill prose.
#   location '미정'       -> UNDECIDED: the owner answered "not decided yet".
#                           Recorded, rendered 장소 미정, never asked again,
#                           and never treated as a venue (no place mint, no
#                           travel signal, not a place-gap).
# The token is the owner's own word; the few spellings he may use collapse to
# it at write time so every reader compares one string.
APPT_PLACE_UNDECIDED = u"\ubbf8\uc815"                       # 미정
_APPT_PLACE_UNDECIDED_SPELLINGS = frozenset((
    u"\ubbf8\uc815", u"\uc7a5\uc18c\ubbf8\uc815", "tbd"))      # 미정 / 장소미정
# SQL guard for the venue-driven lanes (travel sweep, place-gap). Writers
# normalize, so the canonical token is the only stored spelling.
_SQL_LOCATION_NOT_UNDECIDED = "AND TRIM(location) <> '%s' " % APPT_PLACE_UNDECIDED


def _normalize_appt_location(location):
    """Undecided spellings -> APPT_PLACE_UNDECIDED; anything else unchanged."""
    if location is None:
        return None
    key = location.replace(" ", "").strip().lower()
    if key in _APPT_PLACE_UNDECIDED_SPELLINGS:
        return APPT_PLACE_UNDECIDED
    return location


def _appt_split_address(location):
    """Keep the venue/room spelling; send a pasted address to place intake."""
    from place_location import split_location
    text = ' '.join(str(location or '').split())
    _label, _room, address = split_location(text)
    return (text[:-len(address)].rstrip(' ,'), address) if address else (location, '')


def _appt_save_address(conn, event_ulid, location, address):
    if not address:
        return
    row = appt_snapshot(conn, event_ulid)
    if (row is None or _travel_anchor_retired(conn, 'event', event_ulid)
            or travel_core.attendance_online(sys.modules[__name__], conn, row)):
        return
    past = bool(row.get('start_at') and row['start_at'] <= now_utc())
    place = _place_resolve_or_mint(conn, location, address=address,
                                   near_ok=past, emit_task=False)
    if place is None:
        return  # The resolution state retains the address for continuation.
    from place_location import split_location
    label, _room, _address = split_location(location)
    if _resolve_location_place(conn, location) is None:
        travel_place_upd(conn, place['id'], {
            'aliases': _near_json_list(place.get('aliases')) + [label]})
    row = place_address_add(conn, place['id'], address, primary=True)
    print('place-address\t%s\t%s\t%s\t%s' % (
        place['id'], row['kind'], row['is_primary'], _travel_signal_field(row['value'])))


def _location_is_undecided(location):
    return (location is not None
            and _normalize_appt_location(location) == APPT_PLACE_UNDECIDED)


def _appt_place_unset_ids(conn, ids, removed_ids=()):
    """The ids (in the order given) that are LIVE appointments with no
    location at all -- not a venue, not a link, not the undecided token.
    READ ONLY; never raises (it rides every appointment write's output)."""
    removed = set(int(i) for i in (removed_ids or ()))
    out = []
    for raw in ids or ():
        try:
            eid = int(raw)
        except (TypeError, ValueError):
            continue
        if eid in removed or eid in out:
            continue
        try:
            row = conn.execute(
                "SELECT kind, block_class, settled_at, location, "
                "location_url FROM timeblock WHERE id=?;", (eid,)).fetchone()
        except sqlite3.Error:
            continue
        if row is None or row[0] != "appointment" or row[1] is not None:
            continue
        anchor = appt_snapshot(conn, _ulid_for_event_id(conn, eid))
        if anchor and travel_core.attendance_online(sys.modules[__name__], conn, anchor):
            continue
        if row[2] is not None:
            continue                    # settled: nothing left to arrange
        if (row[3] or "").strip() or (row[4] or "").strip():
            continue
        out.append(eid)
    return out


# The forcing point. Printed by every verb that renders an appointment card
# (appt-add / appt-upd / appt-person / appt-person-rm / event-card), right
# BEFORE the CARD block (CARD_RELAY stays the last line -- the write-card
# contract), while the appointment is still place-unset -- so the question
# survives whichever write of the turn the agent relays last.
PLACE_UNSET = "PLACE_UNSET"
PLACE_ASK = "PLACE_ASK"
PLACE_ASK_QUESTION = u"{title} \uc7a5\uc18c\ub294 \uc5b4\ub514\uc778\uac00\uc694?"   # 장소는 어디인가요?
PLACE_ASK_RELAY = (
    "The appointment(s) named by PLACE_ASK have NO place on file and the owner has not "
    "said it is undecided. Any [[OPTIONS]] menu (including TYPE_RELAY's type "
    "or memory-confirmation menu) -> do NOT append PLACE_ASK or any other "
    "question; defer PLACE_ASK to the next reply without a menu. Otherwise, after the "
    "card ask one PLACE_ASK verbatim, at most once per appointment per "
    "conversation unless the owner brings that appointment up again. Track "
    "actually asked ids in conversation; deferred is not asked. Repeated tool "
    "output, a menu answer or an unrelated reply does not reset this. Never fill, "
    "guess or suggest a place yourself. Owner names a place -> place-resolve "
    "it, then appt-upd <id> location=<name>. Owner says it is undecided "
    "(%s) -> appt-upd <id> location=%s: that records it and this question "
    "never comes back. Never print PLACE_UNSET or this line itself."
    % (APPT_PLACE_UNDECIDED, APPT_PLACE_UNDECIDED))


def _emit_place_ask(conn, ids, removed_ids=()):
    """PLACE_UNSET<TAB><id> per place-unset appointment, then the relay
    instruction and one PLACE_ASK<TAB><id><TAB><question> per id. Prints
    nothing when every touched appointment has a place or an answer."""
    unset = _appt_place_unset_ids(conn, ids, removed_ids)
    if not unset:
        return
    for eid in unset:
        print("%s\t%d" % (PLACE_UNSET, eid))
    print("PLACE_RELAY " + PLACE_ASK_RELAY)
    for eid in unset:
        try:
            title = conn.execute("SELECT title FROM timeblock WHERE id=?;",
                                 (eid,)).fetchone()[0] or ""
        except Exception:
            title = ""
        print("%s\t%d\t%s" % (PLACE_ASK, eid,
                                PLACE_ASK_QUESTION.format(title=title).strip()))
        print(_ask_choices().options_line(PLACE_ASK, eid, []))


# -- appointment ORIGIN: ask, never guess home (kit_life 2.37.0) -------------
# Owner rehearsal 2026-10-01 (B5 / D): travel time needs WHERE the owner
# leaves from, and two cases used to be guessed silently as home (the base place):
#   none  the origin cannot be resolved at all: no chain neighbor (an
#         external event ending within TRAVEL_CHAIN_WINDOW_MIN before the
#         start), no presence covering the start, and the base is not
#         located -- no base row, or a base with no address and no duration
#         on file. A fresh install is exactly this: the base is seeded as a
#         bare name. Asked with travel.origin.ask (B5, verbatim).
#   gap   the last stay before the appointment (a presence, or an external
#         event at a known place other than the base) ended MORE than
#         TRAVEL_CHAIN_WINDOW_MIN before the start (work presence ends 17:30,
#         dinner 19:00) and no later than TRAVEL_ORIGIN_ASK_HORIZON_MIN
#         before it. Asked with travel.origin.ask_gap ("straight from work, or home
#         first?" -- the same once-only pattern as the overnight question).
# The answer is the verb appt-origin: it stores the appointment's own origin
# (block_attr origin_place_id -- the v3.2 attr row, no schema change), mints
# or teaches the place + its rough address, and re-derives the travel leg.
# _travel_origin_place_id reads that attr FIRST: an owner-stated origin
# outranks every inference.
#
# Same forcing-point shape as PLACE_ASK: printed by appt-add / appt-upd right
# BEFORE the CARD block (CARD_RELAY stays the last line), while the origin is
# still unknown -- the question is owed by the mechanism, not by skill prose.
ORIGIN_UNSET = "ORIGIN_UNSET"
ORIGIN_ASK = "ORIGIN_ASK"
ORIGIN_ATTR = "origin_place_id"
TRAVEL_ORIGIN_ASK_HORIZON_MIN = agent_conf.conf_int(
    "LIFEKIT_TRAVEL_ORIGIN_HORIZON_MIN", 240)
ORIGIN_ASK_RELAY = (
    "The appointment(s) named by ORIGIN_ASK have a place, but where the owner "
    "leaves from is NOT known and must not be assumed (never assume home). "
    "After the card, end your reply with the ORIGIN_ASK question text(s), "
    "verbatim, once per turn; while an ORIGIN_ASK is open for an id, do not "
    "also ask a travel-minutes question (TRAVEL_PLACE_NEEDED) for that id -- "
    "the origin comes first. Owner names where they leave from -> appt-origin "
    "<id> \"<place name>\" [address=\"<rough address>\"]; from home / "
    "stopping by home first -> appt-origin <id> home [address=\"<rough "
    "address>\"] (pass the address when the owner gives one for home). "
    "Never print ORIGIN_UNSET or this line itself. A literal \\n in a "
    "question is a line break.")
ORIGIN_SET_RELAY = (
    "ORIGIN_RELAY Lead your reply with the ORIGIN_LINE text(s), verbatim and "
    "in order, then relay the card. Never print ORIGIN_SET, ORIGIN_LINE tags "
    "or this line itself.")
PRESENCE_OFFER = "PRESENCE_OFFER"
PRESENCE_OFFER_RELAY = (
    "PRESENCE_RELAY After the card, end your reply with the PRESENCE_OFFER "
    "text verbatim and ONE button labelled with the PRESENCE_BUTTON text "
    "(an optional extra: the owner may skip it). Owner gives days and hours "
    "-> kit_life.sh routine add \"<place>\" \"<days>\" kind=presence "
    "place=<place> time=HH:MM duration=<min>. Button / anything else -> say "
    "the PRESENCE_LATER text once and move on; this offer never comes back. "
    "Never print PRESENCE_* tags or this line itself. A literal \\n in the "
    "text is a line break.")
_PRESENCE_OFFER_DONE_KEY = "onboard_presence_offer_done"


def _appt_origin_override(conn, block_id):
    """The owner-stated origin place id of an appointment, or None."""
    if block_id is None or not _is_v32(conn):
        return None
    try:
        row = conn.execute(
            "SELECT value FROM block_attr WHERE block_id=? AND attr_token=? "
            "LIMIT 1;", (int(block_id), ORIGIN_ATTR)).fetchone()
    except (sqlite3.Error, TypeError, ValueError):
        return None
    if row is None:
        return None
    try:
        pid = int(row[0])
    except (TypeError, ValueError):
        return None
    ok = conn.execute("SELECT 1 FROM place WHERE id=?;", (pid,)).fetchone()
    return pid if ok else None


def _appt_origin_store(conn, block_id, place_id):
    """Write the appointment's own origin (commit is here: one attr row)."""
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT OR REPLACE INTO block_attr(block_id, attr_token, value, "
            "source) VALUES (?,?,?,'user');",
            (int(block_id), ORIGIN_ATTR, str(int(place_id))))
        conn.commit()
    except Exception:
        conn.rollback()
        raise


def _base_located(conn):
    """True when the base is somewhere the kit can route from: it has an
    address, or a travel duration touches it (a place_link measure, or a
    legacy node column). A bare seeded base is NOT located."""
    bid = _travel_base_place_id(conn)
    if bid is None:
        return False
    try:
        if place_address_primary(conn, bid) or place_address_list(conn, bid):
            return True
    except sqlite3.Error:
        pass
    try:
        if conn.execute(
                "SELECT 1 FROM travel_edge WHERE (from_place_id=? OR "
                "to_place_id=?) AND minutes IS NOT NULL LIMIT 1;",
                (bid, bid)).fetchone():
            return True
    except sqlite3.Error:
        pass
    try:
        if conn.execute(
                "SELECT 1 FROM place WHERE to_min IS NOT NULL OR "
                "from_min IS NOT NULL LIMIT 1;").fetchone():
            return True
    except sqlite3.Error:
        pass
    return False


def _travel_last_stay_place_id(conn, anchor):
    """The place of the last stay that ended in the GAP window
    [start - TRAVEL_ORIGIN_ASK_HORIZON_MIN, start - TRAVEL_CHAIN_WINDOW_MIN),
    most recent first: a presence row (its own place), or an external event
    at a resolved place. A stay the owner finished counts (settled 'done');
    an abandoned one does not. None when no stay ended there."""
    at = anchor.get("start_at")
    if at is None:
        return None
    hi = _iso_shift_min(at, -TRAVEL_CHAIN_WINDOW_MIN)
    lo = _iso_shift_min(at, -TRAVEL_ORIGIN_ASK_HORIZON_MIN)
    cands = _travel_rows(
        conn,
        "SELECT id, ulid, kind, location, recurrence_id, block_class, "
        "derived_from, end_at, place_id FROM timeblock "
        "WHERE (settled_at IS NULL OR settled_outcome='done') "
        "AND end_at IS NOT NULL AND end_at >= ? AND end_at < ? "
        "AND id != ? AND block_class IS NULL "
        "ORDER BY end_at DESC;",
        (lo, hi, anchor["id"]))
    for ev in cands:
        if ev.get("kind") == "presence" and ev.get("place_id") is not None:
            return ev["place_id"]
        if _travel_external(conn, ev):
            pid = _travel_external_place_id(conn, ev)
            if pid is not None:
                return pid
    return None


def appt_origin_need(conn, eid, now=None):
    """None when the appointment's origin is known (or no trip exists), else
    ('none', None) or ('gap', <stay place id>). READ ONLY; never raises."""
    try:
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (int(eid),))
        if (anchor is None or anchor.get("kind") != "appointment"
                or not _travel_anchor_eligible(anchor)):
            return None
        if travel_core.attendance_online(sys.modules[__name__], conn, anchor):
            return None
        if anchor["start_at"] <= (now or now_utc()):
            return None                     # past: no trip left to plan
        loc = anchor.get("location")
        if (not loc or _location_is_undecided(loc)
                or _location_link_kind(loc) == "virtual"):
            return None
        dest = anchor.get("place_id")
        if dest is None:
            place = _resolve_location_place(conn, loc)
            dest = place["id"] if place is not None else None
        if dest is None:
            return None                     # venue unread: PLACE/TRAVEL asks own it
        base = _travel_base_place_id(conn)
        if dest == base:
            return None
        if _appt_origin_override(conn, anchor["id"]) is not None:
            return None
        # Rule 1 of the outing model: a leg that follows the previous leg of
        # its own bundle moves with the outing -- its origin is that leg's
        # place however long the gap, so there is nothing to ask.
        if _travel_bundle_neighbour(conn, anchor, "prev") is not None:
            return None
        if _travel_chain_origin_place_id(conn, anchor) is not None:
            return None
        kind, _pid, _rid = presence_at(conn, anchor["start_at"],
                                       exclude_event_id=anchor["id"])
        if kind == "presence":
            return None
        stay = _travel_last_stay_place_id(conn, anchor)
        if stay is not None and stay != base and stay != dest:
            return ("gap", stay)
        if not _base_located(conn):
            return ("none", None)
        return None
    except Exception:
        return None


def _origin_when(conn, start_at, now=None):
    """today / tomorrow / the weekday (within a week) / M/D(dow) -- the day
    the appointment falls on, in the owner's words (travel.origin.when.*)."""
    tz = _day_tz(None, _card_tz_offset())
    try:
        d = (datetime.datetime.strptime(start_at, "%Y-%m-%dT%H:%M:%SZ")
             .replace(tzinfo=timezone.utc).astimezone(tz).date())
        today = (datetime.datetime.strptime(now or now_utc(),
                                            "%Y-%m-%dT%H:%M:%SZ")
                 .replace(tzinfo=timezone.utc).astimezone(tz).date())
    except (TypeError, ValueError):
        return ""
    days = [w.strip() for w in _i18n("day.card.weekdays",
                                     "Mon,Tue,Wed,Thu,Fri,Sat,Sun").split(",")]
    dow = days[d.weekday()] if len(days) == 7 else ""
    delta = (d - today).days
    if delta == 0:
        return _i18n("travel.origin.when.today", "today")
    if delta == 1:
        return _i18n("travel.origin.when.tomorrow", "tomorrow")
    if 1 < delta < 7:
        return _i18n("travel.origin.when.weekday", "{dow}").format(dow=dow)
    return _i18n("travel.origin.when.date", "{md} ({dow})").format(
        md="%d/%d" % (d.month, d.day), dow=dow)


def origin_ask_question(conn, eid, need, now=None):
    """The finished question for one appointment (i18n, owner copy)."""
    row = conn.execute("SELECT title, start_at FROM timeblock WHERE id=?;",
                       (int(eid),)).fetchone()
    title, start_at = (row[0] or "", row[1]) if row else ("", None)
    if need[0] == "gap":
        return _i18n("travel.origin.ask_gap",
                     "Will you go straight from {place}, or stop by home "
                     "first?").format(place=_place_name(conn, need[1]))
    return _i18n("travel.origin.ask",
                 "{when} {title}: roughly where will you leave from, and its "
                 "address?").format(
        when=_origin_when(conn, start_at, now=now), title=title).strip()


def _ask_choices():
    """ask_choices.py (073 closed-choice contract), imported on first use."""
    if SCRIPT_DIR not in sys.path:
        sys.path.insert(0, SCRIPT_DIR)
    import ask_choices
    return ask_choices


def origin_ask_choices(conn, need):
    """[(key, label)] for a 'gap' ORIGIN_ASK: straight from the stay's place
    (place:<id>, its registry name) or home first (home). [] for 'none'."""
    if not need or need[0] != "gap" or need[1] is None:
        return []
    name = _place_name(conn, need[1])
    return [("place:%d" % need[1], _i18n(
                "travel.origin.choice.from", "Straight from {place}").format(
                place=name)),
            ("home", _i18n("travel.origin.choice.home", "Home first"))]


def _emit_origin_ask(conn, ids, now=None):
    """ORIGIN_UNSET<TAB><id><TAB><none|gap> per appointment whose origin is
    unknown, then the relay instruction and one ORIGIN_ASK<TAB><id><TAB>
    <question> per id. Prints nothing when every origin is known."""
    need = []
    for raw in ids or ():
        try:
            eid = int(raw)
        except (TypeError, ValueError):
            continue
        n = appt_origin_need(conn, eid, now=now)
        if n is not None and eid not in [e for e, _ in need]:
            need.append((eid, n))
    if not need:
        return
    for eid, n in need:
        print("%s\t%d\t%s" % (ORIGIN_UNSET, eid, n[0]))
    print("ORIGIN_RELAY " + ORIGIN_ASK_RELAY)
    opts = []
    for eid, n in need:
        try:
            q = origin_ask_question(conn, eid, n, now=now)
        except Exception:
            q = ""
        # 073 ask-choices: the gap question is closed (the stay's place or
        # home first) -- its choices come from the place registry and ride
        # the token line, with the exact [[OPTIONS]] marker after it. The
        # 'none' question asks for a place + address: open, no choices.
        choices = origin_ask_choices(conn, n)
        tail = ("\t" + _ask_choices().choices_field(choices)) if choices \
            else ""
        print("%s\t%d\t%s%s" % (ORIGIN_ASK, eid, q.replace("\n", "\\n"),
                                tail))
        opts.append(_ask_choices().options_line(ORIGIN_ASK, eid, choices))
    for line in opts:
        print(line)
    if opts:
        print(_ask_choices().RELAY)


def _origin_place_label(conn, place_id, address):
    """'<name>(<address>)' + the ko object particle of the last word, or
    'name (address)' in en -- the {place} of travel.origin.remembered."""
    name = _place_name(conn, place_id)
    ko = agent_conf.conf_str("AGENT_LANG", "en") == "ko"
    if address:
        label = ("%s(%s)" if ko else "%s (%s)") % (name, address)
        tail = address
    else:
        label, tail = name, name
    return label + (_josa(tail, "reul") if ko else "")


def cli_clash_answer(argv):
    argv, expected_ask = _pop_opt(argv, '--ask')
    if len(argv) != 2:
        _err("usage: kit_life.sh clash-answer <block> <cancel|move|keep>")
    import owner_clash
    conn = event_conn()
    try:
        owner_clash.answer(sys.modules[__name__], conn, *argv, expected_ask=expected_ask)
    except ValueError as e:
        _err(str(e))
    finally:
        conn.close()


def _travel_origin_resolve(conn, eid):
    """Resolve a missing stated-origin edge now; only this connection writes it."""
    import subprocess
    anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?", (eid,))
    origin = _appt_origin_override(conn, eid)
    dest = _travel_stop_place_id(conn, anchor) if anchor else None
    if origin is None or dest is None or origin == dest or _travel_edge_get(conn, origin, dest):
        return
    script = os.path.join(_kit_root(), 'routines', 'bundle', 'travel-resolve.sh')
    if not os.path.isfile(script):
        return
    env = dict(os.environ, TRAVEL_DB=os.path.abspath(DB_PATH),
               LIFEKIT_SH=os.path.join(SCRIPT_DIR, 'kit_life.sh'))
    try:
        result = subprocess.run(['bash', script, '--lookup-only',
            _place_name(conn, origin), _place_name(conn, dest)],
            env=env, capture_output=True, text=True, timeout=45)
        if result.returncode != 0:
            # Keep the repair instruction visible to the agent answering
            # appt-origin; other lookup failures remain best-effort.
            if result.returncode == 9:
                for line in result.stdout.splitlines():
                    if line.startswith('AGENT_BROWSER_MISSING\t'):
                        print(line)
                        break
            return
        for line in result.stdout.splitlines():
            fields = line.split('\t')
            if len(fields) >= 4 and fields[0] in ('RESOLVED', 'NEGLIGIBLE'):
                minutes = int(fields[3])
                if minutes >= 0:
                    travel_edge_add(conn, origin, dest, minutes)
                return
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return


def cli_appt_origin(argv):
    # appt-origin <id> <place|home> [address=<rough address>]
    #   The answer to ORIGIN_ASK: where the owner leaves from for THIS
    #   appointment. Mints/teaches the place (+ rough address), stores it as
    #   the appointment's origin, re-derives the travel leg, prints the card.
    #   lat= lng= [naver_ref=]: the map lookup's position for the place,
    #   stored with it (coordinates at registration, owner 2026-10-07 17:40).
    usage = ("usage: kit_life.sh appt-origin <id> <place|home> "
             "[address=<rough address>] [lat=D lng=D naver_ref=S]")
    if len(argv) < 2 or not str(argv[0]).isdigit() or not argv[1].strip():
        _err(usage)
    eid, name = int(argv[0]), argv[1].strip()
    address = None
    coord_kv = {}
    for tok in argv[2:]:
        if tok.startswith("address="):
            address = tok.split("=", 1)[1].strip() or None
        elif tok.split("=", 1)[0] in ("lat", "lng", "naver_ref", "coord_src"):
            k, v = tok.split("=", 1)
            coord_kv[k] = v.strip() or None
        else:
            _err(usage)
    conn = event_conn()
    try:
        if _read_appt_kind(conn, eid) != "appointment":
            _err(f"appt-origin: no appointment with id {eid}")
        if not _is_v32(conn):
            _err("appt-origin: this database predates the v3.2 block axis")
        base = _travel_base_place_id(conn)
        minted = False
        if name.lower() in ("home", "base"):
            if base is None:
                _err("appt-origin: no base place on file")
            pid = base
        else:
            if name.startswith("place:"):
                token = name.split(":", 1)[1]
                hit = conn.execute("SELECT name FROM place WHERE id=? AND status='active'", (token,)).fetchone()
                if not hit:
                    _err("appt-origin: unknown place token " + name)
                name = hit[0]
            place = _resolve_location_place(conn, name)
            if place is None:
                near = []
                try:
                    near = near_candidates(conn, "place", name)
                except Exception:
                    near = []
                if near:
                    _near_exit("place", name, near)
                try:
                    place = travel_place_add(conn, name)
                except ValueError as e:
                    _err(str(e))
                minted = True
            pid = place["id"]
        taught = False
        if address and pid is not None:
            have = place_address_primary(conn, pid)
            if not have:
                _place_address_write(conn, pid, address)
                taught = True
            elif have.strip() != address:
                place_address_add(conn, pid, address, primary=False)
        if coord_kv and pid is not None:
            _place_coord_from_kv(conn, pid, coord_kv)
        _before = appt_snapshot(conn, _ulid_for_event_id(conn, eid))
        _appt_origin_store(conn, eid, pid)
        _travel_origin_resolve(conn, eid)
        row = conn.execute("SELECT ulid, title, location FROM timeblock "
                           "WHERE id=?;", (eid,)).fetchone()
        ulid, title, location = row
        status, t_origin, t_dest = (appt_rederive(
            conn, ulid, before=_before).get("attach")
            or (TRAVEL_ATTACH_NONE, "", ""))
        print(f"{eid}\t{title}\t{_place_name(conn, pid)}")
        print("%s\t%d\t%d\t%s" % ("ORIGIN_SET", eid, pid,
                                   _place_name(conn, pid)))
        lines = []
        # A newly minted place, or an address newly taught to ANY place --
        # the base included ("home, near Mangwon" teaches the bare seeded
        # base where it is) -- is confirmed once. Re-stating a place the kit
        # already knew says nothing.
        if minted or taught:
            lines.append(_i18n("travel.origin.remembered",
                               "Got it, I'll remember {place}.").format(
                place=_origin_place_label(conn, pid, address)))
        # The departure line quotes the move leg's start (the helper's own
        # alert fires there) -- only once the leg is DERIVED from a real
        # duration. The 60-minute provisional stopgap is a guess, and a
        # departure time read off a guess is the guess restated as a fact.
        rule = _travel_rule_for_anchor_txn(conn, ulid, None)
        leg = None
        if rule is not None and rule.get("before_src") != TRAVEL_SRC_PROVISIONAL:
            leg = conn.execute(
                "SELECT id, start_at FROM timeblock WHERE block_class='travel' "
                "AND derived_from=? AND derived_role='before' "
                "AND settled_at IS NULL AND start_at > ? "
                "ORDER BY start_at LIMIT 1;", (ulid, now_utc())).fetchone()
        if leg is not None:
            tz = _day_tz(None, _card_tz_offset())
            lines.append(_i18n("travel.origin.depart_alert",
                               "I'll remind you to leave at {time}.").format(
                time=_day_hm(leg[1], tz)))
        for l in lines:
            print("ORIGIN_LINE\t%s" % l)
        if lines:
            print(ORIGIN_SET_RELAY)
        if status in _TRAVEL_ATTACH_NEEDS_ELICIT:
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                status, eid, _travel_signal_field(location), t_origin,
                t_dest))
        _emit_presence_offer(conn, pid, base)
        _emit_prep_default_ask(conn, eid)
        _print_cards(conn, [eid])
    finally:
        conn.close()


def _emit_presence_offer(conn, place_id, base_id):
    """B6: once, after the first travel card from a non-home origin -- offer
    to register the owner's regular stay there (presence routine). Optional
    extra: one 'later' button (travel.presence.later). Skipped when that place already has a
    presence routine. The flag is set when the offer is printed."""
    if place_id is None or place_id == base_id:
        return
    if _config_stored(conn, _PRESENCE_OFFER_DONE_KEY):
        return
    if not _manage_on(conn, 'module_routine'):
        return
    try:
        if conn.execute(
                "SELECT 1 FROM timeblock WHERE kind='presence' "
                "AND place_id=? LIMIT 1;", (place_id,)).fetchone():
            return
    except sqlite3.Error:
        return
    name = _place_name(conn, place_id)
    print("%s\t%s\t%s" % (PRESENCE_OFFER, name, _i18n(
        "travel.presence.offer",
        "If you're at {place} on set days and hours, tell me.").format(
            place=name).replace("\n", "\\n")))
    print("PRESENCE_BUTTON\t%s" % _i18n("travel.presence.later", "Later"))
    print("PRESENCE_LATER\t%s" % _i18n("travel.presence.later_ack",
                                       "Sure, just tell me whenever."))
    print(PRESENCE_OFFER_RELAY)
    try:
        _config_put(conn, _PRESENCE_OFFER_DONE_KEY, now_utc())
        conn.commit()
    except sqlite3.Error:
        pass


PREP_ASK = "PREP_ASK"
PREP_ASK_RELAY = (
    "PREP_RELAY After the card, end your reply with the PREP_ASK text "
    "verbatim, once (an optional answer: the owner may skip it; it is never "
    "asked again). Owner names minutes -> kit_life.sh config-set "
    "travel_prep_min=<minutes> (0 = no prep by default; the prep alert then "
    "leads every outing from home by that much). A different prep for ONE "
    "appointment -> travel-rule-upd <rule> prep_min=<minutes>, never the "
    "default. Never print PREP_ASK or this line itself. A literal \\n in "
    "the text is a line break.")
_PREP_ASK_DONE_KEY = "onboard_prep_default_asked"


def _emit_prep_default_ask(conn, eid):
    """Prep default, asked ONCE (owner 2026-10-06 07:28): the first time an
    appointment gets a move leg from home while no default prep is on file
    and its rule's prep is unset (_travel_rule_prep_unset), print the
    question. The flag is set when it is printed; an answer is
    config-set travel_prep_min=<min>. Best-effort: never raises."""
    try:
        if not _travel_prep_enabled(conn):
            return
        if (_config_stored(conn, TRAVEL_PREP_DEFAULT_KEY) is not None
                or _config_stored(conn, _PREP_ASK_DONE_KEY) is not None):
            return
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (int(eid),))
        if anchor is None or not anchor.get("ulid"):
            return
        rule = _travel_rule_for_anchor_row(conn, anchor)
        if rule is None or not _travel_rule_prep_unset(rule):
            return
        leg = conn.execute(
            "SELECT 1 FROM timeblock WHERE block_class='travel' "
            "AND derived_from=? AND derived_role='before' "
            "AND settled_at IS NULL AND start_at > ? LIMIT 1;",
            (anchor["ulid"], now_utc())).fetchone()
        base_id = _travel_base_place_id(conn)
        if leg is None or base_id is None or \
                _travel_leg_places(conn, "before", anchor)[0] != base_id:
            return
    except (sqlite3.Error, TypeError, ValueError):
        return
    print("%s\t%s" % (PREP_ASK, _i18n(
        "travel.prep.default_ask",
        "How long do you usually need to get ready before going out?"
        ).replace("\n", "\\n")))
    print(_ask_choices().options_line(PREP_ASK, eid, []))
    print(PREP_ASK_RELAY)
    try:
        _config_put(conn, _PREP_ASK_DONE_KEY, now_utc())
        conn.commit()
    except sqlite3.Error:
        pass


def _resolve_bundle_arg(conn, token):
    """`--in <event>`: an event id, or a title that names exactly ONE event
    (case-insensitive exact match -- no fuzzy pick for a write). Loud on a
    miss or an ambiguous title, BEFORE anything is written. None when the
    flag is absent."""
    if token is None:
        return None
    tok = str(token).strip()
    resolved = experience_resolve(conn, tok)
    if resolved is not None:
        return resolved[0]
    if tok.isdigit():
        # The id the agent sees on a card is a BLOCK id (owner 2026-10-07:
        # `presence-add ... --in 13066` on the housewarming appointment said
        # "no such event"). A live, non-derived block id means "the bundle
        # that block is in" -- made in the write's own txn when it has none.
        blk = conn.execute(
            "SELECT id, title, owning_agent FROM timeblock WHERE id=? "
            "AND settled_at IS NULL AND block_class IS NULL;",
            (int(tok),)).fetchone()
        if blk is None:
            _err(f"no such event: {tok}")
        return _BlockBundle(blk[0], blk[1], blk[2])
    tier, rows = event_find(conn, tok)
    if tier != "EXACT" or not rows:
        _err(f"no such event: {tok} (find it with experience-find, or "
             "pass its id)")
    if len(rows) > 1:
        _err("more than one event has the title %s -- pass the id (%s)"
             % (tok, ", ".join(str(r[0]) for r in rows)))
    return int(rows[0][0])


class _BlockBundle(object):
    """`--in <block id>`: the bundle of that block, resolved at insert time
    (its root event when it is in one, else a new event titled after it
    with the block linked as the first leg)."""

    def __init__(self, block_id, title, owning_agent):
        self.block_id = int(block_id)
        self.title = title or ""
        self.owning_agent = owning_agent

    def event_id(self, conn):
        """Inside the caller's txn: never commits (event_create does)."""
        row = conn.execute(
            "SELECT MIN(COALESCE(e.parent_id, e.id)) FROM event_timeblock et "
            "JOIN event e ON e.id = et.event_id WHERE et.timeblock_id=?;",
            (self.block_id,)).fetchone()
        if row and row[0] is not None:
            return int(row[0])
        cur = conn.execute(
            "INSERT INTO event (id, ulid, title, kind_hint, owning_agent) "
            "VALUES (?,?,?,?,?);",
            (next_event_id(conn), new_ulid(), self.title, "outing", self.owning_agent))
        conn.execute("INSERT OR IGNORE INTO event_timeblock (event_id, "
                     "timeblock_id) VALUES (?,?);",
                     (cur.lastrowid, self.block_id))
        return int(cur.lastrowid)


def _bundle_link_hook(event_id):
    """post_insert hook for `--in`: link the new leg to its bundle in the
    insert's own txn (the leg never exists unlinked)."""
    def _hook(conn, eid):
        ev = (event_id.event_id(conn) if isinstance(event_id, _BlockBundle)
              else int(event_id))
        conn.execute("INSERT OR IGNORE INTO event_timeblock (event_id, "
                     "timeblock_id) VALUES (?,?);", (ev, int(eid)))
    return _hook


def _travel_refresh_bundle_neighbours(conn, block_id):
    """Rule 1 at write time: after a leg joins a bundle, its neighbouring
    legs re-derive now -- the previous one drops its return home, the next
    one its before leg. Best-effort; the nightly pass converges the rest."""
    try:
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (int(block_id),))
        if anchor is None:
            return
        state_conn = _travel_state_conn(None)
        for _dir in ("prev", "next"):
            sib = _travel_bundle_neighbour(conn, anchor, _dir)
            if (sib is not None
                    and _travel_rule_for_anchor_row(conn, sib) is not None):
                travel_refresh(conn, state_conn, sib["ulid"])
    except Exception:  # noqa: BLE001 -- never fail a write on a re-derive
        pass


def _routine_clash_after_appt(conn):
    import owner_clash
    owner_clash.discover(sys.modules[__name__], conn)


# Scheduling captures share one decision, including legacy appt-add callers.
# The caller supplies semantic judgment; owner data supplies routine structure.
# Legacy appt-add retains appointment intent when no self-activity data matches.
def _schedule_refuse(reason, title, *details):
    print("SCHEDULE_NEEDED\t%s\t%s%s" % (
        reason, title, "".join("\t" + str(d) for d in details)))
    raise SystemExit(9)


def _schedule_shape(conn, title, place=None, day=None, workout=False):
    """Read owner data only. No fuzzy routine pick or invented duration."""
    norm = lambda x: " ".join((x or "").split()).casefold()
    rows = _travel_rows(conn, "SELECT r.*, p.name AS place_name FROM routine_def r "
                        "LEFT JOIN place p ON p.id=r.place_id WHERE r.status='active' "
                        "AND r.kind='task'", ())
    if day:
        rows = [r for r in rows if r['start_date'] <= day
                and (not r['end_date'] or r['end_date'] >= day)]
    exact = [r for r in rows if norm(r['title']) == norm(title)]
    if not exact and workout:
        exact = [r for r in rows if norm(title).startswith(norm(r['title']) + ' -')]
    title_matches = exact
    if place:
        exact = [r for r in exact if norm(r['place_name']) == norm(place)]
        if not exact and title_matches:
            durations = {r['duration_min'] for r in title_matches}
            if len(durations) != 1 or any(r.get('admit_cmd') is not None for r in title_matches):
                _schedule_refuse('routine_ambiguous', title, *(r['id'] for r in title_matches))
            return dict(duration_min=next(iter(durations)), place_name=place, travel=None,
                        owning_agent=title_matches[0]['owning_agent'])
    # A workout title variant can reuse a workout routine at the stated place,
    # but a shared place alone never turns an unrelated activity into a workout.
    if not exact and place and workout:
        exact = [r for r in rows if norm(r['place_name']) == norm(place)
                 and r.get('action_kind') == 'workout'
                 and (not day or (r['start_date'] <= day and
                                  (not r['end_date'] or r['end_date'] >= day)))]
    if exact:
        shapes = {(r['duration_min'], r['place_id'], r['notify_policy'],
                   r['notify_lead_min'], r.get('admit_cmd')) for r in exact}
        rules = [_travel_row(conn, "SELECT * FROM travel_rule WHERE "
                             "anchor_type='def' AND anchor_ulid=? "
                             "ORDER BY id DESC LIMIT 1", (r['ulid'],)) for r in exact]
        travel_shapes = {tuple(rule.get(k) for k in (
            'status', 'place_id', 'before_min', 'after_min', 'prep_min',
            'before_src', 'after_src', 'prep_src')) if rule else None for rule in rules}
        if len(shapes) != 1 or len(travel_shapes) != 1:
            _schedule_refuse('routine_ambiguous', title, *(r['id'] for r in exact))
        out = dict(exact[0])
        out['travel'] = rules[0]
        return out
    # Known typical length means a stored owner fact, not a product-wide guess.
    # Use the most recent matching timed self activity, never appointments.
    rows = conn.execute("SELECT title, start_at, end_at, owning_agent FROM timeblock WHERE "
                        "kind='task' AND schedule_kind='timed' AND block_class IS NULL "
                        "AND start_at < end_at ORDER BY start_at DESC LIMIT 200").fetchall()
    minutes = None
    owner = None
    for name, start, end, owner in rows:
        if norm(name) == norm(title):
            minutes = int((datetime.datetime.fromisoformat(end.replace('Z', '+00:00')) -
                           datetime.datetime.fromisoformat(start.replace('Z', '+00:00'))).total_seconds() // 60)
            break
    if minutes is None and not workout:
        return None
    return dict(duration_min=minutes, place_name=place, travel=None,
                owning_agent=owner if minutes else (_health_agent_resolve()[0] if workout else None))


def _schedule_apply_task_shape(conn, row, start, end, shape, attendance=None):
    """The existing task/routine schedule and travel verbs own all mutation."""
    if attendance:
        result = timeblock_set_meta(conn, row['id'], row['version'], attendance)
        if result != MutationResult.APPLIED:
            _schedule_refuse('activity_attendance', row['title'], result)
        row = appt_snapshot(conn, row['ulid'])
    if row['start_at'] != start or row['end_at'] != end:
        result = routine_exception(conn, row['ulid'], ('timed', start, end))
        if result != 'applied':
            _schedule_refuse('activity_move', row['title'], result)
    if travel_core.attendance_online(sys.modules[__name__], conn, row):
        travel_core.attendance_repair(sys.modules[__name__], conn, row)
        return
    if not row.get('place_id') and shape.get('place_id'):
        _appt_stamp_place(conn, row, shape['place_id'])
    rule = shape.get('travel')
    existing_rule = _travel_rule_for_anchor_row(conn, row)
    if rule and rule['status'] == 'active' and not existing_rule:
        travel_rule_add(conn, 'event', row['ulid'], place_id=shape.get('place_id'),
                        **{k: rule[k] for k in (
                            'before_min', 'after_min', 'prep_min',
                            'before_src', 'after_src', 'prep_src')})


def _schedule_task_args(title, start, end=None, location=None, note=None,
                        notify=None, project=None, force_new=False, workout=False, attendance=None):
    """Use task-add's validation, duplicate guard, card, travel and outbox."""
    if _shape_of(start) != 'datetime':
        _schedule_refuse('activity_time', title)
    utc = _to_canonical_utc(start)
    local = datetime.datetime.fromisoformat(utc.replace('Z', '+00:00')).astimezone(
        ZoneInfo('Asia/Seoul'))
    args = [title, local.date().isoformat(), note or '', '--at', local.strftime('%H:%M')]
    for key, value in (attendance or {}).items():
        args += ['--' + key.replace('_', '-'), value]
    if end:
        if _shape_of(end) != 'datetime':
            _err('start and end must be the same shape (both datetime or both date)')
        end_utc = _to_canonical_utc(end)
        validate_interval(utc, end_utc)
        minutes = int((datetime.datetime.fromisoformat(end_utc.replace('Z', '+00:00')) -
                       datetime.datetime.fromisoformat(utc.replace('Z', '+00:00'))).total_seconds() // 60)
        if minutes <= 0:
            _schedule_refuse('activity_duration', title, '--dur')
        args += ['--dur', str(minutes)]
    if location:
        args += ['--place', location]
    if notify:
        args += ['--notify', notify]
    if project:
        args += ['--project', project]
    if force_new:
        args += ['--new']
    if not force_new:
        conn = event_conn()
        try:
            shape = _schedule_shape(conn, title, location, local.date().isoformat(), workout)
            if shape is not None:
                old = _travel_rows(conn, "SELECT id,created_by FROM timeblock WHERE "
                                   "kind='appointment' AND title=? AND settled_at IS NULL "
                                   "AND block_class IS NULL AND start_at>=? AND start_at<?",
                                   (title, _to_canonical_utc(local.date().isoformat() + ' 00:00'),
                                    _to_canonical_utc((local.date() + timedelta(days=1)).isoformat() + ' 00:00')))
                for legacy in old:
                    cli_schedule_migrate([str(legacy['id']), '--owner', legacy['created_by'], '--title', title])
                matches = _travel_rows(conn, "SELECT * FROM timeblock WHERE kind='task' "
                                       "AND block_class IS NULL AND settled_at IS NULL "
                                       "AND title=? AND start_at>=? AND start_at<?",
                                       (title, _to_canonical_utc(local.date().isoformat() + ' 00:00'),
                                        _to_canonical_utc((local.date() + timedelta(days=1)).isoformat() + ' 00:00')))
                if not matches and not old:
                    args += ['--new']  # another day's activity is not this occurrence
                if len(matches) == 1:
                    row = matches[0]
                    minutes = (int((datetime.datetime.fromisoformat(end_utc.replace('Z', '+00:00')) -
                                    datetime.datetime.fromisoformat(utc.replace('Z', '+00:00'))).total_seconds() // 60)
                               if end else shape.get('duration_min'))
                    target_end = _iso_shift_min(utc, minutes or 0)
                    if location and location != shape.get('place_name'):
                        _schedule_refuse('activity_place', title, 'task-reschedule')
                    task_meta = dict(attendance or {})
                    if location and (task_meta.get('attendance_mode') == 'online'
                                     or task_meta.get('meeting_url')):
                        task_meta['location'] = location
                    _schedule_apply_task_shape(conn, row, utc, target_end, shape, task_meta)
                    _outbox_enqueue_best_effort(row['ulid'])
                    _print_cards(conn, [row['id']])
                    return row['id']
        finally:
            conn.close()
    return cli_task_add(args, _workout=workout)


def cli_schedule_migrate(argv):
    """Migrate future legacy workout appointments via task-add + appt-cancel.

    Explicit owner and exact training title bound this repair. A people-bearing
    or explicitly booked row is never migrated. Replacement is created first;
    a failed cancellation compensates through task cancellation, so the owner
    cannot lose the original event on a failed task write.
    """
    argv, owner = _pop_opt(argv, '--owner')
    argv, title = _pop_opt(argv, '--title')
    if not owner or not title or (argv and not all(a.isdigit() for a in argv)):
        _schedule_refuse('migration_scope', title or '', '--owner|--title')
    conn = event_conn()
    try:
        rows = _travel_rows(conn, "SELECT * FROM timeblock WHERE kind='appointment' "
                            "AND title=? AND created_by=? AND settled_at IS NULL "
                            "AND block_class IS NULL AND start_at>? ORDER BY id",
                            (title, owner, now_utc()))
    finally:
        conn.close()
    for row in rows:
        if argv and str(row['id']) not in argv:
            continue
        conn = event_conn()
        try:
            people = conn.execute('SELECT 1 FROM event_persons WHERE event_id=? LIMIT 1',
                                  (row['id'],)).fetchone()
            groups = conn.execute('SELECT 1 FROM event_group WHERE event_id=? LIMIT 1',
                                  (row['id'],)).fetchone()
            evidence = conn.execute("SELECT 1 FROM block_attr WHERE block_id=? "
                                    "AND attr_token='schedule_appointment'", (row['id'],)).fetchone()
            shape = _schedule_shape(conn, title, row.get('location'),
                                    str(_local_date_of(row['start_at'], 'Asia/Seoul')))
            if people or groups or evidence or shape is None:
                print('SCHEDULE_MIGRATE_SKIPPED\t%s' % row['id'])
                continue
            if not shape.get('duration_min'):
                _schedule_refuse('duration', title, '--dur|--end')
        finally:
            conn.close()
        local = datetime.datetime.fromisoformat(row['start_at'].replace('Z', '+00:00')).astimezone(
            ZoneInfo('Asia/Seoul'))
        args = [title, local.date().isoformat(), row.get('summary') or '',
                '--at', local.strftime('%H:%M'), '--dur', str(shape['duration_min']), '--new']
        if row.get('location'):
            args += ['--place', row['location']]
        if row.get('project_id'):
            args += ['--project', str(row['project_id'])]
        if row.get('notify_policy'):
            policy = row['notify_policy']
            args += ['--notify', str(row['notify_lead_min']) if policy == 'custom' else policy]
        probe = event_conn()
        try:
            lo, hi = all_day_instants(local.date().isoformat())
            candidates = _travel_rows(probe, "SELECT * FROM timeblock WHERE kind='task' "
                                      "AND title=? AND block_class IS NULL AND settled_at IS NULL "
                                      "AND start_at>=? AND start_at<?", (title, lo, hi))
            if len(candidates) > 1:
                _schedule_refuse('migration_ambiguous', title, *(r['id'] for r in candidates))
            admitted_start = row['start_at']
            if shape.get('admit_cmd') is not None:
                import routine_admission
                admitted = routine_admission.admit(
                    probe, shape, local.date().isoformat(), row['start_at'],
                    _iso_shift_min(row['start_at'], shape['duration_min']), 'timed',
                    source='schedule-migrate', exclude=[row['id']] + [r['id'] for r in candidates])
                if admitted is None:
                    continue
                admitted_start, admitted_end, _sk = admitted
                placed = datetime.datetime.fromisoformat(admitted_start.replace('Z', '+00:00')).astimezone(
                    ZoneInfo('Asia/Seoul'))
                minutes = int((datetime.datetime.fromisoformat(admitted_end.replace('Z', '+00:00')) -
                               datetime.datetime.fromisoformat(admitted_start.replace('Z', '+00:00'))).total_seconds() / 60)
                args[args.index('--at') + 1] = placed.strftime('%H:%M')
                args[args.index('--dur') + 1] = str(minutes)
            else:
                admitted_end = _iso_shift_min(row['start_at'], shape['duration_min'])
            attendance = travel_core.attendance_details(probe, row)
            for key, value in attendance.items():
                if value is not None:
                    args += ['--' + key.replace('_', '-'), value]
            if row.get('location') and travel_core.attendance_online(sys.modules[__name__], probe, row):
                attendance['location'] = row['location']
            created = not candidates
            if candidates:
                replacement = candidates[0]['id']
                _schedule_apply_task_shape(probe, candidates[0], admitted_start,
                                           admitted_end, shape, attendance)
                _outbox_enqueue_best_effort(candidates[0]['ulid'])
        finally:
            probe.close()
        if created:
            replacement = cli_task_add(args, _replacement=True)
        try:
            cli_appt_cancel([str(row['id'])])
        except BaseException:
            if not created:
                raise
            c = event_conn()
            try:
                version = c.execute('SELECT version FROM timeblock WHERE id=?',
                                    (replacement,)).fetchone()[0]
                cancel(c, replacement, version, _facade_agent())
            finally:
                c.close()
            raise
        print('SCHEDULE_MIGRATED\t%s\t%s' % (row['id'], replacement))


def cli_schedule_add(argv):
    """Agent judgment selects kind; auto uses stored structure and typed signals."""
    return cli_appt_add(list(argv), _default_kind='auto')


def _appointment_end(start_at, end_at=None, runtime_min=None):
    """Timed appointments default to three hours (owner 2026-10-01)."""
    if end_at:
        return end_at
    return _iso_shift_min(start_at, runtime_min if runtime_min is not None else 180)


def cli_appt_add(argv, _default_kind='legacy'):
    # appt-add <title> <start_at> [end_at location purpose summary] [--new]
    #          [--notify <policy>] [--project <id|title>]  (DGN-273 per-event
    #          override; project axis: attaches project_block at creation)
    #          [--in <event id|title>]  (2026-09-30: a leg of that outing)
    argv, force_new = _pop_flag(argv, '--new')      # DGN-231
    argv, notify_raw = _pop_opt(argv, '--notify')   # DGN-273
    argv, project_raw = _pop_opt(argv, '--project')  # project axis: id or title
    argv, in_raw = _pop_opt(argv, '--in')           # outing model: bundle
    argv, booked = _pop_flag(argv, '--booked')      # errand gate: a booked time
    argv, appointment = _pop_flag(argv, '--appointment')
    argv, kind = _pop_opt(argv, '--kind')
    if kind not in (None, 'appointment', 'task', 'auto'):
        _err('--kind must be appointment|task|auto')
    kind = kind or _default_kind
    if kind == 'task' and (booked or appointment):
        _err('--kind task conflicts with --booked/--appointment')
    argv, people_raw = _pop_people_args(argv)
    argv, activity = _pop_opt(argv, '--activity')
    if activity not in (None, 'workout'):
        _schedule_refuse('activity_invalid', activity)

    argv, attendance_mode = _pop_opt(argv, '--attendance-mode')
    argv, meeting_url = _pop_opt(argv, '--meeting-url')
    try:
        travel_core.attendance_validate({"attendance_mode": attendance_mode, "meeting_url": meeting_url})
    except ValueError as e:
        _err(str(e))
    argv, place_address_hint = _pop_opt(argv, '--place-address')
    argv, title_alias = _pop_opt(argv, '--alias')
    argv, runtime_raw = _pop_opt(argv, '--runtime-min')
    runtime_min = None
    if runtime_raw is not None:
        if not runtime_raw.isascii() or not runtime_raw.isdigit() or int(runtime_raw) <= 0:
            _err(_i18n("schedule.runtime.invalid", "Runtime must be a positive number of minutes."))
        runtime_min = int(runtime_raw)
    if title_alias is not None and not title_alias.strip():
        _err(_i18n("schedule.alias.empty", "Enter the name you used for this item."))
    argv, room_vals = _pop_room_args(argv)          # 073: room per booking
    if len(argv) < 2 or not argv[0] or argv[0].lstrip().startswith('--') or not argv[1]:
        _err("사용법: kit_life.sh appt-add <title> <start_at> "
             "[end_at location purpose summary] "
             "[--notify default|silent|start_only|<lead-min>] "
             "[--project <id|title>] [--in <event id|title>] [--booked|--appointment] "
             "[people=<refs>] [--kind appointment|task|auto] [--activity workout] "
             "[--alias <owner shorthand>] [--runtime-min <minutes>] [--place-address <address>] "
             "[--attendance-mode online|in_person|unknown] [--meeting-url <URL>]")
    try:
        _np, _nl = parse_notify_arg(notify_raw)
    except ValueError as e:
        _err(str(e))
    g = lambda i: argv[i] if i < len(argv) else None
    title, start_raw = argv[0], argv[1]
    end_raw = g(2)
    location, purpose, summary = g(3), g(4), g(5)
    attendance = {key: value for key, value in (
        ('attendance_mode', attendance_mode), ('meeting_url', meeting_url)) if value is not None}
    # This boundary accepts the agent's understanding, independent of title words.
    # Attendance mode is independent of this decision.
    explicit_appt = kind == 'appointment' or booked or appointment or bool(people_raw and people_raw.strip())
    if kind == 'task' and people_raw:
        _err('--kind task conflicts with people=; use --kind appointment')
    if not explicit_appt:
        try:
            capture_day = (str(_local_date_of(_to_canonical_utc(start_raw), 'Asia/Seoul'))
                           if _shape_of(start_raw) == 'datetime' else start_raw[:10])
        except (ValueError, OverflowError) as exc:
            _err(str(exc))
        probe = event_conn()
        try:
            shape = _schedule_shape(probe, title, location, capture_day, activity == 'workout')
        finally:
            probe.close()
        if kind == 'task' or shape is not None:
            if in_raw or title_alias or room_vals or place_address_hint or purpose:
                _err('task capture options: use task-add or --kind appointment for appointment metadata')
            if runtime_min is not None and not end_raw:
                end_raw = _iso_shift_min(_to_canonical_utc(start_raw), runtime_min)
            if _shape_of(start_raw) == 'date':
                if end_raw or runtime_min is not None:
                    _err('date-only task capture uses one due date; use task-add')
                task_args = [title, start_raw, summary or '']
                for key, value in attendance.items():
                    task_args += ['--' + key.replace('_', '-'), value]
                for option, value in (('--place', location), ('--notify', notify_raw), ('--project', project_raw)):
                    if value:
                        task_args += [option, value]
                if force_new:
                    task_args += ['--new']
                return cli_task_add(task_args, _inherit_shape=True)
            return _schedule_task_args(title, start_raw, end_raw, location,
                                       summary, notify_raw, project_raw, force_new,
                                       activity == 'workout', attendance)
        if kind == 'auto':
            _schedule_refuse('kind', title,
                             '--kind appointment (people/booking/fixed external slot) | --kind task (self activity)')
        # Compatibility for installed skills and legacy appointment producers.
        explicit_appt = True

    s_shape = _shape_of(start_raw)
    if s_shape == "bad":
        _err(f"bad time format: {start_raw}")          # E-add-badfmt (A8)
    if runtime_min is not None and s_shape != "datetime":
        _err(_i18n("schedule.runtime.timed", "A runtime needs a timed appointment."))
    e_shape = _shape_of(end_raw) if end_raw else None
    if e_shape == "bad":
        _err(f"bad time format: {end_raw}")            # E-add-badfmt (A8)
    # MIN-2: mixed shape (datetime start + date-only end, or reverse) -> loud.
    if e_shape is not None and e_shape != s_shape:
        _err("start and end must be the same shape "
             "(both datetime or both date)")           # E-add-mixed (A5/A6)

    agent = _facade_agent()
    # grill-final M-4: every SDK ValueError becomes a loud one-liner (no
    # traceback): impossible calendar dates from _to_canonical_utc, reversed
    # intervals from validate_interval, etc.
    try:
        if s_shape == "date":
            # all_day (A3 single / A4 multi-day). E-add-reversed: date-only
            # reversed range is refused before instant derivation.
            if end_raw and end_raw < start_raw:
                raise ValueError(
                    "reversed interval refused: end %s < start %s"
                    % (end_raw, start_raw))
            schedule_kind = "all_day"
            start_at, end_at = all_day_instants(start_raw, end_raw)
        else:
            # Timed appointment; self-activity/task capture returned above.
            schedule_kind = "timed"
            start_at = _to_canonical_utc(start_raw)
            if end_raw:
                end_at = _to_canonical_utc(end_raw)
            else:
                end_at = _appointment_end(start_at, runtime_min=runtime_min)
    except (ValueError, OverflowError) as e:
        _err(str(e))                                   # E-add-badfmt / reversed
    if in_raw is not None and schedule_kind != "timed":
        _err("--in takes a timed row only (a leg is a time block)")

    # DEV-1 verdict: metadata rides the timeblock_add INSERT itself (single txn,
    # no crash window, no version bump at birth).
    meta = {}
    if attendance_mode is not None:
        meta["attendance_mode"] = attendance_mode
    if meeting_url:
        meta["meeting_url"] = meeting_url
    location = _normalize_appt_location(location)
    location, embedded_address = _appt_split_address(location)
    place_address_hint = place_address_hint or embedded_address
    if location is not None and location != "":
        meta["location"] = location
    if purpose is not None and purpose != "":
        meta["purpose"] = purpose
    if summary is not None and summary != "":
        meta["summary"] = summary

    conn = event_conn()
    # project axis: resolve --project (id or title) BEFORE any write -- an
    # unresolvable project is loud (_resolve_project_id) and must not leave
    # a half-written appointment behind. None when the flag is absent.
    party = _presence_people(conn, people_raw) if people_raw else []
    project_id = _resolve_project_id(conn, project_raw)
    # 073: a room= or a location residue of another kind (a group, a person)
    # is refused BEFORE anything is written (FIELD_KIND_REFUSED, exit 8).
    _room_kind_gate(conn, None, room_vals, location)
    _appt_add_ulid = None
    try:
        # --in resolves BEFORE any write, same as --project.
        bundle_id = _resolve_bundle_arg(conn, in_raw)
        if not force_new:
            # DGN-579 B4: unified find-first probe (T1 = the DGN-263
            # (local_date, title EXACT) appt key; T2/T3 catch cross-facet
            # duplicates). EXISTS + exit 3 contract preserved verbatim.
            local_date = _local_date_of(start_at, "Asia/Seoul").isoformat()
            _exists_gate(conn, title, local_date, _ff_appt_line)
        def after_insert(tx, block_id):
            if party:
                _presence_people_store(tx, block_id, party)
            if explicit_appt:
                tx.execute("INSERT INTO block_attr(block_id,attr_token,value,source) "
                           "VALUES (?,'schedule_appointment',?,'user')",
                           (block_id, 'booked' if booked else 'explicit'))
            if bundle_id is not None:
                _bundle_link_hook(bundle_id)(tx, block_id)
            if title_alias is not None:
                _noun_mod().block_alias_add(sys.modules[__name__], tx, block_id, [title_alias])

        try:
            eid = timeblock_add(conn, kind="appointment", title=title,
                            schedule_kind=schedule_kind, start_at=start_at,
                            end_at=end_at, open_ended=0,
                            owning_agent=agent, created_by=agent,
                            completion_rule="manual", meta=meta,
                            notify_policy=_np, notify_lead_min=_nl,
                            project_id=project_id,
                            post_insert=after_insert)
        except ValueError as e:
            _err(str(e))                               # M-4 loud, no traceback
        if eid is None:
            # DGN-579 B2 (locked decision 1): equal-priority exclusive
            # conflict -> structured CONFLICT listing so the agent can
            # PROMPT the user (not a bare error). Nothing was written.
            cee = _cand_eff_end(start_at, end_at, 0)
            _print_conflict_and_exit(conn, start_at, cee)  # E-add-slot (A7)
        _appt_add_ulid = _ulid_for_event_id(conn, eid)
        _appt_save_address(conn, _appt_add_ulid, location, place_address_hint)
        # DGN-623: presence-aware auto-attach of move/prep for a place-bearing
        # appt. Best-effort, inside the open conn/txn window so the derived
        # blocks ride the same handle. Failure never blocks the write.
        # The --in link is already committed with the row, so the attach
        # below sees a leg of its outing (Rule 1: no move after a sibling).
        _tstatus, _torigin, _tdest = _travel_autoattach_appt(
            conn, _appt_add_ulid, location, declared=True, address_hint=place_address_hint)
        if bundle_id is not None:
            _travel_refresh_bundle_neighbours(conn, eid)
        # The owner declared this appointment: its day re-chains, past legs
        # included (an appointment logged after the fact gets its legs and
        # its neighbours' legs follow it). No-op on a future day.
        _travel_rechain_declared_safe(conn, _appt_add_ulid)
        # owner 2026-10-19: a routine occurrence never sits on this
        # appointment (or its travel/buffer/prep): move or skip, say it once.
        _routine_clash_after_appt(conn)
        # DGN-579 B2b: single choke point -- primary line verbatim + the
        # mandatory MOVEMENT_OVERLAP notice on intersecting movement rows.
        _print_write_result(conn, eid, f"{eid}\t{title}")
        # 073: the room of THIS booking (room= or the room the location
        # named), after the place is attached.
        _appt_room_after_write(conn, eid, room_vals, location)
        # DGN-623: elicitation signal (machine-readable notice, exit stays 0 --
        # the write SUCCEEDED). The skill asks the one-turn question and then
        # registers the datum (travel-place-add / travel-edge-add) + re-attaches
        # via appt-travel-attach. edge_missing names BOTH origin and dest so the
        # skill asks a spatial question. If the skill does nothing, the
        # appointment simply carries no move/prep (silent-safe).
        if _tstatus in _TRAVEL_ATTACH_NEEDS_ELICIT:
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                _tstatus, eid, _travel_signal_field(location),
                _torigin, _tdest))
        # A past appointment: the pairs still missing minutes, for a silent
        # automatic resolve (no question). Nothing on a future one.
        _print_retro_resolve(conn, eid)
        # 2.37.0: where the owner leaves from, when it cannot be known.
        _emit_origin_ask(conn, [eid])
        _emit_prep_default_ask(conn, eid)
        # The confirmation card of what was just created (last, after every
        # machine line).
        _print_cards(conn, [eid])
        _capture_open_today(conn)  # may be a plan; no completion receipt
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _appt_add_ulid:
        _outbox_enqueue_best_effort(_appt_add_ulid)


# DGN-623 auto-attach outcome codes (machine-readable, stable strings the skill
# layer branches on; never localized).
TRAVEL_ATTACH_ATTACHED = "attached"        # rule minted + blocks derived
TRAVEL_ATTACH_EXISTS = "exists"            # a rule was already present (no-op)
TRAVEL_ATTACH_NONE = "none"                # no location on the appt (nothing to do)
TRAVEL_ATTACH_UNKNOWN_PLACE = "unknown_place"   # location not a registered place
TRAVEL_ATTACH_NO_DURATION = "no_duration"       # known place, no base duration
TRAVEL_ATTACH_EDGE_MISSING = "edge_missing"     # origin->dest edge not registered
TRAVEL_ATTACH_ERROR = "error"              # unexpected failure (swallowed)
TRAVEL_ATTACH_RETIRED = "retired"          # the owner retired this anchor's rule
TRAVEL_ATTACH_PAST = "past"                # already started: no trip to plan
# A location that is a LINK, split by what the link is FOR. Both used to come
# back 'unknown_place', which said "not a registered place" for two situations
# that need opposite handling -- and measured 2026-09-12 on the live DB, all
# four URL-locations were in one of the two:
#   704 https://naver.me/Ex4mpLe1      a venue the owner shared as a map link
#   975 https://naver.me/Ex4mpLe2      ditto
#   791 https://meet.google.com/...    a video call: there is nowhere to go
#   796 https://meet.google.com/...    ditto
TRAVEL_ATTACH_LINK_PLACE = "link_place"    # a MAP/unknown link: venue unread
TRAVEL_ATTACH_VIRTUAL_PLACE = "virtual_place"   # a meeting link: no travel EXISTS
# 2026-09-28: the venue text is not on file but LOOKS LIKE a place that is
# ("유디학동치과" vs "학동유디치과"). Nothing minted; the dest column carries
# the existing place's name for the one question "혹시 <dest>랑 같은 곳인가요?".
TRAVEL_ATTACH_NEAR_PLACE = "near_place"

# The outcomes that WARRANT a one-turn elicitation (ask the user for the missing
# duration, then register + re-attach). edge_missing carries origin AND dest so
# the skill asks "<origin>에서 <dest>까지 편도 몇 분?" (spatial-aware question).
#
# link_place is in here and virtual_place is deliberately NOT. A map link is a
# venue nobody has read yet -- exactly the resolvable one-turn question this
# set exists for ("여기 장소 이름이 뭐예요?"). A meet.google.com link is a
# FINISHED answer: the appointment has no physical destination, so there is
# nothing to derive and nothing to ask. Putting it in the elicit set would make
# the system ask about a video call every five minutes, forever.
#
# PUBLIC (no underscore): the mirror carried its own hand-copied duplicate of
# this tuple (_INBOUND_TRAVEL_NEEDS) and would have silently disagreed with the
# kit the moment a code was added here -- which is this commit.
# ── 050: the provisional stopgap ─────────────────────────────────────────
# Two rules that are both right collided (owner + code, both 2026-09-12):
#   owner  "장소 없으면 기본 1시간"  -- never leave me with no travel time.
#   code   never invent a duration; ask once (the TRAVEL_PLACE_NEEDED contract).
# A silent 60 picks the first and destroys the second: six months on, nothing
# can say whether that number was measured, declared, or guessed -- and an
# unmarked guess is indistinguishable from an answer, so the question is never
# asked again.
#
# So the 60 is STAMPED, and the stamp is a COLUMN, not a comment:
# before_src='provisional' (050 widened the travel_rule CHECK to accept it).
# Three consequences, all mechanical:
#   1. the owner gets a travel block instead of nothing;
#   2. the question is STILL owed -- the attach outcome is unchanged, so
#      TRAVEL_PLACE_NEEDED still prints and the sweep still counts it in
#      `needs`. The stopgap is not an answer and never reports as one;
#   3. `WHERE before_src='provisional'` IS the set to overwrite. The moment a
#      real place or edge resolves, the sweep rewrites the rule in place
#      (_travel_provisional_upgrade) -- deterministic verb-layer code, no model
#      discretion (D2), and no second mechanism: the same deriver, the same
#      rule row.
# A pre-050 database has no 'provisional' in its CHECK; the arm no-ops there
# and behaviour is byte-identical to 049.
TRAVEL_SRC_PROVISIONAL = "provisional"
TRAVEL_PROVISIONAL_MIN = agent_conf.conf_int(
    "LIFEKIT_TRAVEL_UNKNOWN_MIN", 60)   # owner's rule, 2026-09-12

TRAVEL_ATTACH_NEEDS_ELICIT = (TRAVEL_ATTACH_UNKNOWN_PLACE,
                              TRAVEL_ATTACH_NEAR_PLACE,
                              TRAVEL_ATTACH_LINK_PLACE,
                              TRAVEL_ATTACH_NO_DURATION,
                              TRAVEL_ATTACH_EDGE_MISSING)
_TRAVEL_ATTACH_NEEDS_ELICIT = TRAVEL_ATTACH_NEEDS_ELICIT


def _travel_anchor_retired(conn, anchor_type, anchor_ulid):
    """Did the owner RETIRE this anchor's travel rule and leave it retired?

    `travel-rule-retire` is the opt-out. It flips the rule to 'retired' and
    tombstones the future blocks -- and that used to be the end of it, because
    nothing ever re-ran attachment. This branch put attachment on a five-minute
    loop, and both existence checks are blind to a retired row: the event path
    asks for status='active' and the def path for status != 'retired', while
    idx_travel_rule_anchor is partial on status != 'retired' so the INSERT does
    not collide either. Net effect measured on a copy of the live DB: retire ->
    3 blocks cleaned -> ONE sweep later a fresh active rule and the identical 3
    blocks are back, pushed to the calendar by the outbox. Each retry left
    another retired row behind. The owner's opt-out silently stopped existing.

    So a retired rule is read as what it is -- an explicit "not this one" -- and
    auto-attach declines. Precedence matters: a NON-retired rule (active, or a
    'proposed' deferred offer) is a live decision and wins, so this only answers
    True when retired rows are ALL there is. An owner who changes their mind
    re-arms explicitly (`appt-travel-attach --force`, `routine-travel-attach
    --force`, or `travel-rule-add`); nothing automatic does it for them."""
    try:
        rows = conn.execute(
            "SELECT id, version, status FROM travel_rule WHERE anchor_type=? "
            "AND anchor_ulid=?;", (anchor_type, anchor_ulid)).fetchall()
    except sqlite3.Error:
        return False                    # best-effort, same grade as the hook
    anchor = appt_snapshot(conn, anchor_ulid)
    if anchor:
        rows = [r for r in rows if r[2] != "retired" or
                travel_core.attendance_owner_retired(conn, anchor, {"id": r[0], "version": r[1]})]
    return bool(rows) and all(r[2] == "retired" for r in rows)


def _travel_signal_field(text):
    """One TSV field of a machine-readable travel signal.

    TRAVEL_PLACE_NEEDED is parsed by column, and locations are free text the
    owner (or Google Calendar) typed -- measured 2026-09-11, blocks 704 and
    706 both store their venue with a TRAILING NEWLINE, which split the
    signal across two lines and put the origin/dest columns on a line of
    their own. A consumer reading column 4 got an empty string and the
    elicitation it was supposed to trigger never happened.

    This is _place_norm_name and nothing else, deliberately. The field is not
    just display: the skill copies it straight into the recovery verb
    (travel-place-add / travel-edge-add), so it IS a lookup key. When it had
    its own private reduction, the key it printed and the name the mint
    stored disagreed on any venue with an INTERNAL newline (block 924, block
    1025) -- feeding the signal back resolved to None and minted a SECOND
    place, hanging the edge on the wrong row so the appointment stayed
    no_duration and the owner was asked the same question every turn. One
    function now decides both."""
    return _place_norm_name(text)


def mirror_adopt_appt(conn, title, schedule_kind, start_at, end_at,
                      owning_agent, created_by, note=None, location=None):
    """gcal-inbound-absorb (dossier 1d option A) -- kit_life seam.

    The mirror's _adopt_foreign_calendar previously called timeblock_add DIRECTLY,
    which BYPASSED the _travel_autoattach_appt hook (that hook lives only in
    cli_appt_add). So an absorbed appointment silently got NO move/prep
    derivation -- the real bug. This seam is the single choke point that does,
    in ONE conn/txn window, exactly what the CLI appt-add path does for the
    agent route: (1) store the GCal location into event.location via the same
    meta INSERT, (2) run the presence-aware DGN-623 auto-attach so move/prep
    is derived, reusing the SAME deriver verbatim.

    Reuse ladder honored: no new derivation math, no new insert path -- it
    composes the existing timeblock_add + bypass_timeblock_add + _travel_autoattach_appt.

    Returns (eid, ulid, overlap_warn, travel) where:
      - overlap_warn is None on the normal guarded insert, or the bypass
        overlap string when the FG-1 slot-loss force-adopt lane was taken.
      - travel is {'status', 'origin', 'dest'} from _travel_autoattach_appt
        (status is a stable TRAVEL_ATTACH_* code; the mirror surfaces the
        elicit codes as an inbound_place_needed signal). travel is None when
        the appt carries no location (nothing to derive).
    NEVER raises for a derive failure (best-effort, silent-safe)."""
    if schedule_kind == 'timed':
        end_at = _appointment_end(start_at, end_at)
    meta = {}
    if location is not None and str(location) != "":
        meta["location"] = location
    overlap_warn = None
    eid = timeblock_add(conn, kind="appointment", title=title,
                    schedule_kind=schedule_kind, start_at=start_at,
                    end_at=end_at, open_ended=0, owning_agent=owning_agent,
                    created_by=created_by, completion_rule="all",
                    note=note, meta=(meta or None))
    if eid is None:
        # FG-1 slot loss: the owner's hand-made entry is reality -- force
        # adopt through the bypass lane (same ruling the mirror used before).
        # bypass_timeblock_add does not carry meta, so set location right after.
        eid, overlap_warn = bypass_timeblock_add(
            conn, kind="appointment", title=title,
            schedule_kind=schedule_kind, start_at=start_at, end_at=end_at,
            owning_agent=owning_agent, created_by=created_by, note=note)
        if location and eid is not None:
            _vr = conn.execute(
                "SELECT version FROM timeblock WHERE id=?;", (eid,)).fetchone()
            if _vr is not None:
                try:
                    timeblock_set_meta(conn, eid, _vr[0], {"location": location})
                except Exception:
                    pass   # best-effort: a location stamp failure is non-fatal
    ulid = _ulid_for_event_id(conn, eid)
    travel = None
    if location:
        status, origin, dest = _travel_autoattach_appt(conn, ulid, location)
        travel = {"status": status, "origin": origin, "dest": dest}
    return eid, ulid, overlap_warn, travel



def mirror_adopt_block(conn, kind, title, schedule_kind, start_at, end_at,
                       owning_agent, created_by, note=None, location=None):
    """Adopt a calendar entry through the SDK write path for its kind."""
    import kind_policy
    policy = kind_policy.get(conn, kind)
    if not policy["adoptable"]:
        raise ValueError("kind is not adoptable: %r" % kind)
    if policy["adopt_path"] == "appt":
        return mirror_adopt_appt(conn, title, schedule_kind, start_at, end_at,
                                 owning_agent, created_by, note, location)
    venue = location if location and _place_mintable_location(location) else None
    if policy["adopt_path"] == "presence":
        # A presence cannot exist without a place and a calendar sync has
        # nobody to ask: the one place mint that stays ungated (near_gate).
        place_id, _ = place_upsert(conn, venue or title, near_gate=False)
        result = presence_add(conn, title, place_id, start_at, end_at,
                              schedule_kind=schedule_kind,
                              owning_agent=owning_agent,
                              created_by=created_by, note=note)
        if result.get("status") != "inserted":
            return None, None, None, None
        return result["eid"], result["ulid"], None, None
    place_id = None
    if venue:
        try:
            place_id, _ = place_upsert(conn, venue)
        except NearMatchError:
            # Near an existing place and nobody to ask here: leave the block
            # unplaced rather than mint a twin. The travel attach on an
            # appointment raises the question (near_place) where one is owed.
            place_id = None
    eid = timeblock_add(conn, kind, title, schedule_kind,
                        start_at=start_at, end_at=end_at,
                        owning_agent=owning_agent, created_by=created_by,
                        note=note, place_id=place_id)
    overlap_warn = None
    if eid is None:
        eid, overlap_warn = bypass_timeblock_add(
            conn, kind=kind, title=title, schedule_kind=schedule_kind,
            start_at=start_at, end_at=end_at, owning_agent=owning_agent,
            created_by=created_by, note=note)
        if place_id is not None and eid is not None:
            _appt_stamp_place(conn, {"id": eid, "place_id": None}, place_id)
    ulid = _ulid_for_event_id(conn, eid)
    travel = None
    if policy["travel_attach"] and schedule_kind == "timed" and place_id:
        status, origin, dest = _travel_autoattach_appt(
            conn, ulid, _place_name(conn, place_id))
        travel = {"status": status, "origin": origin, "dest": dest}
    return eid, ulid, overlap_warn, travel


def _place_name(conn, place_id):
    """Canonical name of a place id, or '' when absent."""
    if place_id is None:
        return ""
    if _is_v32(conn):
        row = conn.execute(
            "SELECT COALESCE(l.display, p.token) FROM place p "
            "LEFT JOIN label l ON l.namespace='place' AND l.token=p.token "
            "AND l.lang='ko' WHERE p.id=?;", (place_id,)).fetchone()
        return row[0] if row else ""
    row = conn.execute("SELECT name FROM place WHERE id=?;",
                       (place_id,)).fetchone()
    return row[0] if row else ""


# ── place ROW from a venue STRING (the intake gap) ────────────────────────
# A place-bearing appointment has to end up with a place ROW, not just a
# string. _resolve_location_place is EXACT (canonical name or taught alias;
# runtime fuzzy matching is forbidden, 6), so the first time the owner names
# a venue it resolves to None -- and that used to be the end of the line:
# auto-attach returned unknown_place, the venue stayed free text in
# location, and nothing downstream had a row to hang a duration on. Every
# derived surface hangs off place_id, so this one miss silently disabled the
# whole travel/prep chain for that appointment. Measured 2026-09-11:
# 231 place-bearing appointments, exactly 1 with a place_id.
#
# The documented recovery could not run either. the schedule skill's SKILL.md
# tells the agent to ask for the address once and then call
# `travel-place-upd "<PLACE>" address=...` -- an UPDATE, against a place row
# that unknown_place guarantees does not exist.
#
# So mint the row here, at the ONE choke point every writer already shares.
# NO DURATIONS: the row is born with a name and nothing else, and the caller
# falls through to no_duration / edge_missing -- the RESOLVABLE elicit codes
# the skill's one-turn ask is written for. A guessed travel time that makes
# him late is worse than no travel block.

_PLACE_MINT_MAX_LEN = 120


def _location_text_shows(text):
    """Does a location with no place row render as its own text on a card?
    Name-shaped only (same shape gate as minting); the undecided token
    renders via its own i18n line, so it is excluded here."""
    return (bool(text) and not _location_is_undecided(text)
            and _place_mintable_location(text))


def _place_mintable_location(text):
    """Is this location string shaped like a VENUE NAME we may register?

    Conservative and about SHAPE only, never about content (a content
    judgement would be the fuzzy matching 6 forbids):
      - a bare URL is a link, not a name (the owner sometimes stores a
        naver.me short link as the location; block 704 does exactly that).
      - past _PLACE_MINT_MAX_LEN it is prose or a pasted blob, not a name.
    A non-mintable location returns the pre-existing unknown_place signal,
    so this predicate can only ever leave behaviour where it already was.

    Judged on the canonical whitespace form -- the same string that would be
    stored -- so a venue does not become mintable or not depending on how
    many newlines the calendar entry happened to carry."""
    t = _place_norm_name(text)
    if not t or len(t) > _PLACE_MINT_MAX_LEN:
        return False
    if _location_link_kind(t):
        return False
    return True


# ── a location that is a LINK ─────────────────────────────────────────────
# Refusing to mint a place out of a URL is right: a link is not a venue name
# and inventing one would be the fuzzy matching 6 forbids. What was wrong was
# stopping there. Sharing a naver/kakao map link IS how the owner names a
# venue -- measured 2026-09-12, a next-day appointment held nothing
# but `https://naver.me/Ex4mpLe1`, and the whole travel chain hangs off a
# place row that string can never produce. It reported `unknown_place` on
# every one of the 5-minute sweeps and nothing anywhere said a word.
#
# So the shape is CLASSIFIED instead of discarded. This function reads the
# host and nothing else -- it never fetches, never guesses a venue, and never
# writes. Turning a map link into a name + address needs the network, and the
# network lives in the skill layer (place-manage/map_search.py --link, which
# already drives naver through agent-browser). This side's only job is to say
# WHICH question is owed.
#
# These are the existing physical-map provider adapters. Remote attendance
# does not use a platform registry: a non-map event URL is a remote venue.
_MAP_LINK_HOSTS = (
    "naver.me", "map.naver.com", "place.naver.com", "m.place.naver.com",
    "kko.to", "map.kakao.com", "place.map.kakao.com", "kakaomap.com",
    "maps.google.com", "maps.app.goo.gl", "g.page",
    "maps.apple.com", "tmap.co.kr", "place.map.naver.com",
)


def _location_link_kind(text):
    """Bare event URL: known map adapter, otherwise a remote venue.

    Map URLs still need resolution to a physical destination before travel.
    No meeting-provider names or natural-language keywords participate.
    """
    t = _place_norm_name(text).lower()
    if not (t.startswith("http://") or t.startswith("https://")):
        return ""
    host = t.split("://", 1)[1].split("/", 1)[0].split("?", 1)[0]
    host = host.split("@")[-1].split(":", 1)[0].strip(".")
    if not host:
        return "other"
    def _is(hosts):
        return any(host == h or host.endswith("." + h) for h in hosts)
    if _is(_MAP_LINK_HOSTS):
        return "map"
    return "virtual"


def _place_resolve_or_mint(conn, location, near_out=None, near_ok=False, address=None, emit_task=True):
    """Venue text -> place row. Resolve first (exact name, then taught alias
    -- so a registered "한빛교회" carrying "가온한빛교회" as an alias is a HIT
    and is never re-minted). A new name must resolve on the map to a real
    address or coordinates before it can be saved.

    Returns the place dict, or None when the text is not mintable -- the
    caller then reports unknown_place exactly as it did before. Never raises:
    a mint failure degrades to the old signal, it does not fail the write.

    2026-09-28: a genuine miss that LOOKS LIKE a live place is not minted
    either. This is the exact path that minted "유디학동치과" beside
    "학동유디치과" (place 23 next to 20): the appointment then had no edge, got
    the 60-minute stopgap, and the owner was asked a question he had already
    answered. The candidates go into `near_out` (a list the caller passes) and
    None comes back; the caller reports near_place.

    near_ok=True skips that check: a PAST appointment's venue is minted as
    its own row even when it looks like one on file (owner 2026-10-05: a
    finished outing asks nothing; a later merge stays place-manage's)."""
    if _location_link_kind(location):
        return None
    from place_location import split_location
    raw_location = location
    location, _room, embedded = split_location(location)
    address = address or embedded or None
    place = _place_at_address(conn, address) or _resolve_location_place(conn, location)
    if place is not None:
        return place if travel_core.attendance_physical_place(sys.modules[__name__], conn, place) else None
    if not _place_mintable_location(location):
        return None
    import place_identity
    if place_identity.gate(sys.modules[__name__], conn, location, address):
        return None
    near = []
    try:
        if not near_ok:
            near = near_candidates(conn, "place", location)
    except Exception:
        near = []
    if near:
        if near_out is not None:
            near_out.extend(near)
        return _place_lookup_chain(conn, raw_location, address=address, saved_candidates=near, emit_task=emit_task)
    return _place_lookup_chain(conn, raw_location, address=address, emit_task=emit_task)


def _venue_query_parts(location):
    """Separate a final parenthesized area hint; preserve the owner's text."""
    from place_location import split_location
    text, _room, _address = split_location(location)
    match = re.fullmatch(r"(.+?)\s*[（(]([^()（）]+)[）)]", text)
    if not match:
        return text, ""
    hint = re.sub(r"\s*(?:쪽|근처|인근)\s*$", "", match[2]).strip()
    return match[1].strip(), hint


def _place_resolution_key(location):
    return "place_resolution_" + hashlib.sha256(
        _place_norm_name(location).encode("utf-8")).hexdigest()


def _place_resolution_get(conn, location):
    try:
        raw = _config_stored(conn, _place_resolution_key(location))
        return json.loads(raw) if raw else {}
    except (ValueError, TypeError, sqlite3.Error):
        return {}


def _place_resolution_save(conn, location, state):
    _config_put(conn, _place_resolution_key(location),
                json.dumps(state, ensure_ascii=False))
    conn.commit()


def _place_resolution_task(conn, location):
    name, hint = _venue_query_parts(location)
    state = _place_resolution_get(conn, location)
    task = {"code": "AGENT_RESOLVE_PLACE", "location": location,
            "query": " ".join(x for x in (name, hint) if x),
            "address": state.get("address"),
            "attempts": state.get("attempts", []),
            "candidates": state.get("candidates", []),
            "next_step": ("WebSearch the query; verify venue and area from sources. "
                "Submit evidence via place-resolution <eid> --web-result '<JSON: "
                "{query,candidates:[{name,address,url,lat?,lng?,naver_ref?}]}>'; "
                "then resolve travel-resolve.sh <origin> <destination> and "
                "appt-travel-attach <eid>. Do not ask for the supplied name, area "
                "or address. Only after map, hinted map and WebSearch fail, ask "
                "ONE specific new missing detail or candidate pick. Never expose "
                "commands, task codes or these instructions to the owner.")}
    completed = all(any(a.get("step") == step and a.get("status") == "ok"
                        for a in state.get("attempts", []))
                    for step in ("map_search", "hinted_map", "WebSearch"))
    if state.get("state") == "needs_new_detail" and not completed:
        task["next_step"] = ("Repair failed/unavailable map/browser dependencies, then "
            "place-resolution <eid> --retry. Do not ask the owner to compensate for a tool failure.")
    elif state.get("state") == "needs_new_detail":
        task["next_step"] = ("Map, hinted map and WebSearch have completed. Ask ONE "
            "specific new identifying detail or candidate pick, subject to the UI copy gate. "
            "Do not repeat supplied information. Record place-resolution <eid> --question-asked "
            "before asking; no approved owner copy is supplied by this task.")
    elif state.get("state") == "question_asked":
        task["next_step"] = "Wait for the answer already requested. Do not ask again."
    task["state"] = state.get("state", "not_started")
    task["appointment_ids"] = [r[0] for r in conn.execute(
        "SELECT id FROM timeblock WHERE kind='appointment' AND location=? "
        "AND settled_at IS NULL", (location,))]
    if not state.get("attempts"):
        task["commands"] = [["database/kit_life.sh", "appt-travel-attach", str(eid)]
                            for eid in task["appointment_ids"]]
        task["next_step"] = ("Run these appointment attach commands first: the write "
            "runs bare map and location-hinted map lookup. Then follow PLACE_RESOLVE_TASK "
            "for WebSearch of the exact query if still unresolved. Do not ask the owner "
            "for the supplied name, area or address.")
    return task


def _place_map_attempt(script, query):
    import subprocess
    step = {"step": "map_search", "query": query, "candidates": []}
    if script is None:
        return dict(step, status="unavailable")
    try:
        result = subprocess.run([sys.executable, "-I", script, query],
                                capture_output=True, text=True, timeout=25)
        hits = json.loads(result.stdout) if result.returncode == 0 else []
        if not isinstance(hits, list):
            raise ValueError("not a candidate list")
        return dict(step, status="ok" if result.returncode == 0 else "failed",
                    returncode=result.returncode,
                    candidates=[h for h in hits if isinstance(h, dict)][:5])
    except (OSError, ValueError, TypeError, subprocess.SubprocessError) as exc:
        return dict(step, status="failed", error=type(exc).__name__)


def _place_hinted_attempt(conn, name, hint):
    """The existing browser lookup, read-only until identity is established."""
    import subprocess
    script = os.path.join(_kit_root(), "routines", "bundle", "travel-resolve.sh")
    step = {"step": "hinted_map", "query": (hint + " " + name).strip(),
            "candidates": []}
    if not os.path.isfile(script):
        return dict(step, status="unavailable")
    env = dict(os.environ, TRAVEL_DB=_conn_db_file(conn),
               LIFEKIT_SH=os.path.join(SCRIPT_DIR, "kit_life.sh"))
    try:
        result = subprocess.run(["bash", script, "--coords-query", name] +
                                (["--hint", hint] if hint else []), env=env,
                                capture_output=True, text=True, timeout=55)
        step.update(status="ok" if result.returncode == 0 else "failed",
                    returncode=result.returncode, output=result.stdout.strip())
        if result.returncode == 1 and "no coordinates or candidates" in result.stdout:
            step["status"] = "ok"
        from place_location import split_location
        found = []
        for line in result.stdout.splitlines():
            fields = line.split("\t")
            if fields[0] == "COORD_CANDIDATE" and len(fields) >= 4:
                label, _room, address = split_location(fields[3])
                address = address or fields[3]
                # Autocomplete can append a repeated venue/category after
                # the road number and floor. Only that address belongs here.
                road = re.match(r'^(.+?(?:대로|로|길)\s+\d+(?:-\d+)?'
                                r'(?:\s+(?:지하\s*)?B?\d+(?:[-~]\d+)?(?:층|호))*)', address)
                if road:
                    address = road[1]
                step["candidates"].append({
                    "name": label if fields[2] == "장소" else fields[2],
                    "address": address})
            elif fields[0] == "COORD_FOUND" and len(fields) == 3:
                parts = fields[2].split(",")
                coord = _naver_ref_coord(fields[2])
                if coord and len(parts) == 5 and parts[2].strip():
                    found.append({"name": parts[2].strip(), "lat": coord[0],
                                  "lng": coord[1], "naver_ref": fields[2]})
        # The end names the selected POI; COORD_FOUND's second field only
        # echoes our query. Never accept a partial failure or ambiguous list.
        candidates = list({(h["name"], h["address"]): h
                           for h in step["candidates"]}.values())
        found = list({h["naver_ref"]: h for h in found}.values())
        if result.returncode == 0 and len(found) == 1 and len(candidates) <= 1:
            hit = found[0]
            if (_compact_name(hit["name"]) == _compact_name(name)
                    or (hint and len(candidates) == 1)):
                hit["address"] = candidates[0]["address"] if candidates else ""
                step["pick"] = hit
                step["candidates"] = [hit]
        return step
    except (OSError, subprocess.SubprocessError) as exc:
        return dict(step, status="failed", error=type(exc).__name__)


def _place_lookup_chain(conn, location, address=None, saved_candidates=(), emit_task=True):
    from place_location import split_location
    name, hint = _venue_query_parts(location)
    _label, _room, embedded = split_location(location)
    prior = _place_resolution_get(conn, location)
    address = address or embedded or prior.get("address") or None
    if (prior.get("attempts") and prior.get("state") in ("web_needed", "needs_new_detail", "question_asked")
            and (address == prior.get("address") or prior.get("question_asked_at"))):
        if address and address != prior.get("address"):
            prior["address"] = address
            _place_resolution_save(conn, location, prior)
        if emit_task:
            print("PLACE_RESOLVE_TASK\t" + json.dumps(_place_resolution_task(conn, location), ensure_ascii=False))
        return None
    attempts = [_place_map_attempt(_map_search_script(), address or name)]
    # A hint in the supplied venue is evidence to use, never discard it when
    # accepting an otherwise exact name in a different district.
    hits = attempts[0]["candidates"]
    compact = _compact_name(name)
    if (not address and not hits and attempts[0]["status"] == "ok"
            and compact and compact != name):
        attempts.append(_place_map_attempt(_map_search_script(), compact))
        hits = attempts[-1]["candidates"]
    exact = [h for h in hits if _compact_name(h.get("name")) == _compact_name(name)
             and (h.get("address") or (h.get("lat") is not None and h.get("lng") is not None))]
    pick = exact[0] if len(hits) == len(exact) == 1 and not hint and not saved_candidates else None
    if pick is None:
        attempts.append(_place_hinted_attempt(conn, name, hint))
        if not saved_candidates:
            pick = attempts[-1].get("pick")
    state = {"location": location, "name": name, "hint": hint, "address": address,
             "attempts": attempts,
             "candidates": list(saved_candidates) + [h for a in attempts for h in a["candidates"]],
             "saved_candidates": list(saved_candidates),
             "state": "resolved" if pick else "web_needed"}
    _place_resolution_save(conn, location, state)
    if pick:
        try:
            return _place_save_evidence(conn, location, pick)
        except (ValueError, TypeError, sqlite3.Error):
            pass
    if emit_task:
        print("PLACE_RESOLVE_TASK\t" + json.dumps(
            _place_resolution_task(conn, location), ensure_ascii=False))
    return None


def _place_save_evidence(conn, location, hit):
    """Use existing identity/alias/coordinate APIs; never mint a duplicate."""
    from place_location import split_location
    name, _hint = _venue_query_parts(location)
    label, _room, _address = split_location(location)
    supplied_address = _address or _place_resolution_get(conn, location).get("address")
    if supplied_address:
        hit = dict(hit, address=supplied_address)
    # Location readers strip pasted addresses before matching aliases.
    location_aliases = list(dict.fromkeys(x for x in (location, label) if x and x != name))
    place = _place_at_address(conn, hit.get("address")) or _resolve_location_place(conn, name)
    if place is None:
        place = travel_place_add(conn, name, aliases=location_aliases or None,
                                 address=hit.get("address"))
    else:
        changes = {}
        aliases = _near_json_list(place.get("aliases"))
        missing_aliases = [x for x in location_aliases if x not in aliases]
        if missing_aliases:
            changes["aliases"] = aliases + missing_aliases
        if hit.get("address") and not place.get("address"):
            changes["address"] = hit["address"]
        if changes:
            travel_place_upd(conn, place["id"], changes)
    if hit.get("lat") is not None and hit.get("lng") is not None:
        place_coord_store(conn, place["id"], hit["lat"], hit["lng"],
                          naver_ref=hit.get("naver_ref"), source="map_resolver")
    return place


def cli_place_resolution(argv):
    """Agent-only continuation. Evidence is bound to the current location."""
    if (not argv or not argv[0].isdigit() or len(argv) not in (1, 2, 3)
            or (len(argv) == 2 and argv[1] not in ("--question-asked", "--retry"))
            or (len(argv) == 3 and argv[1] != "--web-result")):
        _err("usage: place-resolution <eid> [--web-result '<query,candidates JSON>'|--question-asked|--retry]")
    conn = event_conn()
    try:
        row = _travel_row(conn, "SELECT * FROM timeblock WHERE id=? AND kind='appointment'", (int(argv[0]),))
        if not row or not row.get("location"):
            _err("place-resolution: appointment with location required")
        location = row["location"]
        state = _place_resolution_get(conn, location)
        if len(argv) == 2:
            if argv[1] == "--retry":
                if state.get("question_asked_at"):
                    _err("place-resolution: wait for the answer already requested; a retry must not erase the ask-once fact")
                _place_resolution_save(conn, location, {"address": state.get("address")})
                appt_rederive(conn, row["ulid"], before=row)
            else:
                tried = state.get("attempts", [])
                if (state.get("state") != "needs_new_detail" or
                        not all(any(a["step"] == step and a.get("status") == "ok" for a in tried)
                                for step in ("map_search", "hinted_map", "WebSearch"))):
                    _err("place-resolution: a question requires completed map, hinted map and WebSearch; dependency failure is agent work")
                state["state"] = "question_asked"
                state["question_asked_at"] = now_utc()
                _place_resolution_save(conn, location, state)
        if len(argv) == 3:
            evidence = json.loads(argv[2])
            if not isinstance(evidence, dict):
                _err("place-resolution: expected JSON object")
            task = _place_resolution_task(conn, location)
            if evidence.get("query") != task["query"] or not state.get("attempts"):
                _err("place-resolution: run appt-travel-attach for this location first; query must match")
            hits = evidence.get("candidates", [])
            if not isinstance(hits, list) or any(not isinstance(h, dict) or
                    not h.get("name") or not str(h.get("url", "")).startswith(("https://", "http://")) for h in hits):
                _err("place-resolution: each web candidate needs name and source URL")
            state["attempts"].append({"step": "WebSearch", "query": task["query"],
                                       "status": "ok", "candidates": hits})
            state["candidates"] = hits
            name, _hint = _venue_query_parts(location)
            exact = [h for h in hits if _compact_name(h["name"]) == _compact_name(name) and h.get("address")]
            if len(hits) == len(exact) == 1 and (not state.get("saved_candidates") or
                    _resolve_location_place(conn, name) is not None):
                place = _place_save_evidence(conn, location, exact[0])
                state.update(state="resolved", place_id=place["id"])
                _place_resolution_save(conn, location, state)
                result = appt_rederive(conn, row["ulid"], before=row)
                print("PLACE_RESOLUTION\t" + json.dumps({"state": state, "derive": result}, ensure_ascii=False))
                origin = _place_name(conn, _travel_origin_place_id(conn, appt_snapshot(conn, row["ulid"]))) or ""
                print("AGENT_RESOLVE_TRAVEL\t" + json.dumps({"id": row["id"], "origin": origin,
                    "destination": place["name"], "commands": [
                        ["bash", "routines/bundle/travel-resolve.sh", origin, place["name"]],
                        ["database/kit_life.sh", "appt-travel-attach", str(row["id"])]],
                    "next_step": "Run these commands silently. Never ask the owner to run a command."}, ensure_ascii=False))
                return
            state["state"] = "question_asked" if state.get("question_asked_at") else "needs_new_detail"
            _place_resolution_save(conn, location, state)
        print("PLACE_RESOLVE_TASK\t" + json.dumps(_place_resolution_task(conn, location), ensure_ascii=False))
    except (ValueError, TypeError) as exc:
        _err("place-resolution: " + str(exc))
    finally:
        conn.close()



def _appt_stamp_place(conn, anchor, place_id):
    """Write the resolved place onto the appointment row itself.

    place_id is the FK the derived surfaces read (place_render in the
    calendar title, _travel_external_place_id for chain origin, the
    task/appt place join). Auto-attach has always RESOLVED the place and
    then thrown the id away into a travel_rule, leaving the appointment
    row's own place_id NULL -- so the appointment never learned where it
    was.

    The location TEXT is the authority here, so a CHANGED location moves the
    FK with it. An earlier draft refused to overwrite a non-NULL place_id
    ("an owner-set FK wins") and that was measurably wrong: correcting an
    appointment's venue (`appt-upd <id> location=...`) then left the row
    pointed at the place minted from the OLD text -- the stale address while
    the surface said the new name. The guard bought nothing either: no verb
    lets the owner set an appointment's place_id by hand, so this resolver
    is the column's only author for kind='appointment'.

    Never bumps version: this is the derivation layer filling in a structural
    fact, not an owner edit, and a bump here would churn the mirror on every
    re-attach. Best-effort."""
    if anchor is None or place_id is None:
        return
    if anchor.get("place_id") == place_id:
        return
    try:
        conn.execute("BEGIN IMMEDIATE;")
        try:
            _tb_update(conn, anchor["id"], {"place_id": place_id})
            conn.commit()
        except Exception:
            conn.rollback()
            raise
    except Exception:
        pass


def _travel_provisional_supported(conn):
    """True iff travel_rule accepts before_src='provisional' (050+).

    Read off the stored CHECK text rather than off user_version: the pin is
    what an installer promises, the constraint is what the database will
    actually accept, and an IntegrityError inside a best-effort auto-attach is
    invisible. Fail-CLOSED -- unreadable schema means no arming."""
    try:
        row = conn.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' "
            "AND name='travel_rule';").fetchone()
    except sqlite3.Error:
        return False
    return bool(row) and "'provisional'" in (row[0] or "")


def _travel_provisional_arm(conn, event_ulid, place_id, existing):
    """Arm the stopgap: a rule carrying TRAVEL_PROVISIONAL_MIN, stamped
    before_src='provisional'.

    Existing declared/measured rules outrank a fresh guess. An earlier
    stopgap keeps its duration but follows a resolved, corrected venue.
    An unchanged or still-unresolved venue is a no-op on every sweep.
    place_id must be a resolved physical destination. A missing destination
    never receives a provisional duration.
    Returns True iff a rule was armed or retargeted. NEVER raises: this runs
    inside a best-effort attach, and a failed stopgap must not fail the attach."""
    if place_id is None or not _travel_provisional_supported(conn):
        return False
    if existing is not None:
        if (place_id is None
                or existing.get("before_src") != TRAVEL_SRC_PROVISIONAL
                or existing.get("place_id") == place_id):
            return False
        try:
            # This is derived venue metadata, not an owner rule edit.
            # travel_rule_upd would clear pins; keep those times intact.
            conn.execute("BEGIN IMMEDIATE;")
            cur = conn.execute(
                "UPDATE travel_rule SET place_id=?" + _TRAVEL_PREP_RELABEL_SQL +
                ", version=version+1, "
                "updated_at=? WHERE id=? AND version=?;",
                (place_id, now_utc(), existing["id"], existing["version"]))
            conn.commit()
            return cur.rowcount == 1
        except Exception:
            conn.rollback()
            return False
    try:
        # after_src stamped too: the return leg mirrors the guess until the
        # dest->base edge is measured (_travel_provisional_return_min).
        travel_rule_add(conn, "event", event_ulid, place_id=place_id,
                        before_min=TRAVEL_PROVISIONAL_MIN,
                        before_src=TRAVEL_SRC_PROVISIONAL,
                        after_min=0, after_src=TRAVEL_SRC_PROVISIONAL,
                        created_by=_facade_agent())
        return True
    except Exception:
        return False


def _travel_provisional_upgrade(conn, rule, place_id, minutes, now=None):
    """The overwrite half of the contract: a real place/duration has arrived,
    so the stamped guess stops being the answer.

    place_id + before_src='place' hands the leg back to the deriver, which
    re-resolves it from presence + edge at derive time; `minutes` is the
    placeholder the active-rule CHECK needs (before_min > 0), exactly as the
    ordinary attach path seeds it. travel_rule_upd clears the rule's pins and
    refreshes its blocks inline, so the 60-minute block is replaced in the same
    call. Returns True iff the rule was rewritten."""
    seed = _ceil_grid(minutes) if minutes and minutes > 0 else TRAVEL_GRID_MIN
    changes = {"place_id": place_id, "before_min": seed,
               "before_src": "place"}
    if rule.get("after_src") in ("place", TRAVEL_SRC_PROVISIONAL) and not rule.get("after_min"):
        base = _travel_base_place_id(conn)
        # Only the independently measured return clears its provisional mark.
        changes["after_src"] = ("place" if base is not None and
            _travel_edge_get(conn, place_id, base) is not None else TRAVEL_SRC_PROVISIONAL)
    try:
        res = travel_rule_upd(conn, rule["id"], changes, now=now, owner_edit=False)
    except Exception:
        return False
    return res.get("result") == "applied"


def _travel_autoattach_appt(conn, event_ulid, location, force=False,
                            now=None, declared=False, address_hint=None):
    """DGN-623: auto-mint an anchor_type='event' travel rule + derive move/prep
    blocks for a place-bearing appointment, PRESENCE-AWARE (spatial). Shared by
    appt-add and the appt-travel-attach verb (re-attach after edge registration).

    Reuses the existing derivation engine end-to-end: place resolution via
    _resolve_location_place (deterministic name/alias, no network); origin
    resolved from the presence layer at the event time; the outbound duration is
    the stored (origin -> dest) travel_edge, not a flat base-origin number. No
    new derivation math -- the deriver reads the edge.

    Returns (status, origin_name, dest_name). status is a stable TRAVEL_ATTACH_*
    code; NEVER raises. The elicit codes (unknown_place / no_duration /
    edge_missing) are the signal the skill layer must ask the one-turn question.
    edge_missing names BOTH origin and dest so the skill asks a spatial question.
    A non-attach outcome leaves the appointment intact with no move/prep
    (silent-safe fallback). Pinned blocks are never overwritten (engine honors
    the pin). Idempotent: an anchor that already has a rule returns 'exists'.

    An anchor whose rule the owner RETIRED comes back 'retired' and NOTHING is
    written -- no place mint, no place_id stamp, no signal, no rule (see
    _travel_anchor_retired). force=True is the owner asking for it back by
    hand; no automatic lane passes it.

    An appointment that has ALREADY STARTED never produces a question
    (owner 2026-10-05: a past day left unchanged defeats the retro, and
    "registering" a place means home/office-like places). The day still has to be right for
    the retro, so the venue becomes a place row SILENTLY: an exact
    name/alias hit links, a miss is minted from the text, and a near match
    is NOT asked -- it stays a separate row (there is no one to ask about a
    finished evening). The rule is attached only when the outbound duration
    is KNOWN (stored edge / chain); otherwise nothing is armed -- no 60-min
    stopgap at a past instant, no TRAVEL_PLACE_NEEDED -- and the status is
    'past'. Text that is not a venue name (link, blob) is 'past' too. The
    missing pairs are listed silently by _travel_retro_missing_pairs for an
    automatic resolve (TRAVEL_RETRO_RESOLVE). Legs at past instants come
    only from the owner's own write (travel_rechain_declared); the rule
    alone derives nothing in the past. The near-match bypass is the
    owner's own write only (declared=True: appt-add / appt-upd /
    appt-travel-attach); a background lane adopting a past calendar entry
    that looks like a place on file mints nothing and comes back 'past'."""
    row = appt_snapshot(conn, event_ulid)
    if row is not None:
        try:
            travel_core.attendance_repair(sys.modules[__name__], conn, row, now=now)
        except (sqlite3.Error, ValueError):
            return TRAVEL_ATTACH_ERROR, "", ""
        if travel_core.attendance_online(sys.modules[__name__], conn, row):
            return TRAVEL_ATTACH_VIRTUAL_PLACE, "", ""
    if not event_ulid or not location or _location_is_undecided(location):
        # The undecided token is an ANSWER ("not decided yet"), not a venue:
        # minting a place called 미정 would ask a travel question about it.
        return TRAVEL_ATTACH_NONE, "", ""
    try:
        # BEFORE the place mint and the place_id stamp: an opt-out anchor must
        # be untouched, not merely un-derived. Asking later would still leave
        # a minted place row and a TRAVEL_PLACE_NEEDED question behind on an
        # appointment the owner already said no to.
        if not force and _travel_anchor_retired(conn, "event", event_ulid):
            return TRAVEL_ATTACH_RETIRED, "", ""
        # Past anchor: silent resolve-or-mint, no near-match question, no
        # stopgap, no signal (see docstring).
        _row = _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=?;",
                           (event_ulid,))
        past = bool(_row is not None and _row.get("start_at")
                    and _row["start_at"] <= (now or now_utc()))
        # Reuse a saved physical place, or require physical evidence from
        # the map resolver. Unresolved text remains text, without travel.
        _near_hits = []
        if past:
            place = _place_resolve_or_mint(conn, location, near_ok=declared,
                                           near_out=_near_hits, address=address_hint, emit_task=False)
            if place is None:
                return TRAVEL_ATTACH_PAST, "", ""
        else:
            place = _place_resolve_or_mint(conn, location,
                                           near_out=_near_hits, address=address_hint)
        if place is None:
            import place_identity
            if place_identity.ready(conn) and conn.execute(
                    "SELECT 1 FROM place_identity_ask WHERE query=? AND state='pending'",
                    (location,)).fetchone():
                return 'identity_pending', '', ''
        if place is None and _near_hits:
            # Looks like a place on file: ask "혹시 <dest>랑 같은 곳인가요?"
            # (dest column = the existing place's stored name, so
            # near-match-accept/-refuse take it as the ref as-is). Same
            # unresolved-place handling meanwhile -- no trip is guessed.
            return TRAVEL_ATTACH_NEAR_PLACE, "", _near_hits[0]["name"]
        if place is None:
            # Not a registrable name. WHICH kind of not-a-name decides what
            # the owner is owed, and the two are opposites:
            #   virtual -- a meeting link. No destination exists, so this is
            #     a terminal answer: no rule, no blocks, no question, and it
            #     is NOT in the elicit set so nothing nags about it.
            #   map/other -- a link the owner used to point at a real venue.
            #     The name is behind a fetch this layer does not do, so it is
            #     an open QUESTION, and saying so is the whole point: block
            #     704 reported 'unknown_place' on every 5-minute sweep for a
            #     day and nobody heard it.
            # Anything else (a pasted blob, an over-long string) keeps the
            # pre-existing unknown_place signal byte for byte.
            # The dest column echoes the raw venue text, so it gets the same
            # one-line treatment the location column does -- a newline here
            # ended the signal record early just the same.
            _link = _location_link_kind(location)
            if _link == "virtual":
                # A meeting link has no destination, so there is no trip to put
                # a stopgap on. Arming 60 minutes here would invent a commute
                # to a video call -- the one branch that must stay untouched.
                return (TRAVEL_ATTACH_VIRTUAL_PLACE, "",
                        _travel_signal_field(location))
            # No physical destination: preserve the resolution signal, but
            # never arm a provisional trip to a URL or unresolved text.
            if _link:
                return (TRAVEL_ATTACH_LINK_PLACE, "",
                        _travel_signal_field(location))
            return (TRAVEL_ATTACH_UNKNOWN_PLACE, "",
                    _travel_signal_field(location))
        dest_id = place["id"]
        dest_name = place["name"]
        # Resolve presence-origin at the event's time (spatial awareness).
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=?;",
                             (event_ulid,))
        if anchor is None:
            return TRAVEL_ATTACH_NONE, "", dest_name
        # The appointment learns its own place BEFORE any travel outcome is
        # decided: where it is, is true whether or not a duration is known.
        _appt_stamp_place(conn, anchor, dest_id)
        origin_id = _travel_origin_place_id(conn, anchor)
        origin_name = _place_name(conn, origin_id)
        import travel_retry
        travel_retry.enqueue(sys.modules[__name__], conn, anchor, origin_id, dest_id)
        # Single source of truth for "can we derive the outbound leg": resolve it
        # against a SYNTHETIC place-sourced rule (identical logic the deriver
        # runs). before_min/prep placeholders here are irrelevant -- the resolver
        # re-derives from presence + edge / base node column.
        synth_rule = {"before_src": "place", "place_id": dest_id,
                      "before_min": 0, "prep_min": 0}
        before_eff, _prep, edge_status, _oid = _travel_resolve_before_leg(
            conn, synth_rule, anchor)
        existing = _travel_rule_for_anchor_txn(conn, event_ulid, None)
        if edge_status == TRAVEL_EDGE_MISSING and past:
            # Nothing to ask and nothing to guess: the leg stays absent until
            # a duration resolves (TRAVEL_RETRO_RESOLVE, then
            # appt-travel-attach re-enters here).
            return TRAVEL_ATTACH_PAST, origin_name, dest_name
        if edge_status == TRAVEL_EDGE_MISSING:
            # The needed (origin -> dest) edge is unknown. Signal the skill to
            # ask "<origin>에서 <dest>까지 편도 몇 분?" then register it
            # (travel-edge-add) and re-attach. NEVER guess a duration. When the
            # origin is the base and no node column exists, this collapses to the
            # classic no-duration case (empty origin name).
            # 050: the place is known, the DURATION is not. Arm the stopgap on
            # THIS place (so the block lands at the right destination) and
            # return the elicit code unchanged -- the minutes question is still
            # the owner's to answer, and this line does not answer it.
            _travel_provisional_arm(conn, event_ulid, dest_id, existing)
            base = conn.execute(
                "SELECT id FROM place WHERE is_base=1;").fetchone()
            if base is not None and origin_id == base[0]:
                return TRAVEL_ATTACH_NO_DURATION, "", dest_name
            return TRAVEL_ATTACH_EDGE_MISSING, origin_name, dest_name
        # Idempotent: never double-attach an event that already has a rule.
        if existing is not None:
            # 050: unless that rule is the stopgap and a real duration has now
            # resolved -- then this is the overwrite the provisional marker
            # exists for, and it happens here, on the ordinary sweep, with no
            # extra verb and nothing for anyone to remember to run.
            if existing.get("before_src") == TRAVEL_SRC_PROVISIONAL:
                if _travel_provisional_upgrade(conn, existing, dest_id,
                                               before_eff):
                    return TRAVEL_ATTACH_ATTACHED, origin_name, dest_name
            return TRAVEL_ATTACH_EXISTS, origin_name, dest_name
        # Seed a VALID non-zero outbound placeholder so the active-rule CHECK
        # (before_min>0 OR after_min>0) passes even for an edge-only place with
        # no base-origin node column. Placeholder only -- the deriver re-resolves
        # the real leg from presence + edge at derive time (before_src='place').
        #
        # DGN-841 seed-gap fix: a SAME outcome (origin==dest, before_eff=0) is a
        # same-place CHAIN member (e.g. 점심 -> 합주 at one place). It STILL needs
        # a rule so the deriver can emit P2's return leg on the chain tail. The
        # old None seed prefilled before_min from place.to_min (NULL for an
        # edge-only place) -> before_min=after_min=0 -> the active-rule CHECK
        # REFUSED the rule -> the tail got no rule -> no return leg. Fix: arm the
        # rule with a positive grid-valid BEFORE placeholder (before_src='place').
        # The deriver re-resolves this to SAME -> before leg collapses to 0
        # (never leaks), exactly the placeholder-override contract the non-SAME
        # path already relies on. The ONLY no-rule case is dest==base: an event
        # AT home has no outbound and no return, so no rule is legitimate.
        base = conn.execute("SELECT id FROM place WHERE is_base=1;").fetchone()
        if before_eff <= 0 and base is not None and dest_id == base[0]:
            return TRAVEL_ATTACH_NONE, origin_name, dest_name
        seed_before = before_eff if before_eff > 0 else TRAVEL_GRID_MIN
        try:
            travel_rule_add(conn, "event", event_ulid, place_id=dest_id,
                            before_min=seed_before, before_src="place",
                            after_src=(TRAVEL_SRC_PROVISIONAL if
                                travel_retry.ready(conn) and conn.execute(
                                    "SELECT 1 FROM travel_leg_retry WHERE anchor_ulid=? AND role='after' AND state='queued'",
                                    (event_ulid,)).fetchone() else "place"),
                            created_by=_facade_agent())
        except sqlite3.IntegrityError as e:
            # Same convergence the def path already does, verbatim -- the event
            # path lacked it, so a race loser reported 'error' and so did every
            # anchor carrying a 'proposed' rule (the existence check above asks
            # for status='active'; idx_travel_rule_anchor is partial on
            # status != 'retired', so the INSERT collided and nothing caught
            # it). 'error' is terminal here: it is not in the elicit set, so
            # the skill never asks and the sweep reports it again next cycle,
            # forever. A rule IS present -> converge to 'exists'.
            if ("travel_rule.anchor_type" in str(e)
                    or "idx_travel_rule_anchor" in str(e)
                    or "UNIQUE" in str(e)):
                return TRAVEL_ATTACH_EXISTS, origin_name, dest_name
            raise
        return TRAVEL_ATTACH_ATTACHED, origin_name, dest_name
    except Exception:
        # Best-effort: an auto-attach failure must never fail the caller.
        return TRAVEL_ATTACH_ERROR, "", ""


def _travel_retro_missing_pairs(conn, eid, now=None):
    """A PAST appointment's legs that cannot be derived for want of minutes:
    [(origin_name, dest_name), ...], or [] (never raises).

    The pairs are the venue's neighbours on its local day -- the previous
    stop (home when none) -> the venue, the venue -> the next stop (home
    when none), and the venue -> home when the next stop is elsewhere (the
    "does a trip home fit" judgment needs it). Only pairs with no stored
    edge are listed. The CLI prints them as TRAVEL_RETRO_RESOLVE lines: the
    skill resolves each silently (routines/bundle/travel-resolve.sh, the
    existing route puller) and re-attaches; a pair that does not resolve is
    simply left -- no question, no guessed minutes (owner 2026-10-05)."""
    try:
        if not _travel_schema_ready(conn) or not _travel_edge_schema_ready(conn):
            return []
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (eid,))
        if (anchor is None or anchor.get("block_class") is not None
                or anchor.get("settled_at") is not None
                or anchor.get("schedule_kind") != "timed"
                or not anchor.get("start_at") or not anchor.get("end_at")
                or anchor["start_at"] > (now or now_utc())):
            return []
        venue = anchor.get("place_id")
        base = _travel_base_place_id(conn)
        if venue is None or base is None or venue == base:
            return []
        if _travel_anchor_retired(conn, "event", anchor["ulid"]):
            return []
        lo, hi = _travel_local_day_window(anchor["start_at"])
        peers = _travel_rows(
            conn, "SELECT id, ulid, kind, location, recurrence_id, "
            "block_class, derived_from, start_at, end_at, place_id, "
            "schedule_kind FROM timeblock WHERE settled_at IS NULL "
            "AND block_class IS NULL AND schedule_kind='timed' "
            "AND start_at IS NOT NULL AND end_at IS NOT NULL AND id != ? "
            "AND start_at >= ? AND start_at < ? ORDER BY start_at, id;",
            (anchor["id"], lo, hi))
        prev_pid = next_pid = None
        prev_end = None
        for ev in peers:
            if not _travel_external(conn, ev):
                continue
            if ev["end_at"] <= anchor["start_at"]:
                if prev_end is None or ev["end_at"] >= prev_end:
                    prev_end = ev["end_at"]
                    prev_pid = _travel_external_place_id(conn, ev)
            elif ev["start_at"] >= anchor["end_at"] and next_pid is None:
                next_pid = _travel_external_place_id(conn, ev) or base
        prev_pid = prev_pid or base
        next_pid = next_pid or base
        want = [(prev_pid, venue), (venue, next_pid)]
        if next_pid != base:
            want.append((venue, base))
        out = []
        for a, b in want:
            if a == b or (a, b) in out:
                continue
            if _travel_edge_get(conn, a, b) is None:
                out.append((a, b))
        return [(_place_name(conn, a) or "", _place_name(conn, b) or "")
                for a, b in out]
    except Exception:  # noqa: BLE001 -- a probe never fails a write
        return []


def _print_retro_resolve(conn, eid):
    """TRAVEL_RETRO_RESOLVE<TAB><eid><TAB><origin><TAB><dest>, one line per
    missing pair of a past appointment (_travel_retro_missing_pairs)."""
    for a, b in _travel_retro_missing_pairs(conn, eid):
        print("TRAVEL_RETRO_RESOLVE\t%s\t%s\t%s" % (
            eid, _travel_signal_field(a), _travel_signal_field(b)))


def travel_attach_event(conn, event_ulid, location=None, declared=False):
    """PUBLIC seam for callers that hold an anchor ulid and nothing else
    (the mirror's inbound lanes). Runs the SAME DGN-623 auto-attach as
    appt-add, reading the venue off the row when the caller does not carry
    it. Returns (status, origin_name, dest_name); NEVER raises.

    An anchor that already has a rule comes back TRAVEL_ATTACH_EXISTS and a
    row with no venue comes back TRAVEL_ATTACH_NONE, so this is safe to call
    unconditionally after any intake-shaped event."""
    if not event_ulid:
        return TRAVEL_ATTACH_NONE, "", ""
    if location is None:
        try:
            row = conn.execute(
                "SELECT kind, location FROM timeblock WHERE ulid=?;",
                (event_ulid,)).fetchone()
        except sqlite3.Error:
            return TRAVEL_ATTACH_ERROR, "", ""
        if row is None or row[0] != "appointment":
            return TRAVEL_ATTACH_NONE, "", ""
        location = row[1]
    if not location:
        return TRAVEL_ATTACH_NONE, "", ""
    return _travel_autoattach_appt(conn, event_ulid, location,
                                   declared=declared)


# -- appointment change choke point (owner 2026-10-09 09:55) ---------------
# ("why is a changed appointment not fixed right away"): every write lane
# that moves, re-venues, cancels or reshapes an appointment/stay used to
# carry its own hand-picked subset of followers (attach here, refresh there, the old day
# only in one lane, the rule's venue in none). Appointment 15668 changed
# place 26 -> 27 in the calendar and its travel rule kept 26. So: every
# lane snapshots the row BEFORE its write (appt_snapshot) and calls ONE
# function AFTER it (appt_rederive). Derived surfaces that read at select
# time (reminders: remind_select over the blocks + rule; the day card: the
# caller's _day_card_refresh / the mirror's per-cycle refresh) follow from
# the blocks and rule being right.

def appt_snapshot(conn, ulid):
    """The row as it stood BEFORE a write -- the `before` appt_rederive
    diffs against. None when absent; never raises."""
    if not ulid:
        return None
    try:
        return _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=?;",
                           (ulid,))
    except Exception:  # noqa: BLE001 -- a probe never fails a write
        return None


def _travel_autoattach_pending_defs(conn, place_ids=None, state_conn=None):
    """Re-run _travel_autoattach_def for every ACTIVE, timed, place-bound
    routine def (task or presence) away from home that holds no live travel
    rule, optionally only those at `place_ids`. Returns [(def_id, status)].

    Why (2026-10-15 gym audit): a def whose place was set before any
    home<->place duration existed came back 'no_duration' and nothing ever
    asked again -- the def lane had no periodic retry, unlike appointments
    (travel_attach_sweep). The gym defs got place 31 on 10-11 with no edge,
    so no gym legs were derived and the office prep lost its gym return
    leg. Learning the duration later (travel-edge-add, or the nightly pass)
    now completes the attach. A rule the owner retired stays retired
    (_travel_autoattach_def returns 'retired' without writing). NEVER raises."""
    out = []
    try:
        base_id = _travel_base_place_id(conn)
        rows = conn.execute(
            "SELECT d.id, d.ulid, d.place_id FROM routine_def d "
            "WHERE d.status='active' AND d.schedule_kind='timed' "
            "AND d.kind IN ('task','presence') AND d.place_id IS NOT NULL "
            "AND d.place_id IS NOT ? "
            "AND NOT EXISTS (SELECT 1 FROM travel_rule r "
            "  WHERE r.anchor_type='def' AND r.anchor_ulid=d.ulid "
            "  AND r.status != 'retired') "
            "ORDER BY d.id;", (base_id,)).fetchall()
    except sqlite3.Error:
        return out
    want = set(place_ids) if place_ids else None
    for def_id, ulid, pid in rows:
        if want is not None and pid not in want:
            continue
        status, _o, _d = _travel_autoattach_def(conn, ulid,
                                                state_conn=state_conn)
        out.append((def_id, status))
    return out


def _travel_rule_follow_venue(conn, anchor, before, now=None):
    """The appointment's event-direct rule follows a CHANGED venue.

    Follows when the rule pointed at the venue the row had before this
    write (`before`), or is a provisional stopgap (estimated time, not
    venue identity; also the no-snapshot sweep case). A rule the owner aimed
    at some other place is his and stays. The duration source is kept,
    except a place-derived leg whose new edge is unknown: that becomes the
    050 provisional stopgap instead of silently losing its move leg (the
    sweep upgrades it once the edge is measured). Raw UPDATE, not
    travel_rule_upd: that verb clears pins, and the venue is derived
    metadata, not an owner rule edit. Returns True iff rewritten; never
    raises."""
    try:
        new = anchor.get("place_id")
        if new is None or anchor.get("block_class") is not None:
            return False
        rule = _travel_rule_for_anchor_txn(conn, anchor["ulid"], None)
        if rule is None or rule.get("place_id") == new:
            return False
        old = before.get("place_id") if before else None
        if not (rule.get("before_src") == TRAVEL_SRC_PROVISIONAL
                or (old is not None and old != new
                    and rule.get("place_id") == old)):
            return False
        sets, params = ["place_id=?"], [new]
        if (rule.get("before_src") == "place"
                and _travel_provisional_supported(conn)):
            synth = {"before_src": "place", "place_id": new,
                     "before_min": 0, "prep_min": 0}
            if _travel_resolve_before_leg(
                    conn, synth, anchor)[2] == TRAVEL_EDGE_MISSING:
                sets += ["before_src=?", "before_min=?"]
                params += [TRAVEL_SRC_PROVISIONAL, TRAVEL_PROVISIONAL_MIN]
                if (rule.get("after_src") == "place"
                        and int(rule.get("after_min") or 0) == 0):
                    # the return mirrors the stopgap (see
                    # _travel_provisional_return_min); explicit after stays
                    sets += ["after_src=?"]
                    params += [TRAVEL_SRC_PROVISIONAL]
        conn.execute("BEGIN IMMEDIATE;")
        cur = conn.execute(
            "UPDATE travel_rule SET " + ", ".join(sets) +
            _TRAVEL_PREP_RELABEL_SQL + ", version=version+1, updated_at=? "
            "WHERE id=? AND version=?;",
            params + [now or now_utc(), rule["id"], rule["version"]])
        conn.commit()
        return cur.rowcount == 1
    except Exception:  # noqa: BLE001 -- best-effort follower
        try:
            conn.rollback()
        except Exception:  # noqa: BLE001
            pass
        return False


def _travel_refresh_day_all(conn, state_conn, instant, now=None,
                            declared=False):
    """Re-derive every rule-holding anchor of the local day holding
    `instant`: an appointment that moved, re-venued or left changes its
    neighbours' origin, chain tail and the day's single prep. Two passes in
    start order (a leg reads its neighbours' rows; on converged input the
    second pass writes nothing). Future-only, unless `declared` (the owner's
    own edit) on a day that has begun -- that is travel_rechain_declared.
    Pinned rows keep their own branch inside travel_refresh. Never raises."""
    if not instant:
        return
    now = now or now_utc()
    try:
        lo, hi = _travel_local_day_window(instant)
        if declared and lo <= now:
            travel_rechain_declared(conn, state_conn, None, now=now,
                                    instant=instant)
            return
        for _pass in range(2):
            for peer in _travel_rows(
                    conn,
                    "SELECT * FROM timeblock WHERE settled_at IS NULL "
                    "AND block_class IS NULL AND schedule_kind='timed' "
                    "AND start_at >= ? AND start_at < ? "
                    "ORDER BY start_at, id;", (lo, hi)):
                if (_travel_rule_for_anchor_row(conn, peer) is None
                        or not _travel_anchor_eligible(peer)):
                    continue
                travel_refresh(conn, state_conn, peer["ulid"], now=now,
                               _chain=False)
    except Exception:  # noqa: BLE001 -- never fail a write on a re-derive
        pass


_APPT_REDERIVE_KEYS = ("start_at", "end_at", "schedule_kind", "place_id",
                       "location", "settled_at", "title", "kind")


def appt_rederive(conn, ulid, before=None, state_conn=None, declared=False,
                  carry=None, now=None):
    """THE single re-derive after ANY write to an appointment or stay --
    chat verbs (appt-upd / appt-cancel / appt-del / appt-origin /
    presence-move / presence-cancel) and the mirror's inbound edit / move /
    delete alike. `before` is appt_snapshot() taken before the write.

    In order:
      1. venue -> place -> rule: a live appointment with a location re-runs
         the DGN-623 attach (mint/stamp the place, arm/upgrade the stopgap;
         idempotent);
      2. the rule follows a changed venue (_travel_rule_follow_venue);
      3. the row's own legs: travel_refresh (a settled/untimed row retires
         its future unpinned legs; pinned legs keep their pinned branch);
      4. the local day(s) the row was on BEFORE and is on NOW: every
         rule-holding anchor re-derives (origin, chain tail, the day prep);
      5. ride routines of those days re-seat.
    `declared` = the owner's own write (chat verbs); a changed schedule in
    `before` also declares a retime (calendar inbound). A day already begun
    re-chains its past legs too. `carry` = travel_preclean's pins, for the
    guarded chat move.

    Returns travel_refresh's summary plus "attach": (status, origin, dest)
    or None. Never raises: the write has already committed."""
    now = now or now_utc()
    state_conn = _travel_state_conn(state_conn)
    summary = {"result": "ok", "regen": 0, "created": 0, "tombstoned": 0,
               "moved": 0, "attach": None}
    row = appt_snapshot(conn, ulid)
    if row is None:
        summary["result"] = "anchor_not_found"
        return summary
    if row.get("block_class") is not None:
        return summary            # a derived block is not an anchor
    # Calendar retimes are owner edits too. Open the day BEFORE the first
    # refresh so it cannot retire an elapsed leg before re-chaining it.
    retimed = before is not None and any(
        before.get(k) != row.get(k)
        for k in ("start_at", "end_at", "schedule_kind"))
    declared = declared or retimed

    try:
        travel_core.attendance_repair(sys.modules[__name__], conn, row, state_conn, now)
    except (sqlite3.Error, ValueError) as e:
        summary.update(result="error", error=str(e)[:120])
        return summary
    row = appt_snapshot(conn, ulid) or row
    live = row.get("settled_at") is None
    try:
        if live and row.get("kind") == "appointment" and row.get("location"):
            summary["attach"] = travel_attach_event(
                conn, ulid, row["location"], declared=declared)
            row = appt_snapshot(conn, ulid) or row
        if live:
            _travel_rule_follow_venue(conn, row, before, now=now)
    except Exception:  # noqa: BLE001
        pass
    try:
        s = travel_refresh(conn, state_conn, ulid, carry=carry, now=now,
                           declared=declared)
        for k in ("result", "regen", "created", "tombstoned", "moved"):
            summary[k] = s.get(k, summary[k])
    except Exception as e:  # noqa: BLE001
        summary["result"] = "error"
        summary["error"] = str(e)[:120]
    # The owner's own edit re-chains its day whatever field it touched
    # (owner 2026-10-05 21:16); a background lane only when a field the
    # neighbours read moved.
    if not declared and before is not None and all(
            before.get(k) == row.get(k) for k in _APPT_REDERIVE_KEYS):
        return summary
    instants, dates = [], set()
    for src in (before, row):
        at = (src or {}).get("start_at")
        if at and at not in instants:
            instants.append(at)
    for at in instants:
        _travel_refresh_day_all(conn, state_conn, at, now=now,
                                declared=declared)
        try:
            dates.add(_travel_local_date(at, row.get("display_tz")))
        except Exception:  # noqa: BLE001
            pass
    if dates:
        _ride_resolve_best_effort(conn, state_conn, now=now, dates=dates)
    if live and row.get("kind") == "appointment":
        try:
            rr = _roller_mod()
            for token, rid in conn.execute(
                    "SELECT ulid, recurrence_id FROM routine_def "
                    "WHERE status!='retired';").fetchall():
                link = rr.until_link(conn, rid)
                if link and link["event"] == ulid:
                    defn = routine_def_get(conn, token)
                    today = _travel_local_date(now, defn["display_tz"])
                    if defn["status"] == "active":
                        rr.materialize_def(conn, state_conn, defn,
                                           today=today, now=now)
                    else:
                        rr.sync_until(conn, state_conn, defn, today, now=now)
        except Exception as e:
            summary["result"] = "error"
            summary["routine_error"] = str(e)[:120]
    return summary


# ── attach convergence pass (the missing half of the travel lane) ─────────
# travel_conformance_pass converges the BLOCKS of rules that already exist.
# Nothing ever re-ran ATTACHMENT, and attachment was a one-shot at intake:
# cli_appt_add, cli_appt_upd's location edit, and mirror_adopt_appt each call
# _travel_autoattach_appt exactly once, for the row in front of them. An
# appointment that missed that one moment -- imported before the hook existed
# (notion-import), adopted from a calendar entry whose venue was typed in
# later, or left at unknown_place/no_duration because the datum was missing
# that day -- was never looked at again, by anything. There was no verb to
# look at it either. Measured 2026-09-11 on the live DB: 8 appointments in the
# next 4 weeks, 3 carrying a venue string, 0 with a place_id, 0 with a rule.
#
# So: the same deriver, over a WINDOW instead of over one row. No new
# derivation math and no second mechanism -- _travel_autoattach_appt stays the
# single choke point, and its outcome codes are what this pass reports.
TRAVEL_SWEEP_HORIZON_DAYS = agent_conf.conf_int("LIFEKIT_TRAVEL_SWEEP_DAYS", 28)


def travel_attach_sweep(conn, since=None, until=None, now=None):
    """(Re-)run DGN-623 auto-attach over every FUTURE place-bearing
    appointment in [since, until), and (2026-09-30, Rule 2) every future
    hand-entered timed stay (presence) at a place that is not home.

    since/until are canonical UTC instants; defaults are
    [now, now + TRAVEL_SWEEP_HORIZON_DAYS). `since` is floored at `now` on
    every call -- deriving move/prep into the past is never what anyone
    means, and the deriver's own future-only guards would retire the rows
    again anyway.

    Scope, deliberately narrow: kind='appointment', live (unsettled), timed,
    not itself a derived block, and carrying a non-empty location. A row with
    no venue is not an attach miss -- it is an appointment nobody told us the
    place of, and inventing one is exactly the failure mode this lane exists
    to avoid.

    IDEMPOTENT, but not write-free. Measured on a copy of the live DB
    (2026-09-11): an anchor that already carries a rule comes back
    TRAVEL_ATTACH_EXISTS and nothing is written, and a venue that resolved to
    a place last run resolves to the SAME place this run -- names are stored
    and looked up in _place_norm_name form, so a re-run never mints a second
    row for one venue. A `needs` outcome, however, is NOT inert: the deriver
    mints the place row for a resolvable venue and stamps the appointment's
    place_id BEFORE it decides the travel outcome (where the appointment is
    is true whether or not a duration is known -- _appt_stamp_place). What a
    `needs` outcome does not write is a travel_rule or any derived block, and
    those two writes converge, so the SECOND sweep over the same rows is
    write-free and reports the same thing. An anchor the owner retired comes
    back TRAVEL_ATTACH_RETIRED and is not touched at all.

    Returns {'scanned', 'attached', 'exists', 'needs', 'retired', 'other',
    'provisional', 'since', 'until', 'rows'} where rows = [(eid, status,
    location, origin, dest), ...] for every scanned appointment, in start
    order. NEVER raises.

    050: `provisional` is a SUBSET of `needs`, never a replacement for it --
    how many of the still-owed questions now carry a stamped 60-minute stopgap
    instead of nothing at all. `needs` keeps its exact pre-050 meaning, so the
    number a regression check pins does not move because a stopgap landed."""
    now = now or now_utc()
    if since is None or since < now:
        since = now
    if until is None:
        until = (datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
                 + timedelta(days=TRAVEL_SWEEP_HORIZON_DAYS)
                 ).strftime("%Y-%m-%dT%H:%M:%SZ")
    out = {"scanned": 0, "attached": 0, "exists": 0, "needs": 0, "retired": 0,
           "other": 0, "provisional": 0, "since": since, "until": until,
           "rows": []}
    if not _travel_schema_ready(conn):
        return out                      # pre-008 DB -> no-op (M2)
    try:
        rows = conn.execute(
            "SELECT id, ulid, location, start_at FROM timeblock "
            "WHERE kind='appointment' AND block_class IS NULL "
            "AND schedule_kind='timed' AND settled_at IS NULL "
            "AND start_at IS NOT NULL AND start_at >= ? AND start_at < ? "
            "AND location IS NOT NULL AND TRIM(location) <> '' "
            + _SQL_LOCATION_NOT_UNDECIDED +
            "ORDER BY start_at;", (since, until)).fetchall()
        # Rule 2 (2026-09-30): a timed stay away from home is a chain stop
        # and presence-add attaches its arrival leg. A stay written before
        # that (live 15583, the family-home stay) never went through it, so the sweep
        # covers the same rows presence-add would have: hand-entered
        # (a routine presence travels through its def rule), timed, live,
        # at a place that is not home. The venue is the place's name, the
        # string presence-add passes. Same deriver, same idempotence: a
        # stay that already carries a rule comes back 'exists'.
        base_id = _travel_base_place_id(conn)
        stays = conn.execute(
            "SELECT t.id, t.ulid, p.name, t.start_at FROM timeblock t "
            "JOIN place p ON p.id = t.place_id "
            "WHERE t.kind='presence' AND t.block_class IS NULL "
            "AND t.schedule_kind='timed' AND t.settled_at IS NULL "
            "AND t.recurrence_id IS NULL AND COALESCE(t.is_routine, 0) = 0 "
            "AND t.start_at IS NOT NULL AND t.start_at >= ? "
            "AND t.start_at < ? AND t.place_id IS NOT ? "
            "AND p.name IS NOT NULL AND TRIM(p.name) <> '';",
            (since, until, base_id)).fetchall()
        rows = [r[:3] for r in sorted(rows + stays,
                                      key=lambda r: (r[3], r[0]))]
    except sqlite3.Error:
        return out                      # best-effort, same grade as the hook
    attached_ulids = []
    for eid, ulid, location in rows:
        out["scanned"] += 1
        status, origin, dest = _travel_autoattach_appt(conn, ulid, location,
                                                       now=now)
        out["rows"].append((eid, status, location, origin, dest))
        if status == TRAVEL_ATTACH_ATTACHED:
            out["attached"] += 1
            attached_ulids.append(ulid)
        elif status == TRAVEL_ATTACH_EXISTS:
            out["exists"] += 1
        elif status in _TRAVEL_ATTACH_NEEDS_ELICIT:
            out["needs"] += 1
        elif status == TRAVEL_ATTACH_RETIRED:
            # Counted apart from 'other': this is the owner's standing
            # decision, not a failure and not a backlog item. It must never
            # read as something to go fix.
            out["retired"] += 1
        else:
            out["other"] += 1           # none / error
    # 050: count the stopgaps that are standing over this window. Read AFTER
    # the loop, off the rules themselves -- the marker is a column, so this is
    # a query and not a tally the loop has to be trusted to keep.
    if rows:
        try:
            out["provisional"] = conn.execute(
                "SELECT COUNT(*) FROM travel_rule WHERE anchor_type='event' "
                "AND status='active' AND before_src=? AND anchor_ulid IN (%s);"
                % ",".join("?" * len(rows)),
                [TRAVEL_SRC_PROVISIONAL] + [r[1] for r in rows]).fetchone()[0]
        except sqlite3.Error:
            out["provisional"] = 0      # pre-050: no such src, no stopgaps
    for ulid in attached_ulids:
        # DGN-258 parity with appt-travel-attach: the anchor's place_id just
        # became true, so its surface render is stale until it is re-pushed.
        _outbox_enqueue_best_effort(ulid)
    # 2026-10-15: place-bound routine defs still waiting on a duration get
    # the same nightly retry. Kept out of the appointment counters above
    # (place_gap_scan pins those to the same appointment rows).
    out["defs"] = _travel_autoattach_pending_defs(conn)
    out["defs_attached"] = sum(1 for _i, st in out["defs"]
                               if st == TRAVEL_ATTACH_ATTACHED)
    return out


# ── the gap, said out loud ────────────────────────────────────────────────
# travel_attach_sweep already KNOWS which appointments have no travel. It has
# known about block 704 since the moment it was written, and it has said so on
# every one of the 5-minute mirror cycles for a day -- into a step that
# deliberately logs nothing for the elicit outcomes (adapter.travel_attach_step:
# "they report the same thing every five minutes"). That call is right for a
# per-cycle log and wrong as the only surface: the owner found out he had no
# travel time for tomorrow's wedding by asking.
#
# So: a READ verb. No writes of any kind -- not a place mint, not a place_id
# stamp, not an outbox enqueue -- because the point is to be safe to call from
# a briefing, a cron, or a worried human, as often as anyone likes. The sweep
# stays the only thing that writes.
#
# What counts as a gap is deliberately the owner's question and not the
# machine's: "does this appointment have travel time on it?" A row is a gap
# when it is a future place-bearing appointment with no live travel block and
# no active rule to make one. Everything else is reported for context and
# marked not-a-gap.

PLACE_GAP_LINK_ONLY = "link_only"      # location is a link; venue never read
PLACE_GAP_NO_PLACE = "no_place"        # venue text resolves to no place row
PLACE_GAP_NO_DURATION = "no_duration"  # place on file, no derivable duration
PLACE_GAP_VIRTUAL = "virtual"          # meeting link: no travel EXISTS
PLACE_GAP_RETIRED = "retired"          # the owner opted this one out
PLACE_GAP_OK = "ok"                    # travel is on the calendar
PLACE_GAP_SIBLING = "sibling"          # Rule 1: moves with its outing's leg

# The reasons that mean the owner will arrive with no travel time blocked.
# virtual/retired/ok are NOT gaps: one has no destination, one is his own
# standing decision, one is already done. Reporting those three as problems
# is how a warning surface teaches people to ignore it.
PLACE_GAP_REASONS = (PLACE_GAP_LINK_ONLY, PLACE_GAP_NO_PLACE,
                     PLACE_GAP_NO_DURATION)


def place_gap_scan(conn, since=None, until=None, now=None):
    """Future place-bearing appointments that have NO travel time on them.

    READ ONLY. Same window and same appointment rows as travel_attach_sweep
    (so the two can never disagree about which rows are in play; the stays
    the sweep also attaches since 2026-09-30 are not appointments and are
    not on this list), but it resolves
    with _resolve_location_place -- the pure-SELECT half -- and mints
    nothing.

    Returns {'scanned', 'gaps', 'since', 'until', 'rows'} where rows is a
    list of dicts in start order:
      {'id', 'ulid', 'title', 'start_at', 'location', 'location_url',
       'link', 'reason', 'place', 'is_gap'}
    'link' is '' | 'map' | 'virtual' | 'other'; 'place' is the resolved place
    name or ''. location_url is carried because the schema HAS a slot for a
    link (6 live rows use it) and the whole defect is a link sitting in the
    venue slot instead -- so "is the link also where it belongs" is part of
    the finding, and it is what tells a repair whether to move the link or
    leave an existing one alone. NEVER raises -- a briefing must not die
    because a report surface tripped."""
    now = now or now_utc()
    if since is None or since < now:
        since = now
    if until is None:
        until = (datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
                 + timedelta(days=TRAVEL_SWEEP_HORIZON_DAYS)
                 ).strftime("%Y-%m-%dT%H:%M:%SZ")
    out = {"scanned": 0, "gaps": 0, "since": since, "until": until,
           "rows": []}
    if not _travel_schema_ready(conn):
        return out                      # pre-008 DB -> no-op (M2)
    try:
        rows = conn.execute(
            "SELECT id, ulid, title, start_at, location, location_url "
            "FROM timeblock "
            "WHERE kind='appointment' AND block_class IS NULL "
            "AND schedule_kind='timed' AND settled_at IS NULL "
            "AND start_at IS NOT NULL AND start_at >= ? AND start_at < ? "
            "AND location IS NOT NULL AND TRIM(location) <> '' "
            + _SQL_LOCATION_NOT_UNDECIDED +
            "ORDER BY start_at;", (since, until)).fetchall()
    except sqlite3.Error:
        return out                      # best-effort, same grade as the sweep
    for eid, ulid, title, start_at, location, loc_url in rows:
        out["scanned"] += 1
        rec = {"id": eid, "ulid": ulid, "title": title or "",
               "start_at": start_at, "location": _place_norm_name(location),
               "location_url": _place_norm_name(loc_url),
               "link": _location_link_kind(location), "place": "",
               "reason": PLACE_GAP_OK, "is_gap": False}
        try:
            # Order matters and is the same order the deriver decides in:
            # the owner's opt-out outranks every diagnosis (asking about a
            # rule he retired is the machine arguing with him), a meeting
            # link has no destination to diagnose, and only then do we look
            # at whether travel actually landed.
            if _travel_anchor_retired(conn, "event", ulid):
                rec["reason"] = PLACE_GAP_RETIRED
            elif _travel_bundle_neighbour(
                    conn, {"id": eid, "start_at": start_at}, "prev"):
                # The previous leg of its own outing is right before it: the
                # owner travels with the outing, so no travel is owed here.
                rec["reason"] = PLACE_GAP_SIBLING
            elif rec["link"] == "virtual":
                rec["reason"] = PLACE_GAP_VIRTUAL
            else:
                place = _resolve_location_place(conn, location)
                rec["place"] = (place or {}).get("name") or ""
                has_block = conn.execute(
                    "SELECT 1 FROM timeblock WHERE block_class='travel' "
                    "AND derived_from=? AND settled_at IS NULL LIMIT 1;",
                    (ulid,)).fetchone() is not None
                if has_block:
                    rec["reason"] = PLACE_GAP_OK
                elif place is None:
                    rec["reason"] = (PLACE_GAP_LINK_ONLY if rec["link"]
                                     else PLACE_GAP_NO_PLACE)
                else:
                    # A place is on file but nothing derived from it. An
                    # armed rule with no block yet is still a gap TODAY --
                    # what the owner asked is whether travel is on the
                    # calendar, and a rule that has not produced one is not.
                    rec["reason"] = PLACE_GAP_NO_DURATION
        except sqlite3.Error:
            rec["reason"] = PLACE_GAP_OK   # unknown -> never cry wolf
        rec["is_gap"] = rec["reason"] in PLACE_GAP_REASONS
        if rec["is_gap"]:
            out["gaps"] += 1
        out["rows"].append(rec)
    return out


LINK_GAP_ABSENT = "absent"      # no actual travel_min measure was ever written
LINK_GAP_EXPIRED = "expired"    # actual travel_min rows exist, none in force
LINK_GAP_OK = "ok"
LINK_GAP_REASONS = frozenset((LINK_GAP_ABSENT, LINK_GAP_EXPIRED))


def travel_link_gap_scan(conn, now=None):
    """Active place_link pairs that carry NO usable travel duration.

    READ ONLY. Ticket 2026-09-17 travel-edge-measure-migration-hole: 036 moved
    the pairs into place_link but not their minutes into measure, and the
    travel_edge view INNER JOINs the measure -- so a link without one simply
    vanished from every reader and the before-leg went silently MISSING. This
    surfaces those links instead of waiting for an anchor to trip on them.

    A link is in scope when both endpoints are status='active' (a 'gone'
    place has no future travel to owe). Per link, only the 'actual' basis
    travel_min metric counts -- the same filter travel_edge applies:
      ok       an in-force row (valid_until NULL or > now) exists
      expired  rows exist, every one has valid_until <= now
      absent   no row at all ('planned' rows do not count -- the deriver
               never reads them)
    Minutes are reported ONLY for ok links (the in-force value, exactly what
    travel_edge shows). A gap row never carries a number: there is nothing
    to report, and a fallback guess here is precisely what this surface
    exists to refuse. For expired rows 'expired_at' is the latest
    valid_until so the caller can say since when.

    Returns {'links', 'absent', 'expired', 'ok', 'rows'}; rows are dicts
      {'link_id', 'from_id', 'from_name', 'to_id', 'to_name',
       'from_is_base', 'reason', 'minutes', 'expired_at', 'is_gap'}
    ordered by link id. Pre-v3.2 DB (no place_link / measure link column)
    -> empty result. NEVER raises -- a briefing must not die because a
    report surface tripped."""
    now = now or now_utc()
    out = {"links": 0, "absent": 0, "expired": 0, "ok": 0, "rows": []}
    try:
        if not _is_v32(conn):
            return out
        links = conn.execute(
            "SELECT pl.id, pf.id, COALESCE(pf.name,''), pt.id, "
            "COALESCE(pt.name,''), COALESCE(pf.is_base,0) "
            "FROM place_link pl "
            "JOIN place pf ON pf.id = pl.from_place_id "
            "AND pf.status = 'active' "
            "JOIN place pt ON pt.id = pl.to_place_id "
            "AND pt.status = 'active' "
            "ORDER BY pl.id;").fetchall()
        for lid, fid, fname, tid, tname, fbase in links:
            live = conn.execute(
                "SELECT value FROM measure WHERE place_link_id=? "
                "AND metric=? AND basis='actual' "
                "AND (valid_until IS NULL OR valid_until > ?) "
                "ORDER BY observed_at DESC, id DESC LIMIT 1;",
                (lid, TRAVEL_METRIC_MIN, now)).fetchone()
            rec = {"link_id": lid, "from_id": fid, "from_name": fname,
                   "to_id": tid, "to_name": tname,
                   "from_is_base": bool(fbase), "reason": LINK_GAP_OK,
                   "minutes": None, "expired_at": None, "is_gap": False}
            if live is not None:
                rec["minutes"] = int(live[0])
            else:
                dead = conn.execute(
                    "SELECT MAX(valid_until) FROM measure "
                    "WHERE place_link_id=? AND metric=? "
                    "AND basis='actual';",
                    (lid, TRAVEL_METRIC_MIN)).fetchone()
                if dead is not None and dead[0] is not None:
                    rec["reason"] = LINK_GAP_EXPIRED
                    rec["expired_at"] = dead[0]
                else:
                    rec["reason"] = LINK_GAP_ABSENT
            rec["is_gap"] = rec["reason"] in LINK_GAP_REASONS
            out["links"] += 1
            out[rec["reason"]] += 1
            out["rows"].append(rec)
    except sqlite3.Error:
        return {"links": 0, "absent": 0, "expired": 0, "ok": 0, "rows": []}
    return out


def _travel_def_probe_anchor(conn, defn):
    """Synthetic anchor dict for a routine def that has NO materialized
    instance yet (the roller's 28-day horizon may not reach the def's first
    occurrence, so a brand-new def can legitimately have zero rows). Built
    from the def's own next scheduled occurrence via the same projection the
    roller uses, so the probe sees the real instant.

    Used ONLY to answer "is this leg resolvable" at attach time. It is never
    persisted and never derived from -- the deriver re-resolves origin against
    each REAL instance once the roller emits it. id=None is correct here:
    there is no row to self-exclude. Returns None when the def has no upcoming
    occurrence inside its own validity window (nothing to attach to)."""
    try:
        rp = _projection_mod()
        lo = max(routine_today(defn["display_tz"] or TRAVEL_DISPLAY_TZ),
                 defn["start_date"] or "")
        hi = defn.get("end_date") or defn.get("valid_until")
        if not hi or hi < lo:
            return None
        for dd in rp.occurrence_dates(defn, lo, hi):
            sa, ea, _sk = rp.rule_instants(defn, dd.isoformat())
            return {"id": None, "ulid": None, "start_at": sa, "end_at": ea,
                    "display_tz": defn["display_tz"], "title": defn["title"]}
    except Exception:
        return None
    return None


def _travel_autoattach_def(conn, def_ulid, state_conn=None, force=False):
    """DGN-623 presence lane: auto-mint an anchor_type='def' travel rule +
    derive move/prep blocks for a place-bearing PRESENCE routine def. This is
    the recurring-anchor analogue of _travel_autoattach_appt and reuses the
    SAME resolution path (_travel_origin_place_id + _travel_resolve_before_leg
    + travel_rule_add) -- no parallel derivation math.

    Why it exists: fixing the presence_at self-match alone restores nothing,
    because nothing ever MINTED a travel rule for a presence def. Attachment
    used to be keyed off "a rule row happens to exist", i.e. somebody typed a
    verb by hand. Shared by routine_add (kind=presence with a place) and the
    routine-travel-attach verb (attach to an EXISTING def, the same way
    appt-travel-attach re-runs attachment on an existing appointment).

    Shape differences from the appointment path, all forced by the anchor:
      - the place is already resolved (routine_def.place_id), so there is no
        location-string parse and no unknown_place outcome;
      - the leg is probed against a REPRESENTATIVE live instance of the def;
        the deriver re-resolves origin per instance at derive time anyway. No
        live instance yet -> nothing to attach to.
      - dest == base (집) is the 재택 case: the user is already home, so there
        is no outbound and no return. NO rule is minted (no phantom commute).

    Returns (status, origin_name, dest_name) using the same TRAVEL_ATTACH_*
    codes. NEVER raises. Idempotent: an existing non-retired rule returns
    'exists', and idx_travel_rule_anchor (partial unique on
    (anchor_type, anchor_ulid) WHERE status != 'retired') is the concurrent
    backstop -- its IntegrityError converges to 'exists', never a duplicate.

    A def whose rule the owner RETIRED comes back 'retired' and nothing is
    written. The def lane has no periodic loop, so this is not the D1 wound --
    but the existence query here (status != 'retired') is blind to a retired
    row the same way, so `routine-travel-attach` would resurrect it just as
    silently. force=True is the owner asking for it back by hand."""
    if not def_ulid:
        return TRAVEL_ATTACH_NONE, "", ""
    try:
        defn = routine_def_get(conn, def_ulid)
        if defn is None or defn.get("kind") not in ("presence", "task"):
            return TRAVEL_ATTACH_NONE, "", ""
        if (defn.get("kind") == "task"
                and defn.get("schedule_kind") != "timed"):
            # gym-place-wire: a task def travels only when it is timed and
            # place-bound (an untimed todo is no anchor -- OQA-13).
            return TRAVEL_ATTACH_NONE, "", ""
        def_ulid = defn["ulid"]          # accept id/ulid tokens uniformly
        if not force and _travel_anchor_retired(conn, "def", def_ulid):
            return TRAVEL_ATTACH_RETIRED, "", ""
        dest_id = defn.get("place_id")
        if dest_id is None:
            return TRAVEL_ATTACH_NONE, "", ""
        dest_name = _place_name(conn, dest_id)
        base = conn.execute(
            "SELECT id FROM place WHERE is_base=1;").fetchone()
        # 재택 guard FIRST, before any leg resolution: a presence def at the
        # base can never mint a rule, whatever the edge store says.
        if base is not None and dest_id == base[0]:
            return TRAVEL_ATTACH_NONE, "", dest_name
        existing = _travel_row(
            conn, "SELECT * FROM travel_rule WHERE anchor_type='def' "
            "AND anchor_ulid=? AND status != 'retired';", (def_ulid,))
        anchor = _travel_row(
            conn, "SELECT * FROM timeblock WHERE recurrence_id=? "
            "AND settled_at IS NULL ORDER BY start_at LIMIT 1;",
            (defn["recurrence_id"],))
        if anchor is None:
            # Not materialized yet -> probe the def's next scheduled instant
            # so a freshly created def still attaches (the rule then derives
            # per instance as the roller emits them).
            anchor = _travel_def_probe_anchor(conn, defn)
        if anchor is None:
            return TRAVEL_ATTACH_NONE, "", dest_name
        origin_id = _travel_origin_place_id(conn, anchor)
        origin_name = _place_name(conn, origin_id)
        # Single source of truth for "can we derive the outbound leg": the
        # deriver's own resolver against a synthetic place-sourced rule.
        synth_rule = {"before_src": "place", "place_id": dest_id,
                      "before_min": 0, "prep_min": 0}
        before_eff, _prep, edge_status, _oid = _travel_resolve_before_leg(
            conn, synth_rule, anchor)
        if edge_status == TRAVEL_EDGE_MISSING:
            # 050: NO provisional stopgap on the DEF path, deliberately. A def
            # is a recurrence: one stamped guess would derive a 60-minute block
            # per occurrence, for as long as the routine runs, and the evidence
            # this stopgap was built on is entirely about one-off appointments
            # (a wedding, a rehearsal). Scoping it here is a decision, not an
            # omission -- widen it when a recurring routine actually loses its
            # travel, not before.
            if base is not None and origin_id == base[0]:
                return TRAVEL_ATTACH_NO_DURATION, "", dest_name
            return TRAVEL_ATTACH_EDGE_MISSING, origin_name, dest_name
        if existing is not None:
            return TRAVEL_ATTACH_EXISTS, origin_name, dest_name
        # Positive grid-valid placeholder so the active-rule CHECK
        # (before_min>0 OR after_min>0) passes; the deriver overrides it from
        # presence + edge at derive time (before_src='place').
        seed_before = before_eff if before_eff > 0 else TRAVEL_GRID_MIN
        try:
            travel_rule_add(conn, "def", def_ulid, place_id=dest_id,
                            before_min=seed_before, before_src="place",
                            created_by=_facade_agent(), state_conn=state_conn)
        except sqlite3.IntegrityError as e:
            # idx_travel_rule_anchor fired: a concurrent writer attached first.
            # SQLite names the COLUMNS, not the partial index -- verified:
            # "UNIQUE constraint failed: travel_rule.anchor_type,
            # travel_rule.anchor_ulid". Match the signature, converge to
            # 'exists', never duplicate.
            if ("travel_rule.anchor_type" in str(e)
                    or "idx_travel_rule_anchor" in str(e)
                    or "UNIQUE" in str(e)):
                return TRAVEL_ATTACH_EXISTS, origin_name, dest_name
            raise
        return TRAVEL_ATTACH_ATTACHED, origin_name, dest_name
    except Exception:
        # Best-effort: an auto-attach failure must never fail the caller.
        return TRAVEL_ATTACH_ERROR, "", ""


def _local_date_of(instant, tz_name):
    """Local calendar date of a stored canonical-UTC instant."""
    return (datetime.datetime.strptime(instant, "%Y-%m-%dT%H:%M:%SZ")
            .replace(tzinfo=timezone.utc)
            .astimezone(ZoneInfo(tz_name)).date())


def _upd_overlay_time(cur_row, fields):
    """Overlay the given time endpoints onto the CURRENT row (M-2: called with
    a FRESHLY re-read row on every retry). cur_row = (schedule_kind, start_at,
    end_at, open_ended, display_tz). Returns (new_start, new_end, open_ended)
    canonical, or raises ValueError (shape mismatch E-upd-shape / bad format /
    reversed range). schedule_kind transitions are NOT reachable here.

    grill-final F-1 (framework verdict) all_day semantics -- an all_day row is a
    [start_day 00:00 local, end_day+1 00:00 local) instant RANGE, so a
    single-endpoint date update must never overlay ONE instant (that minted
    zero-length / reversed all_day rows and collapsed day-block occupancy):
      - start_at only  = DURATION-PRESERVING SHIFT: the whole range moves so it
        starts on the given date; the length in whole days is preserved
        (multi-day trips stay multi-day).
      - end_at only    = keep start; end re-derived from the given INCLUSIVE
        end date (next-midnight instant). end date < start date -> ValueError.
      - both given     = each endpoint derived from its own date;
        end < start -> ValueError.
    """
    sk, cur_start, cur_end, oe, tz = cur_row
    if sk == "all_day":
        for f in _TIME_FIELDS:
            if f in fields:
                shape = _shape_of(fields[f])
                if shape == "bad":
                    raise ValueError("bad time format: %s" % fields[f])
                if shape != "date":
                    raise ValueError(
                        "shape mismatch: use the SDK schedule_kind transition "
                        "verb to change timed<->all_day")
        # current inclusive local date range
        sd = _local_date_of(cur_start, tz)
        ed_incl = _local_date_of(cur_end, tz) - timedelta(days=1)
        duration_days = (ed_incl - sd).days + 1          # >= 1
        s_raw = fields.get("start_at")
        e_raw = fields.get("end_at")
        if s_raw is not None and e_raw is not None:
            new_sd = datetime.date.fromisoformat(s_raw)
            new_ed = datetime.date.fromisoformat(e_raw)
        elif s_raw is not None:
            # duration-preserving shift
            new_sd = datetime.date.fromisoformat(s_raw)
            new_ed = new_sd + timedelta(days=duration_days - 1)
        else:
            # end-only: keep start, shrink/extend to the given inclusive end
            new_sd = sd
            new_ed = datetime.date.fromisoformat(e_raw)
        if new_ed < new_sd:
            raise ValueError(
                "reversed all_day range refused: end %s < start %s"
                % (new_ed.isoformat(), new_sd.isoformat()))
        ns, ne = all_day_instants(new_sd.isoformat(), new_ed.isoformat(),
                                  tz_name=tz)
        return ns, ne, oe

    # timed row
    new_start, new_end = cur_start, cur_end
    for f in _TIME_FIELDS:
        if f not in fields:
            continue
        raw = fields[f]
        if f == "end_at" and str(raw).strip().lower() in ("", "none",
                                                          "unset", "-"):
            continue                 # clear token: handled after the loop
        shape = _shape_of(raw)
        if shape == "bad":
            raise ValueError("bad time format: %s" % raw)
        if shape != "datetime":
            raise ValueError(
                "shape mismatch: use the SDK schedule_kind transition verb "
                "to change timed<->all_day")
        val = _to_canonical_utc(raw)
        if f == "start_at":
            new_start = val
        else:
            new_end = val
    if "end_at" in fields and str(fields["end_at"]).strip().lower() in (
            "", "none", "unset", "-"):
        new_end = new_start          # end_at= clears the end: start only
    return new_start, new_end, oe


def cli_appt_upd(argv):
    # appt-upd <id> field=value [field=value ...]
    _u = ("사용법: kit_life.sh appt-upd <id> field=value [field=value ...]\n"
          "  field: title start_at end_at location location_url purpose summary"
          " attendance_mode meeting_url"
          " room")
    argv, room_vals = _pop_room_args(argv)          # 073: room per booking
    if len(argv) < 2 and room_vals and len(argv) == 1:
        argv = list(argv) + ["room=" + room_vals[0]]   # room-only edit
    if len(argv) < 2 or not str(argv[0]).isdigit():
        _err(_u)
    eid = int(argv[0])
    fields = {}
    for tok in argv[1:]:
        if '=' not in tok:
            _err(f"field=value 형식이 아님: {tok}\n{_u}")
        col, val = tok.split('=', 1)
        col = col.strip()
        if col == "room":
            continue                    # 073: handled after the edit
        if col not in _APPT_UPD_FIELDS:
            _err(f"수정 불가 컬럼: {col}\n{_u}")
        fields[col] = val
    if not fields and not room_vals:
        _err(_u)

    conn = event_conn()
    if _read_appt_kind(conn, eid) == "appointment":
        # 073: wrong-kind room / location residue refused before any write;
        # a location that moves the booking to ANOTHER place clears its room
        # first (the room belonged to the old place) -- ROOM_CLEARED.
        _room_kind_gate(conn, eid, room_vals, fields.get("location"))
        if "location" in fields:
            _room_clear_on_place_change(conn, eid, fields.get("location"))
    _appt_upd_ulid = None
    # DGN-274 3.5 (V5): pre-clean -> move -> UNCONDITIONAL re-derive. F-A
    # invariant: once anything may have been written (pre-clean, time or
    # meta), EVERY termination path (APPLIED / OVERLAP_REJECT / CAS
    # exhaustion / ValueError -- _err raises SystemExit) runs appt_rederive
    # before returning: success re-derives at the new position, failure at
    # the OLD position -- a failed move never kills the day's prep/departure
    # alert. appt_rederive is the one choke point (owner 2026-10-09): venue
    # -> place -> rule, the rule following a new venue, the row's legs, the
    # old and new day's neighbours and ride routines, past legs included
    # (declared: this is the owner's own edit).
    _travel_carry = None
    _appt_before = None
    _rederive_owed = False
    try:
        # M-1 kind gate: read kind ONCE; task / not-found -> legacy loud reject.
        kind = _read_appt_kind(conn, eid)
        if kind != "appointment":
            _err(f"해당 id 약속 없음: {eid}")            # E-upd-kind / E-upd-notfound
        _appt_upd_ulid = _ulid_for_event_id(conn, eid)
        _appt_before = appt_snapshot(conn, _appt_upd_ulid)

        time_fields = {k: v for k, v in fields.items() if k in _TIME_FIELDS}
        # grill-final m-4 (framework verdict): an empty field value (field=) maps to
        # NULL, matching legacy _txt semantics. title= stays a loud error (the
        # NOT NULL contract lives in timeblock_set_meta).
        meta_fields = {k: (None if (v == "" and k != "title") else v)
                       for k, v in fields.items() if k in _META_FIELDS}
        embedded_address = ''
        if meta_fields.get("location") is not None:
            meta_fields["location"] = _normalize_appt_location(
                meta_fields["location"])
            meta_fields["location"], embedded_address = _appt_split_address(meta_fields["location"])

        time_applied = False
        _had_rule = bool(_appt_upd_ulid) and _travel_rule_for_anchor_txn(
            conn, _appt_upd_ulid, (_appt_before or {}).get(
                "recurrence_id")) is not None
        # ---- time edit (event_move) with M-2 full-row re-read retry loop ----
        if time_fields:
            _arow = conn.execute(
                "SELECT ulid, recurrence_id, block_class, start_at "
                "FROM timeblock WHERE id=?;", (eid,)).fetchone()
            if (_arow is not None and _arow[2] is None
                    and _travel_rule_for_anchor_txn(
                        conn, _arow[0], _arow[1]) is not None):
                # pre-clean dodges the FG-1 slot predicate on the guarded
                # move; its pins are carried into the re-derive.
                _rederive_owed = True
                _p, _travel_carry = travel_preclean(conn, None, _arow[0])
            for attempt in range(_UPD_RETRY_MAX):
                cur = conn.execute(
                    "SELECT version, schedule_kind, start_at, end_at, "
                    "open_ended, display_tz FROM timeblock WHERE id=?;",
                    (eid,)).fetchone()
                if cur is None:
                    _err(f"해당 id 약속 없음: {eid}")
                version = cur[0]
                try:
                    ns, ne, oe = _upd_overlay_time(cur[1:], time_fields)
                    res = event_move(conn, eid, version, ns, ne, open_ended=oe)
                except ValueError as e:
                    # M-4: overlay errors AND event_move validator errors
                    # (reversed interval, all_day belt) -> loud one-liner.
                    _err(str(e))            # E-upd-shape / badfmt / reversed
                if res == MutationResult.APPLIED:
                    time_applied = True
                    _rederive_owed = True
                    break
                if res == MutationResult.OVERLAP_REJECT:
                    # DGN-579 B2: structured CONFLICT listing (self excluded
                    # -- the moved row must not list itself). E-upd-slot (U7).
                    cee = _cand_eff_end(ns, ne, oe)
                    _print_conflict_and_exit(conn, ns, cee, exclude_id=eid)
                if res == MutationResult.NOT_FOUND:
                    _err(f"해당 id 약속 없음: {eid}")
                # CAS_FAIL -> re-read full row and retry.
            else:
                _err("conflict, please retry")            # E-upd-cas (U8)
            if time_applied and _had_rule:
                # dec-021 (OQ-8): the landed schedule change supersedes
                # this anchor instance's skip rows before the re-derive.
                _travel_clear_skips(conn, _appt_upd_ulid)
                _travel_clear_pins(conn, _appt_upd_ulid)    # D3-1

        # ---- meta edit (timeblock_set_meta) retry loop -- m-3: uniform full-row
        # re-read (same discipline as the time loop; meta values are absolute
        # so the re-read is for uniformity, the version is what matters). ----
        meta_ok = False
        if meta_fields:
            fail_reason = "conflict"
            for attempt in range(_UPD_RETRY_MAX):
                cur = conn.execute(
                    "SELECT version, schedule_kind, start_at, end_at, "
                    "open_ended, display_tz FROM timeblock WHERE id=?;",
                    (eid,)).fetchone()
                if cur is None:
                    fail_reason = f"해당 id 약속 없음: {eid}"
                    break
                version = cur[0]
                try:
                    res = timeblock_set_meta(conn, eid, version, dict(meta_fields))
                except ValueError as e:
                    # M-4: kind-illegal column / empty title -> loud one-liner
                    # (or partial report if time already landed).
                    fail_reason = str(e)
                    break
                if res == MutationResult.APPLIED:
                    meta_ok = True
                    _rederive_owed = True
                    break
                if res == MutationResult.NOT_FOUND:
                    fail_reason = f"해당 id 약속 없음: {eid}"
                    break
                # CAS_FAIL -> re-read full row and retry.
            if not meta_ok:
                if time_applied:
                    # U4 partial (spec 4.4 E-upd-partial wording): time landed,
                    # metadata did not, with the concrete reason.
                    _err(f"time applied, metadata NOT applied: {fail_reason}")
                _err(fail_reason if fail_reason != "conflict"
                     else "conflict, please retry")       # E-upd-cas / loud
        if meta_ok:
            _appt_save_address(conn, _appt_upd_ulid, meta_fields.get("location"), embedded_address)
        # success line (legacy shape: id, title, location).
        row = conn.execute(
            "SELECT id, title, location FROM timeblock WHERE id=?;", (eid,)).fetchone()
        # DGN-579 B2b: primary line verbatim + mandatory MOVEMENT_OVERLAP
        # notice (time moves land the row on a possibly-new movement span).
        _print_write_result(conn, eid, f"{row[0]}\t{row[1]}\t{row[2] or ''}")
        # THE choke point, once, on the success path (the finally below
        # keeps it for an early exit) so the card printed next shows the
        # legs as they now stand.
        _rederive_owed = False
        _rd = appt_rederive(conn, _appt_upd_ulid, before=_appt_before,
                            declared=True, carry=_travel_carry)
        # A venue correction, or a time change on an appointment that had
        # no rule, is an intake event: an unanswered travel datum is owed
        # as a question (block 12844, 2026-09-11). Other edits re-derive
        # silently -- they do not re-ask what was already asked.
        _ust = _rd.get("attach") or (None, "", "")
        if (_ust[0] in _TRAVEL_ATTACH_NEEDS_ELICIT
                and ("location" in meta_fields
                     or (time_applied and not _had_rule))):
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                _ust[0], eid, _travel_signal_field(row[2]),
                _ust[1], _ust[2]))
        if time_applied or meta_ok:
            _print_retro_resolve(conn, eid)
        # 073: the room of THIS booking -- the newest owner evidence replaces
        # the stored one (REPLACED), never a "which is right?" question.
        _appt_room_after_write(conn, eid, room_vals,
                               meta_fields.get("location")
                               if "location" in meta_fields else None)
        # 2.37.0: where the owner leaves from, when it cannot be known.
        _emit_origin_ask(conn, [eid])
        _emit_prep_default_ask(conn, eid)
        # The confirmation card: the item as it now stands (new time/place).
        _print_cards(conn, [eid])
    finally:
        # F-A: unconditional re-derive on EVERY termination path after
        # anything may have been written (try/finally grade).
        if _rederive_owed and _appt_upd_ulid:
            appt_rederive(conn, _appt_upd_ulid, before=_appt_before,
                          declared=True, carry=_travel_carry)
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _appt_upd_ulid:
        _outbox_enqueue_best_effort(_appt_upd_ulid)


# -- 073: the room of a booking (block_attr sub_place_id) -----------------
# Rooms vary per booking (A2/A3/D/E at one studio, memory 2026-10-06), so the
# room belongs to the APPOINTMENT, never to the place. room= on appt-add /
# appt-upd names it; a location "<place> <room>" names it too (the 050 lift).
# A value of another kind (a band's name) is refused before any write.
def _pop_room_args(argv):
    rest, vals = [], []
    for tok in argv:
        if isinstance(tok, str) and tok.startswith("room="):
            vals.append(tok.split("=", 1)[1])
        else:
            rest.append(tok)
    if len(vals) > 1:
        _err("E_ROOM_MULTI: one booking has one room -- %d room= values in "
             "one call (%s). Ask which one only if two CURRENT sources "
             "disagree." % (len(vals), " / ".join(vals)), code=2)
    return rest, vals


def _location_residue(conn, location):
    """(place row, residue) when `location` is "<known place> <rest>" and the
    whole string is not itself a place / room on file; else (None, None)."""
    if not location or _resolve_location_place(conn, location) is not None:
        return None, None
    text = _place_norm_name(location)
    parts = text.split(" ")
    for cut in range(len(parts) - 1, 0, -1):
        head, rest = " ".join(parts[:cut]), " ".join(parts[cut:])
        place = _resolve_location_place(conn, head)
        if place is not None:
            return place, rest
    return None, None


def _room_kind_gate(conn, eid, room_vals, location):
    """Exit FIELD_KIND_CODE (8) with the refusal block when room= or the
    location residue names another kind. No-op before 073."""
    try:
        nr = _noun_mod()
        if not nr.ready(conn):
            return
    except Exception:
        return
    place_id = None
    if eid is not None:
        row = conn.execute("SELECT place_id FROM block WHERE id=?;",
                           (int(eid),)).fetchone()
        place_id = row[0] if row else None
    if location:
        p = _resolve_location_place(conn, location)
        if p is not None:
            place_id = p["id"]
    cands = [v for v in room_vals if v and v.strip()]
    if location:
        rp, residue = _location_residue(conn, location)
        if rp is not None:
            place_id = rp["id"]
            cands.append(residue)
    for text in cands:
        if place_id is not None and nr.room_match(conn, place_id, text):
            continue
        other = [h for h in nr.resolve(conn, text) if h["kind"] != "sub_place"]
        if other:
            for line in nr.field_refusal_lines(
                    sys.modules[__name__], conn, "appt.room", text, other[0],
                    eid=eid, place_id=place_id):
                print(line)
            sys.exit(nr.FIELD_KIND_CODE)


def _room_clear_on_place_change(conn, eid, location):
    try:
        nr = _noun_mod()
        if not nr.ready(conn) or nr.block_room(conn, eid) is None:
            return
        cur = conn.execute("SELECT place_id FROM block WHERE id=?;",
                           (int(eid),)).fetchone()
        p = _resolve_location_place(conn, location) if location else None
        if p is None:
            rp, _r = _location_residue(conn, location)
            p = rp
        if cur is not None and p is not None and p["id"] == cur[0]:
            return
        old = nr.block_room_clear(conn, eid)
        conn.commit()
        if old:
            print("ROOM_CLEARED\t%d\t%s" % (eid, old))
    except sqlite3.Error:
        pass


def _appt_room_after_write(conn, eid, room_vals, location):
    """Set the booking's room from room= (wins) or from the room the
    location text named. Prints the noun registry lines. Best-effort past
    the kind gate (already enforced before the write)."""
    try:
        nr = _noun_mod()
        if not nr.ready(conn):
            return
    except Exception:
        return
    text = None
    if room_vals:
        text = room_vals[0]
    elif location:
        p = _resolve_location_place(conn, location)
        if p is not None and p.get("sub_place"):
            text = p["sub_place"]["name"]
        else:
            rp, residue = _location_residue(conn, location)
            # A residue is a room CANDIDATE only when it is one word and the
            # place already has rooms ("<studio> B2-room"); "<city> <street>"
            # is an address, never a typing question.
            if (rp is not None and residue and " " not in residue
                    and nr.room_rows(conn, rp["id"])):
                row = conn.execute("SELECT place_id FROM block WHERE id=?;",
                                   (int(eid),)).fetchone()
                if row is not None and row[0] == rp["id"]:
                    text = residue
    if text is None:
        return
    try:
        lines, _code = nr.apply_room(sys.modules[__name__], conn, eid, text)
    except sqlite3.Error as e:
        print("ROOM_ERROR\t%d\t%s" % (eid, e))
        return
    for line in lines:
        print(line)


# Block kinds a person can be attached to: anything that occupies the
# user's time. 2.37.3: appt-person refused a stay ("해당 id 약속 없음"), so a
# family trip filed as a presence could not carry the family -- the agent
# cancelled the stay and re-filed it as an appointment to get the people on. A presence
# is time the user spends somewhere WITH someone as often as not; the link
# table (event_persons) never cared about kind, only the verb did. Derived
# travel/prep legs and record blocks are not the user's own commitment and
# stay refused.
BLOCK_PERSON_KINDS = ("appointment", "presence", "task")


def _block_person_target(conn, eid, verb):
    row = conn.execute("SELECT kind, block_class FROM timeblock WHERE id=?;",
                       (int(eid),)).fetchone()
    if verb.startswith("appt") and (row is None or row[0] not in
                                    BLOCK_PERSON_KINDS or row[1]):
        _err(f"해당 id 약속 없음: {eid}")            # E-person-kind
    if row is None:
        _err(f"해당 id 일정 없음: {eid}")
    if row[0] not in BLOCK_PERSON_KINDS or row[1]:
        _err(f"사람을 붙일 수 없는 블록 ({row[0]}"
             f"{'/' + row[1] if row[1] else ''}): {eid}")
    return row[0]


def _cli_block_person(argv, verb):
    # block-person <block_id> <person_id> [<person_id> ...]
    #   Several people onto one block in ONE call, so the confirmation is one
    #   card showing all of them (owner 2026-09-24 13:06: three attendees on
    #   11/7 read as one item, not three). appt-person is the same verb under
    #   its old name (alias kept for every existing caller); both accept any
    #   BLOCK_PERSON_KINDS row, appointment or presence or task.
    if (len(argv) < 2 or not all(str(a).isdigit() for a in argv)):
        _err(f"사용법: kit_life.sh {verb} <block_id> <person_id> "
             "[<person_id> ...]")
    eid, pids = int(argv[0]), [int(a) for a in argv[1:]]
    conn = event_conn()
    try:
        kind = _block_person_target(conn, eid, verb)
        # All-or-nothing for the multi form: every id is checked before the
        # first link is written, so a typo in the third id cannot leave the
        # first two linked behind a loud error.
        for pid in pids:
            if conn.execute("SELECT 1 FROM persons WHERE id=?;",
                            (pid,)).fetchone() is None:
                _err(f"no such person {pid}")             # E-person-fk
        for pid in pids:
            try:
                n = event_person_add(conn, eid, pid)
            except sqlite3.IntegrityError:
                _err(f"no such person {pid}")             # E-person-fk
        head = "appt" if verb == "appt-person" else kind
        print(f"{head} {eid} 참가자 {n}명")
        _print_cards(conn, [eid])
    finally:
        conn.close()


def _cli_block_person_rm(argv, verb):
    # block-person-rm <block_id> <person_id>
    if len(argv) < 2 or not str(argv[0]).isdigit() or not str(argv[1]).isdigit():
        _err(f"사용법: kit_life.sh {verb} <block_id> <person_id>")
    eid, pid = int(argv[0]), int(argv[1])
    conn = event_conn()
    try:
        kind = _block_person_target(conn, eid, verb)
        n = event_person_del(conn, eid, pid)
        head = "appt" if verb == "appt-person-rm" else kind
        print(f"{head} {eid} 참가자 {n}명")
        _print_cards(conn, [eid])
    finally:
        conn.close()


def cli_appt_person(argv):
    return _cli_block_person(argv, "appt-person")


def cli_appt_person_rm(argv):
    return _cli_block_person_rm(argv, "appt-person-rm")


def cli_block_person(argv):
    return _cli_block_person(argv, "block-person")


def cli_block_person_rm(argv):
    return _cli_block_person_rm(argv, "block-person-rm")


def cli_dine_choose(argv):
    # dine-choose <appt id> --facts FILE [--new-confirmed] -- the restaurant
    # picked in dining-session becomes the appointment's place (venue as a
    # kit place with its naver id / address / position, meeting point kept
    # in the note, travel re-derived by appt-upd). Body: dining_decide.py.
    import dining_decide
    dining_decide.cli(sys.modules[__name__], argv)


def cli_appt_show(argv):
    # appt-show <id> — 약속 1건 + 참가자
    if not argv or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh appt-show <id>")
    eid = int(argv[0])
    conn = event_conn()
    try:
        a = appt_show_row(conn, eid)                      # M-1: None if not appt
        if a is None:
            _err(f"해당 id 약속 없음: {eid}")            # E-show-kind
        print(APPT_CONTEXT_RELAY, file=sys.stderr)
        # a = (id, title, start_local, end_local, location, purpose, summary,
        #      retro_line)  -- retro_line appended trailing (retro-read-paths)
        print(f"{a[0]}\t{a[1]}\t{a[2] or ''}\t{a[3] or ''}\t"
              f"{a[4] or ''}\t{a[5] or ''}\t{a[6] or ''}\t{a[7]}")
        import person_labels
        for pid, name, aliases, relation in event_persons(conn, eid):
            name = person_labels.person(conn, pid)[0]
            print(f"  {pid}\t{name}\t{aliases or ''}\t{relation or ''}")
        # 073: the booking's room and its groups (machine lines, after the
        # person rows so every existing reader keeps its shape).
        try:
            nr = _noun_mod()
            if nr.ready(conn):
                room = nr.block_room(conn, eid)
                if room is not None:
                    print("ROOM\t%d\t%s" % room)
                for gid, gdisp in nr.event_groups(conn, eid):
                    print("GROUP\t%d\t%s" % (gid, gdisp))
        except sqlite3.Error:
            pass
    finally:
        conn.close()


def _appt_fetch(conn, eid):
    return conn.execute(
        "SELECT id, ulid, title, start_at, end_at, schedule_kind, display_tz, "
        "settled_outcome, settled_at, version FROM timeblock "
        "WHERE id=? AND kind='appointment';", (eid,)).fetchone()


def _resolve_appt(conn, token):
    """Accept integer id or ulid; must be an appointment row."""
    row = None
    if str(token).isdigit():
        row = _appt_fetch(conn, int(token))
    if row is None:
        r = conn.execute(
            "SELECT id FROM timeblock WHERE ulid=? AND kind='appointment';",
            (token,)).fetchone()
        if r is not None:
            row = _appt_fetch(conn, r[0])
    if row is None:
        _err(f"약속 없음: {token}")
    return row


def cli_appt_cancel(argv):
    # appt-cancel <id>  — settle appointment as abandoned (cancel / del path).
    # appt-del is a registered alias for the same operation: the event model
    # has no hard DELETE; the canonical removal path is settled_outcome='abandoned',
    # which drops the row from appt-find and the morning brief (D4 filter).
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh appt-cancel <id>")
    conn = event_conn()
    _cancel_ulid = None
    try:
        row = _resolve_appt(conn, argv[0])
        if row[7] == 'abandoned':
            _err(f"이미 취소된 약속: {row[0]}")
        _before = appt_snapshot(conn, row[1])
        res = cancel(conn, row[0], row[9], _facade_agent())
        if res != MutationResult.APPLIED:
            _err(f"appt-cancel 실패 ({res}): 이미 종결되었거나 동시 변경")
        _cancel_ulid = row[1]
        # The owner removed a stop: the one choke point re-derives its day
        # (neighbours' origin and trips home, the day prep, ride routines;
        # a past day re-chains its legs too). Never fails the cancel.
        appt_rederive(conn, row[1], before=_before, declared=True)
        print(f"{row[0]}\t{row[2]}\tcancelled")
        # Delete convention: the card of what was removed, marked removed.
        _print_cards(conn, [row[0]], removed_ids=[row[0]])
    finally:
        conn.close()
    if _cancel_ulid:
        _outbox_enqueue_best_effort(_cancel_ulid)


# ── DGN-579 presence CLI (spec A3/B4). Mirror enqueue: owner D-C3
#    (2026-07-26, presence = GCal all-day banner) REVERSES the E1 producer
#    gate -- every presence CLI verb enqueues post-commit via
#    _outbox_enqueue_best_effort (same DGN-258 pattern as the other verbs).
#    SDK-layer presence verbs still never enqueue (enqueue lives at the
#    CLI/roller producer layer only). ──────────────────────────────────────

def _presence_conflict_line(r):
    """(id, ulid, title, start_at, end_at, recurrence_id, block_class, ver)"""
    return "%s\t%s\t%s\t%s\t%s" % (
        r[0], r[1], r[2],
        _render_local_col(r[3], "timed", "Asia/Seoul"),
        _render_local_col(r[4], "timed", "Asia/Seoul"))


def _presence_parse_span(start_raw, end_raw):
    """Shared span parser: date pair -> all_day instants (inclusive end
    date); datetime pair -> timed canonical instants. Mixed shape / missing
    end -> ValueError (presence end is REQUIRED, grill B6b)."""
    if not end_raw:
        raise ValueError(
            "presence span requires an explicit end (open-ended presence "
            "is forbidden -- extend end later instead)")
    s_shape = _shape_of(start_raw)
    e_shape = _shape_of(end_raw)
    if s_shape == "bad" or e_shape == "bad":
        raise ValueError("bad time format: %s"
                         % (start_raw if s_shape == "bad" else end_raw))
    if s_shape != e_shape:
        raise ValueError("start and end must be the same shape "
                         "(both datetime or both date)")
    if s_shape == "date":
        if end_raw < start_raw:
            raise ValueError("reversed interval refused: end %s < start %s"
                             % (end_raw, start_raw))
        sa, ea = all_day_instants(start_raw, end_raw)
        return "all_day", sa, ea
    return "timed", _to_canonical_utc(start_raw), _to_canonical_utc(end_raw)


def _pop_people_args(argv):
    rest, values = [], []
    for arg in argv:
        if arg.startswith("people="):
            values.append(arg.split("=", 1)[1])
        else:
            rest.append(arg)
    if len(values) > 1:
        _err("one people= value expected (comma-separated person/group references)")
    return rest, values[0] if values else None


def _presence_people(conn, raw):
    """Resolve the whole party before writing; names must be unambiguous.
    Bare ids are persons; group:<id> and registered group names are groups.
    Empty people= explicitly clears both kinds of participation on update.
    """
    if not raw:
        return []
    nr = _noun_mod()
    party = set()
    for token in (raw or '').split(','):
        token = token.strip()
        if not token:
            continue
        kind, ref = nr.parse_ref(token)
        if ref is not None:
            kind = kind or 'person'
            if kind == 'person':
                found = conn.execute("SELECT id FROM persons WHERE id=?", (ref,)).fetchone()
            elif kind == 'group':
                found = conn.execute("SELECT id FROM person_group WHERE id=? AND status='active'",
                                     (ref,)).fetchone()
            else:
                found = None
            hits = [(kind, ref)] if found else []
        else:
            hits = [(h['kind'], h['ref']) for h in nr.resolve(
                conn, token, kinds=('person', 'group'), all_refs=True)]
        if len(hits) != 1:
            _err("people: unknown, wrong-kind, or ambiguous participant %r; "
                 "use person:<id> or group:<id>" % token)
        party.add(hits[0])
    return sorted(party)


def _presence_people_store(conn, eid, party):
    # Caller owns the transaction, including creation of the presence itself.
    conn.execute("DELETE FROM event_persons WHERE event_id=?", (eid,))
    conn.execute("DELETE FROM event_group WHERE event_id=?", (eid,))
    for kind, ref in party:
        table, col = ('event_persons', 'person_id') if kind == 'person' else ('event_group', 'group_id')
        conn.execute("INSERT INTO %s(event_id, %s) VALUES (?,?)" % (table, col), (eid, ref))


def cli_presence_upd(argv):
    """presence-upd <id|ulid> [title=...] [place=...] [people=...].
    Time changes continue to use presence-move and its travel re-derivation.
    """
    if any(a.startswith(('title=', 'place=', 'location=')) for a in argv[1:]):
        conn = event_conn()
        try:
            _schedule_correction.presence_update(sys.modules[__name__], conn, argv)
        except (ValueError, sqlite3.IntegrityError) as exc:
            _err(str(exc))
        finally:
            conn.close()
        return
    argv, people = _pop_people_args(argv)
    clear_place = "location=" in argv[1:]
    argv = [arg for arg in argv if arg != "location="]
    if len(argv) != 1 or (people is None and not clear_place):
        _err("usage: presence-upd <id|ulid> [people=<participants>] "
             "[location=] (empty location= clears the place)")
    conn = event_conn()
    try:
        eid, ulid, title, _sk, _version = _resolve_presence(conn, argv[0])
        party = _presence_people(conn, people)
        before = appt_snapshot(conn, ulid)
        if clear_place and not _is_v32(conn):
            _err("clearing a presence place requires the block-axis database")
        with conn:
            if people is not None:
                _presence_people_store(conn, eid, party)
            fields = {'updated_at': now_utc()}
            if clear_place:
                conn.execute("DELETE FROM block_attr WHERE block_id=? "
                             "AND attr_token='sub_place_id'", (eid,))
                fields.update(place_id=None, location=None, location_url=None)
            _tb_update(conn, eid, fields, bump_version=True)
        if clear_place:
            travel_core.attendance_clear_travel(
                sys.modules[__name__], conn, appt_snapshot(conn, ulid))
            appt_rederive(conn, ulid, before=before, declared=True)
        changed = "place cleared" if clear_place else "participants"
        _print_write_result(conn, eid, "%d\t%s\t%s" % (eid, title, changed))
        _print_cards(conn, [eid])
    finally:
        conn.close()
    _outbox_enqueue_best_effort(ulid)


def cli_presence_add(argv):
    # presence-add <title> <place|-> <start> <end> [people=...] [--new]
    #              [--in <event id|title|block id>]  (2026-09-30: a leg of
    #              that bundle; 2026-10-07: the id of the block it follows)
    #              [--then <block id>]  (2026-10-07: straight from this stay
    #              to that appointment -- its origin is the stay's place)
    # place '-' with --in <block id>: the stay is at that block's place.
    argv, people = _pop_people_args(argv)
    argv, force_new = _pop_flag(argv, '--new')      # B4 find-first bypass
    argv, no_place = _pop_flag(argv, '--no-place')
    argv, in_raw = _pop_opt(argv, '--in')           # outing model: bundle
    argv, then_raw = _pop_opt(argv, '--then')       # leaves for this block
    if len(argv) < 4 or not argv[0] or argv[0].lstrip().startswith('--') or not argv[1] or not argv[2] or not argv[3]:
        _err("사용법: kit_life.sh presence-add <title> <place|-> "
             "<start> <end> [--new] [--in <event id|title|block id>] "
             "[--then <block id>] [--no-place]")
    title, place_name = argv[0], argv[1]
    placeless_usage = ('for a day off / leave use presence-add "<title>" - '
                       '<date> <date> --no-place (all-day, no place); '
                       'never use "-|-"')
    if place_name.strip() == "-|-":
        _err(placeless_usage)
    if no_place and (place_name.strip() != "-" or in_raw is not None
                     or then_raw is not None):
        _err("--no-place needs place '-' and no --in / --then; " + placeless_usage)
    if place_name.strip() == "-" and not no_place and in_raw is None:
        _err("place '-' needs --in <the block this stay follows>; " + placeless_usage)
    try:
        sk, sa, ea = _presence_parse_span(argv[2], argv[3])
    except ValueError as e:
        _err(str(e))
    if in_raw is not None and sk != "timed":
        _err("--in takes a timed row only (a leg is a time block)")
    if then_raw is not None and (sk != "timed"
                                 or not str(then_raw).strip().isdigit()):
        _err("--then takes the id of the timed block the owner goes to "
             "straight from this stay")
    agent = _facade_agent()
    conn = event_conn()
    _mirror_ulids = []          # D-C3: enqueue after conn closes
    try:
        party = _presence_people(conn, people)
        bundle_id = _resolve_bundle_arg(conn, in_raw)

        def after_insert(c, eid):
            if bundle_id is not None:
                _bundle_link_hook(bundle_id)(c, eid)
            if people is not None:
                _presence_people_store(c, eid, party)
        then_id = _presence_then_target(conn, then_raw, ea)
        inherit = place_name.strip() == "-" and not no_place
        if inherit:
            pid = _presence_inherited_place(conn, bundle_id, sa)
        if not force_new:
            local_date = _local_date_of(sa, "Asia/Seoul").isoformat()
            _exists_gate(conn, title, local_date, _ff_appt_line)
        try:
            if no_place:
                pid, pname = None, ""
            elif inherit:
                pname = _place_name(conn, pid)
            else:
                pid, pname = place_upsert(conn, place_name)
            res = presence_add(conn, title, pid, sa, ea, schedule_kind=sk,
                               owning_agent=agent, created_by=agent,
                               post_insert=after_insert)
        except NearMatchError as e:
            _near_exit(e.domain, e.query, e.cands)
        except ValueError as e:
            _err(str(e))
        if res["status"] == "conflict":
            # A3/App.A-8: equal-provenance overlap -> structured PROMPT
            # listing (analog of the CONFLICT contract). Nothing written.
            print(f"PRESENCE_CONFLICT {len(res['rows'])}")
            for r in res["rows"]:
                print(_presence_conflict_line(r))
            sys.exit(CONFLICT_CODE)
        for su in res["superseded"]:
            # cross-provenance supersession: silent + one-line notice.
            print(f"SUPERSEDED {su}")
        # D-C3 mirror enqueue: new banner + superseded banners (their GCal
        # objects need the cancelled tombstone push).
        _mirror_ulids = [res["ulid"]] + list(res["superseded"])
        # Rule 2 (2026-09-30): a stay is a stop on the travel chain, so it
        # gets its arrival leg exactly like appt-add / task-add and like a
        # routine presence already does through its def rule. Timed only
        # (the anchor predicate); never for a stay at home -- coming home is
        # the previous stop's return leg, not an outing of its own.
        _tstatus, _torigin, _tdest = TRAVEL_ATTACH_NONE, "", ""
        if sk == "timed" and pid is not None and pid != _travel_base_place_id(conn):
            _tstatus, _torigin, _tdest = _travel_autoattach_appt(
                conn, res["ulid"], pname)
        if bundle_id is not None:
            _travel_refresh_bundle_neighbours(conn, res["eid"])
        _then = (_presence_then_apply(conn, then_id, pid)
                 if then_id is not None else None)
        _print_write_result(conn, res["eid"], f"{res['eid']}\t{title}\t{pname}")
        if _tstatus in _TRAVEL_ATTACH_NEEDS_ELICIT:
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                _tstatus, res["eid"], _travel_signal_field(pname),
                _torigin, _tdest))
        if _then is not None and _then[0] in _TRAVEL_ATTACH_NEEDS_ELICIT:
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                _then[0], then_id, _travel_signal_field(_then[3]),
                _then[1], _then[2]))
        # No --then: the appointment this stay runs into asks where the owner
        # leaves from (the 2.37.0 ORIGIN_ASK -- never assume home).
        _next = ([] if then_id is not None
                 else _presence_next_appt_ids(conn, res["eid"]))
        _emit_origin_ask(conn, _next)
        _emit_stay_overlap(conn, res["eid"])
        # the life agent harvest x3 (fb-1790980205-4/-5, fb-1791239400-1/-2,
        # fb-1791325804-1/-2): the verbs exist since 2.38.0, the skill text
        # routes to them, and the life agent still parks companions / birthdays / family
        # links on a stale memory note. The next write is named HERE, at the
        # stay write, with the id filled in.
        if people is None:
            print("NEXT\tblock-person %d <person_id>..." % res["eid"])
            print(STAY_NEXT_RELAY)
        # The new stay's card, then the card of every stay it superseded
        # (those were removed by this write, so they carry the marker).
        _sup_ids = [r[0] for r in (
            conn.execute("SELECT id FROM timeblock WHERE ulid=?;",
                         (u,)).fetchone() for u in res["superseded"])
            if r is not None]
        _print_cards(conn, [res["eid"]]
                     + ([then_id] if then_id is not None else [])
                     + _next + _sup_ids, removed_ids=_sup_ids)
        _capture_open_today(conn)  # arrival vs plan is judged from owner evidence
    finally:
        conn.close()
    for _u in _mirror_ulids:
        _outbox_enqueue_best_effort(_u)


# -- a stay after an appointment (owner 2026-10-07: "sleeping there Thursday,
# going straight to this appointment in the morning") -----------------------
# The owner states a fact; the stay is written, never asked about, and the
# travel rows follow from it (they are engine-owned). Three carriers:
#   --in <block id>   the stay is the next leg of that block's bundle (Rule 1:
#                     no leg between them, no trip home from the block);
#   place '-'         ... and it is at that block's place. A block with no
#                     place prints the block's PLACE_ASK and writes nothing:
#                     the one question is the place, asked once;
#   --then <block id> the owner leaves the stay straight for that block: its
#                     origin is the stay's place (the appt-origin attr), so
#                     the leg departs from there. Without it the block the
#                     stay runs into gets the ORIGIN_ASK question instead.
PLACE_NEEDED_CODE = 6
STAY_PLACE_RELAY = (
    "STAY_PLACE_RELAY Nothing was written: the stay is at the place of the "
    "block named by STAY_PLACE_NEEDED and that place is not on file. Ask "
    "ONLY the PLACE_ASK question, subject to PLACE_RELAY's menu deferral "
    "and once-per-appointment conversation gate. When the owner names it, store it "
    "(appt-upd <id> location=<name>) and re-run this same presence-add -- "
    "never ask whether to write the stay and never ask about travel rows. "
    "Never print STAY_PLACE_NEEDED or this line itself.")


def _presence_inherited_place(conn, bundle, start_at):
    """Place id for presence-add place '-': the place of the block the stay
    follows (--in <block id>, or the --in bundle's leg ending last at/before
    start_at). No place on that block -> its PLACE_ASK, exit
    PLACE_NEEDED_CODE, nothing written."""
    if bundle is None:
        _err("place '-' needs --in <the block this stay follows>; "
             'for a day off / leave use presence-add "<title>" - '
             '<date> <date> --no-place; never use "-|-"')
    if isinstance(bundle, _BlockBundle):
        bid = bundle.block_id
    else:
        ids = _bundle_event_ids(conn, bundle)
        row = conn.execute(
            "SELECT t.id FROM event_timeblock et JOIN timeblock t "
            "ON t.id = et.timeblock_id WHERE et.event_id IN (%s) "
            "AND t.settled_at IS NULL AND t.block_class IS NULL "
            "AND t.end_at IS NOT NULL AND t.end_at <= ? "
            "ORDER BY t.end_at DESC, t.id DESC LIMIT 1;"
            % ",".join("?" * len(ids)), list(ids) + [start_at]).fetchone()
        if row is None:
            _err("place '-': no leg of that bundle ends before the stay")
        bid = row[0]
    blk = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;", (bid,))
    pid = None
    if blk is not None and not _location_is_undecided(blk.get("location")):
        pid = _travel_stop_place_id(conn, blk)
    if pid is None:
        _emit_place_ask(conn, [bid])
        print("STAY_PLACE_NEEDED\t%d" % bid)
        print(STAY_PLACE_RELAY)
        sys.exit(PLACE_NEEDED_CODE)
    return pid


def _presence_then_target(conn, token, stay_end):
    """--then <block id>: a live, timed, non-derived block starting at or
    after the stay ends. None when the flag is absent; loud otherwise."""
    if token is None:
        return None
    if not _is_v32(conn):
        _err("--then: this database predates the v3.2 block axis")
    row = conn.execute(
        "SELECT id, start_at FROM timeblock WHERE id=? AND settled_at IS NULL "
        "AND block_class IS NULL AND schedule_kind='timed';",
        (int(token),)).fetchone()
    if row is None:
        _err(f"--then: no live timed block with id {token}")
    if row[1] is None or row[1] < stay_end:
        _err(f"--then: block {token} starts before the stay ends")
    return int(row[0])


def _presence_then_apply(conn, then_id, place_id):
    """Store the stay's place as then_id's origin and re-derive its legs.
    Returns (attach status, origin name, dest name, location)."""
    _appt_origin_store(conn, then_id, place_id)
    ulid, location = conn.execute(
        "SELECT ulid, location FROM timeblock WHERE id=?;",
        (then_id,)).fetchone()
    status, t_origin, t_dest = _travel_autoattach_appt(conn, ulid, location)
    if _travel_rule_for_anchor_txn(conn, ulid, None) is not None:
        travel_refresh(conn, None, ulid)
        if status == TRAVEL_ATTACH_EXISTS:
            # an existing rule re-derived from the new origin: say so when
            # that hop has no minutes on file (the one travel question).
            anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                                 (then_id,))
            rule = _travel_rule_for_anchor_txn(conn, ulid, None)
            try:
                _m, _p, st, oid = _travel_resolve_before_leg(conn, rule,
                                                             anchor)
            except Exception:  # noqa: BLE001 -- a probe never fails a write
                st, oid = None, None
            if st == TRAVEL_EDGE_MISSING and rule.get("place_id") is not None:
                status = TRAVEL_ATTACH_EDGE_MISSING
                t_origin = _place_name(conn, oid)
                t_dest = _place_name(conn, rule["place_id"])
    return status, t_origin, t_dest, location


def _presence_next_appt_ids(conn, stay_id):
    """Appointments the stay runs into whose origin is the open 'gap'
    question about THIS stay's place (appt_origin_need)."""
    try:
        stay = conn.execute("SELECT end_at, place_id FROM timeblock "
                            "WHERE id=?;", (stay_id,)).fetchone()
        if stay is None or stay[0] is None:
            return []
        hi = _iso_shift_min(stay[0], TRAVEL_ORIGIN_ASK_HORIZON_MIN)
        out = []
        for (aid,) in conn.execute(
                "SELECT id FROM timeblock WHERE kind='appointment' "
                "AND settled_at IS NULL AND block_class IS NULL "
                "AND start_at >= ? AND start_at <= ? ORDER BY start_at, id;",
                (stay[0], hi)).fetchall():
            need = appt_origin_need(conn, aid)
            if need is not None and need == ("gap", stay[1]):
                out.append(aid)
        return out
    except (sqlite3.Error, TypeError, ValueError):
        return []


def _stay_is_overnight(conn, row):
    """A user-authored presence away from home that crosses a local date."""
    if (row.get("kind") != "presence" or row.get("recurrence_id") is not None
            or row.get("block_class") is not None
            or row.get("schedule_kind") != "timed"
            or not row.get("start_at") or not row.get("end_at")):
        return False
    pid = row.get("place_id")
    if pid is None or pid == _travel_base_place_id(conn):
        return False
    return (_local_date_of(row["end_at"], TRAVEL_DISPLAY_TZ)
            > _local_date_of(row["start_at"], TRAVEL_DISPLAY_TZ))


def stay_overlaps(conn, block_id):
    """[(id, title)] of what clashes with block_id through an overnight stay.

    A stay (overnight, away from home) clashes with every live timed block
    that STARTS inside it and is not at a place of its own -- no place or the
    home place: a workout or a chore the routine put at home while the owner
    sleeps elsewhere (a Fri 06:00 workout inside the Thu->Fri stay). A block of
    the stay's own bundle, a derived leg and another stay never clash.
    For a stay this lists the clashing blocks; for any other block, the stay
    it falls in. READ ONLY; never raises."""
    try:
        row = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                          (int(block_id),))
        if row is None or row.get("settled_at") is not None:
            return []
        cols = ("SELECT * FROM timeblock WHERE settled_at IS NULL "
                "AND block_class IS NULL AND schedule_kind='timed' "
                "AND start_at IS NOT NULL AND id != ? ")
        base = _travel_base_place_id(conn)

        def _clashes(stay, other):
            if other.get("kind") == "presence":
                return False
            pid = _travel_stop_place_id(conn, other)
            if pid is not None and pid != base:
                return False
            return not _same_bundle(conn, stay["id"], other["id"])

        if row.get("kind") == "presence":
            if not _stay_is_overnight(conn, row):
                return []
            return [(o["id"], o["title"] or "") for o in _travel_rows(
                conn, cols + "AND start_at >= ? AND start_at < ? "
                "ORDER BY start_at, id;",
                (row["id"], row["start_at"], row["end_at"]))
                if _clashes(row, o)]
        if row.get("block_class") is not None or not row.get("start_at"):
            return []
        return [(st["id"], st["title"] or "") for st in _travel_rows(
            conn, cols + "AND kind='presence' AND start_at <= ? "
            "AND end_at > ? ORDER BY start_at, id;",
            (row["id"], row["start_at"], row["start_at"]))
            if _stay_is_overnight(conn, st) and _clashes(st, row)]
    except Exception:  # noqa: BLE001 -- rides every card
        return []


STAY_NEXT_RELAY = (
    "NEXT_RELAY Anyone the owner named for this stay is linked NOW, in this "
    "turn: person-resolve each, then the NEXT command with their ids (a stay "
    "carries people; never re-file it as an appointment). A birthday in the "
    "same message -> person-set <person> birthday=<as typed>; \"C is the "
    "daughter/son of A and B\" -> person-link C A child and person-link C B "
    "child, plus "
    "person-set C gender=F|M. A note saying a stay cannot carry people or "
    "that birthdays / family links need a DB edit or upstream predates kit "
    "2.38.0 and is wrong. Nobody named -> skip NEXT. Never print NEXT or "
    "this line itself.")
STAY_OVERLAP = "STAY_OVERLAP"
STAY_OVERLAP_RELAY = (
    "STAY_RELAY The block(s) named by STAY_OVERLAP start while the owner "
    "is staying elsewhere. After the card, say so in ONE short line naming "
    "them and ask whether to move or skip them; never move, skip or cancel "
    "them yourself, and never ask about travel rows. Never print "
    "STAY_OVERLAP or this line itself.")


def _emit_stay_overlap(conn, stay_id):
    """STAY_OVERLAP<TAB><id><TAB><title> per block clashing with the stay,
    then the relay. Nothing when nothing clashes."""
    rows = stay_overlaps(conn, stay_id)
    for oid, otitle in rows:
        print("%s\t%d\t%s" % (STAY_OVERLAP, oid, otitle))
    if rows:
        print(STAY_OVERLAP_RELAY)


def _resolve_presence(conn, token):
    """Accept integer id or ulid; must be a presence row. Returns
    (id, ulid, title, schedule_kind, version) or errors out."""
    row = None
    q = ("SELECT id, ulid, title, schedule_kind, version FROM timeblock "
         "WHERE %s=? AND kind='presence';")
    if str(token).isdigit():
        row = conn.execute(q % "id", (int(token),)).fetchone()
    if row is None:
        row = conn.execute(q % "ulid", (token,)).fetchone()
    if row is None:
        _err(f"presence 없음: {token}")
    return row


def cli_presence_move(argv):
    # presence-move <id|ulid> <start> <end>
    if len(argv) < 3 or not argv[0] or not argv[1] or not argv[2]:
        _err("사용법: kit_life.sh presence-move <id|ulid> <start> <end>")
    try:
        sk, sa, ea = _presence_parse_span(argv[1], argv[2])
    except ValueError as e:
        _err(str(e))
    conn = event_conn()
    _mirror_ulid = None
    try:
        row = _resolve_presence(conn, argv[0])
        eid, _ulid, title, cur_sk, _v = row
        _before = appt_snapshot(conn, _ulid)
        if sk != cur_sk:
            _err("shape mismatch: this presence row is %s "
                 "(give matching start/end shape)" % cur_sk)
        for _attempt in range(_UPD_RETRY_MAX):
            cur = conn.execute(
                "SELECT version FROM timeblock WHERE id=?;", (eid,)).fetchone()
            if cur is None:
                _err(f"presence 없음: {eid}")
            try:
                res = presence_move(conn, eid, cur[0], sa, ea)
            except ValueError as e:
                _err(str(e))
            if res == MutationResult.APPLIED:
                _mirror_ulid = _ulid     # D-C3: banner span changed
                break
            if res == MutationResult.OVERLAP_REJECT:
                # one-presence-at-a-time: moving onto a live presence span
                # is refused loudly with the blocker listing.
                cee = _cand_eff_end(sa, ea, 0)
                rows = _presence_overlapping(conn, sa, cee, exclude_id=eid)
                print(f"PRESENCE_CONFLICT {len(rows)}")
                for r in rows:
                    print(_presence_conflict_line(r))
                sys.exit(CONFLICT_CODE)
            if res == MutationResult.NOT_FOUND:
                _err(f"presence 없음: {eid}")
            # CAS_FAIL -> re-read version and retry.
        else:
            _err("conflict, please retry")
        # 2.46.0-dev.2 (trial finding 6): the chat lane moved the stay and
        # stopped there -- its legs (and a ride routine on them) stayed at
        # the old hour until the next sweep. Follow like routine_exception
        # and the mirror's inbound lane do; the counters are the refresh's
        # own (chained neighbours + day peers included), never a guess.
        # It runs BEFORE the choke point (dev.5 merge): appt_rederive's own
        # travel_refresh would otherwise do the regen first and leave this
        # audit line counting zeros.
        _follow = _presence_move_travel_follow(conn, _ulid, emit=False)
        # A stay is where the day's trips leave from: the one choke point
        # re-derives its own legs and both days' appointments.
        appt_rederive(conn, _ulid, before=_before, declared=True)
        _print_write_result(conn, eid, f"{eid}\t{title}\tmoved")
        _presence_move_travel_line(_ulid, _follow)
        _print_cards(conn, [eid])
    finally:
        conn.close()
    if _mirror_ulid:
        _outbox_enqueue_best_effort(_mirror_ulid)


def _presence_move_travel_follow(conn, ulid, emit=True):
    """presence-move's inline travel follow: travel_refresh(stay) and one
    audit line `TRAVEL\t<ulid>\tregen= created= tombstoned= moved= ride=`
    (not for the reply). Best-effort: a fault never fails the committed
    move -- the nightly / mirror-poll sweep converges -- and prints
    `TRAVEL\t<ulid>\terror` instead of made-up zeros. emit=False returns
    the summary ({"result": "error"} on a fault) for
    _presence_move_travel_line to print later."""
    if not _travel_schema_ready(conn):
        return None
    try:
        s_ = travel_refresh(conn, None, ulid)
    except Exception:  # noqa: BLE001 -- never fail a committed move
        s_ = {"result": "error"}
    if emit:
        _presence_move_travel_line(ulid, s_)
    return s_


def _presence_move_travel_line(ulid, s_):
    """The TRAVEL audit line of one _presence_move_travel_follow summary
    (nothing for None / a non-ok refresh other than an error)."""
    if s_ is None:
        return
    if s_.get("result") == "error":
        print("TRAVEL\t%s\terror" % ulid)
        return
    if s_.get("result") != "ok":
        return
    print("TRAVEL\t%s\tregen=%d created=%d tombstoned=%d moved=%d ride=%d"
          % ((ulid,) + tuple(travel_summary_total(s_, k)
                             for k in _TRAVEL_SUMMARY_COUNTS)
             + (s_.get("ride", 0),)))


def cli_presence_cancel(argv):
    # presence-cancel <id|ulid>  -- settle a presence 'abandoned' ("안 가게 됐어").
    # appt-cancel/task-* kind-gate presence out, so this is its ONLY tool
    # surface. Reuses the SDK cancel machinery; enqueues post-commit (D-C3:
    # the GCal banner needs its cancelled tombstone push).
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh presence-cancel <id|ulid>")
    conn = event_conn()
    _mirror_ulid = None
    try:
        row = _resolve_presence(conn, argv[0])
        eid, _ulid, title, _sk, ver = row
        outcome = conn.execute(
            "SELECT settled_outcome FROM timeblock WHERE id=?;", (eid,)).fetchone()[0]
        if outcome == 'abandoned':
            _err(f"이미 취소된 presence: {eid}")
        _before = appt_snapshot(conn, _ulid)
        res = cancel(conn, eid, ver, _facade_agent())
        if res != MutationResult.APPLIED:
            _err(f"presence-cancel 실패 ({res}): 이미 종결되었거나 동시 변경")
        _mirror_ulid = _ulid
        appt_rederive(conn, _ulid, before=_before, declared=True)
        print(f"{eid}\t{title}\tcancelled")
        _print_cards(conn, [eid], removed_ids=[eid])
    finally:
        conn.close()
    if _mirror_ulid:
        _outbox_enqueue_best_effort(_mirror_ulid)


def cli_presence_revive(argv):
    # presence-revive <id|ulid>  -- un-supersede an abandoned presence
    # ("역시 갈래"). Reuses the SDK unsettle lane (guarded: revival that
    # re-overlaps the live presence timeline is refused with the blockers).
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh presence-revive <id|ulid>")
    conn = event_conn()
    _mirror_ulid = None
    try:
        row = _resolve_presence(conn, argv[0])
        eid, ulid, title, _sk, _ver = row
        _before = appt_snapshot(conn, ulid)
        res, _warn = unsettle(conn, ulid, _facade_agent())
        if res == "refused":
            # guarded refusal: either not abandoned, or the old span is now
            # occupied by another live presence. Surface the blockers.
            srow = conn.execute(
                "SELECT start_at, end_at, settled_outcome FROM timeblock "
                "WHERE id=?;", (eid,)).fetchone()
            if srow[2] != 'abandoned':
                _err(f"presence-revive 실패: abandoned 상태가 아님 ({eid})")
            cee = _cand_eff_end(srow[0], srow[1], 0)
            rows = _presence_overlapping(conn, srow[0], cee, exclude_id=eid)
            print(f"PRESENCE_CONFLICT {len(rows)}")
            for r in rows:
                print(_presence_conflict_line(r))
            sys.exit(CONFLICT_CODE)
        if res != "applied":
            _err(f"presence-revive 실패 ({res})")
        _mirror_ulid = ulid              # D-C3: banner returns to GCal
        appt_rederive(conn, ulid, before=_before, declared=True)
        print(f"{eid}\t{title}\trevived")
        _print_cards(conn, [eid])
    finally:
        conn.close()
    if _mirror_ulid:
        _outbox_enqueue_best_effort(_mirror_ulid)


# -- day timeline: the rows, and the GAPS between them (2.25.0) -------------
#
# THE DERIVATION SEAT for the schedule surface. Travel stopped being a row of
# its own: it is the EXPLANATION of the gap between two rows, and the gap line
# carries BOTH the minutes that gap spends and the minutes it has left.
#
#   09:00-17:30 회사
#     ↓ 이동 30분 · 준비 15분 · 여유 15분
#   18:30-20:00 헬스
#
# WHY THE ARITHMETIC LIVES HERE. The morning brief hands data rows plus prose
# to a model and the model renders the section. Slack is clock arithmetic, and
# a model doing clock arithmetic puts a WRONG NUMBER on the owner's screen. So
# every number below is computed from stored spans in Python; the renderers
# (morning brief, pinned day card) print what they are handed, and the prose
# instruction beside the data may only say "verbatim".
#
# WHY THERE IS NO MIGRATION. A gap is (next.start - prev.end) minus the legs
# already derived into it -- three quantities this schema stores as block
# spans today. A stored copy of a derivable number is a second clock (the
# 036/039 discipline), so nothing here is persisted.
#
# WHY EVERY LEG IS NAMED. The 2026-08-25 owner ruling made the arrival buffer
# a NAMED block on purpose: an unexplained 15-minute gap is a question mark, a
# named block explains itself. Folding any leg into the leftover would undo
# exactly that -- it would tell the owner he has free minutes that are already
# spent. So a gap line names every leg it absorbs, and the leftover is what
# remains AFTER all of them.
#
# TOKEN NAMES, and the one collision worth stating out loud. The approved
# shape names the ARRIVAL BUFFER 준비. The kit also derives a leave-home
# readiness leg whose own block title is "준비: <title>" (DGN-305, role
# 'before_prep'). Two different things cannot share one token on one line, so
# the readiness leg is named 외출준비 on the gap line. No block title moves.

DAY_GAP_LEAD = "lead"     # before the first row: no previous commitment
DAY_GAP_MID = "gap"       # between two rows: the only place slack is defined
DAY_GAP_TAIL = "tail"     # after the last row: the way home

# Which derived roles a gap absorbs, and the token each is named under.
# 'before' (the move onto the next row) and 'after' (the move home off the
# previous row) are both moves. Legs are attributed by DERIVATION LINEAGE
# (derived_from), never by geometry: a leg that does not fit its gap starts
# before the previous row ends, and that overhang IS the shortfall this
# render exists to show. Clamping to the gap would hide it.
DAY_GAP_ROLE_TOKEN = {
    "before": "travel",
    "after": "travel",
    "before_prep": "prep",
    TRAVEL_ROLE_BUFFER: "buffer",
}
DAY_INCOMING_ROLES = ("before_prep", "before", TRAVEL_ROLE_BUFFER)
DAY_POS_PAST = "past"
DAY_POS_NOW = "now"
DAY_POS_AHEAD = "ahead"
# Card state selects a localized leading glyph (owner template 2026-10-16).
DAY_MARK = {DAY_POS_PAST: "day.card.mark.past", DAY_POS_NOW: "day.card.mark.now",
            DAY_POS_AHEAD: "day.card.mark.ahead"}

# Schedule rows are quoted, gap lines are not (owner ruling 2026-09-22 12:41).
# The channel merges a contiguous run of quoted lines into one blockquote, so
# an un-quoted gap line between two rows is what separates the boxes.
DAY_ROW_QUOTE = "> "

# Fallbacks for every user-facing token; the i18n bundle overrides each by
# key. '{n}' is the only placeholder.
DAY_I18N_FALLBACK = {
    "day.gap.arrow": u"↓ ",
    "day.gap.sep": u" / ",
    "day.gap.travel": u"이동 {n}분",
    "day.gap.prep": u"외출준비 {n}분",
    "day.gap.buffer": u"준비 {n}분",
    "day.gap.slack": u"여유 {n}분",
    "day.gap.exact": u"딱 맞습니다",
    "day.gap.short": u"{n}분 모자랍니다",
    "day.gap.travel_unknown": u"이동 시간 미정",
    # Two adjoining blocks at DIFFERENT places with zero minutes between them.
    # Not a slack figure and not an unknown duration -- a physical
    # impossibility the owner has to resolve, so it is worded, never numbered.
    "day.gap.no_time_to_move": u"이동 시간 없음, 장소가 바뀝니다",
    # Two consecutive legs of ONE outing (Rule 1): the owner travels with the
    # outing, so the gap names the move and nothing else.
    "day.gap.together": u"\ud568\uaed8 \uc774\ub3d9",
    "day.gap.open_unknown": u"비는 시간 {n}분",
    "day.card.header": u"\U0001f4c5 **{md}({wd})**",
    "day.card.mark.past": "\u2713",
    "day.card.mark.now": "\u2022",
    "day.card.mark.ahead": "\u2022",
    "day.card.now": u" ← 지금",
    # Suffix on the card of an item a write just REMOVED (appt-cancel,
    # presence-cancel, a superseded presence). Same slot as day.card.now.
    "day.card.removed": u" ← 취소됨",
    # Suffix on an appointment whose move leg cannot arrive with the arrival
    # buffer to spare: the leg had to start where the stay before it ends
    # (_travel_before_geometry). Same slot as day.card.now.
    "day.card.tight": u" \u2190 \ube60\ub4ef\ud574\uc694",
    # 067: a row whose start falls outside its place's known opening hours
    # (event_cards only). Same slot as day.card.tight.
    "day.card.hours_outside":
        u" \u2190 \uc601\uc5c5\uc2dc\uac04 \ubc16 ({open}~{close})",
    "day.card.hours_closed": u" \u2190 \ud734\ubb34\uc77c",
    # A block starting inside an overnight stay away from home (and the stay
    # row itself): " <- overlaps: <the other side>" (stay_overlaps).
    "day.card.stay_overlap": u" \u2190 \uacb9\uce68: {titles}",
    "day.card.hours_break":
        u" \u2190 \ud734\uac8c\uc2dc\uac04 ({start}~{end})",
    "day.card.allday": u"종일",
    # A timed appointment whose end nobody stated is stored zero-length
    # (start == end). It prints the start and says the end is open -- never
    # "17:00-17:00", and never an end the kit or the agent picked.
    "day.card.end_unset": u"{start} (종료 미정)",
    # Venue tail for an appointment with no place row: the owner's answer
    # "not decided yet" (every surface), or nobody asked yet (write cards).
    "day.card.place_undecided": u"장소 미정",
    "day.card.place_unset": u"장소 미입력",
    # A timed block that finishes on a later LOCAL date prints BOTH ends with
    # their dates. Bare HH:MM read as a backwards same-day range
    # ("23:00-17:00"); the "(+2일)" suffix that replaced it left the reader
    # counting days off the card ("10:00-12:00(+2일)" for a three-day trip).
    # The dates are the information -- print them.
    # {sdate}/{edate} = M/D, {swd}/{ewd} = day.card.weekdays entries.
    "day.card.multiday": u"{sdate}({swd}) {start} ~ {edate}({ewd}) {end}",
    # Mon..Sun, comma-joined, indexed by datetime.weekday(). One key rather
    # than seven so a locale bundle overrides the whole row or none of it.
    "day.card.weekdays": u"월,화,수,목,금,토,일",
}


def _day_i18n(key):
    return _i18n(key, DAY_I18N_FALLBACK[key])


def _day_tz(tz_name=None, tz_offset=None):
    """Display timezone for the day surface. An explicit integer offset (the
    morning brief's declared AGENT_TZ_OFFSET_HOURS) wins, then a zone name,
    then the kit display tz. An absurd offset falls back rather than
    inventing a fourth clock (the 038 discipline)."""
    if tz_offset is not None and str(tz_offset) != "":
        try:
            off = int(tz_offset)
        except (TypeError, ValueError):
            off = None
        if off is not None and -12 <= off <= 14:
            return timezone(timedelta(hours=off))
    return ZoneInfo(tz_name or TRAVEL_DISPLAY_TZ)


def _day_hm(ts, tz):
    """Canonical UTC instant -> local HH:MM ('' when absent/unparseable)."""
    if not ts:
        return ""
    try:
        return local_datetime(utc_datetime(ts, "%Y-%m-%dT%H:%M:%SZ"), tz).strftime("%H:%M")
    except (TypeError, ValueError):
        return ""


def _day_date_delta(start_ts, end_ts, tz):
    """Whole LOCAL days between two canonical UTC instants (0 when same day,
    absent, or unparseable).

    Compared on local DATES, not on elapsed hours: 23:00 -> 01:00 is one day
    later even though only two hours pass, and that is exactly the case the
    bare-HH:MM range renders as going backwards. Fail-quiet (0) keeps a bad
    timestamp from taking the day surface down -- the range then prints as it
    did before this existed.
    """
    if not start_ts or not end_ts:
        return 0
    try:
        fmt = "%Y-%m-%dT%H:%M:%SZ"
        s = local_datetime(utc_datetime(start_ts, fmt), tz).date()
        e = local_datetime(utc_datetime(end_ts, fmt), tz).date()
    except (TypeError, ValueError):
        return 0
    return (e - s).days


def _day_window(date, tz):
    """[local 00:00, next local 00:00) as canonical UTC instants."""
    day = datetime.datetime.strptime(date, "%Y-%m-%d")
    start = datetime.datetime(day.year, day.month, day.day, tzinfo=tz)
    return (start.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            (start + timedelta(days=1)).astimezone(timezone.utc)
            .strftime("%Y-%m-%dT%H:%M:%SZ"))


def _day_pos(now, start, end):
    """past / now / ahead for a [start, end) span against `now`. A span with
    no end instant (open-ended block, one-sided gap) is 'now' from its start
    onwards and never becomes past -- claiming it ended would be a guess."""
    if not now or not start:
        return DAY_POS_AHEAD
    if now < start:
        return DAY_POS_AHEAD
    if end is None or now < end:
        return DAY_POS_NOW
    return DAY_POS_PAST


def _day_travel_unknown(conn, row):
    """True when this row NEEDS a move nobody could derive -- the venue never
    resolved to a place on file, so the duration is not 0 and not estimable:
    it is UNKNOWN.

    Same question place_gap_scan answers, same primitives, same decision order
    (owner opt-out, then meeting link, then whether travel actually landed),
    so the two surfaces cannot disagree about a row. It is re-asked here
    instead of calling that scan because the scan clamps its window to the
    future and a day card also renders the morning that already happened.
    Never raises: a report surface must not kill a brief."""
    if row["kind"] != "appointment":
        return False
    if travel_core.attendance_online(sys.modules[__name__], conn, row):
        return False
    loc = _place_norm_name(row.get("location"))
    if not loc or _location_is_undecided(loc):
        return False                    # 미정: the row already says so
    try:
        if _travel_bundle_neighbour(conn, row, "prev") is not None:
            return False                # Rule 1: moves with its outing
        if not _travel_schema_ready(conn):
            return False
        if _travel_anchor_retired(conn, "event", row["ulid"]):
            return False
        if _location_link_kind(loc) == "virtual":
            return False
        if conn.execute(
                "SELECT 1 FROM timeblock WHERE block_class='travel' "
                "AND derived_from=? AND settled_at IS NULL LIMIT 1;",
                (row["ulid"],)).fetchone() is None:
            return True
        return _day_inbound_edge_missing(conn, row)
    except sqlite3.Error:
        return False                    # unknown -> never cry wolf


def _day_inbound_edge_missing(conn, row):
    """True when the row has legs but no live inbound move because the hop
    from its origin has no minutes on file (an owner-stated origin -- a stay
    the owner leaves straight from -- with no edge to the venue yet). The
    return leg alone must not read as a known move. Never raises."""
    try:
        if _appt_origin_override(conn, row["id"]) is None:
            return False
        if conn.execute(
                "SELECT 1 FROM timeblock WHERE block_class='travel' "
                "AND derived_from=? AND derived_role='before' "
                "AND settled_at IS NULL LIMIT 1;",
                (row["ulid"],)).fetchone() is not None:
            return False
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (row["id"],))
        rule = _travel_rule_for_anchor_row(conn, anchor)
        if rule is None:
            return False
        return (_travel_resolve_before_leg(conn, rule, anchor)[2]
                == TRAVEL_EDGE_MISSING)
    except Exception:  # noqa: BLE001 -- a report surface never raises
        return False


def _day_leg_minutes(legs):
    """{token: minutes} for a list of derived-leg rows. A leg with no end
    instant contributes nothing -- there is no duration to name."""
    out = {"travel": 0, "prep": 0, "buffer": 0}
    for leg in legs:
        token = DAY_GAP_ROLE_TOKEN.get(leg["derived_role"])
        if token is None or not leg["start_at"] or not leg["end_at"]:
            continue
        out[token] += max(0, _iso_diff_min(leg["end_at"], leg["start_at"]))
    return out


def _day_end_unset(rec):
    """A timed appointment stored zero-length: its end was never stated."""
    return bool(rec.get("kind") == "appointment" and not rec.get("all_day")
                and rec.get("start_at") and rec.get("start_at") == rec.get(
                    "end_at"))


def _day_gap_record(conn, prev, nxt, legs):
    """One gap record, or None when there is nothing to say about this space.

    Emits nothing for a back-to-back pair that spends no derived minutes: a
    line reading "0 travel, 0 slack" is noise, and a gap surface that prints
    on every pair becomes wallpaper the same way an always-present warning
    section does."""
    remote = any(row and travel_core.attendance_online(sys.modules[__name__], conn, row)
                 for row in (prev, nxt))
    gap_min = None
    # An appointment whose end nobody stated has no measurable space after
    # it: counting from its START would print its whole duration as 여유.
    if (prev is not None and nxt is not None and prev["end_at"]
            and not _day_end_unset(prev)):
        gap_min = _iso_diff_min(nxt["start_at"], prev["end_at"])
    if (prev is not None and nxt is not None
            and _same_bundle(conn, prev["id"], nxt["id"])):
        return _day_together_record(prev, nxt, gap_min)
    provisional = False
    for leg in legs:
        rule = _travel_rule_for_anchor_txn(conn, leg.get('derived_from'), None)
        if rule and rule.get('before_src') == TRAVEL_SRC_PROVISIONAL:
            provisional = True
            break
    mins = _day_leg_minutes(legs)
    consumed = mins["travel"] + mins["prep"] + mins["buffer"]
    unknown = provisional or bool(nxt is not None and _day_travel_unknown(conn, nxt))
    # Slack is defined only between TWO rows with a known envelope. A lead or
    # tail gap has one endpoint (no previous commitment to measure against),
    # and an unknown move has no envelope at all.
    slack_min = None
    if gap_min is not None and not unknown:
        slack_min = gap_min - consumed
    # A back-to-back pair that CHANGES PLACE with no minutes between them is
    # the one zero-gap case that must still speak. Measured on the owner's
    # 2026-09-24 day: a dinner with a friend ended 23:00 at a station and a
    # family visit started 23:00 across town, and this surface printed NOTHING
    # between them -- silence
    # that reads as "nothing to arrange" while asserting teleportation. Zero
    # slack is only quiet when the body does not have to move.
    moved = bool(not remote and prev is not None and nxt is not None
                 and (prev.get("place") or "") and (nxt.get("place") or "")
                 and prev["place"] != nxt["place"])
    if not consumed and not unknown and (gap_min is None or gap_min <= 0):
        if not (moved and gap_min == 0):
            return None
    # OVERLAP (gap_min < 0): the next row STARTS BEFORE the previous one ends
    # -- a nested or stacked pair. Measured on live data 2026-09-22: 체중측정
    # 05:00-05:10 sits inside 헬스 05:00-07:00, and this surface rendered
    # "이동 15분 · 25분 모자랍니다" about the space between them. There is no
    # such space: every minute attributed to it is an artifact of leg lineage,
    # not a measurement of this pair, and the owner cannot act on a shortfall
    # in a gap that does not exist. A shortfall means legs OVERFLOW a real gap
    # (gap_min >= 0 and slack < 0); a negative gap is a different fact and this
    # line does not claim it.
    if gap_min is not None and gap_min < 0:
        return None
    kind = (DAY_GAP_MID if prev is not None and nxt is not None
            else DAY_GAP_LEAD if prev is None else DAY_GAP_TAIL)
    leg_starts = [l["start_at"] for l in legs if l["start_at"]]
    leg_ends = [l["end_at"] for l in legs if l["end_at"]]
    pos_start = (prev["end_at"] if prev is not None
                 else (min(leg_starts) if leg_starts else None))
    pos_end = (nxt["start_at"] if nxt is not None
               else (max(leg_ends) if leg_ends else None))
    return {"type": "gap", "gap_kind": kind,
            "prev_id": prev["id"] if prev else None,
            "prev_ulid": prev["ulid"] if prev else None,
            "prev_end": prev["end_at"] if prev else None,
            "next_id": nxt["id"] if nxt else None,
            "next_ulid": nxt["ulid"] if nxt else None,
            "next_start": nxt["start_at"] if nxt else None,
            "gap_min": gap_min,
            "travel_min": mins["travel"], "prep_min": mins["prep"],
            "buffer_min": mins["buffer"], "slack_min": slack_min,
            "travel_unknown": unknown, "provisional": provisional,
            # Only when NOTHING was derived for the move: a derived leg that
            # overflows the zero gap is a measured shortfall ("move 45 min .
            # 45 min short"), and the line says that instead.
            "place_change_no_time": bool(moved and gap_min == 0
                                         and not consumed),
            "leg_ids": sorted(l["id"] for l in legs),
            "pos": DAY_POS_AHEAD,
            "_pos_start": pos_start, "_pos_end": pos_end}


def _day_together_record(prev, nxt, gap_min):
    """Rule 1 on the card: two consecutive legs of one outing. The owner
    moves WITH the outing, so there is no travel figure, no slack and no
    "place changes" warning to print -- but a change of place is never
    silent either (silence there reads as teleportation), so it prints one
    token, day.gap.together. Same place with no gap between says nothing, exactly
    like any other back-to-back pair; an overlap says nothing either."""
    if gap_min is None or gap_min < 0:
        return None
    moved = (prev.get("place") or "") != (nxt.get("place") or "")
    if gap_min == 0 and not moved:
        return None
    return {"type": "gap", "gap_kind": DAY_GAP_MID,
            "prev_id": prev["id"], "prev_ulid": prev["ulid"],
            "prev_end": prev["end_at"], "next_id": nxt["id"],
            "next_ulid": nxt["ulid"], "next_start": nxt["start_at"],
            "gap_min": gap_min, "travel_min": 0, "prep_min": 0,
            "buffer_min": 0, "slack_min": None, "travel_unknown": False,
            "place_change_no_time": False, "move_together": True,
            "leg_ids": [], "pos": DAY_POS_AHEAD,
            "_pos_start": prev["end_at"], "_pos_end": nxt["start_at"]}


# A return leg that starts before this local hour belongs to the night
# before: it stays on the card of the day its row is on (2.29 F9 boundary,
# same knob name).
DAY_NIGHT_CUTOFF_H = agent_conf.conf_int("LIFEKIT_LEG_NIGHT_CUTOFF_H", 6)


def day_timeline(conn, since, until, now=None, tz_name=None, tz_offset=None,
                 exclude_prefixes=(), ids=None, include_helpers=False):
    """Ordered day rows + gap records, after repairing stale attendance travel.

    Returns {'since','until','now','rows','items'} where items is a
    wall-clock-ordered list of records:

      {'type':'row', id, ulid, kind, title, start_at, end_at, start_hm,
                     end_hm, place, people, all_day, pos}
      {'type':'gap', gap_kind, prev_id, prev_ulid, prev_end, next_id,
                     next_ulid, next_start, gap_min, travel_min, prep_min,
                     buffer_min, slack_min, travel_unknown, leg_ids, pos}

    gap_min / slack_min are None where the arithmetic is UNDEFINED -- never 0.
    travel_unknown marks the honest lane: a venue that never resolved to a
    place on file has an unknown move, not a zero one.

    all_day rows ride at the head of the list and are NEVER links in the gap
    chain: a date-only block occupies no clock minutes, so threading one
    between two timed rows would fabricate a gap that does not exist.

    ids -- the WRITE-CONFIRMATION lane (event_cards). Selects exactly these
    blocks, whatever their day and whether or not they are settled (a
    cancelled appointment's card is the confirmation of its removal; a past
    block may already be settled), and ignores since/until. Every row then
    goes through the same enrichment below, so its rendered line is the line
    the day card prints for it -- there is no second row builder."""
    travel_core.attendance_touch(sys.modules[__name__], conn, ids=ids, since=since, until=until, now=now)
    tz = _day_tz(tz_name, tz_offset)
    out = {"since": since, "until": until, "now": now, "rows": [],
           "items": []}
    prefixes = [p for p in (exclude_prefixes or ()) if p]
    try:
        if ids is not None:
            id_list = [int(i) for i in ids]
            if not id_list:
                return out
            raw = conn.execute(
                "SELECT id, ulid, kind, title, start_at, end_at, "
                "schedule_kind, block_class, location "
                "FROM timeblock WHERE start_at IS NOT NULL AND id IN (%s) "
                "ORDER BY start_at, id;" % ",".join("?" * len(id_list)),
                id_list).fetchall()
        else:
            raw = conn.execute(
                "SELECT id, ulid, kind, title, start_at, end_at, "
                "schedule_kind, block_class, location "
                "FROM timeblock "
                "WHERE settled_at IS NULL AND start_at IS NOT NULL "
                "AND start_at >= ? AND start_at < ? "
                "ORDER BY start_at, id;", (since, until)).fetchall()
    except sqlite3.Error:
        return out                      # a report surface never kills a brief
    rows, alldays = [], []
    for bid, ulid, kind, title, sa, ea, sk, bclass, loc in raw:
        if bclass == TRAVEL_BLOCK_CLASS and not include_helpers:
            continue                    # travel is the GAP's story, not a row
        if any((title or "").lstrip().startswith(p) for p in prefixes):
            continue
        rec = {"type": "row", "id": bid, "ulid": ulid, "kind": kind,
               "title": title or "", "start_at": sa, "end_at": ea,
               "location": loc, "place": "", "people": "",
               "all_day": sk == "all_day", "pos": DAY_POS_AHEAD,
               "start_hm": "", "end_hm": ""}
        (alldays if rec["all_day"] else rows).append(rec)
    if not rows and not alldays:
        return out
    # Place name + participants: the ' place / people' tail the schedule line
    # already carries (D27). Read through the same seams event-window uses --
    # raw sqlite on the place table would be an access-rule violation.
    for rec in rows + alldays:
        try:
            prow = conn.execute(
                "SELECT p.name, p.is_base, e.schedule_kind FROM timeblock e LEFT JOIN place p "
                "ON p.id = e.place_id WHERE e.id=?;", (rec["id"],)).fetchone()
            rec["place"] = (prow[0] if prow else None) or ""
            rec["place"] = _presence_place_text(rec["kind"], rec["place"])
            if prow:
                rec["title"] = presence_label(
                    rec["kind"], rec["title"], prow[2],
                    prow[1] if rec["place"] else None)
            # No place row: a name-shaped venue text is still where it is
            # (a one-off venue on a past outing is never registered, owner
            # 2026-10-05). Links, blobs and the undecided token keep their own handling.
            if not rec["place"] and _location_text_shows(rec.get("location")):
                rec["place"] = _place_norm_name(rec["location"])
            rec["place"] = _presence_place_text(rec["kind"], rec["place"])
            anchor = appt_snapshot(conn, rec["ulid"])
            if anchor and travel_core.attendance_online(sys.modules[__name__], conn, anchor):
                rec["online"] = True
                rec["place"] = (rec.get("location") or
                                travel_core.attendance_details(conn, anchor).get("meeting_url") or "")
            rec["people"] = _event_people_names(conn, rec["id"])
            _card_room_and_groups(conn, rec)
        except sqlite3.Error:
            pass
        # An errand (a no-time task at a place, owner 2026-10-06/07) shows
        # its deadline instead of the all-day label, and its slack only
        # when it is tight (errand.py). No buffer, no visit time.
        if rec["all_day"] and rec["kind"] == "task":
            bits = _errand_card_bits(conn, rec["id"], now=now)
            if bits is not None:
                rec["deadline_head"], rec["errand_note"] = bits
        # A block that starts inside an overnight stay away from home (or the
        # stay holding it): the clash is on the card, never silent.
        if not rec["all_day"]:
            rec["stay_overlap"] = [t for _i, t in stay_overlaps(
                conn, rec["id"])]
    legs_by_anchor = {}
    if rows:
        marks = ",".join("?" * len(rows))
        try:
            for lid, dfrom, role, lsa, lea in conn.execute(
                    "SELECT id, derived_from, derived_role, start_at, end_at "
                    "FROM timeblock WHERE block_class=? AND settled_at IS NULL "
                    "AND derived_role IS NOT NULL AND derived_from IN (%s);"
                    % marks,
                    [TRAVEL_BLOCK_CLASS] + [r["ulid"] for r in rows]):
                legs_by_anchor.setdefault(dfrom, []).append(
                    {"id": lid, "derived_role": role,
                     "start_at": lsa, "end_at": lea})
        except sqlite3.Error:
            legs_by_anchor = {}
    # A MULTI-DAY STAY'S TRIP HOME (owner ruling 2026-09-30). The return leg
    # of a row that ends on a later day is that later day's story: the
    # 09-24 -> 09-26 family-home stay printed "move 75 min" under its 09-24 row, two
    # days before anyone moves. On the window lane an 'after' leg belongs to
    # the card whose window holds its START -- dropped here when it starts
    # past the window, and carried in below on the day it does start. The
    # ids lane (write confirmation) has no day window and keeps every leg.
    # The night is the day's own: a return leg that starts after midnight
    # but before DAY_NIGHT_CUTOFF_H (a night out ending 00:30) stays under
    # its row, so the card-day of a return leg is the local date of
    # (leg start - cutoff). Ported from the 2.29 past-midnight guard.
    windowed = ids is None and since is not None and until is not None
    if windowed:
        _cut = 60 * max(0, min(DAY_NIGHT_CUTOFF_H, 23))
        _since_c = _iso_shift_min(since, _cut)
        _until_c = _iso_shift_min(until, _cut)
        for _ulid, _ls in legs_by_anchor.items():
            _ls[:] = [l for l in _ls if not (
                l["derived_role"] == "after" and l["start_at"]
                and l["start_at"] >= _until_c)]
    carried = []
    if windowed:
        carried = _day_carried_returns(conn, _since_c, _until_c,
                                       [r["ulid"] for r in rows],
                                       anchor_before=since)

    remote_ulids = {r["ulid"] for r in rows if r.get("online")}

    def _legs(ulid, roles):
        if ulid in remote_ulids:
            return []
        return [l for l in legs_by_anchor.get(ulid, ())
                if l["derived_role"] in roles]

    for rec in alldays:
        out["items"].append(rec)
    for idx, row in enumerate(rows):
        prev = rows[idx - 1] if idx else None
        legs = _legs(row["ulid"], DAY_INCOMING_ROLES)
        if row.get("kind") == "appointment" and row.get("place"):
            before = next((l for l in legs
                           if l["derived_role"] == "before"
                           and l.get("start_at") and l.get("end_at")), None)
            if before is not None:
                duration = max(0, _iso_diff_min(before["end_at"],
                                                before["start_at"]))
                if duration:
                    anchor = _travel_row(
                        conn, "SELECT * FROM timeblock WHERE id=?", (row["id"],))
                    origin_id, dest_id = _travel_leg_places(conn, "before", anchor)
                    mode = (_config_stored(conn, "travel_mode") or "").lower()
                    if mode in TRAVEL_MODE_CARD_TEXT:
                        row["card_travel"] = {
                            "departure": _day_hm(before["start_at"], tz),
                            "arrival": _day_hm(before["end_at"], tz),
                            "minutes": duration,
                            "mode": TRAVEL_MODE_CARD_TEXT[mode],
                            "buffer": max(0, _iso_diff_min(
                                row["start_at"], before["end_at"])),
                            "map_button": _card_map_button(conn, origin_id, dest_id),
                        }
        row["tight"] = _day_row_tight(row, legs, conn)
        if row.get('kind') == 'appointment' and row['tight']:
            import appointment_buffer
            anchor = _travel_row(conn, 'SELECT * FROM timeblock WHERE id=?', (row['id'],))
            pref = appointment_buffer.resolve(sys.modules[__name__], conn, anchor)
            for leg in legs:
                if (pref['strict'] and leg['derived_role'] == 'before'
                        and leg.get('start_at') and leg.get('end_at')
                        and not appointment_buffer.late(sys.modules[__name__], conn,
                                                        anchor, (leg['start_at'], leg['end_at']))):
                    margin = max(0, _iso_diff_min(row['start_at'], leg['end_at']))
                    row['buffer_note'] = _i18n('buffer.squeeze').format(n=margin)
        if prev is not None:
            legs = legs + _legs(prev["ulid"], ("after",))
        gap = _day_gap_record(conn, prev, row, legs)
        if gap is not None:
            out["items"].append(gap)
        row["start_hm"] = _day_hm(row["start_at"], tz)
        row["end_hm"] = _day_hm(row["end_at"], tz)
        row["end_day_offset"] = _day_date_delta(row["start_at"],
                                                row["end_at"], tz)
        if row["end_day_offset"] > 0:
            row["start_local"] = _day_local_date(row["start_at"], tz)
            row["end_local"] = _day_local_date(row["end_at"], tz)
        out["items"].append(row)
    if rows:
        last = rows[-1]
        tail = _day_gap_record(conn, last, None, _legs(last["ulid"],
                                                      ("after",)))
        if tail is not None:
            out["items"].append(tail)
    for prev, legs in carried:
        rec = _day_gap_record(conn, prev, None, legs)
        if rec is None:
            continue
        # Wall-clock slot: in front of the first timed row that starts at or
        # after the stay ends, and in front of that row's own lead-in gap.
        at = len(out["items"])
        for i, item in enumerate(out["items"]):
            if (item["type"] == "row" and not item["all_day"]
                    and item["start_at"] >= prev["end_at"]):
                at = i
                if i and out["items"][i - 1]["type"] == "gap":
                    at = i - 1
                break
        out["items"].insert(at, rec)
    if now:
        for rec in out["items"]:
            if rec["type"] == "row":
                rec["pos"] = _day_pos(now, rec["start_at"], rec["end_at"])
            else:
                rec["pos"] = _day_pos(now, rec["_pos_start"], rec["_pos_end"])
    for rec in out["items"]:
        rec.pop("_pos_start", None)
        rec.pop("_pos_end", None)
    out["rows"] = rows
    return out


def _day_row_tight(row, legs, conn=None):
    """True when the row's own move leg arrives later than the arrival buffer
    allows (start - _travel_appt_buffer_min). Only appointments carry the
    buffer; no move leg -> never tight."""
    if conn is not None and row.get('kind') == 'appointment':
        import appointment_buffer
        anchor = _travel_row(conn, 'SELECT * FROM timeblock WHERE id=?', (row['id'],))
        for leg in legs:
            if (leg['derived_role'] == 'before' and leg.get('start_at') and leg.get('end_at')
                    and appointment_buffer.late(sys.modules[__name__], conn, anchor,
                                                (leg['start_at'], leg['end_at']))):
                return True
        rule = appointment_buffer.resolve(sys.modules[__name__], conn, row)
        if not rule['strict']:
            return False
    buf = _travel_appt_buffer_min(row, conn)
    if buf <= 0 or not row.get("start_at"):
        return False
    want = _iso_shift_min(row["start_at"], -buf)
    return any(l["derived_role"] == "before" and l["end_at"]
               and l["end_at"] > want for l in legs)


def _day_carried_returns(conn, since, until, on_card_ulids,
                         anchor_before=None):
    """[(prev, legs)] for every live return leg ('after') that starts inside
    [since, until) off an anchor that started BEFORE anchor_before (default
    since) -- a multi-day stay coming to its end on this day. day_timeline
    passes the window shifted by DAY_NIGHT_CUTOFF_H and the card's own
    midnight as anchor_before. prev carries what _day_gap_record
    reads off a row (id, ulid, end_at, place); the row itself is not on this
    card. Never raises: a report surface must not kill a brief."""
    out = []
    try:
        found = conn.execute(
            "SELECT l.id, l.derived_role, l.start_at, l.end_at, "
            "a.id, a.ulid, a.end_at, p.name "
            "FROM timeblock l JOIN timeblock a ON a.ulid = l.derived_from "
            "LEFT JOIN place p ON p.id = a.place_id "
            "WHERE l.block_class=? AND l.settled_at IS NULL "
            "AND l.derived_role='after' AND l.start_at >= ? "
            "AND l.start_at < ? AND a.settled_at IS NULL "
            "AND a.block_class IS NULL AND a.start_at < ? "
            "ORDER BY a.end_at, l.start_at;",
            (TRAVEL_BLOCK_CLASS, since, until,
             anchor_before or since)).fetchall()
    except sqlite3.Error:
        return out
    by_anchor = {}
    for lid, role, lsa, lea, aid, aulid, aea, pname in found:
        if aulid in on_card_ulids or not aea:
            continue
        if aulid not in by_anchor:
            by_anchor[aulid] = ({"id": aid, "ulid": aulid, "end_at": aea,
                                 "place": pname or ""}, [])
            out.append(by_anchor[aulid])
        by_anchor[aulid][1].append({"id": lid, "derived_role": role,
                                    "start_at": lsa, "end_at": lea})
    return out


def day_gap_text(rec):
    """A gap record's tokens as ONE string -- no arrow, no indent.

    Token order is wall-clock order (외출준비 -> 이동 -> 준비), then the
    leftover. A zero-minute leg prints NO token: '준비 0분' is noise, and the
    ruling that made the buffer a named block never asked for a named
    absence. Leftover wording, one rendering each and no overlap:
        K  > 0  ->  여유 K분
        K == 0  ->  딱 맞습니다
        K  < 0  ->  |K|분 모자랍니다
    Zero is worded, not numbered, on purpose: '여유 0분' asks the reader to
    notice a digit before he learns there is no room, and this line exists to
    be read at a glance.

    UNKNOWN travel never produces a 여유 token. It prints 이동 시간 미정 and,
    when the space itself is measurable, 비는 시간 N분 -- deliberately not the
    word 여유, so an unknown move can never be read as confirmed slack. The
    action stays on the existing honest lane (the brief's travel-gap list)."""
    sep = _day_i18n("day.gap.sep")
    if rec.get("provisional"):
        return _i18n('travel.provisional.card', 'Travel time is being checked; time reserved for now.')
    if rec.get("move_together"):
        return _day_i18n("day.gap.together")
    tokens = []
    if rec["prep_min"]:
        tokens.append(_day_i18n("day.gap.prep").format(n=rec["prep_min"]))
    if rec.get("place_change_no_time"):
        # Leads the line: the reader must meet the impossibility before any
        # number. Returns immediately -- a 딱 맞습니다 next to it would read
        # as "this works", which is the opposite of the fact.
        return _day_i18n("day.gap.no_time_to_move")
    if rec["travel_unknown"]:
        tokens.append(_day_i18n("day.gap.travel_unknown"))
    elif rec["travel_min"]:
        tokens.append(_day_i18n("day.gap.travel").format(n=rec["travel_min"]))
    if rec["buffer_min"]:
        tokens.append(_day_i18n("day.gap.buffer").format(n=rec["buffer_min"]))
    if rec["travel_unknown"]:
        if rec["gap_min"] is not None and rec["gap_min"] > 0:
            tokens.append(_day_i18n("day.gap.open_unknown")
                          .format(n=rec["gap_min"]))
    elif rec["slack_min"] is not None:
        k = rec["slack_min"]
        if k > 0:
            tokens.append(_day_i18n("day.gap.slack").format(n=k))
        elif k == 0:
            tokens.append(_day_i18n("day.gap.exact"))
        else:
            tokens.append(_day_i18n("day.gap.short").format(n=-k))
    return sep.join(tokens)


def _day_multiday_head(rec):
    """'11/27(금) 10:00 ~ 11/29(일) 12:00' for a timed block whose end is on a
    later local date; None when the parts are missing (caller falls back)."""
    try:
        wds = _day_i18n("day.card.weekdays").split(",")
        sd, ed = rec["start_local"], rec["end_local"]
        parts = dict(sdate="%d/%d" % (sd.month, sd.day), swd=wds[sd.weekday()],
                     start=rec["start_hm"], edate="%d/%d" % (ed.month, ed.day),
                     ewd=wds[ed.weekday()], end=rec["end_hm"])
    except (AttributeError, IndexError, KeyError, TypeError):
        return None
    try:
        return _day_i18n("day.card.multiday").format(**parts)
    except (KeyError, IndexError, ValueError):
        return DAY_I18N_FALLBACK["day.card.multiday"].format(**parts)


def _day_local_date(ts, tz):
    """Canonical UTC instant -> local date (None when absent/unparseable)."""
    if not ts:
        return None
    try:
        return (datetime.datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")
                .replace(tzinfo=timezone.utc).astimezone(tz).date())
    except (TypeError, ValueError):
        return None


def _day_row_text(rec, sep, rng_fmt):
    """Schedule heading; an enriched roster is rendered on the following rows."""
    place = rec["place"]
    if not place and rec.get("kind") == "appointment":
        if _location_is_undecided(rec.get("location")):
            place = _day_i18n("day.card.place_undecided")
        elif rec.get("place_unset"):
            place = _day_i18n("day.card.place_unset")
    # A place named like the block itself (a presence titled after its
    # place, the life agent 2026-10-06 "08:30-17:00 X - X") says the word twice. Once.
    if place and place.strip() == (rec["title"] or "").strip():
        place = ""
    roster = rec.get("participant_lines")
    row_sep = " / " if roster else sep
    tail = "".join(row_sep + part for part in
                   ((place,) if roster is not None else (place, rec["people"]))
                   if part)
    if rec["all_day"]:
        # A dated to-do with no time is not an all-day EVENT: it prints bare
        # (owner 2026-10-12 06:46: "why all-day..").
        # "all-day" stays for appointments / blocks the owner called all-day.
        head = rec.get("deadline_head") or (
            "" if rec.get("kind") == "task" else _day_i18n("day.card.allday"))
    elif (rec.get("kind") == "task" and rec["start_hm"]
          and rec.get("start_at") and rec.get("start_at") == rec.get("end_at")):
        head = rec["start_hm"]      # a to-do's time with no stated end
    elif _day_end_unset(rec) and rec["start_hm"]:
        try:
            head = _day_i18n("day.card.end_unset").format(
                start=rec["start_hm"])
        except (KeyError, IndexError, ValueError):
            head = rec["start_hm"]
    elif rec["start_hm"] and rec["end_hm"]:
        # A block that ends on a LATER local date renders its end as bare
        # HH:MM, which reads as a backwards same-day range: a 2-night stay
        # (09-24 23:00 -> 09-26 17:00) printed as "23:00-17:00". Measured on
        # the owner's 2026-09-24 brief. The date is the part being dropped,
        # so both ends print with their dates (_day_multiday_head).
        end_hm = rec["end_hm"]
        span = rec.get("end_day_offset") or 0
        head = None
        if span > 0 and rec.get("start_local") and rec.get("end_local"):
            head = _day_multiday_head(rec)
        if head is None:
            try:
                head = rng_fmt.format(start=rec["start_hm"], end=end_hm)
            except (KeyError, IndexError, ValueError):
                # A locale override with a wrong placeholder must not take
                # the whole day surface down -- fall back to the built-in.
                head = rec["start_hm"] + "-" + end_hm
    else:
        head = rec["start_hm"]
    title = rec["title"].replace("·", "/") if roster else rec["title"]
    return ("%s %s%s" % (head, title, tail)) if head else (title + tail)


def _appointment_card_travel_lines(travel):
    """Approved appointment detail lines, without a quote container."""
    departure = u"⬇️ {departure} 출발 / {mode} {minutes}분".format(**travel)
    arrival = u"• 도착 {arrival}".format(**travel)
    if travel["buffer"] > 0:
        arrival += u" / 시작 {buffer}분 전".format(**travel)
    return [departure, arrival]


def day_render(timeline, mode="card", date=None, separator=None):
    """Render a day_timeline() result.

    mode 'plain' -- the morning brief's block: '- ' bullets with the gap line
                    indented under the row it precedes. No markers: the brief
                    is a snapshot sent once, at dawn.
    mode 'card'  -- the pinned dashboard card: a header line plus past / now /
                    ahead markers, so one pinned message reads as a calendar
                    as the day advances.
    Returns '' when there is nothing to show. An empty card CLEARS the pin
    section rather than pinning an empty box. separator lets a later approved
    surface retain its own punctuation while reusing the shared row layout."""
    sep = (_i18n("schedule.line.sep", u" / ")
           if separator is None else separator)
    rng_fmt = _i18n("schedule.time_range", "{start}-{end}")
    arrow = _day_i18n("day.gap.arrow")
    head_lines = []
    if mode == "card" and date:
        try:
            day = datetime.datetime.strptime(date, "%Y-%m-%d")
            md = "%d/%d" % (day.month, day.day)
            wd = _day_i18n("day.card.weekdays").split(",")[day.weekday()]
        except (TypeError, ValueError, IndexError):
            md, wd = date, ""
        head_lines.append(_day_i18n("day.card.header")
                          .format(date=date, md=md, wd=wd))
    body, run = [], []
    list_mode = sum(r['type'] == 'row' for r in timeline['items']) > 1
    def flush():
        if run:
            from item_grouping import markdown_items
            body.append(markdown_items(run))
            run.clear()
    for rec in timeline["items"]:
        if rec["type"] == "gap":
            text = day_gap_text(rec)
            if not text:
                continue
            flush()
            text = "  " + arrow + text
            if mode == "card" and rec["pos"] == DAY_POS_NOW:
                text += _day_i18n("day.card.now")
            body.append(text)
            continue
        # Card A's old metadata join remains for rows without a roster.
        # Participant-bearing headings use the approved slash in _day_row_text.
        row_sep = (" \u00b7 " if separator is None and mode == "card"
                   and (rec.get("kind") == "appointment" or rec.get("card_a"))
                   else sep)
        text = _day_row_text(rec, row_sep, rng_fmt)
        # card_a: the time-block mutation card (timeblock_card.py) draws any
        # kind in the appointment card A body -- no pos marker, no live-position
        # suffix (the state line above it, not the clock, says what happened).
        card_a = bool(mode == "card" and rec.get("card_a"))
        appointment_card = (mode == "card" and (rec.get("kind") == "appointment"
                                                or card_a))
        if mode == "card":
            if not appointment_card:
                text = "%s %s" % (_day_i18n(DAY_MARK[rec["pos"]]), text)
            if card_a:
                pass
            elif rec.get("removed"):
                # Write confirmation of a cancel/delete (event_cards). Same
                # slot and arrow as the '지금' suffix, and it replaces it: a
                # removed row is not where the day is standing.
                text += _day_i18n("day.card.removed")
            # An all-day band spans the whole day; marking it '지금' would
            # point at a row the owner is not standing on.
            elif rec["pos"] == DAY_POS_NOW and not rec["all_day"]:
                text += _day_i18n("day.card.now")
            elif rec.get('buffer_note') and rec['pos'] == DAY_POS_AHEAD:
                text += ' ' + rec['buffer_note']
            elif rec.get("tight") and rec["pos"] == DAY_POS_AHEAD:
                text += _day_i18n("day.card.tight")
            elif rec.get("errand_note"):
                text += rec["errand_note"]
            if rec.get("hours_flag"):
                text += rec["hours_flag"]
            if rec.get("stay_overlap") and not rec.get("removed"):
                text += _day_i18n("day.card.stay_overlap").format(
                    titles=", ".join(rec["stay_overlap"]))
        elif not rec.get("participant_lines"):
            text = "- " + text
        # QUOTED ROWS (owner ruling 2026-09-22 12:41 "일정 인용블록으로 나오면
        # 좋겠어"): a schedule row is quoted, a gap line is not. Contiguous
        # quoted lines merge into ONE blockquote on the channel, and every
        # rendered gap line breaks that run -- so each commitment reads as its
        # own box and the space between boxes is what the gap spends. Rows with
        # no gap line between them (nested or back-to-back) share a box, which
        # is what they are. Cosmetic only: the same lines, same order, same
        # numbers.
        item_start = len(body)
        body.append(DAY_ROW_QUOTE + text)
        body.extend(DAY_ROW_QUOTE + line for line in rec.get("participant_lines", ()))
        travel = rec.get("card_travel") if appointment_card else None
        if travel:
            body.extend(DAY_ROW_QUOTE + line
                        for line in _appointment_card_travel_lines(travel))
        if list_mode:
            item = '\n'.join(line.removeprefix(DAY_ROW_QUOTE) for line in body[item_start:])
            if mode != 'card':
                item = item.removeprefix('- ')
            run.append(item)
            del body[item_start:]
        elif rec.get("participant_lines"):
            body.append("")
    flush()
    if not body:
        return ""
    return "\n".join(head_lines + body).rstrip()


def cli_day_card(argv):
    # day-card [--date YYYY-MM-DD] [--tz <zone>] [--tz-offset <hours>]
    #          [--now <UTC ISO>] [--plain | --pin | --today]
    #          [--exclude-prefix <p[,p]>]
    #
    #   THE day surface. Prints the day's rows with a gap line between them
    #   naming every derived leg that gap spends and what is left over.
    #   Travel blocks are NOT rows here -- they are what the gap line says.
    #
    #   Does not change schedule rows or acknowledge owner choices. Elapsed
    #   clash questions expire in config when the connection is writable.
    #
    #   --plain  the morning brief's block ('- ' bullets, no markers)
    #   --pin    the pinned day card (2026-10-02): today's tasks, today's
    #            schedule (stays + appointments), the week calendar
    #            (day_pin_render)
    #   --pin-meta  internal producer snapshot: rendered text plus latest row
    #            boundary at/before --now, using exactly the same visible data.
    #   --today  THE answer to a today-list ask (today's tasks / list /
    #            schedule, owner 2026-10-07): the pin's header, tasks and
    #            today's schedule, no week section -- the same text the
    #            workbench card shows, so the reply looks like the card. The
    #            model relays it verbatim and adds at most one line on top;
    #            it never composes a timeline (prep / move / buffer blocks
    #            are not items).
    #   default  the day card (header + past/now/ahead markers); the write
    #            confirmation cards use the same row render
    #   Empty output with exit 0 when the day has no rows: the caller's own
    #   "omit the section" / "clear the pin" path then applies.
    argv = list(argv)
    argv, plain = _pop_flag(argv, "--plain")
    argv, pin = _pop_flag(argv, "--pin")
    argv, pin_meta = _pop_flag(argv, "--pin-meta")
    pin = pin or pin_meta
    argv, today_only = _pop_flag(argv, "--today")
    date = tz_name = tz_offset = now = None
    prefixes = []
    while argv:
        flag = argv.pop(0)
        if flag == "--date" and argv:
            date = argv.pop(0)
        elif flag == "--tz" and argv:
            tz_name = argv.pop(0)
        elif flag == "--tz-offset" and argv:
            tz_offset = argv.pop(0)
        elif flag == "--now" and argv:
            now = argv.pop(0)
        elif flag == "--exclude-prefix" and argv:
            prefixes.extend(p.strip() for p in argv.pop(0).split(",")
                            if p.strip())
        else:
            _err("usage: kit_life.sh day-card [--date YYYY-MM-DD] "
                 "[--tz <zone>] [--tz-offset <hours>] [--now <UTC ISO>] "
                 "[--plain | --pin | --today] [--exclude-prefix <p[,p]>]")
    try:
        tz = _day_tz(tz_name, tz_offset)
    except Exception:
        _err("day-card: 알 수 없는 시간대: %s" % tz_name)
    if now:
        try:
            canonical(now)
        except ValueError as e:
            _err("day-card: %s" % e)
    else:
        now = now_utc()
    if date is None:
        date = (datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
                .replace(tzinfo=timezone.utc).astimezone(tz)
                .strftime("%Y-%m-%d"))
    if not _DATE_RE.match(str(date)):
        _err("day-card: --date는 YYYY-MM-DD 형식이어야 합니다")
    if (plain + pin + today_only) > 1:
        _err("day-card: --plain, --pin and --today are different surfaces")
    since, until = _day_window(date, tz)
    conn = event_conn()
    try:
        if pin or today_only:
            if pin_meta:
                data = day_pin_data(
                    conn, date, now=now, tz_name=tz_name, tz_offset=tz_offset,
                    exclude_prefixes=prefixes,
                    owning_agent=task_find_owning_agent([])[1], links=True,
                    crew_agents=(_crew_domain_agents()
                                 if scope_self()["role"] == "main" else ()))
                boundaries = [r.get(key) for r in data["today"] + data["tasks_today"]
                              if not r.get("all_day")
                              for key in ("start_at", "end_at")
                              if r.get(key) and r[key] <= now]
                print(json.dumps({"text": day_pin_render(data), "date": date,
                                  "now": now, "boundary": max(boundaries or [""])}))
                return
            # place links ride the pin only (the bridge sanitizer turns
            # them into <a href> on pin send AND edit); --today and
            # event-day are relayed by the model and stay plain
            text = day_today_card(conn, date, now=now, tz_name=tz_name,
                                  tz_offset=tz_offset,
                                  exclude_prefixes=prefixes,
                                  with_week=not today_only, links=pin)
            if text:
                print(text)
            return
        tl = day_timeline(conn, since, until, now=now, tz_name=tz_name,
                          tz_offset=tz_offset, exclude_prefixes=prefixes)
        notes = routine_day_notes(conn, date, now=now)
    finally:
        conn.close()
    text = day_render(tl, mode=("plain" if plain else "card"), date=date)
    text = "\n".join(([text] if text else []) + notes)
    if text:
        print(text)


# -- week calendar (owner 2026-10-02 13:01-13:03) -----------------------------
# ONE week-strip renderer for every surface that draws a Mon..Sun calendar:
# the pinned day card's week section here, and -- once it switches --
# pack_health's split screen and morning pin (ui_labels.week_calendar today).
# Same visual standard as that pack renderer:
#   row 1  weekday short names (copy, day.week.weekdays)
#   row 2  one cell per day: a count (1..9, more than 9 -> the 'over' glyph,
#          0 -> the 'none' glyph), or a code's first Hangul syllable / first
#          letter or digit (upper case)
#   row 3  optional marks: 'today' / 'done' glyphs, other days blank, trailing
#          blanks cut; dropped when nothing is marked
# Layout per locale (day.week.layout):
#   full  every cell ONE full-width glyph, cells joined by two spaces (ko)
#   half  every cell ONE half-width glyph, cells joined by one space (en)
# With rule=True a line of the rule glyph, exactly the row width in display
# cells, goes above and below. Every glyph is copy; no branch on language.
WEEK_CAL_SEP = {"full": "  ", "half": " "}
_WEEK_CAL_FULLWIDTH_SHIFT = 0xFEE0           # '!'..'~' -> U+FF01..U+FF5E
WEEK_CAL_MARKS = ("today", "done")

WEEK_I18N_FALLBACK = {
    "day.week.layout": u"full",
    "day.week.weekdays": u"\uc6d4,\ud654,\uc218,\ubaa9,\uae08,\ud1a0,\uc77c",
    "day.week.none": u"\u318d",
    "day.week.blank": u"\u3000",
    "day.week.over": u"\uff0b",
    "day.week.today": u"\uff1e",
    "day.week.done": u"\uff36",
    "day.week.rule": u"-",
}


def _i18n_lang(key, lang=None, fallback=""):
    """_i18n for an explicit language (the week-calendar verb's --lang):
    the kit bundle of `lang`, then en, then `fallback`. lang None -> the
    instance language (_i18n)."""
    if not lang:
        return _i18n(key, fallback)
    root = _kit_root()
    for cand in (lang, "en"):
        val = _kit_bundle(root, cand).get(key)
        if isinstance(val, str) and val != "":
            return val
    return fallback


def _week_i18n(key, lang=None):
    return _i18n_lang(key, lang, WEEK_I18N_FALLBACK[key])


def week_cal_layout(lang=None):
    got = _week_i18n("day.week.layout", lang)
    return got if got in WEEK_CAL_SEP else "full"


def week_cal_width(text):
    """Display cells of one line: East Asian Wide/Fullwidth = 2, else 1."""
    import unicodedata
    return sum(2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
               for ch in text)


def _week_wide(ch):
    if "!" <= ch <= "~":
        return chr(ord(ch) + _WEEK_CAL_FULLWIDTH_SHIFT)
    return ch


def week_cal_cell(value, layout="full", lang=None):
    """One day cell. An int (or an all-digit string) is a COUNT; any other
    string is a code drawn as its first Hangul syllable, else its first
    letter/digit upper-cased; nothing -> the none glyph."""
    fit = _week_wide if layout == "full" else (lambda ch: ch)
    none = _week_i18n("day.week.none", lang)
    if isinstance(value, bool):
        value = int(value)
    if isinstance(value, str) and value.strip().isdigit():
        value = int(value.strip())
    if isinstance(value, int):
        if value <= 0:
            return none
        if value > 9:
            return _week_i18n("day.week.over", lang)
        return fit(str(value))
    for ch in str(value or "").strip():
        if u"\uac00" <= ch <= u"\ud7a3":
            return ch
        if ch.isalnum():
            return fit(ch.upper()) if ch.isascii() else ch
    return none


def week_calendar(cells, marks=None, lang=None, rule=False):
    """The calendar lines. `cells` = 7 values Mon..Sun (see week_cal_cell);
    `marks` = None or 7 tokens ('today' | 'done' | '' / None)."""
    layout = week_cal_layout(lang)
    sep = WEEK_CAL_SEP[layout]
    names = [w.strip() for w in _week_i18n("day.week.weekdays", lang)
             .split(",")]
    if len(names) != 7:
        names = WEEK_I18N_FALLBACK["day.week.weekdays"].split(",")
    cells = list(cells or ())
    cells = (cells + [None] * 7)[:7]
    # Owner 2026-10-02 13:27: TODAY is marked in the weekday row as "[<day>]"
    # (the brackets take the separator spaces on both sides, so no column
    # moves); every row is indented one space so a Monday bracket fits. The
    # third row carries only 'done' marks.
    marks = (list(marks) + [None] * 7)[:7] if marks is not None else [None] * 7
    if layout == "half":
        # Equal 3-cell columns (" T "): the bracket takes the pad spaces, so
        # [T] keeps a space on both sides and no column moves.
        def row(vals):
            return "".join(" %s " % v for v in vals)
        plain = row(names)
        head = plain
        if "today" in marks:
            i = marks.index("today")
            chars = list(head)
            chars[3 * i] = "["
            chars[3 * i + 2] = "]"
            head = "".join(chars)
        out = [head.rstrip(), row(week_cal_cell(c, layout, lang)
                                  for c in cells).rstrip()]
        if any(m == "done" for m in marks):
            blank = _week_i18n("day.week.blank", lang)
            glyph = _week_i18n("day.week.done", lang)
            line = row(glyph if m == "done" else blank for m in marks).rstrip()
            if line.strip():
                out.append(line)
        if rule:
            line = _week_i18n("day.week.rule", lang) * week_cal_width(plain.rstrip())
            out = [line] + out + [line]
        return out
    plain = " " + sep.join(names)
    head = plain
    if "today" in marks:
        i = marks.index("today")
        start = 1 + sum(len(n) + len(sep) for n in names[:i])
        end = start + len(names[i])
        chars = list(head)
        chars[start - 1] = "["
        if end < len(chars):
            chars[end] = "]"
        else:
            chars.append("]")
        head = "".join(chars)
    out = [head, " " + sep.join(week_cal_cell(c, layout, lang) for c in cells)]
    if any(m == "done" for m in marks):
        blank = _week_i18n("day.week.blank", lang)
        glyph = {m: _week_i18n("day.week." + m, lang) for m in WEEK_CAL_MARKS}
        row = sep.join(glyph.get(m, blank) if m == "done" else blank
                       for m in marks).rstrip()
        if row.strip():
            out.append(" " + row)
    if rule:
        line = _week_i18n("day.week.rule", lang) * week_cal_width(plain)
        out = [line] + out + [line]
    return out


def cli_week_calendar(argv):
    # week-calendar [--cells v1,..,v7] [--marks m1,..,m7] [--today <day>]
    #               [--lang <code>] [--rule]
    #
    #   The kit's ONE week-strip renderer (see week_calendar above). Read only,
    #   no database. Input is Mon..Sun, comma-separated, exactly 7 fields
    #   (empty fields allowed):
    #     --cells  per day: a count (0 -> none glyph, 1..9, >9 -> over glyph)
    #              or a code (first Hangul syllable / first letter or digit).
    #              Omitted -> an empty week.
    #     --marks  per day: today | done | (empty). Adds the third row.
    #     --today  shorthand for one 'today' mark: MON..SUN, 1..7 (Mon=1) or a
    #              YYYY-MM-DD date (its weekday). Merged over --marks.
    #     --lang   copy/layout language (default: the instance language).
    #     --rule   rule lines above and below, exactly the row width.
    #   Output: the calendar lines, nothing else.
    argv = list(argv)
    argv, rule = _pop_flag(argv, "--rule")
    usage = ("usage: kit_life.sh week-calendar [--cells v1,..,v7] "
             "[--marks m1,..,m7] [--today MON..SUN|1..7|YYYY-MM-DD] "
             "[--lang <code>] [--rule]")
    cells = marks = today = lang = None
    while argv:
        flag = argv.pop(0)
        if flag == "--cells" and argv:
            cells = argv.pop(0)
        elif flag == "--marks" and argv:
            marks = argv.pop(0)
        elif flag == "--today" and argv:
            today = argv.pop(0)
        elif flag == "--lang" and argv:
            lang = argv.pop(0).strip() or None
        else:
            _err(usage)

    def _seven(raw, what):
        parts = [p.strip() for p in raw.split(",")]
        if len(parts) != 7:
            _err("week-calendar: %s needs 7 comma-separated fields (Mon..Sun), "
                 "got %d" % (what, len(parts)))
        return parts

    cell_vals = _seven(cells, "--cells") if cells is not None else [""] * 7
    mark_vals = None
    if marks is not None:
        mark_vals = _seven(marks, "--marks")
        bad = [m for m in mark_vals if m and m not in WEEK_CAL_MARKS]
        if bad:
            _err("week-calendar: unknown mark %r (today|done|empty)" % bad[0])
    if today is not None:
        t = today.strip().upper()
        if t in _WEEKDAY_CODES:
            idx = _WEEKDAY_CODES.index(t)
        elif t.isdigit() and 1 <= int(t) <= 7:
            idx = int(t) - 1
        elif _DATE_RE.match(today.strip()):
            try:
                idx = datetime.datetime.strptime(today.strip(),
                                                 "%Y-%m-%d").weekday()
            except ValueError:
                _err("week-calendar: bad --today date %r" % today)
        else:
            _err("week-calendar: --today expects MON..SUN, 1..7 or "
                 "YYYY-MM-DD")
        mark_vals = mark_vals or [""] * 7
        mark_vals[idx] = "today"
    print("\n".join(week_calendar(cell_vals, mark_vals, lang=lang,
                                  rule=rule)))


# -- the pinned day card (owner 2026-10-02 13:01-13:03) -----------------------
# Owner 2026-10-26: week first, then today modules; one quote per module
# block, bullets on unnumbered rows, checkbox/number markers unchanged.
# The week is a compact count grid.
# Empty sections are omitted. Owner 2026-10-11 10:44 ("no time on the task,
# no appointments of the week"): a timed task of today carries its time in
# the today-schedule row form ('10:00-10:15', day.pin.task_row_timed), and
# under the grid every appointment of the ISO week is listed again, one
# shared quote (owner 2026-10-16), weekday + date on each, past/done marked
# (day.pin.week_row / day.pin.week_done_row; cut in fe6100d, restored). Today includes stays and appointments; the
# week counts appointments only. --today / event-day share this renderer.
# Input to the framework sanitizer: Markdown bold/links and HTML blockquotes.
# Data tag openers are defused, not entity-escaped (the bridge escapes once).
DAY_PIN_OVERDUE_SHOW = 2
DAY_PIN_TODAY_KINDS = ("presence", "appointment")

DAY_PIN_I18N_FALLBACK = {
    "day.pin.header": u"\U0001f4c5 **{md}({wd})**",
    "day.pin.tasks": u"\u2705 **\uc624\ub298 \ud560 \uc77c**",
    "day.pin.task_row": u"[ ] {title}",
    "day.pin.task_row_timed": u"[ ] {time} {title}",
    "day.pin.task_done_row": u"[v] {title}",
    "day.pin.task_done_row_timed": u"[v] {time} {title}",
    "day.pin.more": u"\uc678 {n}\uac74",
    "day.pin.today": u"\U0001f4cd **\uc624\ub298 \uc77c\uc815**",
    "day.pin.appt_row": u"{row}",
    "day.pin.mode.bike": u"\uc790\uc804\uac70",
    "day.pin.mode.car": u"\uc2b9\uc6a9\ucc28",
    "day.pin.mode.transit": u"\ub300\uc911\uad50\ud1b5",
    "day.pin.mode.walk": u"\ub3c4\ubcf4",
    "day.pin.place_line": u"\U0001f3e0 {place}",
    "day.pin.travel_row": u"\u2b07\ufe0f {dep} \ucd9c\ubc1c{rest}",
    "day.pin.travel_min": u"{n}\ubd84",
    "day.pin.travel_together": u"\u2b07\ufe0f {label}",
    "day.pin.week": u"\U0001f5d3\ufe0f **\uc774\ubc88 \uc8fc** ({start}-{end})",
    "day.pin.week_upcoming": u"\u2022 {row}",
    "day.pin.week_today": u"[\uc624\ub298] ",
    "day.pin.week_row": u"{wd} {md}  {time} {title}",
    "day.pin.week_done_row": u"\u2713 {wd} {md}  {time} {title}",
}

# The pin is sanitizer INPUT, not finished HTML: the bridge
# (sanitize_message_for_telegram, consumer rail, parse_mode HTML) passes the
# whitelisted <blockquote> through and escapes every other '&', '<', '>'
# itself -- so data is NOT entity-escaped here (that would print a literal
# '&amp;'). What data must never do is FORM a tag: a '<' that opens a
# letter or '/' gets a WORD JOINER after it, so '<b>' in a title is drawn as
# text and '</blockquote>' cannot close the block early.
DAY_PIN_QUOTE = ("<blockquote>", "</blockquote>")


def _day_pin_quote(lines):
    """One quote block: `lines` (data already in them) joined by newlines,
    tag openers defused, wrapped in the blockquote tags."""
    body = _day_pin_defuse("\n".join(lines))
    return quote_block(body)


def _day_pin_defuse(text):
    """Keep user data from forming HTML, including unquoted departures."""
    return defuse_tag_openers(text)


def _day_pin_i18n(key, **kw):
    text = _i18n(key, DAY_PIN_I18N_FALLBACK[key])
    if not kw:
        return text
    try:
        return text.format(**kw)
    except (KeyError, IndexError, ValueError):
        return DAY_PIN_I18N_FALLBACK[key].format(**kw)


def _md(d):
    return slash_md(*month_day(d))


def _day_pin_mode_label(conn):
    """The travel row's mode word. No leg stores a mode (it is resolved at
    routing time from the owner's recorded transport, config travel_mode), so
    every leg shows that one; unset or unknown -> the owner's default, transit
    (owner ruling 2026-10-29 15:02)."""
    mode = (_config_stored(conn, "travel_mode") or "").strip().lower()
    return _day_pin_i18n("day.pin.mode." + (
        mode if mode in TRAVEL_MODE_CARD_TEXT else "transit"))


def _day_pin_travel(conn, rec, tz):
    """The travel the appointment or stay `rec` leads to, from the kit's own
    derived 'before' leg: {'dep': local HH:MM, 'origin': place name or '',
    'min': int or None}, or None when no live leg exists (no travel known ->
    no line).
    Origin is _travel_origin_place_id's (stated origin, event ending within
    the chain window, routine place at that time, else home). The mode is not
    stored on a leg (resolved at routing time only): 'mode' is the owner's
    recorded transport word (_day_pin_mode_label).
    A leg that moves with its outing (Rule 1: the previous leg of its own
    bundle, at another place) is {'together': True} -- the same one token
    the day card prints, never a departure the engine did not derive.
    Never raises: the pin must survive a travel-store fault."""
    try:
        if rec.get("all_day") or rec.get("kind") not in DAY_PIN_TODAY_KINDS:
            return None
        anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                             (int(rec["id"]),))
        sib = (_travel_bundle_neighbour(conn, anchor, "prev")
               if anchor is not None else None)
        if sib is not None:
            if (_travel_stop_place_id(conn, sib)
                    == _travel_stop_place_id(conn, anchor)):
                return None             # same place: nothing moved
            return {"together": True}
        leg = conn.execute(
            "SELECT start_at, end_at FROM timeblock WHERE block_class=? "
            "AND derived_role='before' AND derived_from=? "
            "AND settled_at IS NULL AND start_at IS NOT NULL "
            "ORDER BY start_at DESC, id DESC LIMIT 1;",
            (TRAVEL_BLOCK_CLASS, rec["ulid"])).fetchone()
        if leg is None:
            return None
        rule = _travel_rule_for_anchor_row(conn, anchor) if anchor else None
        if rule and rule.get('before_src') == TRAVEL_SRC_PROVISIONAL:
            return {'provisional': True}
        dep = _day_hm(leg[0], tz)
        if not dep:
            return None
        mins = (_iso_diff_min(leg[1], leg[0]) if leg[1] else None)
        origin, origin_id = "", None
        try:
            origin_id = _travel_origin_place_id(
                conn, {"id": rec["id"], "ulid": rec["ulid"],
                       "start_at": rec["start_at"]})
            origin = _place_name(conn, origin_id) or ""
        except Exception:  # noqa: BLE001 -- unknown origin: leave it out
            origin, origin_id = "", None
        result = {"dep": dep, "origin": origin, "origin_id": origin_id,
                  "min": mins if mins and mins > 0 else None,
                  "mode": _day_pin_mode_label(conn)}
        # Owner ruling 2026-10-29 16:02: the pin travel row carries no buffer
        # text ('여유 N분 · HH:MM 도착'); chat card A keeps it.
        return result
    except (sqlite3.Error, TypeError, ValueError, KeyError):
        return None


def _crew_domain_agents():
    """The other owner tokens the leader's pin also reads timed blocks of:
    read_scope() minus the leader itself ([] on a domain agent / solo).
    Never raises."""
    sc = scope_self()
    if sc["role"] != "main":
        return []
    return [t for t in sc["task_scope"].split(",") if t and t != sc["agent"]]


def day_pin_data(conn, date, now=None, tz_name=None, tz_offset=None,
                 exclude_prefixes=(), owning_agent=None, links=False,
                 crew_agents=()):
    """What the pin shows for local `date`: {'date', 'monday', 'tasks_today',
    'tasks_overdue', 'appts': {local date: [day-card row records]},
    'today': [today's stay + appointment row records, time-ordered, each
    with pin_travel]}. 'appts' holds appointments only (the week section);
    'today' adds the stays. A record settled 'done' carries pin_done=True.
    links=True (the pinned card only) adds pin_links to today's records
    (_day_pin_links). crew_agents (the life agent only): crew domain agents
    whose TIMED task blocks of the day join 'today' (owner 2026-10-13: the
    health blocks were missing on the life agent); never the tasks section.
    Schedule rows are read only; elapsed clash questions expire. A sqlite
    error leaves the affected part empty. Korean life pins also carry workouts (local date -> session/done)
    and workout_unknown_days, the count of workout dates without a pack label.
    """
    tz = _day_tz(tz_name, tz_offset)
    day = datetime.datetime.strptime(date, "%Y-%m-%d").date()
    monday = day - timedelta(days=day.weekday())
    prefixes = [p for p in (exclude_prefixes or ()) if p]
    out = {"date": day, "monday": monday, "tasks_today": [],
           "tasks_overdue": [], "appts": {}, "today": [],
           "routine_notes": routine_day_notes(conn, date, now=now)}
    import occurrence_projection
    out["occurrences"] = occurrence_projection.opted_in(conn, day=date)
    import health_regimen
    out["regimen_line"] = health_regimen.card_line(sys.modules[__name__], conn, date)
    out["ledger_budget"] = None
    if manage_eligible(conn, "ledger"):
        import ledger_plan
        out["ledger_budget"] = ledger_plan.budget(conn, date)

    def _shown(title):
        return not any((title or "").lstrip().startswith(p) for p in prefixes)

    today_s, today_e = _day_window(date, tz)
    scope = (owning_agent, owning_agent)
    where = ("FROM timeblock e "
             "WHERE e.kind='task' AND e.settled_at IS NULL "
             "AND e.block_class IS NULL AND e.start_at IS NOT NULL "
             "AND (? IS NULL OR instr(',' || ? || ',', "
             "',' || e.owning_agent || ',') > 0) ")
    base = "SELECT e.id, e.title " + where
    # a crew member's TIMED block shows in the schedule (below), not twice
    crew_in = [a.strip().lower() for a in (crew_agents or ()) if a and a.strip()]
    crew_timed_out = ("AND NOT (e.schedule_kind='timed' AND e.owning_agent "
                      "IN (%s)) " % ",".join("?" * len(crew_in))
                      if crew_in else "")
    try:
        # A timed task (schedule_kind 'timed') carries its local start / end
        # HH:MM for the row; an all-day / due one has none.
        # Today's tasks keep a row once settled 'done' (marked done, owner
        # 2026-10-12 11:31: a finished task must not vanish from the pin);
        # an abandoned one still drops. Overdue stays open tasks only.
        today_where = where.replace(
            "AND e.settled_at IS NULL ",
            "AND (e.settled_at IS NULL OR e.settled_outcome = 'done') ")
        out["tasks_today"] = [
            {"id": i, "title": t or "",
             "start_at": s if k == "timed" else None,
             "end_at": e if k == "timed" else None,
             "start_hm": _day_hm(s, tz) if k == "timed" else "",
             "end_hm": (_day_hm(e, tz) if k == "timed" and e and e != s
                        and _day_local_date(e, tz) == day else ""),
             "done": st is not None}
            for i, t, k, s, e, st in conn.execute(
                "SELECT e.id, e.title, e.schedule_kind, e.start_at, "
                "e.end_at, e.settled_at " + today_where +
                "AND e.start_at >= ? AND e.start_at < ? " + crew_timed_out +
                "ORDER BY e.start_at, e.id;",
                scope + (today_s, today_e) + tuple(crew_in))
            if _shown(t)]
        # task-overdue's predicate (effective end before today's local
        # midnight), on the card's own clock. When this day already has a
        # visible occurrence of a routine, do not append older occurrences
        # as untimed copies. Match the routine and owner, never the title;
        # routines without an occurrence this day still carry over.
        out["tasks_overdue"] = [
            {"id": i, "title": t or ""} for i, t in conn.execute(
                base + "AND COALESCE(e.end_at, e.start_at) <= ? "
                "AND (e.recurrence_id IS NULL OR NOT EXISTS ("
                "SELECT 1 FROM timeblock current WHERE "
                "current.recurrence_id=e.recurrence_id "
                "AND current.owning_agent=e.owning_agent "
                "AND current.kind='task' AND current.block_class IS NULL "
                "AND (current.settled_at IS NULL OR current.settled_outcome='done') "
                "AND current.start_at >= ? AND current.start_at < ?)) "
                "ORDER BY e.start_at, e.id;", scope + (today_s, today_s, today_e))
            if _shown(t)]
    except sqlite3.Error:
        pass
    # An errand (a no-time task at a place, errand.py) carries its deadline
    # on the task row too -- the day card already showed it, the pin and
    # the --today answer did not (trial caution 2.46.0-dev.2).
    for t in out["tasks_today"] + out["tasks_overdue"]:
        bits = _errand_card_bits(conn, t["id"], now=now)
        if bits is not None:
            t["deadline"] = bits[0]

    week_s, _ = _day_window(monday.isoformat(), tz)
    week_e, _ = _day_window((monday + timedelta(days=7)).isoformat(), tz)
    # Korean life-pin grid only; English retains its current renderer.
    if (agent_conf.conf_str("AGENT_LANG", "en") == "ko"
            and scope_self()["role"] == "main"):
        import pin_workouts
        out["workouts"], out["workout_unknown_days"] = pin_workouts.week(
            sys.modules[__name__], conn, day, tz, week_s, week_e)
    try:
        found = conn.execute(
            "SELECT id, settled_outcome FROM timeblock "
            "WHERE kind IN (%s) "
            "AND start_at IS NOT NULL AND start_at >= ? AND start_at < ? "
            % ",".join("?" * len(DAY_PIN_TODAY_KINDS)) +
            "AND (block_class IS NULL OR block_class <> ?) "
            "AND (settled_outcome IS NULL OR settled_outcome <> 'abandoned') "
            "ORDER BY start_at, id;",
            DAY_PIN_TODAY_KINDS + (week_s, week_e, TRAVEL_BLOCK_CLASS)
        ).fetchall()
    except sqlite3.Error:
        found = []
    crew = [a.strip().lower() for a in (crew_agents or ()) if a and a.strip()]
    if crew:
        try:
            found = list(found) + conn.execute(
                "SELECT id, settled_outcome FROM timeblock "
                "WHERE kind='task' AND schedule_kind='timed' "
                "AND block_class IS NULL AND start_at IS NOT NULL "
                "AND start_at >= ? AND start_at < ? "
                "AND (settled_at IS NULL OR settled_outcome='done') "
                "AND owning_agent IN (%s) ORDER BY start_at, id;"
                % ",".join("?" * len(crew)),
                (today_s, today_e) + tuple(crew)).fetchall()
        except sqlite3.Error:
            pass
    ids = [r[0] for r in found]
    done_ids = set(r[0] for r in found if r[1] == "done")
    if ids:
        tl = day_timeline(conn, None, None, now=now, tz_name=tz_name,
                          tz_offset=tz_offset, exclude_prefixes=prefixes,
                          ids=ids)
        for rec in tl["items"]:
            if rec["type"] != "row":
                continue                # gap lines are not pin rows
            d = _day_local_date(rec["start_at"], tz)
            if d is None:
                continue
            rec["pin_done"] = rec["id"] in done_ids
            if d == day:
                out["today"].append(rec)
            if rec["kind"] == "appointment":
                out["appts"].setdefault(d, []).append(rec)

        def _order(r):
            return (not r["all_day"], r["start_at"] or "", r["id"])
        for d in out["appts"]:
            out["appts"][d].sort(key=_order)
        out["today"].sort(key=_order)
        for rec in out["today"]:
            rec["pin_travel"] = _day_pin_travel(conn, rec, tz)
            if links:
                rec["pin_links"] = _day_pin_links(conn, rec)
        out.update(_day_pin_ends(conn, out["today"], tz, day, links))
    return out


def _day_pin_ends(conn, today, tz, day, links=False):
    """The day's two end lines of the pin (owner 2026-10-29 15:02):
    {'pin_start': {'name', 'id'}} where the day begins -- the first anchor's
    origin by the kit's own rule (_travel_origin_place_id: stated origin,
    chain neighbour, the stay/presence row, else home) -- and
    {'pin_return': {'dep', 'min', 'mode', 'route'?, 'end', 'end_id'}} from the
    last anchor's live return ('after') leg, ending at the stay row covering
    its arrival, else home (presence_at). Keys are absent when the engine has
    no such place / no return leg that day: nothing is invented.
    Never raises."""
    res = {}
    try:
        anchors = [r for r in today if not r.get("all_day")
                   and r.get("kind") in DAY_PIN_TODAY_KINDS
                   and r.get("start_at")]
        if not anchors:
            return res
        first, last = anchors[0], anchors[-1]
        sid = (first.get("pin_travel") or {}).get("origin_id")
        if sid is None:
            sid = _travel_origin_place_id(
                conn, {"id": first["id"], "ulid": first["ulid"],
                       "start_at": first["start_at"]})
        # A legacy placeless stay can supply an inferred origin/return.
        name = _presence_place_text(
            "presence", _place_name(conn, sid) if sid is not None else "")
        if name:
            res["pin_start"] = {"name": name, "id": sid}
        leg = conn.execute(
            "SELECT start_at, end_at FROM timeblock WHERE block_class=? "
            "AND derived_role='after' AND derived_from=? "
            "AND settled_at IS NULL AND start_at IS NOT NULL "
            "ORDER BY start_at DESC, id DESC LIMIT 1;",
            (TRAVEL_BLOCK_CLASS, last["ulid"])).fetchone()
        if leg is None:
            return res
        # the night is the day's own (DAY_NIGHT_CUTOFF_H); a later day's
        # trip home belongs to that day's card
        if _day_local_date(_iso_shift_min(
                leg[0], -60 * DAY_NIGHT_CUTOFF_H), tz) != day:
            return res
        dep = _day_hm(leg[0], tz)
        end_id = presence_at(conn, leg[1] or leg[0],
                             exclude_event_id=last["id"])[1]
        end = _presence_place_text(
            "presence", _place_name(conn, end_id) if end_id is not None else "")
        if not dep or not end:
            return res
        mins = _iso_diff_min(leg[1], leg[0]) if leg[1] else None
        ret = {"dep": dep, "min": mins if mins and mins > 0 else None,
               "mode": _day_pin_mode_label(conn), "end": end,
               "end_id": end_id}
        if links:
            anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?;",
                                 (int(last["id"]),))
            from_id = _travel_leg_places(conn, "after", anchor)[0]
            route = travel_directions_link(conn, from_id, end_id)
            if route:
                ret["route"] = route["url"]
        res["pin_return"] = ret
    except Exception:  # noqa: BLE001 -- the pin survives a travel-store fault
        return {}
    return res


def _day_pin_links(conn, rec):
    """Map links for the place names of one pinned row (owner 2026-10-09
    10:21 "pin place links"; the maintainer worklog 2026-10-09-pin-place-links):
      place   the row's place token -> the destination's place link on the
              owner's map for the leg's region (map_providers_for_leg;
              travel_place_link: stored URL, place page, or a search for
              name + address).  Google only when no map is picked.
      route   the directions route of the leg INTO the row, when both ends
              have stored coordinates (travel_directions_link); it is the
              link of the travel row's "<mode> N min" text (owner 2026-10-29
              15:02), absent otherwise (plain text, never a fake route).
    Only a LOCATABLE place is linked (stored map URL, coordinates or an
    address): a bare nickname ('home', 'office') would open a search for
    the word itself.  {} when the row has no such place on file (a venue
    text is not linked).  Never raises: a link fault leaves the plain
    name."""
    out = {}

    def locatable(pid):
        return pid is not None and bool(
            _place_map_url(conn, pid) or place_coord_get(conn, pid)
            or _travel_place_map_string(conn, pid))
    try:
        row = conn.execute("SELECT place_id FROM timeblock WHERE id=?;",
                           (int(rec["id"]),)).fetchone()
        dest_id = row[0] if row else None
        if not locatable(dest_id):
            dest_id = None
        tv = rec.get("pin_travel") or {}
        origin_id = tv.get("origin_id")
        if origin_id == dest_id or not locatable(origin_id):
            origin_id = None
        region = travel_leg_region(conn, origin_id, dest_id)
        provider = map_providers_for_leg(conn, region)[0]
        if dest_id is not None:
            out["place"] = travel_place_link(conn, dest_id, provider)
            route = travel_directions_link(conn, origin_id, dest_id, region)
            if route:
                out["route"] = route["url"]
    except Exception:  # noqa: BLE001 -- the pin must survive a link fault
        return {}
    return out


PIN_BLOCK_SLOTS = ("week_grid", "week_items", "today")
_PIN_ITEM_MARKER_RE = re.compile(r"^(?:\[[ v-]\] |[0-9]+[.)] |\u2022 )")


def sub_line(value):
    """Locale-neutral value breakdown; accepts a bare or already marked line."""
    value = str(value).strip()
    if value.startswith("\u2514 "):
        value = value[2:]
    return " \u2514 " + value


def bullet(value):
    """Unnumbered item, preserving existing numbers and checkbox markers."""
    value = str(value)
    return value if _PIN_ITEM_MARKER_RE.match(value) else "\u2022 " + value


def bar_inline(value):
    """One bar in HTML prose; column-aligned cards own their whole fence."""
    import html
    return "<code>" + html.escape(str(value)) + "</code>"


def group(lines, title=None, trusted_html=False):
    """One quote with its title outside. Default input is pin sanitizer data.

    trusted_html=True accepts renderer-owned HTML, with dynamic data escaped
    by the caller. It must never be used for unescaped user input.
    """
    rows = [str(line) for line in lines if str(line).strip()]
    if not rows:
        return ""
    quote = ("<blockquote>" + "\n".join(rows) + "</blockquote>"
             if trusted_html else _day_pin_quote(rows))
    heading = str(title or "") if trusted_html else _day_pin_defuse(str(title or ""))
    return (heading + "\n" if heading else "") + quote


def pin_format_block(lines, title=None, style="items"):
    """One module block: title outside ONE quote, data tag openers defused.

    items: prefix unnumbered rows with a bullet; keep checkbox and numbered
    markers. plain: preserve grid whitespace. Empty blocks are omitted.
    This is sanitizer input (Markdown headings/links, HTML blockquotes).
    """
    if style not in ("items", "plain"):
        raise ValueError("unknown pin block style: %s" % style)
    rows = [str(line) for line in lines if str(line).strip()]
    if not rows:
        return ""
    if style == "items":
        rows = [bullet(line) for line in rows]
    return group(rows, title)


def pin_week_grid(day, day_mark_provider, lang=None):
    """Mon..Sun rows, with [today] in the weekday row and no V line.

    day_mark_provider(date) returns the module's count/code for that day.
    The calling agent resolves competing module marks in this provider;
    this helper never sums or overwrites module values. The life agent supplies only
    appointment counts. Packs may supply their own module marks instead.
    """
    monday = day - timedelta(days=day.weekday())
    week = [monday + timedelta(days=i) for i in range(7)]
    return week_calendar([day_mark_provider(d) for d in week],
                         ["today" if d == day else "" for d in week], lang=lang)


class PinBlockRegistry:
    """One ordered registry per pin composer, shared by kit and pack modules.

    Entries are (module_id, slot, order, render). render(data) returns one
    formatted module block or an empty string. Equal orders retain registry
    insertion order. Registration is explicit; rendering has no side effects.
    """
    def __init__(self):
        self.blocks = []

    def register(self, module_id, slot, order, render):
        if not module_id or slot not in PIN_BLOCK_SLOTS:
            raise ValueError("pin block needs a module id and a known slot")
        if not isinstance(order, int) or not callable(render):
            raise ValueError("pin block needs an integer order and render function")
        if any(b[0:2] == (module_id, slot) for b in self.blocks):
            raise ValueError("duplicate pin block: %s/%s" % (module_id, slot))
        self.blocks.append((module_id, slot, order, render))

    def render(self, data, header, with_week=True):
        parts = []
        previous = None
        for slot in PIN_BLOCK_SLOTS:
            if not with_week and slot != "today":
                continue
            for module_id, _, order, render in sorted(
                    (b for b in self.blocks if b[1] == slot), key=lambda b: b[2]):
                block = render(data)
                if not block:
                    continue
                # Week item modules append directly beneath the week grid.
                gap = ("\n" if previous in ("week_grid", "week_items")
                       and slot != "today" else "\n\n")
                parts.append((gap if parts else "") + block)
                previous = slot
        return header + "\n\n" + "".join(parts) if parts else ""


def _day_pin_week_grid(data):
    monday = data["monday"]
    week = [monday + timedelta(days=i) for i in range(7)]
    workouts = data.get("workouts") or {}
    if agent_conf.conf_str("AGENT_LANG", "en") == "ko":
        import html
        has_appts = any(data["appts"].get(d) for d in week)
        owns_health = "health" in scope_self()["owns"]
        show_health = bool(workouts) and owns_health
        if not has_appts and not show_health:
            return ""
        # Keep the health grid's spacing. The appointment-only owner pick
        # adds one space before both the weekday strip and the data cells.
        padding = " " if owns_health else "  "
        rows = ["  " + padding + pin_week_grid(data["date"], lambda d: 0)[0]]

        def row(label, cells):
            return label + padding + "".join(
                cell + " " * max(0, 4 - week_cal_width(cell))
                for cell in cells).rstrip()

        if has_appts:
            rows.append(row(u"\uc57d\uc18d", [str(len(data["appts"][d]))
                if data["appts"].get(d) else u"\u318d" for d in week]))
        if show_health:
            marks = []
            for d in week:
                workout = workouts.get(d) or {}
                name = workout.get("session")
                marks.append(name[0] + (u"\u2713" if workout.get("done") else "")
                             if name else u"\u318d")
            rows.append(row(u"\ud5ec\uc2a4", marks))
        title = u"\U0001f5d3\ufe0f <b>\uc774\ubc88 \uc8fc (%s-%s)</b>" % (
            _md(monday), _md(week[-1]))
        return title + "\n<pre>" + html.escape("\n".join(rows)) + "</pre>"
    if not any(data["appts"].get(d) for d in week):
        return ""
    y, w, _ = monday.isocalendar()
    title = _day_pin_i18n("day.pin.week", year=y, week=w,
                          start=_md(monday), end=_md(week[-1]))
    return pin_format_block(pin_week_grid(
        data["date"], lambda d: len(data["appts"].get(d, ()))), title, style="plain")


def _day_pin_week_items(data):
    day = data["date"]
    week = [data["monday"] + timedelta(days=i) for i in range(7)]
    wds = _day_pin_weekdays()
    # The under-list: the whole ISO week (owner 2026-10-04 08:05), done
    # when its day is past, it is settled 'done', or it already ended.
    allday = _day_i18n("day.card.allday")
    rows = []
    for d in week:
        for rec in data["appts"].get(d, ()):
            when = ("" if rec.get("kind") == "task" else allday) \
                if rec["all_day"] else (rec["start_hm"] or allday)
            done = (d < day or rec.get("pin_done")
                    or rec.get("pos") == DAY_POS_PAST)
            key = "day.pin.week_done_row" if done else "day.pin.week_row"
            wd = wds[d.weekday()]
            if d == day:
                wd = _day_pin_i18n("day.pin.week_today") + wd
            row = _day_pin_i18n(key, wd=wd, md=_md(d),
                                time=when, title=rec["title"].replace(" \u00b7 ", " / "))
            if not when:
                row = re.sub(r" {3,}", "  ", row)
            rows.append(row)
    return pin_format_block(rows)


def _day_pin_tasks(data):
    # The complete pin was approved with middle dots on 2026-10-29 15:02.
    sep = " \u00b7 "
    rng_fmt = _i18n("schedule.time_range", "{start}-{end}")
    tasks = data["tasks_today"]
    overdue = data["tasks_overdue"]
    shown = overdue[:DAY_PIN_OVERDUE_SHOW]
    if tasks or overdue:
        lines = []
        for t in tasks + shown:
            title = ((t["title"] + sep + t["deadline"]) if t.get("deadline")
                     else t["title"])
            when = t.get("start_hm") or ""
            if when and t.get("end_hm"):
                try:
                    when = rng_fmt.format(start=when, end=t["end_hm"])
                except (KeyError, IndexError, ValueError):
                    when = when + "-" + t["end_hm"]
            done = t.get("done")
            key = (("day.pin.task_done_row_timed" if done
                    else "day.pin.task_row_timed") if when else
                   ("day.pin.task_done_row" if done else "day.pin.task_row"))
            lines.append(_day_pin_i18n(key, time=when, title=title))
        if len(overdue) > len(shown):
            lines.append(_day_pin_i18n("day.pin.more",
                                       n=len(overdue) - len(shown)))
        return pin_format_block(lines, _day_pin_i18n("day.pin.tasks"))
    return ""


def _day_pin_schedule(data):
    day = data["date"]
    # A data dict without 'today' (built before stays joined the section)
    # renders the day's appointments, as it always did.
    todays = data["today"] if "today" in data else data["appts"].get(day, [])
    if todays:
        lines, run = [], []
        def flush():
            if run:
                from item_grouping import quote_items
                lines.append(quote_items(run))
                run.clear()
        start = data.get("pin_start")
        if start and start.get("name"):
            lines.append(_day_pin_defuse(_day_pin_i18n(
                "day.pin.place_line", place=start["name"])))
        for rec in todays:
            if rec["place"] and rec["place"].strip() == rec["title"].strip():
                # A venue named like the appointment ('<restaurant>' at
                # '<restaurant>') says the same word twice; the pin keeps one.
                rec = dict(rec, place="")
            plinks = rec.get("pin_links") or {}
            if rec["place"] and plinks.get("place"):
                # the place token only: same visible text, now a link. A
                # stay row titled after its place ('<place>: <label> . <place>') links
                # the leading word (owner 2026-10-29 15:02 preview), the
                # tail stays plain; every other row links the place token.
                lead = rec["place"] + u":"
                if (rec.get("kind") == "presence"
                        and (rec["title"] or "").startswith(lead)):
                    rec = dict(rec, title=_md_link(rec["place"],
                                                   plinks["place"]) +
                               rec["title"][len(rec["place"]):])
                else:
                    rec = dict(rec, place=_md_link(rec["place"],
                                                   plinks["place"]))

            # Card A owns schedule-anchor typography. Render one anchor at a
            # time so the pin cannot drift from event_cards/day_render, then
            # translate its Markdown quote container to the pin's HTML quote.
            # The date header is intentionally absent when date=None.
            # The pin keeps its compact derived departure travel line on
            # top; Card A supplies the anchor only.
            card_rec = dict(rec, type="row")
            tv = rec.get("pin_travel")
            # Owner ruling 2026-10-29 13:06: the pin drops card A's
            # departure/arrival detail lines; the compact travel row above
            # the anchor is the only travel line. Chat card A keeps them.
            card_rec.pop("card_travel", None)
            # Preserve that later pin preview when the shared chat join changes.
            rendered = day_render({"items": [card_rec]}, mode="card", date=None,
                                  separator=" \u00b7 ")
            block = [line[len(DAY_ROW_QUOTE):]
                     if line.startswith(DAY_ROW_QUOTE) else line
                     for line in rendered.splitlines() if line.strip()]
            if block and block[0].startswith(u"\u2022 "):
                # final shape (owner 2026-10-29 15:02): the anchor row has no
                # leading bullet (card A draws one on a stay row)
                block[0] = block[0][2:]

            if tv:
                flush()
            # Travel stays outside the quote, directly above its anchor.
            if tv and tv.get("together"):
                lines.append(_day_pin_defuse(_day_pin_i18n(
                    "day.pin.travel_together",
                    label=_day_i18n("day.gap.together"))))
            elif tv and tv.get('provisional'):
                lines.append(_i18n(
                    'travel.provisional.card',
                    'Travel time is being checked; time reserved for now.'))
            elif tv:
                rest = _day_pin_leg_text(tv, plinks.get("route"))
                lines.append(_day_pin_defuse(_day_pin_i18n(
                    "day.pin.travel_row", dep=tv["dep"], rest=rest)))
            if block:
                if len(todays) > 1:
                    run.append(_day_pin_defuse('\n'.join(block)))
                else:
                    lines.append(_day_pin_quote(block))
        flush()
        ret = data.get("pin_return")
        if ret and ret.get("dep") and ret.get("end"):
            lines.append(_day_pin_defuse(_day_pin_i18n(
                "day.pin.travel_row", dep=ret["dep"],
                rest=_day_pin_leg_text(ret, ret.get("route")))))
            lines.append(_day_pin_defuse(_day_pin_i18n(
                "day.pin.place_line", place=ret["end"])))
        if any(l.startswith("<blockquote>") for l in lines):
            return (_day_pin_defuse(_day_pin_i18n("day.pin.today")) + "\n" +
                    "\n".join(lines).rstrip())
    return ""


DAY_PIN_ARROW = u"\u2b07\ufe0f"


def _day_pin_leg_text(tv, url=None):
    """The ' / <mode> N min' tail of a travel row ('' when the leg has no known
    duration: nothing is invented); the mode text is the directions link when
    `url` is given (a leg with both ends located), plain text otherwise."""
    if not tv.get("min"):
        return ""
    text = ((tv.get("mode") or _day_pin_i18n("day.pin.mode.transit")) + " " +
            _day_pin_i18n("day.pin.travel_min", n=tv["min"]))
    return " / " + (
        _md_link(text, url) if url else text)


def _day_pin_weekdays():
    names = [w.strip() for w in _day_i18n("day.card.weekdays").split(",")]
    return names if len(names) == 7 else DAY_I18N_FALLBACK["day.card.weekdays"].split(",")


