def day_pin_buttons(conn, date, tz_name=None, tz_offset=None,
                    owning_agent=None, limit=4, exclude_prefixes=(), register=False):
    """Buttons for visible OPEN tasks, ordered by their stored start time.

    register=True replaces the live token set for this instance. Plain
    rendering is read-only; the publisher registers only outside --dry.
    """
    owner = owning_agent or _pin_agent()
    data = day_pin_data(conn, date, tz_name=tz_name, tz_offset=tz_offset,
                        owning_agent=task_find_owning_agent([])[1],
                        crew_agents=_crew_domain_agents(),
                        exclude_prefixes=exclude_prefixes)
    ids = {r["id"] for r in data["tasks_today"] + data["tasks_overdue"][:DAY_PIN_OVERDUE_SHOW]}
    ids.update(r["id"] for r in data["today"] if r["kind"] == "task")
    found = conn.execute(
        "SELECT e.id,e.ulid,e.title,e.version,e.owning_agent,COALESCE(a.value,'check') "
        "FROM timeblock e LEFT JOIN block_attr a ON a.block_id=e.id "
        "AND a.attr_token='action_kind' WHERE e.kind='task' AND e.block_class IS NULL "
        "AND e.settled_at IS NULL ORDER BY e.start_at,e.id;").fetchall()
    buttons, actions = [], {}
    for eid, ulid, title, version, item_owner, kind in found:
        if len(buttons) >= max(0, min(4, int(limit))):
            break
        if eid not in ids or (kind != "check" and item_owner != owner):
            continue
        label = _i18n("day.pin.button.start" if kind != "check" else "day.pin.button.done",
                      "Start {title}" if kind != "check" else "Done {title}").format(title=title or "")
        token = "pin:" + new_ulid()
        buttons.append({"text": label, "callback_data": "opt:" + token})
        actions[token] = dict(id=eid, ulid=ulid, title=title, version=version, kind=kind)
    retire_buttons = []
    for line in routine_retire_asks(conn, consume=False):
        fields = line.split("\t")
        if fields[0] != "RETIRE_ASK":
            continue
        defn = routine_def_get(conn, fields[1])
        choices = []
        for value in fields[3].removeprefix("choices=").split("|"):
            choice, label = value.split("=", 1)
            token = "pin:" + new_ulid()
            choices.append({"text": defn["title"] + " " + label,
                            "callback_data": "opt:" + token})
            actions[token] = dict(ulid=defn["ulid"], version=defn["version"],
                                  kind="routine_retire", choice=choice)
        retire_buttons.append(choices)
    if register:
        _config_put(conn, "day_pin_actions." + owner, json.dumps(actions))
        conn.commit()
    return [[b] for b in buttons] + retire_buttons


def cli_day_pin_buttons(argv):
    argv, date = _pop_opt(argv, "--date")
    argv, tz_offset = _pop_opt(argv, "--tz-offset")
    argv, excluded = _pop_opt(argv, "--exclude-prefix")
    if argv or not date or not _DATE_RE.match(date):
        _err("usage: day-pin-buttons --date YYYY-MM-DD [--tz-offset H] [--exclude-prefix LIST]")
    conn = event_conn()
    try:
        print(json.dumps(day_pin_buttons(conn, date, tz_offset=tz_offset,
                         exclude_prefixes=(excluded or "").split(","), register=True),
                         ensure_ascii=False, separators=(",", ":")))
    finally:
        conn.close()


def routine_sync_retro(conn, lane, clock, today=None, now=None, state_conn=None):
    """Idempotently create/update this agent's scheduled retro occurrences."""
    if lane not in ("daily", "weekly"):
        raise ValueError("retro lane must be daily|weekly")
    parts = clock.split()
    cadence, tod = ("D", clock) if lane == "daily" else ("W:" + parts[0].upper(), parts[-1])
    _routine_validate(cadence, "timed", tod, "task")
    owner = _pin_agent()
    title = _i18n("bundle.daily_retro.name" if lane == "daily" else "bundle.weekly_review.name", lane + " retro")
    purpose = "retro:" + lane
    rows = conn.execute("SELECT ulid FROM routine_def WHERE owning_agent=? "
                        "AND status='active' AND (purpose=? OR (title=? AND action_kind='retro'))",
                        (owner, purpose, title)).fetchall()
    if len(rows) > 1:
        raise ValueError("multiple retro routines need reconciliation")
    changes = dict(cadence=cadence, time_of_day=tod, schedule_kind="timed",
                   title=title, purpose=purpose, action_kind="retro", notify_policy="start_only")
    if rows:
        old = routine_def_get(conn, rows[0][0])
        changes = {k: v for k, v in changes.items() if old.get(k) != v}
        if changes:
            return routine_update(conn, rows[0][0], changes, today=today, now=now, state_conn=state_conn)
        return {"result": "unchanged"}
    return routine_add(conn, title, cadence, "timed", time_of_day=tod,
                       purpose=purpose, action_kind="retro", owning_agent=owner,
                       notify_policy="start_only", today=today, now=now, state_conn=state_conn)


def retro_task_for_day(conn, lane, date):
    """The scheduled retro replaces the legacy cron start card, even if done."""
    row = conn.execute(
        "SELECT e.id FROM timeblock e JOIN routine_def d USING(recurrence_id) "
        "WHERE d.purpose=? AND d.owning_agent=? AND d.status='active' "
        "AND d.action_kind='retro' AND e.rec_date=? "
        "AND (e.settled_at IS NULL OR e.settled_outcome='done') ORDER BY e.id LIMIT 1",
        ("retro:" + lane, _pin_agent(), date)).fetchone()
    return row[0] if row else None


def cli_retro_task(argv):
    if len(argv) != 2 or argv[0] not in ("daily", "weekly") or not _DATE_RE.match(argv[1]):
        _err("usage: retro-task daily|weekly YYYY-MM-DD")
    conn = event_conn()
    try:
        bid = retro_task_for_day(conn, argv[0], argv[1])
        if bid is not None:
            print(bid)
    finally:
        conn.close()


def weekly_retro_week_end(day):
    """Same reviewed week as weekly-review: Sunday today, else last Sunday."""
    d = datetime.date.fromisoformat(day)
    return (d - datetime.timedelta(days=d.isoweekday() % 7)).isoformat()


def weekly_retro_key(week_end, agent=None):
    d = datetime.date.fromisoformat(week_end)
    if d.isoweekday() != 7:
        raise ValueError("weekly retro week end must be a Sunday")
    return "weekly_retro.%s.%s" % (agent or _pin_agent(), week_end)


def weekly_retro_state(conn, week_end, agent=None):
    """Durable agent/week fact in the existing config store, not a tmp marker."""
    raw = _config_stored(conn, weekly_retro_key(week_end, agent))
    try:
        fact = json.loads(raw or "{}")
    except ValueError:
        return {}
    return fact if isinstance(fact, dict) else {}


def weekly_retro_record(conn, week_end, state):
    key = weekly_retro_key(week_end)
    if state not in ("started", "done"):
        raise ValueError("weekly retro state must be started|done")
    if not conn.in_transaction:
        conn.execute("BEGIN IMMEDIATE")
    before = _retro_correction.stored(conn, key)
    fact = weekly_retro_state(conn, week_end)
    if fact.get("state") == "done" or fact.get("state") == state:
        return fact
    fact.update(state=state, week_end=week_end,
                week_start=(datetime.date.fromisoformat(week_end) - datetime.timedelta(days=6)).isoformat())
    fact[state + "_utc"] = canonical(now_utc())
    _config_put(conn, key, json.dumps(fact, sort_keys=True))
    _retro_correction.remember(conn, key, before, fact)
    return fact


def cli_weekly_retro(argv, state=None):
    if len(argv) != 1:
        _err("usage: weekly-retro-done|weekly-retro-start|weekly-retro-status YYYY-MM-DD (Sunday)")
    conn = event_conn()
    try:
        fact = (weekly_retro_record(conn, argv[0], state) if state
                else weekly_retro_state(conn, argv[0]))
        if state:
            conn.commit()
        print("%s\t%s" % (fact.get("state", "missing").upper(), argv[0]))
    except ValueError as exc:
        _err(str(exc))
    finally:
        conn.close()


def cli_retro_schedule(argv):
    if len(argv) != 2:
        _err("usage: retro-schedule daily|weekly HH:MM|'Sun HH:MM'")
    conn = event_conn()
    try:
        print(json.dumps(_retro_correction.schedule(sys.modules[__name__], conn, 'retro-schedule', argv[0], argv[1])))
    except (ValueError, IndexError) as exc:
        _err(str(exc))
    finally:
        conn.close()


# -- write confirmation cards (owner 2026-09-24 13:06) ------------------------
# "이런식으로 카드 crud한 경우 카드처럼 보여주면 좋겠어". A write verb that
# touches a card-shaped item (a block on the day card: appointment, presence,
# timed task -- its time, place, people) ends its output with the RENDERED
# card of every item it touched, and the model relays those lines as the
# confirmation. The model never re-types the card, for the same reason the
# morning brief's schedule block arrives rendered (2.26.0): a model that
# retypes a quoted row normalizes it into a bullet sentence.
#
# One renderer: each card is day_timeline(ids=[id]) -> day_render(mode='card')
# for the item's own local date, so its row line is byte-identical to the line
# the pinned day card prints for it. Gap lines are dropped -- a confirmation is
# about the item, not the space around it. One date = one card (header + the
# quoted rows of that date's items); two dates -> two cards separated by a
# blank line (the life agent 2026-10-06: two same-day items used to repeat the header).
#
# Output contract (appended AFTER every existing line, so column/first-line
# readers are unaffected):
#     CARD_BEGIN <n>
#     <card> [blank line <card> ...]
#     CARD_END
#     CARD_RELAY <instruction>
CARD_BEGIN = "CARD_BEGIN"
CARD_END = "CARD_END"
MAP_BUTTON = "MAP_BUTTON"
CARD_RELAY = (
    "CARD_RELAY The lines between CARD_BEGIN and CARD_END are the ALREADY "
    "RENDERED card of every item this write touched -- the same card the "
    "pinned day card shows for it. Your confirmation to the user IS those "
    "lines, reproduced VERBATIM and in the given order, with at most ONE "
    "short lead line before them. Each card is a date header line followed "
    "by that date's rows, each starting with '> ': the leading '> ' is part "
    "of the row -- keep it exactly; do NOT substitute a bullet, do NOT turn "
    "a row into a sentence, do NOT add, drop, merge, reorder or re-word a "
    "line, do NOT recompute a time, and keep the blank line between two "
    "cards. An undated card instead has a title line and a date-undecided "
    "marker: preserve both, without adding a date header or quote. "
    "After CARD_END, attach each MAP_BUTTON label/url as that card "
    "message's URL button; never print the MAP_BUTTON machine line. A row "
    "ending in the removed marker is the card of an item this "
    "write removed: relay it as it is. When this turn wrote MORE THAN ONE "
    "item (several writes), do not relay the per-write blocks: run "
    "`event-card <id> <id> ...` once with every item the turn touched "
    "(past-dated ones included; a removed one also in --removed <id>) and "
    "relay that one block -- it shows each item's final state, and items on "
    "the same date share one header there. Never print CARD_BEGIN, CARD_END "
    "or this CARD_RELAY line itself.")


def _card_tz_offset():
    """The declared AGENT_TZ_OFFSET_HOURS (the pinned card's clock), or None
    so _day_tz falls back to the kit display tz. Never invents a 0."""
    try:
        raw = os.environ.get("AGENT_TZ_OFFSET_HOURS")
        if raw is None:
            raw = agent_conf._raw("AGENT_TZ_OFFSET_HOURS")
        return raw if raw not in (None, "") else None
    except Exception:
        return None


def event_cards(conn, ids, now=None, removed_ids=(), tz_name=None,
                tz_offset=None, card_a=False):
    """[card text, ...] for the blocks `ids`: ONE card per local date (the
    date header once, then that date's rows in wall-clock order), dates in
    the order their first id was given. A block with no start instant (an
    undated task) uses the shared title/date-undecided body. A missing id
    or a travel leg outside card_a yields no row.
    Repairs stale attendance/travel before reading; never raises -- a
    confirmation surface must not fail a write that already committed.

    the life agent 2026-10-06 13:05: presence-move + appt-add on the same day relayed
    two cards under the same date header; a turn that wrote several items
    ends with one `event-card <id> <id> ...` and the items of a day share
    its header."""
    if now is None:
        now = now_utc()
    if tz_name is None and tz_offset is None:
        tz_offset = _card_tz_offset()
    removed = set(int(i) for i in (removed_ids or ()))
    by_date, order, seen = {}, [], set()
    for raw_id in ids or ():
        try:
            eid = int(raw_id)
        except (TypeError, ValueError):
            continue
        if eid in seen:
            continue
        seen.add(eid)
        try:
            saved = conn.execute('SELECT title,start_at,kind FROM timeblock WHERE id=?',
                                 (eid,)).fetchone()
            if saved and saved[1] is None and saved[2] == 'task':
                key = ('undated', eid)
                order.append(key)
                by_date[key] = _timeblock_card_mod().undated_body(sys.modules[__name__], saved[0])
                continue
            tz = _day_tz(tz_name, tz_offset)
            tl = day_timeline(conn, None, None, now=now, tz_name=tz_name,
                              tz_offset=tz_offset, ids=[eid], include_helpers=card_a)
            rows = [r for r in tl["items"] if r["type"] == "row"]
            if not rows:
                continue
            row = rows[0]
            row["removed"] = eid in removed
            if card_a:
                row["card_a"] = True
            # Confirmation lane only: the day card stays quiet about a
            # missing venue; the card of a write says it, next to the ask.
            row["place_unset"] = bool(
                _appt_place_unset_ids(conn, [eid], removed))
            # 067: a start outside the place's known hours is flagged on
            # the card (closed day / outside / break); '' otherwise.
            row["hours_flag"] = ("" if row["removed"]
                                 else _place_hours_card_flag(conn, eid, now))
            date = (datetime.datetime.strptime(row["start_at"],
                                               "%Y-%m-%dT%H:%M:%SZ")
                    .replace(tzinfo=timezone.utc).astimezone(tz)
                    .strftime("%Y-%m-%d"))
        except Exception:
            continue
        if date not in by_date:
            by_date[date] = []
            order.append(date)
        by_date[date].append((len(seen), row))
    cards = []
    for date in order:
        if isinstance(date, tuple):
            cards.append(by_date[date])
            continue
        # wall clock; a tie keeps the given order (a write lists the item it
        # wrote before the one it superseded)
        rows = [r for _o, r in sorted(
            by_date[date], key=lambda t: (not t[1].get("all_day"),
                                          t[1]["start_at"], t[0]))]
        try:
            text = day_render({"items": rows}, mode="card", date=date)
        except Exception:
            continue
        if text:
            cards.append(text)
    return cards


def _print_cards(conn, ids, removed_ids=(), mutation_state=None):
    """Append the CARD block (contract above) to a write verb's output.
    Prints nothing when no touched item has a card."""
    tc = _timeblock_card_mod() if mutation_state else None
    cards = ([tc.render(sys.modules[__name__], conn,
                        tc.TimeblockMutationResult('write', int(i), mutation_state))
              for i in ids] if tc else event_cards(conn, ids, removed_ids=removed_ids))
    cards = [c for c in cards if c]
    if cards:
        _emit_place_ask(conn, ids, removed_ids)
    _emit_place_hours(conn, ids, removed_ids)
    _emit_errand(conn, ids, removed_ids)
    _emit_map_region(conn, ids, removed_ids)
    _emit_place_coord(conn, ids, removed_ids)
    if tc:
        _emit_card_block(cards, relay=tc.RELAY)
    else:
        _emit_card_block(cards, _event_card_map_buttons(conn, ids, removed_ids))


def _emit_errand(conn, ids, removed_ids=(), now=None):
    """ERRAND lines (errand.py plan_line) for the touched errands + relay."""
    removed = set(str(i) for i in (removed_ids or ()))
    try:
        _errand_mod().emit(sys.modules[__name__], conn,
                           [i for i in ids or () if str(i) not in removed],
                           now=now)
    except Exception:
        pass


def _event_card_map_buttons(conn, ids, removed_ids=(), destination_fallback=False):
    """Ordered map actions for live appointments represented by a card block."""
    removed = {int(i) for i in (removed_ids or ())}
    out = []
    for raw_id in ids or ():
        try:
            eid = int(raw_id)
            if eid in removed:
                continue
            anchor = _travel_row(conn, "SELECT * FROM timeblock WHERE id=?",
                                 (eid,))
            if not anchor or anchor.get("kind") != "appointment":
                continue
            leg = conn.execute(
                "SELECT start_at,end_at FROM timeblock WHERE block_class=? "
                "AND derived_role='before' AND derived_from=? AND settled_at IS NULL "
                "AND start_at IS NOT NULL AND end_at IS NOT NULL ORDER BY id DESC LIMIT 1",
                (TRAVEL_BLOCK_CLASS, anchor["ulid"])).fetchone()
            if not leg or _iso_diff_min(leg[1], leg[0]) <= 0:
                if destination_fallback:
                    button = _card_map_button(conn, None, anchor.get("place_id"), search_only=True,
                                              location=anchor.get("location"))
                    if button:
                        out.append(button)
                continue
            origin_id, dest_id = _travel_leg_places(conn, "before", anchor)
            button = _card_map_button(conn, origin_id, dest_id)
            if button:
                out.append(button)
        except (TypeError, ValueError, sqlite3.Error):
            continue
    return out


def _emit_card_block(cards, map_buttons=(), relay=None):
    if not cards:
        return
    print("%s %d" % (CARD_BEGIN, len(cards)))
    print("\n\n".join(cards))
    print(CARD_END)
    for button in map_buttons:
        print("%s\t%s\t%s" % (MAP_BUTTON, button["text"], button["url"]))
    print(relay or CARD_RELAY)


def cli_event_card(argv):
    # event-card <id> [<id> ...] [--removed <id[,id]>] [--now <UTC ISO>]
    #            [--tz <zone>] [--tz-offset <hours>]
    #   READ ONLY. The confirmation card(s) of the given blocks, in the CARD
    #   block contract the write verbs append. For a turn that touched several
    #   items through several writes: one call, one card per item, final state.
    argv = list(argv)
    argv, removed_raw = _pop_opt(argv, "--removed")
    argv, now = _pop_opt(argv, "--now")
    argv, tz_name = _pop_opt(argv, "--tz")
    argv, tz_offset = _pop_opt(argv, "--tz-offset")
    usage = ("usage: kit_life.sh event-card <id> [<id> ...] "
             "[--removed <id[,id]>] [--now <UTC ISO>] [--tz <zone>] "
             "[--tz-offset <hours>]")
    if not argv or not all(str(a).isdigit() for a in argv):
        _err(usage)
    removed = [r.strip() for r in (removed_raw or "").split(",") if r.strip()]
    if not all(r.isdigit() for r in removed):
        _err(usage)
    if now:
        try:
            canonical(now)
        except ValueError as e:
            _err("event-card: %s" % e)
    conn = event_conn()
    try:
        cards = event_cards(conn, argv, now=now, removed_ids=removed,
                            tz_name=tz_name, tz_offset=tz_offset)
        if cards:
            _emit_place_ask(conn, argv, removed)
        _emit_place_hours(conn, argv, removed, now=now)
        _emit_errand(conn, argv, removed, now=now)
        _emit_map_region(conn, argv, removed, now=now)
        _emit_place_coord(conn, argv, removed, now=now)
        _emit_card_block(cards, _event_card_map_buttons(conn, argv, removed))
    finally:
        conn.close()


DERIVED_RELAY = (
    "DERIVED_RELAY The ids in DERIVED are travel rows the kit derives from "
    "the appointments and stays around them. They follow those rows by "
    "themselves: never offer to cancel, move or confirm them, and never ask "
    "about them. The owner states a fact (stays over, goes straight there, "
    "comes home later) -> write THAT (presence-add / appt-upd) and the "
    "travel follows. Never print DERIVED or this line itself.")


def _event_day_line(item):
    """Render one event_day partition row for CLI. Columns:
      id<TAB>kind<TAB>title<TAB>start_local<TAB>end_local<TAB>place<TAB>status
      <TAB>retro_line   (retro-read-paths: trailing, '' if never set)"""
    (eid, _ulid, kind, title, sl, el, _sk, _tm, _bc, pname, st,
     retro_line) = item
    return f"{eid}\t{kind}\t{title}\t{sl}\t{el}\t{pname or ''}\t{st}\t{retro_line}"


# event-day's human part (owner 2026-10-07 09:15). Asked for today's to-do
# list, the life agent read event-day's rows and composed a list of its own: the 17:15
# move, the 18:00 appointment buffer and the 18:30 trip home as peers of the
# office stay and the dentist appointment, in a format the
# pinned card never uses. Prose routing to day-card --today had already
# failed, so the verb itself now ends with the card (day_today_card, the
# same text byte for byte) and no derived row is a row any more.
DAY_CARD_BEGIN = "DAY_CARD_BEGIN"
DAY_CARD_END = "DAY_CARD_END"
DAY_CARD_RELAY = (
    "DAY_CARD_RELAY The lines between DAY_CARD_BEGIN and DAY_CARD_END are "
    "the ALREADY RENDERED card of this date -- the same text the pinned "
    "workbench card and `day-card --today` show. When you tell the user "
    "about this day (its list, tasks, schedule), your reply IS those lines, "
    "reproduced VERBATIM, with at most ONE short line of your own on top: "
    "do NOT re-type, reorder, merge, bullet or re-word a line, and add no "
    "row of your own. Travel, prep and buffer are not items: they appear "
    "only as the departure line under the item they lead to. Every line "
    "above DAY_CARD_BEGIN (BAND / ANCHORED / DUE rows, ids, DERIVED) is "
    "machine data for verbs, NOT for the user: never show or paraphrase it. "
    "An empty card means nothing is on this date: say so in one line. Never "
    "print DAY_CARD_BEGIN, DAY_CARD_END or this DAY_CARD_RELAY line itself.")


def cli_event_day(argv):
    # event-day <YYYY-MM-DD> [tz] [--with-derived] [--now <UTC ISO>]
    #   THE day-view query (B1), two parts:
    #   1. machine rows, one partition per header so consumers can split:
    #      BAND <n> / ANCHORED <n> / DUE <n>, each followed by its rows.
    #      floating (untimed backlog) is excluded by contract; derived rows
    #      (travel / prep / buffer) are excluded too -- --with-derived puts
    #      them back in ANCHORED and names them on DERIVED (+ its relay), for
    #      travel maintenance only.
    #   2. the day card (day_today_card: day-card --today for that date),
    #      between DAY_CARD_BEGIN / DAY_CARD_END, then DAY_CARD_RELAY as the
    #      last line. That card is the only part a reply may show.
    usage = (u"\uc0ac\uc6a9\ubc95: kit_life.sh event-day <YYYY-MM-DD> [tz] "
             "[--with-derived] [--now <UTC ISO>]")
    argv = list(argv)
    argv, with_derived = _pop_flag(argv, "--with-derived")
    argv, now = _pop_opt(argv, "--now")
    if not argv or not argv[0] or not _DATE_RE.match(argv[0]) or len(argv) > 2:
        _err(usage)
    tz_arg = argv[1] if len(argv) > 1 and argv[1] else None
    tz = tz_arg or "Asia/Seoul"
    if now:
        try:
            canonical(now)
        except ValueError as e:
            _err("event-day: %s" % e)
    conn = event_conn()
    try:
        day = event_day(argv[0], tz_name=tz, conn=conn,
                        with_derived=with_derived)
        if any(item[2] == 'appointment' for rows in day.values() for item in rows):
            print(APPT_CONTEXT_RELAY, file=sys.stderr)
        card = day_today_card(conn, argv[0], now=now or now_utc(),
                              tz_name=tz_arg)
    finally:
        conn.close()
    derived = []
    for key, label in (("band", "BAND"), ("anchored", "ANCHORED"),
                       ("due", "DUE")):
        rows = day[key]
        print(f"{label} {len(rows)}")
        for item in rows:
            print(_event_day_line(item))
            if item[8] == TRAVEL_BLOCK_CLASS:
                derived.append(str(item[0]))
    # Travel rows print like tasks ("<move>: <home> ... open"). They are the
    # engine's, derived from the stays and appointments around them: the life agent
    # offered twice to cancel the trip home instead of writing the stay the
    # owner stated (2026-10-07). The marker rides the listing that shows them.
    if derived:
        print("DERIVED\t%s" % ",".join(derived))
        print(DERIVED_RELAY)
    print(DAY_CARD_BEGIN)
    if card:
        print(card)
    print(DAY_CARD_END)
    print(DAY_CARD_RELAY)


def cli_migrate_body_stats(argv):
    """body_stats.json 의 모든 키를 config 테이블로 복사(멱등, v2).

    DEFAULT_STATS 에 없는 키(goal_mode, skeletal_muscle_kg, updated 등)도 전부 복사한다.
    _CONFIG_STORE(=SqliteConfigStore) 경유로 upsert 하므로 몇 번 돌려도 안전(멱등).
    파일이 없으면 아무것도 안 하고 알린다(이미 클린 컷오버 후일 수 있음)."""
    if not os.path.isfile(BODY_STATS_PATH):
        print(f"migrate-body-stats: {BODY_STATS_PATH} 없음 (스킵)")
        return
    try:
        with open(BODY_STATS_PATH, encoding='utf-8') as f:
            raw = json.load(f)
    except (json.JSONDecodeError, OSError) as e:
        _err(f"migrate-body-stats: body_stats.json 읽기 실패: {e}")
    if not isinstance(raw, dict) or not raw:
        print("migrate-body-stats: 복사할 키 없음 (빈 파일)")
        return
    # update()가 'updated'를 오늘로 덮으니, 파일의 updated 를 보존하려면 마지막에
    # 파일 값으로 다시 씀. 여기선 전 키를 그대로 넘기고 update의 updated 자동갱신을 허용하되,
    # 파일에 updated 가 있으면 그 값으로 최종 덮어써 원본 이력을 보존한다.
    _CONFIG_STORE.update(dict(raw))
    if 'updated' in raw:
        # update()가 'updated'=오늘로 덮었으므로 파일의 원본 updated로 되돌린다(멱등 이력 보존).
        conn = get_conn()
        try:
            conn.execute(
                "INSERT INTO config (key, value) VALUES ('updated', ?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value, "
                "updated_at=datetime('now','localtime');", (str(raw['updated']),))
            conn.commit()
        finally:
            conn.close()
    keys = sorted(raw.keys())
    print(f"migrate-body-stats: {len(keys)}개 키 복사 완료 -> config")
    for k in keys:
        print(f"  {k}={raw[k]}")


def cli_body_state(argv):
    """현재 신체/목표 상태를 KEY=VALUE 로 출력(v2 hook/사람용).

    goal_mode + weight + 계산된 목표(compute_targets/compute_macro_goals)를 함께 낸다.
    hook 주입도 이 값을 재사용(1 SQLite read). 값은 SQL canonical(_CONFIG_STORE)에서 온다.

    2.20.0: 마지막 줄 `body_stats_defaults=` 는 위 숫자들 중 저장값이 아니라 코드
    기본값에서 온 키 목록이다(빈 값 = 전부 the owner's measured values). KEY=VALUE 블록이라
    life-skeleton-get 과 같은 규약으로 항상 찍는다 -- 없을 때만 찍으면 읽는 쪽이
    "이 줄이 없다"와 "이 verb 는 그런 줄을 안 낸다"를 구별할 수 없다."""
    conn = get_conn()
    try:
        stats = body_stats_for_conn(conn)
        t = targets_for_date(datetime.date.today().isoformat(), stats=stats, conn=conn)
    finally:
        conn.close()
    # Was compute_targets(stats, exercise_kcal=<a literal zero>): a hardcoded
    # rest day, the copy DGN-193 left behind (ticket 2026-09-02 D1).  Now the
    # one source, the same adjusted target the shared text card shows.
    g = resolve_macro_goals(t['eff_goal'], stats)
    print(f"goal_mode={stats.get('goal_mode', '')}")
    print(f"weight_kg={stats.get('weight_kg', '')}")
    print(f"bmr={t['bmr']}")
    print(f"neat={t['neat']}")
    print(f"deficit={t['deficit']}")
    print(f"eff_goal={t['eff_goal']}")
    print(f"protein_g={'' if g['protein'] is None else g['protein']}")
    print(f"carb_g={'' if g['carb'] is None else g['carb']}")
    print(f"fat_g={g['fat']}")
    # additive metadata (a parser of the keys above is unaffected)
    print(f"protein_source={g['protein_source']}")
    print(f"diet_style={g['style'] or ''}")
    print(f"macro_status={g['status']}")
    if g['protein_policy']:
        print(f"protein_policy={g['protein_policy']['name']}/"
              f"v{g['protein_policy']['version']}")
    # 064: additive.  burn_known=0 = trained today, burn not entered.
    # Owner 2026-10-18/19: calibrated burn contributes to the intake target.
    print(f"burn_kcal={_f0(t['burn_kcal'])}")
    print(f"burn_known={1 if t['burn_known'] else 0}")
    print("burn_role=target_allowance")
    print("body_stats_defaults=%s" % ','.join(body_stats_defaults_used(stats, macros=g)))


# life_skeleton_work_days canonical storage format (DGN-708 kit_life).
# Stored value is ALWAYS English 3-letter day abbrevs, comma-joined, in
# week order: e.g. "Mon,Tue,Wed,Thu,Fri". Consumers (the health agent's protein coaching,
# the life agent's reminders) parse this deterministically. Normalization is enforced here
# at WRITE time (forcing point) so any writer -- setup skill, agent, direct
# config-set -- yields the same canonical form regardless of input language.
_WD_ORDER = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
_WD_INDEX = {d: i for i, d in enumerate(_WD_ORDER)}
# token -> canonical abbrev. Korean single chars + optional 요일 suffix, and
# English full / abbrev names, case-insensitive.
_WD_TOKEN = {
    "mon": "Mon", "monday": "Mon", "월": "Mon", "월요일": "Mon",
    "tue": "Tue", "tues": "Tue", "tuesday": "Tue", "화": "Tue", "화요일": "Tue",
    "wed": "Wed", "weds": "Wed", "wednesday": "Wed", "수": "Wed", "수요일": "Wed",
    "thu": "Thu", "thur": "Thu", "thurs": "Thu", "thursday": "Thu",
    "목": "Thu", "목요일": "Thu",
    "fri": "Fri", "friday": "Fri", "금": "Fri", "금요일": "Fri",
    "sat": "Sat", "saturday": "Sat", "토": "Sat", "토요일": "Sat",
    "sun": "Sun", "sunday": "Sun", "일": "Sun", "일요일": "Sun",
}


def _wd_lookup(tok):
    tok = tok.strip()
    if not tok:
        return None
    return _WD_TOKEN.get(tok.lower())


def _normalize_work_days(value):
    """Normalize a work-days string to canonical 'Mon,Tue,...' form.

    Accepts Korean day names (월화수목금, 월~금, 월,화,수), English names/abbrevs
    (Mon-Fri, monday tuesday, Mon,Tue), ranges via '~' or '-', and comma /
    space / middot separators. Returns the canonical comma-joined abbrevs in
    week order with duplicates removed. If the input cannot be fully parsed,
    the ORIGINAL value is returned unchanged (fail-safe: never drop data)."""
    if value is None:
        return value
    raw = value.strip()
    if not raw:
        return value
    days = set()

    def _add(abbr):
        if abbr is not None:
            days.add(abbr)
        return abbr

    def _expand_range(a, b):
        ia, ib = _WD_INDEX[a], _WD_INDEX[b]
        if ia <= ib:
            for i in range(ia, ib + 1):
                days.add(_WD_ORDER[i])
        else:  # wrap-around, e.g. Sat~Mon
            for i in list(range(ia, 7)) + list(range(0, ib + 1)):
                days.add(_WD_ORDER[i])
        return True

    # Split into comma / space / middot separated segments first.
    segments = [s for s in re.split(r"[,\s·]+", raw) if s]
    for seg in segments:
        # Range within a segment: A~B or A-B (day names on both sides).
        m = re.match(r"^(.+?)\s*[~\-]\s*(.+)$", seg)
        if m:
            a, b = _wd_lookup(m.group(1)), _wd_lookup(m.group(2))
            if a and b:
                _expand_range(a, b)
                continue
            return value  # unparseable range -> leave original untouched
        # Whole segment as one token.
        hit = _wd_lookup(seg)
        if hit:
            _add(hit)
            continue
        # Korean run without separators, e.g. "월화수목금".
        if re.fullmatch(r"[월화수목금토일]+", seg):
            for ch in seg:
                _add(_wd_lookup(ch))
            continue
        return value  # unrecognized token -> leave original untouched
    if not days:
        return value
    return ",".join(d for d in _WD_ORDER if d in days)


_TRAVEL_MODES = ("transit", "walk", "car", "bike")


def cli_config_set(argv):
    # config-set key=value [key=value ...]
    # Upsert one or more config rows via _CONFIG_STORE (set_stats). 'updated' auto.
    # This is the CLI path the diet-status skill uses to persist body stats without
    # touching the config table directly (set_stats/SqliteConfigStore mirror).
    _u = ("Usage: kit_life.sh config-set key=value [key=value ...]\n"
          "  Upserts config rows (body stats). 'updated' auto-set to today.")
    if not argv:
        _err(_u)
    fields = {}
    for tok in argv:
        if '=' not in tok:
            _err(f"not key=value: {tok}\n{_u}")
        k, v = tok.split('=', 1)
        k = k.strip()
        if not k:
            _err(f"empty key: {tok}\n{_u}")
        if k in ("diet_style", "diet_protein_mode"):
            # standing nutrition policy: ledger first, config copy -- never a
            # bare config write (diet-target-set --style / --protein-mode)
            _err(f"{k} is written by diet-target-set (ledger first)")
        if k == "life_skeleton_work_days":
            v = _normalize_work_days(v)  # enforce canonical Mon,Tue,... on write
        elif k == "travel_mode":
            # The user's own mobility means (kit 2.27.1), read by
            # routines/travel-resolve.sh when no per-trip mode is given.
            # Recorded on demand, never seeded. Closed vocabulary so a free
            # word cannot land and read back as a mode the map cannot route.
            v = v.strip().lower()
            if v not in _TRAVEL_MODES:
                _err(f"travel_mode must be one of {'|'.join(_TRAVEL_MODES)}: {v!r}")
        elif k in (TRAVEL_PREP_ENABLED_KEY, kind_policy.TRAVEL_CALENDAR_ENABLED_KEY):
            v = v.strip()
            if v not in ("0", "1"):
                _err(f"{k} must be 0 or 1: {v!r}")
        elif k == TRAVEL_PREP_DEFAULT_KEY:
            # The user's default prep before leaving home (PREP_ASK answer):
            # whole minutes >= 0, grid-ceiled like every travel minute.
            digits = re.sub(r"[^0-9]", "", v)
            if not digits:
                _err(f"{TRAVEL_PREP_DEFAULT_KEY} must be minutes >= 0: {v!r}")
            v = str(_ceil_grid(int(digits)))
        fields[k] = v
    if not fields:
        _err(_u)
    if 'protein_g' in fields:
        fields['diet_protein_override'] = '1'
        fields['diet_protein_mode'] = 'manual'
    merged = set_stats(**fields)
    for k in sorted(fields.keys()):
        print(f"{k}={merged.get(k, '')}")
    if kind_policy.TRAVEL_CALENDAR_ENABLED_KEY in fields:
        conn = event_conn()
        try:
            for ev in _travel_rows(conn, "SELECT * FROM timeblock", ()):
                if (kind_policy.calendar_key(ev, conn) == "travel"
                        and (kind_policy.for_event(ev, conn)["mirror_surface"] == "calendar"
                             or ev.get("schedule_kind") != "untimed")):
                    _outbox_enqueue_best_effort(ev["ulid"])
        finally:
            conn.close()
    if set(fields) & {TRAVEL_PREP_DEFAULT_KEY, TRAVEL_PREP_ENABLED_KEY}:
        # A new default or opt-in switch changes expected prep: re-derive
        # the active rules now (the nightly conformance pass's own step)
        # instead of waiting a night. Best-effort; that pass converges anyway.
        conn = event_conn()
        try:
            for rule in _travel_rows(
                    conn, "SELECT * FROM travel_rule WHERE status='active';",
                    ()):
                travel_refresh_rule(conn, None, rule)
        except Exception:
            pass
        finally:
            conn.close()
    if set(fields) & {'weight_kg', 'height_cm', 'age', 'sex',
                      'target_weight_kg', 'protein_g'}:
        conn = get_conn()
        try:
            notice = _refresh_diet_from_body(conn)
        finally:
            conn.close()
        if notice:
            print(notice)


def cli_config_get(argv):
    # config-get <key> [--json] -- read-only mirror of config-set.
    # Prints the STORED value verbatim (config.value is TEXT; no cast, no
    # DEFAULT_STATS fallback -- a key nobody wrote is "unset", not a default).
    # Skills used to reach for raw SQL against the config table; this is the
    # verb for it. Unset key: nothing on stdout (or {"set": false} with
    # --json) and exit 1, so `v=$(kit_life.sh config-get k) || ...` works.
    _u = "Usage: kit_life.sh config-get <key> [--json]"
    argv, want_json = _pop_flag(argv, '--json')
    if len(argv) != 1 or not argv[0].strip():
        _err(_u)
    key = argv[0].strip()
    conn = get_conn()
    try:
        row = conn.execute(
            "SELECT value, updated_at FROM config WHERE key=? LIMIT 1;",
            (key,)).fetchone()
    finally:
        conn.close()
    if want_json:
        print(json.dumps({"key": key, "set": row is not None,
                          "value": None if row is None else row[0],
                          "updated_at": None if row is None else row[1]},
                         ensure_ascii=False))
    elif row is not None:
        print(row[0] if row[0] is not None else "")
    if row is None:
        sys.exit(1)


def cli_life_skeleton_get(argv):
    """life-skeleton-get -- read the owner's life-skeleton profile from the config table.

    Outputs KEY=VALUE lines (empty string when not yet set). Keys:
      life_skeleton_weekday_bed   HH:MM, weekday bedtime (local time)
      life_skeleton_weekday_wake  HH:MM, weekday wake time
      life_skeleton_weekend_bed   HH:MM, weekend bedtime
      life_skeleton_weekend_wake  HH:MM, weekend wake time
      life_skeleton_work_days     canonical: English 3-letter day abbrevs,
                                  comma-joined, week order Mon..Sun -- always
                                  "Mon,Tue,Wed,Thu,Fri" form regardless of the
                                  input language (normalized at write time by
                                  config-set). Consumers parse by splitting on
                                  ',' against Mon/Tue/Wed/Thu/Fri/Sat/Sun.
      life_skeleton_work_start    HH:MM, work day start
      life_skeleton_work_end      HH:MM, work day end

    Write via: kit_life.sh config-set life_skeleton_weekday_bed=HH:MM ...
    All keys are optional; absent = empty string (not yet captured).

    FILLED BY: onboard-sweep --capture (work_* keys, derived from the active
    non-base presence routine) and the onboarding interview's captured answers
    (sleep keys) -- see the core-setup engine (2.22.0). Key list is the
    module constant _LIFE_SKELETON_KEYS (single home, shared with the sweep)."""
    for k in _LIFE_SKELETON_KEYS:
        v = get_config(k, "")
        print(f"{k}={v}")


def cli_health_agent_get(argv):
    """health-agent-get -- which slug health-domain rows are stamped with.

    Prints KEY=VALUE lines:
      health_domain_agent=<slug>
      source=env|crew|derived|default
      fact=<the machine fact that won>        (derived; for default: why the
                                               derivation fell through)
      recorded_owner=<slug|->                 (the owner the last health write
                                               recorded; '-' = none yet)
    'env' = LIFEKIT_HEALTH_AGENT in THIS process only; 'crew' = the manual
    override row written by health-agent-set; 'derived' = read from the crew's
    members (the normal path -- nobody has to set anything); 'default' = no
    fact decides."""
    slug, source, fact = _health_agent_resolve_full()
    print(f"{HEALTH_DOMAIN_AGENT_KEY}={slug}")
    print(f"source={source}")
    if source in ("derived", "default") and fact:
        print(f"fact={fact}")
    recorded = None
    if os.path.isfile(DB_PATH):
        try:
            conn = sqlite3.connect(DB_PATH, timeout=5)
            try:
                recorded = _health_owner_recorded(conn)
            finally:
                conn.close()
        except sqlite3.Error:
            recorded = None
    print(f"recorded_owner={recorded or '-'}")


# ── scope-self (2.38.0, domain brief/retro standard) ─────────────────────
# Which lines THIS instance may emit in its brief / daily retro / weekly
# review. Nothing new is stored: the role is the instance's own
# DOGANY_AGENT_CLASS (missing = main, the framework convention), and a
# domain's owner is the one _health_agent_resolve_full already derives from
# the crew's members. A domain no member serves belongs to the main agent.
#
# Domains the kit knows a crew owner for, with the retro module that carries
# their lines and the legacy owner tokens their task rows may still carry
# (the retired health slug stamped tasks before the 2026-09 re-mint).
_SCOPE_DOMAINS = {
    "health": {"module": "module_health",
               "aliases": (_HEALTH_DOMAIN_AGENT_RETIRED,)},
}
SCOPE_INSTANCE_ROOT_ENV = "LIFEKIT_INSTANCE_ROOT"


def _instance_root():
    """This instance's root: the parent of the database dir (the same root
    _health_crew_members uses for a solo instance). LIFEKIT_INSTANCE_ROOT
    overrides it for tests and for a caller that runs the kit from a shared
    checkout."""
    env = os.environ.get(SCOPE_INSTANCE_ROOT_ENV, "").strip()
    return env or _kit_root()


def _root_conf_get(root, key):
    """First `key=` value in <root>/config/agent.conf (whitespace, then one
    matched quote pair stripped -- agent_conf's convention), '' if absent."""
    try:
        with open(os.path.join(root, "config", "agent.conf"),
                  encoding="utf-8", errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if line.startswith(key + "="):
                    return agent_conf._unquote(line.split("=", 1)[1].strip()).strip()
    except OSError:
        pass
    return ""


_SCOPE_LEGACY_OWNERS = ("user",)


def read_scope(agent=None):
    """THE read scope of the crew leader: owner tokens whose timeblock /
    task / appointment rows a READ surface shows. Owner 2026-10-13: "\uc544\uadf8\ub294
    \uc81c\ub108\ub7f4\ub9ac\uc2a4\ud2b8\ub77c \ubaa8\ub4e0 \uc77c\uc815\uacfc \uc57d\uc18d, \ud560 \uc77c\uc744 \uc54c\uc544\uc57c \ub3fc" -- the life crew leader
    sees every member's schedule, so every reader that filters by
    owning_agent takes its tokens from here (a domain agent keeps its own
    scope_self task_scope). Members = crew.conf members' agent names plus the
    leader; a retired member's legacy alias (and 'user') only while it still
    owns an OPEN row. [] = unscoped (a solo instance reads everything, as
    before). Writes keep their own owning_agent; notify scope
    (REMIND_EXCLUDE_OWNERS) is a separate knob. Never raises."""
    try:
        _reg, roots = _health_crew_members()
        toks = [agent] if agent else []
        for r in roots:
            n = _instance_conf_read(r).get("DOGANY_AGENT_NAME", "").strip().lower()
            if _AGENT_SLUG_RE.match(n) and n not in toks:
                toks.append(n)
        if len(roots) <= 1:
            return []
        legacy = [a for d in _SCOPE_DOMAINS.values() for a in d["aliases"]]
        legacy += list(_SCOPE_LEGACY_OWNERS)
        try:
            c = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
            try:
                open_own = {r[0] for r in c.execute(
                    "SELECT DISTINCT owning_agent FROM timeblock "
                    "WHERE settled_at IS NULL;")}
            finally:
                c.close()
        except sqlite3.Error:
            open_own = set(legacy)       # unreadable: show more, not less
        toks += [a for a in legacy if a and a in open_own and a not in toks]
        return toks
    except Exception:  # noqa: BLE001
        return []


def scope_self():
    """dict: role, agent, owns, others_own, skip_modules, task_scope,
    leader_root. Read-only, never raises (a fact we cannot read decides
    nothing: the instance is then main and owns what no one else owns)."""
    root = _instance_root()
    conf = _instance_conf_read(root)
    agent = conf.get("DOGANY_AGENT_NAME", "").strip().lower()
    if not _AGENT_SLUG_RE.match(agent):
        agent = ""
    role = (conf.get("DOGANY_AGENT_CLASS", "") or "main").strip().lower()
    role = "domain" if role == "domain" else "main"
    owns, others = [], []
    for dom in _SCOPE_DOMAINS:
        if dom == "health":
            try:
                slug, source, _fact = _health_agent_resolve_full()
            except Exception:
                slug, source = None, "default"
            mine = (bool(agent) and slug == agent) or (
                role == "main" and source == "default")
        else:   # pragma: no cover -- one domain today
            mine = role == "main"
        (owns if mine else others).append(dom)
    knob = _root_conf_get(root, "TASK_OWNING_AGENT")
    if role == "main":
        # the crew leader reads EVERY member's rows (owner 2026-10-13): the
        # TASK_OWNING_AGENT knob narrows a domain agent, never the leader.
        scope = read_scope(agent)
    elif knob:
        scope = [t.strip().lower() for t in knob.split(",") if t.strip()]
    elif role == "domain" and agent:
        scope = [agent]
        for dom in owns:
            scope += [a for a in _SCOPE_DOMAINS[dom]["aliases"]
                      if a and a not in scope]
    else:
        scope = []          # unscoped main instance: byte-identical reads
    return {
        "role": role,
        "agent": agent or "-",
        "owns": ",".join(owns),
        "others_own": ",".join(others),
        "skip_modules": ",".join(_SCOPE_DOMAINS[d]["module"] for d in others),
        "task_scope": ",".join(scope),
        "leader_root": (conf.get("DOGANY_LEADER_ROOT", "") or "-").strip(),
    }


def cli_scope_self(argv):
    """scope-self [--json] -- this instance's brief/retro scope (2.38.0).

    KEY=VALUE lines, always in this order:
      role=main|domain        DOGANY_AGENT_CLASS (missing = main)
      agent=<slug|->          DOGANY_AGENT_NAME
      owns=<d1,d2|>           crew domains this instance owns (health)
      others_own=<d|>         crew domains another member owns
      skip_modules=<m|>       retro modules of others_own (retro-sections
                              --skip-module)
      task_scope=<a,b|>       owner tokens for task read verbs: TASK_OWNING_AGENT
                              when set; a domain agent otherwise reads its own
                              slug plus the legacy aliases of what it owns; an
                              unscoped main agent prints nothing (reads stay
                              byte-identical)
      leader_root=<path|->    DOGANY_LEADER_ROOT
    Read-only; opens no database for writing."""
    d = scope_self()
    if "--json" in argv:
        print(json.dumps(d, ensure_ascii=False, sort_keys=True))
        return
    for k in ("role", "agent", "owns", "others_own", "skip_modules",
              "task_scope", "leader_root"):
        print(f"{k}={d[k]}")


def cli_health_agent_set(argv):
    """health-agent-set <slug> -- MANUAL OVERRIDE of the crew-level
    health-domain owner. Not a setup step: the owner is derived from the crew's
    members (see health-agent-get). Use it only when those facts point the
    wrong way.

    Writes the override row in the crew-shared DB (config-set is the wrong
    door: it also bumps the body-stats 'updated' date) and hands the domain
    over in the SAME transaction: health-domain rows stamped with the recorded
    owner are relabeled to <slug>, exactly as the next health write would."""
    _u = ("Usage: kit_life.sh health-agent-set <slug>\n"
          "  slug: lowercase agent slug, e.g. ag")
    if len(argv) != 1:
        _err(_u)
    slug = str(argv[0]).strip()
    if not _AGENT_SLUG_RE.match(slug):
        _err(f"not an agent slug: {argv[0]!r}\n{_u}")
    conn = get_conn()
    try:
        conn.execute(
            "INSERT INTO config (key, value) VALUES (?, ?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value, "
            "updated_at=datetime('now','localtime');",
            (HEALTH_DOMAIN_AGENT_KEY, slug))
        _health_domain_handover(conn, slug)
        conn.commit()
    finally:
        conn.close()
    slug_now, source = _health_agent_resolve()
    print(f"{HEALTH_DOMAIN_AGENT_KEY}={slug}")
    if source == "env":
        # The row landed, but THIS process is overridden -- say so rather than
        # let the caller believe the stamp changed here.
        print(f"WARN {HEALTH_DOMAIN_AGENT_ENV}={slug_now} overrides the crew "
              f"setting in this process", file=sys.stderr)


def cli_log_metric(argv, edit=False):
    # log-metric <date> <metric> <value> [note]
    # Upsert a single time-series measurement (one row per (date, metric)).
    if len(argv) < 3 or not argv[0] or not argv[1]:
        _err("Usage: kit_life.sh log-metric <date> <metric> <value> [note]")
    date, metric, value = argv[0], argv[1], argv[2]
    note = argv[3] if len(argv) > 3 else None
    conn = get_conn()
    try:
        existing = conn.execute("SELECT id,note FROM metric_log WHERE date=? AND metric=?",
                                (date, metric)).fetchone()
    finally:
        conn.close()
    if edit and not existing:
        _err("metric-edit: observation not found; use log-metric to create it")
    if edit and len(argv) == 3:
        note = existing[1]
    mid = log_metric(date, metric, value, note=note, update_only=edit)
    # Echo the STORED value on the metric's declared grid (_metric_echo):
    # 2.1.0 echoed _f0() while storing the decimal, so 21.5 printed as 22 --
    # the store was right and the echo lied.  Undeclared metrics keep the
    # legacy integer echo byte-identical.
    print(f"{mid}\t{date}\t{metric}\t{_metric_echo(metric, value)}")
    _metric_write_notices(metric, value, date, note, existing, mid)


def _metric_write_notices(metric, value, date, note, existing, mid):
    """Shared post-commit readback hooks for individual and sheet writes."""
    # Touchpoint hook (cut 1): this verb IS where a body metric gets touched,
    # so the cadence question surfaces HERE -- as a machine line the skill
    # renders, not as skill prose that can forget.  Emitted ONLY while the
    # metric is guided-class and unconfirmed; one freshness-set later this
    # line stops forever (ask once = structural, not discipline).
    # 2.1.1 owner gate: the ask belongs to the agent owning the metric's
    # domain (owner ruling 2026-09-08: the shared skill is correct, the ask
    # is the health agent's).  Caller identity = _facade_agent(), the same path the
    # appt/insight owning_agent stamps use.  A non-owning caller records in
    # silence and the UNCONSUMED ask stays live for the owner's next touch;
    # a guided token whose domain has no declared owner is fail-closed
    # silence, never an open ask.  The line itself CARRIES domain + owner so
    # a reading skill can gate on data, not on remembered prose.
    conn = get_conn()
    try:
        # weight_kg: the key the weight answer and health-log write
        # body weight under (_METRIC_LOG_KEYS).
        prof = _PROFILE_FROM_METRIC.get(metric)
        if prof is not None and _config_stored(conn, prof[0]) == \
                _fmeas(_num(value, None)):
            # the profile now holds this reading (_profile_from_metric)
            print("PROFILE\t%s\t%s" % (prof[0], _fmeas(_num(value, None))))
        if metric in ('body_weight', 'weight_kg', 'body_fat_pct',
                      'skeletal_muscle_kg', 'lean_mass_kg',
                      'fat_free_mass_kg', 'ffm_kg', 'height_cm'):
            notice = _refresh_diet_from_body(conn)
            if notice:
                print(notice)
        # A goal set on a stale InBody: a newer weight / InBody is the cue
        # to propose the update (the agent speaks the line's last field).
        # record-always-on: both proposals below are the health module's
        # management lens; the reading itself is already written.
        manage = _manage_on(conn, 'module_health')
        if manage:
            for line in _inbody_basis_notice(conn, metric, date, note):
                print(line)
        state, hours, why, domain, owner = metric_cadence_state(conn, metric)
    finally:
        conn.close()
    if manage and state == 'ask' and owner is not None \
            and owner == _facade_agent():
        print("CADENCE-ASK\t%s\t%s\t%s\t%s\t%s"
              % (metric, _fh(hours), domain, owner, why))
    conn = get_conn()
    try:
        if existing:
            _capture_open_today(conn)
            return
        _capture_open_today(conn, "log-metric", mid,
                            conn.execute("SELECT date FROM " + "metric_log" +
                                         " WHERE id=?", (mid,)).fetchone()[0], "metric_log")
    finally:
        conn.close()



# Closed vocabulary for an atomic sheet; individual log-metric remains open.
_BODY_SHEET_KEYS = frozenset(_METRIC_ECHO_DECIMALS) | frozenset((
    "weight_kg", "body_weight", "body_fat_pct", "skeletal_muscle_kg",
    "fat_mass_kg", "fat_free_mass_kg", "ffm_kg", "height_cm",
    "visceral_fat_level", "bmr_kcal", "inbody_score"))


def cli_log_body_sheet(argv):
    """log-body-sheet <date> <note> <key=value> [...] (atomic upsert)."""
    usage = "Usage: kit_life.sh log-body-sheet <YYYY-MM-DD> <note> <key=value> [...]"
    if len(argv) < 3:
        print("BODY-SHEET written 0 / rejected 0 names=-")
        _err(usage)
    day, note = argv[:2]
    entries, rejected = {}, []
    try:
        if datetime.date.fromisoformat(day).isoformat() != day:
            raise ValueError("non-canonical date")
    except ValueError:
        rejected.append("date")
    for token in argv[2:]:
        key, sep, value = token.partition("=")
        try:
            if not sep or key not in _BODY_SHEET_KEYS or key in entries:
                raise ValueError("unknown, malformed or duplicate key")
            entries[key] = _metric_input_value(value)
        except ValueError:
            rejected.append(key or token)
    if rejected:
        print("BODY-SHEET written 0 / rejected %d names=%s" % (
            len(rejected), ",".join(rejected)))
        _err("log-body-sheet: sheet rejected; no measurements written")
    conn = None
    try:
        conn = get_conn()
        rows = []
        for key, value in entries.items():
            existing = conn.execute(
                "SELECT id FROM metric_log WHERE date=? AND metric=?;",
                (day, key)).fetchone()
            mid = log_metric(day, key, value, note=note, conn=conn, commit=False)
            rows.append((key, value, existing, mid))
        # These profile facts belong to the sheet transaction too. A backfill
        # must not replace a later measured profile value.
        for key in ("weight_kg", "skeletal_muscle_kg", "fat_mass_kg", "lean_mass_kg"):
            if key not in entries:
                continue
            keys = _METRIC_LOG_KEYS.get("body_weight", (key,)) \
                if key == "weight_kg" else (key,)
            later = conn.execute(
                "SELECT 1 FROM metric_log WHERE metric IN (%s) AND date>? LIMIT 1;"
                % ",".join("?" * len(keys)), tuple(keys) + (day,)).fetchone()
            if not later:
                _config_put(conn, key, _fmeas(entries[key]))
        stored = conn.execute(
            "SELECT metric,value FROM metric_log WHERE date=? AND metric IN (%s);"
            % ",".join("?" * len(entries)), (day,) + tuple(entries)).fetchall()
        if dict(stored) != entries:
            raise ValueError("sheet readback does not match the submitted measurements")
        conn.commit()
    except (Exception, SystemExit) as exc:
        if conn is not None:
            conn.rollback()
        print("BODY-SHEET written 0 / rejected %d names=%s" % (
            len(entries), ",".join(entries)))
        _err("log-body-sheet: transaction failed: %s" % exc)
    finally:
        if conn is not None:
            conn.close()
    print("BODY-SHEET written %d / rejected 0 names=%s" % (
        len(stored), ",".join(key for key, _value in stored)))
    for key, value, existing, mid in rows:
        print("%s\t%s\t%s\t%s" % (mid, day, key, _metric_echo(key, value)))
        try:
            _metric_write_notices(key, value, day, note, existing, mid)
        except (Exception, SystemExit) as exc:
            _err("log-body-sheet: measurements persisted; post-write hook failed: %s" % exc)


def cli_metric_edit(argv):
    # metric-edit <date> <metric> <value> [note] -- correction, never creation.
    if len(argv) < 3:
        _err("Usage: kit_life.sh metric-edit <date> <metric> <value> [note]")
    # Reuse the ordinary mutation path so profile/cadence/capture side effects
    # remain identical to an overwrite through log-metric.
    cli_log_metric(argv, edit=True)


# metric-del: one dated body-composition record set taken back in
# conversation (a wrong InBody photo, a sheet logged twice). metric_log holds one row per
# (date, metric), so a date (+ the InBody note health-log writes) names
# the set exactly. The profile keys health-log copies into config
# (step 4) are taken back with it when they came from this record: the
# stored value equals the deleted one and no later reading exists. Such a
# key falls back to the newest remaining reading, else it is unset.
_METRIC_DEL_SOURCES = ("inbody",)
_METRIC_DEL_CONFIG = {"weight_kg": ("weight_kg", "body_weight"),
                      "skeletal_muscle_kg": ("skeletal_muscle_kg",),
                      "fat_mass_kg": ("fat_mass_kg",),
                      "lean_mass_kg": ("lean_mass_kg",),
                      # 2.42.0: an InBody sheet's height lands in the profile
                      # (_profile_from_metric); taking the sheet back reverts it
                      "height_cm": ("height_cm",)}


def _profile_kept(conn, key):
    """True when `key` is a stable profile fact (068 profile_keep): it is
    never deleted, only re-valued."""
    try:
        return conn.execute("SELECT 1 FROM profile_keep WHERE key=?;",
                            (key,)).fetchone() is not None
    except sqlite3.OperationalError:
        return False


def metric_del(conn, date, source=None, owning_agent=None):
    """Delete the metric_log rows of `date` (InBody-noted only when source
    is 'inbody'; one owner's only with owning_agent). Returns (deleted rows
    [(metric, value, note, owning_agent)], config changes [(key, old, new
    or None)], rows left on the date that the filters kept). The caller
    commits."""
    rows = conn.execute(
        "SELECT id, metric, value, note, owning_agent FROM metric_log "
        "WHERE date=? ORDER BY metric;", (date,)).fetchall()
    hit, kept = [], []
    for r in rows:
        ok = owning_agent is None or r[4] == owning_agent
        if source == "inbody":
            ok = ok and (r[3] or "").strip().lower().startswith("inbody")
        (hit if ok else kept).append(r)
    for r in hit:
        conn.execute("DELETE FROM metric_log WHERE id=?;", (r[0],))
    gone = {r[1]: r[2] for r in hit}
    changes = []
    for key, metrics in _METRIC_DEL_CONFIG.items():
        mine = [gone[m] for m in metrics if m in gone]
        cur = _config_stored(conn, key)
        if not mine or cur is None:
            continue
        try:
            same = any(abs(float(cur) - float(v)) < 1e-6 for v in mine)
        except (TypeError, ValueError):
            same = False
        q = ",".join("?" * len(metrics))
        later = conn.execute(
            "SELECT 1 FROM metric_log WHERE metric IN (%s) AND date>? "
            "LIMIT 1;" % q, tuple(metrics) + (date,)).fetchone()
        if not same or later:
            continue
        prev = conn.execute(
            "SELECT value FROM metric_log WHERE metric IN (%s) "
            "ORDER BY date DESC, id DESC LIMIT 1;" % q,
            tuple(metrics)).fetchone()
        if prev is not None:
            _config_put(conn, key, _fmeas(prev[0]))
            changes.append((key, cur, _fmeas(prev[0])))
        elif _profile_kept(conn, key):
            continue        # no earlier reading: the kept fact stays as is
        else:
            conn.execute("DELETE FROM config WHERE key=?;", (key,))
            changes.append((key, cur, None))
    return ([(r[1], r[2], r[3], r[4]) for r in hit], changes,
            [(r[1], r[2], r[3], r[4]) for r in kept])


def cli_metric_del(argv):
    # metric-del --date YYYY-MM-DD [--source inbody] [--owning-agent A]
    # Deletes one dated record set from metric_log and prints every row it
    # removed; a profile key copied from that record is put back (see
    # metric_del). Nothing matching -> exit 1 naming what IS on that date.
    _u = ("Usage: kit_life.sh metric-del --date YYYY-MM-DD [--source inbody] "
          "[--owning-agent A]\n"
          "  Deletes that date's metric_log rows (--source inbody: only the "
          "rows noted InBody...) and prints each one removed.")
    argv, date = _pop_opt(argv, '--date')
    argv, source = _pop_opt(argv, '--source')
    argv, owner = _pop_opt(argv, '--owning-agent')
    if argv or not date:
        _err(_u)
    try:
        datetime.date.fromisoformat(date)
    except ValueError:
        _err("metric-del: --date must be YYYY-MM-DD: %r\n%s" % (date, _u))
    if source is not None and source not in _METRIC_DEL_SOURCES:
        _err("metric-del: --source must be one of %s: %r"
             % ("|".join(_METRIC_DEL_SOURCES), source))
    conn = get_conn()
    try:
        hit, changes, kept = metric_del(conn, date, source, owner)
        if not hit:
            conn.rollback()
            what = ", ".join("%s=%s (%s, %s)" % (m, _metric_echo(m, v),
                                                 n or "no note", o)
                             for m, v, n, o in kept)
            _err("metric-del: nothing deleted -- no metric_log row on %s "
                 "matches%s%s. On that date: %s"
                 % (date, " --source %s" % source if source else "",
                    " --owning-agent %s" % owner if owner else "",
                    what or "no rows at all"))
        conn.commit()
        print("DELETED\t%s\t%d" % (date, len(hit)))
        for m, v, n, o in hit:
            print("  ROW\t%s\t%s\t%s\t%s" % (m, _metric_echo(m, v),
                                            n or "-", o))
        for key, old, new in changes:
            print("  CONFIG\t%s\t%s -> %s" % (key, old,
                                              new if new is not None
                                              else "(unset)"))
        for m, v, n, o in kept:
            print("  KEPT\t%s\t%s\t%s\t%s" % (m, _metric_echo(m, v),
                                             n or "-", o))
        gone = {m for m, _v, _n, _o in hit}
        for gid, gm in conn.execute(
                "SELECT id, metric FROM ledger_goal WHERE "
                "substr(baseline_as_of,1,10)=? AND metric IS NOT NULL "
                "AND status IN ('active','proposed') ORDER BY id;",
                (date,)).fetchall():
            if gm in gone:
                print("  GOAL-BASELINE\t%s\t%s\t(baseline was this record; "
                      "the goal itself is unchanged)" % (gid, gm))
        if gone & {'body_weight', 'weight_kg', 'body_fat_pct',
                   'skeletal_muscle_kg', 'lean_mass_kg', 'fat_free_mass_kg',
                   'ffm_kg'} or changes:
            notice = _refresh_diet_from_body(conn)
            if notice:
                print(notice)
    finally:
        conn.close()

# ── freshness cadence hooks (cut 1) ───────────────────────────────────────
# The machinery half of the three-way ownership split declared at
# _CADENCE_GUIDED (module cargo).  Three verbs:
#   freshness-touch   what a skill runs when it touches a metric: says
#                     confirmed / ask / silent, and CARRIES the guideline on
#                     'ask' so no skill ever asks a bare question -- plus the
#                     metric's domain + owning agent (2.1.1) so a share-mode
#                     skill can gate "is this mine?" on data.
#   freshness-set     the user's answer lands (declared_by='user').  The one
#                     write path a skill uses; raw SQL stays banned.
#   freshness-report  the RETRO hook: metrics stale by their OWN declared
#                     cadence.  No cadence -> not even mentioned (fail-closed
#                     both ways: never fresh, never nagged).

_CANON_GLOB = ('[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T'
               '[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z')

_CADENCE_KEYWORDS = {'daily': 24.0, 'weekly': 168.0,
                     'biweekly': 336.0, 'monthly': 720.0}


def _fh(h):
    """Hours for TAB output: integral -> bare int, else %g. '-' for None."""
    if h is None:
        return '-'
    f = float(h)
    return str(int(f)) if f == int(f) else ('%g' % f)


def metric_cadence_state(conn, metric):
    """-> (state, hours, why, domain, owner).  states:
    confirmed  a metric_freshness row exists.  NEVER re-ask.
    ask        guided-class, unanswered: hours/why carry the module guideline
               the question must be asked WITH.
    silent     no row, no guideline: fail-closed, nobody asks anything.
    domain/owner: the metric's crew-lane domain and the agent slug owning it
    (_cadence_domain_owner) -- carried in EVERY state for a guided token
    (ownership does not vanish with confirmation), None elsewhere.
    A FIXED-class token with no row is declared on the spot (the touch is a
    module act, same footing as the meal-write declaration) and reads back
    'confirmed'."""
    guided = _CADENCE_GUIDED.get(metric)
    domain = guided[3] if guided else None
    owner = _cadence_domain_owner(domain) if domain else None
    row = conn.execute(
        "SELECT stale_after_hours FROM metric_freshness WHERE metric=?",
        (metric,)).fetchone()
    if row is not None:
        return ('confirmed', float(row[0]), None, domain, owner)
    if metric in _CADENCE_FIXED:
        _cadence_declare_fixed(conn, (metric,))
        conn.commit()
        return ('confirmed', _CADENCE_FIXED_HOURS, None, domain, owner)
    if guided is not None:
        hours, why = guided[0], guided[1]
        return ('ask', hours, why, domain, owner)
    return ('silent', None, None, None, None)


def cli_freshness_touch(argv):
    # freshness-touch <metric>
    # -> <metric>\t<confirmed|ask|silent>\t<hours|->\t<domain|->\t<owner|->
    #    \t<why|->
    # domain/owner (2.1.1): same fields the CADENCE-ASK line carries.  This
    # is a READ verb, so it reports identically to every caller -- the
    # render gate ("is this mine?") is the reading skill's, decided against
    # the owner field, never against remembered prose.
    if not argv or not argv[0]:
        _err("Usage: kit_life.sh freshness-touch <metric>")
    conn = get_conn()
    try:
        state, hours, why, domain, owner = metric_cadence_state(conn, argv[0])
    finally:
        conn.close()
    print("%s\t%s\t%s\t%s\t%s\t%s" % (argv[0], state, _fh(hours),
                                      domain or '-', owner or '-',
                                      why or '-'))


def cli_freshness_set(argv):
    # freshness-set <metric> <daily|weekly|biweekly|monthly|<hours>> [note...]
    # The USER's confirmed cadence.  Upsert: answering again (a deliberate
    # change of mind) is allowed -- what is banned is RE-ASKING, and that ban
    # lives in metric_cadence_state, not here.
    _u = ("Usage: kit_life.sh freshness-set <metric> "
          "<daily|weekly|biweekly|monthly|hours> [note]")
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err(_u)
    metric, spec = argv[0], argv[1].strip().lower()
    note = " ".join(argv[2:]) if len(argv) > 2 else None
    hours = _CADENCE_KEYWORDS.get(spec)
    if hours is None:
        try:
            hours = float(spec)
        except ValueError:
            _err("bad cadence %r -- want daily|weekly|biweekly|monthly or "
                 "hours as a number\n%s" % (spec, _u))
        if hours <= 0:
            _err("cadence hours must be > 0: %r" % spec)
    conn = get_conn()
    try:
        if conn.execute("SELECT 1 FROM metric_def WHERE token=?",
                        (metric,)).fetchone() is None:
            guided = _CADENCE_GUIDED.get(metric)
            if guided is None:
                # Fail-closed: metric_freshness FKs metric_def, and a token
                # unknown to both the schema and the module guideline layer
                # gets NO invented registration.
                _err("unknown metric %r: no metric_def row and no module "
                     "guideline -- register the metric first" % metric)
            # Body-comp tokens predate their metric_def rows (the metric_log
            # lane never registered).  Register from module cargo, the same
            # defensive-registration idiom the travel lane uses.  owner_module
            # stays NULL: the body-comp -> DB-domain mapping is the owner's
            # (037 §6.1d), not this verb's.  (The crew-lane owner the 2.1.1
            # ask gate uses is a different axis and rides as module cargo,
            # _cadence_domain_owner -- it is NOT written here either.)
            unit = guided[2]
            conn.execute(
                "INSERT INTO metric_def(token, scope_kind, accrual, "
                "unit_token, owner_module, origin) "
                "VALUES (?,?,?,?,NULL,'module')",
                (metric, 'entity', 'observed', unit))
        conn.execute(
            "INSERT INTO metric_freshness(metric, stale_after_hours, "
            "declared_by, note) VALUES (?,?,'user',?) "
            "ON CONFLICT(metric) DO UPDATE SET "
            "stale_after_hours=excluded.stale_after_hours, "
            "declared_by='user', note=excluded.note",
            (metric, hours, _txt(note)))
        conn.commit()
    finally:
        conn.close()
    print("%s\t%s\tuser" % (metric, _fh(hours)))


def cli_freshness_report(argv):
    # freshness-report [--all]
    # -> one TAB row per DECLARED metric that is not fresh:
    #    <metric>\t<stale|noarrival>\t<cadence_h>\t<last_observed|->\t
    #    <age_h|->\t<owner_module|->\t<declared_by>
    # --all additionally shows fresh metrics (flag 'fresh') for debugging.
    #
    # This is the RETRO hook's read surface.  The freshness idiom is the
    # 037 view's, restated once: basis='actual' only (a plan is not an
    # arrival), valid_until in force (a superseded value is not an arrival),
    # and the GRADE FLOOR + FUTURE CLAMP (a date-only observed_at counts
    # from 00:00:00Z of its own day, and a graded instant may never exceed
    # now -- 038: without the clamp a local-grade stamp floored to a FUTURE
    # instant between 00:00 and 09:00 local and its negative age read
    # 'fresh' through every window.  Error bounded, always toward STALE;
    # an excluded-only metric reads 'noarrival', never 'fresh').  Values come
    # from `measure` and nowhere else (S1: one home, one shape, one bug) --
    # so a lane that has not ported (metric_log, workouts, spend_entry)
    # reads 'noarrival' here, which is the truth about the value house, not
    # about the user.  Metrics with NO declared cadence are absent by
    # construction: this SELECT starts from metric_freshness.
    argv, show_all = _pop_flag(argv, '--all')
    now = now_utc()
    now_dt = datetime.datetime.strptime(now, '%Y-%m-%dT%H:%M:%SZ')
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT mf.metric, mf.stale_after_hours, mf.declared_by, "
            "       md.owner_module, "
            "       (SELECT MAX(CASE WHEN m.observed_at GLOB ? "
            "                        THEN m.observed_at "
            "                        ELSE substr(m.observed_at,1,10) "
            "                             || 'T00:00:00Z' END) "
            "          FROM measure m "
            "         WHERE m.metric = mf.metric "
            "           AND m.basis = 'actual' "
            "           AND (m.valid_until IS NULL OR m.valid_until > ?) "
            "           AND (CASE WHEN m.observed_at GLOB ? "
            "                     THEN m.observed_at "
            "                     ELSE substr(m.observed_at,1,10) "
            "                          || 'T00:00:00Z' END) <= ?) "
            "  FROM metric_freshness mf "
            "  JOIN metric_def md ON md.token = mf.metric "
            " ORDER BY COALESCE(md.owner_module,''), mf.metric",
            (_CANON_GLOB, now, _CANON_GLOB, now)).fetchall()
    finally:
        conn.close()
    for metric, hours, declared_by, owner_module, last_obs in rows:
        if last_obs is None:
            flag, age_h = 'noarrival', None
        else:
            obs_dt = datetime.datetime.strptime(last_obs, '%Y-%m-%dT%H:%M:%SZ')
            age_h = (now_dt - obs_dt).total_seconds() / 3600.0
            flag = 'stale' if age_h > float(hours) else 'fresh'
        if flag == 'fresh' and not show_all:
            continue
        print("%s\t%s\t%s\t%s\t%s\t%s\t%s"
              % (metric, flag, _fh(hours), last_obs or '-',
                 '-' if age_h is None else '%.1f' % age_h,
                 owner_module or '-', declared_by))


TREND_USAGE = ("사용법: kit_life.sh trend <metric> [--window <일수>] [--json]\n"
               "  --window 는 정수 일수(7 또는 7일)\n"
               "  <metric> ∈ {%s}" % ', '.join(sorted(TREND_REGISTRY)))


def cli_trend(argv):
    # trend <metric> [--window <일수>] [--json]
    #   --window <일수>  창을 N일로 덮어씀(기본은 지표별 레지스트리 창:
    #                 weekly-point 12주=84일, daily-multi 7일).
    #   --json        호출부(스킬/루틴)가 쓰는 구조체를 그대로 출력.
    # 레지스트리에 없는 지표는 등재된 지표 목록을 보여주고 종료코드 1
    # (오늘 실측된 결함: "동사는 있는데 사용법에 없어 없는 줄 알았다" --
    # 이 verb는 USAGE/main()의 명령 목록 둘 다에 등재돼 있다).
    argv, want_json = _pop_flag(argv, '--json')
    argv, window_opt = _pop_opt(argv, '--window')
    if not argv or not argv[0]:
        _err(TREND_USAGE)
    metric = argv[0]
    if metric not in TREND_REGISTRY:
        print("알 수 없는 지표: %s" % metric, file=sys.stderr)
        print("(%s)" % ', '.join(sorted(TREND_REGISTRY)), file=sys.stderr)
        sys.exit(1)
    window_days = None
    if window_opt is not None:
        # "7" and "7일" both mean 7 days; anything else is a usage error, not
        # a traceback.
        m = re.fullmatch(r"\s*(\d+)\s*일?\s*", window_opt)
        if not m or int(m.group(1)) < 1:
            _err("--window 는 1 이상의 정수 일수(예: 7 또는 7일): %r\n%s"
                 % (window_opt, TREND_USAGE))
        window_days = int(m.group(1))
    conn = get_conn()
    try:
        trend = compute_trend(conn, metric, window_days=window_days)
    finally:
        conn.close()
    if want_json:
        print(json.dumps(trend, ensure_ascii=False))
        return
    text = render_trend_text(trend)
    if text:
        print(text)


# ── DGN-180 task CLI (event core, kind='task'; dec-001) ───────────────────
# Output contract (task.sh 1:1): id<TAB>title<TAB>due<TAB>done|todo.
# id = event integer id (same id space as the appt-* CLI).

def _task_fetch(conn, eid):
    # DGN-579: trailing place name (11th col) via LEFT JOIN; NULL when unset.
    return conn.execute(
        "SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, e.schedule_kind, "
        "e.display_tz, e.settled_outcome, e.settled_at, e.version, p.name "
        "FROM timeblock e LEFT JOIN place p ON p.id = e.place_id "
        "WHERE e.id=? AND e.kind='task';", (eid,)).fetchone()


def _resolve_task(conn, token):
    """Accept integer id or ulid; must be a task row."""
    row = None
    if token.isdigit():
        row = _task_fetch(conn, int(token))
    if row is None:
        r = conn.execute("SELECT id FROM timeblock WHERE ulid=? AND kind='task';",
                         (token,)).fetchone()
        if r is not None:
            row = _task_fetch(conn, r[0])
    if row is None:
        _err(f"task 없음: {token}")
    return row


def _task_line(row):
    # DGN-579: accept both the legacy 10-col row and the 11-col row whose
    # trailing field is the place name. The first 4 output fields stay
    # byte-identical (id/title/due/state); place is appended as a NEW 5th
    # TAB field only (raw name, or empty) so existing $2/$3 awk parsers never
    # break.
    eid, _ulid, title, sa, _ea, _sk, tz, outcome, _sat, _v = row[:10]
    place = row[10] if len(row) > 10 else None
    due = str(_local_date_of(sa, tz or "Asia/Seoul")) if sa else ""
    state = "done" if outcome == "done" else "todo"
    return f"{eid}\t{title}\t{due}\t{state}\t{place or ''}"


def _task_struct(row):
    """Lossless task read used by cards; the legacy TSV stays untouched."""
    eid, ulid, title, sa, ea, schedule_kind, tz, outcome, _sat, version = row[:10]
    place = row[10] if len(row) > 10 else None
    zone = tz or "Asia/Seoul"

    def local(instant):
        if not instant:
            return None
        parsed = _parse_utcz(instant)
        if parsed is None:
            return None
        return parsed.replace(tzinfo=timezone.utc).astimezone(ZoneInfo(zone)).isoformat()

    start_local, end_local = local(sa), local(ea)
    span = None
    if start_local and schedule_kind == "timed":
        span = start_local[11:16]
        if end_local:
            span += " - " + end_local[11:16]
    return {"id": eid, "ulid": ulid, "title": title,
            "due": str(_local_date_of(sa, zone)) if sa else None,
            "state": "done" if outcome == "done" else "todo",
            "place": place, "schedule_kind": schedule_kind,
            "start_at": sa, "end_at": ea, "display_tz": zone,
            "start_local": start_local, "end_local": end_local,
            "local_span": span, "version": version}


def _travel_block_gate(conn, eid, verb, hint):
    """DGN-274 4.4 (V6): write verbs refuse travel blocks LOUDLY with a
    one-line pointer to the travel verb family (model discretion zero --
    the refusal lives in verb code)."""
    row = conn.execute(
        "SELECT block_class FROM timeblock WHERE id=?;", (eid,)).fetchone()
    if row is not None and row[0] == "travel":
        _err("%s: travel block refused -- %s" % (verb, hint))


_HHMM_RE = re.compile(r"^([01]?\d|2[0-3]):[0-5]\d$")  # G1: HH:MM local time


def cli_task_add(argv, _workout=False, _replacement=False, _inherit_shape=False):
    # task-add <title> [due_date] [note] [--notify <policy>] [--new] [--place <n>]
    #          [--at HH:MM] [--dur <minutes> | --end HH:MM] [--project <id|title>]
    # (dec-001: timeblock_add kind='task'; --notify = DGN-273 per-event override)
    # G1: --at makes a one-off TIMED task -> route_surface (kind='task',
    # schedule_kind='timed') lands it on the CALENDAR, not Google Tasks. No --at
    # -> the all_day/untimed behavior is byte-identical to before.
    # project axis: --project attaches project_block at creation, same
    # transaction as the block insert (timeblock_add's project_id kwarg).
    # Omitting the flag leaves this path byte-identical to before it landed.
    argv, force_new = _pop_flag(argv, '--new')      # DGN-263
    argv, notify_raw = _pop_opt(argv, '--notify')   # DGN-273
    argv, place_raw = _pop_opt(argv, '--place')     # DGN-579 place on tasks
    argv, at_raw = _pop_opt(argv, '--at')           # G1: HH:MM local start
    argv, dur_raw = _pop_opt(argv, '--dur')         # G1: duration minutes
    argv, end_raw = _pop_opt(argv, '--end')         # G1: HH:MM local end
    argv, project_raw = _pop_opt(argv, '--project')  # project axis: id or title
    argv, booked = _pop_flag(argv, '--booked')      # errand gate: a booked time
    argv, attendance_mode = _pop_opt(argv, '--attendance-mode')
    argv, meeting_url = _pop_opt(argv, '--meeting-url')
    attendance = {key: value for key, value in (
        ('attendance_mode', attendance_mode), ('meeting_url', meeting_url)) if value is not None}
    try:
        travel_core.attendance_validate(attendance)
    except ValueError as e:
        _err(str(e))
    online = attendance_mode == 'online' or bool(meeting_url)
    if not argv or not argv[0] or argv[0].lstrip().startswith('--'):
        _err("사용법: kit_life.sh task-add <title> [due_date] [note] "
             "[--notify default|silent|start_only|<lead-min>] [--place <name>] "
             "[--at HH:MM] [--dur <minutes> | --end HH:MM] "
             "[--project <id|title>]")
    title = argv[0]
    due = argv[1] if len(argv) > 1 and argv[1] else None
    note = argv[2] if len(argv) > 2 and argv[2] else None
    if due is not None and not _DATE_RE.match(due):
        _err(f"bad date format (want YYYY-MM-DD): {due}")
    try:
        np, nl = parse_notify_arg(notify_raw)
    except ValueError as e:
        _err(str(e))
    # G1: validate the timed flags (loud one-liners, no traceback).
    timed = at_raw is not None and str(at_raw).strip() != ""
    if not timed and (dur_raw or end_raw):
        _err("--dur/--end require --at (timed task); give --at HH:MM")
    if timed:
        if due is None:
            _err("--at requires a due_date (YYYY-MM-DD) for the timed task")
        if not _HHMM_RE.match(at_raw):
            _err(f"bad time format (want HH:MM): {at_raw}")
        if dur_raw and end_raw:
            _err("give either --dur or --end, not both")
        if end_raw is not None and str(end_raw).strip() != "":
            if not _HHMM_RE.match(end_raw):
                _err(f"bad time format (want HH:MM): {end_raw}")
        if dur_raw is not None and str(dur_raw).strip() != "":
            if not str(dur_raw).isdigit() or int(dur_raw) <= 0:
                _err(f"--dur must be a positive integer (minutes): {dur_raw}")
    if booked:
        if not timed or not due:
            _schedule_refuse('booked_time', title, '--at')
        appt_args = [title, due + ' ' + at_raw]
        end = (due + ' ' + end_raw if end_raw else
               _iso_shift_min(_to_canonical_utc(due + ' ' + at_raw), int(dur_raw)) if dur_raw else '')
        if end or place_raw or note:
            appt_args += [end, place_raw or '', '', note or '']
        appt_args += ['--booked']
        for key, value in attendance.items():
            appt_args += ['--' + key.replace('_', '-'), value]
        if notify_raw:
            appt_args += ['--notify', notify_raw]
        if project_raw:
            appt_args += ['--project', project_raw]
        if force_new:
            appt_args += ['--new']
        return cli_appt_add(appt_args)
    conn = event_conn()
    shape = None
    if timed or (due and _inherit_shape):
        shape = _schedule_shape(conn, title, place_raw, due, _workout)
        if shape is not None:
            if timed and not dur_raw and not end_raw and shape.get('duration_min'):
                dur_raw = str(shape['duration_min'])
            if not place_raw:
                place_raw = shape.get('place_name')
            if notify_raw is None and shape.get('notify_policy'):
                np, nl = shape['notify_policy'], shape.get('notify_lead_min')
    if not force_new:
        # DGN-579 B4: unified find-first probe (T2 exact + T3 LIKE keep the
        # DGN-263 partial-match behavior; T1/T2 add cross-facet coverage).
        # EXISTS + exit 3 contract preserved verbatim. Reconcile-before-write.
        _exists_gate(conn, title, due, _ff_task_line)
    # DGN-579: resolve --place to a place_id (None when absent -> byte-identical
    # legacy behavior). place_upsert is the sole place insert path.
    place_id = None
    if not online and place_raw is not None and str(place_raw).strip():
        try:
            place_id, _ = place_upsert(conn, place_raw)
        except NearMatchError as e:
            _near_exit(e.domain, e.query, e.cands)
    # project axis: resolve --project (id or title) BEFORE any write --
    # an unresolvable project is loud (_resolve_project_id) and must not
    # leave a half-written task behind. None when the flag is absent.
    project_id = _resolve_project_id(conn, project_raw)
    meta = dict(attendance)
    if online and place_raw:
        meta['location'] = place_raw
    _task_add_ulid = None
    _tstatus = None
    try:
        if timed:
            # G1: date + HH:MM (local) -> canonical UTC, same tz convention as
            # appt-add (_to_canonical_utc: naive local == Asia/Seoul -> UTC).
            start_at = _to_canonical_utc(f"{due} {at_raw}")
            if end_raw is not None and str(end_raw).strip() != "":
                end_at = _to_canonical_utc(f"{due} {end_raw}")
            elif dur_raw and str(dur_raw).strip():
                end_at = _iso_shift_min(start_at, int(dur_raw))
            else:
                # A to-do given a time with no stated end stores START ONLY
                # (zero-length, the appointment end_unset shape): the card
                # prints "18:00 title", never an invented hour (owner
                # 2026-10-12 06:55, "does a pickup take an hour").
                end_at = start_at
            try:
                validate_interval(start_at, end_at)  # reversed --end -> loud
            except ValueError as e:
                _err(str(e))
            # G1: reuse the timed create path (timeblock_add kind='task'
            # schedule_kind='timed') -- block_class stays NULL so route_cal_key
            # sends it to the TASK calendar, not the travel/checklist surface.
            eid = timeblock_add(conn, "task", title, "timed", start_at=start_at,
                            end_at=end_at, owning_agent=(shape.get('owning_agent') if shape else None) or _facade_agent(),
                            created_by=_facade_agent(), note=note,
                            notify_policy=np, notify_lead_min=nl,
                            place_id=place_id, project_id=project_id, meta=meta,
                            exclusive_override=0 if _replacement else None)
            if eid is None:
                # slot_exclusive timed task lost the overlap guard: structured
                # conflict listing (same contract as appt-add).
                _print_conflict_and_exit(conn, start_at, end_at)
        elif due:
            sa, ea = all_day_instants(due)
            eid = timeblock_add(conn, "task", title, "all_day", start_at=sa,
                            end_at=ea, owning_agent=(shape.get('owning_agent') if shape else None) or _facade_agent(),
                            created_by=_facade_agent(), note=note,
                            notify_policy=np, notify_lead_min=nl,
                            place_id=place_id, project_id=project_id, meta=meta)
        else:
            eid = timeblock_add(conn, "task", title, "untimed",
                            owning_agent=_facade_agent(),
                            created_by=_facade_agent(), note=note,
                            notify_policy=np, notify_lead_min=nl,
                            place_id=place_id, project_id=project_id, meta=meta)
        _task_add_ulid = _ulid_for_event_id(conn, eid)
        # G1: a timed place-bearing task is a travel anchor -- auto-attach the
        # move/prep exactly like appt-add (existing DGN-623 hook). The hook
        # resolves place via location text, so pass the place NAME. Best-effort:
        # a failure never blocks the write.
        routine_rule = shape.get('travel') if shape else None
        if timed and not online and routine_rule and (place_raw == shape.get('place_name')):
            # Carry the routine's declared travel policy, including an explicit
            # retirement. Do not silently revive travel the owner disabled.
            if routine_rule['status'] == 'active':
                travel_rule_add(conn, 'event', _task_add_ulid, place_id=place_id,
                                **{k: routine_rule[k] for k in (
                                    'before_min', 'after_min', 'prep_min',
                                    'before_src', 'after_src', 'prep_src')})
        elif timed and place_id is not None:
            _tstatus, _torigin, _tdest = _travel_autoattach_appt(
                conn, _task_add_ulid, _place_name(conn, place_id))
        # DGN-579 B2b: choke-point reporter (probe is a no-op for the
        # all_day/untimed shapes; timed variants get the MOVEMENT_OVERLAP
        # notice for free).
        _print_write_result(conn, eid, _task_line(_task_fetch(conn, eid)))
        if _tstatus in _TRAVEL_ATTACH_NEEDS_ELICIT:
            print("TRAVEL_PLACE_NEEDED\t%s\t%s\t%s\t%s\t%s" % (
                _tstatus, eid, place_raw or "", _torigin, _tdest))
        # A dated task is a row on the day card; an undated one has no card
        # and prints nothing here.
        _print_cards(conn, [eid], mutation_state="created")
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _task_add_ulid:
        _outbox_enqueue_best_effort(_task_add_ulid)
    return eid


def cli_errand_classify(argv):
    # errand-classify <title> [--place <name>] [--at HH:MM] [--booked]
    #   READ ONLY. The engine's class for a capture:
    #   ERRAND_CLASS<TAB>errand|appointment|ask|task|other<TAB><verb class|->
    #   <TAB><reason>; ask -> + ERRAND_ASK<TAB><question>.
    argv, verb_class = _pop_opt(argv, '--verb-class')
    argv, place = _pop_opt(argv, '--place')
    argv, at = _pop_opt(argv, '--at')
    argv, booked = _pop_flag(argv, '--booked')
    if not argv or not argv[0]:
        _err("usage: kit_life.sh errand-classify <title> [--place <name>] "
             "[--at HH:MM] [--booked]")
    em = _errand_mod()
    K = sys.modules[__name__]
    has_place = bool(place) and not _location_is_undecided(place)
    try:
        v = em.classify(K, argv[0], has_place, at=at, booked=booked, verb=verb_class)
    except ValueError as exc:
        _err(str(exc))
    print("ERRAND_CLASS\t%s\t%s\t%s" % (v["class"], v["verb_class"] or "-",
                                         v["reason"]))
    if v["class"] == em.CLASS_ASK:
        print("ERRAND_ASK\t" + em.ask_text(K, argv[0], place))


def cli_errand_plan(argv):
    # errand-plan <id> [<id> ...] [--now <UTC ISO>]
    #   READ ONLY. One ERRAND line per errand (errand.plan_line).
    argv, now = _pop_opt(argv, '--now')
    if not argv or not all(str(a).isdigit() for a in argv):
        _err("usage: kit_life.sh errand-plan <id> [<id> ...] [--now <UTC ISO>]")
    conn = event_conn()
    try:
        em = _errand_mod()
        for a in argv:
            p = em.plan(sys.modules[__name__], conn, a, now=now)
            if p is not None:
                print(em.plan_line(p))
    finally:
        conn.close()


def task_find_owning_agent(argv):
    """Resolve the owning-agent READ SCOPE for a task read verb (task-find /
    task-overdue / task-done-between), and return it with the flag stripped
    out of argv.

    CROSS-DOMAIN LEAK: a HEALTH-domain instance's evening retro listed the
    user's tomorrow tasks via `task-find <date>` and surfaced a timeblock
    belonging to a DIFFERENT instance (owning_agent / created_by both pointing
    elsewhere). Where several instances share one kit_life.db, each domain
    instance must read only the rows it owns. The reciprocal knobs on the other
    side (BRIEF_DIET_RECAP / RETRO_HEALTH_SOURCE) already exist for the same
    reason, so the scoping has to be symmetric.

    The defect shape was ABSENCE, not a wrong predicate: cli_task_find simply
    had no owner filter, so every instance sharing this DB read every other
    instance's tasks.

    CODE decides the scope, not the model -- same discipline as
    GOAL_OWNING_AGENT (2026-08-24 goal-consult fix): a CLI flag alone would
    depend on the model remembering to pass it, which is exactly the failure
    mode this codebase keeps repeating. An omitted flag falls back to the
    instance's own TASK_OWNING_AGENT knob in config/agent.conf.

    kit_life.py is SHARED by every instance, so no agent name is hardcoded here
    -- the instance declares itself. Unset knob => None => byte-identical to the
    previous unscoped behavior, so instances that have not opted in (the life agent) are
    unaffected.
    """
    argv, raw = _pop_opt(argv, '--owning-agent')    # same contract as --notify
    sc = scope_self()
    if sc["role"] == "main" and sc["task_scope"]:
        # crew leader: read_scope() beats the flag and the knob (owner
        # 2026-10-13); a solo instance (scope []) keeps flag / knob as before
        return argv, sc["task_scope"]
    owning_agent = (raw or "").strip().lower() or None
    if owning_agent is None:
        owning_agent = (agent_conf.conf_str("TASK_OWNING_AGENT", None)
                        or sc["task_scope"] or None)
    # 2.38.0: a comma list is a scope of several owner tokens (a domain's own
    # slug plus its legacy aliases, as `scope-self` prints task_scope). The
    # queries match a token exactly ("instr(',a,b,', ',x,')"), and a slug
    # never holds a comma, so one token reads exactly as before.
    if owning_agent:
        toks = [t.strip().lower() for t in owning_agent.split(",") if t.strip()]
        owning_agent = ",".join(dict.fromkeys(toks)) or None
    return argv, owning_agent


def _related_shopping(conn, words='', block_id=None):
    # Older standalone fixtures/kits may not ship the optional capture module.
    if not conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='shop_capture'").fetchone():
        return []
    import shop_capture
    return shop_capture.related(conn, words, block_id)


def cli_task_find(argv):
    # task-find [date|all|keyword] [--owning-agent <name>]
    #   -- archived(=abandoned, OQ-C1) excluded.
    argv, owning_agent = task_find_owning_agent(argv)
    arg = argv[0] if argv and argv[0] else "all"
    conn = event_conn()
    try:
        # DGN-579: trailing place name (11th col) via LEFT JOIN.
        base = ("SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, "
                "e.schedule_kind, e.display_tz, e.settled_outcome, "
                "e.settled_at, e.version, p.name FROM timeblock e "
                "LEFT JOIN place p ON p.id = e.place_id "
                "WHERE e.kind='task' "
                "AND e.block_class IS NULL "   # DGN-274 4.4 (V7): blocks are
                                               # time, not to-dos
                "AND (e.settled_outcome IS NULL OR e.settled_outcome <> 'abandoned') "
                # Domain read-scope. `? IS NULL` keeps the unscoped instance
                # byte-identical; a scoped instance never sees another agent's
                # rows -- including rows with a NULL owner, which are not its
                # own either.
                "AND (? IS NULL OR instr(',' || ? || ',', ',' || e.owning_agent || ',') > 0) ")
        scope = (owning_agent, owning_agent)
        if arg == "all":
            rows = conn.execute(
                base + "ORDER BY (start_at IS NULL), start_at DESC;",
                scope).fetchall()
        elif _DATE_RE.match(arg):
            ws, we = all_day_instants(arg)
            rows = conn.execute(
                base + "AND start_at >= ? AND start_at < ? "
                "ORDER BY start_at DESC;", scope + (ws, we)).fetchall()
        else:
            rows = conn.execute(
                base + "AND title LIKE ? "
                "ORDER BY (start_at IS NULL), start_at DESC;",
                scope + (f"%{arg}%",)).fetchall()
        seen = set()
        for row in rows:
            related = _related_shopping(conn, row[2], row[0])
            seen.update(related)
            print(_task_line(row) + ("\t" + " | ".join(related) if related else ""))
        if arg != "all" and not _DATE_RE.match(arg):
            for line in _related_shopping(conn, arg):
                if line not in seen:
                    print(line)
    finally:
        conn.close()


def cli_task_read(argv):
    """task-read [date|all|keyword]: structured, lossless task-find twin."""
    argv, owning_agent = task_find_owning_agent(argv)
    arg = argv[0] if argv and argv[0] else "all"
    conn = event_conn()
    try:
        base = ("SELECT e.id,e.ulid,e.title,e.start_at,e.end_at,e.schedule_kind,"
                "e.display_tz,e.settled_outcome,e.settled_at,e.version,p.name "
                "FROM timeblock e LEFT JOIN place p ON p.id=e.place_id "
                "WHERE e.kind='task' AND e.block_class IS NULL "
                "AND (e.settled_outcome IS NULL OR e.settled_outcome<>'abandoned') "
                "AND (? IS NULL OR instr(','||?||',', ','||e.owning_agent||',')>0) ")
        scope = (owning_agent, owning_agent)
        if arg == "all":
            rows = conn.execute(base + "ORDER BY (start_at IS NULL),start_at DESC", scope).fetchall()
        elif _DATE_RE.match(arg):
            ws, we = all_day_instants(arg)
            rows = conn.execute(base + "AND start_at>=? AND start_at<? ORDER BY start_at", scope + (ws, we)).fetchall()
        else:
            rows = conn.execute(base + "AND title LIKE ? ORDER BY (start_at IS NULL),start_at DESC", scope + ("%" + arg + "%",)).fetchall()
        out = []
        for row in rows:
            task = _task_struct(row)
            action = conn.execute("SELECT value FROM block_attr WHERE block_id=? AND attr_token='action_kind'", (row[0],)).fetchone()
            task["action_kind"] = action[0] if action else "check"
            detail = conn.execute("SELECT note,place_id,notify_policy,notify_lead_min FROM timeblock WHERE id=?", (row[0],)).fetchone()
            task.update(zip(('note', 'place_id', 'notify_policy', 'notify_lead_min'), detail))
            related = _related_shopping(conn, row[2], row[0])
            if related:
                task["related_shopping"] = related
            out.append(task)
        print(json.dumps(out, ensure_ascii=False))
    finally:
        conn.close()


def cli_task_origin_set(argv):
    """Mark a task created by kit/module workflow code, never by the owner."""
    if len(argv) != 2 or not str(argv[0]).isdigit():
        _err("usage: task-origin-set ID kit|module_<name>")
    origin = str(argv[1]).strip()
    if origin != "kit" and not re.match(r"^module_[a-z0-9_]+$", origin):
        _err("task origin must be kit or module_<name>")
    conn = event_conn()
    try:
        row = conn.execute(
            "SELECT created_by FROM timeblock WHERE id=? AND kind='task'",
            (int(argv[0]),)).fetchone()
        if row is None:
            _err("task not found: " + str(argv[0]))
        if row[0] not in (origin, _facade_agent()):
            _err("task origin is already owned by another provenance")
        _tb_update(conn, int(argv[0]), {'created_by': origin})
        conn.commit()
        print("TASK_ORIGIN\t%s\t%s" % (argv[0], origin))
    finally:
        conn.close()


def cli_day_record_summary(argv):
    """Read-only cross-agent facts for a local day, independent of module gates."""
    if len(argv) != 1 or not _DATE_RE.match(argv[0]):
        _err("usage: kit_life.sh day-record-summary YYYY-MM-DD")
    date = argv[0]
    conn = event_conn()
    try:
        meals = []
        for row in conn.execute(
                "SELECT m.id,m.meal,m.name,m.owning_agent,m.created_at,re.event_id,e.title "
                "FROM " + MEALS_V32 + " m LEFT JOIN record r ON r.source_table='block' AND r.source_id=m.id "
                "LEFT JOIN record_event re ON re.record_id=r.id LEFT JOIN event e ON e.id=re.event_id "
                "WHERE m.date=? ORDER BY m.id,re.event_id", (date,)).fetchall():
            item = {"id": row[0], "kind": "meal", "date": date, "slot": meal_slots.label(row[1]),
                    "title": row[2], "owning_agent": row[3], "created_at": row[4],
                    "event_id": row[5], "event_title": row[6], "provenance": "shared_db"}
            if not meals or meals[-1] != item:
                meals.append(item)
        workouts = [{"id": r[0], "kind": "workout", "date": r[1],
                     "minutes": r[2], "note": r[3], "owning_agent": r[4],
                     "provenance": "shared_db"}
                    for r in conn.execute(
                        "SELECT id,date,minutes,note,owning_agent FROM workouts "
                        "WHERE date=? ORDER BY id", (date,)).fetchall()]
        print(json.dumps({"date": date, "meals": meals, "workouts": workouts},
                         ensure_ascii=False))
    finally:
        conn.close()


def _task_title_aliases(conn):
    """Owner-confirmed alias -> full task title, shared by daily instances."""
    raw = _config_stored(conn, "task_title_aliases")
    aliases = json.loads(raw) if raw else {}
    if not isinstance(aliases, dict) or not all(
            isinstance(k, str) and isinstance(v, str)
            for k, v in aliases.items()):
        raise ValueError("invalid task_title_aliases config")
    return aliases


def task_alias(conn, title, alias):
    """Register an explicit title alias; never learn one from a fuzzy guess."""
    title, alias = title.strip(), alias.strip().casefold()
    if not title or not alias:
        raise ValueError("task-alias needs a title and alias")
    conn.execute("BEGIN IMMEDIATE;")
    try:
        titles = {r[0] for r in conn.execute(
            "SELECT title FROM timeblock WHERE kind='task' "
            "AND block_class IS NULL UNION SELECT title FROM routine_def "
            "WHERE kind='task';")}
        exact = [t for t in titles if t.casefold() == title.casefold()]
        if len(exact) != 1:
            raise ValueError("task-alias needs one existing exact title")
        title = exact[0]
        aliases = _task_title_aliases(conn)
        if (any(t.casefold() == alias and t != title for t in titles)
                or (alias in aliases and aliases[alias] != title)):
            raise ValueError("task-alias conflicts with an existing title or alias")
        aliases[alias] = title
        _config_put(conn, "task_title_aliases", json.dumps(aliases, ensure_ascii=False))
        conn.commit()
    except Exception:
        conn.rollback()
        raise


# Shared completion proof. Photo hooks arm today's open ids for the inbound
# bridge request_id; later owner statements use the existing plain-chat path.
# In the photo turn accept an authentic callback, the owner's verbatim caption,
# a grounded image assertion, or a same-turn dated capture receipt. No task,
# app or metric matcher lives here: agents compare meaning and this layer
# validates provenance, ambiguity and dates before the ordinary CAS settle.
# With no bridge turn known the photo gate retains its legacy TTL protection;
# record proof always requires a known current turn, even without a photo hook.
# Callback tokens remain bound to their offered row via inbound-context.json.
PHOTO_GATE_KEY = "task_photo_gate"
PHOTO_GATE_TTL_S = 3 * 3600
_PHOTO_TOKEN_ALPHABET = "ACDEFHJKLMNPQRTUVWXY3479"
_PHOTO_TOKEN_RE = re.compile(r"#([%s]{4})\b" % _PHOTO_TOKEN_ALPHABET)
# Owner completion words (ko: did / done / finished / yes ...; en yes/done)
# and their negations (ko: did not / could not / no / not yet). Escaped:
# code stays ASCII (tools/nonascii-ratchet.py).
SETTLE_PROOF_ATTR = "settle_proof"
RECORD_RECEIPTS_PREFIX = "task_record_receipts:"


def _record_snapshot(conn, table, row_id):
    """Fingerprint stored evidence, including the meal's normalized facts."""
    cur = conn.execute("SELECT * FROM %s WHERE id=?" % table, (row_id,))
    row = cur.fetchone()
    if row is None:
        return None, None
    data = dict(zip([c[0] for c in cur.description], row))
    parts = [data]
    if table in (MEALS_V32, "block"):
        for child in ("block_attr", "measure"):
            parts.append([list(r) for r in conn.execute(
                "SELECT * FROM %s WHERE block_id=? ORDER BY rowid" % child,
                (row_id,))])
    if table == "owned_item":
        for related, column in (("spend_entry", "spend_id"), ("shop_item", "item_id")):
            if data.get(column) is not None:
                parts.append([list(r) for r in conn.execute(
                    "SELECT * FROM %s WHERE id=?" % related, (data[column],))])
    fp = hashlib.sha256(json.dumps(parts, ensure_ascii=False, sort_keys=True,
                                  default=str).encode("utf-8")).hexdigest()
    return data, fp


def _activity_day(value, tz="Asia/Seoul"):
    if not value:
        return None
    try:
        if _DATE_RE.fullmatch(str(value)):
            return str(datetime.date.fromisoformat(value))
        return str(_local_date_of(_to_canonical_utc(value), tz))
    except (TypeError, ValueError):
        return None


def _capture_open_today(conn, verb=None, row_id=None, activity_date=None,
                        table=None):
    """One trailing candidate line, no matching and no nested write hooks.

    A dated activity may issue a bounded current-turn receipt. Undated
    containers, plans, corrections and external DB rows only list candidates.
    Both operations are fail-open AFTER the capture's commit, independently.
    """
    try:
        turn = _inbound_request_id()
        if turn and table and activity_date:
            # Serialize receipt read/modify/write when a panel is captured by
            # concurrent CLI calls in the same turn. The activity is committed.
            conn.execute("BEGIN IMMEDIATE")
            data, fp = _record_snapshot(conn, table, row_id)
            if data is not None and not (table == MEALS_V32 and
                    str(data.get("name", "")).endswith(PLANNED_SUFFIX)):
                # Prefer the activity date stored on the record, never insertion
                # time. Caller date only selects the field for heterogeneous rows.
                day = _activity_day(activity_date)
                key = RECORD_RECEIPTS_PREFIX + (_facade_agent() or "default")
                raw = _config_stored(conn, key)
                try:
                    state = json.loads(raw) if raw else {}
                except (TypeError, ValueError):
                    state = {}
                if not isinstance(state, dict):
                    state = {}
                if state.get("turn") != turn or not isinstance(state.get("receipts"), dict):
                    state = {"turn": turn, "receipts": {}}
                receipts = state.setdefault("receipts", {})
                receipts["%s:%s" % (verb, row_id)] = {
                    "table": table, "id": int(row_id), "date": day,
                    "fingerprint": fp}
                # Bound state even during an unusually large single turn.
                while len(receipts) > 512:
                    del receipts[next(iter(receipts))]
                _config_put(conn, key, json.dumps(state, ensure_ascii=False))
            conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    try:
        rows = task_open_today(conn, owning_agent=None)
        if rows:
            rows = [{k: r[k] for k in ("id", "title", "aliases")} for r in rows]
            print("OPEN_TODAY\t" + json.dumps({"open": rows}, ensure_ascii=False,
                                             separators=(",", ":")))
    except Exception:
        pass  # Never tell the caller to retry a record that already committed.


def _capture_candidates():
    """For correction verbs whose writer owns and closes its connection."""
    try:
        conn = get_conn()
        try:
            _capture_open_today(conn)
        finally:
            conn.close()
    except Exception:
        pass


def _record_proof(conn, evidence, now, tz="Asia/Seoul"):
    """Validate same instance, same turn, activity day and unchanged row."""
    if not evidence or ":" not in evidence:
        return "RECORD_MALFORMED", None
    verb, rid = evidence.split(":", 1)
    if not verb or not rid.isdigit():
        return "RECORD_MALFORMED", None
    key = RECORD_RECEIPTS_PREFIX + (_facade_agent() or "default")
    raw = _config_stored(conn, key)
    try:
        state = json.loads(raw) if raw else {}
    except (TypeError, ValueError):
        state = {}
    if not isinstance(state, dict):
        state = {}
    turn = _inbound_request_id()
    if not turn:
        return "RECORD_NO_TURN", None
    if not raw:
        for other_key, other_raw in conn.execute(
                "SELECT key,value FROM config WHERE key LIKE ?", (RECORD_RECEIPTS_PREFIX + "%",)):
            if other_key == key:
                continue
            try:
                other = json.loads(other_raw)
                if isinstance(other, dict) and other.get("turn") == turn and \
                        isinstance(other.get("receipts"), dict) and evidence in other["receipts"]:
                    return "RECORD_OTHER_INSTANCE", None
            except (TypeError, ValueError):
                pass
        return "RECORD_UNKNOWN", None
    if state.get("turn") != turn:
        return "RECORD_OTHER_TURN", None
    receipts = state.get("receipts")
    rec = receipts.get("%s:%s" % (verb, rid)) if isinstance(receipts, dict) else None
    if not isinstance(rec, dict) or not rec:
        return "RECORD_UNKNOWN", None
    if rec.get("date") != str(_local_date_of(now, tz)):
        return "RECORD_NOT_TODAY", None
    try:
        data, fp = _record_snapshot(conn, rec["table"], rec["id"])
    except (sqlite3.Error, KeyError):
        return "RECORD_CHANGED", None
    if data is None:
        return "RECORD_DELETED", None
    if fp != rec.get("fingerprint"):
        return "RECORD_CHANGED", None
    return None, rec


def _photo_gate(conn, now):
    """The armed photo gate {armed_at, ids, taps{token: id}} or None."""
    raw = _config_stored(conn, PHOTO_GATE_KEY)
    if not raw:
        return None
    try:
        gate = json.loads(raw)
        armed = datetime.datetime.strptime(gate["armed_at"], "%Y-%m-%dT%H:%M:%SZ")
        ids = [int(i) for i in gate.get("ids") or []]
        taps = {str(k): int(v) for k, v in (gate.get("taps") or {}).items()}
    except (ValueError, KeyError, TypeError):
        return None
    age = (datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ") - armed).total_seconds()
    if age < 0 or age > PHOTO_GATE_TTL_S or not ids:
        return None
    out = dict(armed_at=gate["armed_at"], ids=ids, taps=taps)
    if gate.get("activity_ids"):
        out["activity_ids"] = [int(i) for i in gate["activity_ids"]]
    labels = gate.get("labels")
    if isinstance(labels, dict):
        out["labels"] = {str(k): int(v) for k, v in labels.items()}
    if gate.get("photo_turn"):
        out["photo_turn"] = str(gate["photo_turn"])
        if gate.get("caption"):
            out["caption"] = str(gate["caption"])
    return out


def _inbound_context():
    """The bridge's .telegram_bot/inbound-context.json (the owner turn in
    progress), or {} outside an owner turn."""
    path = os.path.join(_kit_root(), ".telegram_bot",
                        "inbound-context.json")
    try:
        with open(path, encoding="utf-8") as fh:
            ctx = json.load(fh)
    except (OSError, ValueError):
        return {}
    return ctx if isinstance(ctx, dict) else {}


def _inbound_request_id():
    """request_id of the owner turn in progress, or None outside one."""
    rid = _inbound_context().get("request_id")
    return str(rid) if rid else None


def _photo_arm(conn, now, ids, caption=None, activity_ids=None):
    """Arm (or extend) the gate for `ids`; the arming turn (and the owner's
    caption of that photo, if any) is recorded."""
    gate = _photo_gate(conn, now) or dict(armed_at=now, ids=[], taps={})
    gate["ids"] = sorted(set(gate["ids"]) | set(ids))
    gate.pop("activity_ids", None)
    if activity_ids:
        gate["activity_ids"] = sorted(set(activity_ids))
    turn = _inbound_request_id()
    if turn:
        if gate.get("photo_turn") != turn:
            gate.pop("caption", None)
        gate["photo_turn"] = turn
        if caption and caption.strip():
            gate["caption"] = caption.strip()[:2000]
    return gate


def _photo_gate_put(conn, gate):
    if gate and gate["ids"]:
        _config_put(conn, PHOTO_GATE_KEY, json.dumps(gate, sort_keys=True))
    else:
        conn.execute("DELETE FROM config WHERE key=?;", (PHOTO_GATE_KEY,))


def _photo_tap_id(gate, tap):
    """Block id the tapped button's token names, or None. The token rides
    the button's callback_data (the bridge's inbound-context of the tap
    turn); a tapped text that still carries "#TOKEN" (older buttons) works
    too."""
    taps = (gate or {}).get("taps", {})
    m = _PHOTO_TOKEN_RE.search(tap or "")
    if m and m.group(1) in taps:
        return taps[m.group(1)]
    ctx = _inbound_context() if tap is not None else {}
    m = _PHOTO_TOKEN_RE.search(str(ctx.get("callback_data") or ""))
    return taps.get(m.group(1)) if m else None


def _photo_tap_row(gate, tap):
    """Block id the tap names: its token, else its clean label (instance
    binding only -- a label is guessable, so it is never proof)."""
    hit = _photo_tap_id(gate, tap)
    if hit is None and tap:
        hit = (gate or {}).get("labels", {}).get(tap.strip())
    return hit


def _photo_gate_holds(gate, turn):
    """True while the gate guards settles: in the photo turn itself, or when
    no owner turn is known (TTL hold). Another owner turn is the owner's own
    report and settles on the plain chat path."""
    photo_turn = (gate or {}).get("photo_turn")
    return not (photo_turn and turn and turn != photo_turn)


def _norm_words(text):
    return " ".join((text or "").split()).casefold()


def _said_in_caption(gate, said, names):
    """--said in the photo turn is the owner's own words only when it is a
    full verbatim photo caption, independent of task-name words."""
    words, caption = _norm_words(said), _norm_words((gate or {}).get("caption"))
    return bool(words and caption and words == caption)


def _evidence_refusal(evidence, names=()):
    """An agent assertion must be substantive, not just a copied title.

    The agent grounds this in the actual image; the database deliberately does
    not maintain an application/task keyword table.
    """
    text = (evidence or "").strip()
    if not text or \
            _norm_words(text) in {_norm_words(n) for n in names if n}:
        return "EVIDENCE_NOT_DONE"
    return None


def _photo_proof(gate, block_id, tap=None, said=None, turn=None, evidence=None,
                 names=()):
    """None when block_id may settle now, else the refusal reason. `turn` =
    the current owner turn (_inbound_request_id): the gate holds only in
    the photo turn (or with no turn known); there --said must be a verbatim
    piece of the photo's own caption naming the task (`names` = its title /
    aliases), else the owner's words come with their next message.
    `evidence` = the agent's grounded image assertion (--photo-evidence): it is
    the photo turn's proof, accepted with or without an armed gate."""
    if (evidence is None and gate and gate.get("activity_ids")
            and _photo_gate_holds(gate, turn)):
        return "TASK_IN_PROGRESS"
    if evidence is not None:
        return _evidence_refusal(evidence, names)
    if not gate or block_id not in gate["ids"] or not _photo_gate_holds(gate, turn):
        return None
    if tap is not None:
        return None if _photo_tap_id(gate, tap) == block_id else "TAP_UNKNOWN"
    if said is not None:
        if turn and gate.get("photo_turn") == turn \
                and not _said_in_caption(gate, said, names):
            return "SAID_IN_PHOTO_TURN"
        return None if str(said).strip() else 'SAID_NOT_DONE'
    return "PHOTO_CONFIRM_REQUIRED"


def _settle_proof_put(conn, block_id, kind, text):
    """Record what settled a photo-gated row (tap / said / photo_evidence,
    verbatim) on the row itself."""
    if text is None:
        return
    conn.execute("BEGIN IMMEDIATE;")
    try:
        conn.execute(
            "INSERT OR REPLACE INTO block_attr(block_id, attr_token, value, "
            "source) VALUES (?,?,?,'user');",
            (int(block_id), SETTLE_PROOF_ATTR,
             json.dumps({kind: text}, ensure_ascii=False)))
        conn.commit()
    except Exception:
        conn.rollback()
        raise


def _photo_gate_release(conn, now, block_id):
    gate = _photo_gate(conn, now)
    if gate and block_id in gate["ids"]:
        gate["ids"] = [i for i in gate["ids"] if i != block_id]
        gate["taps"] = {k: v for k, v in gate["taps"].items() if v != block_id}
        if "labels" in gate:
            gate["labels"] = {k: v for k, v in gate["labels"].items()
                              if v != block_id}
        _photo_gate_put(conn, gate)
        conn.commit()


PHOTO_CONFIRM_NEXT = (
    "photo-originated completion: do NOT say it is recorded. If the image "
    "evidences TODAY's activity fulfilling this task, settle with "
    "--photo-evidence \"<observed evidence, visible text verbatim>\"; else ask the owner "
    "with the tap (task-open-today --photo --offer <id>) and settle after "
    "the tap with --tap \"<tapped text>\", or with --said \"<the owner's own "
    "words>\" when they typed it in a later message (never in the photo "
    "turn itself, never invented).")


PHOTO_REPLY_NEXT = (
    "your whole message is `reply` verbatim: exactly one completion line. "
    "No capture card, saved-field count, analysis, question, closer or emoji. "
    "Do not start onboarding, setup or coaching after this capture. This "
    "completion reply takes precedence over skill and card-followup replies.")


PHOTO_ACTIVITY_GRACE_S = 15 * 60
PHOTO_ACTIVITY_NEXT = (
    "This photo belongs to the activity in progress. Inspect it and answer "
    "the activity question, including an implicit question without a caption. "
    "Do not complete or announce a task, offer done buttons, or create a "
    "duplicate activity/meal log. Only a clearly visible finished end-state "
    "of this task permits --photo-evidence with --photo-end-state. Describe "
    "that end-state in the evidence; ingredients or an intermediate step "
    "are not an end-state. Keep tool work silent, then answer the photo.")
PHOTO_ALREADY_NEXT = (
    "No completion message: reply is empty. Inspect the photo and answer it "
    "as a question about this activity, including an implicit question. "
    "Do not say already done, announce completion, or create a duplicate activity.")


def _photo_activity_route(conn, now, owning_agent=None):
    """One photo priority gate: open workouts, then started task windows.

    Plain tasks have no separate running session: scheduled start is the
    start boundary, including starts delivered by a reminder. Retimed/snoozed
    rows use their current window. Grace is inclusive through end + 15 min.
    Read all dates so a task spanning midnight keeps its activity priority.
    """
    sessions = _workout_history.open_sessions(sys.modules[__name__], conn, _pin_agent())
    if sessions:
        return dict(status="SESSION_OPEN", reason="WORKOUT_SESSION_OPEN",
                    route="workout-session", sessions=sessions,
                    next=_workout_history.SESSION_NEXT)
    rows = conn.execute(
        "SELECT id,ulid,title,start_at,end_at,display_tz FROM timeblock "
        "WHERE kind='task' AND block_class IS NULL AND settled_at IS NULL "
        "AND schedule_kind='timed' AND start_at<=? "
        "AND (? IS NULL OR instr(',' || ? || ',', ',' || owning_agent || ',') > 0)",
        (now, owning_agent, owning_agent)).fetchall()
    active = []
    instant = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
    for bid, ulid, title, start, end, tz in rows:
        deadline = datetime.datetime.strptime(end, "%Y-%m-%dT%H:%M:%SZ") if end else None
        if deadline is None or instant <= deadline + datetime.timedelta(seconds=PHOTO_ACTIVITY_GRACE_S):
            active.append(dict(id=bid, ulid=ulid, title=title,
                               start_local=_render_local_col(start, "timed", tz or "Asia/Seoul")))
    if active:
        return dict(status="ACTIVITY_IN_PROGRESS", reason="TASK_IN_PROGRESS",
                    route="task-activity", activities=active, next=PHOTO_ACTIVITY_NEXT)
    return None


def _timeblock_card_mod():
    if SCRIPT_DIR not in sys.path:
        sys.path.insert(0, SCRIPT_DIR)
    import timeblock_card
    return timeblock_card


def _said_done_time(said, when, tz, now):
    """Resolve explicit --when now|HH:MM. said is inert audit evidence."""
    if when:
        w = str(when).strip().lower()
        if w == "now":
            return "now", now
        m = re.fullmatch(r"(\d{1,2}):(\d{2})", w)
        if not m:
            raise ValueError("--when needs now or HH:MM")
        h, mi, pref = int(m.group(1)), int(m.group(2)), None
    else:
        # Time is supplied by the agent's --when value, not a prose verb.
        return None, None
    zone = ZoneInfo(tz or "Asia/Seoul")
    local = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ").replace(
        tzinfo=datetime.timezone.utc).astimezone(zone)
    cands = [h] if (pref in ("\uc624\uc804", "\uc544\uce68", "\uc0c8\ubcbd") or h >= 12) else (
        [h + 12] if pref in ("\uc624\ud6c4", "\uc800\ub141", "\ubc24", "\uc810\uc2ec") and h < 12 else [h, h + 12])
    best = None
    for hh in cands:
        if hh > 23 or mi > 59:
            continue
        at = local.replace(hour=hh, minute=mi, second=0, microsecond=0)
        if at <= local and (best is None or at > best):
            best = at
    if best is None:
        return None, None
    return "at", best.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _late_done_plan(conn, row_start, row_end, now, said=None, when=None, tz=None):
    """(settled_at_ts, offer) for one done settle -- the single late-done
    decision every done verb shares (owner 2026-10-18 19:07, kit dev.41).
    Done now always stands (streak continues). A done past start + duration
    + 30 min records at the SCHEDULED time until the owner picks, and offers
    the existing [around HH:MM] [just now HH:MM] row -- unless the owner
    already said when in the same message (then it is recorded directly)."""
    kind, ts = _said_done_time(said, when, tz, now)
    if kind:
        return ts, False
    if _start_card_mod().is_late(row_start, row_end, now):
        return row_start, True
    return None, False


def _done_card(conn, verb, block_id):
    """The state-line card A of a task this verb just settled done, or ''."""
    tc = _timeblock_card_mod()
    return tc.render(sys.modules[__name__], conn,
                     tc.from_settle(conn, verb, block_id))


def _mutation_card(conn, verb, block_id, state):
    tc = _timeblock_card_mod()
    return tc.render(sys.modules[__name__], conn,
                     tc.TimeblockMutationResult(verb, int(block_id), state))


def _photo_reply(result, title):
    """Completion copy only for a newly settled task; repeats answer the activity."""
    if result["status"] == "ALREADY_DONE":
        result.update(reply="", next=PHOTO_ALREADY_NEXT)
    elif result["status"] == "DONE":
        name = (result["candidates"] or [{}])[0].get("title") or title
        result["reply"] = _i18n("task.photo.done_line", "Marked {title} done.").replace("{title}", name)
        result["next"] = PHOTO_REPLY_NEXT
    return result


def task_done_today(conn, title, now=None, instance=None, owning_agent=None,
                    tap=None, said=None, evidence=None, record_evidence=None,
                    photo_end_state=False, or_overdue=False, when=None):
    """Resolve today's task, then settle via the ordinary CAS mutation.

    Exact title or explicitly registered alias only. Two open instances
    always ASK, nearest start first; proximity never authorizes a guess.
    An explicit instance is accepted only within today's matching rows.
    A row armed by the photo gate settles only with proof (tap / said /
    a grounded image assertion), else CONFIRM and nothing is written.
    or_overdue: when no instance is open today, settle the most recent
    overdue open instance (same exact/alias match, same ASK on two).
    """
    now = canonical(now or now_utc())
    query = title.strip().casefold()
    if not query:
        raise ValueError("task-done-today needs a title")
    activity = _activity_session_state(conn)
    if activity and activity['phase'] not in ('closed', 'cancelled'):
        return dict(status='SESSION_OPEN', reason='ACTIVITY_SESSION_OPEN', candidates=[],
                    next='Run cooking input with the owner words or image context first. Keep tasks open.')
    gate = _photo_gate(conn, now)
    activity_photo = (gate and gate.get("activity_ids") and
                      _photo_gate_holds(gate, _inbound_request_id()))
    activity = (_photo_activity_route(conn, now, owning_agent)
                if evidence is not None or activity_photo else None)
    if activity and activity["route"] == "workout-session":
        return dict(activity, candidates=[])
    sessions = _workout_history.photo_sessions(sys.modules[__name__], conn)
    if sessions:
        return dict(status="SESSION_OPEN", reason="WORKOUT_SESSION_OPEN",
                    candidates=[], sessions=sessions, next=_workout_history.SESSION_NEXT)
    tap_row = (_photo_tap_row(gate, tap)
               if instance is None and tap is not None else None)
    alias = _task_title_aliases(conn).get(query)
    titles = {query}
    if alias:
        titles.add(alias.casefold())
    rows = conn.execute(
        "SELECT id, ulid, title, start_at, display_tz, rec_date, version, "
        "settled_at, settled_outcome FROM timeblock "
        "WHERE kind='task' AND block_class IS NULL "
        "AND (? IS NULL OR instr(',' || ? || ',', ',' || owning_agent || ',') > 0);",
        (owning_agent, owning_agent)).fetchall()
    matches = []
    overdue = []
    now_dt = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
    for eid, ulid, name, start, tz, rec_date, version, settled, outcome in rows:
        if name.casefold() not in titles or not start:
            continue
        tz = tz or "Asia/Seoul"
        today = str(_local_date_of(now, tz))
        day = rec_date or str(_local_date_of(start, tz))
        if instance and str(instance) not in (str(eid), ulid):
            continue
        if day != today:
            if or_overdue and day < today and settled is None:
                overdue.append(dict(id=eid, ulid=ulid, title=name, start_at=start,
                                    version=version, settled_at=settled,
                                    outcome=outcome, display_tz=tz, day=day))
            continue
        matches.append(dict(id=eid, ulid=ulid, title=name, start_at=start,
                            version=version, settled_at=settled, outcome=outcome, display_tz=tz))
    matches.sort(key=lambda r: (abs((datetime.datetime.strptime(
        r["start_at"], "%Y-%m-%dT%H:%M:%SZ") - now_dt).total_seconds()), r["id"]))
    opened = [r for r in matches if r["settled_at"] is None]
    if not opened and overdue:
        latest = max(r["day"] for r in overdue)
        opened = sorted((r for r in overdue if r["day"] == latest),
                        key=lambda r: (r["start_at"], r["id"]))
    if any(r["id"] == tap_row for r in opened):
        # the tapped button names its instance (a label shared by two
        # offers names whichever row matches this title)
        opened = [r for r in opened if r["id"] == tap_row]
    if activity and (not photo_end_state or len(opened) != 1 or
                     opened[0]["id"] not in {r["id"] for r in activity["activities"]}):
        # Activity priority also blocks an unrelated title from consuming
        # an in-progress photo as generic completion evidence.
        return dict(activity, candidates=opened, reply="")
    if len(opened) > 1:
        return {"status": "ASK", "candidates": opened}
    if not opened:
        done = [r for r in matches if r["outcome"] == "done"]
        return {"status": "ALREADY_DONE" if done else "NOT_FOUND", "candidates": done}
    row = opened[0]
    sessions = _workout_history.task_sessions(sys.modules[__name__], conn, row["id"])
    if sessions:
        return dict(status="SESSION_OPEN", reason="WORKOUT_SESSION_OPEN",
                    candidates=[row], sessions=sessions,
                    next=_workout_history.SESSION_NEXT)
    if record_evidence is not None:
        refusal, _receipt = _record_proof(conn, record_evidence, now, row["display_tz"])
    else:
        refusal = _photo_proof(gate, row["id"], tap, said, _inbound_request_id(),
                               evidence, names=[row["title"]] + sorted(titles))
    if refusal:
        if activity:
            return dict(activity, reason=refusal, candidates=[row], reply="")
        return {"status": "CONFIRM", "reason": refusal, "candidates": [row],
                "next": PHOTO_CONFIRM_NEXT}
    proof_sources = [(_receipt["table"], _receipt["id"])] if record_evidence is not None else []
    blk = conn.execute("SELECT end_at, schedule_kind FROM timeblock WHERE id=?;",
                       (row["id"],)).fetchone()
    settle_at, late_offer = _late_done_plan(
        conn, row["start_at"] if blk and blk[1] == "timed" else None,
        blk[0] if blk else None, now, said=said, when=when, tz=row["display_tz"])
    result = force_settle(conn, row["id"], row["version"], "owner-chat",
                          settled_at_ts=settle_at or now, experience_evidence=proof_sources,
                          experience_verbatim=said, move_late=not late_offer)
    if result == MutationResult.SESSION_OPEN:
        return dict(status="SESSION_OPEN", reason="WORKOUT_SESSION_OPEN",
                    candidates=[row], next=_workout_history.SESSION_NEXT)
    if result == MutationResult.APPLIED:
        if record_evidence is not None:
            _settle_proof_put(conn, row["id"], "record_evidence", record_evidence)
        elif evidence is not None:
            _settle_proof_put(conn, row["id"], "photo_evidence", evidence)
        elif gate and row["id"] in gate["ids"] and (tap is not None
                                                    or said is not None):
            _settle_proof_put(conn, row["id"], "tap" if tap is not None
                              else "said", tap if tap is not None else said)
        _photo_gate_release(conn, now, row["id"])
        row.update(settled_at=settle_at or now, outcome="done", version=row["version"] + 1)
        row["start_at"] = conn.execute("SELECT start_at FROM timeblock WHERE id=?",
                                      (row["id"],)).fetchone()[0]
        out = {"status": "DONE", "candidates": [row]}
        if late_offer:
            out["late"] = True
        return out
    return {"status": "RETRY", "candidates": []}


def _emit_late_card(card, options):
    """The done card; with a late-done choice, the card block then the
    [[OPTIONS]] marker on its own line LAST (card first, row after)."""
    if not options:
        _timeblock_card_mod().emit(sys.modules[__name__], card)
        return
    sc = _start_card_mod()
    _emit_card_block([card], relay=sc.LATE_OPTIONS_RELAY)
    print(options)


def cli_task_alias(argv):
    if len(argv) != 2:
        _err("usage: kit_life.sh task-alias <exact-title> <alias>")
    conn = event_conn()
    try:
        task_alias(conn, argv[0], argv[1])
        print("OK")
    except ValueError as exc:
        _err(str(exc))
    finally:
        conn.close()


def cli_task_done_today(argv):
    argv, owning_agent = task_find_owning_agent(argv)
    argv, instance = _pop_opt(argv, '--id')
    argv, tap = _pop_opt(argv, '--tap')
    argv, said = _pop_opt(argv, '--said')
    argv, evidence = _pop_opt(argv, '--photo-evidence')
    argv, record_evidence = _pop_opt(argv, '--record-evidence')
    argv, photo_end_state = _pop_flag(argv, '--photo-end-state')
    argv, or_overdue = _pop_flag(argv, '--or-overdue')
    argv, when = _pop_opt(argv, '--when')
    if (photo_end_state and evidence is None) or len(argv) != 1 or sum(x is not None for x in (tap, said, evidence, record_evidence)) > 1:
        _err("usage: kit_life.sh task-done-today <title-or-alias> [--id ID] "
             "[--tap TAPPED-TEXT | --said OWNER-WORDS | "
             "--photo-evidence OBSERVED-EVIDENCE [--photo-end-state] | --record-evidence VERB:ID] "
             "[--or-overdue] [--when now|HH:MM]")
    conn = event_conn()
    card = ""
    options = ""
    try:
        result = task_done_today(conn, argv[0], instance=instance,
                                 owning_agent=owning_agent, tap=tap, said=said,
                                 evidence=evidence, record_evidence=record_evidence,
                                 photo_end_state=photo_end_state,
                                 or_overdue=or_overdue, when=when)
        # Every successful completion shares the same state-line card A,
        # including photo and same-turn record evidence.
        if result["status"] == "DONE":
            card = _done_card(conn, "task-done-today",
                              result["candidates"][0]["id"])
            if card and result.get("late"):
                options = _start_card_mod().offer_late(
                    sys.modules[__name__], conn, result["candidates"][0]["id"],
                    canonical(now_utc()))
    except ValueError as exc:
        _err(str(exc))
    finally:
        conn.close()
    _photo_reply(result, argv[0])
    if card:
        result.update(reply="", next=_timeblock_card_mod().NEXT)
    if options:
        result["next"] = ("the mutation card is the CARD block below, then its "
                          "late-done choice marker (card, then marker): relay it exactly once, "
                          "with no success line of your own")
    if result["status"] == "DONE":
        _outbox_enqueue_best_effort(result["candidates"][0]["ulid"])
    print(json.dumps(result, ensure_ascii=False))
    _emit_late_card(card, options)


def task_open_today(conn, now=None, owning_agent=None, done=False):
    """Today's still-open task/routine instances with their registered
    aliases, nearest start first. The photo -> done lane (owner 2026-10-09
    21:28) matches what a photo shows against exactly these titles/aliases,
    then settles through task-done-today; same day rule as that verb.
    done=True: today's DONE instances instead (a photo of an activity
    already settled today answers ALREADY_DONE, owner 2026-10-11)."""
    now = canonical(now or now_utc())
    aliases = _task_title_aliases(conn)
    rows = conn.execute(
        "SELECT id, ulid, title, start_at, display_tz, rec_date, is_routine "
        "FROM timeblock WHERE kind='task' AND block_class IS NULL "
        + ("AND settled_outcome='done' " if done else "AND settled_at IS NULL ") +
        "AND start_at IS NOT NULL "
        "AND (? IS NULL OR instr(',' || ? || ',', ',' || owning_agent || ',') > 0);",
        (owning_agent, owning_agent)).fetchall()
    now_dt = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
    out = []
    for eid, ulid, title, start, tz, rec_date, routine in rows:
        tz = tz or "Asia/Seoul"
        if (rec_date or str(_local_date_of(start, tz))) != str(_local_date_of(now, tz)):
            continue
        out.append(dict(
            id=eid, ulid=ulid, title=title,
            start_local=_render_local_col(start, "timed", tz),
            aliases=sorted(a for a, t in aliases.items()
                           if t.casefold() == (title or "").casefold()),
            routine=bool(routine), _start=start))
    out.sort(key=lambda r: (abs((datetime.datetime.strptime(
        r["_start"], "%Y-%m-%dT%H:%M:%SZ") - now_dt).total_seconds()), r["id"]))
    for r in out:
        del r["_start"]
    return out


def _photo_push_sh():
    """routines/push.sh of this instance ($WARG_PUSH first), or None."""
    for path in (os.environ.get("WARG_PUSH"),
                 os.path.join(_kit_root(), "routines", "push.sh")):
        if path and os.path.isfile(path) and os.access(path, os.X_OK):
            return path
    return None


def _photo_offer_buttons(rows, tokens):
    """One button per offered row. The owner sees a clean label; its token
    rides callback_data only ("opt:<label> #TOKEN", <= 64 bytes). The
    bridge's opt: route replays the button TEXT as the owner's message and
    publishes the tapped callback_data in inbound-context.json, where
    _photo_tap_id reads the token."""
    out = []
    for r in rows:
        tag = "#" + tokens[r["id"]]
        if len(rows) == 1:
            label = _i18n("task.photo.done_button", "Done")
        else:
            hm = r["start_local"][11:16] if "T" in r["start_local"] else ""
            label = " ".join(x for x in (r["title"] or "", hm) if x)
        name = label
        data = "opt:%s %s" % (name, tag)
        while len(data.encode("utf-8")) > 64 and name:
            name = name[:-1]
            data = "opt:%s~ %s" % (name, tag)
        out.append([{"text": label, "callback_data": data}])
    return out


def task_photo_offer(conn, rows, now=None, push=None, caption=None):
    """Arm a token per offered row and post the confirm keyboard through the
    kit button path (push.sh --strict --buttons-json). Returns
    (buttons, posted). Unposted (no push.sh / it failed): the tokens stay
    unknown to the agent, so only --said can settle."""
    now = canonical(now or now_utc())
    activity = _photo_activity_route(conn, now, task_find_owning_agent([])[1])
    if activity:
        raise ValueError(activity["reason"] + ": " + activity["next"])
    gate = _photo_arm(conn, now, [r["id"] for r in rows], caption)
    tokens = {}
    for r in rows:
        tok = "".join(secrets.choice(_PHOTO_TOKEN_ALPHABET) for _ in range(4))
        tokens[r["id"]] = tok
        gate["taps"][tok] = r["id"]
    buttons = _photo_offer_buttons(rows, tokens)
    labels = gate.setdefault("labels", {})
    for r, row in zip(rows, buttons):
        labels[row[0]["text"]] = r["id"]
    conn.execute("BEGIN IMMEDIATE;")
    _photo_gate_put(conn, gate)
    conn.commit()
    if len(rows) == 1:
        text = _i18n("task.photo.ask_one", "Did you do {title}?").replace(
            "{title}", rows[0]["title"] or "")
    else:
        text = _i18n("task.photo.ask_which", "Which one did you do?")
    import subprocess
    push = push if push is not None else _photo_push_sh()
    posted = False
    if push:
        try:
            p = subprocess.run([push, "--strict", "--text", text, "--buttons-json",
                                json.dumps(buttons, ensure_ascii=False)],
                               capture_output=True, text=True, timeout=30)
            posted = p.returncode == 0
        except (OSError, subprocess.SubprocessError):
            posted = False
    return dict(text=text, buttons=[b["text"] for row in buttons
                                    for b in row]), posted


CAPTURE_SILENT_NEXT = (
    "write no text until your final reply: every text block, even one line "
    "before a tool call, is sent to the owner as its own message. Adding "
    "today's done block is part of recording, not a decision to announce. "
    "Finish the settle in tool calls, then reply only the completion line.")


def cli_task_open_today(argv):
    # task-open-today [--owning-agent X] [--photo [--offer ID[,ID]]
    #                  [--caption OWNER-CAPTION]]
    #   -> JSON {"open": [...], "done": [...]} (+ "gate" / "offer" on photo path)
    # --caption: the owner's own typed caption of the photo (the photo hook
    # passes it); in the photo turn --said may quote it.
    argv, owning_agent = task_find_owning_agent(argv)
    argv, photo = _pop_flag(argv, '--photo')
    argv, offer = _pop_opt(argv, '--offer')
    argv, caption = _pop_opt(argv, '--caption')
    if argv or ((offer is not None or caption is not None) and not photo):
        _err("usage: kit_life.sh task-open-today [--owning-agent NAME] "
             "[--photo [--offer ID[,ID]] [--caption OWNER-CAPTION]]")
    conn = event_conn()
    out = {}
    try:
        activity = _activity_session_state(conn) if photo else None
        if activity and activity['phase'] not in ('closed', 'cancelled'):
            print(json.dumps(dict(open=[], done=[], status='SESSION_OPEN', route='cooking-session',
                next='Run cooking input with the owner words or image context first. Do not settle tasks.'), ensure_ascii=False))
            return
        now = canonical(now_utc())
        activity = _photo_activity_route(conn, now, owning_agent) if photo else None
        if activity and activity["route"] == "workout-session":
            _workout_history.route_photo(sys.modules[__name__], conn, _pin_agent())
            print(json.dumps(dict(activity, open=[], done=[]), ensure_ascii=False))
            return
        if activity:
            # Use the existing photo gate, retaining the same turn/caption
            # binding. No completion offer is posted during an activity.
            ids = [r["id"] for r in activity["activities"]]
            gate = _photo_arm(conn, now, ids, caption, activity_ids=ids)
            conn.execute("BEGIN IMMEDIATE;")
            _photo_gate_put(conn, gate)
            conn.commit()
            print(json.dumps(dict(activity, open=[], done=[]), ensure_ascii=False))
            return
        try:
            rows = task_open_today(conn, owning_agent=owning_agent)
            done = task_open_today(conn, owning_agent=owning_agent,
                                   done=True)
        except ValueError as exc:
            _err(str(exc))
        related = list(dict.fromkeys(line for r in rows
            for line in _related_shopping(conn, r["title"], r["id"])))[:5]
        if related:
            out["related_shopping"] = related
        now = canonical(now_utc())
        if done:
            out["done"] = [dict(id=r["id"], title=r["title"],
                                aliases=r["aliases"]) for r in done]
        if photo and offer is None and rows:
            gate = _photo_arm(conn, now, [r["id"] for r in rows], caption)
            conn.execute("BEGIN IMMEDIATE;")
            _photo_gate_put(conn, gate)
            conn.commit()
            out["gate"] = ("armed: settle with grounded photo/record evidence or "
                           "owner confirmation; multiple fulfilled rows require "
                           "one question via --offer <id>[,<id>]")
        elif photo and offer is not None:
            want = {w.strip() for w in offer.split(",") if w.strip()}
            rows = [r for r in rows if str(r["id"]) in want or r["ulid"] in want]
            if not rows or len(rows) != len(want):
                _err("task-open-today --offer: every id must be one of "
                     "today's open rows")
            sent, posted = task_photo_offer(conn, rows, now=now, caption=caption)
            out["offer"] = dict(sent, posted=posted, next=(
                "the question and its button are sent: do not repeat them, no "
                "[[OPTIONS]]; settle after the tap with task-done-today "
                "\"<title>\" --tap \"<tapped text>\"" if posted else
                "not posted: ask with one [[OPTIONS]] button yourself; settle after "
                "the owner's answer with --said \"<their words>\""))
        if offer is None:
            # Read at the capture/settle boundary, where between-tool
            # narration slipped in (the life agent R5, the health agent R3): the instruction rides
            # the data, with or without the photo hook.
            out["next"] = CAPTURE_SILENT_NEXT
    finally:
        conn.close()
    print(json.dumps(dict(open=rows, **out), ensure_ascii=False))


def cli_task_done(argv):
    argv, tap = _pop_opt(argv, '--tap')
    argv, said = _pop_opt(argv, '--said')
    argv, when = _pop_opt(argv, '--when')
    if not argv or not argv[0]:
        _err("\uc0ac\uc6a9\ubc95: kit_life.sh task-done <id> [--when now|HH:MM]")
    options = ""
    conn = event_conn()
    _task_done_ulid = None
    try:
        row = _resolve_task(conn, argv[0])
        _travel_block_gate(conn, row[0], "task-done",
                           "blocks have no done settle concept (completion tracking does not apply)")
        if (_workout_history.task_sessions(sys.modules[__name__], conn, row[0])
                or _workout_history.photo_sessions(sys.modules[__name__], conn)):
            _err("WORKOUT_SESSION_OPEN: " + _workout_history.SESSION_NEXT)
        refusal = _photo_proof(
            _photo_gate(conn, canonical(now_utc())), row[0], tap, said,
            _inbound_request_id(), names=[row[2]] + [
                a for a, t in _task_title_aliases(conn).items()
                if t.casefold() == (row[2] or "").casefold()])
        if refusal:
            _err("CONFIRM (%s): %s" % (refusal, PHOTO_ACTIVITY_NEXT
                                     if refusal == "TASK_IN_PROGRESS" else PHOTO_CONFIRM_NEXT))
        _now = canonical(now_utc())
        try:
            settle_at, late_offer = _late_done_plan(
                conn, row[3] if row[5] == "timed" else None, row[4], _now,
                said=said, when=when, tz=row[6])
        except ValueError as exc:
            _err(str(exc))
        res = force_settle(conn, row[0], row[9], _facade_agent(),
                           settled_at_ts=settle_at,
                           experience_verbatim=said, move_late=not late_offer)
        if res == MutationResult.SESSION_OPEN:
            _err("WORKOUT_SESSION_OPEN: " + _workout_history.SESSION_NEXT)
        if res != MutationResult.APPLIED:
            _err(f"task-done 실패 ({res}): 이미 완료/취소되었거나 동시 변경")
        _photo_gate_release(conn, canonical(now_utc()), row[0])
        _task_done_ulid = row[1]
        print(_task_line(_task_fetch(conn, row[0])))
        _done = _done_card(conn, "task-done", row[0])
        if _done and late_offer:
            options = _start_card_mod().offer_late(sys.modules[__name__], conn, row[0], _now)
        _emit_late_card(_done, options)
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _task_done_ulid:
        _outbox_enqueue_best_effort(_task_done_ulid)


