def _defer_shape(cur_sk, cur_start, cur_end, tz_name, new_date,
                 at_hhmm=None, force_all_day=False, end_hhmm=None,
                 no_end=False):
    """_defer_shape_base plus the explicit end: end_hhmm sets the local end
    on the new date, no_end clears it back to start only (zero-length).
    Either needs a timed result; delete + recreate is never the workaround."""
    if end_hhmm and no_end:
        raise ValueError("give either --end or --no-end, not both")
    sk, sa, ea = _defer_shape_base(cur_sk, cur_start, cur_end, tz_name,
                                   new_date, at_hhmm=at_hhmm,
                                   force_all_day=force_all_day)
    if not (end_hhmm or no_end):
        return sk, sa, ea
    if sk != "timed":
        raise ValueError("--end / --no-end need a timed task "
                         "(give --at HH:MM)")
    if no_end:
        return sk, sa, sa
    if not _HHMM_RE.match(end_hhmm):
        raise ValueError("bad time format (want HH:MM): %s" % end_hhmm)
    tz = tz_name or "Asia/Seoul"
    local_start = (_iso_dt(sa).replace(tzinfo=timezone.utc)
                   .astimezone(ZoneInfo(tz)).strftime("%Y-%m-%d"))
    return sk, sa, _to_canonical_utc("%s %s" % (local_start, end_hhmm))


def _defer_shape_base(cur_sk, cur_start, cur_end, tz_name, new_date,
                      at_hhmm=None, force_all_day=False):
    """Derive the (schedule_kind, start_at, end_at) a DATE move should land on.

    Defer-preserves-shape rule (2026-08-25): moving a row to another date
    changes the DATE and NOTHING else. A kind change must be asked for, never
    fall out of the move.

      timed   -> stays timed. Same LOCAL clock time on the new date, duration
                 preserved as an absolute delta. An open-ended row (end NULL)
                 keeps end NULL (bypass_schedule_apply's open_ended rule).
      all_day -> stays all_day. Span length in whole days preserved, so a
                 multi-day block stays multi-day.
      untimed -> carries no date at all, so handing it one IS a shape change.
                 Becomes all_day (legacy behaviour) unless at_hhmm is given.
      at_hhmm      -> EXPLICIT promote/keep timed at that local time.
      force_all_day -> EXPLICIT demote to an all-day row.

    tz_name is the row's display_tz (falls back to Asia/Seoul). Returns
    (schedule_kind, start_at, end_at); raises ValueError on a bad clock time.
    """
    tz = tz_name or "Asia/Seoul"
    if at_hhmm and force_all_day:
        raise ValueError("give either --at or --all-day, not both")
    if force_all_day:
        sa, ea = all_day_instants(new_date, tz_name=tz)
        return "all_day", sa, ea
    if at_hhmm:
        if not _HHMM_RE.match(at_hhmm):
            raise ValueError("bad time format (want HH:MM): %s" % at_hhmm)
        start_at = _to_canonical_utc("%s %s" % (new_date, at_hhmm))
        # keep the row's own duration when it had one; else the add-path default
        if cur_sk == "timed" and cur_start and cur_end:
            delta = (_iso_dt(cur_end) - _iso_dt(cur_start))
            end_at = _iso_fmt(_iso_dt(start_at) + delta)
        elif cur_sk == "timed" and cur_start and cur_end is None:
            end_at = None                       # open-ended stays open-ended
        else:
            end_at = start_at        # no invented length (zero-length = start only)
        return "timed", start_at, end_at
    if cur_sk == "timed" and cur_start:
        # SAME local clock time, new date. zoneinfo does the offset, so this
        # is DST-correct for any display_tz, not just the DST-free default.
        hhmm = (_iso_dt(cur_start).replace(tzinfo=timezone.utc)
                .astimezone(ZoneInfo(tz)).strftime("%H:%M"))
        start_at = _to_canonical_utc("%s %s" % (new_date, hhmm))
        if cur_end is None:
            end_at = None                       # open-ended stays open-ended
        else:
            end_at = _iso_fmt(_iso_dt(start_at)
                              + (_iso_dt(cur_end) - _iso_dt(cur_start)))
        return "timed", start_at, end_at
    if cur_sk == "all_day" and cur_start and cur_end:
        # duration-preserving day shift (same contract as _upd_overlay_time)
        sd = _local_date_of(cur_start, tz)
        ed_incl = _local_date_of(cur_end, tz) - timedelta(days=1)
        span_days = max((ed_incl - sd).days, 0)
        new_sd = datetime.date.fromisoformat(new_date)
        new_ed = new_sd + timedelta(days=span_days)
        sa, ea = all_day_instants(new_sd.isoformat(), new_ed.isoformat(),
                                  tz_name=tz)
        return "all_day", sa, ea
    # untimed (or a shape-degraded row): the only sensible landing is all_day.
    sa, ea = all_day_instants(new_date, tz_name=tz)
    return "all_day", sa, ea


def _defer_by_shape(cur_sk, cur_start, cur_end, offset):
    """Move from the item's scheduled start before this operation, never now.

    Signed whole minutes/hours/days; preserve duration and a NULL end exactly.
    Untimed/all-day items need an explicit date/time rather than an invented
    clock anchor. UTC arithmetic also preserves elapsed time across DST.
    """
    match = re.fullmatch(r"([+-])([1-9][0-9]*)([mhd])", offset)
    if not match:
        raise ValueError("bad --by offset (want +30m, +2h, +1d or -30m)")
    if cur_sk != "timed" or not cur_start:
        raise ValueError("--by requires a timed task with a scheduled start")
    minutes = int(match[2]) * {"m": 1, "h": 60, "d": 1440}[match[3]]
    delta = timedelta(minutes=minutes if match[1] == "+" else -minutes)
    return ("timed", _iso_fmt(_iso_dt(cur_start) + delta),
            _iso_fmt(_iso_dt(cur_end) + delta) if cur_end else None)


def cli_task_reschedule(argv, mutation_state="changed"):
    # task-reschedule <id> <YYYY-MM-DD> [--at HH:MM | --all-day]
    #                 [--end HH:MM | --no-end]
    # task-reschedule <id> --by +2h  (scheduled start + offset, never now)
    #
    # --end HH:MM sets the end, --no-end clears it to start only; a time given
    # with no end never gets an invented length (owner 2026-10-12).
    #
    # Defer-preserves-time fix (2026-08-25). This verb used to hardcode
    # schedule_kind='all_day', so "move it to tomorrow" silently demoted a
    # TIMED task to an all-day one: resolve_time_mode then made it time_mode
    # ='due' and route_surface sent it to Google Tasks instead of the calendar
    # -- a surface the owner does not read. The owner had already ruled
    # (2026-08-23) that a task with no time-of-day is forbidden; that rule
    # landed on the registration path (task-add --at) and never on this one.
    # A defer now moves the DATE and nothing else; kind changes are explicit
    # (--at promotes/keeps timed, --all-day demotes).
    argv, at_raw = _pop_opt(argv, '--at')
    argv, force_all_day = _pop_flag(argv, '--all-day')
    argv, end_raw = _pop_opt(argv, '--end')
    argv, no_end = _pop_flag(argv, '--no-end')
    argv, by_raw = _pop_opt(argv, '--by')
    if by_raw is not None and (len(argv) != 1 or at_raw is not None or
                              force_all_day or end_raw is not None or no_end):
        _err("--by cannot be combined with a date, --at, --all-day, --end or --no-end")
    if not argv or not argv[0] or (by_raw is None and len(argv) != 2):
        _err("사용법: kit_life.sh task-reschedule <id> --by +2h | <id> <YYYY-MM-DD> "
             "[--at HH:MM | --all-day] [--end HH:MM | --no-end]")
    if by_raw is None and not _DATE_RE.match(argv[1]):
        _err(f"bad date format (want YYYY-MM-DD): {argv[1]}")
    conn = event_conn()
    _task_resched_ulid = None
    try:
        row = _resolve_task(conn, argv[0])
        _travel_block_gate(conn, row[0], "task-reschedule",
                           "all_day coercion would corrupt the block shape; use travel-move")
        # row = (id, ulid, title, start_at, end_at, schedule_kind, display_tz, ...)
        cur_start, cur_end, cur_sk, tz = row[3], row[4], row[5], row[6]
        try:
            if by_raw is not None:
                sk, sa, ea = _defer_by_shape(cur_sk, cur_start, cur_end, by_raw)
            else:
                sk, sa, ea = _defer_shape(cur_sk, cur_start, cur_end, tz, argv[1],
                                      at_hhmm=at_raw,
                                      force_all_day=force_all_day,
                                      end_hhmm=end_raw, no_end=no_end)
        except (ValueError, OverflowError) as e:
            _err(str(e))
        res, warn = bypass_schedule_apply(conn, row[1], sk, sa, ea)
        if res != "applied":
            _err(f"task-reschedule 실패 ({res})")
        if warn:
            print(warn, file=sys.stderr)
        if cur_sk == "untimed" and sk == "all_day":
            # the one shape change a plain defer can still cause -- say so
            # instead of letting it be silent (the 12999 class of defect).
            print("note: untimed task got a date but no time-of-day -- "
                  "it lands on the tasks surface, not the calendar. "
                  "re-run with --at HH:MM to put it on the calendar.",
                  file=sys.stderr)
        _task_resched_ulid = row[1]
        print(_task_line(_task_fetch(conn, row[0])))
        _print_cards(conn, [row[0]], mutation_state=mutation_state)
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _task_resched_ulid:
        _outbox_enqueue_best_effort(_task_resched_ulid)


# -- workout-defer: move a planned workout day (2026-10-13) ------------------
# Incident 2026-10-13 06:56: the owner said "just cardio today, push lower body
# to tomorrow, the InBody too" and the agent answered "deferred" with NO write -- the kit had
# no verb that moves a planned workout day, so the claim had nothing to stand
# on, and the follow-up hand moves (task-reschedule per row) left today's 06:00
# session row in place, relabelled in prose only.
#
# This verb is that move, owner spec 13:38/13:40 (D1 CORRECTED):
#   * the split's session task and the named companions (InBody ...) move TO the
#     target day/time together. Nothing is renamed at defer time: today keeps
#     no presumptive row, it simply has no workout row until a record makes one
#     (close_task.sh: a cardio record yields its own cardio task).
#   * the rotation is not touched -- rotation-current reads performed sets only,
#     so the deferred split stays next; nothing is skipped or queued.
#   * an existing target-day gym visit anchors the workout after that visit;
#     otherwise the target time defaults to the owner's usual time for that weekday
#     class (weekday / weekend) from the done session-task history; else the row's
#     own time.
#   * two steps: without --apply it prints DEFER_ASK (the confirm question +
#     one move button); --apply writes and prints DEFERRED rows plus the
#     DEFER_CARD read back from what was saved -- the agent echoes that card,
#     never its own sentence.
WORKOUT_DEFER_TITLE = "\ud5ec\uc2a4"
WORKOUT_DEFER_HISTORY_DAYS = 56
WORKOUT_DEFER_MIN_SAMPLES = 2


def _wd_tz():
    return ZoneInfo("Asia/Seoul")


def _wd_local(instant, tz_name=None):
    return (_iso_dt(instant).replace(tzinfo=timezone.utc)
            .astimezone(ZoneInfo(tz_name or "Asia/Seoul")))


def _wd_open_rows(conn, day, match):
    """Open (unsettled, not archived) task rows on local DAY whose title
    satisfies match(title). Rows: _task_fetch shape (11 cols)."""
    ws, we = all_day_instants(day)
    rows = conn.execute(
        "SELECT e.id FROM timeblock e WHERE e.kind='task' "
        "AND e.block_class IS NULL AND e.settled_at IS NULL "
        "AND e.start_at >= ? AND e.start_at < ? ORDER BY e.start_at, e.id;",
        (ws, we)).fetchall()
    out = []
    for (eid,) in rows:
        r = _task_fetch(conn, eid)
        if r is not None and match(r[2] or ""):
            out.append(r)
    return out


def _wd_is_session_title(title):
    t = WORKOUT_DEFER_TITLE
    return title == t or title.startswith(t + " -")


def _wd_weekday_class(day):
    return "weekend" if datetime.date.fromisoformat(day).weekday() >= 5 else "weekday"


def workout_usual_time(conn, target_day, before_day=None):
    """(HH:MM, n) = the modal local start time of DONE timed session rows on
    the target day's weekday class over the last WORKOUT_DEFER_HISTORY_DAYS
    (ties -> the most recent). None when fewer than WORKOUT_DEFER_MIN_SAMPLES
    rows share the modal time."""
    before = before_day or target_day
    lo = (datetime.date.fromisoformat(before)
          - timedelta(days=WORKOUT_DEFER_HISTORY_DAYS)).isoformat()
    ws, _ = all_day_instants(lo)
    we, _ = all_day_instants(before)
    cls = _wd_weekday_class(target_day)
    counts, last_seen = {}, {}
    for title, sa, tz in conn.execute(
            "SELECT title, start_at, display_tz FROM timeblock "
            "WHERE kind='task' AND schedule_kind='timed' "
            "AND settled_outcome='done' AND start_at >= ? AND start_at < ? "
            "ORDER BY start_at;", (ws, we)).fetchall():
        if not _wd_is_session_title(title or ""):
            continue
        loc = _wd_local(sa, tz)
        if _wd_weekday_class(loc.strftime("%Y-%m-%d")) != cls:
            continue
        hm = loc.strftime("%H:%M")
        counts[hm] = counts.get(hm, 0) + 1
        last_seen[hm] = sa
    if not counts:
        return None
    hm = max(counts, key=lambda k: (counts[k], last_seen[k]))
    if counts[hm] < WORKOUT_DEFER_MIN_SAMPLES:
        return None
    return hm, counts[hm]


def _ko_has_final(word):
    """True when the last syllable of WORD carries a final consonant other
    than rieul (the euro/ro particle split); Latin letters and digits read as open."""
    s = (word or "").rstrip()
    if not s:
        return False, False
    c = s[-1]
    if "\uac00" <= c <= "\ud7a3":
        jong = (ord(c) - 0xAC00) % 28
        return jong != 0, jong == 8
    return False, False


def _ko_ro(word):
    fin, rieul = _ko_has_final(word)
    return word + ("\uc73c\ub85c" if fin and not rieul else "\ub85c")


def _ko_rang(word):
    fin, _r = _ko_has_final(word)
    return word + ("\uc774\ub791" if fin else "\ub791")


def _wd_time_phrase(hm, lang):
    h, m = (int(x) for x in hm.split(":"))
    if lang != "ko":
        ap = "am" if h < 12 else "pm"
        return "%d:%02d %s" % (h % 12 or 12, m, ap)
    if h < 5:
        part = "\uc0c8\ubcbd"
    elif h < 11:
        part = "\uc544\uce68"
    elif h < 12:
        part = "\uc624\uc804"
    elif h < 18:
        part = "\uc624\ud6c4" if h > 12 else "\ub0ae"
    elif h < 22:
        part = "\uc800\ub141"
    else:
        part = "\ubc24"
    h12 = h if h <= 12 else h - 12
    return "%s %d\uc2dc" % (part, h12) + (" %d\ubd84" % m if m else "")


_WD_DOW_EN = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
_WD_DOW_EN_FULL = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
                   "Saturday", "Sunday")


def _wd_visit(conn, day, session, moving):
    """First open timed gym visit on DAY, with its recorded end as the anchor.

    Place identity admits appointments and tasks at the session's gym. Legacy
    InBody tasks have no place: admit that exact title only for the same owning
    agent, never a measurement explicitly placed at a different venue.
    """
    place, owner = conn.execute(
        "SELECT place_id, owning_agent FROM timeblock WHERE id=?;",
        (session[0],)).fetchone()
    ws, we = all_day_instants(day)
    for eid, ulid, title, sa, ea, pid, agent, venue in conn.execute(
            "SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, "
            "e.place_id, e.owning_agent, p.name FROM timeblock e "
            "LEFT JOIN place p ON p.id=e.place_id "
            "WHERE e.kind IN ('task','appointment') "
            "AND e.schedule_kind='timed' AND e.block_class IS NULL "
            "AND e.settled_at IS NULL AND e.start_at >= ? AND e.start_at < ? "
            "ORDER BY e.start_at, e.id;", (ws, we)).fetchall():
        if eid in moving or _wd_is_session_title(title or ""):
            continue
        same_place = place is not None and pid == place
        legacy_inbody = (pid is None and owner and agent == owner
                         and (title or "").strip().casefold()
                         in ("\uc778\ubc14\ub514", "inbody"))
        if not (same_place or legacy_inbody):
            continue
        if not ea or ea <= sa:
            raise ValueError("VISIT_NO_END", "id=%s has no recorded visit end" % eid)
        # _defer_shape interprets the clock in the moved session's timezone.
        loc_end = _wd_local(ea, session[6])
        if loc_end.date().isoformat() != day or loc_end.second or loc_end.microsecond:
            raise ValueError("VISIT_TIME", "id=%s end is not a target-day minute" % eid)
        return dict(id=eid, ulid=ulid, title=title, start_at=sa, end_at=ea,
                    at=loc_end.strftime("%H:%M"), place=venue,
                    start=_wd_local(sa, session[6]).strftime("%H:%M"))
    return None


def _wd_visit_suffix(plan):
    """A factual clock/title fragment, using the card's existing separators."""
    visit = plan.get("visit")
    if not visit:
        return ""
    text = " \u00b7 %s\u2013%s %s" % (visit["start"], visit["at"], visit["title"])
    if visit["place"]:
        text += " \u00b7 " + visit["place"]
    return text


def workout_defer_plan(conn, from_day, to_day, at=None, companions=(),
                       rotation=None):
    """Resolve the rows a defer would move and the slot it lands on.
    Returns a dict; raises ValueError(code, detail) on a refusal."""
    sess = _wd_open_rows(conn, from_day, _wd_is_session_title)
    if not sess:
        raise ValueError("NONE", "no open %s task on %s"
                         % (WORKOUT_DEFER_TITLE, from_day))
    if len(sess) > 1:
        raise ValueError("MULTI", ",".join(str(r[0]) for r in sess))
    rows = [sess[0]]
    for name in companions:
        hit = _wd_open_rows(conn, from_day, lambda t, n=name: t == n)
        if not hit:
            raise ValueError("COMPANION_NONE", "no open task '%s' on %s"
                             % (name, from_day))
        if len(hit) > 1:
            raise ValueError("COMPANION_MULTI", name)
        if hit[0][0] not in [r[0] for r in rows]:
            rows.append(hit[0])
    clash = _wd_open_rows(conn, to_day, _wd_is_session_title)
    if clash:
        raise ValueError("CONFLICT", "%s already has open %s task id=%s"
                         % (to_day, WORKOUT_DEFER_TITLE, clash[0][0]))
    title = sess[0][2]
    split = title[len(WORKOUT_DEFER_TITLE) + 3:].strip() \
        if title.startswith(WORKOUT_DEFER_TITLE + " -") else ""
    if not split:
        rot = rotation if rotation is not None else rotation_current(conn=conn)
        split = rot.get("next_split") or ""
    visit = None
    if at:
        if not _HHMM_RE.match(at):
            raise ValueError("BAD_TIME", at)
        hm, source = at, "given"
    else:
        visit = _wd_visit(conn, to_day, sess[0], {r[0] for r in rows})
        usual = None if visit else workout_usual_time(conn, to_day, before_day=from_day)
        if visit:
            hm, source = visit["at"], "visit"
        elif usual:
            hm, source = usual[0], "usual"
        elif sess[0][5] == "timed" and sess[0][3]:
            hm, source = _wd_local(sess[0][3], sess[0][6]).strftime("%H:%M"), "own"
        else:
            raise ValueError("NO_TIME", "no usual time and the row has no "
                             "time-of-day -- give --at HH:MM")
    return dict(rows=rows, split=split or WORKOUT_DEFER_TITLE, at=hm,
                source=source, from_day=from_day, to_day=to_day,
                weekday_class=_wd_weekday_class(to_day), visit=visit)


def _wd_labels(plan):
    return [plan["split"]] + [r[2] for r in plan["rows"][1:]]


def _wd_range_text(day, start_hm, end_hm, lang):
    """'M/D(dow) HH:MM-HH:MM' (start only when the end is unknown)."""
    d = datetime.date.fromisoformat(day)
    dow = _WEEKDAY_KO[d.weekday()] if lang == "ko" else _WD_DOW_EN[d.weekday()]
    out = "%d/%d(%s)" % (d.month, d.day, dow)
    if start_hm:
        out += " " + start_hm + ("\u2013" + end_hm if end_hm else "")
    return out


def _wd_ask_items(conn_rows, plan, lang):
    """Per moved row: name, place, minutes, before/after range text."""
    items = []
    for i, r in enumerate(plan["rows"]):
        sk, sa, ea, tz = r[5], r[3], r[4], r[6]
        name = plan["split"] if i == 0 else r[2]
        mins = None
        if sk == "timed" and sa and ea:
            mins = int((_iso_dt(ea) - _iso_dt(sa)).total_seconds() // 60) or None
        nsk, nsa, nea = _defer_shape(sk, sa, ea, tz, plan["to_day"],
                                     at_hhmm=plan["at"])

        def rng(k, a, b):
            loc = _wd_local(a, tz)
            if k != "timed":
                return _wd_range_text(loc.date().isoformat(), None, None, lang)
            end = _wd_local(b, tz).strftime("%H:%M") if b and b != a else None
            return _wd_range_text(loc.date().isoformat(),
                                  loc.strftime("%H:%M"), end, lang)
        items.append(dict(name=name, place=(r[10] or "").strip(), mins=mins,
                          before=rng(sk, sa, ea), after=rng(nsk, nsa, nea)))
    return items


def workout_defer_ask_text(plan, lang=None):
    """The deferral screen (owner-approved 2026-10-27): optional reason line,
    a quote block (name / place / duration / before / after), the question."""
    lang = lang or _plan_lang()
    items = _wd_ask_items(None, plan, lang)
    lines = [it["name"] for it in items]
    # place / duration: shown once when the items that have one agree
    place = {it["place"] for it in items if it["place"]}
    if len(place) == 1:
        lines.append(_i18n("workout.defer.ask.place", "Place: {place}")
                     .replace("{place}", place.pop()))
    mins = {it["mins"] for it in items if it["mins"]}
    if len(mins) == 1:
        lines.append(_i18n("workout.defer.ask.duration", "Duration: {n} min")
                     .replace("{n}", str(mins.pop())))
    bt = _i18n("workout.defer.ask.before", "Before change: {range}")
    at_ = _i18n("workout.defer.ask.after", "After change: {range}")
    if len({(it["before"], it["after"]) for it in items}) == 1:
        pairs = items[:1]
    else:
        pairs = items
    for it in pairs:
        lines.append(bt.replace("{range}", it["before"]))
        lines.append(at_.replace("{range}", it["after"]))
    out = [DAY_ROW_QUOTE + _day_pin_defuse(l) for l in lines]
    if plan["source"] == "usual":
        cls = _i18n("workout.defer.class.%s" % plan["weekday_class"],
                    plan["weekday_class"])
        reason = _i18n("workout.defer.ask.usual",
                       "You usually train {class} at {usual}.")
        out.insert(0, reason.replace("{class}", cls)
                   .replace("{usual}", _wd_time_phrase(plan["at"], lang)))
    out.append("")
    out.append(_i18n("workout.defer.ask.question", "Change the schedule?"))
    return "\n".join(out)


# device_label: which watch / phone produced a workout. Reads the arrival
# payload's source fields (HealthKit sourceName / source.name / bundleIdentifier,
# Health Connect dataOrigin / device manufacturer + model). The exact field
# names are NOT verified against a real arrival (the health pack clone was not
# available): every known spelling is tried, and an unreadable source gives
# None, never a guess.
_DEV_SRC_KEYS = ("device", "deviceName", "device_name", "source", "sourceName",
                 "source_name", "sourceRevision", "bundleIdentifier",
                 "bundle_id", "bundleId", "dataOrigin", "data_origin",
                 "origin", "manufacturer", "model", "brand", "product",
                 "name", "package", "packageName")
_DEV_PHONE_RE = re.compile(r"\b(iphone|ipad|ipod|pixel \d|android phone)\b|phone|\ud3f0",
                           re.I)
_DEV_KNOWN = (  # (key, pattern) - first match wins; order matters
    ("apple", re.compile(r"apple\s*watch|\uc560\ud50c\s*\uc6cc\uce58|com\.apple\.health|watch\d+,\d+", re.I)),
    ("galaxy", re.compile(r"galaxy\s*watch|\uac24\ub7ed\uc2dc\s*\uc6cc\uce58|sm-r\d{3}|com\.samsung\.android\.wear|com\.sec\.android\.app\.shealth", re.I)),
    ("garmin", re.compile(r"garmin|\uac00\ubbfc|com\.garmin", re.I)),
    ("fitbit", re.compile(r"fitbit|\ud54f\ube57|com\.fitbit", re.I)),
)


def _dev_strings(info):
    out = []
    if isinstance(info, str):
        out.append(info)
    elif isinstance(info, dict):
        for k in _DEV_SRC_KEYS:
            if k in info:
                out.extend(_dev_strings(info[k]))
    return [x.strip() for x in out if isinstance(x, str) and x.strip()]


def _dev_maker(info):
    """The manufacturer / brand string of a source dict (also inside its
    nested `device` dict), else None."""
    if not isinstance(info, dict):
        return None
    for d in (info, info.get("device")):
        if isinstance(d, dict):
            for k in ("manufacturer", "brand"):
                v = d.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
    return None


def device_label(source_info, lang=None):
    """Display name of the device behind a workout arrival, or None when it
    cannot be told. Apple Watch, Galaxy Watch, Garmin and Fitbit get their i18n names
    (watch.device.*), a phone-only source gets the phone name (not a watch),
    any other Wear OS / watch maker -> the manufacturer's own name.
    source_info: a string or a dict (nested dicts are read too)."""
    lang = lang or _plan_lang()
    texts = _dev_strings(source_info)
    if not texts:
        return None
    blob = " | ".join(texts)

    def t(k, fb):
        return _i18n_lang("record.notice.watch.device." + k, lang, fb)
    for key, rx in _DEV_KNOWN:
        if rx.search(blob):
            return t(key, key)
    if re.search(r"watch|wear\s*os|\uc6cc\uce58", blob, re.I):
        return _dev_maker(source_info) or t("unknown", "")
    if _DEV_PHONE_RE.search(blob):
        return t("phone", "")
    maker = _dev_maker(source_info)
    return maker if maker and not _DEV_PHONE_RE.search(maker) else None


def workout_received_notice(name, minutes=None, start=None, end=None,
                            kcal=None, question=None, lang=None, device=None):
    """The watch-workout notice, in the shared record frame (owner
    2026-10-27 09:06 / 09:50): title naming the real device (Apple Watch
    -> the i18n watch.device.apple name; no device -> watch.device.unknown), then the workout / time / burn rows in one quote block
    (only the fields that have a value), then the question if there is one.
    start / end are "HH:MM" strings; minutes / kcal are numbers (kcal is
    rounded). device is the display name from device_label()."""
    import record_notice  # the one record frame; lazy: test copies of the kit omit it
    lang = lang or _plan_lang()

    def t(key, fb=""):
        return _i18n_lang("record.notice." + key, lang, fb)
    dur = (t("val.min").replace("{n}", str(int(round(minutes))))
           if minutes and int(round(minutes)) else "")
    rng = (t("val.range").replace("{start}", start).replace("{end}", end)
           if start and end else "")
    when = (t("val.time_range").replace("{dur}", dur).replace("{range}", rng)
            if dur and rng else dur or rng)
    burn = (t("val.kcal").replace("{n}", str(int(round(kcal))))
            if kcal and int(round(kcal)) else "")
    dev = (device or "").strip() or t("watch.device.unknown", "")
    return record_notice.render(
        t("watch.title").replace("{device}", dev),
        [(t("watch.label.workout"), name),
         (t("watch.label.time"), when),
         (t("watch.label.burn"), burn)],
        question)


def workout_defer_card(conn, plan, lang=None):
    """The confirmation card, read back from the SAVED rows."""
    lang = lang or _plan_lang()
    parts, day = [], None
    for i, r0 in enumerate(plan["rows"]):
        r = _task_fetch(conn, r0[0])
        loc = _wd_local(r[3], r[6])
        day = day or loc.date()
        label = plan["split"] if i == 0 else r[2]
        s = "%s %s" % (loc.strftime("%H:%M"), label)
        if r[10]:
            s += " \u00b7 %s" % r[10]
        parts.append(s)
    rows = ", ".join(parts)
    if lang == "ko":
        date_s = "%s %d/%d" % (_WEEKDAY_KO[day.weekday()], day.month, day.day)
        rows = _ko_ro(rows)
    else:
        date_s = "%s %d/%d" % (_WD_DOW_EN[day.weekday()], day.month, day.day)
    tmpl = _i18n("workout.defer.done", "\u2705 Moved to {date}: {rows}")
    return (tmpl.replace("{date}", date_s).replace("{rows}", rows)
            + _wd_visit_suffix(plan))


def workout_defer_apply(conn, plan):
    """Move every planned row to plan['to_day'] at plan['at'] (duration kept).
    All or nothing: a refused row puts the rows already moved back."""
    done = []
    for r in plan["rows"]:
        eid, ulid, _t, sa, ea, sk, tz = r[:7]
        nsk, nsa, nea = _defer_shape(sk, sa, ea, tz, plan["to_day"],
                                     at_hhmm=plan["at"])
        res, _warn = bypass_schedule_apply(conn, ulid, nsk, nsa, nea)
        if res != "applied":
            for (u, osk, osa, oea) in reversed(done):
                bypass_schedule_apply(conn, u, osk, osa, oea)
            raise ValueError("APPLY_FAILED", "id=%s (%s)" % (eid, res))
        done.append((ulid, sk, sa, ea))
    return [d[0] for d in done]


def cli_workout_defer(argv):
    # workout-defer [--from YYYY-MM-DD] [--to YYYY-MM-DD] [--at HH:MM]
    #               [--with <title>]... [--apply]
    # --from defaults to today (KST), --to to the day after --from.
    # stdout (no --apply):
    #   DEFER_ASK<TAB><question><TAB>split=<code><TAB>to=<date><TAB>at=<HH:MM>
    #            <TAB>source=visit|usual|own|given<TAB>ids=<id,...><TAB>choices=move=<label>
    #   ASK_OPTIONS<TAB>DEFER_ASK<TAB><ids><TAB>[[OPTIONS: <label>]]
    # stdout (--apply):
    #   DEFERRED<TAB><id><TAB><title><TAB><date><TAB><HH:MM>   one per moved row
    #   DEFER_CARD<TAB><card>   -- echo this verbatim, nothing else
    # Refusal: DEFER_REFUSED<TAB><code><TAB><detail>, exit 1, nothing written.
    companions = []
    while "--with" in argv:
        argv, w = _pop_opt(argv, "--with")
        if w:
            companions.append(w)
    argv, from_day = _pop_opt(argv, "--from")
    argv, to_day = _pop_opt(argv, "--to")
    argv, at = _pop_opt(argv, "--at")
    argv, apply_ = _pop_flag(argv, "--apply")
    if argv:
        _err("usage: kit_life.sh workout-defer [--from YYYY-MM-DD] "
             "[--to YYYY-MM-DD] [--at HH:MM] [--with <title>]... [--apply]")
    from_day = from_day or datetime.datetime.now(_wd_tz()).strftime("%Y-%m-%d")
    for d in (from_day, to_day):
        if d and not _DATE_RE.match(d):
            _err(f"bad date format (want YYYY-MM-DD): {d}")
    to_day = to_day or (datetime.date.fromisoformat(from_day)
                        + timedelta(days=1)).isoformat()
    conn = event_conn()
    moved = []
    try:
        try:
            plan = workout_defer_plan(conn, from_day, to_day, at=at,
                                      companions=companions)
            if apply_:
                moved = workout_defer_apply(conn, plan)
        except ValueError as e:
            code, detail = (e.args + ("",))[:2]
            print("DEFER_REFUSED\t%s\t%s" % (code, detail))
            print("workout-defer refused: %s %s -- nothing was moved"
                  % (code, detail), file=sys.stderr)
            sys.exit(1)
        ids = ",".join(str(r[0]) for r in plan["rows"])
        if not apply_:
            ac = _ask_choices()
            choices = [("move", _i18n("workout.defer.button.move", "Change")),
                       ("keep", _i18n("workout.defer.button.keep", "Keep as is"))]
            print("DEFER_ASK\t%s\tsplit=%s\tto=%s\tat=%s\tsource=%s\tids=%s\t%s"
                  % (workout_defer_ask_text(plan), plan["split"], to_day,
                     plan["at"], plan["source"], ids,
                     ac.choices_field(choices)))
            print(ac.options_line("DEFER_ASK", ids, choices))
            return
        for r0 in plan["rows"]:
            r = _task_fetch(conn, r0[0])
            loc = _wd_local(r[3], r[6])
            print("DEFERRED\t%s\t%s\t%s\t%s" % (r[0], r[2],
                                                loc.strftime("%Y-%m-%d"),
                                                loc.strftime("%H:%M")))
        print("DEFER_CARD\t%s" % workout_defer_card(conn, plan))
    finally:
        conn.close()
    for u in moved:
        _outbox_enqueue_best_effort(u)


def _parse_postpone_when(text, now=None, tz_name="Asia/Seoul"):
    """Resolve an owner-facing postpone time to a local date and clock time.

    A clock without a day means its next occurrence after ``now``. For an
    ambiguous 12-hour clock this considers both AM and PM. An explicit day
    wins and uses the stated clock on that day; an unqualified clock on an
    explicit day keeps its literal hour (9 means 09:00). Korean literals use
    escapes so this implementation block remains ASCII-only.
    """
    value = (text or "").strip().lower()
    if not value:
        raise ValueError("postpone time is empty")
    tz = ZoneInfo(tz_name or "Asia/Seoul")
    if now is None:
        local_now = datetime.datetime.now(tz)
    elif isinstance(now, str):
        local_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        if local_now.tzinfo is None:
            local_now = local_now.replace(tzinfo=tz)
        else:
            local_now = local_now.astimezone(tz)
    else:
        local_now = now
        if local_now.tzinfo is None:
            local_now = local_now.replace(tzinfo=tz)
        else:
            local_now = local_now.astimezone(tz)

    # Consume recognized day/meridiem tokens, then require one whole clock
    # expression. Partial matches must not silently turn 9:99 into 9:00 or
    # an unsupported day into today.
    days = re.findall(r"\d{4}-\d{2}-\d{2}|\uc624\ub298|\ub0b4\uc77c|\ubaa8\ub808|\btoday\b|\btomorrow\b", value)
    if len(days) > 1:
        raise ValueError("give one day")
    explicit_day = None
    if days:
        day = days[0]
        offsets = {"\uc624\ub298": 0, "today": 0,
                   "\ub0b4\uc77c": 1, "tomorrow": 1, "\ubaa8\ub808": 2}
        explicit_day = (local_now.date() + timedelta(days=offsets[day])
                        if day in offsets else datetime.date.fromisoformat(day))
        value = value.replace(day, "", 1).strip()
    parts = re.findall(r"\uc624\uc804|\uc624\ud6c4|\bam\b|\bpm\b", value)
    if len(parts) > 1:
        raise ValueError("give one meridiem")
    meridiem = None
    if parts:
        meridiem = "pm" if parts[0] in ("\uc624\ud6c4", "pm") else "am"
        value = value.replace(parts[0], "", 1).strip()
    value = re.sub(r"\s*(?:\uc73c\ub85c|\ub85c)?\s*(?:\ubbf8\ub904\s*\uc918|\uc62e\uaca8\s*\uc918)?[.!?]*$", "", value).strip()
    value = re.sub(r"^at\s+", "", value)
    match = re.fullmatch(r"([0-9]{1,2}):([0-9]{2})", value)
    if match:
        hour, minute = int(match.group(1)), int(match.group(2))
    else:
        native_hours = dict(zip(
            ("\ud55c", "\ub450", "\uc138", "\ub124", "\ub2e4\uc12f", "\uc5ec\uc12f",
             "\uc77c\uacf1", "\uc5ec\ub35f", "\uc544\ud649", "\uc5f4", "\uc5f4\ud55c", "\uc5f4\ub450"),
            range(1, 13)))
        match = re.fullmatch(r"([0-9]{1,2}|" + "|".join(native_hours) +
                             r")\s*\uc2dc\s*(?:(\ubc18)|([0-9]{1,2})\s*\ubd84)?", value)
        if not match:
            raise ValueError("postpone time needs H:MM or an hour expression")
        raw_hour = match.group(1)
        hour = native_hours[raw_hour] if raw_hour in native_hours else int(raw_hour)
        minute = 30 if match.group(2) else int(match.group(3) or 0)
    if hour > 23 or minute > 59 or (meridiem and not 1 <= hour <= 12):
        raise ValueError("postpone clock is out of range")

    if meridiem:
        hour = hour % 12 + (12 if meridiem == "pm" else 0)
        hours = [hour]
    elif 1 <= hour <= 12 and explicit_day is None:
        hours = sorted(set((hour % 12, hour % 12 + 12)))
    else:
        hours = [hour]

    if explicit_day is not None:
        chosen = datetime.datetime.combine(
            explicit_day,
            datetime.time(hours[0], minute), tzinfo=tz)
    else:
        candidates = []
        for extra_day in (0, 1):
            date_value = local_now.date() + timedelta(days=extra_day)
            for candidate_hour in hours:
                candidate = datetime.datetime.combine(
                    date_value, datetime.time(candidate_hour, minute), tzinfo=tz)
                if candidate > local_now:
                    candidates.append(candidate)
        chosen = min(candidates)
    return chosen.date().isoformat(), chosen.strftime("%H:%M")


def cli_task_postpone(argv):
    # task-postpone <id> <owner time text> [--now ISO]
    # Resolve the time first, then move the existing row. Never implement a
    # postpone as task-add: moving one identity cannot leave a duplicate.
    argv, now_raw = _pop_opt(argv, '--now')
    if len(argv) < 2 or not argv[0]:
        _err("usage: kit_life.sh task-postpone <id> <time text> [--now ISO]")
    text = " ".join(argv[1:])
    try:
        date_value, hhmm = _parse_postpone_when(text, now=now_raw)
    except (ValueError, TypeError, OverflowError):
        _err(_i18n("task.postpone.invalid", "Invalid postpone time."))
    cli_task_reschedule([argv[0], date_value, '--at', hhmm], mutation_state='postponed')


def cli_task_undate(argv):
    # task-undate <id>  -- retro-read-paths / D5 나중에: demote a DATED task
    # back to the dateless open shape (schedule_kind='untimed',
    # start_at/end_at NULL) -- the same shape task-add produces when given no
    # due date. task-reschedule has no path here (it always requires a date);
    # this is its dateless counterpart, named after the un- family
    # (project-unlink, travel-unpin) rather than task-undone's done/undone
    # pairing, since there is no "task-date" verb to pair against.
    #
    # The row stays open (status is a v_block_state derivation off
    # settled_at, untouched here) and block_class stays NULL, so it keeps
    # showing on every open-task surface (task-find/task-overdue exclude it
    # only for lacking start_at, not for being untimed) and it also becomes
    # visible on task-untimed-open (kind='task' AND settled_at IS NULL AND
    # status='open' AND block_class IS NULL AND schedule_kind='untimed' AND
    # start_at IS NULL) -- exactly the auto-linker's candidate predicate. See
    # the report for the consequence; nothing about the auto-linker itself
    # changes here.
    #
    # A routine occurrence refuses (bypass_schedule_apply's M-C untimed gate,
    # 'rejected_untimed') -- a recurring instance may never lose its date.
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh task-undate <id>")
    conn = event_conn()
    _task_undate_ulid = None
    try:
        row = _resolve_task(conn, argv[0])
        _travel_block_gate(conn, row[0], "task-undate",
                           "travel blocks are derived and carry no date to clear")
        res, warn = bypass_schedule_apply(conn, row[1], "untimed", None, None)
        if res != "applied":
            _err(f"task-undate 실패 ({res})")
        if warn:
            print(warn, file=sys.stderr)
        _task_undate_ulid = row[1]
        print(_task_line(_task_fetch(conn, row[0])))
        _timeblock_card_mod().emit(sys.modules[__name__],
                                   _mutation_card(conn, 'task-undate', row[0], 'changed'))
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _task_undate_ulid:
        _outbox_enqueue_best_effort(_task_undate_ulid)


def cli_task_retitle(argv):
    # task-retitle <id> <new_title> -- rename an actionable timeblock's title.
    # Actionable = kind IN ('task','appointment'); presence rows and derived
    # travel blocks are refused LOUDLY (a rename has no meaning there). Pure
    # title mutation: no slot touched, so it uses the focused CAS-guarded write
    # convention (same as _settle) rather than the slot-overlap helper.
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err("사용법: kit_life.sh task-retitle <id> <new_title>")
    if not str(argv[0]).isdigit():
        _err(f"해당 id 태스크 없음: {argv[0]}")
    eid = int(argv[0])
    new_title = argv[1]
    conn = event_conn()
    _task_retitle_ulid = None
    try:
        row = conn.execute(
            "SELECT id, ulid, kind, block_class, version, schedule_kind, "
            "display_tz FROM timeblock WHERE id=?;", (eid,)).fetchone()
        if row is None:
            _err(f"해당 id 태스크 없음: {eid}")
        _id, ulid, kind, block_class, version, sk, tz = row
        # V6-style loud refusal: derived travel blocks never get retitled here.
        if block_class == "travel":
            _err("task-retitle: travel block refused -- derived block titles "
                 "are owned by the travel deriver (use travel-move / travel-skip)")
        # Only actionable rows carry a user-authored title worth renaming.
        if kind not in ("task", "appointment"):
            _err(f"task-retitle: {kind} 행은 이름 변경 불가. "
                 "actionable(task/appointment) 행만 대상")
        # Focused CAS-guarded write (mirrors the _settle convention): bump
        # version, stamp updated_at, then recompute+commit in one txn.
        now = now_utc()
        conn.execute("BEGIN IMMEDIATE;")
        try:
            if _tb_update(conn, eid, {'title': new_title, 'updated_at': now},
                          bump_version=True, cas_version=version) != 1:
                conn.rollback()
                _err("task-retitle 실패 (cas_fail): 동시 변경 감지")
            _recompute_and_store(conn, eid, now=now)
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        _task_retitle_ulid = ulid
        # Output matches cli_task_reschedule's TSV columns (id/title/due/state).
        r = conn.execute(
            "SELECT id, title, start_at, settled_outcome FROM timeblock "
            "WHERE id=?;", (eid,)).fetchone()
        due = str(_local_date_of(r[2], tz or "Asia/Seoul")) if r[2] else ""
        state = "done" if r[3] == "done" else "todo"
        print(f"{r[0]}\t{r[1]}\t{due}\t{state}")
        _print_cards(conn, [eid], mutation_state="changed")
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit -- a
    # retitle must re-push the new title to the calendar surface.
    if _task_retitle_ulid:
        _outbox_enqueue_best_effort(_task_retitle_ulid)


def cli_task_archive(argv):
    # OQ-C1 (LOUD, TEMPORARY): 179 task-archive semantics = archived_at
    # visibility soft-delete, but the event table has NO archive home
    # (archived_at lives on the legacy tasks table only). Per the OQ-C1
    # ruling fallback we do NOT invent schema here: archive maps to
    # cancel(abandoned) -- hidden from task-find/overdue and deleted from
    # the mirror surface (X8). Divergence: an archived task shows as
    # "cancelled" semantics, not neutral archive. Revisit when an event
    # archive column is specced (OPEN QUESTION OQ-C1 in DGN-180).
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh task-archive <id>")
    conn = event_conn()
    _task_archive_ulid = None
    try:
        row = _resolve_task(conn, argv[0])
        _travel_block_gate(conn, row[0], "task-archive",
                           "skip semantics live in travel-skip (pin/tombstone bookkeeping differs)")
        res = cancel(conn, row[0], row[9], _facade_agent())
        if res != MutationResult.APPLIED:
            _err(f"task-archive 실패 ({res}): 이미 종결되었거나 동시 변경")
        _task_archive_ulid = row[1]
        print(f"{row[0]}\t{row[2]}\tarchived")
        _timeblock_card_mod().emit(sys.modules[__name__],
                                   _done_card(conn, "task-archive", row[0]))
    finally:
        conn.close()
    # DGN-258: best-effort mirror outbox enqueue after successful commit.
    if _task_archive_ulid:
        _outbox_enqueue_best_effort(_task_archive_ulid)


def cli_retro_start(argv):
    # A typed date or the issued card/callback binds this read-only entry.
    argv, date = _pop_opt(argv, '--date')
    if len(argv) > 1 or (not argv and date is None):
        _err('usage: retro-start "<action or full reply context>"')
    import retro_session
    try:
        with open(os.path.join(_instance_root(), '.telegram_bot', 'inbound-context.json')) as fh:
            inbound = json.load(fh)
    except (OSError, ValueError):
        inbound = {}
    out = retro_session.resolve(argv[0] if argv else '', inbound, now_utc(), date=date)
    print(json.dumps(out or dict(status='NOT_RETRO'), ensure_ascii=False))


def cli_task_overdue(argv):
    # task-overdue [--before YYYY-MM-DD] [--owning-agent <name>]
    # open tasks whose effective end passed before today's local midnight.
    # Same domain read-scope task-find already carries: this verb is the
    # identical leak shape (no owner filter at all, so every instance sharing
    # one DB reads every other instance's backlog), measured live before it
    # was closed -- a life-domain retro listing the health instance's unclosed
    # roller-born blocks as its own overdue backlog.
    argv, weekly = _pop_flag(argv, "--weekly")
    argv, before = _pop_opt(argv, "--before")
    argv, owning_agent = task_find_owning_agent(argv)
    if before:
        try:
            if datetime.date.fromisoformat(before).isoformat() != before:
                raise ValueError()
        except ValueError:
            _err('task-overdue --before requires YYYY-MM-DD')
    today = before or datetime.datetime.now(ZoneInfo("Asia/Seoul")).strftime("%Y-%m-%d")
    today_start, _ = all_day_instants(today)
    conn = event_conn()
    try:
        rows = conn.execute(
            # DGN-579: trailing place name (11th col) via LEFT JOIN.
            "SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, "
            "e.schedule_kind, e.display_tz, e.settled_outcome, e.settled_at, "
            "e.version, p.name FROM timeblock e "
            "LEFT JOIN place p ON p.id = e.place_id "
            "WHERE e.kind='task' AND e.settled_at IS NULL "
            "AND e.block_class IS NULL "  # DGN-274 4.4 (V7): expired blocks
                                          # must never pile up in overdue
            "AND e.start_at IS NOT NULL "
            "AND COALESCE(e.end_at, e.start_at) <= ? "
            # Domain read-scope (see task_find_owning_agent). `? IS NULL`
            # keeps an unscoped caller byte-identical; a scoped caller never
            # sees another domain agent's backlog.
            "AND (? IS NULL OR instr(',' || ? || ',', ',' || e.owning_agent || ',') > 0) "
            "ORDER BY e.start_at;",
            (today_start, owning_agent, owning_agent)).fetchall()
        for row in rows:
            if weekly:
                if not weekly_review_visible(conn, row[0]):
                    continue
                row = list(row)
                row[2] = weekly_review_title(conn, row[0], row[2])
            print(_task_line(row))
    finally:
        conn.close()


def retro_system_task_ids(conn):
    """Workflow provenance, including a legacy ledger task's saved identity."""
    ids = {r[0] for r in conn.execute(
        "SELECT id FROM timeblock WHERE kind='task' AND "
        "(created_by='kit' OR substr(created_by,1,7)='module_')")}
    # Older onboarding wrote the facade as creator. Its own saved task id is
    # producer evidence; matching the localized title alone would hide owner tasks.
    try:
        path = os.path.join(_instance_root(), 'files', 'ledger', 'onboarding.json')
        with open(path, encoding='utf-8') as fh:
            state = json.load(fh)
        tid = (state.get('backfill') or {}).get('task_id')
        if str(tid).isdigit() and conn.execute(
                "SELECT 1 FROM timeblock WHERE id=? AND kind='task'", (int(tid),)).fetchone():
            ids.add(int(tid))
    except (OSError, ValueError, AttributeError, TypeError):
        pass
    return ids


def cli_task_untimed_open(argv):
    # task-untimed-open [--suggest] [--owning-agent <name>]
    #   (read-only without --suggest; ag-life-integration R1)
    # Surface OPEN untimed/floating task fragments -- the ones every other task
    # query misses because they carry no start_at (task-overdue and the day view
    # both require start_at IS NOT NULL). These are the fragments the mirror
    # routes to Google Tasks, a surface the user does not actually watch, so
    # they silently die as 'abandoned'. This verb lets the daily/weekly surfaces
    # pull them back where the user reacts to them.
    #
    # Output TSV cols: id  title  updated_at(local YYYY-MM-DD)  [suggest_project]
    # The first 3 fields are always present. With --suggest a 4th field is
    # appended: the title of the single best-matching active project (longest
    # word overlap / substring), or '' when no confident match. The suggestion
    # is READ-ONLY -- nothing is persisted (timeblock has no project_id column
    # yet; that is a separate kit_life-lane schema change). It is purely a hint
    # for the surface to show the user for an auto-suggest react.
    #
    # SILENT AUTO-LINK (ag-life-integration, owner-confirmed direction): when the
    # timeblock.project_id column is present (migration 027 applied) AND --suggest
    # is passed, the best-matching active project is PERSISTED onto the block
    # (no user prompt) via _autolink_project. On a pre-027 DB the write silently
    # no-ops and this verb stays read-only -- so the same code is safe in the
    # live tree before the migration lands. The 4th printed field always reflects
    # the linked/suggested project title (identical whether persisted or not).
    #
    # Owner read-scope (2.39.x): the same task_find_owning_agent scope as
    # task-find / task-overdue. The weekly retro reads this list as the
    # owner's set-aside (later) backlog, and on a shared crew DB an unscoped read would
    # hand the life agent the health agent's dateless rows as its own.
    #
    # --brief (morning brief): a task that belongs to a project is a project
    # step, not a fragment -- rows already linked (or linked by the auto-link
    # just now) are dropped, so no "-> project?" is ever printed for them.
    # Instead each active project's single most-stalled open step (untouched
    # > 3 local days) is emitted once as a 'step' row:
    #   step <TAB> project <TAB> step title <TAB> days <TAB> block_id
    # (owner 2026-10-13: name a stalled in-flight step once, never list steps).
    argv, weekly = _pop_flag(argv, "--weekly")
    argv, retro = _pop_flag(argv, "--retro")
    argv, today_raw = _pop_opt(argv, "--today")
    argv, owning_agent = task_find_owning_agent(argv)
    suggest = "--suggest" in argv
    brief = "--brief" in argv
    conn = event_conn()
    try:
        import wait_resolution
        system_ids = retro_system_task_ids(conn) if retro else set()
        resolved = {r[0] for r in wait_resolution.open_waits(conn)
                    if wait_resolution.linked_evidence(conn, r)}
        rows = conn.execute(
            "SELECT e.id, e.title, e.updated_at, e.display_tz "
            "FROM timeblock e "
            "WHERE e.kind='task' AND e.settled_at IS NULL "
            "AND e.status='open' "
            "AND e.block_class IS NULL "
            "AND e.schedule_kind='untimed' "
            "AND e.start_at IS NULL "
            + ("AND e.project_id IS NULL " if brief
               and _timeblock_has_project_id(conn) else "") +
            "AND (? IS NULL OR instr(',' || ? || ',', ',' || e.owning_agent || ',') > 0) "
            "ORDER BY e.updated_at;", (owning_agent, owning_agent)).fetchall()
        projects = []
        if suggest:
            # Active projects only (status contains the in-progress marker).
            projects = [(r[0], r[1]) for r in project_list()
                        if r[2] and "진행" in r[2]]
        wrote = False
        for eid, title, upd, tz in rows:
            if eid in resolved:
                continue
            # A module/kit-created prompt is workflow state, not something the
            # owner experienced.  Other callers retain the historical list.
            if eid in system_ids:
                continue
            if brief and wait_resolution.subject(title):
                title = wait_resolution.question(sys.modules[__name__], title)
            if weekly:
                if not weekly_review_visible(conn, eid):
                    continue
                title = weekly_review_title(conn, eid, title)
            upd_d = str(_local_date_of(upd, tz or "Asia/Seoul")) if upd else ""
            if suggest:
                # Persist the silent auto-link (no-op on pre-027 DB / no match);
                # linked is the title actually stored, else fall back to the
                # read-only suggestion so the printed hint is never lost.
                linked = _autolink_project(conn, eid, title, projects)
                if linked is not None:
                    wrote = True
                if brief and linked is not None:
                    continue            # now a project step, not a fragment
                sug = linked if linked is not None else \
                    _suggest_project_title(title, projects)
                print(f"{eid}\t{title}\t{upd_d}\t{sug}")
            else:
                print(f"{eid}\t{title}\t{upd_d}")
        if wrote:
            conn.commit()
        if brief and _timeblock_has_project_id(conn):
            today_l = (datetime.date.fromisoformat(today_raw) if today_raw else
                       datetime.datetime.now(ZoneInfo("Asia/Seoul")).date())
            steps = conn.execute(
                "SELECT p.title, e.title, e.updated_at, e.display_tz, e.id "
                "FROM timeblock e JOIN projects p ON p.id = e.project_id "
                "WHERE e.kind='task' AND e.settled_at IS NULL "
                "AND e.status='open' AND e.block_class IS NULL "
                "AND e.start_at IS NULL "
                "AND p.status LIKE '%\uc9c4\ud589%' "
                "AND (? IS NULL OR instr(',' || ? || ',', ',' || e.owning_agent || ',') > 0) "
                "ORDER BY e.updated_at;", (owning_agent, owning_agent)).fetchall()
            seen = set()
            for ptitle, stitle, upd, tz, sid in steps:
                if sid in resolved or ptitle in seen or not upd:
                    continue
                if sid in system_ids:
                    continue
                days = (today_l - _local_date_of(upd, tz or "Asia/Seoul")).days
                if days > 3:
                    seen.add(ptitle)
                    question = wait_resolution.question(sys.modules[__name__], stitle)
                    print(f"step\t{ptitle}\t{stitle}\t{days}\t{sid}\t{question}")
    finally:
        conn.close()


def _suggest_project_title(task_title, projects):
    """Return the best-matching active project title for a task fragment, or ''
    when no confident match. Heuristic (read-only, no side effects):
      1. any project whose title shares a >=2-char token with the task title;
      2. rank by longest shared substring/token length; ties -> first.
    Deliberately conservative: the user confirms the map, so a miss (empty) is
    cheaper than a wrong auto-map. Tokenization is whitespace-based on both
    sides; punctuation is stripped from the edges of each token."""
    if not task_title or not projects:
        return ""
    def _toks(s):
        out = []
        for w in str(s).split():
            w = w.strip("()[]{}.,/-_·:;–—")
            if len(w) >= 2:
                out.append(w)
        return out
    t_toks = _toks(task_title)
    if not t_toks:
        return ""
    best_title = ""
    best_score = 0
    for _pid, ptitle in projects:
        p_toks = _toks(ptitle)
        score = 0
        for tt in t_toks:
            for pt in p_toks:
                if tt == pt:
                    score = max(score, len(tt) * 2)     # exact token match
                elif tt in pt or pt in tt:
                    score = max(score, min(len(tt), len(pt)))  # substring
        if score > best_score:
            best_score = score
            best_title = ptitle
    return best_title


def _timeblock_has_project_id(conn):
    """Feature-detect the timeblock.project_id column (migration 027) at runtime.
    The silent auto-link write path (task <-> project achievement axis) MUST call
    this and no-op when the column is absent, so the code is safe to sit in the
    live tree on a v25/v26 (pre-027) DB BEFORE the migration is applied. PRAGMA is
    an in-memory schema lookup (same precedent as _has_travel_columns). Returns
    False on any sqlite error (fail-closed -> pre-027 no-op semantics)."""
    try:
        cols = {r[1] for r in conn.execute("PRAGMA table_info(timeblock);")}
    except sqlite3.Error:
        return False
    return "project_id" in cols


def _autolink_project(conn, tb_id, task_title, projects):
    """SILENT AUTO-LINK: persist the best-matching active project onto a task
    block's project_id, no user prompt (ag-life-integration, owner-confirmed
    direction). Uses the same conservative heuristic as the read-time suggest
    (_suggest_project_title). Behavior contract:
      * column absent (pre-027 DB)      -> silent no-op, return None.
      * no confident project match      -> no-op, return None.
      * project_id already set          -> DO NOT overwrite, return existing.
      * confident match on an empty slot -> write project_id, return the title.
    Never raises for a missing column / missing match -- a link is a bonus, its
    absence must never break the read that triggered it. `projects` is the
    pre-filtered list of active (id, title) tuples the caller already built."""
    if not _timeblock_has_project_id(conn):
        return None
    sug = _suggest_project_title(task_title, projects)
    if not sug:
        return None
    # Map the suggested title back to its project id (first active match).
    pid = None
    for _pid, _ptitle in projects:
        if _ptitle == sug:
            pid = _pid
            break
    if pid is None:
        return None
    # measure-first: never clobber a link the user (or a prior pass) already set.
    cur = conn.execute(
        "SELECT project_id FROM timeblock WHERE id=?;", (tb_id,)).fetchone()
    if cur is None:
        return None
    if cur[0] is not None:
        # already linked -> report the existing link, no write.
        row = conn.execute(
            "SELECT title FROM projects WHERE id=?;", (cur[0],)).fetchone()
        return row[0] if row else None
    conn.execute(
        "UPDATE timeblock SET project_id=? WHERE id=?;", (pid, tb_id)) \
        if not _is_v32(conn) else conn.execute(
        "INSERT OR REPLACE INTO project_block(project_id, block_id) VALUES (?,?);",
        (pid, tb_id))
    return sug


def cli_tasks_by_project(argv):
    # tasks-by-project [--open] [--since <YYYY-MM-DD>] [--project <id|title>]
    #   (read side of the project axis: project_block direct links + the
    #   routine_def.project_id derived join, kit_life 2.24.0)
    # Group task blocks by their EFFECTIVE project: a direct project_block
    # link if one exists, else the project of the routine_def the occurrence
    # was materialized from (COALESCE(direct, routine-derived) -- DERIVED,
    # never stored at materialization time; a retired/re-pointed routine_def
    # never leaves a stale link behind). Output TSV cols:
    #   project_id  project_title  task_id  task_title  status  link_source
    # link_source is 'direct' (project_block row on this block) or 'routine'
    # (no direct link; reached the project only via the block's routine_def).
    # Rows with no linked project (direct or derived) are excluded entirely --
    # this verb is a JOIN surface, not a task listing.
    # --open: only open (unsettled) task blocks.
    # --since <date>: only blocks updated on/after that local date (without
    #   it this dumped the FULL history -- 1,730 rows on the live DB -- which
    #   is why nothing ever called it; --since is what makes it usable).
    # --project <id|title>: restrict to one project (same id-or-title
    #   resolution as task-add/appt-add --project; unresolvable is loud).
    # Feature-detects the project_id column: on a pre-027 DB it emits NOTHING
    # (clean no-op), so the surface just renders an empty section.
    open_only = "--open" in argv
    argv, since_raw = _pop_opt(argv, "--since")
    argv, project_raw = _pop_opt(argv, "--project")
    if since_raw is not None and not _DATE_RE.match(since_raw):
        _err(f"bad date format (want YYYY-MM-DD): {since_raw}")
    conn = event_conn()
    try:
        if not _timeblock_has_project_id(conn):
            return  # pre-027 DB: no linked column -> nothing to group, no-op.
        pid_filter = _resolve_project_id(conn, project_raw)
        where = ("WHERE e.kind='task' AND e.block_class IS NULL "
                 "AND COALESCE(e.project_id, rd.project_id) IS NOT NULL ")
        params = []
        if open_only:
            where += "AND e.settled_at IS NULL AND e.status='open' "
        if since_raw is not None:
            ws, _ = all_day_instants(since_raw)
            where += "AND e.updated_at >= ? "
            params.append(ws)
        if pid_filter is not None:
            where += "AND COALESCE(e.project_id, rd.project_id) = ? "
            params.append(pid_filter)
        rows = conn.execute(
            "SELECT COALESCE(e.project_id, rd.project_id), p.title, "
            "e.id, e.title, e.status, "
            "CASE WHEN e.project_id IS NOT NULL THEN 'direct' ELSE 'routine' END "
            "FROM timeblock e "
            "LEFT JOIN routine_def rd ON rd.recurrence_id = e.recurrence_id "
            "LEFT JOIN projects p ON p.id = COALESCE(e.project_id, rd.project_id) "
            + where +
            "ORDER BY COALESCE(e.project_id, rd.project_id), e.updated_at;",
            params).fetchall()
        for pid, ptitle, tid, ttitle, status, link_source in rows:
            print(f"{pid}\t{ptitle or '(none)'}\t{tid}\t{ttitle}\t{status}"
                  f"\t{link_source}")
    finally:
        conn.close()


def cli_task_done_between(argv):
    # task-done-between <from> <to> [--owning-agent <name>]
    #   (to = EXCLUSIVE; weekly-review window)
    # Same domain read-scope as task-find / task-overdue, closed at the same
    # time for a specific reason: the COMPLETED side of the leak is latent
    # only while the peer's blocks rarely get closed. Wiring their close
    # carrier turns a rare leak into a daily one ("done today" listing the
    # other domain's sessions). Measured before it shipped. Unset flag +
    # unset knob => byte-identical.
    argv, weekly = _pop_flag(argv, "--weekly")
    argv, owning_agent = task_find_owning_agent(argv)
    if len(argv) < 2 or not _DATE_RE.match(argv[0]) or not _DATE_RE.match(argv[1]):
        _err("사용법: kit_life.sh task-done-between <YYYY-MM-DD> <YYYY-MM-DD>")
    ws, _ = all_day_instants(argv[0])
    we, _ = all_day_instants(argv[1])
    conn = event_conn()
    try:
        rows = conn.execute(
            # DGN-579: trailing place name (11th col) via LEFT JOIN.
            "SELECT e.id, e.ulid, e.title, e.start_at, e.end_at, "
            "e.schedule_kind, e.display_tz, e.settled_outcome, e.settled_at, "
            "e.version, p.name FROM timeblock e "
            "LEFT JOIN place p ON p.id = e.place_id "
            "WHERE e.kind='task' AND e.settled_outcome='done' "
            "AND e.block_class IS NULL "  # DGN-274 4.4 (V7): weekly review
                                          # (done-between) stays uncontaminated
            "AND e.settled_at >= ? AND e.settled_at < ? "
            # Domain read-scope (see task_find_owning_agent). `? IS NULL`
            # keeps an unscoped caller byte-identical.
            "AND (? IS NULL OR instr(',' || ? || ',', ',' || e.owning_agent || ',') > 0) "
            "ORDER BY e.settled_at;",
            (ws, we, owning_agent, owning_agent)).fetchall()
        for row in rows:
            if weekly:
                if not weekly_review_visible(conn, row[0]):
                    continue
                row = list(row)
                row[2] = weekly_review_title(conn, row[0], row[2])
            done_d = str(_local_date_of(row[8], row[6] or "Asia/Seoul"))
            # DGN-579: place appended as a NEW 5th TAB field (raw name or
            # empty); first 4 fields stay byte-identical.
            print(f"{row[0]}\t{row[2]}\t{done_d}\tdone\t{row[10] or ''}")
    finally:
        conn.close()


def cli_event_window(argv):
    argv, weekly = _pop_flag(argv, "--weekly")
    # event-window <from_utc> <to_utc> [kind] -- remind.sh read lane (04b).
    if len(argv) < 2:
        _err("사용법: kit_life.sh event-window <from_utc> <to_utc> [kind]")
    try:
        canonical(argv[0])
        canonical(argv[1])
    except ValueError as e:
        _err(str(e))
    kind = argv[2] if len(argv) > 2 and argv[2] else None
    conn = event_conn()
    try:
        travel_core.attendance_touch(sys.modules[__name__], conn, since=argv[0], until=argv[1])
        # DGN-273: notify columns appended as cols 7-8 (existing consumers
        # read cols 1-6 by position and are unaffected).
        # DGN-579: place name appended as trailing col 9 (LEFT JOIN; existing
        # positional consumers reading cols 1-8 stay unaffected).
        # 052: people appended as trailing col 10 (retro/brief needs the
        # complete schedule surface; existing positional consumers reading
        # cols 1-9 stay unaffected).
        # retro-read-paths: retro_line appended as trailing col 11 (existing
        # positional consumers reading cols 1-10 stay unaffected).
        q = ("SELECT e.id, e.ulid, e.kind, e.title, e.start_at, e.end_at, "
             "e.status, e.notify_policy, e.notify_lead_min, p.name, "
             "e.retro_line "
             "FROM timeblock e "
             "LEFT JOIN place p ON p.id = e.place_id "
             "WHERE e.settled_at IS NULL AND e.schedule_kind='timed' "
             "AND e.start_at >= ? AND e.start_at < ? ")
        params = [argv[0], argv[1]]
        if kind:
            q += "AND e.kind=? "
            params.append(kind)
        for eid, u, k, t, sa, ea, st, np, nl, pn, rl in conn.execute(
                q + "ORDER BY e.start_at;", params).fetchall():
            if weekly and not weekly_review_visible(conn, eid):
                continue
            if weekly:
                t = weekly_review_title(conn, eid, t)
                rl = " ".join(str(rl or "").split())
            people = _event_people_names(conn, eid)
            related = _related_shopping(conn, t, eid)
            extra = "\t" + " | ".join(related) if related else ""
            print(f"{u}\t{k}\t{t}\t{sa}\t{ea or ''}\t{st}"
                  f"\t{np or ''}\t{'' if nl is None else nl}\t{pn or ''}"
                  f"\t{people}\t{rl or ''}" + extra)
    finally:
        conn.close()


def cli_event_retro_set(argv):
    # event-retro-set <event_id|event_ulid> <line>
    if len(argv) != 2 or not argv[0] or not str(argv[1]).strip():
        _err("usage: kit_life.sh event-retro-set <event_id|event_ulid> <line>")

    conn = event_conn()
    try:
        before = conn.execute("SELECT retro_line FROM timeblock WHERE id=? OR ulid=?",
                              (argv[0], argv[0])).fetchone()
        try:
            row = event_retro_set(conn, argv[0], argv[1])
        except ValueError as e:
            _err(str(e))
        if row is None:
            _err("event-retro-set: event not found: %s" % argv[0])
        print("%s\t%s\t%s" % row)
        day = conn.execute("SELECT rec_date, start_at, display_tz FROM timeblock "
                           "WHERE id=?", (row[0],)).fetchone()
        activity = day[0] or _activity_day(day[1], day[2] or "Asia/Seoul")
        if before and before[0] == row[2]:
            _capture_open_today(conn)
        else:
            _capture_open_today(conn, "event-retro-set", row[0], activity, "block")
    finally:
        conn.close()


