def cli_map_region_set(argv):
    # map-region-set <CC> <provider[,provider]|none> [--label <name>]
    #                [--source <s>] [--box lat_min,lat_max,lng_min,lng_max]
    #   069: a region's local map apps, looked up (MAP_REGION_NEEDED). Only
    #   providers the kit can link are stored; the rest are reported.
    argv = list(argv)
    argv, label = _pop_opt(argv, "--label")
    argv, source = _pop_opt(argv, "--source")
    argv, box_raw = _pop_opt(argv, "--box")
    usage = ("usage: kit_life.sh map-region-set <CC> "
             "<provider[,provider]|none> [--label <name>] [--source <s>] "
             "[--box lat_min,lat_max,lng_min,lng_max]  (linkable: %s)"
             % ",".join(sorted(_MAP_LINK_BUILDERS)))
    if len(argv) != 2:
        _err(usage)
    box = None
    if box_raw:
        try:
            box = [float(x) for x in box_raw.split(",")]
        except ValueError:
            box = None
        if box is None or len(box) != 4:
            _err(usage)
    conn = get_conn()
    try:
        res = map_region_set(conn, argv[0], argv[1], label=label,
                             source=source or "agent_lookup", box=box)
    finally:
        conn.close()
    if res["result"] != "applied":
        print("map-region\t%s" % res["result"])
        sys.exit(3)
    print("map-region\tapplied\t%s\t%s" % (
        res["region"], ",".join(res["providers"]) or "none"))
