def cli_map_provider(argv):
    # map-provider [--json]   READ ONLY: every known region, its local
    #   providers, the user's pick (or the Google default) and whether the
    #   one-time question was asked.
    argv, as_json = _pop_flag(list(argv), "--json")
    if argv:
        _err("usage: kit_life.sh map-provider [--json]")
    conn = get_conn()
    try:
        out = []
        if _map_region_ready(conn):
            for (reg,) in conn.execute(
                    "SELECT region FROM map_region ORDER BY region;"):
                out.append({
                    "region": reg, "label": map_region_label(conn, reg),
                    "local": map_region_local(conn, reg),
                    "pick": map_provider_pick(conn, reg),
                    "uses": map_providers_for_leg(conn, reg),
                    "asked": _config_stored(
                        conn, _MAP_PROVIDER_ASKED_KEY % reg) is not None})
    finally:
        conn.close()
    if as_json:
        print(json.dumps({"default": MAP_PROVIDER_DEFAULT, "regions": out},
                         ensure_ascii=False))
        return
    print("default\t%s" % MAP_PROVIDER_DEFAULT)
    for r in out:
        print("%s\t%s\tlocal=%s\tuses=%s%s" % (
            r["region"], r["label"], ",".join(r["local"]) or "-",
            ",".join(r["uses"]), "" if r["pick"] else "\t(default)"))


