def cli_place_address_ask(argv):
    # place-address-ask <place>   the owner was asked for this place's
    #   address (NEEDS_ADDRESS from place-coord-backfill.sh) -- recorded so
    #   it is asked ONCE. "place-address-ask<TAB>applied|already<TAB><id>";
    #   exit 3 not_found.
    if len(argv) != 1:
        _err("usage: kit_life.sh place-address-ask <place>")
    conn = get_conn()
    try:
        res = place_address_ask_mark(conn, argv[0])
    finally:
        conn.close()
    if res["result"] == "not_found":
        print("place-address-ask\tnot_found")
        sys.exit(3)
    print("place-address-ask\t%s\t%s" % (res["result"], res["place_id"]))


