def _place_hours_week_lines(doc):
    """'mon<TAB>09:30-18:30<TAB>13:00-14:00' per stored day (+ holiday)."""
    if doc.get("none"):
        return ["none"]
    out = []
    days = doc.get("days") or {}
    for d in _HOURS_DAYS + ("holiday",):
        v = doc.get("holiday") if d == "holiday" else days.get(d)
        if v is None:
            continue
        if isinstance(v, dict):
            out.append("%s\t%s-%s\t%s" % (d, v["open"], v["close"],
                                          _hours_breaks_text(v)))
        else:
            out.append("%s\t%s" % (d, v))
    return out


def _place_hours_text(place, date, day):
    """One reply-ready sentence for a known day (kit bundle copy), or ''."""
    def tx(key, fb):
        return _i18n("place.hours." + key, fb)
    try:
        wds = _day_i18n("day.card.weekdays").split(",")
        md = "%d/%d" % (date.month, date.day)
        parts = dict(name=place.get("name") or "", md=md,
                     wd=wds[date.weekday()])
        if day["state"] == "closed":
            key = "closed_holiday" if day.get("why") == "holiday" else "closed"
            return tx(key, "{name} {md}({wd}) closed").format(**parts)
        if day["state"] != "open":
            return ""
        brs = ""
        if day.get("breaks"):
            brs = tx("break", " (break {ranges})").format(ranges=", ".join(
                "%s~%s" % tuple(b) for b in day["breaks"]))
        return tx("open", "{name} {md}({wd}) {open}~{close}{breaks}, "
                  "closes {close}").format(open=day["open"],
                                           close=day["close"], breaks=brs,
                                           **parts)
    except (KeyError, IndexError, ValueError, AttributeError):
        return ""


def cli_place_hours_set(argv):
    # place-hours-set <place> <json|text> [--source <url>] [--fetched <date>]
    #   067: store a place's opening hours, upsert (one row per place).
    #   Written by the agent after PLACE_HOURS_NEEDED (it looked the hours up
    #   itself), or when the owner states them (no --source). <place> = id,
    #   ulid or exact name. Hours: see place_hours_parse; 'none' = the place
    #   keeps no hours. Prints "place-hours-set<TAB>applied<TAB><id><TAB>
    #   <name><TAB><fetched>" and the stored week, one line per day; exit 3
    #   not_found / bad_hours / schema_not_ready (nothing written).
    argv, src = _pop_opt(list(argv), "--source")
    argv, fetched = _pop_opt(argv, "--fetched")
    if len(argv) != 2:
        _err("usage: kit_life.sh place-hours-set <place> <json|text> "
             "[--source <url>] [--fetched YYYY-MM-DD]")
    conn = get_conn()
    try:
        res = place_hours_set(conn, argv[0], argv[1], source_url=src,
                              fetched_on=fetched)
    finally:
        conn.close()
    if res["result"] != "applied":
        print("place-hours-set\t%s%s" % (
            res["result"], ("\t" + res["error"]) if res.get("error") else ""))
        sys.exit(3)
    print("place-hours-set\tapplied\t%s\t%s\t%s" % (
        res["place_id"], _travel_signal_field(res["name"] or ""),
        res["fetched_on"]))
    for line in _place_hours_week_lines(res["hours"]):
        print(line)


def cli_place_hours(argv):
    # place-hours <place> [YYYY-MM-DD] [--now <UTC ISO>] [--json]
    #   067, READ ONLY: the place's hours on that local date (default today):
    #   place-hours<TAB><id><TAB><name><TAB><date><TAB>OPEN|CLOSED|UNKNOWN|
    #     NO_HOURS<TAB><open|-><TAB><close|-><TAB><breaks|why><TAB><source|->
    #     <TAB><fetched|->
    #   OPEN adds PLACE_HOURS_DEFAULT<TAB>-<TAB><HH:MM> (a no-time visit's
    #   start inside the hours, not before now on today) when one fits, and
    #   PLACE_HOURS_TEXT<TAB><sentence> (the reply copy, states the closing
    #   time). No hours on file or older than the stale window ->
    #   PLACE_HOURS_NEEDED + the relay: look them up, place-hours-set, re-ask.
    #   Exit 0; 3 = no such place.
    argv, now = _pop_opt(list(argv), "--now")
    argv, as_json = _pop_flag(argv, "--json")
    usage = ("usage: kit_life.sh place-hours <place> [YYYY-MM-DD] "
             "[--now <UTC ISO>] [--json]")
    if len(argv) not in (1, 2):
        _err(usage)
    try:
        if now:
            canonical(now)
        date = (datetime.date.fromisoformat(argv[1]) if len(argv) == 2
                else _place_hours_today(now))
    except ValueError as e:
        _err("place-hours: %s\n%s" % (e, usage))
    conn = get_conn()
    try:
        place = travel_place_get(conn, argv[0])
        if place is None:
            print("place-hours\tnot_found")
            sys.exit(3)
        day = place_hours_on(conn, place["id"], date, now=now)
        default = place_hours_default_start(day, date, now=now)
        needed = bool(day.get("stale"))
        if as_json:
            out = dict(day, place_id=place["id"], name=place.get("name"),
                       date=date.isoformat(), default_start=default,
                       needed=needed)
            out["breaks"] = [list(b) for b in out.get("breaks") or ()]
            print(json.dumps(out, ensure_ascii=False, sort_keys=True))
            return
        st = "NO_HOURS" if day["state"] == "none" else None
        line = _place_hours_open_line("place-hours", place["id"], place,
                                      date, day).split("\t")
        line = line[:1] + line[2:]              # no block key on the verb
        if st:
            line[4] = st
        print("\t".join(line + [_travel_signal_field(
            day.get("source_url") or "-"), day.get("fetched_on") or "-"]))
        if default:
            print("%s\t-\t%s" % (PLACE_HOURS_DEFAULT, default))
        text = _place_hours_text(place, date, day)
        if text:
            print("PLACE_HOURS_TEXT\t" + text)
        if needed:
            print(_place_hours_needed_line(conn, place))
            print("PLACE_HOURS_RELAY " + PLACE_HOURS_RELAY)
    finally:
        conn.close()


def cli_travel_edge_add(argv):
    # travel-edge-add <from_place> <to_place> <minutes> [prep_min] [--clear-prep]
    #   DGN-623: register a one-way movement duration for an ORDERED place pair
    #   (spatial awareness). The skill calls this after the user answers
    #   "<from>에서 <to>까지 편도 몇 분?"; then appt-travel-attach re-derives.
    #   from/to accept a place id, ulid, or exact name (travel_place_get).
    #   prep_min OMITTED = the stored prep is left alone (T1: the minutes-only
    #   form is what travel-resolve.sh and the skills call, and it used to wipe
    #   the pair's declared prep). Clearing is a separate explicit surface
    #   (--clear-prep), never an overload of the optional positional.
    argv, clear_prep = _pop_flag(list(argv), "--clear-prep")
    if len(argv) < 3:
        _err("usage: kit_life.sh travel-edge-add <from_place> <to_place> "
             "<minutes> [prep_min] [--clear-prep]")
    conn = event_conn()
    try:
        pf = travel_place_get(conn, argv[0])
        pt = travel_place_get(conn, argv[1])
        if pf is None:
            _err("travel-edge-add: from place %r not found" % argv[0])
        if pt is None:
            _err("travel-edge-add: to place %r not found" % argv[1])
        if not str(argv[2]).lstrip("-").isdigit():
            _err("travel-edge-add: minutes must be an integer")
        prep = None if clear_prep else TRAVEL_PREP_KEEP
        if len(argv) >= 4 and argv[3] != "":
            if clear_prep:
                _err("travel-edge-add: prep_min and --clear-prep contradict "
                     "each other -- pass one")
            if not str(argv[3]).lstrip("-").isdigit():
                _err("travel-edge-add: prep_min must be an integer")
            prep = int(argv[3])
        try:
            e = travel_edge_add(conn, pf["id"], pt["id"], int(argv[2]),
                                prep_min=prep)
        except ValueError as ex:
            _err(str(ex))
        print("%s\t%s->%s\t%s\t%s" % (
            e["id"], pf["name"], pt["name"], e["minutes"],
            e["prep_min"] if e["prep_min"] is not None else ""))
        # 2026-10-15: a def left at no_duration attaches as soon as its
        # home<->place duration is known (one line per def attempted).
        attached = _travel_autoattach_pending_defs(
            conn, place_ids=(pf["id"], pt["id"]))
        for def_id, st in attached:
            print("routine-travel-attach\t%s\t%s" % (def_id, st))
        # 2026-10-15 15:07 live: home->gym attached the gym rules while
        # gym->home was unknown (after leg left to derive-time, correct), but
        # adding gym->home re-derived nothing -- the return legs waited for a
        # nightly pass and were baked by hand. The rules at either end of
        # the pair re-derive now (one line per rule, its effective return).
        for rid, after in _travel_edge_refresh_rules(
                conn, (pf["id"], pt["id"])):
            print("travel-refresh\t%s\tafter=%s" % (
                rid, "-" if after is None else after))
    finally:
        conn.close()


def cli_travel_edge_retract(argv):
    # Expire the current ordered-pair measures; history remains auditable.
    if len(argv) != 2:
        _err("usage: kit_life.sh travel-edge-retract <from_place> <to_place>")
    conn = event_conn()
    try:
        pf, pt = travel_place_get(conn, argv[0]), travel_place_get(conn, argv[1])
        if pf is None or pt is None:
            _err("travel-edge-retract: both places must exist")
        stamp = now_utc()
        conn.execute('BEGIN IMMEDIATE')
        lid = _travel_v32_link_id(conn, pf['id'], pt['id'], create=False)
        n = 0
        if lid is not None:
            n = conn.execute('SELECT count(*) FROM measure WHERE place_link_id=? '
                             "AND metric IN (?,?) AND basis='actual' "
                             'AND (valid_until IS NULL OR valid_until>?)',
                             (lid, TRAVEL_METRIC_MIN, TRAVEL_METRIC_PREP, stamp)).fetchone()[0]
            for metric in (TRAVEL_METRIC_MIN, TRAVEL_METRIC_PREP):
                _travel_v32_set(conn, lid, metric, None, now=stamp)
        conn.commit()
        print("travel-edge\tretracted\t%s->%s\tmeasures=%s" %
              (pf["name"], pt["name"], n))
        for rid, after in _travel_edge_refresh_rules(conn, (pf["id"], pt["id"])):
            print("travel-refresh\t%s\tafter=%s" % (rid, "-" if after is None else after))
    finally:
        conn.close()


def _travel_edge_refresh_rules(conn, place_ids):
    """Re-derive every ACTIVE rule bound to one of `place_ids` whose legs
    come from the edges (before_src or after_src 'place'): a newly learned
    duration reaches the move / return legs at once instead of at the next
    nightly pass. Returns [(rule_id, effective after minutes or None for
    the next live instance)]. Best-effort: never raises."""
    out = []
    try:
        ids = [int(p) for p in place_ids if p is not None]
        if not ids:
            return out
        rows = conn.execute(
            "SELECT id FROM travel_rule WHERE status='active' AND place_id "
            "IN (%s) AND (before_src='place' OR after_src='place') "
            "ORDER BY id;" % ",".join("?" * len(ids)), ids).fetchall()
    except sqlite3.Error:
        return out
    for (rid,) in rows:
        try:
            rule = travel_rule_get(conn, rid)
            if rule is None:
                continue
            travel_refresh_rule(conn, None, rule)
            after = None
            anchor = _travel_rule_next_anchor(conn, rule)
            if anchor is not None:
                exp = _travel_expected_after(conn, rule, anchor)
                if exp is not None:
                    after = _iso_diff_min(exp[1], exp[0])
            out.append((rid, after))
        except Exception:  # noqa: BLE001 -- the edge is stored either way
            continue
    return out


def _travel_rule_next_anchor(conn, rule):
    """The rule's next live anchor row (a def's earliest unsettled
    instance, or the event itself), or None."""
    if rule.get("anchor_type") == "def":
        d = routine_def_get(conn, rule["anchor_ulid"])
        if d is None or not d.get("recurrence_id"):
            return None
        return _travel_row(
            conn, "SELECT * FROM timeblock WHERE recurrence_id=? AND "
            "settled_at IS NULL AND block_class IS NULL AND start_at >= ? "
            "ORDER BY start_at LIMIT 1;", (d["recurrence_id"], now_utc()))
    return _travel_row(conn, "SELECT * FROM timeblock WHERE ulid=? AND "
                       "settled_at IS NULL;", (rule["anchor_ulid"],))


