_SPEND_VALID_SCOPE = {'personal', 'business', 'unknown'}
# Intake is a domain write channel; detailed channel/provenance stays in intake.
# Existing chat and batch callers retain their source values.
_SPEND_VALID_SOURCE = {'chat', 'batch', 'intake'}
# DGN-564: kind value set; no DB CHECK (source precedent), SDK enforces here.
_SPEND_VALID_KIND = {'expense', 'income'}


def cli_spend_add(argv):
    # spend-add <date> <amount> <name> [category] [method] [scope] [note]
    #           [--fixed 0|1] [--new] [--source chat|batch|intake]
    #           [--kind expense|income]
    # is_fixed omitted -> inherit category is_fixed_default.
    argv, experience_id = _pop_opt(argv, '--experience')
    argv, force_new = _pop_flag(argv, '--new')
    argv, fixed_val = _pop_opt(argv, '--fixed')
    argv, source_val = _pop_opt(argv, '--source')
    argv, kind_val = _pop_opt(argv, '--kind')
    _u = ("사용법: kit_life.sh spend-add <date> <amount> <name> "
          "[category] [method] [scope] [note] [--fixed 0|1] [--new] "
          "[--source chat|batch|intake] [--kind expense|income]")
    if len(argv) < 3 or not argv[0] or not argv[1] or not argv[2]:
        _err(_u)
    date, amount_str, name = argv[0], argv[1], argv[2]
    try:
        amount = int(amount_str)
    except ValueError:
        _err(f"amount는 정수(KRW)여야 함: {amount_str}")
    g = lambda i: argv[i] if i < len(argv) else None
    category = g(3)
    method = g(4)
    scope = g(5) or 'personal'
    note = g(6)
    if scope not in _SPEND_VALID_SCOPE:
        _err(f"scope 값 오류: {scope} (personal/business/unknown)")
    is_fixed = None
    if fixed_val is not None:
        if fixed_val not in ('0', '1'):
            _err("--fixed 값은 0 또는 1이어야 함")
        is_fixed = int(fixed_val)
    source = source_val or 'chat'
    if source not in _SPEND_VALID_SOURCE:
        _err(f"source 값 오류: {source}")
    kind = kind_val or 'expense'
    if kind not in _SPEND_VALID_KIND:
        _err(f"kind 값 오류: {kind} (expense/income)")
    conn = get_conn()
    try:
        if not force_new:
            # DGN-231 reconcile-before-write: match key = (date, amount, kind).
            # DGN-564: same (date, amount) but different kind is NOT a dup.
            matches = conn.execute(
                "SELECT e.id, e.name, e.amount, COALESCE(c.display_name, c.name,'') "
                "FROM spend_entry e "
                "LEFT JOIN spend_category c ON c.id = e.category_id "
                "WHERE e.date=? AND e.amount=? AND e.kind=?;",
                (date, amount, kind)).fetchall()
            if matches:
                print(f"EXISTS {len(matches)}")
                for eid, ename, eamt, ecat in matches:
                    print(f"{eid}\t{ename}\t{eamt}\t{ecat}")
                sys.exit(EXISTS_CODE)
        nid = spend_add(date, amount, name, category=category, method=method,
                        scope=scope, note=note, is_fixed=is_fixed,
                        source=source, kind=kind, conn=conn, experience_id=experience_id)
        row = conn.execute(
            "SELECT e.id, e.name, e.amount, COALESCE(c.display_name, c.name,'') "
            "FROM spend_entry e "
            "LEFT JOIN spend_category c ON c.id = e.category_id "
            "WHERE e.id=?;", (nid,)).fetchone()
        print(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[3]}")
        import shop_payment
        for line in shop_payment.notices(sys.modules[__name__], conn, nid):
            print(line)
        conn.commit()
        _capture_open_today(conn, "spend-add", nid,
                            conn.execute("SELECT date FROM " + "spend_entry" +
                                         " WHERE id=?", (nid,)).fetchone()[0], "spend_entry")
    finally:
        conn.close()


