def _pay_method_by_ref(conn, ref):
    """결제수단 ref 해석: 전부 숫자면 id, 아니면 name. (id, name, kind) 또는 None."""
    if ref is None:
        return None
    s = str(ref).strip()
    if s == '':
        return None
    if s.isdigit():
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE id=?;",
            (int(s),)).fetchone()
    else:
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE name=?;",
            (s,)).fetchone()
    return row  # (id, name, kind) or None


def cli_spend_category_list(argv):
    # spend-category-list [--since YYYY-MM-DD] [--sum] [--json] -- the active
    # expense categories, most spent first since --since (personal rows; ties
    # and no spend: the category's own sort). --sum: one line instead, every
    # personal expense since --since, categorized or not. Read only. Ledger
    # onboarding offers its category and budget buttons from these records.
    argv, as_json = _pop_flag(list(argv), "--json")
    argv, as_sum = _pop_flag(argv, "--sum")
    argv, since = _pop_opt(argv, "--since")
    if argv or (since is not None and not _DATE_RE.match(since)):
        _err("usage: kit_life.sh spend-category-list [--since YYYY-MM-DD] "
             "[--sum] [--json]")
    conn = get_conn()
    try:
        if as_sum:
            total, count = conn.execute(
                f"SELECT COALESCE(SUM(amount-COALESCE((SELECT r.amount FROM v_ledger_reimbursement r WHERE r.spend_id=spend_entry.id),0)-{_review_reimbursement_sql('spend_entry')}), 0), COUNT(*) FROM spend_entry "
                "WHERE kind = 'expense' AND scope = 'personal' AND date >= ?;",
                (since or '9999-12-31',)).fetchone()
            print(json.dumps({"since": since, "total": total, "count": count})
                  if as_json else "total\t%d\t%d" % (total, count))
            return
        rows = conn.execute(
            "SELECT c.id, c.name, COALESCE(c.display_name, c.name), "
            f"COALESCE(SUM(e.amount-COALESCE((SELECT r.amount FROM v_ledger_reimbursement r WHERE r.spend_id=e.id),0)-{_review_reimbursement_sql('e')}), 0), COUNT(e.id) FROM spend_category c "
            "LEFT JOIN spend_entry e ON e.category_id = c.id "
            "AND e.kind = 'expense' AND e.scope = 'personal' AND e.date >= ? "
            "WHERE c.active = 1 AND c.kind = 'expense' GROUP BY c.id "
            "ORDER BY 4 DESC, c.sort, c.id;", (since or '9999-12-31',)
        ).fetchall()
    finally:
        conn.close()
    out = [{"id": r[0], "key": r[1], "label": r[2], "total": r[3],
            "count": r[4]} for r in rows]
    if as_json:
        print(json.dumps(out, ensure_ascii=False))
        return
    for r in out:
        print("%d\t%s\t%s\t%d\t%d" % (r["id"], r["key"], r["label"],
                                      r["total"], r["count"]))


def cli_spend_category_rekey(argv):
    # spend-category-rekey [--dry-run] -- the rows the old fallback keyed
    # 'cat' / 'cat_<n>' get the key their label now derives (2.46.0-dev.2).
    # Ids are untouched (every reference is by id); idempotent.
    argv, dry = _pop_flag(list(argv), "--dry-run")
    conn = get_conn()
    try:
        moved = spend_category_rekey(conn, apply=not dry)
        if not dry:
            conn.commit()
    finally:
        conn.close()
    for cid, old, new in moved:
        print("%s\t%d\t%s\t%s" % ("would_rekey" if dry else "rekeyed",
                                   cid, old, new))
    print("%s\t%d" % ("dry-run" if dry else "applied", len(moved)))


def _method_entity_accrue(conn, name):
    """2.34.0, intake port (design A2-2, ledger pack gap G6): the payment instrument's
    entity + label, find-first, in the caller's transaction.  Resolution is
    the 039 rule (_spend_entity_id: label(namespace='entity').display == the
    method name, exactly one active entity), so a card registered here
    resolves for spend-add, intake confirmation and every crossing view.

    Returns (status, entity_id):
      ('found', id)      a label already names exactly one active entity
      ('created', id)    no label named it: entity + ko label inserted
      ('ambiguous', None) several entities carry that label -- nothing written
      ('inactive', None)  the one labelled entity is dormant/gone -- nothing
                          written (reviving a retired instrument is the
                          owner's call, not a side effect of method-add)
    The token/ulid are ASCII and derived from the name (a Korean card name
    has no honest transliteration), so re-adding the same name after its
    label was removed finds the same entity instead of minting a twin."""
    m = (name or '').strip()
    if not m:
        return ('ambiguous', None)
    hits = conn.execute(
        "SELECT DISTINCT e.id, e.status FROM entity e "
        "JOIN label l ON l.namespace='entity' AND l.token=e.token "
        "WHERE l.display=?;", (m,)).fetchall()
    if len(hits) > 1:
        return ('ambiguous', None)
    if len(hits) == 1:
        return ('found', hits[0][0]) if hits[0][1] == 'active' \
            else ('inactive', None)
    digest = hashlib.sha256(m.encode('utf-8')).hexdigest()[:12]
    token = 'pay_method_' + digest
    ulid = 'x-ent-pm-' + digest
    row = conn.execute("SELECT id, status FROM entity WHERE ulid=?;",
                       (ulid,)).fetchone()
    if row is None:
        eid = conn.execute(
            "INSERT INTO entity(ulid, token, fungible, origin, status) "
            "VALUES (?,?,0,'user','active');", (ulid, token)).lastrowid
    elif row[1] != 'active':
        return ('inactive', None)
    else:
        eid = row[0]
    conn.execute(
        "INSERT OR IGNORE INTO label(namespace, token, lang, display) "
        "VALUES ('entity', ?, 'ko', ?);", (token, m))
    return ('created', eid)


def method_add(name, kind, aliases=None, billing_day=None, link=None,
               conn=None, with_entity=False):
    """결제수단 find-first/upsert(D3). name UNIQUE 기준: 있으면 기존 행 반환(중복
    생성 금지), 없으면 신규. 반환: (id, name, kind).

    kind 검증/체크카드-링크 강제(2026-07-27 convention)는 CLI 계층에서 수행하며,
    core 는 이미 검증된 값을 받는다. link=계정 ref -> linked_account_id.

    2.34.0: 같은 트랜잭션에서 entity + label 을 find-first 로 붙인다
    (_method_entity_accrue). 기존 수단(2.34 이전 등록, entity 없음)도 다시
    method-add 하면 붙는다. with_entity=True 면 (id, name, kind, status,
    entity_id) 를 반환한다."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        linked_id = None
        if link is not None:
            lrow = _pay_method_by_ref(conn, link)
            linked_id = lrow[0] if lrow else None
        existing = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE name=?;",
            (name,)).fetchone()
        if existing:
            row = existing  # find-first: 중복 생성 금지
        else:
            cur = conn.execute(
                "INSERT INTO pay_method (name, kind, aliases, billing_day, "
                "linked_account_id) VALUES (?,?,?,?,?);",
                (name, kind, _txt(aliases), billing_day, linked_id))
            row = conn.execute(
                "SELECT id, name, kind FROM pay_method WHERE id=?;",
                (cur.lastrowid,)).fetchone()
        status, eid = _method_entity_accrue(conn, row[1])
        conn.commit()
        return tuple(row) + (status, eid) if with_entity else row
    finally:
        if own:
            conn.close()


def method_list(conn=None):
    """전 결제수단 목록. 반환: (id, name, kind, billing_day, linked_name) 리스트."""
    own = conn is None
