_METHOD_UPD_COLS = {'name', 'kind', 'aliases', 'billing_day',
                    'linked_account_id'}


def method_upd(mid, fields, conn=None):
    """결제수단 부분 갱신. 갱신 후 (id, name, kind, billing_day, linked_account_id)
    반환(없으면 None). 수정 불가 컬럼은 ValueError."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sets, vals = [], []
        for col, raw in fields.items():
            if col not in _METHOD_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'kind' and raw not in _PAY_METHOD_KINDS:
                raise ValueError(
                    f"kind 값 오류: {raw} "
                    f"({'|'.join(sorted(_PAY_METHOD_KINDS))})")
            if col == 'billing_day':
                sets.append(f"{col}=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            elif col == 'linked_account_id':
                sets.append(f"{col}=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            elif col == 'aliases':
                sets.append(f"{col}=?")
                vals.append(_txt(raw))
            else:
                sets.append(f"{col}=?")
                vals.append(raw)
        if not sets:
            raise ValueError("갱신할 필드 없음")
        vals.append(int(mid))
        conn.execute(
            f"UPDATE pay_method SET {', '.join(sets)} WHERE id=?;", vals)
        conn.commit()
        return conn.execute(
            "SELECT id, name, kind, billing_day, linked_account_id "
            "FROM pay_method WHERE id=?;", (int(mid),)).fetchone()
    finally:
        if own:
            conn.close()


def method_link(card_ref, account_ref, conn=None):
    """카드의 linked_account_id 를 결제계정으로 설정. 반환: (card_id, card_name,
    account_id, account_name) 또는 None(카드/계정 미해석)."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        card = _pay_method_by_ref(conn, card_ref)
        acct = _pay_method_by_ref(conn, account_ref)
        if card is None or acct is None:
            return None
        conn.execute(
            "UPDATE pay_method SET linked_account_id=? WHERE id=?;",
            (acct[0], card[0]))
        conn.commit()
        return (card[0], card[1], acct[0], acct[1])
    finally:
        if own:
            conn.close()


def _guard_row(conn, key, scope='global'):
    """ledger_guard 한 행 조회. 반환: (guard_key, scope, value, unit, enforcement,
    inviolable) 또는 None. 가드 임계값은 코드가 아닌 이 행에서 읽는다(D2/D5)."""
    return conn.execute(
        "SELECT guard_key, scope, value, unit, enforcement, inviolable "
        "FROM ledger_guard WHERE guard_key=? AND scope=?;",
        (key, scope)).fetchone()


class PaylineGuardBlock(Exception):
    """auto_entry_enabled(block) 위반: auto 쓰기가 가드로 차단됨. 행 미생성."""


class PaylineGuardHold(Exception):
    """entry_amount_ceiling(hold) 초과: --confirm 없으면 보류. 행 미생성."""
    def __init__(self, amount, ceiling):
        self.amount = amount
        self.ceiling = ceiling
        super().__init__(
            f"금액 {amount:,}원이 확인 임계 {ceiling:,}원을 초과합니다. "
            f"확인 후 --confirm 으로 진행하세요.")


def fixed_add(name, amount, category=None, next_due=None, cycle='monthly',
              pay_mode=None, method=None, direction='expense', auto_entry=0,
              source='interview', confirm=False, conn=None):
    """고정비/정기수입 한 건 기록(direction 통합). 새 행 id 반환.

    가드 통합(D2/D5, 임계값은 ledger_guard 에서 읽음):
    - auto_entry_enabled(block): auto_entry=1 요청인데 가드 value=0 이면
      PaylineGuardBlock (행 미생성).
    - entry_amount_ceiling(hold): amount > 가드 value 이면 confirm=False 시
      PaylineGuardHold (행 미생성). confirm=True 면 진행.
    검증(direction/source/auto/amount)은 CLI 계층에서 수행, core 는 게이트만."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        amount = int(amount)
        # 가드 읽기 (하드코딩 금지)
        g_auto = _guard_row(conn, 'auto_entry_enabled')
        if int(auto_entry) == 1 and g_auto is not None and \
                (g_auto[2] is None or int(g_auto[2]) == 0):
            raise PaylineGuardBlock(
                "auto_entry_enabled 가드가 꺼져 있어 자동입력을 차단합니다. "
                "guard-set auto_entry_enabled 1 로 활성화 후 다시 시도하세요.")
        g_ceil = _guard_row(conn, 'entry_amount_ceiling')
        if g_ceil is not None and g_ceil[2] is not None and \
                amount > int(g_ceil[2]) and not confirm:
            raise PaylineGuardHold(amount, int(g_ceil[2]))
        cid = spend_category_get_or_create(conn, category) if category else None
        mrow = _pay_method_by_ref(conn, method) if method else None
        method_id = mrow[0] if mrow else None
        if pay_mode not in (None, '', 'auto', 'manual'):
            raise ValueError('pay_mode must be auto, manual or empty (unknown)')
        cur = conn.execute(
            "INSERT INTO fixed_cost "
            "(name, amount, category_id, next_due, cycle, pay_mode, method_id, "
            "direction, auto_entry, source, pay_mode_source) VALUES (?,?,?,?,?,?,?,?,?,?,?);",
            (name, amount, cid, _txt(next_due), cycle, _txt(pay_mode),
             method_id, direction, int(auto_entry), source, 'owner' if pay_mode is not None else None))
        conn.commit()
        return cur.lastrowid
    finally:
        if own:
            conn.close()


def fixed_list(direction=None, conn=None):
    """고정비/정기수입 목록. direction 지정 시 필터. 반환: (id, name, amount,
    direction, category, next_due, cycle, method_name) 리스트.

    category = ko display (COALESCE(display_name, name)); fixed-list is
    human-facing output (bulleted 원/합계), so it renders the ko label."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        base = (
            "SELECT f.id, f.name, f.amount, f.direction, "
            "COALESCE(c.display_name, c.name, ''), COALESCE(f.next_due,''), "
            "f.cycle, COALESCE(m.name,'') FROM fixed_cost f "
            "LEFT JOIN spend_category c ON c.id = f.category_id "
            "LEFT JOIN pay_method m ON m.id = f.method_id ")
        if direction:
            return conn.execute(
                base + "WHERE f.direction=? ORDER BY f.id;",
                (direction,)).fetchall()
        return conn.execute(base + "ORDER BY f.id;").fetchall()
    finally:
        if own:
            conn.close()


_FIXED_UPD_COLS = {
    'name': _txt, 'category': None, 'next_due': _txt, 'cycle': _txt,
    'pay_mode': _txt, 'amount': _strict_amount,
    'method_id': None, 'direction': None, 'auto_entry': None, 'source': None,
}


def fixed_upd(fid, fields, conn=None):
    """고정비 부분 갱신. 갱신 후 (id, name, amount, direction) 반환(없으면 None).
    strict amount, direction/auto/source 검증. category 는 get_or_create 로 해석."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        sets, vals = [], []
        for col, raw in fields.items():
            if col not in _FIXED_UPD_COLS:
                raise ValueError(f"수정 불가 컬럼: {col}")
            if col == 'category':
                cid = spend_category_get_or_create(conn, raw) if raw else None
                sets.append("category_id=?")
                vals.append(cid)
            elif col == 'amount':
                sets.append("amount=?")
                vals.append(_strict_amount(raw))
            elif col == 'direction':
                if raw not in _FIXED_DIRECTIONS:
                    raise ValueError(
                        f"direction 값 오류: {raw} (expense/income)")
                sets.append("direction=?")
                vals.append(raw)
            elif col == 'auto_entry':
                if str(raw) not in ('0', '1'):
                    raise ValueError(f"auto_entry 값 오류: {raw} (0/1)")
                sets.append("auto_entry=?")
                vals.append(int(raw))
            elif col == 'source':
                if raw not in _FIXED_SOURCES:
                    raise ValueError(
                        f"source 값 오류: {raw} (interview/chat/batch)")
                sets.append("source=?")
                vals.append(raw)
            elif col == 'method_id':
                sets.append("method_id=?")
                vals.append(int(raw) if str(raw).strip() != '' else None)
            elif col == 'pay_mode':
                if raw not in ('auto', 'manual', '', None):
                    raise ValueError('pay_mode must be auto, manual or empty (unknown)')
                sets.extend(("pay_mode=?", "pay_mode_source='owner'"))
                vals.append(raw or None)
            else:
                sets.append(f"{col}=?")
                vals.append(_FIXED_UPD_COLS[col](raw))
        if not sets:
            raise ValueError("갱신할 필드 없음")
        vals.append(int(fid))
        conn.execute(
            f"UPDATE fixed_cost SET {', '.join(sets)} WHERE id=?;", vals)
        conn.commit()
        return conn.execute(
            "SELECT id, name, amount, direction FROM fixed_cost WHERE id=?;",
            (int(fid),)).fetchone()
    finally:
        if own:
            conn.close()


def fixed_del(fid, conn=None):
    """고정비/정기수입 한 건 삭제."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        conn.execute("DELETE FROM fixed_cost WHERE id=?;", (int(fid),))
        conn.commit()
    finally:
        if own:
            conn.close()


def method_del(mid, conn=None):
    """결제수단(카드/계좌 공용) 삭제. FK-안전: 고정비(method_id) 또는 다른 결제수단
    (linked_account_id, 예: 체크카드 연결계좌)가 참조 중이면 삭제 거부.
    반환: (status, payload).
      ('notfound', None)                     -- 해당 id 없음
      ('blocked', {'fixed':[(id,name)...],   -- 참조자 목록(먼저 재지정/링크해제 필요)
                   'linked':[(id,name)...]})
      ('deleted', (id, name, kind))          -- 삭제 완료"""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        row = conn.execute(
            "SELECT id, name, kind FROM pay_method WHERE id=?;",
            (int(mid),)).fetchone()
        if row is None:
            return ('notfound', None)
        fixed_refs = conn.execute(
            "SELECT id, name FROM fixed_cost WHERE method_id=? ORDER BY id;",
            (int(mid),)).fetchall()
        linked_refs = conn.execute(
            "SELECT id, name FROM pay_method WHERE linked_account_id=? "
            "ORDER BY id;", (int(mid),)).fetchall()
        if fixed_refs or linked_refs:
            return ('blocked',
                    {'fixed': fixed_refs, 'linked': linked_refs})
        import ledger_benefits
        ledger_benefits.forget_method(conn, int(mid))
        conn.execute("DELETE FROM pay_method WHERE id=?;", (int(mid),))
        conn.commit()
        return ('deleted', row)
    finally:
        if own:
            conn.close()


def guard_get(key, scope='global', conn=None):
    """가드 행 조회. 반환: (guard_key, scope, value, unit, enforcement,
    inviolable) 또는 None."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        return _guard_row(conn, key, scope)
    finally:
        if own:
            conn.close()


def guard_set(key, value, scope='global', enforcement=None, unit=None,
              source=None, conn=None):
    """기존 가드 행 갱신(생성 안 함, v1.1). value 는 정수 또는 None(measure-first).
    updated_at 갱신. enforcement 지정 시 {block,hold,inform} 검증. 갱신 후 행 반환;
    (key,scope) 행 없으면 None."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        if _guard_row(conn, key, scope) is None:
            return None
        if enforcement is not None and enforcement not in _GUARD_ENFORCEMENT:
            raise ValueError(
                f"enforcement 값 오류: {enforcement} (block/hold/inform)")
        sets = ["value=?", "updated_at=datetime('now','localtime')"]
        vals = [None if value is None else int(value)]
        if enforcement is not None:
            sets.append("enforcement=?")
            vals.append(enforcement)
        if unit is not None:
            sets.append("unit=?")
            vals.append(unit)
        if source is not None:
            sets.append("source=?")
            vals.append(source)
        vals.extend([key, scope])
        conn.execute(
            f"UPDATE ledger_guard SET {', '.join(sets)} "
            "WHERE guard_key=? AND scope=?;", vals)
        conn.commit()
        return _guard_row(conn, key, scope)
    finally:
        if own:
            conn.close()


# ── payline CLI (v1.1) ──────────────────────────────────────

def cli_method_add(argv):
    # method-add <name> <kind> [aliases] [--billing-day N] [--link <ref>]
    #            [--new-confirmed]
    # method_add is find-first on the EXACT name; the near gate (2026-09-28)
    # stops "현대카드 M" / "현대 카드M" beside 현대카드M from minting a second
    # instrument (and a second entity). --new-confirmed = owner said different.
    argv, new_confirmed = _pop_flag(argv, '--new-confirmed')
    argv, billing_val = _pop_opt(argv, '--billing-day')
    argv, link_val = _pop_opt(argv, '--link')
    _u = ("사용법: kit_life.sh method-add <name> <kind> [aliases] "
          "[--billing-day N] [--link <account_name_or_id>]\n"
          "  kind: " + '|'.join(sorted(_PAY_METHOD_KINDS)))
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err(_u)
    name, kind = argv[0], argv[1]
    aliases = argv[2] if len(argv) > 2 else None
    if kind not in _PAY_METHOD_KINDS:
        _err(f"kind 값 오류: {kind} ({'|'.join(sorted(_PAY_METHOD_KINDS))})")
    billing_day = None
    if billing_val is not None:
        if not str(billing_val).isdigit():
            _err(f"--billing-day 는 숫자여야 함: {billing_val}")
        billing_day = int(billing_val)
    conn = get_conn()
    try:
        # 체크카드(debit_card)는 결제계정 링크 필수(2026-07-27 convention). 신용카드는 선택.
        if kind == 'debit_card':
            if link_val is None or _pay_method_by_ref(conn, link_val) is None:
                _err("체크카드는 결제계정 링크가 필요합니다. "
                     "--link <account_name_or_id> 로 결제계정을 지정하세요.")
        if conn.execute("SELECT 1 FROM pay_method WHERE name=?;",
                        (name,)).fetchone() is None:
            _near_gate_new_confirmed(conn, "method", name, new_confirmed)
        row = method_add(name, kind, aliases=aliases, billing_day=billing_day,
                         link=link_val, conn=conn, with_entity=True)
        # 2.34.0: 4th column = the resolved entity id (empty when it could
        # not be resolved without guessing; the reason goes to stderr).
        print(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[4] if row[4] else ''}")
        if row[3] == 'ambiguous':
            print(f"주의: '{row[1]}' 라벨이 여러 entity 를 가리켜 연결하지 않았습니다 "
                  "(이 수단의 지출은 대상 미귀속으로 남고 intake 확정이 거부됩니다).",
                  file=sys.stderr)
        elif row[3] == 'inactive':
            print(f"주의: '{row[1]}' entity 가 휴면/폐기 상태라 되살리지 않았습니다.",
                  file=sys.stderr)
    finally:
        conn.close()


def _method_aliases(raw):
    """pay_method.aliases is free text: a JSON list, or pipe/comma separated
    (the same reading intake.money_data applies)."""
    try:
        vals = json.loads(raw or '[]')
        if not isinstance(vals, list):
            raise ValueError()
    except (ValueError, TypeError):
        vals = re.split(r'[|,]', raw or '')
    out = []
    for v in vals:
        v = str(v).strip()
        if v and v not in out:
            out.append(v)
    return out


def method_list_json(conn, canonical=False):
    """2.34.0 (G3): machine read of every payment method incl. aliases and the
    resolved entity id. Read-only; no write lock."""
    from ledger_instrument_facts import records
    facts = records(conn)
    out = []
    for mid, name, kind, aliases, bd, lid, canonical_id in conn.execute(
            "SELECT id, name, kind, aliases, billing_day, linked_account_id, canonical_id "
            "FROM pay_method ORDER BY id;").fetchall():
        out.append({'id': mid, 'name': name, 'kind': kind,
                    'instrument_facts': facts.get(mid),
                    'aliases': _method_aliases(aliases), 'billing_day': bd,
                    'linked_account_id': lid,
                    'entity_id': _spend_entity_id(conn, name)})
        if canonical:
            out[-1]['canonical_id'] = canonical_id
    return out


def method_alias_add(ref, aliases, conn):
    """2.34.0 (G3): merge aliases into a method (method-upd aliases= replaces).
    Find-first: an alias already present, or equal to the name, is skipped.
    Refuses an alias another method already answers to (name or alias) --
    that would make intake resolution ambiguous. Stores a JSON list.
    Returns (id, name, aliases list, added list) or None (no such method)."""
    row = _pay_method_by_ref(conn, ref)
    if row is None:
        return None
    cur = conn.execute("SELECT aliases FROM pay_method WHERE id=?;",
                       (row[0],)).fetchone()[0]
    have = _method_aliases(cur)
    added = []
    for a in aliases:
        a = str(a).strip()
        if not a or a == row[1] or a in have:
            continue
        for oid, oname, oal in conn.execute(
                "SELECT id, name, aliases FROM pay_method WHERE id<>?;",
                (row[0],)).fetchall():
            if a == oname or a in _method_aliases(oal):
                raise ValueError(f"별칭 '{a}' 는 이미 다른 결제수단({oid}. {oname})이 씁니다")
        have.append(a)
        added.append(a)
    if added:
        conn.execute("UPDATE pay_method SET aliases=? WHERE id=?;",
                     (json.dumps(have, ensure_ascii=False), row[0]))
        conn.commit()
    return (row[0], row[1], have, added)


def cli_method_alias_add(argv):
    # method-alias-add <id|name> <alias> [<alias> ...]
    if len(argv) < 2 or not argv[0]:
        _err("사용법: kit_life.sh method-alias-add <id|name> <alias> [<alias> ...]")
    conn = get_conn()
    try:
        conn.execute('BEGIN IMMEDIATE')
        try:
            res = method_alias_add(argv[0], argv[1:], conn)
        except ValueError as e:
            conn.rollback()
            _err(str(e))
        if res is None:
            conn.rollback()
            _err(f"해당 결제수단 없음: {argv[0]}")
        if conn.in_transaction:
            conn.commit()
        print(json.dumps({'id': res[0], 'name': res[1], 'aliases': res[2],
                          'added': res[3]}, ensure_ascii=True))
    finally:
        conn.close()


def cli_method_list(argv):
    # method-list [--json [--canonical]]: optional identity for inventory matching
    if argv and argv[0] == '--json':
        conn = get_conn()
        try:
            print(json.dumps(method_list_json(conn, canonical='--canonical' in argv), ensure_ascii=True))
        finally:
            conn.close()
        return
    rows = method_list()
    if not rows:
        print("등록된 결제수단 없음")
        return
    for mid, name, kind, billing_day, linked_name in rows:
        bd = f" 청구일{billing_day}" if billing_day else ""
        ln = f" -> {linked_name}" if linked_name else ""
        # human render: ko display for kind (fallback to raw key if unmapped).
        kind_disp = _PAY_METHOD_KIND_DISPLAY.get(kind, kind)
        print(f"  {mid}. {name} [{kind_disp}]{bd}{ln}")


