def cli_check(argv):
    """Read-only integrity/version report (DGN-672 contract C5).

    Single locus for "is this kit_life DB healthy and what version is it".
    Consumers: backup-data.sh pre-dump gate, restore-data.sh candidate/post
    verify (via --db), ad-hoc "is the DB ok".

    Connection is a READ-ONLY URI (never get_conn) because:
      (a) a check tool must never mutate its target -- _apply_pragmas executes
          journal_mode=WAL, a write-y pragma (wrong on a possibly corrupt DB);
      (b) DB absence is handled here in the report format (get_conn has its
          own fixed stderr+exit(1) shape).

    Output, one item per line:
        integrity=ok|FAIL
        user_version=N
        table=<name> rows=N     (actual tables, sorted; rows=ERR if unreadable)
        missing=<name>          (in schema.sql's CREATE TABLE set, absent in DB)
        body_stats_defaults=<comma keys>   (2.20.0; empty = none)
    The expected table set is parsed from the instance's database/schema.sql
    (never hardcoded); when schema.sql is absent only the actual set is listed.

    2.20.0 body_stats_defaults: THE machine-side answer to "did the owner's
    body measurements quietly vanish". On 2026-09-11 they did, and the only
    thing that ever noticed was a human squinting at a protein figure the next
    afternoon. `check` is what backup-data.sh and restore-data.sh already run,
    so this is the report that gets read without anyone deciding to look.
    An integrity-ok DB with a non-empty list is NOT a FAIL -- a fresh instance
    that has never been measured is legitimately in that state -- so this line
    never moves the exit code.

    Flags: --db <path> checks a candidate DB with this same logic (used by
    restore-data.sh); default is the live DB_PATH.

    Exit: 0 = integrity ok / 1 = FAIL or DB absent. A version mismatch is a
    REPORT, not an exit reason (backup must keep running on drifted DBs)."""
    p = argparse.ArgumentParser(prog='kit_life.sh check', add_help=False)
    p.add_argument('--db', default=DB_PATH)
    ns, _ = p.parse_known_args(argv)
    db_path = ns.db
    if not os.path.isfile(db_path):
        # No DB = a non-kit_life / un-seeded instance: this is the NORMAL state,
        # not a failure (pack compat-lint C6 / plan section 2d graceful no-op).
        # A default-path absence exits 0 (nothing to check); an explicit --db
        # target that is missing stays a FAIL (restore-verify still catches a
        # vanished candidate). A present-but-CORRUPT DB below still exits 1, so
        # the backup corruption gate is unchanged.
        if db_path == DB_PATH:
            print("integrity=absent (no kit_life.db; not a kit_life instance)")
            sys.exit(0)
        print(f"integrity=FAIL (db missing: {db_path})")
        sys.exit(1)
    integrity = 'FAIL'
    user_version = None
    tables = []
    counts = {}
    stat_defaults = None
    try:
        import ro_open  # noqa: E402
        conn = ro_open.open_ro(db_path)
        try:
            row = conn.execute("PRAGMA integrity_check;").fetchone()
            if row and str(row[0]).lower() == 'ok':
                integrity = 'ok'
            user_version = conn.execute("PRAGMA user_version;").fetchone()[0]
            tables = sorted(r[0] for r in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' "
                "AND name NOT LIKE 'sqlite_%';"))
            for t in tables:
                try:
                    counts[t] = conn.execute(
                        'SELECT COUNT(*) FROM "%s";' % t).fetchone()[0]
                except sqlite3.Error:
                    counts[t] = 'ERR'
            if 'config' in tables:
                # Read through the store's own row reader on OUR read-only
                # connection, so `check --db <candidate>` judges the candidate
                # and never the live DB, and so the classification of "served
                # from code" cannot drift from what load_body_stats() does.
                try:
                    stat_defaults = body_stats_defaults_used(
                        _merge_body_stats(
                            SqliteConfigStore()._read_rows(conn=conn)))
                except sqlite3.Error:
                    stat_defaults = None
        finally:
            conn.close()
    except sqlite3.Error as e:
        print(f"integrity=FAIL ({e})")
        sys.exit(1)
    print(f"integrity={integrity}")
    if user_version is not None:
        print(f"user_version={user_version}")
    for t in tables:
        print(f"table={t} rows={counts[t]}")
    if stat_defaults is not None:
        print("body_stats_defaults=%s" % ','.join(stat_defaults))
    schema_path = os.path.join(SCRIPT_DIR, 'schema.sql')
    if os.path.isfile(schema_path):
        expected = set()
        with open(schema_path, encoding='utf-8') as f:
            for m in re.finditer(
                    r'^\s*CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?'
                    r'["\']?(\w+)', f.read(),
                    re.IGNORECASE | re.MULTILINE):
                expected.add(m.group(1))
        for name in sorted(expected - set(tables)):
            print(f"missing={name}")
    sys.exit(0 if integrity == 'ok' else 1)


# ── inspect: the SAFE raw-read verb ────────────────────────────────────────
# Raw table reads show cancelled blocks and gone places exactly like live rows;
# a reader who forgot the filter misread the owner's data twice (2026-09-23,
# 2026-09-24). The read path itself now defaults to live-only, so nobody has
# to remember. SQLite resolves an unqualified name in the TEMP schema before
# main, so a TEMP VIEW named like the table SHADOWS it for the user's SELECT;
# main.<table> stays reachable for forensic reads. Predicates are the kit's own
# LIVE_*_SQL constants (one definition, see near LIVE_FILTER).
#
# Shadowed (table -> group -> predicate). Groups are the two opt-outs:
#   cancelled  block, timeblock, sub_event  (settled 'abandoned' / tombstoned)
#   retired    place, travel_rule, routine_def, carry_item, life_why,
#              ledger_goal                  (gone / retired / archived ...)
# `timeblock` is shadowed by name because a main-schema view does NOT see a
# temp shadow of the table it reads (verified) -- without it the compat view
# would leak cancelled rows straight through.
# DELIBERATELY LEFT RAW: travel_edge (a view; already live-only via
# v_place_link_measure), the other v_* views (they derive over main tables;
# reach cancelled-free numbers through timeblock/block), ax_* / thesis /
# hypothesis / goal_readiness_rule / generator / inflow / domain (no kit-wide
# live predicate exists for them -- inventing one here would be a new
# definition, not a reuse), goal_target / commitment (versioned history read
# as-of via valid_from/valid_until, not tombstoned), and every ledger/log
# table (rows are facts, not tombstoned).
# CAVEAT: a live block whose place is gone drops out of an INNER JOIN to the
# shadowed place -- LEFT JOIN it, or pass --include-retired.
INSPECT_SHADOWS = (
    ("block", "cancelled", LIVE_BLOCK_SQL),
    ("timeblock", "cancelled", LIVE_BLOCK_SQL),
    ("sub_event", "cancelled", LIVE_SUB_SQL),
    ("place", "retired", LIVE_PLACE_SQL),
    ("travel_rule", "retired", LIVE_TRAVEL_RULE_SQL),
    ("routine_def", "retired", LIVE_ROUTINE_DEF_SQL),
    ("carry_item", "retired", LIVE_CARRY_SQL),
    ("life_why", "retired", LIVE_WHY_SQL),
    ("ledger_goal", "retired", LIVE_GOAL_SQL),
)
_INSPECT_STMT_RE = re.compile(
    r"^\s*(?:select|with|values|pragma\s+table_x?info)\b", re.IGNORECASE)
_INSPECT_PRAGMAS = ("table_info", "table_xinfo")


class InspectRefused(Exception):
    """The statement is not a single read; nothing was executed."""


def _inspect_uri(path):
    """Read-only URI that creates NO side files. mode=ro alone still creates
    -wal/-shm beside a WAL database nobody has open (measured), and a read
    tool must leave the directory as it found it. With any side file already
    present a live connection owns them, so plain mode=ro reads the WAL
    correctly; with none present there is no un-checkpointed content, and
    immutable=1 opens without creating anything."""
    from urllib.parse import quote
    live = any(os.path.exists(path + suf) for suf in ("-wal", "-shm", "-journal"))
    return "file:%s?mode=ro%s" % (quote(os.path.abspath(path)),
                                  "" if live else "&immutable=1")


def _inspect_authorizer(action, arg1, arg2, dbname, source):
    if action in (sqlite3.SQLITE_SELECT, sqlite3.SQLITE_READ,
                  sqlite3.SQLITE_RECURSIVE):
        return sqlite3.SQLITE_OK
    if action == sqlite3.SQLITE_FUNCTION:
        return (sqlite3.SQLITE_DENY if (arg2 or "").lower() == "load_extension"
                else sqlite3.SQLITE_OK)
    if action == sqlite3.SQLITE_PRAGMA and (arg1 or "").lower() in _INSPECT_PRAGMAS:
        return sqlite3.SQLITE_OK
    return sqlite3.SQLITE_DENY


def inspect_query(db_path, sql, include_cancelled=False, include_retired=False):
    """Run ONE read statement against the kit DB, live-only by default.
    Returns (columns, rows, active_shadows, skipped_shadows). Raises
    InspectRefused for anything that is not a single SELECT / WITH / VALUES /
    PRAGMA table_info."""
    stmt = (sql or "").strip()
    while stmt.endswith(";"):
        stmt = stmt[:-1].rstrip()
    if not stmt or not _INSPECT_STMT_RE.match(stmt):
        raise InspectRefused("only one SELECT / WITH ... SELECT / "
                             "PRAGMA table_info is accepted")
    conn = sqlite3.connect(_inspect_uri(db_path), uri=True)
    try:
        have = {r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type IN ('table','view');")}
        active, skipped = [], []
        for table, group, pred in INSPECT_SHADOWS:
            if table not in have:
                continue
            if (group == "cancelled" and include_cancelled) or \
                    (group == "retired" and include_retired):
                skipped.append(table)
                continue
            conn.execute('CREATE TEMP VIEW "%s" AS SELECT * FROM main."%s" '
                         'WHERE %s;' % (table, table, pred))
            active.append(table)
        conn.execute("PRAGMA query_only = ON;")   # after the TEMP views: they need a write
        conn.set_authorizer(_inspect_authorizer)
        try:
            cur = conn.execute(stmt)
            cols = [d[0] for d in (cur.description or [])]
            rows = cur.fetchall()
        except sqlite3.ProgrammingError as e:      # more than one statement
            raise InspectRefused(str(e))
        except sqlite3.DatabaseError as e:
            if any(m in str(e).lower() for m in (
                    "not authorized", "cannot modify", "readonly")):
                raise InspectRefused("statement is not a read (%s)" % e)
            raise
        return cols, rows, active, skipped
    finally:
        conn.close()


def _inspect_cell(v):
    if v is None:
        return ""
    if isinstance(v, bytes):
        return v.hex()
    return str(v).replace("\\", "\\\\").replace("\t", "\\t").replace(
        "\n", "\\n").replace("\r", "\\r")


def cli_inspect(argv):
    """inspect "<SELECT ...>" [--include-cancelled] [--include-retired] [--json]
    Safe raw read: live-only by default (see INSPECT_SHADOWS), read-only, no
    side files, one read statement. TSV with header, or --json rows. One
    stderr line names the shadows that were active."""
    sql, as_json, inc_c, inc_r = None, False, False, False
    for a in argv:
        if a == "--json":
            as_json = True
        elif a == "--include-cancelled":
            inc_c = True
        elif a == "--include-retired":
            inc_r = True
        elif a.startswith("--"):
            _err("inspect: unknown option %s" % a)
        elif sql is None:
            sql = a
        else:
            _err("inspect: one quoted statement only")
    if sql is None:
        _err('usage: inspect "<SELECT ...>" [--include-cancelled] '
             '[--include-retired] [--json]')
    if not os.path.isfile(DB_PATH):
        _err("inspect: no kit_life.db (%s)" % DB_PATH)
    try:
        cols, rows, active, skipped = inspect_query(DB_PATH, sql, inc_c, inc_r)
    except InspectRefused as e:
        _err("inspect: refused -- %s" % e)
    except sqlite3.Error as e:
        _err("inspect: %s" % e)
    print("inspect: live-only shadows active: %s%s -- raw rows via main.<table>"
          % (",".join(active) or "(none)",
             ("; skipped by flag: " + ",".join(skipped)) if skipped else ""),
          file=sys.stderr)
    # Raw schedule lookups are also a common recall route. Context goes to
    # stderr so JSON/TSV consumers retain the exact query result on stdout.
    literals = re.findall(r"'((?:''|[^'])*)'", sql)[:20]
    if 'title' in cols:
        literals += [str(r[cols.index('title')] or '') for r in rows[:20]]
    if literals:
        conn = sqlite3.connect(_inspect_uri(DB_PATH), uri=True)
        try:
            conn.execute("PRAGMA query_only = ON")
            for line in _related_shopping(conn, ' '.join(v[:500].replace("''", "'") for v in literals)):
                print(line, file=sys.stderr)
        finally:
            conn.close()
    if as_json:
        print(json.dumps([{c: (v.hex() if isinstance(v, bytes) else v)
                           for c, v in zip(cols, r)} for r in rows],
                         ensure_ascii=False))
    else:
        print("\t".join(cols))
        for r in rows:
            print("\t".join(_inspect_cell(v) for v in r))


# ── Event / Experience overlay (026) ──────────────────────────────────────
# Experience container laid ON TOP of timeblock (026 overlay; timeblock is
# UNCHANGED -- DGN-783 lock). Six tables: event / record / artifact /
# record_event (N:M) / event_timeblock (N:M containment) / insight (crew SoT).
#
# Verb surface consumed by the episode-log / episode-session / episode-setup
# skills. All verbs open get_conn() (foreign_keys=ON), so the schema's
# downward-only ON DELETE CASCADE keeps every delete NON-DESTRUCTIVE: an event
# delete drops only its junction links; the underlying timeblock / record /
# artifact rows survive.
#
# Sign-off guards enforced HERE (code, not prose):
#   1. insight insert: ulid MANDATORY (new_ulid); evidence = JSON array of EVENT
#      ulids (see cli_experience_distill).
#   2. record-attach source_table WHITELIST (RECORD_SOURCE_TABLES); anything else
#      rejected at the tool layer (D2 code-gate). New source = add to the set.
#   3. delete-event: (a) unlink-only (event row + its junction links go, timeblock
#      / record / artifact originals survive -- schema cascade is junction-only);
#      (b) source-row delete removes its pointing record in the SAME tx
#      (cli_experience_delete_source, FK-non-destructive); (c) orphan-insight
#      guard warns when an insight's evidence references the event being deleted.

# Authoritative source_table token registry = REAL table names (the kit owns it,
# sign-off #2). A new evidence source module MUST be registered here. No CHECK
# in schema (a CHECK would force a migration per new source); the whitelist lives
# at the tool layer instead.
# 'block' (cut 3): v3.2 record-idiom rows -- meals since 036 (source_module=
# 'diet', settled_by='meal-record'). Registering the token carries two duties,
# both honored in code: (a) attach derives record.ts from the block's OWN
# event-time stamp, never created_at (owner 2026-09-08 13:29); (b) every block
# DELETE site clears the pointing record in the SAME tx (_block_record_del,
# 026 polymorphic-integrity guard #1).
RECORD_SOURCE_TABLES = frozenset({'workouts', 'metric_log', 'spend_entry',
                                  'artifact', 'block', 'made_dish', 'owned_item',
                                  'owned_stock', 'shop_capture', 'shop_item',
                                  'ledger_resource', 'entity', 'stock_use'})

# record_event.role CHECK domain (schema-backed); tool validates before insert
# for a clean error instead of a raw IntegrityError.
_RECORD_EVENT_ROLES = frozenset({'primary', 'incidental'})


from event_identity import lookup_boundary as _identity_boundary


def _experience_lookup_boundary(*positions, **kwargs):
    return _identity_boundary(sys.modules[__name__], *positions, **kwargs)


def experience_resolve(conn, token):
    """Canonical occurrence lookup for numeric ID, ULID or capture key."""
    from event_identity import resolve
    return resolve(conn, token)


def next_event_id(conn):
    from event_identity import next_id
    return next_id(conn)


def _event_row(conn, event_id):
    """(id, ulid, title) for an event, or None if absent."""
    return experience_resolve(conn, event_id)


# Capture is a domain write, independent of module management state. All callers
# share their transaction with this helper; it never commits a partial capture.
_RECORD_SOURCE_PK = {'owned_stock': 'owned_id', 'stock_use': 'rowid'}


def _experience_time(occurred_on=None, occurred_at=None):
    occurred_on, occurred_at = occurred_on or None, occurred_at or None
    if occurred_on:
        occurred_on = datetime.date.fromisoformat(occurred_on).isoformat()
    if occurred_at:
        instant = datetime.datetime.fromisoformat(occurred_at.replace('Z', '+00:00'))
        if instant.tzinfo is None:
            raise ValueError('occurrence time needs an explicit timezone')
        day = instant.date().isoformat()
        if occurred_on and occurred_on != day:
            raise ValueError('occurrence date and time disagree')
        occurred_on = day
    return occurred_on, occurred_at


def _experience_source(conn, table, source_id):
    if table not in RECORD_SOURCE_TABLES:
        raise ValueError('unregistered experience source: ' + str(table))
    pk = _RECORD_SOURCE_PK.get(table, 'id')
    cursor = conn.execute('SELECT * FROM ' + table + ' WHERE ' + pk + '=?',
                          (int(source_id),))
    row = cursor.fetchone()
    if row is None:
        raise ValueError('experience source missing: %s:%s' % (table, source_id))
    data = dict(zip((d[0] for d in cursor.description), row))
    # Never use created_at, selected_on or completed_at (the session clock).
    clock = conn.execute("SELECT value FROM block_attr WHERE block_id=? AND attr_token='meal_occurred_at'", (source_id,)).fetchone() if table == 'block' else None
    return (clock[0] if clock else None) or (data.get('start_at') if table == 'block' else None) or data.get('date') or data.get('bought_on') or data.get('ts')


def _experience_adopt_capture(conn, target, sources):
    """Fold a provisional capture into an explicitly linked occurrence.

    This preserves the old attach verbs: a domain write followed by attachment
    cannot leave a second automatic container. Curated hierarchies, exclusion
    memories and distilled experiences are retained as independent containers.
    Only capture-created containers qualify; source rows are never deleted.
    """
    target = int(target)
    candidates = set()
    for table, sid in sources:
        if table in {'shop_item', 'ledger_resource', 'entity'}:
            continue
        candidates.update(row[0] for row in conn.execute(
            'SELECT re.event_id FROM record r JOIN record_event re ON re.record_id=r.id '
            'WHERE r.source_table=? AND r.source_id=? AND re.event_id<>?',
            (table, int(sid), target)))
    for old in sorted(candidates):
        if not conn.execute('SELECT 1 FROM experience_capture_key WHERE capture_key=?',
                            ('created:' + str(old),)).fetchone():
            continue
        row = conn.execute('SELECT ulid,note,reaction,occurred_on,occurred_at,parent_id FROM event WHERE id=?', (old,)).fetchone()
        if row is None or row[5] is not None:
            continue
        if (conn.execute('SELECT 1 FROM event WHERE parent_id=?', (old,)).fetchone()
                or conn.execute('SELECT 1 FROM event_record_exclusion WHERE event_id=?', (old,)).fetchone()
                or conn.execute('SELECT 1 FROM event_child_exclusion WHERE parent_id=? OR child_id=?', (old, old)).fetchone()
                or conn.execute('SELECT 1 FROM insight WHERE instr(evidence,?)>0', (row[0],)).fetchone()):
            continue
        for field, value in (('note', row[1]), ('reaction', row[2])):
            if value:
                kept = conn.execute('SELECT ' + field + ' FROM event WHERE id=?', (target,)).fetchone()[0]
                if not kept or ('\n' + value + '\n') not in ('\n' + kept + '\n'):
                    conn.execute('UPDATE event SET ' + field + '=? WHERE id=?',
                                 ((kept + '\n' if kept else '') + value, target))
        conn.execute('UPDATE event SET occurred_on=COALESCE(occurred_on,?), occurred_at=CASE WHEN occurred_on IS NULL OR occurred_on=? THEN COALESCE(occurred_at,?) ELSE occurred_at END WHERE id=?', (row[3], row[3], row[4], target))
        conn.execute('INSERT OR IGNORE INTO record_event(record_id,event_id,role,weight,source,added_at) '
                     'SELECT re.record_id,?,re.role,re.weight,re.source,re.added_at FROM record_event re '
                     'WHERE re.event_id=? AND NOT EXISTS(SELECT 1 FROM event_record_exclusion x WHERE x.event_id=? AND x.record_id=re.record_id)',
                     (target, old, target))
        conn.execute('INSERT OR IGNORE INTO event_timeblock(event_id,timeblock_id,added_at) '
                     'SELECT ?,et.timeblock_id,et.added_at FROM event_timeblock et WHERE et.event_id=? '
                     "AND NOT EXISTS(SELECT 1 FROM event_record_exclusion x JOIN record r ON r.id=x.record_id WHERE x.event_id=? AND r.source_table='block' AND r.source_id=et.timeblock_id)",
                     (target, old, target))
        conn.execute('INSERT OR IGNORE INTO experience_person(event_id,person_id,added_at) SELECT ?,person_id,added_at FROM experience_person WHERE event_id=?', (target, old))
        conn.execute('UPDATE experience_capture_key SET event_id=? WHERE event_id=? AND capture_key<>?',
                     (target, old, 'created:' + str(old)))
        conn.execute('UPDATE shop_capture SET event_id=? WHERE event_id=?', (target, old))
        conn.execute('DELETE FROM event WHERE id=?', (old,))


def experience_ensure(conn, title, *, occurred_on=None, occurred_at=None,
                      block_id=None, evidence=(), note=None, reaction=None,
                      event_id=None, verbatim=None, kind_hint=None,
                      _savepoint=True):
    """Ensure one occurrence and its evidence, under the caller's writer lock.

    Linked block/source identity wins over day/title. Unknown occurrence time
    stays NULL. The context day scopes retries only; it is never event time.
    A savepoint makes validation/link failures atomic even inside a batch.
    The session writer owns rollback and forbids nested transaction controls;
    its kit completion hook passes _savepoint=False inside that transaction.
    """
    occurred_on, occurred_at = _experience_time(occurred_on, occurred_at)
    if not str(title).strip():
        raise ValueError('experience title required')
    if not _savepoint and not conn.in_transaction:
        raise ValueError('experience capture requires caller transaction')
    if not conn.in_transaction:
        conn.execute('BEGIN IMMEDIATE')
    if _savepoint:
        conn.execute('SAVEPOINT experience_capture')
    try:
        sources = list(dict.fromkeys((str(t), int(i)) for t, i in evidence))
        if block_id is not None:
            block_id = int(block_id)
            sources.insert(0, ('block', block_id))
        stamps = {(t, i): _experience_source(conn, t, i) for t, i in sources}
        # Capture returns both the numeric id and ULID. Accept either stable
        # identifier so a linked domain write needs no owner-visible retry.
        eid = None
        if event_id is not None:
            from event_identity import require
            eid = require(conn, event_id)
        if eid is None and block_id is not None:
            linked = conn.execute('SELECT event_id FROM event_timeblock WHERE timeblock_id=? ORDER BY event_id LIMIT 1', (block_id,)).fetchone()
            eid = linked[0] if linked else None
        for table, sid in sources:
            if eid is not None:
                break
            if table in {'shop_item', 'ledger_resource', 'entity'}:
                continue
            linked = conn.execute('SELECT re.event_id FROM record r JOIN record_event re ON re.record_id=r.id WHERE r.source_table=? AND r.source_id=? ORDER BY re.event_id LIMIT 1', (table, sid)).fetchone()
            eid = linked[0] if linked else None
        context_day = os.environ.get('LIFEKIT_CONTEXT_DATE') or str(datetime.date.today())
        key = json.dumps([occurred_on or context_day, str(title).strip().casefold()])
        if eid is None:
            linked = conn.execute('SELECT event_id FROM experience_capture_key WHERE capture_key=?', (key,)).fetchone()
            eid = linked[0] if linked else None
        if eid is None:
            linked = conn.execute('SELECT id FROM event WHERE lower(title)=lower(?) AND occurred_on IS ? ORDER BY id LIMIT 1', (title, occurred_on)).fetchone() if occurred_on else None
            eid = linked[0] if linked else None
        if eid is not None:
            from event_identity import require
            eid = require(conn, eid)
        if eid is None:
            cur = conn.execute('INSERT INTO event(id,ulid,title,kind_hint,owning_agent,occurred_on,occurred_at) VALUES(?,?,?,?,?,?,?)',
                               (next_event_id(conn), new_ulid(), title, kind_hint, _facade_agent(), occurred_on, occurred_at))
            eid = cur.lastrowid
            conn.execute('INSERT INTO experience_capture_key VALUES(?,?)', ('created:' + str(eid), eid))
        previous_day = conn.execute('SELECT occurred_on FROM event WHERE id=?', (eid,)).fetchone()[0]
        if occurred_on and previous_day and occurred_on != previous_day:
            conn.execute('DELETE FROM experience_capture_key WHERE event_id=? AND capture_key<>?', (eid, 'created:' + str(eid)))
            if occurred_at is None:
                conn.execute('UPDATE event SET occurred_at=NULL WHERE id=?', (eid,))
        conn.execute('INSERT OR IGNORE INTO experience_capture_key VALUES(?,?)', (key, eid))
        conn.execute('UPDATE event SET occurred_on=COALESCE(?,occurred_on), occurred_at=COALESCE(?,occurred_at) WHERE id=?', (occurred_on, occurred_at, eid))
        for field, value in (('note', note), ('reaction', reaction), ('note', verbatim)):
            if value is not None and value != '':
                old = conn.execute('SELECT ' + field + ' FROM event WHERE id=?', (eid,)).fetchone()[0]
                # Preserve separate owner answers verbatim; a retry appends nothing.
                if not old or ('\n' + value + '\n') not in ('\n' + old + '\n'):
                    conn.execute('UPDATE event SET ' + field + '=? WHERE id=?',
                                 ((old + '\n' if old else '') + value, eid))
        if verbatim:
            row = conn.execute("SELECT a.id FROM artifact a JOIN record r ON r.source_table='artifact' AND r.source_id=a.id JOIN record_event re ON re.record_id=r.id WHERE re.event_id=? AND a.kind='note' AND a.ref=?", (eid, verbatim)).fetchone()
            if not row:
                aid = conn.execute("INSERT INTO artifact(ulid,kind,ref,ts,owning_agent) VALUES(?,'note',?,?,?)", (new_ulid(), verbatim, occurred_at or occurred_on, _facade_agent())).lastrowid
                sources.append(('artifact', aid))
                stamps['artifact', aid] = occurred_at or occurred_on
        for table, sid in sources:
            rid = record_upsert(conn, table, sid, ts=stamps[table, sid], owning_agent=_facade_agent())
            if stamps[table, sid] is not None:
                conn.execute('UPDATE record SET ts=? WHERE id=?', (stamps[table, sid], rid))
            excluded = conn.execute('SELECT 1 FROM event_record_exclusion WHERE event_id=? AND record_id=?', (eid, rid)).fetchone()
            if not excluded:
                conn.execute("INSERT OR IGNORE INTO record_event(record_id,event_id,role,source) VALUES(?,?,'primary','capture')", (rid, eid))
        if block_id is not None:
            conn.execute('INSERT OR IGNORE INTO event_timeblock(event_id,timeblock_id) VALUES(?,?)', (eid, block_id))
            conn.execute('INSERT OR IGNORE INTO experience_person(event_id,person_id) SELECT ?,person_id FROM event_persons WHERE event_id=?', (eid, block_id))
        _experience_adopt_capture(conn, eid, sources)
        if verbatim:
            import wait_resolution
            wait_resolution.resolve_words(sys.modules[__name__], conn, verbatim, _facade_agent(),
                                          occurred_on=occurred_on)
        if _savepoint:
            conn.execute('RELEASE experience_capture')
        return eid
    except Exception:
        if _savepoint:
            conn.execute('ROLLBACK TO experience_capture')
            conn.execute('RELEASE experience_capture')
        raise


def _experience_block(conn, block_id, **kwargs):
    row = conn.execute('SELECT title,date FROM block WHERE id=?', (int(block_id),)).fetchone()
    if row is None:
        raise ValueError('experience block missing')
    evidence = list(kwargs.pop('evidence', ()))
    evidence += [('entity', r[0]) for r in conn.execute('SELECT DISTINCT entity_id FROM block_entity WHERE block_id=?', (int(block_id),))]
    return experience_ensure(conn, row[0], block_id=block_id,
                             occurred_on=row[1], evidence=evidence, **kwargs)


# Tool-only directive shared by event and linked meal capture. Never relay it.
