def cli_experience_find(argv):
    # experience-find <title> [date]
    if not argv or not argv[0]:
        _err("사용법: kit_life.sh experience-find <title> [date]")
    title = argv[0]
    date = argv[1] if len(argv) > 1 and argv[1] else None
