@_experience_lookup_boundary(0)
def cli_experience_enrich(argv):
    # Keep legacy subjective-only calls compatible with minimal kit installs.
    legacy = {'reaction', 'note', 'kind_hint', 'title'}
    if argv and any(tok.split('=', 1)[0] not in legacy for tok in argv[1:]):
        import experience_retro
        if not argv[0].isdigit() or any('=' not in tok for tok in argv[1:]):
            raise ValueError('usage: experience-enrich ID field=value ...')
        conn = get_conn()
        try:
            experience_retro.enrich(sys.modules[__name__], conn, int(argv[0]),
                                    dict(tok.split('=', 1) for tok in argv[1:]))
            print('enriched event ' + argv[0])
            _capture_open_today(conn)
        finally:
            conn.close()
        return
    # experience-enrich <event_id> [reaction=<text>] [note=<text>]
    #                   [kind_hint=<text>] [title=<text>]
    # Subjective-facet fill (A5 review). reaction is the primary enrichment.
    if not argv or not argv[0] or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh experience-enrich <event_id> field=value ...")
    event_id = int(argv[0])
    _EDITABLE = {'reaction', 'note', 'kind_hint', 'title'}
    sets = []
    vals = []
    for tok in argv[1:]:
        if '=' not in tok:
            _err(f"field=value 형식이어야 함: {tok}")
        k, v = tok.split('=', 1)
        if k not in _EDITABLE:
            _err(f"수정 불가 필드: {k} (허용: {', '.join(sorted(_EDITABLE))})")
        sets.append(f"{k}=?")
        vals.append(_txt(v))
    if not sets:
        _err("변경할 field=value 가 없음")
    conn = get_conn()
    try:
        if _event_row(conn, event_id) is None:
            _err(f"event 없음: {event_id}")
        if (os.path.isfile(os.path.join(SCRIPT_DIR, 'experience_retro.py'))
                and any(tok.startswith('reaction=') for tok in argv[1:])
                and conn.execute('SELECT count(*) FROM event WHERE parent_id=?',
                                 (event_id,)).fetchone()[0] >= 2):
            import experience_retro
            experience_retro.enrich(sys.modules[__name__], conn, event_id,
                                    dict(tok.split('=', 1) for tok in argv[1:]))
        else:
            conn.execute("BEGIN IMMEDIATE")
            correction_scope = _retro_correction.ReceiptScope(events=(event_id,))
            correction_before = _retro_correction.snapshot(conn, _retro_correction.ENRICH_TABLES, correction_scope)
            conn.execute("UPDATE event SET " + ", ".join(sets) + " WHERE id=?;",
                         tuple(vals) + (event_id,))
            _retro_correction.receipt(conn, 'enrich:' + str(event_id), correction_before,
                                      _retro_correction.ENRICH_TABLES, correction_scope)
            conn.commit()
        print(f"enriched event {event_id}")
        _capture_open_today(conn)
    finally:
        conn.close()


