def cli_experience_rollup(argv):
    # experience-rollup <event_id>
    if not argv or not argv[0] or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh experience-rollup <event_id>")
    event_id = int(argv[0])
    conn = get_conn()
    try:
        if _event_row(conn, event_id) is None:
            _err(f"event 없음: {event_id}")
        rows = _rollup_facets(conn, event_id)
        tb = conn.execute(
            "SELECT COUNT(*) FROM event_timeblock WHERE event_id=?;",
            (event_id,)).fetchone()[0]
        for source_table, cnt in rows:
            print(f"{source_table}\t{cnt}")
        print(f"timeblock\t{tb}")
    finally:
        conn.close()


def cli_experience_query(argv):
    # experience-query <objective|subjective> [date_from] [date_to]
    if not argv or argv[0] not in ('objective', 'subjective'):
        _err("사용법: kit_life.sh experience-query "
             "<objective|subjective> [date_from] [date_to]")
    lens = argv[0]
    date_from = argv[1] if len(argv) > 1 and argv[1] else None
    date_to = argv[2] if len(argv) > 2 and argv[2] else None
    where = []
    params = []
    if date_from:
        where.append("e.occurred_on >= ?")
        params.append(date_from)
    if date_to:
        where.append("e.occurred_on <= ?")
        params.append(date_to)
    where_sql = (" WHERE " + " AND ".join(where)) if where else ""
    conn = get_conn()
    try:
        import occurrence_projection
        if lens == 'objective':
            # objective: which resources are bundled (record + timeblock counts).
            rows = conn.execute(
                "SELECT e.id, e.ulid, e.title, "
                "(SELECT COUNT(*) FROM record_event re WHERE re.event_id=e.id), "
                "(SELECT COUNT(*) FROM event_timeblock et WHERE et.event_id=e.id)"
                " FROM event e" + where_sql + " ORDER BY e.id;",
                tuple(params)).fetchall()
            projected = occurrence_projection.project([
                dict(id=eid, ulid=ulid, title=title, parent_id=None,
                     record_count=rc, timeblock_count=tc)
                for eid, ulid, title, rc, tc in rows],
                occurrence_projection.alias_map(conn))
            for row in projected:
                print(f"{row['id']}\t{row['ulid']}\t{row['title']}\t{row['record_count']}\t{row['timeblock_count']}")
        else:
            # subjective: reaction + note (the meaning facet).
            rows = conn.execute(
                "SELECT e.id, e.ulid, e.title, "
                "COALESCE(e.reaction,''), COALESCE(e.note,'') "
                "FROM event e" + where_sql + " ORDER BY e.id;",
                tuple(params)).fetchall()
            projected = occurrence_projection.project([
                dict(id=eid, ulid=ulid, title=title, parent_id=None,
                     reaction=reaction, note=note)
                for eid, ulid, title, reaction, note in rows],
                occurrence_projection.alias_map(conn))
            for row in projected:
                print(f"{row['id']}\t{row['ulid']}\t{row['title']}\t{row['reaction']}\t{row['note']}")
    finally:
        conn.close()


@_experience_lookup_boundary(0, comma=True)
def cli_experience_distill(argv):
    # experience-distill <event_id,event_id,...> --text <text> [--agent <a>]
    # GUARD #1: insight.ulid MANDATORY (new_ulid); evidence = JSON array of the
    # EVENT ULIDs (not ids), resolved from the given event ids.
    argv, text = _pop_opt(argv, '--text')
    argv, agent_opt = _pop_opt(argv, '--agent')
    _u = ("사용법: kit_life.sh experience-distill <event_id,event_id,...> "
          "--text <text> [--agent <a>]")
    if not argv or not argv[0] or text is None or text == '':
        _err(_u)
    try:
        ev_ids = [int(x) for x in argv[0].split(',') if x.strip() != '']
    except ValueError:
        _err(f"event_ids는 콤마 구분 숫자여야 함: {argv[0]}")
    if not ev_ids:
        _err("근거 event_id가 없음")
    conn = get_conn()
    try:
        # Resolve event ids -> ulids (evidence must be ULIDs, sign-off #1).
        placeholders = ",".join("?" for _ in ev_ids)
        rows = conn.execute(
            "SELECT id, ulid FROM event WHERE id IN (%s);" % placeholders,
            tuple(ev_ids)).fetchall()
        found = {r[0]: r[1] for r in rows}
        missing = [i for i in ev_ids if i not in found]
        if missing:
            _err(f"event 없음: {', '.join(str(m) for m in missing)}")
        evidence_ulids = [found[i] for i in ev_ids]
        ulid = new_ulid()   # GUARD #1: mandatory, never rely on DB default.
        agent = agent_opt or _facade_agent()
        cur = conn.execute(
            "INSERT INTO insight (ulid, text, evidence, owning_agent) "
            "VALUES (?,?,json(?),?);",
            (ulid, text, json.dumps(evidence_ulids), agent))
        conn.commit()
        # machine TSV: insight_id \t ulid
        print(f"{cur.lastrowid}\t{ulid}")
    finally:
        conn.close()


@_experience_lookup_boundary(0, ulid=True)
def cli_experience_list_insights(argv):
    # experience-list-insights [event_ulid]
    # With an event_ulid: only insights whose evidence references that ulid.
    ev_ulid = argv[0] if argv and argv[0] else None
    conn = get_conn()
    try:
        if ev_ulid:
            rows = conn.execute(
                "SELECT id, ulid, text, evidence, created_at FROM insight "
                "WHERE evidence IS NOT NULL AND json_valid(evidence) "
                "AND EXISTS (SELECT 1 FROM json_each(evidence) "
                "WHERE json_each.value=?) ORDER BY id;", (ev_ulid,)).fetchall()
        else:
            rows = conn.execute(
                "SELECT id, ulid, text, evidence, created_at FROM insight "
                "ORDER BY id;").fetchall()
        for iid, ulid, text, evidence, created in rows:
            # tab-safe: text may contain tabs -> collapse for the TSV line.
            safe = str(text).replace("\t", " ").replace("\n", " ")
            print(f"{iid}\t{ulid}\t{safe}\t{evidence or ''}\t{created}")
    finally:
        conn.close()


def _insights_referencing(conn, event_ulid):
    """Insights whose evidence JSON array contains this event ulid (orphan
    guard, sign-off #3c). Returns [(id, ulid, text), ...]."""
    return conn.execute(
        "SELECT id, ulid, text FROM insight "
        "WHERE evidence IS NOT NULL AND json_valid(evidence) "
        "AND EXISTS (SELECT 1 FROM json_each(evidence) "
        "WHERE json_each.value=?) ORDER BY id;", (event_ulid,)).fetchall()


@_experience_lookup_boundary(0)
def cli_experience_delete(argv):
    # experience-delete <event_id> [--force]
    # GUARD #3a: NON-DESTRUCTIVE. Deleting the event row cascades ONLY its
    #   junction rows (record_event / event_timeblock) -- schema cascade is
    #   junction-only, so timeblock / record / artifact ORIGINALS survive. There
    #   is deliberately NO code path here that DELETEs an original row.
    # GUARD #3c: orphan-insight guard. If any insight's evidence references this
    #   event's ulid, refuse unless --force (warn on stderr, exit 3).
    argv, force = _pop_flag(argv, '--force')
    if not argv or not argv[0] or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh experience-delete <event_id> [--force]")
    event_id = int(argv[0])
    conn = get_conn()
    try:
        row = _event_row(conn, event_id)
        if row is None:
            _err(f"event 없음: {event_id}")
        ev_ulid = row[1]
        orphans = _insights_referencing(conn, ev_ulid)
        if orphans and not force:
            # Not a mutation: report the referencing insights and stop (exit 3,
            # same EXISTS_CODE convention the add verbs use for "resolve first").
            print(f"INSIGHT_REF {len(orphans)}")
            for iid, iulid, itext in orphans:
                safe = str(itext).replace("\t", " ").replace("\n", " ")
                print(f"{iid}\t{iulid}\t{safe}")
            sys.exit(EXISTS_CODE)
        conn.execute("DELETE FROM event WHERE id=?;", (event_id,))
        conn.commit()
        print(f"deleted event {event_id} (links removed; "
              f"timeblock/record originals untouched)")
    finally:
        conn.close()


def cli_experience_delete_source(argv):
    # experience-delete-source <source_table> <source_id>
    # GUARD #3b (FK-non-destructive polymorphic integrity): when a SOURCE row is
    #   deleted, its pointing record row MUST be deleted in the SAME tx -- else
    #   the record dangles and a later rowid reuse silently re-binds it. Deleting
    #   the record cascades its record_event links (junction-only). timeblock is
    #   NOT a record source, so it is out of scope here.
    _u = "사용법: kit_life.sh experience-delete-source <source_table> <source_id>"
    if len(argv) < 2 or not argv[0] or not argv[1]:
        _err(_u)
    # GUARD (2026-08-25): SECOND ENTRANCE to the cascading workouts delete.
    #   `experience-delete-source workouts <id>` reaches the exact same
    #   `DELETE FROM workouts` as workout-del, so it routes through the exact
    #   same count-matched confirmation. Without this the guard on workout-del
    #   would be a front door with the back door left open.
    argv, _wd_confirm = _pop_opt(argv, '--confirm-destroy-sets')
    source_table, source_id = argv[0], argv[1]
    if source_table not in RECORD_SOURCE_TABLES:
        _err(f"source_table 미허용: {source_table} "
             f"(허용: {', '.join(sorted(RECORD_SOURCE_TABLES))})")
    # cut 3: block rows are LANE-owned -- a generic delete here would bypass
    # each lane's own guards (meal-del's settled_by filter, spend's shadow
    # discipline, the calendar CAS). The lane deletes clear the pointing
    # record themselves in the same tx (_block_record_del), so guard #3b
    # stays honored without a second entrance.
    if source_table == 'block':
        _err("block 은 소유 레인 동사로 지움 (meal-del / spend-del / 캘린더 "
             "레인). 원본 삭제 시 포인터 record 는 같은 tx 에서 함께 정리됨")
    if not str(source_id).isdigit():
        _err(f"source_id는 숫자여야 함: {source_id}")
    source_id = int(source_id)
    conn = get_conn()
    try:
        if source_table == 'artifact':
            conn.execute("BEGIN IMMEDIATE")
            correction_events = [r[0] for r in conn.execute(
                "SELECT re.event_id FROM record r JOIN record_event re ON re.record_id=r.id "
                "WHERE r.source_table='artifact' AND r.source_id=?", (source_id,))]
            correction_scope = _retro_correction.ReceiptScope(events=correction_events,
                                                                artifacts=(source_id,))
            correction_before = _retro_correction.snapshot(conn, _retro_correction.EXPERIENCE_TABLES, correction_scope)
        # Same-tx: delete the source row AND its pointing record together.
        if source_table == 'artifact':
            conn.execute("DELETE FROM artifact WHERE id=?;", (source_id,))
        elif source_table == 'workouts':
            _workout_history.reject_legacy_write(conn, source_id)
            census = workout_dependents(source_id, conn)
            if not census['exists']:
                _err(f"운동 id={source_id} 없음 (workout-find로 확인하세요)")
            if (_wd_confirm is None
                    or not str(_wd_confirm).lstrip('-').isdigit()
                    or int(_wd_confirm) != census['sets']):
                _print_workout_del_refusal(
                    census, verb="experience-delete-source",
                    extra_args=" workouts %s" % source_id)
            conn.execute("DELETE FROM workouts WHERE id=?;", (source_id,))
            _workout_shadow_del(conn, source_id)  # cut 4 slab 2: shadow follows
            _wd_census = census
        elif source_table in {'made_dish', 'owned_item', 'owned_stock', 'shop_capture', 'shop_item', 'ledger_resource', 'entity', 'stock_use'}:
            pk = _RECORD_SOURCE_PK.get(source_table, 'id')
            conn.execute('DELETE FROM ' + source_table + ' WHERE ' + pk + '=?', (source_id,))
        elif source_table == 'metric_log':
            conn.execute("DELETE FROM metric_log WHERE id=?;", (source_id,))
        elif source_table == 'spend_entry':
            conn.execute("DELETE FROM spend_entry WHERE id=?;", (source_id,))
            _spend_shadow_del(conn, source_id)  # 039: crossing shadow follows
        cur = conn.execute(
            "DELETE FROM record WHERE source_table=? AND source_id=?;",
            (source_table, source_id))
        if source_table == 'artifact':
            _retro_correction.receipt(conn, 'artifact:' + str(source_id), correction_before,
                                      _retro_correction.EXPERIENCE_TABLES, correction_scope)
        conn.commit()
        print(f"deleted source {source_table}:{source_id} "
              f"(records removed: {cur.rowcount})")
        if source_table == 'workouts':
            print("  CASCADED %s set(s) + %s classification(s)"
                  % (_wd_census['sets'], _wd_census['classes']))
            for _n, _c, _s in _wd_census['exercises']:
                print("  DESTROYED set\t%s\t%d\tset_seq=%s" % (_n, _c, _s))
            _report_stale_markers(source_id, "experience-delete-source")
    finally:
        conn.close()


