_CADENCE_KO = {24.0: "매일", 168.0: "주 1회", 336.0: "2주에 1회",
               720.0: "월 1회"}
_N_KO = {1: "한", 2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯"}

# Words that must never reach the user from a kit-rendered line. Checked over
# every template at import (a leaking template cannot ship) and over rendered
# output by test_goal_next_move. Structure words, the internal goal/rule split,
# layer names, and machine vocabulary.
_MOVE_UNSPEAKABLE = ('사다리', '래더', '라더', '한 칸', '칸', '규칙', '단기',
                     '중기', '장기', '지표', '축', 'ladder', 'rung', 'layer',
                     'goal', 'rule', 'axis', 'metric', 'step')


# The approved strand_confirm invitation is declarative (2026-11-04).
# Templates that END a spoken move: each must end on the next decision (a
# question), never on an open "tell me if you want it different" (owner
# rehearsal 2026-09-26 13:27). Example lines ("ex) ...") may follow the
# question.
_MOVE_DECISION_KEYS = ("ask_activity.health", "ask_training",
                       "ask_baseline.weight",
                       "ask_baseline.inbody", "ask_baseline.height",
                       "inbody_stale", "inbody_carry_ask", "basis_update",
                       "ask_baseline.approx",
                       "ask_demographics.age", "ask_demographics.sex",
                       "order_ask", "direction_ask",
                       "direction_adjust_ask",
                       "pace_ask", "held_ask",
                       "prac_ask", "ask_safety", "ask_safety_records",
                       "ask_sex", "ask_feasibility", "confirm_activity",
                       "confirm_activity_tr", "direction_confirm",
                       "direction_confirm_one", "direction_change_ask",
                       "prac_open", "prac_open_plain",
                       "prac_ask.connection",
                       "strands_fix_ask")
# Steps whose copy key is "<step>.<domain>": the copy (and so the step) is
# the domain pack's; the kit carries none (see _move_has).
_MOVE_DOMAIN_STEPS = ("ask_activity",)
# Move asks that read candidate-answer buttons from "<copy key>.buttons"
# (owner 2026-10-05; the pack-supplied copy block).
_MOVE_BUTTON_STEPS = ("ask_activity",)
# Templates that ask the user for DATA (rehearsal 2026-09-28: asks read as abrupt demands).
# Each is "<why line>\n<question line>" (example lines may follow): the why
# says what the answer is used for in this interview, then exactly ONE
# question, and no "없으면 ..." fallback ask (the fallback is the next
# move). Domain-suffixed steps (_MOVE_DOMAIN_STEPS, e.g. ask_activity.health)
# are data asks too. Gated by move_copy_problems -- the kit's tables at
# import, a pack's override bundle in its own tests -- and a non-conforming
# override is passed over at render when a conforming layer exists.
_MOVE_ASK_KEYS = ("ask_training", "confirm_activity", "confirm_activity_tr",
                  "ask_baseline.inbody", "ask_baseline.height",
                  "ask_baseline.weight", "ask_baseline.approx",
                  "inbody_stale", "inbody_carry_ask",
                  "ask_demographics.age", "ask_demographics.sex",
                  "ask_safety", "ask_safety_records", "ask_sex",
                  "ask_feasibility", "direction_adjust_ask",
                  "direction_confirm", "direction_confirm_one",
                  "direction_change_ask", "prac_open", "prac_open_plain")
# A why line ends on the use, never on announcing the ask (owner 08:39:
# "먼저 경력을 확인할게요" is not a why); a second ask offered for the "no"
# case.
_ASK_BARE_LEAD_RE = re.compile(r"(확인할게요|여쭤볼게요|여쭐게요)[.!]?$")
_ASK_FALLBACK_RE = re.compile(r"없으면|없으시면|(?i:\bif not\b)")
# Escape hatches the tool never offers (K8, D5b): the user may say "later"
# and is heard, but no rendered line and no button proposes it.
_MOVE_ESCAPE_TERMS = ("나중에", "다음에 할게", "나중에 할게")
# R3 (owner 2026-09-27): the user never hears how the trend is made -- no
# reading count ("최근 4번"), no narrowing of a range, no averaging talk.
# The tool still judges on the trend; the words say "요즘".
_MOVE_MECHANISM_RE = re.compile(r"최근 (\{[a-z0-9_]+\}|\d+)번|\{k2?\}번|"
                                r"\{need\}번|좁히|좁혀|\d+번 뒤|평균으로 봐")
# Any emoji at all in consult copy (journey 2026-09-26: option markers and
# cheer icons included) -- the hand-gesture rule below is the older, wider
# spoken-form gate for every kit line.
_MOVE_EMOJI_RE = re.compile("[\u2600-\u27bf\U0001f000-\U0001faff"
                            "\u2b50\u2b55\u2705\u274c\u2728]")
# Hand-gesture emoji (owner 2026-09-26 13:49: emoji are fine, hand signs are
# not -- thumbs, pointing, waving, folded hands, OK/victory signs, skin-tone
# modifiers that ride them). Every other emoji (the option markers above
# included) may be spoken.
_HAND_EMOJI_RE = re.compile("[\u261d\u270a-\u270d"
                            "\U0001f446-\U0001f450\U0001f485"
                            "\U0001f590\U0001f595\U0001f596"
                            "\U0001f64b\U0001f64c\U0001f64f"
                            "\U0001f90c\U0001f90f\U0001f918-\U0001f91f"
                            "\U0001f932\U0001faf0-\U0001faf8"
                            "\U0001f3fb-\U0001f3ff]")


def _spoken_form_ok(text):
    """None when a spoken line is allowed, else the reason: no hand-gesture
    emoji, no code block, no backslash escape (a literal backslash reaches the
    user as-is on the channel)."""
    t = str(text or "")
    if _HAND_EMOJI_RE.search(t):
        return "hand-gesture emoji"
    if "```" in t:
        return "code block"
    if "\\" in t:
        return "backslash escape"
    return None


_EXAMPLES_HEADS = ("예)", "e.g.")


def _ends_on_decision(text):
    """True when the last spoken line is a question. Example answers ("예)"
    and the "• " lines under it) may follow the question, and so may the one
    free-input line of a question whose answers are buttons (_spoken_lines)."""
    lines = _spoken_lines(text)
    return bool(lines) and lines[-1].endswith("?")


def _spoken_lines(text):
    """The non-empty spoken lines of a template, example lines and the
    closing free-input line of a buttons question excluded."""
    lines = [ln.strip() for ln in str(text or "").split("\n")]
    lines = [ln for ln in lines if ln]
    for head in _EXAMPLES_HEADS:
        if head in lines:
            lines = lines[:lines.index(head)]
    lines = [ln for ln in lines if not ln.startswith("ex)")]
    if len(lines) > 1 and not lines[-1].endswith("?") and \
            lines[-1] in _free_input_lines():
        lines = lines[:-1]
    return lines


def _is_move_ask(key):
    """True when goal.move.<key> asks the user for data (_MOVE_ASK_KEYS or a
    domain-suffixed step such as ask_activity.health)."""
    step, _, dom = str(key).partition(".")
    return key in _MOVE_ASK_KEYS or (step in _MOVE_DOMAIN_STEPS and bool(dom))


def ask_shape_problem(text):
    """None when a data-ask template is "<why line>\n<one question>", else
    the reason. The why line states what the answer is used for (no '?', not
    a bare "확인할게요" lead); the question line is the only '?' in the
    spoken text; no "없으면 ..." fallback ask rides along."""
    lines = _spoken_lines(text)
    if len(lines) != 2:
        return "not one why line + one question line"
    why, q = lines
    if "?" in why:
        return "the why line asks"
    if _ASK_BARE_LEAD_RE.search(re.sub(r"\{[a-z_]+\}", "", why).strip()):
        return "the why line names no use"
    if q.count("?") != 1 or not q.endswith("?"):
        return "not exactly one question"
    if _ASK_FALLBACK_RE.search(why + " " + q):
        return "a fallback ask in the same message"
    return None


def move_copy_problems(table, src="copy"):
    """Every gate violation in a {move key: template} table, as strings ([]
    = clean).  The kit gates its own tables at import (_move_copy_gate); a
    pack gates the copy it supplies with this same function in its tests --
    pack copy is never gated at kit import (a bad pack must not break the
    kit; a bad pack template is skipped at render instead)."""
    out = []
    for k, v in table.items():
        if not isinstance(v, str):
            out.append('%s %s: not a string' % (src, k))
            continue
        low = re.sub(r"\{[a-z_]+\}", "", v).lower()   # placeholders are not speech
        for tok in _MOVE_UNSPEAKABLE:
            if tok in low:
                out.append('internal vocabulary %r in %s move copy %s'
                           % (tok, src, k))
        bad = _spoken_form_ok(v)
        if bad is not None:
            out.append('%s in %s move copy %s' % (bad, src, k))
        # the owner's '--' and escape-hatch rulings (2026-09-26 18:19, K8)
        if " -- " in v or v.rstrip().endswith(" --"):
            out.append("'--' in %s move copy %s" % (src, k))
        for tok in _MOVE_ESCAPE_TERMS:
            if tok in v:
                out.append('escape hatch %r in %s move copy %s'
                           % (tok, src, k))
        if _MOVE_MECHANISM_RE.search(v):
            out.append('trend mechanism words in %s move copy %s' % (src, k))
        if _MOVE_EMOJI_RE.search(v):
            out.append('emoji in %s move copy %s' % (src, k))
    for k in _MOVE_DECISION_KEYS:
        if k in table and isinstance(table[k], str) and \
                not _ends_on_decision(table[k]):
            out.append('%s move copy %s does not end on the next decision'
                       % (src, k))
    for k, v in table.items():
        if isinstance(v, str) and _is_move_ask(k) and \
                not k.endswith(".buttons"):
            bad = ask_shape_problem(v)
            if bad is not None:
                out.append('%s move copy %s (data ask): %s' % (src, k, bad))
    return out


def _move_copy_gate():
    # The code table, and the ko bundle's goal.move.* values (the copy a
    # Korean user hears when no pack supplies the key).  A decision key the
    # kit carries no copy for (a domain-suffixed step) is the pack's to gate.
    # A ".buttons" key is a list of answer labels (owner 2026-10-05 10:45),
    # not a why + question sentence: labels are gated by _copy_labels.
    ko = {k[len("goal.move."):]: v for k, v in _i18n_bundle("ko").items()
          if k.startswith("goal.move.") and isinstance(v, str)
          and not k.endswith(".buttons")}
    probs = move_copy_problems(_MOVE_COPY, "code") + \
        move_copy_problems(ko, "ko.json")
    assert not probs, probs[0]


_move_copy_gate()


# The bridge renders a button as "N. label" and keeps the whole row only
# when every label fits about 31 widths (CJK counts 1.5); one overflow turns
# every button of the keyboard into a bare number.
_BUTTON_WIDTH_MAX = 31


def _button_width(text):
    return sum(1.5 if ord(ch) > 0x2E7F else 1 for ch in str(text))


def _rec_label(title, n):
    """The recommended option's button: its title with the (추천) marker
    (owner 2026-10-01: the marker rides the button too), the bare title
    when the marked row would not fit."""
    marked = _move_text("opt_rec", title=title)
    if _button_width("%d. %s" % (n, marked)) <= _BUTTON_WIDTH_MAX:
        return marked
    return title


def _option_lines(n, title, desc, plus, minus, rec=False, calendar=(),
                  extra=()):
    """One option of a decision move: the bold heading, the one-line
    description under it (plus any extra plain line, e.g. the protein of a
    pace), the week calendar (if any) as the only quoted lines, then the pro
    and con lines as plain text."""
    t = _move_text("opt_rec", title=title) if rec else title
    out = [_move_text("opt_title", n=n, title=t),
           _move_text("opt_desc", text=desc)]
    out += [_move_text("opt_desc", text=x) for x in extra]
    out += ["> %s" % ln for ln in calendar]
    out.append(_move_text("opt_plus", text=plus))
    out.append(_move_text("opt_minus", text=minus))
    return out



