def _uniq(items):
    """Items in order, each once (two safety rows on one site -- e.g. a
    side and a note -- read '우측 무릎 · 우측 무릎' on the card, live
    2026-10-01)."""
    seen = []
    for x in items:
        if x not in seen:
            seen.append(x)
    return seen


def _card_sites_uniq(text, conn=None):
    """Normalize a saved safety list and drop repeats. Legacy middle-dot
    lists remain readable; repeated sites are re-read from active records
    so a duplicated first site cannot hide another site."""
    if not text:
        return text
    parts = [p.strip() for p in re.split(r"\s*(?:\u00b7|/)\s*", str(text)) if p.strip()]
    if len(_uniq(parts)) == len(parts):
        return " / ".join(parts)
    recs = _safety_records(conn) if conn is not None else []
    if recs:
        return " / ".join(_uniq(r["site"] for r in recs))
    return " / ".join(_uniq(parts))


def _card_words(text, cap=None):
    """One card line's words, cut to fit (card phrase first, else raw)."""
    cap = cap or _CARD_WORDS_MAX
    t = " ".join(str(text or "").replace("\\", " ").replace("\u00b7", "/").split())
    if len(t) > cap:
        t = t[:cap - 1].rstrip() + "…"
    return t or None


def _card_training(words):
    """The training-age item: the card_training template around the words,
    its fixed word dropped when the words already carry it (live
    2026-09-29: the phrase "경력 8년" in "경력 {words}" -> "경력 경력 8년")."""
    fixed = " ".join(_move_text("card_training", words="").split())
    w = " ".join(str(words).split())
    if fixed and fixed.lower() in w.lower():
        return w
    return _move_text("card_training", words=w)


def _card_short(metric):
    if metric in _CARD_SHORT:
        return _CARD_SHORT[metric]
    return _metric_label(metric)[0]


def _card_date(iso):
    try:
        d = datetime.date.fromisoformat(str(iso)[:10])
    except ValueError:
        return str(iso)
    return _move_text("card_date", y=d.year, m=d.month, d=d.day)


def _card_deadline(iso, today=None):
    """'2026년 12월 19일 (12주 남음)' -- whole weeks left, counted from today."""
    try:
        d = datetime.date.fromisoformat(str(iso)[:10])
    except ValueError:
        return None
    today = today or datetime.date.today()
    days = (d - today).days
    if days < 0:
        return _move_text("card_deadline_past", y=d.year, m=d.month, d=d.day)
    return _move_text("card_deadline", y=d.year, m=d.month, d=d.day,
                      weeks=days // 7)


def _has_body_reading(conn):
    if any(_metric_current_value(conn, m)[0] is not None
           for m in _CARD_BODY_METRICS):
        return True
    return _config_stored(conn, "weight_kg") is not None


def _card_body(conn, st):
    """Body line: weight, skeletal muscle, body fat off the latest readings
    and their latest date, else the height / weight the user stated, else
    'none yet' once declined."""
    items, dates = [], []
    for m in _CARD_BODY_METRICS:
        cur, as_of = _metric_current_value(conn, m)
        if cur is None:
            continue
        if m == "body_weight":
            items.append(_move_text("card_body_weight", value=_fmeas(cur)))
        else:
            item = _move_text("card_body_item", mlabel=_card_short(m),
                              value=_fmeas(cur), unit=_metric_label(m)[1])
            if m == "skeletal_muscle_kg" and str(as_of)[:10] in (
                    water_flags(conn).get("flags") or {}):
                # R3: this reading moved with body water
                item = _move_text("card_water", value=item)
            items.append(item)
        dates.append(str(as_of))
    h = _config_stored(conn, "height_cm")
    if items:
        return _move_text("card_body_dated",
                          items=_move_text("card_sep").join(items),
                          as_of=_card_date(max(dates)))
    parts = []
    if h:
        parts.append(_move_text("card_body_height", h=h))
    w = _config_stored(conn, "weight_kg")
    if w:
        parts.append(_move_text("card_body_weight", value=w))
    if parts:
        return _move_text("card_sep").join(parts)
    if set(st.get("unknown") or []) & set(_CARD_BODY_METRICS):
        return _move_text("card_body_none")
    return None


def _safety_parts(text):
    """[(site or None, rest)] from a safety answer ('; '-joined per site)."""
    out = []
    for p in re.split(r"[;；]", str(text or "")):
        p = " ".join(p.split())
        if not p:
            continue
        words = p.split(" ")
        side = words[0] if words[0] in _CARD_SIDES and len(words) > 1 else None
        head = words[1] if side else words[0]
        rest = words[2:] if side else words[1:]
        site = next((s for s in sorted(_CARD_SITES, key=len, reverse=True)
                     if head == s or (head.startswith(s)
                                      and head[len(s):] in ("이", "가", "은",
                                                            "는", "도"))),
                    None)
        site = _SITE_WORD_CANON.get(site, site)
        if site and rest:
            out.append(((side + " " if side else "") + site, " ".join(rest)))
        else:
            out.append((None, p))
    return out


def _card_safety(text):
    if text == "none":
        return _move_text("card_safety_none")
    shown = []
    for site, rest in _safety_parts(text):
        if site:
            shown.append(_move_text("card_safety_site", site=site,
                                    words=_card_words(rest)))
        else:
            shown.append(_card_words(rest))
    return ", ".join(x for x in shown if x) or None


def _safety_sites(st):
    """The body sites named in the safety answer (for the care line)."""
    saf = (st.get("safety") or {}).get("text")
    if not saf or saf == "none":
        return []
    return [s for s, _r in _safety_parts(saf) if s]


def _strand_kind(conn, st, axis):
    """'measured' | 'practice' | 'care' | None for one strand."""
    if axis["metric"] and not _metric_is_program(conn, axis["metric"]):
        return "measured"
    kind = (st.get("strand_kind") or {}).get(axis["axis_key"])
    if kind in _STRAND_KINDS:
        return kind
    if axis["metric"] or axis.get("domain") == "health":
        return "practice"
    return None


def _card_items_order(conn, st, axes):
    """항목 order = the order the interview fills them: measured body
    strands by phase, the other measured strands, practice, care."""
    def rank(a):
        kind = _strand_kind(conn, st, a)
        if kind == "measured":
            grp = 0 if _metric_is_body(conn, a["metric"]) else 1
        else:
            grp = {"practice": 2, "care": 3}.get(kind, 4)
        return (grp, a["phase_order"] or 99, a["rank"])
    return sorted(axes, key=rank)


def _card_goal_value(g):
    """The strand's number, short: '골격근 37.2~38.0kg', '3대 합계 350kg',
    '체지방 14.4~15.4kg (약 18~19%)' (A7: body fat shown in kg)."""
    m = g.get("metric") or ""
    ml, u = _card_short(m), _metric_label(m)[1]
    if g.get("target_value") is None:
        return _move_text("card_goal_pending", mlabel=ml)
    det = g.get("detail")
    lo = _num(_detail_get(det, "range_lo"), None)
    hi = _num(_detail_get(det, "range_hi"), None)
    klo = _num(_detail_get(det, "kg_lo"), None)
    khi = _num(_detail_get(det, "kg_hi"), None)
    if klo is not None and khi is not None and lo is not None and \
            hi is not None:
        return _move_text("card_goal_fat_kg", mlabel=ml, lo=_frange(klo),
                          hi=_frange(khi), plo=int(round(lo)),
                          phi=int(round(hi)))
    if lo is None or hi is None or abs(lo - hi) < 1e-9:
        return _move_text("card_goal_one", mlabel=ml,
                          value=(_fmeas(g["target_value"]) if m in _RATE_METRICS else
                                 ("%.3f" % g["target_value"]).rstrip("0").rstrip(".")), unit=u)
    return _move_text("card_goal", mlabel=ml, lo=_frange(lo),
                      hi=_frange(hi), unit=u)


def _card_lift(g):
    """R1 card line of a per-session progression."""
    u = _metric_label(g.get("metric") or "")[1]
    base = g.get("baseline_value")
    if base is None:
        return _move_text("card_lift_pending")
    stretch = _num(_detail_get(g.get("detail"), "stretch_value"), None)
    if stretch is not None:
        return _move_text("card_lift_stretch", value=_fmeas(base), unit=u,
                          stretch=_fmeas(stretch))
    return _move_text("card_lift", value=_fmeas(base), unit=u)


def _card_goal(g):
    m = g.get("metric") or ""
    ml, u = _card_short(m), _metric_label(m)[1]
    if _detail_get(g.get("detail"), "habit_adoption"):
        return _move_text("habit.card.cap" if g["rule_period"] == "month"
                          else "habit.card", value=_fmeas(g["target_value"]),
                          unit=_habit_unit(None, g["metric"]),
                          period=_move_text("habit.period." + g["rule_period"]))
    if _is_progression_goal(g):
        return _card_lift(g)
    if g.get("target_value") is None:
        return _move_text("card_goal_pending", mlabel=ml)
    lo = _num(_detail_get(g.get("detail"), "range_lo"), None)
    hi = _num(_detail_get(g.get("detail"), "range_hi"), None)
    held = _detail_get(g.get("detail"), "phase") == "maintain"
    if not held:
        return _card_goal_value(g)
    if lo is None or hi is None or abs(lo - hi) < 1e-9:
        return _move_text("card_goal_hold", mlabel=ml,
                          value=_fmeas(g["target_value"]), unit=u)
    return _move_text("card_goal_maintain", mlabel=ml, lo=_frange(lo),
                      hi=_frange(hi), unit=u)


def _card_strand_value(conn, st, a, goals, deferred=()):
    g = goals.get(a["axis_key"])
    if g is not None and _detail_get(g.get("detail"), "tracking") != "session":
        return _card_goal(g)
    if a["axis_key"] in deferred:
        return _move_text("card_next_phase")
    kind = _strand_kind(conn, st, a)
    if kind == "practice" and (st.get("practice") or {}).get(a["axis_key"]):
        phrase = ((st.get("card") or {}).get("practice") or {}).get(
            a["axis_key"])
        pick = (st.get("practice_pick") or {}).get(a["axis_key"])
        proposal = (st.get("practice_proposals") or {}).get(a["axis_key"])
        if proposal and pick:
            selected = pick if isinstance(pick, list) else [pick]
            cards = {o["id"]: o["card"] for o in proposal["options"]}
            if all(p in cards for p in selected):
                return _move_text("card_sep").join(cards[p] for p in selected)
        if isinstance(pick, list):
            return _move_text("card_sep").join(
                _move_text("card_prac." + p) for p in pick)
        if phrase:
            return _card_words(phrase)
        if pick in _PRACTICE_ALL_PICKS:
            return _move_text("card_prac." + pick)
        return _move_text("card_practice")
    care = (st.get("care") or {}).get(a["axis_key"])
    if kind == "care" and care:
        return (_move_text("card_care") if care == "yes"
                else _card_words(care))
    if kind is None:
        return _move_text("card_carried")
    return None


def _card_cadence(conn, st, goals):
    """측정 line: the body metrics' declared cadence as ONE InBody item (they
    come off one reading), any other metric's on its own, 'not set' when the
    user declined. Read-only -- metric_cadence_state would declare a
    fixed-class row."""
    declined = st.get("cadence_declined") or {}
    body, other, seen = {}, [], set()
    for g in goals.values():
        m = g.get("metric")
        if not m or m in seen:
            continue
        seen.add(m)
        row = conn.execute("SELECT stale_after_hours FROM metric_freshness "
                           "WHERE metric=?;", (m,)).fetchone()
        if row is not None:
            h = float(row[0])
            cad = _CADENCE_KO.get(h, "%s시간마다" % _fh(h))
            if _metric_is_body(conn, m):
                body.setdefault(cad, []).append(m)
            else:
                other.append(_move_text("card_cadence", mlabel=_card_short(m),
                                        cadence=cad))
        elif declined.get(m):
            other.append(_move_text("card_cadence_declined",
                                    mlabel=_card_short(m)))
    out = []
    for cad, ms in body.items():
        key = ("card_cadence_weight" if ms == ["body_weight"]
               else "card_cadence_inbody")
        out.append(_move_text(key, cadence=cad))
    return _move_text("card_sep").join(out + other) or None


def _phase_split(conn, axes, measured):
    """(pair, deferred keys, grow_later keys, held keys, together) for the
    current phase, read off the strands' phase order."""
    pair = _tension_pair(measured)
    deferred, grow_later, held, together = [], [], [], False
    if pair:
        d, s_ = pair
        if d["phase_order"] is not None and s_["phase_order"] is not None:
            if d["phase_order"] == s_["phase_order"]:
                together = True
            else:
                later = d if d["phase_order"] > s_["phase_order"] else s_
                grow_later = [later["axis_key"]]
                if later is s_:
                    held = [s_["axis_key"]] + [
                        a["axis_key"] for a in measured
                        if a is not d and a is not s_
                        and not _metric_is_body(conn, a["metric"])
                        and not _is_progression(conn, a)]
                else:
                    deferred = [later["axis_key"]]
    return pair, deferred, grow_later, held, together


def _move_card(conn, domain, mv):
    """The onboarding card for one spoken move (approved shape 2026-09-26
    17:18): [지향] / [현재] / [목표], filled from stored data, the slot this
    move asks in bold. An empty slot is its label alone (A6). A domain shows
    only the slots it has a move for (현재's 몸 / 주의 are health's; 순서 only
    when two strands pull apart). The strand names are the user's own words
    everywhere, the order line included (A5)."""
    dom = domain or "health"
    wid = mv.get("why_id")
    st = _move_state(conn, wid) if wid is not None else {}
    axes = _user_axes(conn, domain, wid) if wid is not None else []
    goals = _why_goals(conn, wid) if wid is not None else {}
    key = mv.get("axis_key")
    pending = goals.get(key)
    if dom == "health" and mv.get("kind") == "propose_pace" and \
            _metric_is_body(conn, mv.get("metric")) and \
            pending is not None and pending.get("target_value") is None:
        # An unaccepted target renders like the ordinary first proposal.
        # Keep the stored placeholder until the existing choice accepts it.
        goals.pop(key)
    measured = [a for a in axes if a["metric"]
                and not _metric_is_program(conn, a["metric"])]
    pair, deferred, _gl, _held, _tog = _phase_split(conn, axes, measured)
    now = _CARD_ASKS.get(mv.get("kind"))
    now_axis = None
    if mv.get("kind") == "ask_baseline":
        if mv.get("axis_key"):
            now_axis = mv["axis_key"]
        else:
            now = "body"
    elif mv.get("kind") in _CARD_STRAND_ASKS:
        now_axis = mv.get("axis_key")
    T = _move_text

    def item(slot, value):
        name = T("card." + slot)
        if not value:
            return T("card_item_now_empty" if slot == now
                     else "card_item_empty", name=name)
        return T("card_item_now" if slot == now else "card_item",
                 name=name, value=value)

    why_text = _why_text(conn, wid) if wid is not None else None
    qlabel = {a["axis_key"]: _strand_info(conn, st, a, why_text)["label"]
              for a in axes}
    lines = [T("card_title", name=T("card.aim"))]
    # one strand per line, each a top bullet (owner 2026-10-01: the
    # ' / '-joined line read as one cramped run).
    lines += [T("card_item_head", name=qlabel[a["axis_key"]]) for a in axes]
    now_lines = []
    cw = st.get("card") or {}
    if _move_has("ask_activity.%s" % dom):
        act = _card_words(cw.get("activity") or st.get("activity"))
        tr = _card_words(cw.get("training") or st.get("training"))
        if mv.get("kind") == "confirm_activity":
            ff = st.get("facts_from") or {}
            fcw = ff.get("card") or {}
            act = _card_words(fcw.get("activity") or ff.get("activity"))
            tr = _card_words(fcw.get("training") or ff.get("training"))
        if not tr and act:
            band = _config_stored(conn, _EXP_KEY)
            if band in _EXP_BANDS:
                tr = T("exp_band." + band)
        if act and tr:
            act = T("card_sep").join([act, _card_training(tr)])
        now_lines.append(item("activity", act))
    if dom == "health":
        now_lines.append(item("body", _card_body(conn, st)))
        saf = (st.get("safety") or {}).get("text")
        if saf and saf != "none" and cw.get("safety"):
            saf_shown = _card_words(_card_sites_uniq(cw["safety"], conn),
                                    _CARD_SAFETY_MAX)
        else:
            saf_shown = _card_safety(saf) if saf else None
        if saf_shown is None and now == "safety":
            recs = _safety_records(conn)
            if recs:
                saf_shown = T("card_sep").join(_uniq(r["site"] for r in recs))
        now_lines.append(item("safety", saf_shown))
    if now_lines:
        lines += [T("card_gap"), T("card_title", name=T("card.now"))]
        lines += now_lines
    lines += [T("card_gap"), T("card_title", name=T("card.goal"))]
    # K6: this phase's items each carry their own date when the dates
    # differ; one deadline line when they agree.
    phase_goals = {k: g for k, g in goals.items()
                   if k not in deferred and g.get("horizon_date")}
    dates = sorted({str(g["horizon_date"])[:10]
                    for g in phase_goals.values()})
    per_item = len(dates) > 1
    if not per_item:
        lines.append(item("deadline",
                          _card_deadline(dates[0]) if dates else None))
    if pair:
        lines.append(item("order", _order_mode_line(st, pair, True)[0]))
    if axes:
        lines.append(T("card_item_head", name=T("card.items")))
        for a in _card_items_order(conn, st, axes):
            val = _card_strand_value(conn, st, a, goals, deferred)
            g = phase_goals.get(a["axis_key"])
            if per_item and val and g is not None:
                val = T("card_due", value=val,
                        date=_card_date(g["horizon_date"]))
            is_now = a["axis_key"] == now_axis
            if val:
                lines.append(T("card_sub_now" if is_now else "card_sub",
                               name=qlabel[a["axis_key"]], value=val))
            else:
                lines.append(T("card_sub_now_empty" if is_now
                               else "card_sub_empty",
                               name=qlabel[a["axis_key"]]))
    else:
        lines.append(item("items", None))
    if dom == "health" and st.get("diet_target"):
        diet = st["diet_target"]
        value = (T("diet_pending") if diet.get("pending") else
                 T("diet_line", kcal=diet["kcal"], protein=diet["protein"]))
        lines.append(item("diet", value))
    lines.append(item("cadence", _card_cadence(conn, st, goals)))
    return "\n".join(lines)


def reading_notes(conn):
    """R3: [{metric, date, value, kind: off|water, dir, line}] for the latest
    reading of each judged body metric that is off its trend beyond one
    reading's noise, or (skeletal muscle) moved with body water. The water
    note replaces the off note for the same reading."""
    out = []
    for m in _READING_CHECK_METRICS:
        if _metric_source(conn, m) is None:
            continue
        lc = metric_judged(conn, m).get("latest_check")
        if not lc or not (lc.get("water") or lc.get("off")):
            continue
        ml, unit = _card_short(m), _metric_label(m)[1]
        date = _fmt_date_ko(lc["date"])
        if lc.get("water"):
            kind, dir_ = "water", lc["water"]
            line = _move_text("reading_water." + dir_, date=date, mlabel=ml)
        else:
            kind, dir_ = "off", lc["off"]
            v = _fmeas(lc["value"])
            line = _move_text("reading_off." + dir_, date=date, mlabel=ml,
                              value=v, unit=unit, eun=_josa(v + unit, "eun"))
        out.append({"metric": m, "date": lc["date"], "value": lc["value"],
                    "trend": lc["trend"], "band": lc["band"], "kind": kind,
                    "dir": dir_, "line": line})
    return out


def _fold_readback(conn, wid, mv):
    """Put the pending confirmations at the head of this move's readback.

    Since the card (2.28.x) the only queued line is a strand-direction
    correction (axis-direction); the strands, the answers and an accepted
    proposal are confirmed by their filled lines on the card. Each line is spoken ONCE, on the first move that speaks after it was
    produced: the move state remembers which move (by signature) carried it,
    so re-rendering that same move repeats it and any later move does not.
    A silent move (no say, no hand-off) carries nothing. The same holds for
    the direction's opening readback (records, carried strands)."""
    st = _move_state(conn, wid)
    shown = dict(st.get("shown") or {})
    sig = _move_sig(mv)
    speaks = bool(mv.get("say")) or bool(mv.get("delegate"))
    changed = False

    def once(tag):
        nonlocal changed
        cur = shown.get(tag)
        if cur is None:
            if not speaks:
                return False
            shown[tag] = sig
            changed = True
            return True
        return cur == sig

    head = [c["line"] for c in (st.get("carry") or [])
            if once("carry:%s" % c["id"])]
    # R3: a new reading off its trend (or moved with body water) is named
    # once, plainly, on the first move that speaks after it arrived.
    notes = reading_notes(conn)
    head += [n["line"] for n in notes
             if once("reading:%s:%s" % (n["metric"], n["date"]))]
    if notes:
        mv["reading_notes"] = notes
    intro = list(mv.get("readback") or [])
    if intro and not once("intro"):
        intro = []
    mv["readback"] = head + intro
    if changed:
        st["shown"] = shown
        _move_state_put(conn, wid, st)
        conn.commit()
    return mv


# ── records the journey reads: the calendar, the safety rows ───────────────

_WEEKDAY_CODES = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN")
_WEEKDAY_KO = ("월", "화", "수", "목", "금", "토", "일")
_EXERCISE_WORDS = re.compile("헬스|운동|세션|웨이트|workout|gym|training",
                             re.I)
_MEASURE_WORDS = re.compile("체중|인바디|측정|weigh|inbody", re.I)


def _cadence_weekdays(cadence):
    """[0..6] from a routine cadence 'W:MON,WED!hol'; [] when not weekly."""
    c = str(cadence or "").split("!")[0]
    if not c.startswith("W:"):
        return []
    out = []
    for tok in c[2:].split(","):
        tok = tok.strip().upper()
        if tok in _WEEKDAY_CODES:
            out.append(_WEEKDAY_CODES.index(tok))
    return sorted(set(out))


def calendar_windows(conn, owning_agent=None, kind="exercise"):
    """The active timed routines of one kind on the calendar: 'exercise'
    (헬스/운동 slots) or 'measure' (체중/인바디). With owning_agent: only that
    agent's rows (none -> []). Without: every row of that kind. Read-only.

    -> [{id, title, weekdays: [0..6], start 'HH:MM', end 'HH:MM', since}]"""
    try:
        rows = conn.execute(
            "SELECT id, title, COALESCE(purpose,''), cadence, time_of_day, "
            "duration_min, start_date, owning_agent FROM routine_def WHERE "
            "status='active' AND schedule_kind='timed' ORDER BY id;"
        ).fetchall()
    except sqlite3.OperationalError:
        return []
    picked = []
    for rid, title, purpose, cad, tod, dur, start, agent in rows:
        is_measure = bool(_MEASURE_WORDS.search(title or ""))
        is_ex = (not is_measure and
                 bool(_EXERCISE_WORDS.search("%s %s" % (title, purpose))))
        if (kind == "measure" and not is_measure) or \
                (kind == "exercise" and not is_ex):
            continue
        days = _cadence_weekdays(cad)
        if not days or not tod:
            continue
        try:
            h, mi = [int(x) for x in str(tod).split(":")[:2]]
        except ValueError:
            continue
        end_min = h * 60 + mi + int(dur or 0)
        picked.append({"id": rid, "title": title, "weekdays": days,
                       "start": "%02d:%02d" % (h, mi),
                       "end": "%02d:%02d" % ((end_min // 60) % 24,
                                             end_min % 60),
                       "since": str(start)[:10], "owning_agent": agent})
    if owning_agent:
        # Only this agent's own rows: another agent's routine must never be
        # quoted as "your calendar" (journey-pack review 2026-09-27).
        picked = [w for w in picked if w["owning_agent"] == owning_agent]
    return picked


def _days_compact(days):
    """[1,2,3,4] -> '화~금'; [0,2,4] -> '월·수·금'; [5,6] -> '토·일'."""
    runs, cur = [], []
    for d in sorted(days):
        if cur and d == cur[-1] + 1:
            cur.append(d)
        else:
            if cur:
                runs.append(cur)
            cur = [d]
    if cur:
        runs.append(cur)
    out = []
    for r in runs:
        if len(r) >= 3:
            out.append("%s~%s" % (_WEEKDAY_KO[r[0]], _WEEKDAY_KO[r[-1]]))
        else:
            out.extend(_WEEKDAY_KO[x] for x in r)
    return "/".join(out)


def _days_band(days):
    s = set(days)
    if s == set(range(7)):
        return _move_text("cal_every_day")
    if s == set(range(5)):
        return _move_text("cal_weekdays")
    if s == {5, 6}:
        return _move_text("cal_weekend")
    return _days_compact(days)


def _hours_text(start, end):
    h1, m1 = [int(x) for x in start.split(":")]
    h2, m2 = [int(x) for x in end.split(":")]
    if m1 == 0 and m2 == 0:
        return _move_text("cal_hours", h1=h1, h2=h2)
    return _move_text("cal_hm", h1=start, h2=end)


def _calendar_lead(conn, owning_agent):
    """('평일 아침', '헬스') for the G2 lead, or None."""
    wins = calendar_windows(conn, owning_agent)
    if not wins:
        return None
    days = sorted({d for w in wins for d in w["weekdays"]})
    starts = [int(w["start"][:2]) for w in wins]
    if all(h < 12 for h in starts):
        band = _move_text("cal_morning")
    elif all(12 <= h < 17 for h in starts):
        band = _move_text("cal_daytime")
    elif all(h >= 17 for h in starts):
        band = _move_text("cal_evening")
    else:
        band = None
    when = _days_band(days) + (" " + band if band else "")
    titles = []
    for w in wins:
        if w["title"] not in titles:
            titles.append(w["title"])
    return when, "/".join(titles)


def calendar_line(conn, owning_agent=None):
    """A4: '캘린더에는 7월부터 월 6~8시, 화~금 5~7시로 걸려 있어요.' from the
    active workout routines, or None when there are none. The program's
    first question opens with it (the pack speaks it)."""
    wins = calendar_windows(conn, owning_agent)
    if not wins:
        return None
    wins = sorted(wins, key=lambda w: (w["weekdays"][0], w["start"]))
    parts = [_move_text("cal_window", days=_days_compact(w["weekdays"]),
                        hours=_hours_text(w["start"], w["end"]))
             for w in wins]
    since = min(w["since"] for w in wins)
    try:
        sd = datetime.date.fromisoformat(since)
    except ValueError:
        sd = None
    if sd is None or sd > datetime.date.today():
        return _move_text("handoff_calendar_nosince",
                          windows=", ".join(parts))
    return _move_text("handoff_calendar",
                      since=_move_text("cal_month", m=sd.month),
                      windows=", ".join(parts))


_SIDE_WORDS = {"우측": "우측", "오른쪽": "우측", "좌측": "좌측",
               "왼쪽": "좌측", "양쪽": "양쪽"}
_SITE_KO = {"knee": "무릎", "shoulder": "어깨", "foot": "발", "back": "허리",
            "lower_back": "허리", "wrist": "손목", "elbow": "팔꿈치",
            "ankle": "발목", "neck": "목", "hip": "고관절", "calf": "종아리",
            "hamstring": "햄스트링", "plantar": "족저근막"}
# A site word the user says that the kit renders by its precise name:
# "jokjeogeun" (plantar muscle) is how people say the plantar FASCIA, and the
# owner corrected it on 2026-10-06 (the life agent asked fascia vs muscle; answer: fascia).
# The stored words stay verbatim; only the rendered site name is canonical.
_SITE_WORD_CANON = {"\uc871\uc800\uadfc": "\uc871\uc800\uadfc\ub9c9"}
_PARTICLES = ("이", "가", "은", "는", "도", "을", "를")


def _safety_site_name(key, value):
    """'우측 무릎' from (injury_<site>_<side>, '우측 무릎이 가끔 ...'): the words the
    user used for the site, else the key's site."""
    words = str(value or "").split()
    side = None
    i = 0
    if words and words[0] in _SIDE_WORDS:
        side = _SIDE_WORDS[words[0]]
        i = 1
    site = None
    if len(words) > i:
        w = words[i]
        if len(w) > 1 and w.endswith(_PARTICLES):
            w = w[:-1]
        if w and len(w) <= 6 and all("가" <= ch <= "힣" for ch in w):
            site = _SITE_WORD_CANON.get(w, w)
    tok = str(key or "")[len("injury_"):]
    kside = None
    if tok.endswith("_r"):
        kside, tok = "r", tok[:-2]
    elif tok.endswith("_l"):
        kside, tok = "l", tok[:-2]
    key_site = _SITE_KO.get(tok)
    if site is not None and key_site and site != key_site \
            and key_site in " ".join(words[i + 1:]):
        # one sentence naming two sites stored on two rows ("우측 무릎
        # 어깨 ...", live 2026-10-01): its first words name the FIRST
        # row's site only -- this row is the key's site, the side word
        # belonged to the other site
        site, side = None, None
    if site is None:
        site = key_site or tok.replace("_", " ")
    if side is None and kside:
        side = _move_text("side." + kside)
    return "%s %s" % (side, site) if side else site


def _safety_records(conn):
    """The active injury rows: [{key, site, value}] (G4 reads these first)."""
    try:
        rows = conn.execute(
            "SELECT key, value FROM ledger_constraint WHERE class='safety' "
            "AND status='active' AND key LIKE 'injury\\_%' ESCAPE '\\' "
            "ORDER BY id;").fetchall()
    except sqlite3.OperationalError:
        return []
    return [{"key": k, "site": _safety_site_name(k, v), "value": v}
            for k, v in rows]


def _sites_joined(sites, compress=False):
    """'우측 무릎·우측 어깨' or, compressed, '우측 무릎·어깨'."""
    if not sites:
        return ""
    if compress:
        heads = {s.split(" ", 1)[0] for s in sites if " " in s}
        if len(heads) == 1 and all(" " in s for s in sites):
            h = heads.pop()
            return h + " " + "/".join(s.split(" ", 1)[1] for s in sites)
    return "/".join(sites)


# ── G7 practice (A8) ─────────────────────────────────────────────────────────
# Which three picks a practice strand is offered is decided by what the strand
# is ABOUT, never shared between strands (owner 2026-09-28 21:13: the 연결
# strand got the 기능성 menu byte for byte, the owner re-typed "1,2 둘다
# 하고싶다고", and that complaint was recorded as the 연결 answer).
# Routing is data, one row per set:
#   key    the set's name (also the suffix of its own set-level copy keys)
#   metrics  the pack-computed measures the set's picks move (a strand linked
#          to one belongs to the set whatever it is called)
#   words  what puts a strand in the set -- matched on its qualifier, name,
#          then on the clause of the direction that names it;
#          never on the whole direction (that is how a menu gets borrowed)
#   picks  its three options (copy: prac_t / prac_d / prac_p / prac_m /
#          card_prac .<pick>)
#   lines  set-level lines spoken after the options
#   two    the "several together, said in words" line (no limit: the
#          owner picks as many as he wants); ask = the closing question
#   rec    recommendation rules in order: ("onesided", pick, copy key) =
#          a one-sided safety record; ("safety", pick, copy key) = any
#          caution on record; ("words", regex, pick, copy key) = the
#          words appear in this strand's qualifier, name or clause ({words}
#          = the word matched); ("default", pick, copy key)
# A strand no row matches -- or whose set an earlier practice strand of the
# same direction already took -- gets ONE open ask in its own words.
#   frame  the line after the strand's picture that says why these options
#          ("frame.<key>" with the strand's clause, "frame_plain.<key>"
#          without one)
# Two sets never share a pick key, and a pick key keeps ONE meaning: a pick
# whose meaning changed gets a new key (the pack composes by key).
# Crossfit-type function is work capacity -- intervals, power, mixed-modal
# circuits -- and never one-side balance / coordination: that is how the
# body links, the connection side (owner 2026-09-29 13:09: 기능성 offered
# 좌우 균형·협응 and read like 연결).
