def _print_move(res):
    """Text mode: SAY lines are the only user-facing output."""
    print("MOVE\t%s\tdone\t%s" % (res["kind"], res["done"]))
    for line in res.get("readback") or []:     # the card is the first
        print("SAY\t%s" % line.replace("\n", "\n\t"))
    if res.get("say"):
        print("SAY\t%s" % res["say"].replace("\n", "\n\t"))
    for k in ("on_yes", "on_answer", "on_proceed", "on_no",
              "if_still_unknown", "on_site", "rebuild_commit"):
        if res.get(k):
            print("CMD\t%s\t%s" % (k, json.dumps(res[k], ensure_ascii=False)))
    for c in res.get("choices") or []:
        print("CHOICE\t%s" % json.dumps(c, ensure_ascii=False))


def cli_goal_interview(argv):
    # goal-interview <goal_id> [--revise <field>] [--json]
    # goal-interview --start [--domain D] [--scope rebuild|adjust|add] [--json]
    # goal-interview --start --intent rebuild [--domain D] [--json]
    # goal-interview --start --said "<owner's words>" [--domain D] [--json]
    # goal-interview --next [--domain D] [--stage] [--json]   (055: the move)
    argv, as_json = _pop_flag(argv, '--json')
    argv, is_start = _pop_flag(argv, '--start')
    argv, is_next = _pop_flag(argv, '--next')
    argv, is_restart = _pop_flag(argv, '--restart')
    argv, intent = _pop_opt(argv, '--intent')
    argv, said = _pop_opt(argv, '--said')
    usage = ("사용법: kit_life.sh goal-interview <goal_id> [--revise <field>] "
             "[--json]  |  kit_life.sh goal-interview --start [--domain D] "
             "[--said \"<words>\" | --scope rebuild|adjust|add | --intent "
             "rebuild] [--json]  |  kit_life.sh "
             "goal-interview --next [--domain D] [--stage] [--json]  |  "
             "kit_life.sh goal-interview --restart --domain D "
             "[--from goal|program] [--json]")
    said_intent = None
    if said is not None:
        if (intent is not None or not is_start or is_next or is_restart
                or '--scope' in argv or '--stage' in argv
                or not said.strip()):
            _err(usage)
        # Owner prose is evidence only. The agent chooses an explicit scope or
        # intent; this compatibility form always opens the neutral fork.
    if intent is not None:
        if (intent != 'rebuild' or not is_start or is_next or is_restart
                or '--scope' in argv or '--stage' in argv):
            _err(usage)
        # An explicit fresh-start request already answers the opening fork.
        # Use the same staged move as choosing rebuild, including its renderer.
        argv = argv + ['--scope', 'rebuild']
    if is_restart:
        # "다시 하자": the ONE path (JOURNEY 7). Archives the unfinished
        # interview, keeps finished goals until the new wrap, returns the
        # first move of the new interview with the restart line.
        argv, domain = _pop_opt(argv, '--domain')
        argv, from_ = _pop_opt(argv, '--from')
        argv, agent = _pop_opt(argv, '--owning-agent')
        if argv or not domain or (from_ or "goal") not in ("goal",
                                                            "program"):
            _err(usage)
        conn = get_conn()
        try:
            res = goal_interview_restart(conn, domain, agent, from_ or "goal")
        finally:
            conn.close()
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
            return
        for a in res["archived"]:
            print("ARCHIVED\twhy\t%d\tstrands\t%s\tgoals\t%s\tkey\t%s"
                  % (a["why_id"], ",".join(a["axes"]) or "-",
                     ",".join(str(x) for x in a["goal_ids"]) or "-",
                     a["archive_key"]))
        print("KEPT\t%s" % (",".join(str(x) for x in res["kept_goal_ids"])
                            or "-"))
        if res.get("next"):
            _print_move(res["next"])
        else:
            print("SAY\t%s" % res["say"])
        return


    if is_next:
        argv, stage = _pop_flag(argv, '--stage')
        argv, domain = _pop_opt(argv, '--domain')
        argv, agent = _pop_opt(argv, '--owning-agent')
        if argv:
            _err(usage)
        conn = get_conn()
        try:
            if stage:
                # A staged move belongs to an OPEN walk (2026-10-10, the health agent:
                # `--next --stage` with none open wrapped the existing card
                # as "done"). A pre-walk restart window still counts.
                w = _rebuild_walk(conn)
                if w is None and _restart_state(conn) is None:
                    _err("goal-interview --next --stage: no staged rebuild "
                         "walk is open -- " + _REBUILD_WALK_HINT
                         % (domain or "<D>"))
                if w is not None and domain and w.get("domain") and \
                        w["domain"] != domain:
                    _err("goal-interview --next --stage: the open rebuild "
                         "walk is for domain %s, not %s -- "
                         % (w["domain"], domain)
                         + _REBUILD_WALK_HINT % domain)
            res = goal_next_move(conn, domain, agent, stage)
        finally:
            conn.close()
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
        else:
            _print_move(res)
        return
    if is_start:
        opt = {}
        i = 0
        while i < len(argv):
            if argv[i] in ("--domain", "--scope", "--owning-agent") and i + 1 < len(argv):
                opt[argv[i][2:]] = argv[i + 1]; i += 2
            else:
                _err(usage)
        if opt.get("scope") and opt["scope"] not in _INTERVIEW_SCOPES:
            _err("goal-interview: --scope must be one of %s"
                 % "|".join(_INTERVIEW_SCOPES))
        if opt.get("scope") == "rebuild":
            # The ONE door into a staged rebuild (fork pick, --intent,
            # --said): open a fresh walk, return its first move. Old goals
            # stay active until the wrap's goal commit.
            conn = get_conn()
            try:
                _rebuild_walk_open(conn, opt.get("domain"),
                                   opt.get("owning-agent"))
                res = goal_next_move(conn, opt.get("domain"),
                                     opt.get("owning-agent"), True)
            finally:
                conn.close()
            if said_intent:
                res["said_intent"] = said_intent
            if as_json:
                print(json.dumps(res, ensure_ascii=False))
            else:
                _print_move(res)
            return
        conn = get_conn()
        try:
            res = goal_interview_start(
                conn, domain=opt.get("domain"), scope=opt.get("scope"),
                owning_agent=opt.get("owning-agent"))
        finally:
            conn.close()
        if said is not None:
            res["said_intent"] = said_intent
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
            return
        if said is not None:
            print("SAID-INTENT\t%s" % (said_intent or "-"))
        print("STAGE\t%s\tfield\t%s\task\t%s\tgoals\t%s"
              % (res["stage"], res.get("field") or "", res.get("ask_kind", ""),
                 res["goal_count"]))
        if res.get("uncovered_axes"):
            print("UNCOVERED\t%s" % ", ".join(res["uncovered_axes"]))
        # The non-JSON path is a real surface (the shell caller reads these
        # lines), so a metric-level gap has to appear here too -- otherwise
        # the fix exists only for --json callers and the TSV reader keeps
        # seeing a fully covered picture.
        if res.get("uncovered_metrics"):
            print("UNCOVERED-METRIC\t%s"
                  % ", ".join("%s/%s" % (m["axis"], m["label"])
                              for m in res["uncovered_metrics"]))
        if res.get("destructive"):
            print("DESTRUCTIVE\tretire\t%s"
                  % ",".join(str(i) for i in res.get("retire_goal_ids") or []))
        if res.get("question"):
            print("Q\t%s" % res["question"].replace("\n", "\n\t"))
        for c in res.get("choices") or []:
            print("  CHOICE\t%s" % json.dumps(c, ensure_ascii=False))
        if res.get("on_answer"):
            print("CMD\ton_answer\t%s"
                  % json.dumps(res["on_answer"], ensure_ascii=False))
        if res.get("next_cmd"):
            print("NEXT\t%s" % json.dumps(res["next_cmd"], ensure_ascii=False))
        for ln in _why_label_ask_lines(res.get("whys") or []):
            print(ln)
        return
    argv, reopen = _pop_opt(argv, '--revise')
    if not argv or not str(argv[0]).isdigit():
        _err(usage)
    if reopen is not None and reopen not in _INTERVIEW_FIELDS:
        _err("goal-interview: --revise must be one of %s"
             % "|".join(_INTERVIEW_FIELDS))
    conn = get_conn()
    try:
        res = goal_interview_next(conn, int(argv[0]), reopen=reopen)
    finally:
        conn.close()
    if res is None:
        _err("goal 없음: %s" % argv[0])
    if as_json:
        print(json.dumps(res, ensure_ascii=False))
        return
    if res["done"]:
        print("DONE\t%s\t%s\trung\t%s"
              % (res.get("commitment_kind") or "goal", res["goal_id"],
                 res["rung_state"]))
        return
    print("STEP\t%s/%s\tfield\t%s\task\t%s"
          % (res["step_no"], res["total_steps"], res["field"],
             res.get("ask_kind", "")))
    if res.get("question"):
        print("Q\t%s" % res["question"])
    else:
        # agent-decided field: no question exists; name the write commands.
        print("DECIDE\t%s" % res.get("note", ""))
        for c in res.get("choices") or []:
            print("  CHOICE\t%s" % json.dumps(c, ensure_ascii=False))
    ki = res.get("kind_inference")
    if ki:
        print("KIND-INFER\t%s\t%s\t%s" % (ki["suggest"], ki["why"],
                                             ki["write_cmd"]))
    if res.get("inferred"):
        print("INFERRED\t%s" % json.dumps(res["inferred"], ensure_ascii=False))


def cli_goal_answer(argv):
    """Execute one issued goal-interview answer, exactly once per value.

    A transport retry receives the byte-identical first receipt and never
    reaches the underlying writer.  The comparison form is Unicode NFC with
    runs of whitespace folded; the original argv remains the write evidence.
    """
    argv, screen_id = _pop_opt(argv, '--screen-id')
    argv, token = _pop_opt(argv, '--answer-token')
    if argv and argv[0] == '--':
        argv = argv[1:]
    if not screen_id or not token or not argv or argv[0] == 'goal-answer':
        _err("goal-answer: issued --screen-id and --answer-token plus a verb are required")
    import hashlib
    import unicodedata
    normalized = [" ".join(unicodedata.normalize("NFC", str(x)).split())
                  for x in argv]
    value_hash = hashlib.sha256(json.dumps(
        normalized, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")).hexdigest()
    receipt_key = "goal_answer_receipt_%s" % hashlib.sha256(
        token.encode("utf-8")).hexdigest()[:24]
    conn = get_conn()
    try:
        old = _config_stored(conn, receipt_key)
        if old:
            receipt = json.loads(old)
            if receipt.get("screen_id") != screen_id:
                _err("goal-answer: token does not belong to this screen")
            if receipt.get("value_hash") == value_hash:
                print(receipt["receipt"])
                return
        issued = False
        for (raw,) in conn.execute(
                "SELECT value FROM config WHERE key LIKE 'goal_answer_active_%';"):
            try:
                active = json.loads(raw)
            except (TypeError, ValueError):
                continue
            if active.get("screen_id") == screen_id and active.get("token") == token:
                issued = True
                break
        if not issued:
            _err("goal-answer: screen is no longer open")
    finally:
        conn.close()
    output = _run_verb(argv)
    receipt_text = json.dumps({"screen_id": screen_id,
                               "answer_token": token,
                               "applied": True},
                              ensure_ascii=False, separators=(",", ":"))
    conn = get_conn()
    try:
        saved = {"screen_id": screen_id, "value_hash": value_hash,
                 "receipt": receipt_text, "writer_output": output}
        _config_put(conn, receipt_key, json.dumps(saved, ensure_ascii=False,
                                                  separators=(",", ":")))
        conn.commit()
    finally:
        conn.close()
    print(receipt_text)

