def cli_goal_rebuild_commit(argv):
    # goal-rebuild-commit --replacing <ids> --with <ids> [--json]
    #
    # The COMMIT half of a create-first rebuild, and the ONLY path that retires
    # on a rebuild. It refuses unless every replacement is real and finished, so
    # an interview abandoned at any point leaves the active set untouched.
    argv, as_json = _pop_flag(argv, '--json')
    argv, old_raw = _pop_opt(argv, '--replacing')
    argv, new_raw = _pop_opt(argv, '--with')
    if not old_raw or not new_raw:
        _err("사용법: kit_life.sh goal-rebuild-commit --replacing <ids> "
             "--with <ids> [--json]")
    def _ids(raw):
        out = []
        for t in str(raw).replace(" ", ",").split(","):
            if t.strip().isdigit():
                out.append(int(t.strip()))
        return out
    old_ids, new_ids = _ids(old_raw), _ids(new_raw)
    if not new_ids:
        _err("goal-rebuild-commit: --with needs at least one replacement id -- "
             "a rebuild that retires everything and puts nothing back is the "
             "failure mode this verb exists to prevent")
    conn = get_conn()
    try:
        # 2026-10-10 (the health agent): the replacement must be a staged walk's answer,
        # not any finished row -- an unchanged copy of the old goal is
        # "finished" too, and it committed.
        walk_bad, problems = _goal_commit_refusals(conn, old_ids, new_ids)
        if walk_bad:
            print("REFUSED\tnot a staged rebuild walk's result; the current "
                  "goals were not retired")
            for p in walk_bad:
                print("  %s" % p)
            print("goals %s stay active. %s"
                  % (",".join(str(i) for i in old_ids) or "-",
                     _REBUILD_WALK_HINT % "<D>"))
            sys.exit(EXISTS_CODE)
        if problems:
            print("REFUSED\t대체 목표가 아직 완성되지 않아 기존 목표를 접지 않았습니다")
            for p in problems:
                print("  %s" % p)
            print("기존 목표 %s 는 그대로 활성 상태입니다."
                  % ",".join(str(i) for i in old_ids))
            sys.exit(EXISTS_CODE)
        _goal_commit(conn, "rebuild", old_ids, new_ids)
        out = {"retired": old_ids, "activated": new_ids}
        if as_json:
            print(json.dumps(out, ensure_ascii=False))
        else:
            print("COMMITTED\tactivated\t%s\tretired\t%s"
                  % (",".join(str(i) for i in new_ids),
                     ",".join(str(i) for i in old_ids)))
            for i in new_ids + old_ids:
                r = _goal_fetch(conn, i)
                if r is not None:
                    print(_goal_line(r))
    finally:
        conn.close()


def cli_hypothesis_add(argv):
    # hypothesis-add --text T --subject-kind insight|why|goal [--subject-id id]
    #   [--domain D] [--sensitivity normal|sensitive] [--owning-agent A]
    o = {}
    keys = {"--text": "text", "--subject-kind": "subject_kind",
            "--subject-id": "subject_id", "--domain": "domain",
            "--sensitivity": "sensitivity", "--owning-agent": "owning_agent"}
    i = 0
    while i < len(argv):
        if argv[i] in keys and i + 1 < len(argv):
            o[keys[argv[i]]] = argv[i + 1]; i += 2
        else:
            _err("사용법: kit_life.sh hypothesis-add --text T --subject-kind "
                 "insight|why|goal [--subject-id id] [--domain D] "
                 "[--sensitivity normal|sensitive] [--owning-agent A]")
    if not o.get("text") or not o.get("subject_kind"):
        _err("hypothesis-add: --text and --subject-kind required")
    if o["subject_kind"] not in ("insight", "why", "goal"):
        _err("hypothesis-add: --subject-kind must be insight|why|goal")
    sens = o.get("sensitivity", "normal")
    if sens not in ("normal", "sensitive"):
        _err("hypothesis-add: --sensitivity must be normal|sensitive")
    conn = get_conn()
    try:
        ulid = new_ulid()
        cur = conn.execute(
            "INSERT INTO hypothesis (ulid, text, subject_kind, subject_id, "
            "confidence, stance, domain, sensitivity, owning_agent) "
            "VALUES (?,?,?,?,?,?,?,?,?);",
            (ulid, o["text"], o["subject_kind"],
             int(o["subject_id"]) if o.get("subject_id") else None,
             0.0, "open", _txt(o.get("domain")), sens,
             (o.get("owning_agent") or _facade_agent())))
        conn.commit()
        print("%s\t%s\t%s\tconf=0.0\tstance=open"
              % (cur.lastrowid, ulid, o["subject_kind"]))
    finally:
        conn.close()


def cli_hypothesis_evidence_add(argv):
    # hypothesis-evidence-add <hypothesis_id> --kind behavior|verbal_affirm|
    #   verbal_deny [--record-id id] [--weight w] [--observed-at ts]
    # Appends one evidence row, then recomputes confidence (behavior >> verbal).
    # weight defaults per kind (tunable constants); pass --weight to override.
    if not argv or not str(argv[0]).isdigit():
        _err("사용법: kit_life.sh hypothesis-evidence-add <hypothesis_id> "
             "--kind behavior|verbal_affirm|verbal_deny [--record-id id] "
             "[--weight w] [--observed-at ts]")
    hid = int(argv[0])
    rest = argv[1:]
    o = {}
    keys = {"--kind": "evidence_kind", "--record-id": "record_id",
            "--weight": "weight", "--observed-at": "observed_at"}
    i = 0
    while i < len(rest):
        if rest[i] in keys and i + 1 < len(rest):
            o[keys[rest[i]]] = rest[i + 1]; i += 2
        else:
            _err("hypothesis-evidence-add: bad arg near %s" % rest[i])
    kind = o.get("evidence_kind")
    if kind not in ("behavior", "verbal_affirm", "verbal_deny"):
        _err("hypothesis-evidence-add: --kind must be behavior|verbal_affirm|verbal_deny")
    weight = (_num(o["weight"]) if o.get("weight") is not None
              else _EVIDENCE_DEFAULT_WEIGHT[kind])
    conn = get_conn()
    try:
        if conn.execute("SELECT 1 FROM hypothesis WHERE id=?;", (hid,)).fetchone() is None:
            _err("hypothesis 없음: %s" % hid)
        observed = o.get("observed_at") or _utc_now_str()
        conn.execute(
            "INSERT INTO hypothesis_evidence (ulid, hypothesis_id, record_id, "
            "evidence_kind, weight, observed_at) VALUES (?,?,?,?,?,?);",
            (new_ulid(), hid,
             int(o["record_id"]) if o.get("record_id") else None,
             kind, weight, observed))
        conn.commit()
        conf = hypothesis_confidence_recompute(conn, hid)
        row = conn.execute(
            "SELECT stance FROM hypothesis WHERE id=?;", (hid,)).fetchone()
        print("%s\tkind=%s\tweight=%s\tconf=%.3f\tstance=%s"
              % (hid, kind, weight, conf, row[0]))
    finally:
        conn.close()


