# -- record-always-on: the ONE management-eligibility check ------------------
# Record always, manage only when eligible (the maintainer worklog
# 2026-10-13-kit-modules-record-always-on). Every kit module RECORDS what the
# owner says, shows or does, whatever its switches say. What waits is the
# module's MANAGEMENT lens: goals, diagnosis, sweeps, coaching, automations,
# target offers, setup buttons, enrichment and label asks. This section is
# the ONE check that says whether a module's management may speak
# (_manage_on / manage_eligible), plus the readback a module's setup opens
# with. Lives in kit_life.py, not a side module: meal-add / why-add /
# log-metric / appt-origin call it and must run wherever kit_life.py runs.
#
# VERBS
#   manage-state [<module> ...] [--json]
#         MANAGE<TAB>module<TAB>on|off<TAB>reason   one line per module
#         reason: consent | declined | bundle-off | default | configured:<probe>
#                 | not-onboarded
#   manage-set <module> [<module> ...] on|off [--json]
#         the owner's explicit management choice (starting a module's setup,
#         declining it). Shared across agents: config key manage.<module>.
#   capture-readback <module> [--limit N] [--json]
#         READBACK<TAB>module<TAB>n, then ROW<TAB>kind<TAB>date<TAB>text<TAB>source
#         what is already recorded for that module, newest first. A setup shows
#         these rows first and never asks for them again.
#
# Module names: the manifest token (module_ledger) or its short form (ledger).
#
# DECISION ORDER (eligible)
#   1. config manage.<module> = on|off (the owner's explicit choice) wins.
#   2. bundle compat: a BUNDLE_<SKILL> key of the module explicitly 'off' (legacy
#      alias keys resolved first) and none 'on' -> off. 'on' alone is NOT
#      consent: the first-install walkthrough switched every skill on.
#      Blank never counts.
#   3. default_on modules (schedule; contracts) -> on.
#   4. evidence of configured management (completed onboarding, a stored
#      target, an open goal, a scheduled brief ...) -> on.
#   5. otherwise off. Recording never reads this.

MANAGE_SHORT_PREFIX = 'module_'

# module, default ('on' | 'gated'), evidence probe, bundle rows whose
# BUNDLE_<ID> key is a management compat input for the module.
MANAGE_MODULES = (
    ('module_schedule', 'on', None, ('schedule-log', 'day-card')),
    # Contracts and device warranties: on by default, no onboarding.
    ('module_contracts', 'on', None, ()),
    ('module_ledger', 'gated', 'ledger_onboarded',
     ('ledger-log', 'ledger-session', 'ledger-setup')),
    ('module_meal', 'gated', 'meal_targets', ('meal-log',)),
    ('module_workout', 'gated', None, ('workout-log',)),
    ('module_health', 'gated', 'health_goal', ('health-log',)),
    ('module_goal', 'gated', 'open_goal', ('goal-session',)),
    ('module_routine', 'gated', 'routine_defs', ('routine-manage',)),
    ('module_brief', 'gated', 'brief_routines',
     ('brief-setup', 'morning-brief', 'daily-retro', 'weekly-review')),
    ('module_episode', 'gated', 'episode_configured', ()),
    ('module_person', 'gated', None, ('person-manage', 'person-session')),
    ('module_place', 'gated', None, ('place-manage',)),
    ('module_shopping', 'gated', 'shop_hunts',
     ('shopping-log', 'shopping-session')),
    # dining v1 (2026-10-15): no tables yet (taste store waits for the
    # Why-net seam), so no evidence probe; the skill fires on a food ask.
    ('module_dining', 'gated', None, ('dining-session',)),
    ('module_outing', 'gated', None, ('outing-session',)),
    ('module_admin', 'gated', None, ()),
    ('module_work', 'gated', None, ()),
    ('module_transport', 'gated', None, ()),
    ('module_invest', 'gated', None, ()),
    ('module_business', 'gated', None, ()),
    ('module_core', 'gated', 'open_goal', ('core-setup',)),
)
_MANAGE_BY = {m[0]: m for m in MANAGE_MODULES}

# Retired skill ids -> live ids (service/kit_life/skill-aliases.tsv, embedded:
# the engine runs on instances and fixtures without service/). Held equal to
# the TSV by tests/test_record_always_on.py.
MANAGE_LEGACY_ALIASES = (
    ('meal-capture', 'meal-log'),
    ('relationship', 'person-manage'),
    ('relationship-care', 'person-session'),
    ('goal-setting', 'goal-session'),
    ('dogany-routine', 'routine-manage'),
    ('inbody-capture', 'health-log'),
    ('place-setup', 'place-manage'),
    ('route-find', 'place-view'),
    ('entity-flow', 'ledger-view'),
    ('retro-reflection', 'brief-session'),
    ('life-onboarding', 'core-setup'),
    ('life-setup', 'brief-setup'),
    ('ledger-import', 'ledger-log'),
)

MANAGE_CONF_NAMES = ('kit_life.conf', 'lifekit.conf')
MANAGE_CONSENT_KEY = 'manage.%s'


class ManageUsage(Exception):
    pass


def manage_module_token(name):
    n = str(name or '').strip().lower()
    if not n.startswith(MANAGE_SHORT_PREFIX):
        n = MANAGE_SHORT_PREFIX + n
    if n not in _MANAGE_BY:
        raise ManageUsage('unknown module %r (%s)' % (
            name, ' '.join(m[0][len(MANAGE_SHORT_PREFIX):] for m in MANAGE_MODULES)))
    return n


def _manage_bundle_key(skill):
    return 'BUNDLE_' + skill.replace('-', '_').upper()


def _manage_read_conf(root):
    vals = {}
    for nm in MANAGE_CONF_NAMES:
        p = os.path.join(root, 'config', nm)
        try:
            with open(p, encoding='utf-8') as fh:
                for line in fh:
                    line = line.strip()
                    if not line or line.startswith('#') or '=' not in line:
                        continue
                    k, _s, v = line.partition('=')
                    v = v.strip()
                    if len(v) >= 2 and v[0] == v[-1] and v[0] in '"\'':
                        v = v[1:-1]
                    vals.setdefault(k.strip(), v.strip().lower())
        except OSError:
            continue
    return vals


def manage_bundle_values(conf, skills):
    """{skill: 'on'|'off'|''} with legacy keys resolved first: a blank live
    key takes its retired alias's value."""
    old_of = {}
    for old, new in MANAGE_LEGACY_ALIASES:
        old_of.setdefault(new, []).append(old)
    out = {}
    for s in skills:
        v = conf.get(_manage_bundle_key(s), '')
        if not v:
            for old in old_of.get(s, ()):
                if conf.get(_manage_bundle_key(old)):
                    v = conf[_manage_bundle_key(old)]
                    break
        out[s] = v if v in ('on', 'off') else ''
    return out


# -- evidence probes: configured management that already exists -------------

def _manage_q1(conn, sql, args=()):
    try:
        return conn.execute(sql, args).fetchone()
    except Exception:            # a table this DB predates = no evidence
        return None


def _manage_probe(conn, root, conf, name):
    if name == 'ledger_onboarded':
        p = os.path.join(root, 'files', 'ledger', 'onboarding.json')
        try:
            with open(p, encoding='utf-8') as fh:
                return bool((json.load(fh) or {}).get('completed_at'))
        except (OSError, ValueError, AttributeError):
            return False
    if name == 'meal_targets':
        try:
            return bool(meal_targets_set(conn))
        except Exception:
            return False
    if name == 'open_goal':
        return (_manage_q1(conn, "SELECT 1 FROM ledger_goal WHERE status IN "
                                 "('active','proposed') LIMIT 1") is not None
                or _manage_q1(conn, 'SELECT 1 FROM goal WHERE closed_at IS '
                                    'NULL LIMIT 1') is not None)
    if name == 'health_goal':
        # not metric_freshness: a capture declares fixed-class cadences
        # itself, and a capture never switches management on
        return (_manage_q1(conn, "SELECT 1 FROM ledger_goal WHERE status IN "
                                 "('active','proposed') AND domain='health' "
                                 "LIMIT 1") is not None
                or _manage_q1(conn, "SELECT 1 FROM goal WHERE closed_at IS "
                                    "NULL AND domain='health' LIMIT 1")
                is not None)
    if name == 'routine_defs':
        return _manage_q1(conn, "SELECT 1 FROM routine_def WHERE status='active' "
                         "LIMIT 1") is not None
    if name == 'brief_routines':
        return any(conf.get(_manage_bundle_key(r)) == 'on' for r in
                   ('morning-brief', 'daily-retro', 'weekly-review'))
    if name == 'episode_configured':
        # episode-setup writes episode.auto_cluster into config/kit_life.conf
        if conf.get('episode.auto_cluster') == 'on':
            return True
        row = _manage_q1(conn, "SELECT value FROM config WHERE "
                        "key='episode.auto_cluster'")
        return bool(row) and str(row[0]).strip().lower() == 'on'
    if name == 'shop_hunts':
        return _manage_q1(conn, 'SELECT 1 FROM shop_hunt LIMIT 1') is not None
    return False


def _manage_root():
    return _agent_root()


def manage_state(conn, module, root=None, conf=None):
    """(on: bool, reason) for one module token."""
    module = manage_module_token(module)
    _m, default, probe, skills = _MANAGE_BY[module]
    root = root or _manage_root()
    conf = _manage_read_conf(root) if conf is None else conf
    row = _manage_q1(conn, 'SELECT value FROM config WHERE key=?',
              (MANAGE_CONSENT_KEY % module,))
    choice = str(row[0]).strip().lower() if row else ''
    if choice == 'on':
        return True, 'consent'
    if choice == 'off':
        return False, 'declined'
    vals = manage_bundle_values(conf, skills).values()
    if 'off' in vals and 'on' not in vals:
        return False, 'bundle-off'
    if default == 'on':
        return True, 'default'
    if probe and _manage_probe(conn, root, conf, probe):
        return True, 'configured:' + probe
    return False, 'not-onboarded'


def manage_eligible(conn, module):
    """True when the module's management may speak. Never fails open: an
    unreadable state is 'off' for gated modules."""
    try:
        return manage_state(conn, module)[0]
    except Exception:
        row = _MANAGE_BY.get(module) or _MANAGE_BY.get(MANAGE_SHORT_PREFIX + str(module))
        return bool(row) and row[1] == 'on'


def manage_set_choice(conn, module, value):
    module = manage_module_token(module)
    if value not in ('on', 'off'):
        raise ManageUsage('manage-set <module> ... on|off')
    conn.execute("INSERT INTO config (key, value) VALUES (?, ?) ON "
                 "CONFLICT(key) DO UPDATE SET value=excluded.value, "
                 "updated_at=datetime('now','localtime');",
                 (MANAGE_CONSENT_KEY % module, value))
    return module


# -- readback: what is already recorded --------------------------------------

def _manage_rows(conn, sql, args=()):
    try:
        return conn.execute(sql, args).fetchall()
    except Exception:
        return []


def _manage_won(n):
    try:
        return format(int(n), ',')
    except (TypeError, ValueError):
        return str(n)


def manage_readback(conn, module, limit=10):
    """[{kind, date, text, source}] newest first, per module."""
    module = manage_module_token(module)
    out = []

    def add(kind, date, text, source=None):
        out.append({'kind': kind, 'date': (str(date)[:10] if date else ''),
                    'text': str(text), 'source': source or ''})

    if module in ('module_ledger', 'module_contracts'):
        for name, amt, cycle, due, direction, src, at in _manage_rows(
                conn, "SELECT name, amount, cycle, next_due, direction, "
                "source, created_at FROM fixed_cost WHERE COALESCE(state, "
                "'active') <> 'stopped' ORDER BY created_at DESC, id DESC"):
            add('fixed_cost', at, '%s %s %s%s' % (
                name, _manage_won(amt), cycle or '-',
                (' next %s' % due) if due else ''),
                src if direction != 'income' else 'income')
        if module == 'module_ledger':
            for name, kind, at in _manage_rows(conn, "SELECT name, kind, created_at "
                                        "FROM pay_method ORDER BY id DESC"):
                add('pay_method', at, '%s (%s)' % (name, kind))
            for d, name, amt, src in _manage_rows(
                    conn, "SELECT date, name, amount, source FROM spend_entry "
                    "WHERE kind='expense' ORDER BY date DESC, id DESC LIMIT ?",
                    (limit,)):
                add('spend', d, '%s %s' % (name, _manage_won(amt)), src)
    elif module == 'module_meal':
        for d, slot, name in _manage_rows(
                conn, "SELECT date, meal, name FROM " + MEALS_V32 +
                " ORDER BY date DESC, id DESC LIMIT ?", (limit,)):
            add('meal', d, '%s %s' % (meal_slots.label(slot), name), 'meal-record')
    elif module == 'module_workout':
        for d, mins, kcal, note in _manage_rows(
                conn, "SELECT date, minutes, kcal, note FROM workouts "
                "ORDER BY date DESC, id DESC LIMIT ?", (limit,)):
            add('workout', d, '%s min%s%s' % (
                _n(mins) if mins is not None else '-',
                (' %s kcal' % _n(kcal)) if kcal is not None else '',
                (' ' + note) if note else ''))
    elif module == 'module_health':
        for d, metric, val, note in _manage_rows(
                conn, "SELECT m.date, m.metric, m.value, m.note FROM "
                "metric_log m WHERE m.id = (SELECT id FROM metric_log x WHERE "
                "x.metric=m.metric ORDER BY x.date DESC, x.id DESC LIMIT 1) "
                "ORDER BY m.date DESC, m.metric LIMIT ?", (limit,)):
            add('metric', d, '%s %s' % (metric, _fmeas(val) if isinstance(
                val, (int, float)) else val), note)
        for key, val, src, at in _manage_rows(
                conn, "SELECT key, value, source, recorded_at FROM "
                "ledger_constraint WHERE status='active' AND class='safety' "
                "ORDER BY recorded_at DESC"):
            add('constraint', at, '%s: %s' % (key, val), src)
    elif module in ('module_goal', 'module_core'):
        for text, at in _manage_rows(conn, "SELECT text, created_at FROM life_why "
                              "WHERE status='active' ORDER BY created_at DESC"):
            add('why', at, text, 'owner')
        if module == 'module_core':
            for key in ('height_cm', 'weight_kg'):
                row = _manage_q1(conn, 'SELECT value, updated_at FROM config '
                                'WHERE key=?', (key,))
                if row and row[0] not in (None, ''):
                    add('profile', row[1], '%s %s' % (key, row[0]), 'config')
            for dom, days, a, b, src, at in _manage_rows(
                    conn, "SELECT domain, weekdays, start_hm, end_hm, source, "
                    "recorded_at FROM availability_window WHERE "
                    "status='active' ORDER BY recorded_at DESC"):
                add('availability', at, '%s %s %s-%s' % (
                    dom, days, a or '', b or ''), src)
            for kind, name, src, at in _manage_rows(
                    conn, "SELECT kind, name, source, recorded_at FROM "
                    "ledger_resource WHERE status='active' "
                    "ORDER BY recorded_at DESC"):
                add('resource', at, '%s: %s' % (kind, name), src)
    elif module == 'module_routine':
        for item, note, detail, src, at in _manage_rows(
                conn, "SELECT item, note, detail, source, recorded_at FROM "
                "ledger_preference WHERE topic='habit' AND status='active' "
                "ORDER BY recorded_at DESC"):
            add('habit', at, item + ((' ' + detail) if detail else ''), src)
        for title, cadence, at in _manage_rows(
                conn, "SELECT title, cadence, created_at FROM routine_def "
                "WHERE status='active' ORDER BY created_at DESC"):
            add('routine', at, '%s (%s)' % (title, cadence), 'routine')
    elif module == 'module_person':
        for name, rel, bday, job, at in _manage_rows(
                conn, "SELECT name, relation, birthday, job, created_at FROM "
                "persons ORDER BY created_at DESC, id DESC LIMIT ?", (limit,)):
            bits = [b for b in (rel, _person_value_label("birthday", bday)
                                if bday else None, job) if b]
            add('person', at, name + ((' (%s)' % ', '.join(bits))
                                      if bits else ''))
    elif module == 'module_place':
        for name, addr, at in _manage_rows(
                conn, "SELECT COALESCE(display_name, name), address, "
                "created_at FROM place WHERE COALESCE(status,'active') "
                "<> 'gone' ORDER BY created_at DESC, id DESC LIMIT ?",
                (limit,)):
            add('place', at, name + ((' ' + addr) if addr else ''))
    elif module == 'module_shopping':
        for d, name, store in _manage_rows(
                conn, "SELECT o.bought_on, i.name, o.store FROM owned_item o "
                "JOIN shop_item i ON i.id=o.item_id ORDER BY o.bought_on DESC, "
                "o.id DESC LIMIT ?", (limit,)):
            add('owned', d, name + ((' @' + store) if store else ''))
        for axis, val, pol, at in _manage_rows(
                conn, "SELECT axis, value, polarity, recorded_at FROM "
                "taste_mark WHERE status='active' ORDER BY recorded_at DESC"):
            add('taste', at, '%s %s: %s' % (pol, axis, val))
        for item, at in _manage_rows(conn, "SELECT item, recorded_at FROM "
                              "ledger_preference WHERE topic='want' AND "
                              "status='active' ORDER BY recorded_at DESC"):
            add('want', at, item)
    elif module == 'module_episode':
        for title, reaction, at in _manage_rows(
                conn, "SELECT title, reaction, created_at FROM event "
                "ORDER BY created_at DESC, id DESC LIMIT ?", (limit,)):
            add('experience', at, title + ((' -- ' + reaction)
                                           if reaction else ''))
    elif module in ('module_brief', 'module_schedule'):
        for title, kind, start, outcome in _manage_rows(
                conn, "SELECT title, kind, start_at, settled_outcome FROM "
                "timeblock WHERE kind IN ('task','appointment','presence') "
                "AND COALESCE(block_class,'') <> 'travel' "
                "ORDER BY start_at DESC, id DESC LIMIT ?", (limit,)):
            add(kind, start, title + ((' [%s]' % outcome) if outcome else ''))
    return out


# -- CLI ---------------------------------------------------------------------

def manage_cli(verb, argv):
    argv, as_json = _pop_flag(argv, '--json')
    conn = get_conn()
    try:
        try:
            _manage_run(conn, verb, argv, as_json)
            if conn.in_transaction:
                conn.commit()
        except ManageUsage as e:
            if conn.in_transaction:
                conn.rollback()
            _err('%s: %s' % (verb, e), 2)
    finally:
        conn.close()


def _manage_run(conn, verb, argv, as_json):
    if verb == 'manage-state':
        mods = [manage_module_token(a) for a in argv] or [m[0] for m in MANAGE_MODULES]
        res = []
        root = _manage_root()
        conf = _manage_read_conf(root)
        for m in mods:
            on, why = manage_state(conn, m, root=root, conf=conf)
            res.append({'module': m, 'state': 'on' if on else 'off',
                        'reason': why})
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
        else:
            for r in res:
                print('MANAGE\t%s\t%s\t%s' % (r['module'], r['state'],
                                             r['reason']))
        return
    if verb == 'manage-set':
        if len(argv) < 2 or argv[-1] not in ('on', 'off'):
            raise ManageUsage('manage-set <module> [<module> ...] on|off')
        value = argv[-1]
        mods = [manage_set_choice(conn, a, value) for a in argv[:-1]]
        conn.commit()
        res = [{'module': m, 'state': value,
                'reason': 'consent' if value == 'on' else 'declined'}
               for m in mods]
        if as_json:
            print(json.dumps(res, ensure_ascii=False))
        else:
            for r in res:
                print('MANAGE\t%s\t%s\t%s' % (r['module'], r['state'],
                                             r['reason']))
        return
    if verb == 'capture-readback':
        argv, lim = _pop_opt(argv, '--limit')
        if len(argv) != 1:
            raise ManageUsage('capture-readback <module> [--limit N] [--json]')
        try:
            limit = int(lim) if lim is not None else 10
        except ValueError:
            raise ManageUsage('--limit N')
        m = manage_module_token(argv[0])
        rows = manage_readback(conn, m, limit=limit)
        if as_json:
            print(json.dumps({'module': m, 'rows': rows}, ensure_ascii=False))
        else:
            print('READBACK\t%s\t%d' % (m, len(rows)))
            for r in rows:
                print('ROW\t%s\t%s\t%s\t%s' % (
                    r['kind'], r['date'] or '-',
                    r['text'].replace('\t', ' ').replace('\n', ' '),
                    r['source'] or '-'))
        return
    raise ManageUsage('unknown verb ' + verb)


def _manage_on(conn, module):
    """True when <module>'s management lens may speak (offers, setup buttons,
    coaching, enrichment asks). Recording never calls this."""
    return manage_eligible(conn, module)


def _manage_cli(verb):
    def run(argv):
        return manage_cli(verb, argv)
    run.__name__ = 'cli_' + verb.replace('-', '_')
    return run


